INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04003','fiesta','Feria de Todos los Santos y Romería de la Virgen del Saliente','Feria de ganado histórica, festival de rock (Albox Rock) y romería religiosa. Se celebra en Noviembre (Feria) y Septiembre (Romería). La Romería está declarada de Interés Turístico de Andalucía; su feria es una de las más multitudinarias e históricas del norte de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90406','fiesta','Fiestas patronales de Santa Rosa de Lima y Fiesta del Aceite de Oliva','Patronal, tradicional y gastronómica (puesta en valor del aceite de oliva virgen extra de la Alpujarra). Se celebra en Agosto (Patronales) y Noviembre (Aceite). Fiesta local de gran valor etnográfico y gastronómico a nivel comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90407','fiesta','Fiestas en honor a la Virgen del Rosario y Fiesta del Jameo','Patronal, verbenas de verano y encuentros culturales en sus pedanías (Hijate). Se celebra en Agosto. Celebración de carácter marcadamente vecinal y de retorno de emigrantes en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90408','fiesta','Fiestas de San Roque','Patronal, procesiones tradicionales y comidas populares en la plaza del pueblo. Se celebra en Agosto. Municipio de muy baja población; sus fiestas mantienen viva la tradición oral y vecinal de la Sierra de los Filabres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90409','fiesta','Fiestas en honor a la Virgen de la Visitación y San Juan Bautista','Religiosa, quema de "juas" (muñecos de trapo) y verbenas populares. Se celebra en Junio y Julio. Tradición local muy viva con actividades culturales orientadas al Valle del Andarax.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90410','fiesta','Fiestas en honor a San Nicolás de Bari y la Virgen de la Purísima Concepción','Patronal, castillos de fuegos artificiales y festivales de música de bandas. Se celebra en Diciembre. Destaca por su arraigo invernal y por congregar a gran parte de la comarca del Poniente y área metropolitana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90411','fiesta','Fiestas de San Sebastián','Patronal, reparto de roscos benditos y procesión tradicional. Se celebra en Enero. Celebración de invierno pequeña pero muy singular por el rito de los roscos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04004','fiesta','Feria de Almería en honor a la Virgen del Mar y Semana Santa de Almería','Feria de día y de noche, corridas de toros, conciertos, gastronomía (tapas) y desfiles procesionales. Se celebra en Agosto (Feria) y Marzo/Abril (Semana Santa). La Semana Santa está declarada de Interés Turístico Nacional. La Feria de Agosto cuenta con gran proyección andaluza, destacando su ambiente en el centro histórico durante el día). ¿Prefieres que continuemos con el siguiente bloque de la letra A de Almería (Almócita, Alsodux, Antas, Arboleas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90734','fiesta','La Noche de los Candiles y Fiestas de San Blas','Cultural (iluminación exclusiva con fuego), etnográfica y patronal. Se celebra en Mayo (Candiles) y Febrero (San Blas). La Noche de los Candiles atrae gran turismo interior por su singularidad ecológica y mágica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90412','fiesta','Fiestas en honor a la Virgen de la Asunción','Patronal y verbenas de verano. Se celebra en Agosto. Celebración vecinal de retorno estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90413','fiesta','Fiestas Patronales de la Virgen de la Cabeza','Patronal, desfile de carrozas y verbenas. Se celebra en Septiembre. Gran arraigo en la comarca del Levante Almeriense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90414','fiesta','Fiestas de Santa Ana y Feria de la Virgen del Pilar','Patronal, conciertos y convivencia de la comunidad británica local. Se celebra en Julio y Octubre. Destaca por su fuerte integración multicultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90415','fiesta','Fiestas de la Virgen del Rosario','Patronal y actividades culturales de verano. Se celebra en Agosto. Tradición puramente local del Valle del Almanzora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90416','fiesta','Fiestas del Santo Cristo del Bosque','Romería religiosa de gran devoción y procesión de montaña. Se celebra en Septiembre. Atrae a miles de peregrinos de toda la provincia de Almería y Granada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04904','fiesta','Fiestas de Santiago Apóstol','Fiestas patronales de costa, castillos de fuegos artificiales y ferias. Se celebra en Julio. Ambiente costero veraniego muy concurrido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90417','fiesta','Fiestas de Moros y Cristianos en honor a San Francisco de Asís','Histórica, teatral y patronal. Se celebra en Septiembre. Representación de moros y cristianos de gran valor histórico en la Alpujarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90418','fiesta','Fiestas de la Virgen del Rosario','Patronal, pasacalles y comidas populares. Se celebra en Julio. Ámbito vecinal y familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04005','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Cabeza','Histórica, desfiles y procesiones. Se celebra en Septiembre. Destacan los trajes y las relaciones teatrales entre bandos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90735','fiesta','Fiestas de San Roque y Fiesta de la Exaltación de la Santa Cruz','Patronal y religiosa tradicional. Se celebra en Agosto y Septiembre. Pequeña celebración de alta montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90419','fiesta','Fiestas en honor a la Virgen de la Cabeza y Cata del Vino','Patronal, feria de atracciones y evento gastronómico local. Se celebra en Septiembre. Muy concurrida por su cercanía a la capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90420','fiesta','Fiestas de San Juan de la Cruz','Patronal de invierno. Se celebra en Noviembre. El municipio menos poblado de la provincia; valor puramente etnográfico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90421','fiesta','Romería de la Virgen de la Cabeza en el Monte Monteagud','Romería religiosa de montaña y verbenas. Se celebra en Septiembre. Santuario de enorme devoción para toda la Sierra de los Filabres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90422','fiesta','Fiestas de San Juan Bautista','Patronal, tradicionales hogueras y baños de medianoche. Se celebra en Junio. Ámbito local del curso medio del Andarax.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90423','fiesta','Feria de Berja y Fiestas de la Virgen de Gádor','Feria mayor de verano, festivales flamencos, romería y procesión solemne. Se celebra en Agosto (Feria) y Septiembre (Patrona). La bajada de la Virgen de Gádor es de gran relevancia religiosa en el Poniente Almeriense; feria muy potente comercialmente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90736','fiesta','Fiestas de la Santa Cruz del Voto','Religiosa e histórica (procesión de la cruz milagrosa), feria local. Se celebra en Abril. Celebración centenaria de gran fervor en toda la Alpujarra baja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04031','fiesta','Fiestas de San Antón y San Ildefonso (Los Carreticos)','Tradicional con fuego (lanzamiento de carretillas de pólvora) y patronal. Se celebra en Enero. Espectacular fiesta del fuego que atrae a muchos aficionados a la pirotecnia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04006','fiesta','Fiestas de Moros y Cristianos en honor a San Antonio de Padua','Histórica, desembarco marítimo simulado en la playa y desfiles. Se celebra en Junio. De las recreaciones de Moros y Cristianos más espectaculares de la costa mediterránea, muy turística.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04033','fiesta','Fiestas de la Virgen del Rosario','Patronal y verbenas populares. Se celebra en Agosto. Entorno rural de montaña, ambiente familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04036','fiesta','Fiestas en honor a la Virgen de Fátima','Patronal, procesiones y verbenas veraniegas. Se celebra en Agosto. Foco vecinal y emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04037','fiesta','Fiestas de San Isidro y Fiestas del Verano (Feria de Chirivel)','Tradición agrícola, desfiles de carrozas y conciertos al aire libre. Se celebra en Mayo y Agosto. Referente festivo estival en la comarca de Los Vélez.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04034','fiesta','Fiestas en honor a San Sebastián y la Virgen de la Piedad','Patronal y procesión por calles estrechas. Se celebra en Agosto. Ámbito estrictamente local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04035','fiesta','Feria de San Diego de Alcalá y Semana Santa','Feria mayor de invierno y desfiles procesionales barrocos de gran valor. Se celebra en Noviembre (Feria) y Marzo/Abril (Semana Santa). Su Semana Santa cuenta con pasos vivientes de gran belleza e imaginería histórica notable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04038','fiesta','Fiestas del Santísimo Cristo de la Luz','Religiosa, pirotécnica (quema masiva de miles de cohetes durante la procesión). Se celebra en Septiembre. Declarada de Interés Turístico Nacional de Andalucía. Es una de las mayores expresiones de fe y uso de pólvora del sur de España; atrae a más de 300.000 personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04008','fiesta','Fiestas de San Isidro Labrador y Festival de Teatro de El Ejido','Feria mayor con carrozas y macro-conciertos; festival de artes escénicas. Se celebra en Junio (San Isidro) y Mayo/Junio (Teatro). El Festival de Teatro es Fiesta de Interés Turístico Nacional por su vanguardia y escala internacional. Las fiestas de San Isidro son masivas en el Poniente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04041','fiesta','Fiestas patronales en honor a la Virgen del Rosario','Patronal de montaña con vistas al mar, verbenas tradicionales. Se celebra en Octubre. Tranquila celebración local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04043','fiesta','Fiestas en honor a San Roque','Patronal, quema de castillos de fuegos artificiales y verbenas de plaza. Se celebra en Agosto. Atrae a muchos visitantes de los núcleos costeros cercanos debido al frescor de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04044','fiesta','Fiestas de San Esteban y Fiesta del Oro Blanco (Mármol)','Patronal y ferias de muestras culturales asociadas a la industria del mármol. Se celebra en Agosto. Fuerte dinamismo juvenil y musical en la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04009','fiesta','Fiestas de San Antón y San Sebastián','Patronal, tradicionales hogueras urbanas gigantes y procesiones con disparos de fogueo. Se celebra en Enero. Declarada de Interés Turístico de Andalucía por su arraigo e historia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04010','fiesta','Fiestas de San Sebastián y la Virgen de las Angustias / Chisco de San Antón','Patronal, gastronómica (reparto de arroz y migas) e históricas hogueras. Se celebra en Agosto (Patronales) y Enero (Chisco). Referente de las tradiciones folclóricas del corazón de la Alpujarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04047','fiesta','Fiestas de la Virgen del Rosario y Día de la Naranja','*. Patronal y Feria Gastronómica (reparto masivo de zumo y postres de naranja). *. Se celebra en Octubre (Patronal) y Febrero (Naranja). *. El Día de la Naranja atrae a miles de visitantes de la provincia para consumir producto local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04011','fiesta','Feria de la Virgen del Carmen y Festival Gastronómico de la Gamba Roja de Garrucha','Marinera (procesión marítima), turística y gastronómica de alto nivel. Se celebra en Julio (Carmen) y Octubre (Gamba). La gamba roja es un reclamo culinario gourmet nacional; la procesión marinera es espectacular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04012','fiesta','Fiestas de Moros y Cristianos en honor a San Sebastián','Recreación histórica y desfiles con trajes tradicionales de gran valor. Se celebra en Enero. Conserva la estructura clásica de "relaciones" escritas antiguas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04051','fiesta','Fiestas de la Virgen del Carmen y San Blas','Patronal, procesiones y bailes tradicionales en el Valle del Andarax. Se celebra en Julio y Febrero. Identidad local muy marcada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04052','fiesta','Fiestas de San José y certámenes de música urbana','Feria urbana, actividades infantiles y macroconciertos. Se celebra en Mayo. Municipio de gran crecimiento periférico, fiestas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04013','fiesta','Feria de Octubre y Semana Santa de HuércalOvera','Macro-feria comercial/atracciones y desfiles procesionales históricos de alto valor artístico. Se celebra en Octubre (Feria) y Marzo/Abril (Semana Santa). Su Semana Santa es Fiesta de Interés Turístico Nacional, famosa por la espectacularidad de sus desfiles y sus ricos bordados históricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04054','fiesta','Fiestas de San Roque','Patronal, verbenas nocturnas y juegos tradicionales. Se celebra en Agosto. Ambiente puramente alpujarreño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04055','fiesta','Fiestas de San Sebastián y Virgen de los Dolores','Patronal, hogueras de San Antón y pasacalles de bandas. Se celebra en Enero y Agosto. Pequeña pero muy participativa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04056','fiesta','Fiestas en honor a San Ramón Nonato','Patronal, comida popular en la plaza mayor del pueblo. Se celebra en Agosto. Foco en el turismo rural y la vecindad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04901','fiesta','Fiestas patronales repartidas en sus núcleos (Escúllar, Doña María, Ocaña)','Fiestas de la Virgen del Rosario. Rural, patronal y cultural. Se celebra en Agosto. Une la tradición de tres pequeños núcleos históricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04014','fiesta','Feria de la Alpujarra y Fiestas de la Virgen de la Salud / Fiesta del Vino','Feria cultural, patronal y gastronómica dedicada a los vinos de la tierra. Se celebra en Septiembre (Patrona) y Abril/Mayo (Feria del Vino). Capital vitivinícola de la Alpujarra almeriense, sus ferias agroalimentarias atraen mucho turismo gastronómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04058','fiesta','Fiestas de San Blas y recreación histórica de la "Guerra a Francia"','Patronal e Histórico-Satírica (celebración de cuando el pueblo declaró la guerra a Francia en el siglo XIX). Se celebra en Septiembre. Fiesta única y muy curiosa por su base histórica, sale en medios nacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04048','fiesta','Fiesta de la Virgen del Carmen y Auto Sacramental de los Reyes Magos','Patronal veraniega y representación teatral navideña en la calle. Se celebra en Julio (Carmen) y Enero (Reyes). El Auto de los Reyes Magos es de los más antiguos y seguidos de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04061','fiesta','Fiestas de San Sebastián y Virgen del Rosario','Patronal y baños tradicionales en las aguas termales de Cela. Se celebra en Enero y Agosto. La balsa de Cela genera un foco festivo veraniego muy potente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04015','fiesta','Fiestas de la Virgen del Rosario y Recreación Histórica "Canteros y Caciques"','Patronal y Teatral/Industrial (recreación del pleito por las canteras de mármol, ambientada en el siglo XX). Se celebra en Octubre (Patrona) y Mayo (Canteros). "Canteros y Caciques" se ha convertido en un gran evento turístico-cultural regional con trajes de época y gastronomía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04063','fiesta','Fiestas de la Virgen de la Cabeza y Fiesta del Jamón de María','Romería de montaña y Feria gastronómica dedicada a sus curados de alta montaña. Se celebra en Agosto (Patronal) y Octubre (Jamón). Muy concurrida por la calidad de sus productos cárnicos y el entorno natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04016','fiesta','Fiestas de Moros y Cristianos de Mojácar y Fiestas de San Agustín','Histórica de gran espectacularidad, desfiles masivos en la playa y calles del pueblo blanco, trabucadas. Se celebra en Junio (Moros y Cristianos) y Agosto (San Agustín). La fiesta de Moros y Cristianos es un referente absoluto en el sur de España por la belleza plástica del entorno y la calidad del vestuario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04065','fiesta','Fiestas de San Miguel Arcángel','Patronal, verbenas de plaza y degustaciones de repostería local. Se celebra en Septiembre. Carácter íntimo y rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04017','fiesta','Feria de Níjar y Fiestas de las pedanías costeras (San José, Las Negras)','Feria tradicional de artesanía (jarapas/ alfarería) y verbenas de playa veraniegas. Se celebra en Septiembre (Feria) y Verano (Pedanías). Combina la identidad artesanal del pueblo con el turismo masivo estival del Parque Natural de Cabo de Gata.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04018','fiesta','Fiestas de San Marcos (Fiesta de los Toros Ensogaos)','Taurino-religiosa tradicional (procesión donde toros y vacas son guiados con sogas ante el santo). Se celebra en Abril. Declarada de Interés Turístico de Andalucía por su antigüedad y carácter insólito.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04068','fiesta','Fiestas de la Virgen del Patrocinio y Relaciones de Moros y Cristianos','Patronal e histórica en un pueblo de arquitectura de pizarra. Se celebra en Noviembre. Poco poblado pero de gran belleza estética invernal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04019','fiesta','Fiestas de San Sebastián y San Ildefonso (La Fiesta de las Carretillas)','Tradición extrema del fuego (lanzamiento de miles de carretillas pirotécnicas en procesión nocturna). Se celebra en Enero. De gran renombre provincial y regional para los amantes de la pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04070','fiesta','Feria de la Virgen de las Mercedes y Fiestas de San Gregorio','Patronal, conciertos y mercado tradicional en el norte de la provincia. Se celebra en Agosto. Centro de reunión festiva para el Valle del Almanzora alto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04071','fiesta','Recreación Histórica de la Paz de las Alpujarras y Fiestas de Santa Ana','Histórica rigurosa (recreación de la paz entre Don Juan de Austria y los moriscos en 1570, con trajes del S. XVI) y patronal. Se celebra en Mayo (Recreación) y Julio (Patronal). Referente nacional en recreación histórica por su fidelidad militar y gastronómica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04072','fiesta','Fiestas de San Antonio de Padua','Patronal, verbenas al aire libre junto a sus famosas formaciones rocosas ("derrumbes"). Se celebra en Junio. Ambiente rural agradable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04020','fiesta','Fiestas de la Virgen de los Remedios y Fiesta de la Castaña','Patronal y Gastronómica de otoño (puesta en valor de los castañares alpujarreños). Se celebra en Agosto (Patrona) y Octubre/Noviembre (Castaña). La fiesta de la castaña atrae mucho excursionismo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04074','fiesta','Fiestas de San Claudio y Mercado Romano de Bayyana','Patronal y cultural-histórica (orígenes romanos e islámicos del municipio). Se celebra en Mayo. Eventos culturales vinculados a la historia arqueológica local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04021','fiesta','Fiestas Patronales en honor a San Miguel Arcángel y Día de la Vieja','Feria local con conciertos, festividad etnográfica al aire libre (Día de la Vieja con ruptura de muñecos tradicionales llenos de caramelos). Se celebra en Septiembre (San Miguel) y Marzo (Día de la Vieja). Impulsada enormemente a nivel turístico por el atractivo de su Geoda Gigante; el Día de la Vieja tiene fuerte impacto comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04022','fiesta','Juegos Moriscos de Abén Humeya y Fiestas de San Ginés','Fiesta de recreación histórica, deportiva, cultural y patronal. Se celebra en Agosto. Declarada de Interés Turístico Nacional de Andalucía. Es una fiesta única en España que recupera competiciones deportivas y tradiciones musicales de origen morisco del año 1569.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04077','fiesta','Fiestas en honor a San Agapito','Patronal, procesiones de invierno, tracas tradicionales y verbenas. Se celebra en Agosto. Tradición muy localizada en el valle medio del Andarax, orientada al reencuentro estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04078','fiesta','Fiestas en honor a la Virgen del Rosario y San Albertito','Patronal, desfiles de carrozas, ferias de mediodía y eventos culturales. Se celebra en Septiembre y Octubre. Fiestas muy populares y participativas por su cercanía e interconexión con el área de Almería capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04023','fiesta','Fiestas de Santa Ana (El Puerto) y Fiestas de la Virgen del Rosario','Fiesta mayor costera, procesión marítimoterrestre, fuegos artificiales en el mar y feria de atracciones masiva. Se celebra en Julio (Santa Ana) y Octubre (Virgen del Rosario). La procesión marítima y el lavado de cara a la Virgen en las fiestas de Santa Ana atraen a decenas de miles de turistas veraneantes. Gran despliegue de conciertos y ferias de día.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04080','fiesta','Fiestas de San Agustín','Patronal y religiosa con arraigo vecinal. Se celebra en Agosto. Municipio pequeño; las fiestas conservan una atmósfera rural e íntima de la Alpujarra Almeriense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04081','fiesta','Fiestas de la Virgen del Rosario','Fiestas tradicionales, procesión histórica y verbena nocturna. Se celebra en Octubre. Arraigo local centrado en la preservación de su patrimonio cultural y convivencia comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04082','fiesta','Fiestas de Moros y Cristianos en honor a San Divino y San Gregorio','Representación histórica y patronal. Se celebra en Agosto. Destaca por sus relaciones de Moros y Cristianos, un texto teatral medieval que los vecinos escenifican en la plaza de la iglesia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04025','fiesta','Fiesta del Jamón de Serón y Fiestas de la Virgen de los Remedios','Gastronómica (feria de embutidos y jamones de alta calidad) y patronal. Se celebra en Julio (Jamón) y Agosto (Remedios). La Feria del Jamón es una de las citas gastronómicas más famosas del sureste peninsular, atrayendo a miles de amantes de la gastronomía y profesionales del sector alimentario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04084','fiesta','Fiestas de Moros y Cristianos en honor a San Sebastián','Recreación histórica y fiesta patronal tradicional. Se celebra en Septiembre (o Enero según tradición litúrgica trasladada). Muy vistosas por la indumentaria de las tropas moras y cristianas en la Sierra de los Filabres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04085','fiesta','Fiestas en honor a San Sebastián y San Antonio Abad','Patronal de invierno, quema de carretillas (fuegos artificiales artesanales) y pasacalles. Se celebra en Enero. Fiesta peculiar por el uso tradicional de la pólvora a nivel comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04026','fiesta','Feria y Fiestas de San Roque','Feria mayor, procesión del patrón donde se lanzan miles de "roscos de pan" desde los balcones, y verbenas. Se celebra en Agosto. La tradición de arrojar roscos al paso de San Roque le da un valor etnográfico único muy fotografiado a nivel provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04087','fiesta','Fiestas en honor a San Roque y Fiesta de la Fritada de Suflí','Patronal y gastronómica (degustación masiva de su tradicional conserva artesanal de pimiento y tomate). Se celebra en Agosto. Su miniferia gastronómica de la fritada le otorga un encanto culinario muy apreciado en la comarca del Almanzora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04088','fiesta','Feria de Tabernas en honor a la Virgen de las Angustias y Almería Western Film Festival (AWFF)','Feria tradicional y festival de cine internacional temático del género Western. Se celebra en Agosto (Feria) y Octubre (Festival). El festival internacional de cine especializado en el "Spaghetti Western" le otorga relevancia mediática y cultural global a la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04089','fiesta','Fiestas de San José y Feria Medieval','Patronal, folclórica (Encuentro de Cuadrillas de Ánimas) y mercado tradicional. Se celebra en Marzo (San José) y Diciembre (Cuadrillas). Su certamen de música tradicional de ánimas es un bastión de la cultura musical folclórica andaluza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04091','fiesta','Fiestas de la Virgen del Rosario y Jornada de Recuperación de los Oficios Perdidos','Patronal y etnográfica-cultural de recreación histórica. Se celebra en Octubre (Patronal) y Noviembre (Oficios). La jornada de oficios históricos convierte al pueblo entero en un museo vivo atrayendo a numeroso turismo cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04092','fiesta','Fiestas de la Virgen del Socorro y Festividad de San Sebastián','Patronal, alfombras de serrín coloreado, verbenas populares y lanzamiento de roscos/cacahuetes. Se celebra en Septiembre (Socorro) y Enero (San Sebastián). Sus espectaculares alfombras de colores en las calles para la procesión son muy reconocidas en toda la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04028','fiesta','Feria de Turre en honor a San Francisco de Asís','Feria tradicional, carreras de cintas a caballo y bailes populares al aire libre. Se celebra en Octubre. Concurrente punto de encuentro para el Levante Almeriense, potenciado por su población internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04094','fiesta','Fiestas de San Antonio de Padua','Patronal, procesión, fuegos artificiales y verbenas. Se celebra en Junio. Celebración vecinal en las faldas de Sierra Alhamilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04095','fiesta','Fiestas en honor a la Virgen de la Cabeza','Romería al Santuario del cerro de Monteagud y feria local. Se celebra en Septiembre. La peregrinación al cerro de Monteagud es un fenómeno de devoción religiosa transversal en todo el interior provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04096','fiesta','Fiestas de San Blas','Patronal de invierno y reparto de roscos bendecidos. Se celebra en Enero. Fiesta tradicional pequeña enfocada en las costumbres serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04097','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de los Tornos','Recreación histórica y fiesta patronal mariana. Se celebra en Agosto. Tradición preservada con fervor que resalta sobre la orografía montañosa del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04098','fiesta','Fiestas de Alporchones en honor a la Virgen de la Cabeza y Festival de Música Renacentista y Barroca','Patronal e hito musical-cultural europeo de música antigua. Se celebra en Agosto (Patronal) y Julio (Festival). Su Festival de Música Antigua goza de una proyección académica e internacional excelente, atrayendo a expertos e intérpretes de todo el continente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04099','fiesta','Semana Santa de Vélez-Rubio y Feria de Verano','Tradición barroca de desfiles procesionales y feria mayor comercial/lúdica. Se celebra en Marzo/Abril (Semana Santa) y Agosto (Feria). [1] *. Su Semana Santa está declarada Fiesta de Interés Turístico Nacional de Andalucía por la riqueza de sus hermandades, imaginería y los tradicionales "Armaos".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04029','fiesta','Feria y Fiestas de San Cleofás y Fiestas de la Virgen de las Angustias','Feria mayor tradicional, corridas de toros (en su histórica plaza), desfiles de gigantes y cabezudos y ferias de día. Se celebra en Septiembre (San Cleofás) y Junio (Angustias). Una de las ferias de mayor empaque, elegancia y afluencia de público del levante andaluz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04101','fiesta','Fiestas Patronales de la Virgen de las Angustias','Patronal, eventos culturales y estrecha relación lúdica con la comunidad de la Base Militar militar de la Legión. Se celebra en Octubre. Mucha participación local y gran afluencia de visitantes de la capital provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04030','fiesta','Fiestas del Cristo de la Salud (Vícar Pueblo) y Fiestas de las Cabañuelas','Fiestas de barrio y pueblo, verbenas de gran envergadura y actividades deportivas. Se celebra en Septiembre y Julio. Fiestas muy populosas debido al gran crecimiento demográfico del "corazón del Poniente".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04103','fiesta','Fiestas de San Ramón Nonato y San Juan','Patronales, verbenas populares, y carreras de cintas. Se celebra en Agosto. Enfoque tradicional y festivo de gran ambiente vecinal con presencia de comunidad británica afincada). [1] Con esto queda completada al 100% la provincia de Almería de la A a la Z en base a los criterios reales de puntuación. Dime si pasamos al siguiente bloque del documento Word para la siguiente provincia en orden alfabético de Andalucía, que corresponde a Cádiz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16001','fiesta','Feria de Agosto y Romería de Nuestra Señora de los Santos','Feria de ganado tradicional, festividad religiosa y eventos hípicos en pleno Parque Natural de los Alcornocales. Se celebra en Agosto (Feria) y Septiembre (Romería). Destaca por su arraigo rural y la belleza paisajística de su romería.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90467','fiesta','Semana Santa y Feria del Espárrago','Religiosa y Gastronómica (puesta en valor de su producto estrella con degustaciones y mercado hortofrutícola). Se celebra en Marzo/Abril (Semana Santa) y Abril (Espárrago). Su Feria del Espárrago se ha convertido en un referente agroalimentario de la Sierra de Cádiz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90468','fiesta','Feria de la Primavera y Rally de Algar','Feria local andaluza y evento deportivo automovilístico de gran repercusión. Se celebra en Mayo (Feria) y Septiembre (Rally). El rally atrae a miles de aficionados al motor de toda Andalucía, transformando el municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16002','fiesta','Feria Real de Algeciras y Fiesta de la Inalcanzable (Carnaval Especial)','Gran feria andaluza con corridas de toros de renombre, casetas y pasacalles tradicionales. Se celebra en Junio (Feria Real) y Febrero (Carnaval). La Feria Real está declarada de Interés Turístico Nacional de Andalucía y es uno de los grandes motores festivos del Campo de Gibraltar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16003','fiesta','Recreación Histórica del 2 de Mayo y Fiestas de Santiago Apóstol','Recreación histórica y fiesta patronal. Los vecinos se visten de época para conmemorar la resistencia contra las tropas napoleónicas en 1810. Se celebra en Mayo (Recreación) y Julio (Santiago). La Recreación Histórica está declarada de Interés Turístico de Andalucía por su espectacular rigor y participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16004','fiesta','Semana Santa, Toro del Aleluya y Feria de San Miguel','Religiosa, encierro taurino tradicional y feria patronal. Se celebra en Marzo/Abril (Semana Santa y Toro) y Septiembre (Feria). Su Semana Santa y el encierro del Toro del Aleluya el Domingo de Resurrección están declarados de Interés Turístico Nacional por su espectacularidad en el casco histórico colgado del tajo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90031','fiesta','Semana Gastronómica del Atún de Almadraba y Feria del Carmen','Gastronómica de alto nivel, feria marinera y procesión marítima de la patrona. Se celebra en Mayo (Atún) y Julio (Carmen). La Semana del Atún es un hito culinario internacional que atrae a chefs y turistas de todo el mundo para degustar el "oro rojo".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11901','fiesta','Fiesta de la Independencia y Feria de Santiago','Conmemoración histórica institucional, cultural y feria tradicional de casetas. Se celebra en Marzo (Independencia) y Julio (Feria). Muy celebrada a nivel comarcal, destacando sus eventos culturales y gastronómicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90469','fiesta','Fiestas Patronales de San Blas y la Feria de Agosto','Patronal con su tradicional "Suelta del Toro de Cuerda" y fiestas de verano. Se celebra en Febrero (San Blas) y Agosto (Feria). El toro de cuerda de San Blas conserva un valor etnográfico muy antiguo en la Sierra de Grazalema.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90470','fiesta','Carnaval de Bornos y Feria de San Laureano','Carnaval tradicional con "chuzos" (máscaras y disfraces típicos) y feria de septiembre. Se celebra en Febrero (Carnaval) y Septiembre (Feria). Su Carnaval está declarado de Interés Turístico de Andalucía debido a su singularidad, coplas y personajes propios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16009','fiesta','Carnaval de Cádiz y Gran Regata de Veleros','Carnaval masivo (chirigotas, comparsas, coros), fiesta de interés internacional, y eventos náuticos. Se celebra en Febrero/Marzo. Declarado Fiesta de Interés Turístico Internacional. Uno de los carnavales más famosos del mundo, referente cultural, musical y satírico inigualable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16006','fiesta','Feria de la Primavera y Romería del Santísimo Cristo de la Almoraima','Feria andaluza de tipología rural y peregrinación religiosa en un entorno medieval fortificado. Se celebra en Mayo. Su ubicación y el encanto del castillo le dan a la romería un toque estético muy singular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16007','fiesta','Feria de San Antonio y Fiesta del Vino y la Vendimia','Feria mayor de trajes de flamenca y vino fino, y festividad enológica en torno a sus bodegas. Se celebra en Junio (San Antonio) y Septiembre (Vendimia). Es una de las ferias playeras y estivales con mayor dinamismo económico y afluencia turística de la Bahía de Cádiz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90032','fiesta','Carnaval de Chipiona y Fiestas de la Virgen de Regla','Carnaval de gran tradición andaluza, procesión multitudinaria de la Virgen en la playa y fuegos artificiales. Se celebra en Febrero (Carnaval) y Septiembre (Virgen de Regla). El Carnaval de Chipiona cuenta con la distinción de Interés Turístico de Andalucía. La salida de la Virgen de Regla marca el cierre de la temporada veraniega con desfiles masivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16008','fiesta','Ruta del Atún de Almadraba y Feria de Nuestra Señora de las Virtudes','Jornadas gastronómicas del atún (tapas en decenas de bares) y feria patronal de septiembre. Se celebra en Mayo (Ruta del Atún) y Septiembre (Feria). Su ruta gastronómica es de las más consolidadas de la costa andaluza, atrayendo masivamente al turismo gastronómico antes del verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90737','fiesta','Corpus Christi de El Gastor','Religiosa y etnográfica. Las calles se cubren por completo con un manto de juncos, hierba y flores ("la juncia") y las fachadas se decoran con altares. Se celebra en Junio. Declarada de Interés Turístico Nacional de Andalucía por la espectacular transformación vegetal de todo el pueblo y sus toques con la "Gaita Gastoreña".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11027','fiesta','Feria de la Primavera y Fiesta del Vino Fino','Gran feria andaluza dedicada cada año a una ciudad de España, maridada con vino fino de las bodegas locales, caballos y casetas. Se celebra en Mayo. Declarada de Interés Turístico Nacional de Andalucía; es una de las ferias con más prestigio y elegancia de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90738','fiesta','Semana Santa y Feria de la Cruz','Procesiones tradicionales de gran fervor y feria local de verano. Se celebra en Marzo/Abril y Septiembre. Fuerte arraigo comarcal en la transición entre la Campiña y la Sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11019','fiesta','Lunes del Toro de Cuerda y Fiestas de los Bandoleros ("Sangre y Amor en la Sierra")','Tradición taurina antiquísima y recreación histórica bandolera de los siglos XVIII y XIX. Se celebra en Julio (Toro) y Octubre (Bandoleros). La recreación de los bandoleros transforma el pueblo blanco por completo en un escenario de época, atrayendo mucho turismo de interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','fiesta','Feria del Caballo y Fiestas de la Vendimia','Feria señorial centrada en el caballo andaluz, el flamenco purista y los vinos de Jerez (Sherry); pisada de la uva y catas populares. Se celebra en Mayo (Feria) y Septiembre (Vendimia). La Feria del Caballo está declarada Fiesta de Interés Turístico Internacional; un despliegue único en el mundo de carruajes, jinetes y casetas abiertas al público.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11021','fiesta','Feria de Mayo y Jornadas Micológicas de Jimena','Feria de ganado reconvertida en lúdica y jornadas gastronómicas centradas en la recolección e ingesta de setas (chantarelas). Se celebra en Mayo y Noviembre (Micológicas). Las jornadas micológicas son referente andaluz debido a la riqueza biológica de los montes cercanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11022','fiesta','Velada y Fiestas de La Línea ("La Salvaora")','*. Feria mayor de diez días de duración con la tradicional "Cabalgata", casetas y el "Domingo Rociero". *. Se celebra en Julio. *. Destaca su "Domingo Rociero", donde toda la población y visitantes toman las calles del centro en una masiva fiesta diurna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16016','fiesta','Feria de San Isidro Labrador y Toro Embolao','Feria tradicional de campo y encierro del toro embolado el Domingo de Resurrección. Se celebra en Mayo (Feria) y Marzo/Abril (Toro). El Toro Embolao congrega a millares de jóvenes de toda la comarca de Gibraltar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','fiesta','Feria de Medina y Jornadas de Puertas Abiertas / Ruta del Dulce','Feria de las más antiguas de la provincia y promoción gastronómica del alfajor artesanal y repostería árabe. Se celebra en Junio (Feria) y Diciembre (Dulce). Capital repostera de la provincia; sus eventos de invierno atraen turismo masivo por la fama de sus dulces navideños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11024','fiesta','Romería del Lunes de Quasimodo y Feria de San Agustín','Romería centenaria (la más antigua de la provincia) y feria lúdico-comercial. Se celebra en Abril (Quasimodo) y Agosto (Feria). El Lunes de Quasimodo está declarado de Interés Turístico de Andalucía y destaca por sus meriendas campestres de "hornazos".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11025','fiesta','Fiesta de la Juventud y Concurso Nacional de Cante por Peteneras','Feria local y festival cultural de flamenco puro de máxima categoría. Se celebra en Junio (Fiesta) y Julio (Peteneras). Cuna del cante por Peteneras; su festival es una meca para los estudiosos del flamenco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11026','fiesta','Feria del Ganado y Feria de la Miel','Feria agrícola y muestra gastronómica/apícola con expositores de mieles de la Sierra de Cádiz. Se celebra en Septiembre. Gran productor regional de miel; la feria atrae a profesionales y turismo familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11028','fiesta','Feria de Puerto Real y Fiestas del Carmen','Feria típica andaluza en el Parque de Las Canteras, casetas y paseos de caballos. Se celebra en Junio. Fundada en 1843, es una de las ferias más antiguas y tradicionales del entorno de la Bahía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11029','fiesta','Feria de Agosto y Romería de Santa María de la Magdalena','Feria de verano y romería tradicional en los márgenes del río Guadalete. Se celebra en Agosto (Feria) y Julio (Romería). Fiestas muy vecinales con actividades lúdicas tradicionales de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11030','fiesta','Fiesta de la Urta y Feria de la Primavera','Gastronómica (degustaciones del plato típico "Urta a la Roteña", concursos de cocina) y feria de casetas andaluzas. Se celebra en Agosto (Urta) y Mayo (Feria). La Fiesta de la Urta está declarada de Interés Turístico de Andalucía, siendo el epicentro del verano roteño con conciertos y gastronomía marinera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11031','fiesta','Feria del Carmen y de la Sal','Feria mayor de casetas con sabor marinero, conmemoración de las Salinas locales y procesión náutica de la Virgen del Carmen. Se celebra en Julio. De gran envergadura en la Bahía de Cádiz; combina el ambiente de las casetas nocturnas con el tipismo de la producción de sal tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11902','fiesta','Feria de San José','Feria patronal, suelta de vaquillas, conciertos y actividades ecuestres. Se celebra en Mayo. Fiesta local de ambiente rural muy conectada con el entorno agrario y ganadero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11033','fiesta','Feria Real de San Roque y Toro del Aguardiente','Feria mayor andaluza de día y noche, coronación de reinas y un encierro taurino tradicional desde 1649. Se celebra en Agosto. El Toro del Aguardiente, celebrado el último día de feria a primera hora de la mañana, es muy multitudinario en la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','fiesta','Carreras de Caballos en la Playa de Sanlúcar y Feria de la Manzanilla','Carreras hípicas sobre el hipódromo natural de la arena húmeda del río Guadalquivir, y feria andaluza consagrada a su vino Manzanilla. Se celebra en Agosto (Carreras) y Mayo/Junio (Feria de la Manzanilla). Las Carreras de Caballos son Fiesta de Interés Turístico Internacional; un espectáculo visual único en el mundo con el Parque Nacional de Doñana al fondo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11034','fiesta','Semana Santa de Setenil y Fiesta de los Entresijos','Religiosa singular por su orografía urbana bajo las rocas, y festividad cultural de verano. Se celebra en Marzo/Abril (Semana Santa). Declarada de Interés Turístico de Andalucía. La estampa de las hermandades de los "Blancos" y los "Negros" desfilando por las calles cueva techadas por rocas gigantescas es impactante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11035','fiesta','Feria de Tarifa y Cabalgata Agrícola en honor a la Virgen de la Luz','Feria andaluza que comienza con una multitudinaria escolta de cientos de jinetes a caballo que acompañan a la virgen desde su santuario rural. Se celebra en Septiembre. La Cabalgata Agrícola es Fiesta de Interés Turístico de Andalucía, siendo una de las estampas ecuestres más bellas del Campo de Gibraltar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11036','fiesta','Fiestas Patronales de la Virgen de la Antigua y Feria de San Roque','Procesión tradicional y verbenas en su pintoresco casco antiguo. Se celebra en Agosto. Fiesta familiar de carácter marcadamente local en el norte de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11037','fiesta','Fiesta de la Trebujena Gastronómica (Garbanzos como Conejo) y Fiesta de la Vendimia / Alboroque','Concurso de cocina tradicional multitudinario en el campo y festividad del mosto y vino local. Se celebra en Diciembre (Cocina) y Septiembre (Vendimia). El concurso gastronómico de los "Garbanzos como Conejo" y sus fiestas del mosto atraen a miles de personas de la provincia buscando autenticidad culinaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11038','fiesta','Cruces de Mayo ("La Crujía de Gamones") y Feria de Septiembre','Rito pagano/religioso donde se calientan plantas de gamón en hogueras para hacerlas explotar dándoles un fuerte golpe, y feria mayor. Se celebra en Mayo (Crujía de Gamones) y Septiembre (Feria). La Crujía de Gamones está declarada Fiesta de Interés Turístico de Andalucía por ser una tradición sonora y visual completamente exclusiva de esta localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','fiesta','Toro de Embolao y Feria de la Primavera','Encierro taurino por las empinadas calles del pueblo blanco el Domingo de Resurrección, y feria de casetas. Se celebra en Marzo/Abril (Toro) y Abril/Mayo (Feria). La estampa monumental del Toro de Embolao corriendo entre las fachadas encaladas del recinto amurallado congrega a muchísimo turismo nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11040','fiesta','Feria del Queso Artesanal de Andalucía y Fiestas de la Virgen del Rosario','Macro-feria gastronómica dedicada a los quesos artesanos (especialmente de cabra payoya) en el pueblo más pequeño de la provincia. Se celebra en Abril (Feria del Queso). Convertida en la feria del queso más importante del sur de España; recibe en un solo fin de semana a más de 20.000 visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11041','fiesta','Feria de San Mateo (Exposierra) y Romería de las Montañas','Feria multisectorial e histórica de ganado (de las más antiguas del país, desde el siglo XVI) y masiva romería de la comarca. Se celebra en Septiembre. La Feria de San Mateo y su exposición agrícola/ganadera son un motor comercial fundamental e histórico en toda la Sierra de Cádiz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90739','fiesta','Corpus Christi de Zahara de la Sierra','Fiesta de Interés Turístico Nacional. Todo el pueblo se transforma en un bosque artificial tapizando el suelo de juncia, vistiendo las paredes con ramas de olivo y palmas, creando una atmósfera mística e inolvidable. Se celebra en Junio. *. Una de las fiestas más singulares, bellas y antiguas de España, con una repercusión turística y fotográfica de primer orden). Con esto queda completada al 100% la provincia de Cádiz de la A a la Z. Puedes copiar este bloque a tu documento Word. Dime si pasamos al siguiente bloque del documento para redactar la siguiente provincia de Andalucía en orden alfabético, que corresponde a Córdoba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90740','fiesta','Feria de San Andrés y Fiesta del Aceite de Oliva','Feria de ganado histórica, tradiciones lúdicas y promoción de su aceite de oliva virgen extra. Se celebra en Abril (Aceite) y Noviembre (San Andrés). Su fiesta oleícola destaca en la comarca del Alto Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17001','fiesta','Semana Santa y Feria Real','Religiosa (desfiles barrocos en su singular Plaza de San José) y feria mayor de casetas. Se celebra en Marzo/Abril (Semana Santa) y Agosto (Feria). Semana Santa de gran arraigo y belleza plástica debido al urbanismo de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90741','fiesta','Festum (Jornadas de Cultura Romana) y Fiestas de San Juan','Recreación histórica y cultural (banquetes romanos, teatro, visitas a su villa romana) y patronal. Se celebra en Agosto (Festum). Referente andaluz en turismo arqueológico y recreación histórica rigurosa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17002','fiesta','Feria de Nuestra Señora del Rosario y Mercado Medieval','Feria tradicional andaluza y jornadas culturales a las faldas de su famoso castillo. Se celebra en Octubre. Su espectacular castillo potencia el turismo de sus fiestas y zocos medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90445','fiesta','Fiesta de la Cruz de Añora y Olimpiadas Rurales de los Pedroches','Fiesta etnográfica (cruces de mayo monumentales forradas de encaje) y evento lúdicodeportivo de juegos tradicionales. Se celebra en Mayo (Cruces) y Julio (Olimpiadas). Las Cruces están declaradas de Interés Turístico de Andalucía. Las Olimpiadas Rurales son un fenómeno masivo único que recupera juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17003','fiesta','Semana Santa de Baena y Jornadas del Olivar y el Aceite','Religiosa y cultural-gastronómica. Destaca el toque atronador de miles de tambores artesanos. Se celebra en Marzo/Abril (Semana Santa) y Noviembre (Aceite). Declarada Fiesta de Interés Turístico Nacional. La figura de los "Coliblancos" y "Colinegros" tocando el tambor es mundialmente famosa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17004','fiesta','Feria de San Roque y Romería de Nuestra Señora de la Alcantarilla','Feria mayor de verano y multitudinaria romería compartida con Extremadura. Se celebra en Agosto (San Roque) y Abril (Romería). La romería es una de las más multitudinarias e históricas de la comarca de Los Pedroches.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90446','fiesta','Feria y Fiestas de San Isidro y Feria de Nuestra Señora de los Remedios','Feria tradicional de casetas, muestras de ganado y procesión de la patrona. Se celebra en Mayo (San Isidro) y Septiembre (Remedios). Fiestas populares de gran arraigo en la comarca del Valle del Guadiato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90447','fiesta','Feria de Agosto y Representación Histórica "La Duquesa de Benamejí"','Feria de verano y obra teatral popular de bandolerismo en un entorno natural. Se celebra en Agosto. La representación teatral involucra a cientos de vecinos y atrae a mucho turismo cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90742','fiesta','Fiestas de la Virgen del Rosario','Fiestas patronales, verbenas de verano y juegos tradicionales para niños. Se celebra en Agosto / Octubre. Celebración de carácter marcadamente familiar y de retorno de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17005','fiesta','Feria Real de Bujalance y Feria de la Patrona (Virgen de la Asunción)','Una de las ferias comerciales más antiguas de la provincia y festividad religiosa. Se celebra en Septiembre (Feria Real). Su feria real conserva una importante esencia agrícola y comercial en la campiña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17006','fiesta','Fiestas en honor a María Santísima de la Sierra y Semana Santa','Feria Real, bajada de la Virgen desde su santuario (Romería) y desfiles procesionales barrocos. Se celebra en Septiembre (Fiestas de la Sierra) y Marzo/Abril. Declaradas de Interés Turístico Nacional. La "Bajada de la Virgen" el 4 de septiembre congrega a decenas de miles de personas a caballo y a pie.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90448','fiesta','Cañete en Flor y Feria Real de San Miguel','Festival cultural y paisajístico (calles y fachadas decoradas con flores artísticas al estilo de los patios) y feria de septiembre. Se celebra en Mayo (Cañete en Flor) y Septiembre (Feria). El festival de las flores se ha convertido en un gran foco de atracción turística de primavera en la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90449','fiesta','Fiesta del Toro de Cuerda y la Pascua de los Moraos','Encierro tradicional taurino medieval y carnaval singular de disfraces y coplas antiguas. Se celebra en Agosto (Toro) y Febrero/Marzo (Pascua). Ambas celebraciones están declaradas de Interés Turístico de Andalucía por conservar ritos muy primitivos y únicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26041','fiesta','Feria del Lechón Ibérico y Feria de San Antonio Abad','Gastronómica (degustación masiva de lechón frito, embutidos y productos del cerdo ibérico) y patronal. Se celebra en Octubre (Feria del Lechón). Referente gastronómico provincial en pleno Parque Natural de la Sierra de Cardeña y Montoro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14017','fiesta','Feria de San Jaime y Fiesta de la Colonización','Feria andaluza de trajes de flamenca y casetas, y conmemoración histórica de su fundación por Carlos III con colonos centroeuropeos. Se celebra en Julio (Feria) y Agosto (Colonización). Singular por conservar y recordar el legado y apellidos de los colonos alemanes y franceses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14018','fiesta','Feria Real de la Infanta Doña María y Fiestas del Ecce Homo','Feria mayor de casetas y procesión tradicional del patrono. Se celebra en Septiembre (Feria Real) y Marzo/ Abril. Ambiente muy festivo y de reunión comarcal en el Alto Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14019','fiesta','Feria Artesanal de la Madera de Olivo (Ars Olea) y Feria Real','Feria cultural, turística y artesanal dedicada al tallado del olivo, combinada con gastronomía local y bacalao. Se celebra en Octubre (Ars Olea) y Septiembre (Feria). Ars Olea atrae a compradores de artesanía de toda España y pone en valor su barrio histórico fortificado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14020','fiesta','Feria de Santa Ana','Fiestas patronales veraniegas, verbenas populares y campeonatos de juegos rurales. Se celebra en Julio. Celebración entrañable que duplica la población del municipio en época estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14021','fiesta','Festival de los Patios Cordobeses, Feria de Nuestra Señora de la Salud y Semana Santa','Concurso internacional de patios decorados con flores, gran feria andaluza con casetas abiertas en el Arenal, y desfiles procesionales solemnes. Se celebra en Mayo (Patios y Feria). Los Patios están declarados Patrimonio Inmaterial de la Humanidad por la UNESCO y Fiesta de Interés Turístico Internacional. El "Mayo Cordobés" es un fenómeno turístico mundial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14022','fiesta','Feria en honor a San Pedro y Cata del Vino Montilla-Moriles','Feria tradicional de verano y evento de promoción enológica de vinos finos de la zona. Se celebra en Abril/Mayo (Cata) y Septiembre (Feria). Gran cultura del vino en sus bodegas, muy vinculada a la Subbética cordobesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14023','fiesta','Fiesta de la Candelaria y Feria de San Roque','Gran hoguera tradicional con mercado medieval, espectáculos de fuego y feria mayor de casetas. Se celebra en Febrero (Candelaria) y Agosto (San Roque). Su Fiesta de la Candelaria es uno de los eventos invernales más bonitos y visitados de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14024','fiesta','Feria Real en honor a Nuestro Padre Jesús Nazareno','Feria mayor de casetas, carreras de cintas y procesión tradicional. Se celebra en Septiembre. *. Fiesta típicamente campesina de cierre de campaña veraniega con fuerte tradición vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14025','fiesta','Feria del Chorizo Artesano y Feria de San Bartolomé','Gastronómica (degustación del embutido típico local, la morcilla de Espejo y chorizos) y feria de verano. Se celebra en Octubre (Matanza/Chorizo) y Agosto (Feria). Su feria gastronómica del embutido goza de gran prestigio en toda la provincia de Córdoba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14026','fiesta','Feria de San Sebastián y Fiestas de la Virgen de la Estrella','Patronal de invierno y feria veraniega con romería al santuario rural. Se celebra en Enero y Agosto. Mucha animación veraniega potenciada por los aficionados a la escalada en sus parajes naturales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17010','fiesta','Feria Real de Fernán Núñez y Fiesta de la Entrá de Mayo','Feria andaluza de gran recinto, conciertos y concurso popular de cruces florales. Se celebra en Agosto (Feria) y Mayo (Entrá). Su feria de agosto es de las más animadas de la comarca de la Campiña Sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14029','fiesta','Representación Popular de la obra teatral "Fuenteovejuna" de Lope de Vega y Feria de San Agustín','Escenificación teatral monumental a cargo de los propios vecinos en la plaza pública, y feria tradicional. Se celebra en Agosto. La representación teatral del clásico de Lope de Vega tiene proyección nacional y atrae a miles de espectadores de toda España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14030','fiesta','Fuente Palmera de Boda y Feria Real de la Purísima Concepción','Feria comercial de moda nupcial de relevancia nacional y feria patronal. Se celebra en Octubre (Feria Nupcial) y Agosto (Feria Real). Conocido como "El Pueblo de las Novias"; su feria nupcial atrae a miles de compradores de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14031','fiesta','Danza de los Danzantes de FuenteTójar (Fiestas de San Isidro)','Fiesta de Interés Turístico de Andalucía. Danza ritual milenaria con sombreros gigantes llenos de cintas de colores e instrumentos antiguos. Se celebra en Mayo. Es una de las joyas folclóricas más antiguas de España, preservada de forma idéntica desde hace siglos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14033','fiesta','Feria de Nuestra Señora del Carmen','Feria local de casetas, concursos gastronómicos de salmorejo y juegos infantiles. Se celebra en Julio. Festa de carácter tranquilo, muy familiar y de vecindad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14034','fiesta','Romería de la Virgen de las Cruces','Peregrinación religiosa y convivencia en el paraje arqueológico de Majadaiglesia. Se celebra en Mayo. Gran valor paisajístico e histórico debido al entorno de pozos romanos donde se celebra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14035','fiesta','Representación de "La Vaquera de la Finojosa" y Feria de San Agustín','Teatro popular monumental en la plaza de la catedral (basado en el poema del Marqués de Santillana) y gran feria comercial. Se celebra en Agosto. La representación teatral es un hito cultural andaluz con gran cobertura mediática cada pocos años.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14036','fiesta','Feria de San Abundio y Romería de San Cristóbal','Feria tradicional de verano y romería ecuestre en plena Sierra Morena. Se celebra en Julio (San Abundio). Muy concurrida por turistas rurales atraídos por la naturaleza de su Parque Natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14037','fiesta','Feria Real de la Virgen de la Piedad y Semana Santa','Procesiones tradicionales, bajada de la patrona y desfiles con trajes típicos en el entorno de su castillo y su embalse. Se celebra en Septiembre (Feria Real). El entorno estético de su embalse y el barrio de los patios llenos de macetas azules potencian estas fiestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14038','fiesta','Fiestas Aracelitanas (Virgen de Araceli) y Semana Santa de Lucena','Fiestas mayores de gran envergadura, procesiones solemnes cargadas al estilo "santería" local y feria de atracciones. Se celebra en Mayo (Aracelitanas) y Marzo/Abril (Semana Santa). Las Fiestas Aracelitanas están declaradas de Interés Turístico Nacional. La "Santería lucentina" es una forma de portar los pasos única en Andalucía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14039','fiesta','Feria del Olivar y la Feria de San Bartolomé','Muestra agroalimentaria de aceite de oliva y maquinaria, y feria de verano con verbenas. Se celebra en Agosto. Pueblo blanco de gran tradición olivarera con unas verbenas veraniegas muy pintorescas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14040','fiesta','Feria del Ajo y del Melón de Montalbán y Fiestas de Nuestro Padre Jesús Calvario','Macro-feria gastronómica y comercial agroalimentaria (expositores, tren de catas) y fiesta patronal. Se celebra en Julio (Ajo y Melón) y Agosto (Patronal). Principal productor de ajo de Andalucía; su feria agrícola congrega a miles de profesionales y visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14041','fiesta','Paxera (Feria del Vino Pedro Ximénez) y Feria de San Acacio','Exhibición etnográfica y gastronómica de la pasera (secado de la uva al sol) y catas de vino dulce. Se celebra en Septiembre (Paxera). La Paxera es un evento visual y culinario espectacular al mostrar el proceso artesanal del vino pasificado más grande de Europa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14042','fiesta','Fiesta de la Vendimia de MontillaMoriles y Fiesta de la Cruz','Pisada tradicional de la uva, cata abierta de vinos finos, amontillados y dulces, y desfiles de caballos. Se celebra en Septiembre (Vendimia) y Mayo (Cruces). Declarada de Interés Turístico Nacional. Epicentro del marco vinícola de la provincia, cita ineludible para los amantes de la enología.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14043','fiesta','Semana Santa de Montoro y Feria del Olivo','Desfiles procesionales con los "Romanos de Montoro" (armaduras artesanales centenarias) y macroferia internacional del aceite de oliva. Se celebra en Marzo/Abril (Semana Santa) y Mayo (Feria del Olivo, bienal). Su Semana Santa y su Feria Internacional del Olivo son referentes andaluces y atraen a miles de personas al meandro del río Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14044','fiesta','Mundamortis (Jornadas de Turismo de la Muerte) y Feria de San Pancracio','Único festival de España que combina turismo cultural, gastronomía (gachas tradicionales) y visitas nocturnas a sus famosas Cisternas Romanas del cementerio. Se celebra en Noviembre (Mundamortis) y Mayo (San Pancracio). Evento pionero e internacional de turismo cultural de cementerios y patrimonio romano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14045','fiesta','Real Feria del Vino de Moriles y Fiestas de la Virgen del Rosario','Feria monográfica y cata gigante de vinos de sus bodegas locales con degustaciones gastronómicas. Se celebra en Octubre (Feria del Vino). Co-capital de la denominación de origen; sus bodegas abren sus puertas en una fiesta de gran afluencia regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14046','fiesta','Feria Real de San Pedro','Feria andaluza clásica, concursos de destreza en la recolección de aceituna (simulacros) y casetas populares. Se celebra en Julio. Ambiente muy acogedor e integrador típico del interior cordobés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14047','fiesta','Fiestas de San Benito y la Danza de las Espadas (Bachimala)','Religiosa, folclórica y etnográfica. Destaca la ancestral danza guerrera donde los hombres entrelazan espadas de hierro alrededor del cuello del santo y del maestro de danza. Se celebra en Marzo (Romería) y Julio (Feria). La Danza de las Espadas está declarada de Interés Turístico de Andalucía por su altísimo valor antropológico y espectacularidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14048','fiesta','Feria Real en honor a la Virgen del Carmen y Fiesta de la Candelaria','Feria mayor de verano y hogueras tradicionales de invierno. Se celebra en Agosto (Feria) y Febrero (Candelaria). Fiesta de gran dinamismo vecinal y excelente ambiente de casetas en el sur de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14049','fiesta','Feria de Mayo y Fiesta de la Feria de Agosto / Semana de Teatro','Feria mayor tradicional, festejos patronales de la Virgen de Belén y muestra de artes escénicas de relevancia andaluza. Se celebra en Mayo (Feria), Julio (Teatro) y Septiembre (Patrona). Su Feria de Teatro en el Sur la convierte en el gran epicentro de las artes escénicas de la comunidad, sumando gran valor cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14050','fiesta','Fiestas de Santiago Apóstol y Fiesta del Cristo de los Desamparados','Patronal, verbenas populares, eventos deportivos y procesiones. Se celebra en Julio (Santiago) y Septiembre (Cristo). Celebración muy participativa en la comarca del Alto Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14051','fiesta','Función de los Soldados (Fiesta de Tarugos) y Feria de San Agustín','Tradición histórica-militar de origen centenario y feria tradicional de verano en el corazón de Los Pedroches. Se celebra en Septiembre (Función) y Agosto (Feria). Su "Función de los Soldados" recrea un voto histórico de protección militar con gran vistosidad etnográfica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14052','fiesta','Feria de Nuestra Señora del Rosario y Feria de la Asunción (Pueblonuevo)','Ferias mayores de tradición minera, con un fuerte arraigo obrero, atracciones y conciertos. Se celebra en Agosto (Asunción) y Octubre (Rosario). Es una de las ferias con mayor infraestructura y extensión del Valle del Guadiato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14053','fiesta','Feria de la Salud y Romería de la Virgen de la Salud','Feria de mediodía y noche, paseos de caballos y peregrinación rural a la ermita. Se celebra en Septiembre. Tradición muy consolidada que marca el final de las cosechas en la Vega del Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14054','fiesta','Feria de Nuestra Señora de las Mercedes y Romería de la Virgen de Luna','Gran feria taurina y ganadera del norte de la provincia, y romería tradicional compartida con porteadores armados (hornazos y descargas de pólvora). Se celebra en Septiembre (Feria) y Febrero (Romería). La Romería de la Virgen de Luna está declarada de Interés Turístico de Andalucía. Su Feria de las Mercedes es la más importante de la mitad norte cordobesa por su feria taurina de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14055','fiesta','Semana Santa de Priego y Feria Real de San Nicasio','Religiosa barroca de máxima devoción, con la multitudinaria subida al Calvario de la canastilla de Jesús Nazareno, y feria comercial/ganadera. Se celebra en Marzo/Abril (Semana Santa) y Septiembre (Feria). Su Semana Santa y los Domingos de Mayo están declarados de Interés Turístico Nacional por su espectacular imaginería barroca y la bendición masiva de hornazos en el monte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14056','fiesta','Semana Santa de Puente Genil ("La Mananta") y Feria Real','Religiosa única en España (personajes bíblicos desfilando con corporaciones y "rostricos") y feria andaluza. Se celebra en Marzo/Abril ("La Mananta") y Agosto (Feria). La Mananta es Fiesta de Interés Turístico Nacional de Andalucía y destaca a nivel internacional; los desfiles con figuras del Antiguo y Nuevo Testamento por las calles le confieren un valor antropológico inigualable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14059','fiesta','Fiesta del Colono y Verbena de San Roque','Recreación histórica y fiesta gastronómica que conmemora la fundación del pueblo por colonos centroeuropeos con degustaciones del "Pavo con Fideos" tradicional. Se celebra en Agosto. Muy singular por mantener platos típicos y costumbres de herencia alemana y francesa del siglo XVIII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14061','fiesta','Fiestas del Calabacino y Romería de la Virgen de las Cruces','Tradición medieval carnavalesca-patronal y romería a orillas del río Guadalmez. Se celebra en Febrero (Calabacino) y Mayo (Romería). El Calabacino es un rito invernal muy llamativo y cómico con disfraces y coplillas locales en los confines de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14060','fiesta','Feria del Cristo de la Vera Cruz y Fiesta de la Tapa','Feria mayor de verano y muestra gastronómica de productos de la campiña. Se celebra en Septiembre (Feria) y Julio (Gastronomía). Feria señorial muy concurrida en la Campiña Sur cordobesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14062','fiesta','Romería de la Virgen de Veredas y Feria de San Sebastián','Romería de gran arraigo ganadero en carretas engalanadas y fiesta patronal. Se celebra en Mayo (Romería) y Agosto (Feria). La romería congrega a gran parte del Valle de los Pedroches por su devoción histórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14063','fiesta','Corpus Christi de Valenzuela','Religiosa y artística. Todo el municipio amanece cubierto de kilómetros de alfombras multicolores hechas con serrín tintado y sal, dibujando filigranas en el suelo. Se celebra en Junio. Declarado de Interés Turístico de Andalucía debido al asombroso despliegue artesanal de sus vecinos por todo el plano urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14064','fiesta','Feria de la Virgen de la Fátima y Fiestas de San Borrego','Romería comarcal, procesiones y verbenas de verano. Se celebra en Mayo. Festa entrañable de reencuentro vecinal y familiar en el Guadiato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14066','fiesta','Feria en honor a Nuestra Señora de la Estrella','Feria mayor con procesiones, espectáculos pirotécnicos junto al Guadalquivir, casetas y conciertos. Se celebra en Septiembre. Una de las ferias de septiembre con mayor renombre y afluencia en el límite provincial con Jaén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14067','fiesta','Gran Huevada y Feria de San Bartolomé','Gastronómica masiva (reparto gratuito de miles de huevos fritos, pan y vino en la plaza) y feria mayor. Se celebra en Agosto. La "Gran Huevada" se celebra en la víspera de la feria y atrae a miles de personas de toda la provincia por su carácter único y festivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14068','fiesta','Fiesta de las Aguas y Feria de San Rafael','Festividad lúdica vinculada a su histórica tradición de balnearios y aguas medicinales, y feria local. Se celebra en Julio (Aguas) y Mayo (San Rafael). Singular por los tradicionales "baños de agua" y juegos infantiles con agua en Sierra Morena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14069','fiesta','Feria del Jamón Ibérico de Los Pedroches y Feria de San Miguel','Macro-feria gastronómica dedicada al jamón de bellota 100% ibérico (concursos de cortadores, catas) y feria tradicional de atracciones. Se celebra en Octubre (Feria del Jamón) y Agosto (San Miguel). La Feria del Jamón es el evento gastronómico de referencia del norte de Andalucía; congrega a los mejores profesionales del sector cárnico del país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14070','fiesta','Feria de San Jacinto y Semana de Turismo de la Reina','Feria patronal y jornadas de recreación histórica/medieval basadas en leyendas locales. Se celebra en Agosto. Sus recreaciones teatrales nocturnas en rincones del pueblo tienen un gran encanto estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14071','fiesta','Feria de la Trasierra y Fiesta de la Trashumancia','*. Feria tradicional de verano y puesta en valor de las rutas de pastoreo serranas. *. Se celebra en Agosto. *. Ambiente serrano muy auténtico que rescata las tradiciones ganaderas de Sierra Morena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14072','fiesta','Romería de la Divina Pastora y Fiesta del Pastoreo','Romería en el paraje del Guadamatilla y feria etnográfica de tradiciones rurales. Se celebra en Mayo. Destaca la confección artesanal de los tradicionales "arcos de flores" que decoran el paso de la Virgen.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14073','fiesta','Feria de la Virgen de Villaviciosa y Fiesta Gastronómica del Corzo y la Caza Mayor','Feria mayor tradicional y jornadas de cocina cinegética basadas en las capturas de la sierra. Se celebra en Septiembre (Feria) y Noviembre (Caza). Referente provincial para los amantes de la gastronomía de caza mayor y productos del monte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14074','fiesta','Auto Sacramental de los Reyes Magos y Feria de Santa Ana','Representación teatral popular e histórica, y feria de verano con tradicionales encierros de vaquillas. Se celebra en Enero (Auto de Reyes) y Julio (Santa Ana). El Auto Sacramental está declarado de Interés Turístico de Andalucía. Se representa cada cuatro años, movilizando a casi todo el pueblo como actores en un escenario gigante al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14075','fiesta','Feria Nacional del Queso Artesanal de Zuheros y Fiestas de la Virgen de la Remedios','Macro-mercado gastronómico que reúne a los quesos artesanos con Denominación de Origen más importantes de España, y feria local. Se celebra en Septiembre (Feria del Queso). La Feria del Queso de Zuheros, ubicada en un precioso entorno de pueblo blanco fortificado, es un hito gastronómico nacional que satura de visitantes la Subbética cordobesa). [1] Con esto queda completada al 100% la provincia de Córdoba de la A a la Z. Puedes copiar este bloque directamente a tu documento Word. Dime si pasamos al siguiente bloque del documento para redactar la siguiente provincia de Andalucía en orden alfabético, que corresponde a Granada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90424','fiesta','Fiestas Patronales en honor a San Antonio de Padua','Patronal, verbenas populares, actividades culturales y tradicionales "llantas" (hogueras). Se celebra en Junio. Fiesta de carácter local y vecinal enfocada en el reencuentro de la comunidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90494','fiesta','Fiestas Populares en honor a el Cristo de la Salud','Feria de grandes dimensiones con conciertos, actividades infantiles, ferias de mediodía y eventos deportivos. Se celebra en Agosto. Una de las fiestas con más afluencia del área metropolitana de Granada gracias a sus potentes verbenas y actividades.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90425','fiesta','Fiestas de San Luis Rey de Francia y Fiesta del Vino de Albondón','Patronal con tradicionales representaciones de Moros y Cristianos, y feria enológica de puesta en valor de los vinos de la Alpujarra Contraviesa. Se celebra en Agosto. Muy conocida en la comarca por sus "relaciones" históricas de moros y cristianos y la degustación de sus reconocidos vinos peleones y de viticultura heroica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90426','fiesta','Fiestas de San Francisco de Asís','Fiestas patronales, procesiones religiosas y verbenas nocturnas. Se celebra en Octubre. Celebración entrañable en la comarca de Guadix con un marcado acento familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90037','fiesta','Fiestas de San Patricio y Feria de Verano','Devoción patronal singular (único patrón San Patricio en la España peninsular) y feria de atracciones. Se celebra en Marzo (San Patricio) y Agosto (Feria). La festividad de San Patricio atrae a numerosos curiosos y descendientes de irlandeses debido a la singular historia de la llegada de la imagen a la costa granadina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90427','fiesta','Fiestas de Nuestra Señora de las Angustias','Fiestas tradicionales del Valle de Lecrín, música de bandas y comidas populares. Se celebra en Agosto. Ambiente festivo de retorno estival en un entorno natural único.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90428','fiesta','Fiestas de la Virgen del Rosario y Fiesta de los Chiscos','Patronal con desfile de gigantes y cabezudos, y hogueras tradicionales de invierno (chiscos). Se celebra en Agosto (Patronales) y Enero (Chiscos). La fiesta invernal de los Chiscos destaca por la quema de ramajes y la degustación de embutidos locales en el Marquesado de Zenete.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90429','fiesta','Fiestas de San Sebastián y Fiesta del Pan de Alfacar','Patronal y gastronómica (promoción de su pan con Indicación Geográfica Protegida - IGP). Se celebra en Enero (San Sebastián) y eventos promocionales del pan en otoño. Su tradición panadera y los eventos gastronómicos vinculados a su famoso horno moruno atraen a numeroso público de toda la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90430','fiesta','Feria Real de Santa Ana y Fiesta del Sgarracho','Feria mayor de verano y representación etnográfica satírica. Se celebra en Julio. Su feria de verano cuenta con gran arraigo en el Poniente Granadino, destacando las actividades en sus pedanías como Fuentes de Cesna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19001','fiesta','Carnaval de Alhama de Granada y Feria de Septiembre','Carnaval tradicional e histórico de "máscaras y mascarones" que recorren las calles entonando coplillas satíricas, y feria mayor. Se celebra en Febrero (Carnaval) y Septiembre (Feria). Declarado Fiesta de Interés Turístico de Andalucía. Es uno de los carnavales más antiguos, singulares y puros que se conservan en la comunidad autónoma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90431','fiesta','Fiestas de la Inmaculada Concepción (Fiestas Grandes)','Fiestas patronales religiosas de gran fastuosidad, verbenas multitudinarias y carrozas. Se celebra en Agosto. Aunque la festividad litúrgica es en diciembre, sus fiestas grandes se trasladan al verano para maximizar la participación.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90495','fiesta','Fiestas de San Roque','Fiestas patronales, actividades lúdicas infantiles y verbenas populares. Se celebra en Agosto. Centrada en el encuentro de los vecinos de la comarca de Los Montes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90496','fiesta','Fiestas en honor al Santo Cristo de la Salud','Tradición alpujarreña, procesiones por calles estrechas y empinadas y comidas comunitarias. Se celebra en Septiembre. Conserva el sabor y la autenticidad de las celebraciones de la alta montaña granadina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19002','fiesta','Fiestas Patronales de la Virgen de la Antigua','Fiesta mayor de la costa tropical con una espectacular procesión marítimo-terrestre y un colosal castillo de fuegos artificiales piromusicales lanzados desde los peñones costeros. Se celebra en Agosto. Declarada Fiesta de Interés Turístico de Andalucía. Su espectáculo de fuegos artificiales del 15 de agosto es el más famoso e imponente del litoral granadino, congregando a más de 100.000 espectadores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18904','fiesta','Fiestas del Santo Cristo de la Expiración (Mecina Bombarón) y Fiestas de la Virgen de los Dolores (Yegen)','Patronal alpujarreña tradicional y jornadas culturales sobre tradiciones locales. Se celebra en Agosto y Septiembre. Especial interés por sus paisajes urbanos típicos y el fomento del turismo rural durante las festividades.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18018','fiesta','Fiestas de San Hermenegildo','Fiestas patronales ligadas históricamente a su pasado minero, destacando el tradicional "palo de San Hermenegildo" y los fuegos de pólvora. Se celebra en Mayo. Mucha devoción y carácter identitario ligado a los pies de Sierra Nevada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18020','fiesta','Fiestas de San Sebastián y la Virgen de los Dolores','Patronal, verbenas estivales y actividades deportivas en el entorno del Embalse de los Bermejales. Se celebra en Agosto. Potenciada turísticamente por los veraneantes que acuden a las zonas recreativas del pantano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18021','fiesta','Fiestas de San Miguel Arcángel','Macro-feria urbana con un recinto ferial de gran capacidad, conciertos de primer nivel nacional, eventos deportivos y feria de día. Se celebra en Septiembre. Por volumen de población e infraestructuras, es una de las ferias más populosas y vibrantes del cinturón metropolitano de Granada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18022','fiesta','Fiestas de Santa Ana','Feria mayor andaluza, tradicionales espectáculos taurinos y ecuestres, y conciertos al aire libre en el Coliseo Ciudad de Atarfe. Se celebra en Julio. Feria de gran solera que destaca especialmente por la calidad de su programación cultural y espectáculos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18023','fiesta','Feria y Fiestas de Baza / Fiesta del Cascamorras','Celebración etnográfica ancestral donde un personaje ataviado con un traje multicolor (el Cascamorras) viaja desde Guadix para intentar llevarse la Virgen de la Piedad, mientras miles de vecinos manchados de pintura negra impiden su avance. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico Internacional. Es una de las joyas antropológicas de España; una carrera desenfrenada de pintura y agua única en el mundo compartida con Guadix.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18024','fiesta','Fiestas en honor a San Roque','Patronal de verano, pasacalles, verbenas y comidas de convivencia vecinal. Se celebra en Agosto. Fiestas muy familiares en un entorno de media montaña a las puertas de la Sierra de Huétor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18025','fiesta','Fiestas de la Virgen de la Paz','Fiestas patronales tradicionales en el marco de sus singulares paisajes de cárcavas y casas cueva. Se celebra en Agosto. Entorno único que dota a las procesiones y verbenas de un ambiente muy pintoresco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18027','fiesta','Fiestas de la Virgen del Carmen','*. Feria local, procesión de la patrona, verbenas nocturnas y actividades deportivas y gastronómicas. *. Se celebra en Julio. *. Centro de actividad festiva relevante dentro del plano de la Hoya de Guadix.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18028','fiesta','Fiestas de San Sebastián','Fiestas tradicionales, quema de grandes hogueras populares y verbenas. Se celebra en Agosto (traslado estival) y Enero (litúrgico). Marcado carácter olivarero y comarcal en la zona norte de Los Montes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18029','fiesta','Fiestas de Moros y Cristianos en honor a Nuestra Señora de la Cabeza','Recreación histórica y fiesta religiosa. Destaca por albergar las "Coplas", que componen el texto de las fiestas de Moros y Cristianos de mayor extensión e importancia literaria de toda España. Se celebra en Abril. Declarada de Interés Turístico de Andalucía. Sus desfiles, la indumentaria de las comparsas y el estruendo de los trabucos la convierten en un referente monumental del Altiplano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18030','fiesta','Nochevieja en Agosto y Fiestas de San Pantaleón','Curiosidad festiva internacional (se celebra el Fin de Año con uvas, polvorones, cabalgata de Reyes Magos y nieve artificial en pleno agosto) y fiesta patronal tradicional. Se celebra en Agosto (Nochevieja veraniega y San Pantaleón). Un error en el suministro eléctrico en la Nochevieja de 1994 originó esta ingeniosa fiesta que hoy en día atrae a miles de turistas internacionales buscando tomar las uvas en manga corta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18032','fiesta','Fiestas Patronales de San Sebastián y San Antonio Abad','Tradición de la Alpujarra profunda, procesiones en el Barranco del Poqueira, bailes folclóricos y el rito del "entierro del zorro". Se celebra en Agosto. Estética espectacular gracias a la arquitectura bereber del pueblo y conservación estricta de costumbres etnográficas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18033','fiesta','Fiestas de San Felipe y Santiago y Fiesta del Vino','Patronal andaruza y muestra tradicional de vinos locales artesanos de la Sierra. Se celebra en Mayo y Agosto. Destaca el ambiente hospitalario y los convites con vino del terreno y jamón a los visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18034','fiesta','Fiestas en honor a San Sebastián','Procesiones tradicionales de invierno, verbenas trasladadas a época estival y comidas populares. Se celebra en Agosto. Fiesta eminentemente local de ambiente agrario en la comarca de Alhama.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18035','fiesta','Real Feria del Ganado de Cádiar y Fiesta del Vino ("La Fuente del Vino")','Histórica feria ganadera y gran celebración vitivinícola donde la fuente principal de la plaza del pueblo emana vino gratis de la Contraviesa ininterrumpidamente durante los días de fiesta. Se celebra en Octubre. Es una de las fiestas con más solera de la Alpujarra; el hito de la "Fuente del Vino" atrae a ríos de gente de toda la geografía andaluza). Dime si deseas que continuemos directamente con el siguiente bloque de la letra C y D de Granada (Cájar, Calicasas, Campotéjar, Caniles, Cástaras, Castilléjar, Castril, Cenes de la Vega, Chauchina, Chimeneas, Churriana de la Vega, Cijuela, Cogollos de Guadix, Cogollos de la Vega, Colomera, Cortes de Baza, Cortes y Graena, Cuevas del Campo, Cúllar, Cúllar Vega, Darro, Dehesas de Guadix, Dehesas Viejas, Deifontes, Diezma, Dílar, Dólar, Dúdar, Dúrcal...). ¿Prefieres avanzar de esta forma ordenada para ir construyendo tu Word?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18036','fiesta','Fiestas Patronales de San Francisco de Asís y el Día de la Toma de la Papilla','Patronal, eventos deportivos de hockey (gran tradición local) y verbena popular. Se celebra en Octubre. Fiesta muy concurrida por su proximidad a la capital y excelente ambiente juvenil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18037','fiesta','Fiestas en honor a la Virgen del Rosario','Procesiones tradicionales, verbenas de verano y actividades infantiles. Se celebra en Agosto. Pequeña celebración de marcado carácter familiar en el área metropolitana norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18038','fiesta','Fiestas de la Virgen de los Remedios','Patronal con desfile de carrozas, tiradas de cohetes y verbenas nocturnas. Se celebra en Mayo. Gran tradición religiosa y festiva que congrega a muchos vecinos de la comarca de Los Montes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18039','fiesta','Fiesta de San Antonio y el Robo del Santo','Fiesta etnográfica única. Los vecinos del pueblo se dividen en bandos para disputarse y "robar" la imagen de San Antonio en una emocionante y pacífica trifulca popular. Se celebra en Enero. Declarada de Interés Turístico de Andalucía debido a la tremenda singularidad de su ritual del "robo" y el fervor popular que despierta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18044','fiesta','Fiestas del Santo Cristo de la Salud','Tradición serrana, comidas populares en la plaza y procesiones por el entramado alpujarreño. Se celebra en Agosto. Conserva la pureza y el ambiente íntimo de los pueblos de la alta montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18045','fiesta','Fiestas de Santo Domingo de Guzmán y Fiesta del Agua','Patronal de verano combinada con remojones colectivos y charangas en la plaza del pueblo para mitigar el calor. Se celebra en Agosto. Fuerte poder de convocatoria en la comarca de Huéscar, atrayendo a muchos jóvenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18046','fiesta','Fiestas Patronales del Cristo del Consuelo y de la Virgen del Rosario (Tradicionales Encierros de Castril)','Encierros taurinos históricos por las empinadas y estrechas calles del pueblo, migas populares y peñas festivas. Se celebra en Octubre. Sus encierros de reses bravas son de los más famosos y espectaculares del norte de Granada por la fisonomía de sus calles medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18047','fiesta','Fiestas en honor a San Bartolomé','Feria local con casetas, ferias de mediodía, eventos culturales y rutas gastronómicas de la Vega. Se celebra en Agosto. Ubicado a las puertas de Sierra Nevada, atrae a una ingente cantidad de público de Granada capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18059','fiesta','Fiestas en honor a la Virgen del Pincho','Peregrinación religiosa de gran envergadura a nivel provincial, procesiones y feria lúdica. Se celebra en Abril. La devoción a la Virgen de la Vega o "del Pincho" moviliza cada año a miles de peregrinos de toda la Vega de Granada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18061','fiesta','Fiestas de la Virgen del Rosario y San Roque','Fiestas patronales tradicionales, carreras de cintas a caballo y verbenas. Se celebra en Agosto. Ambiente festivo rural y familiar muy arraigado en la comarca de Loja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18062','fiesta','Fiestas Patronales de la Virgen de la Cabeza','Gran feria metropolitana, espectáculos pirotécnicos de primer nivel, ferias de día y conciertos. Se celebra en Septiembre. Una de las ferias del cinturón de Granada más activas y con mayor despliegue lúdico y de casetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18048','fiesta','Fiestas en honor a Nuestro Padre Jesús Nazareno','Feria local, torneos deportivos, desfiles de carrozas y orquestas nocturnas. Se celebra en Septiembre. Fiestas participativas con una comunidad vecinal muy implicada en las actividades.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18049','fiesta','Fiestas de la Virgen de la Cabeza y la Carretada','Romería patronal que incluye el rito de "la Carretada", donde se subastan productos de la tierra para sufragar las fiestas. Se celebra en Abril. Tradición con siglos de historia a los pies de la cara norte de Sierra Nevada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90432','fiesta','Fiestas de San Antón y los Chiscos','Grandes hogueras vecinales (chiscos) por todos los barrios, acompañadas de vino mosto y productos de la matanza. Se celebra en Enero. Sus lumbres de invierno son un referente de convivencia y gastronomía tradicional en la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18051','fiesta','Fiestas del Santísimo Cristo de la Vera Cruz','Patronal, procesión solemne, competiciones deportivas y verbenas bajo la estampa de su castillo árabe. Se celebra en Septiembre. Fiesta de gran solera que reúne a las familias olivareras de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18053','fiesta','Fiestas en honor a los Santos Médicos (Cosme y Damián)','Fiestas patronales de gran devoción, ferias de día y actividades culturales en sus pedanías. Se celebra en Septiembre. Atrae a muchísimos fieles y visitantes del Altiplano debido a la fama milagrosa de sus patrones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18054','fiesta','Fiestas de San Antonio (Graena) y Fiesta de las Aguas Continentales','Fiestas populares ligadas a su tradición de balnearios y aguas termales. Se celebra en Junio y Agosto. Muy concurrida por los usuarios de las aguas medicinales y el turismo rural de casas cueva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18912','fiesta','Semana Santa Viviente de Cuevas del Campo','Representación teatral pasional. Más de 300 vecinos recrean el drama del Calvario convirtiendo el pueblo en la Jerusalén del siglo I. Se celebra en Marzo/Abril. Declarada Fiesta de Interés Turístico de Andalucía y de Interés Nacional. Atrae a miles de visitantes por el tremendo realismo de sus escenarios naturales y cuevas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18056','fiesta','Fiestas de Moros y Cristianos en honor a la Santísima Virgen de la Cabeza','Desfiles históricos masivos con espectaculares trajes de filiación levantina, boatos, música y trabucadas. Se celebra en Abril. Declarada Fiesta de Interés Turístico de Andalucía. Junto a Benamaurel, es uno de los bastiones de esta fiesta en la provincia por su vistosidad y elegancia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18057','fiesta','Fiestas de San Miguel Arcángel y la Fiesta del Vino de la Vega','Feria mayor metropolitana y jornadas de degustación de vinos mostos locales producidos artesanalmente. Se celebra en Septiembre (Feria) y Diciembre (Vino). Su certamen gastronómico de vino mosto artesanal rescata una de las tradiciones agrarias más antiguas de la Vega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18063','fiesta','Fiestas del Santo Cristo de Amparo y San Tiburcio','Fiestas patronales, encierros infantiles, verbenas y paella gigante para el pueblo. Se celebra en Octubre. Marcar el fin de las campañas agrícolas con un gran ambiente de convivencia vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18064','fiesta','Fiestas de Nuestra Señora de la Candelaria','Procesiones tradicionales, quema de lumbres en invierno y actividades lúdicas veraniegas trasladadas. Se celebra en Agosto (traslado festivo). Fiesta pequeña y hospitalaria centrada en el retorno de los emigrantes en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18065','fiesta','Fiestas Patronales de la Virgen del Rosario','Feria local de casetas, carreras de cintas, comidas populares y verbenas. Se celebra en Agosto. Municipio de reciente creación independiente; sus fiestas celebran la identidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18066','fiesta','Fiestas de la Virgen del Milagro y San Isidro','Fiestas patronales ligadas a la cultura del agua (Nacimiento de Deifontes) con verbenas y procesión tradicional. Se celebra en Agosto. *. Famosa por su "Feria del mediodía" que se celebra al frescor de sus conocidos parajes acuíferos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18067','fiesta','Fiestas de la Virgen del Rosario y el Cristo de la Fe','Fiestas patronales tradicionales en el mirador de Sierra Nevada. Se celebra en Agosto. Su espectacular ubicación dota a las procesiones y verbenas de un marco fotográfico impresionante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18068','fiesta','Fiestas de la Virgen de las Nieves y Fiesta del Mosto de Dílar','Romería serrana alpina a Sierra Nevada y jornadas gastronómicas dedicadas al vino mosto local. Se celebra en Agosto (Virgen) y Octubre/ Noviembre (Mosto). La romería asciende a gran altitud y es de una belleza paisajística espectacular; su fiesta del mosto atrae a muchísimos gastrónomos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18069','fiesta','Fiestas de San Andrés Apóstol','Procesión del patrón, quema de castillos de fuegos artificiales y bailes populares en el Marquesado. Se celebra en Noviembre. Conservación impecable de las tradiciones de invierno en el interior provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18070','fiesta','Fiestas en honor a San Blas','Patronal de invierno con reparto de roscos bendecidos, y fiestas recreativas en verano. Se celebra en Febrero. Entorno ribereño junto al río Aguas Blancas con ambiente íntimo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18071','fiesta','Fiestas de San Ramón Nonato y Feria de Turismo del Valle de Lecrín','Feria de grandes dimensiones, carrozas, castillos de fuegos artificiales y muestra promocional de productos artesanos del valle. Se celebra en Agosto. Capital del Valle de Lecrín; su feria es el gran escaparate comercial, lúdico y gastronómico de toda la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18072','fiesta','Fiestas del Cristo de la Resignación','Patronal tradicional, verbenas populares y actividades deportivas en el llano de la zona de compras. Se celebra en Agosto. En pleno crecimiento industrial, la fiesta mantiene su esencia de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18074','fiesta','Fiestas de la Virgen de la Cabeza','Fiestas patronales del Marquesado con relaciones tradicionales y comidas populares. Se celebra en Agosto. Estampa típica serrana junto a sus históricos castillos de tierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18076','fiesta','Fiestas de Nuestra Señora del Rosario y San Antón','Procesión tradicional, hogueras de invierno y verbenas de verano. Se celebra en Agosto. Muy conectada al patrimonio arqueológico y paleontológico de su entorno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18079','fiesta','Fiestas de la Virgen de los Dolores y "El 5 a las 5" (Semana Cultural de Federico García Lorca)','Feria mayor andaluza y festival cultural e institucional internacional que conmemora el nacimiento del poeta Federico García Lorca. Se celebra en Septiembre (Feria) y Junio (Semana Cultural). Los actos del "5 a las 5" tienen relevancia cultural internacional, atrayendo a literatos, músicos y turistas de todo el mundo a su casa natal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18905','fiesta','Fiestas de la Virgen de las Nieves','Macro-feria metropolitana, ferias de mediodía multitudinarias, grandes conciertos de pop/rock nacional y exhibiciones ecuestres. Se celebra en Agosto. Una de las fiestas con mayor volumen de visitantes del cinturón urbano de Granada debido a su gran despliegue de casetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18082','fiesta','Fiestas del Santo Cristo de la Expiración y Fiesta de la Matanza tradicional','Patronal de verano con desfiles, y jornadas etnográfico-gastronómicas invernales en torno al cerdo. Se celebra en Agosto (Patronales) y Enero (Matanza). Su fiesta de la matanza y el vino del país conserva recetas milenarias del Altiplano que atraen al turismo gastronómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18083','fiesta','Fiestas de San Sebastián','Fiestas vecinales, procesión del santo y verbenas estivales. Se celebra en Agosto. Municipio de baja población; la fiesta destaca por su ambiente íntimo de reencuentro familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18084','fiesta','Fiestas de la Divina Pastora','Feria metropolitana con su tradicional carrera de cintas en moto, verbenas populares y feria de día. Se celebra en Septiembre. Estrecha colaboración vecinal y ambiente muy festivo a los pies de Sierra Nevada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18085','fiesta','Fiestas de San Cayetano y Encierros Taurinos de Gor','Encierros taurinos de reses bravas por el casco urbano, considerados de los más antiguos de España (documentados desde hace siglos), acompañados de verbenas. Se celebra en Agosto. Meca de los aficionados taurinos de la provincia; sus tradicionales encierros matinales transforman el pueblo por completo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18086','fiesta','Fiestas de la Virgen de la Asunción y Festival Astronómico del Desierto','Fiestas patronales y festival científico-turístico aprovechando su cielo certificado Starlight. Se celebra en Agosto. Su festival de observación astronómica y música en el desierto de Gorafe le suma un atractivo turístico único en Europa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18087','fiesta','Feria del Corpus Christi y festividad del Día de la Toma / Semana Santa de Granada','Gran feria andaluza con un espectacular recinto de casetas (en Almanjáyar), las famosas "Carocas" (quintas satíricas), los desfiles de la Tarasca y procesión del Corpus. Semana Santa de máxima categoría internacional. Se celebra en Mayo/Junio (Corpus) y Marzo/Abril (Semana Santa). Su Semana Santa -especialmente el paso de los Gitanos por el Sacromonte- está declarada de Interés Turístico Internacional. La Feria del Corpus es uno de los hitos festivos y culturales indiscutibles del sur de España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18088','fiesta','Fiestas de Nuestra Señora de Loreto','Fiestas patronales, desfiles de carrozas engalanadas, verbenas y comidas comunitarias en la plaza. Se celebra en Agosto. Marcado acento agrario en el límite norte que separa Granada de Jaén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18089','fiesta','Fiesta del Cascamorras y Feria de Guadix','Celebración de Interés Internacional en la que el Cascamorras sale del pueblo para ir a Baza (y posteriormente regresa). Al volver a Guadix el 9 de septiembre, es recibido por miles de accitanos que lo tiñen de pintura de color arcilla/pólvora. Feria con corridas de toros y casetas. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico Internacional. El Cascamorras en Guadix representa el clímax de una de las tradiciones más espectaculares, multitudinarias e impactantes del patrimonio folclórico mundial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18906','fiesta','Fiestas de la Virgen de la Aurora (Guájar Faragüit) y San Antonio (Guájar Fondón)','Tradición de los pueblos del valle con chirimías tradicionales, música de bandas y procesiones marianas. Se celebra en Agosto. Especial belleza por el entorno natural subtropical y el carácter hospitalario de sus tres núcleos de población.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90038','fiesta','Fiestas de la Virgen del Carmen y Fiestas de San Miguel','Procesión marítima en Castell de Ferro, fuegos artificiales reflejados en el mar, verbenas de playa y feria de atracciones. Se celebra en Julio (Carmen) y Septiembre (San Miguel). La procesión marítima veraniega satura de turistas de costa toda la franja litoral del municipio). Dime si deseas que sigamos con el siguiente bloque de la letra H hasta la M de Granada (Güéjar Sierra, Güevéjar, Huélago, Huéneja, Huéscar, Huétor Santillán, Huétor Tájar, Huétor Vega, Illora, Itrabo, Iznalloz, Jayena, Jérez del Marquesado, Jete, Jun, Juviles, Láchar, Lanjarón, Lanteira, Lecrín, Lentegí, Lobras, Loja, Lugros, Lújar, Malahá, Maracena, Marchal, Moclín, Molvízar, Monachil, Montefrío, Montejícar, Montillana, Moraleda de Zafayona, Morelábor, Motril, Murtas...). ¿Pasamos al siguiente bloque para tu Word?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18094','fiesta','Fiestas Patronales en honor a San Roque y la Virgen del Rosario / Fiesta de la Asadura Matancera','Patronal serrana y Gastronómica (degustación masiva en la plaza de más de 2.000 kg de asadura al estilo güejareño cocinada a la leña). Se celebra en Agosto (Patronales) y Febrero (Asadura). Su fiesta gastronómica de la asadura matancera es un referente invernal que atrae a miles de visitantes de toda la provincia a los pies de Sierra Nevada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18095','fiesta','Fiestas Patronales en honor a la Virgen del de las Cruces','Feria local con verbenas nocturnas, actividades infantiles y comidas populares. Se celebra en Agosto. Fiestas muy participativas y con un gran ambiente juvenil por su cercanía al área metropolitana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18096','fiesta','Fiestas en honor a San Martín','Procesiones tradicionales, verbenas de verano y quema de castillos de fuegos artificiales. Se celebra en Agosto (traslado estival) y Noviembre (litúrgico). Ambiente familiar centrado en acoger a los nacidos en el pueblo que residen fuera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18097','fiesta','Fiestas en honor a la Presentación de la Virgen y San Blas','Patronal del Marquesado, tradicionales lumbres de San Blas con degustación de patatas asadas y embutidos. Se celebra en Septiembre y Febrero. Mucha tradición en sus bailes populares y arraigo de costumbres de interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18098','fiesta','Fiestas en honor a las Santas Patronas Alodía y Nunilón','Romería monumental de la "Santiya" al santuario de la sierra, desfiles de carrozas, ferias de mediodía y tradicionales bailes de las "Santas". Se celebra en Mayo. Declarada de Interés Turístico de Andalucía. Destaca por el espectacular traslado de las imágenes, la rivalidad pacífica con Puebla de Don Fadrique por la custodia de las Santas y su rica feria cordobesa-andaluza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18099','fiesta','Fiestas de San Sebastián y la Virgen de los Dolores','Fiestas patronales, actividades lúdicas en la naturaleza y verbenas populares. Se celebra en Agosto. Potenciada por su ubicación en pleno Parque Natural de la Sierra de Huétor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18100','fiesta','Feria de Mayo y Fiestas de Nuestro Padre Jesús Nazareno / Feria del Espárrago Verde','Gran feria comercial, eventos ecuestres, ferias de día multitudinarias y promoción de su producto estrella con IGP. Se celebra en Mayo y Septiembre. Es una de las ferias agrícolas y lúdicas más potentes y con mayor volumen de negocio del Poniente Granadino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18101','fiesta','Fiestas de San Roque y Jornadas del Vino y las Habas','Feria local metropolitana y muestra gastronómica/enológica dedicada al famoso vino mosto local de sus bodegas y habas con jamón. Se celebra en Agosto (San Roque) y Abril (Jornadas del Vino). Sus jornadas del vino mosto y gastronomía de la Vega atraen cada primavera a miles de personas de la capital granadina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18102','fiesta','Real Feria de Ganado de Íllora y Festival Parapanda Folk','Feria tradicional de origen ganadero y festival internacional de música folk y tradicional de gran prestigio. Se celebra en Agosto (Festival) y Octubre (Feria). El Festival Parapanda Folk está declarado de Interés Turístico de Andalucía y es uno de los certámenes de música de raíz más importantes de España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18103','fiesta','Fiestas de la Virgen de la Salud','Fiestas patronales tradicionales de la Costa Tropical, verbenas de noche y procesiones solemnes. Se celebra en Agosto. Fiesta familiar en un precioso entorno de cultivos subtropicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18105','fiesta','Feria de la Virgen de los Remedios y Feria Intercomarcal de la Caza','Feria mayor de casetas y muestra monográfica agro-cinegética dedicada al sector de la caza menor y mayor. Se celebra en Agosto (Remedios) y Septiembre/ Octubre (Caza). Capital de la comarca de Los Montes; su feria de la caza es un punto de encuentro clave para el sector a nivel andaluz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18107','fiesta','Fiestas en honor a la Virgen del Rosario y San Antonio','Fiestas patronales tradicionales, carreras de cintas a caballo y verbenas populares. Se celebra en Agosto. Arraigo vecinal con actividades muy ligadas al entorno natural de la Sierra de Almijara.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18108','fiesta','Feria Ganadera del Marquesado y Fiestas de la Virgen de la Purísima','Feria de ganado tradicional (una de las pocas que subsisten con compraventa real de reses) y fiestas patronales. Se celebra en Septiembre. Su feria de ganado del 24 de septiembre atrae a ganaderos de toda Andalucía y conserva un inmenso valor etnográfico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18109','fiesta','Fiestas en honor a la Virgen de Bodíjar','Fiestas patronales tradicionales de la costa interior, procesión de la virgen por el valle de los frutos tropicales. Se celebra en Diciembre y Agosto (traslado lúdico). Carácter hospitalario y ambiente veraniego muy agradable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18111','fiesta','Fiestas de la Virgen de la Merced','Feria local, torneos deportivos, verbenas de noche y actividades relacionadas con su histórica tradición de cerámica artesanal. Se celebra en Septiembre. Mucha participación vecinal potenciada por su crecimiento demográfico en el cinturón de Granada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18112','fiesta','Fiestas en honor a la Virgen del Rosario','Tradición alpujarreña, quema de tracas, bailes populares y comidas colectivas en la plaza. Se celebra en Agosto. Municipio de baja población; sus fiestas conservan la esencia más pura e íntima de la Alta Alpujarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18115','fiesta','Fiestas Populares de Láchar y Feria de Peñuelas','Feria de verano con desfiles de carrozas, ferias de mediodía en las calles y orquestas en directo. Se celebra en Agosto. Muy animadas debido al carácter festivo y hospitalario de sus vecinos en la Vega Baja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18116','fiesta','Fiestas de San Juan y de la Juventud (Fiesta del Agua y del Jamón)','Hito lúdico monumental. En la medianoche de San Juan se celebra la "Carrera del Agua", donde decenas de miles de personas recorren las calles empapándose con mangueras, cubos y camiones cisterna durante una hora exacta. Se celebra en Junio. Declarada Fiesta de Interés Turístico de Andalucía. Es la fiesta del agua más famosa, multitudinaria y frenética de España, congregando a decenas de miles de turistas nacionales e internacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18117','fiesta','Fiestas del Santo Cristo de las Penas','Fiestas patronales del Marquesado, procesión solemne, tradicionales "reuniones" familiares y verbenas de verano. Se celebra en Agosto. Mucho arraigo religioso y gran afluencia de emigrantes que retornan en época estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18119','fiesta','Fiestas del Santo Cristo del Zapato (Chite) y Fiestas Patronales de Talará','Fiestas que aglutinan las tradiciones de sus seis núcleos de población, destacando procesiones singulares y ferias de día. Se celebra en Septiembre. La devoción al Cristo del Zapato atrae a fieles de todo el Valle de Lecrín debido a su curiosa iconografía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18120','fiesta','Fiestas de la Virgen del Rosario','Fiestas patronales tradicionales, comidas populares en la plaza y verbenas bajo los árboles de la sierra. Se celebra en Agosto. Ambiente rural e íntimo en un enclave ideal para el turismo activo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18121','fiesta','Fiestas de San Agustín (Lobras) y de la Virgen de la Candelaria (Tímar)','Tradición etnográfica alpujarreña, comidas comunitarias a base de migas y vinos de la Contraviesa. Se celebra en Agosto. Conserva un encanto rural único gracias a su baja población y el esmero de sus vecinos por mantener los ritos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18122','fiesta','Feria Mayor de Loja y Semana Santa de Loja','*. Gran feria andaluza de verano con casetas y conciertos, y Semana Santa singular con la figura de los "Incensarios" (personajes satíricos de estética única que danzan ante los pasos). *. Se celebra en Agosto (Feria) y Marzo/Abril (Semana Santa). *. Su Semana Santa está declarada de Interés Turístico Nacional de Andalucía debido al incalculable valor antropológico de los Incensarios, únicos en el mundo del folclore religioso.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18123','fiesta','Fiestas del Santo Cristo de los Milagros','Fiestas patronales religiosas, procesión solemne por la serranía y verbenas de verano. Se celebra en Agosto. Punto de acceso al espectacular Bosque de la Dehesa del Camarate; fiestas muy acogedoras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18124','fiesta','Fiestas en honor al Santo Cristo de la Cabrilla','Fiestas patronales tradicionales, comidas vecinales en la plaza y fuegos artificiales de montaña con vistas al mar mediterráneo. Se celebra en Agosto. Pequeña celebración con un precioso marco visual entre el mar y la sierra costera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18126','fiesta','Fiestas de San Isidro Labrador y la Inmaculada Concepción','Feria local vinculada históricamente a su patrimonio termal y sus famosas salinas romanas, con verbenas y actividades tradicionales. Se celebra en Mayo. Fiesta con gran arraigo en la comarca del Temple, atrayendo a mucho público de los pueblos colindantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18127','fiesta','Feria de Maracena en honor a San Joaquín','Macro-feria metropolitana, inmenso recinto ferial de casetas, ferias de mediodía de gran afluencia y conciertos gratuitos de bandas nacionales de primer nivel. Se celebra en Agosto. Por su volumen demográfico, es una de las ferias más populosas y vibrantes del cinturón urbano de Granada capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18128','fiesta','Fiestas de Nuestra Señora de la Purificación','Fiestas patronales tradicionales en el paisaje singular de los "Badlands" y las casas cueva, con procesiones y verbenas. Se celebra en Agosto (traslado estival). Entorno paisajístico espectacular que le da un toque único a sus noches de fiesta de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18132','fiesta','Romería del Santísimo Cristo de Paño de Moclín','Fenómeno masivo de devoción religiosa. Decenas de miles de peregrinos de toda Andalucía suben a pie hasta el castillo medieval para tocar el lienzo del Cristo, al que históricamente se le atribuyen propiedades milagrosas (citado por Lorca en su obra ''Yerma''). Se celebra en Octubre. Declarada de Interés Turístico de Andalucía. Es una de las romerías e hitos religiosos de un solo día más populosos e históricos del sur de España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18133','fiesta','Fiestas de Moros y Cristianos en honor a Santa Ana','Recreación histórica y fiesta patronal. Destaca por la representación teatral de los combates entre los bandos moro y cristiano en la plaza de la iglesia. Se celebra en Julio. Declarada de Interés Turístico de Andalucía por conservar con gran pureza el texto y las indumentarias tradicionales en la costa interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18134','fiesta','Fiestas de San Antón (Monachil Pueblo) y la Virgen de las Nieves (Sierra Nevada)','Romería alpina de alta montaña a más de 3.000 metros de altitud en Sierra Nevada, y fiestas tradicionales de San Antón con su típica olla monachilera. Se celebra en Agosto (Virgen de las Nieves) y Enero (San Antón). La procesión de la Virgen de las Nieves en los picos altos es la más elevada de la península ibérica; un espectáculo visual bellísimo e inigualable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18135','fiesta','Feria de Agosto y Fiestas de San Sebastián','Feria mayor andaluza con desfiles de gigantes y cabezudos, ferias de mediodía en sus monumentales plazas y eventos gastronómicos dedicados a su afamado queso de Montefrío. Se celebra en Agosto. Muy potenciada por su proyección turística internacional tras ser nombrado uno de los pueblos con mejores vistas del mundo por National Geographic; sus fiestas atraen a multitud de viajeros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18136','fiesta','Fiestas en honor a la Virgen de la Cabeza','Fiestas patronales, desfiles de moros y cristianos locales, comidas populares y verbenas. Se celebra en Agosto. Tradición muy consolidada en la comarca de Los Montes con gran vistosidad en sus actos religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18137','fiesta','Fiestas de la Virgen del Rosario','Feria local de casetas, carreras de cintas, comidas populares y competiciones deportivas. Se celebra en Agosto. Ambiente típicamente olivarero con mucha hospitalidad hacia los visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18138','fiesta','Feria de Verano y Fiestas de la Virgen de las Angustias','Feria mayor con casetas en el recinto, verbenas populares, eventos deportivos y degustaciones culinarias de la vega. Se celebra en Agosto. Punto de encuentro lúdico muy dinámico en el eje de la autovía A-92.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18909','fiesta','Fiestas de la Santa Cruz (Moreda) y de la Virgen del Rosario (Laborcillas)','Fiestas patronales de sus dos núcleos de población con procesiones tradicionales y verbenas de verano. Se celebra en Agosto. Fiesta pequeña y familiar enfocada a la convivencia vecinal en la Hoya de Guadix.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18140','fiesta','Feria de Agosto en honor a Nuestra Señora de la Cabeza y Fiestas de la Virgen del Carmen','Gran feria de la Costa Tropical con recinto ferial de grandes dimensiones, corridas de toros, ferias de día en el centro urbano y procesión marítimo-terrestre del Carmen en el puerto. Se celebra en Agosto (Feria) y Julio (Carmen). Es la feria más grande y populosa de todo el litoral granadino; un despliegue masivo de conciertos, tradiciones marineras y ambiente andaluz de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18141','fiesta','Fiestas de la Santa Cruz y San Miguel / Feria del Vino de la Contraviesa','Fiestas patronales con tradicionales trovos alpujarreños (poesía improvisada) y muestra de los vinos locales de alta montaña y el pan de Murtas. Se celebra en Mayo y Septiembre. Mutilo de gran tradición cultural alpujarreña; sus concursos de trovo y las catas de vino atraen a los amantes del folclore más puro de la sierra). Dime si deseas que sigamos con el siguiente bloque de la letra N hasta la Z de Granada (Nigüelas, Nívar, Ogíjares, Orce, Órgiva, Otura, Padul, Pampaneira, Pedro Martínez, Peligros, La Peza, Pinos Genil, Pinos Puente, Píñar, Puebla de Don Fadrique, Pulianas, Purullena, Quéntar, Rubite, Salar, Salobreña, Santa Cruz del Comercio, Santa Fe, Sopórtujar, Sorvilán, Torrenueva Costa, Trevélez, Turón, Ugíjar, Valderrubio, El Valle, Valle del Zalabí, Válor, Vegas del Genil, Vélez de Benaudalla, Ventas de Zafarrayona, Villa de Otura, Villamena, Villanueva de las Torres, Villanueva Mesía, Víznar, Zafarraya, Zagra, Zubia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18143','fiesta','Fiestas del Alero en honor a la Virgen de las Angustias','Fiestas patronales tradicionales del Valle de Lecrín, conciertos de música clásica y bandas, y verbenas. Se celebra en Septiembre. Destaca por la belleza de sus conciertos en los jardines románticos del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18144','fiesta','Fiestas de Santo Cristo de la Salud','Fiestas patronales de montaña, verbenas de verano y rutas gastronómicas. Se celebra en Septiembre. Excelente ambiente vecinal con unas vistas espectaculares de la Vega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18145','fiesta','Festival Nacional de Cante Flamenco de Ogíjares y Fiestas del Cristo de la Expiración','Festival cultural de flamenco de máxima categoría nacional y feria de casetas metropolitana. Se celebra en Septiembre. Su Festival de Cante Flamenco es uno de los más antiguos y respetados de Andalucía; una cita ineludible para los grandes nombres del género.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18146','fiesta','Fiestas de San Antón y la Danza de los Cascaborras','Fiesta etnográfica ancestral. Un personaje pintoresco (el Cascaborra) recorre el pueblo persiguiendo de forma lúdica a los vecinos, acompañado de una danza tradicional con espadas. Se celebra en Enero. Declarada de Interés Turístico de Andalucía por su incalculable valor histórico, ligada a las tradiciones del Altiplano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19021','fiesta','Fiestas del Santísimo Cristo de la Expiración y Feria de Turismo y Artesanía de la Alpujarra (Hecho en la Alpujarra)','Devoción religiosa masiva (con impresionantes tracas y toneladas de pólvora) y macroferia comercial de productos serranos. Se celebra en Marzo/Abril (Cristo) y Semana Santa (Feria). Capital de la Alpujarra; la feria "Hecho en la Alpujarra" atrae a decenas de miles de personas buscando gastronomía, vinos y artesanía tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18150','fiesta','Real Feria de Ganado y Fiestas de Padul / Feria del Agroalimentaria y del Turismo','Feria de muestras comercial centrada en la matanza tradicional, el vino del terreno y los productos de la zona del humedal. Se celebra en Septiembre (Feria Real) y Diciembre (Feria Agroalimentaria). Su feria agroalimentaria de invierno es una de las más exitosas de la provincia para la compra de embutidos y productos artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18151','fiesta','Feria de Artesanía, Turismo y Agricultura Tradicional de la Alpujarra y Fiestas de la Santa Cruz','Muestra turística y cultural en las calles escalonadas del Barranco del Poqueira. Se celebra en Octubre. Declarada de Interés Turístico de Andalucía. Durante el puente de octubre, el pueblo entero se convierte en un zoco artesanal y gastronómico masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18152','fiesta','Fiestas de la Virgen del Rosario','Fiestas patronales del llano, encierros infantiles, verbenas y migas populares. Se celebra en Agosto. Ambiente muy familiar centrado en el reencuentro estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18153','fiesta','Fiestas Populares en honor a San Ildefonso y la Virgen del Rosario','Feria urbana metropolitana, grandes verbenas, conciertos de pop nacional y actividades infantiles. Se celebra en Julio. Una de las ferias veraniegas del cinturón de Granada con mejor infraestructura y seguridad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18154','fiesta','Fiestas Patronales de Nuestra Señora del Rosario y San Marcos (Los Encierros de La Peza)','Encierros taurinos tradicionales por el campo y el casco antiguo, donde la plaza del pueblo se cierra con maderas al estilo medieval. Se celebra en Octubre. Declarada de Interés Turístico de Andalucía. Sus encierros (apodados "el de los carboneros") son célebres en toda la comunidad por su autenticidad y riesgo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18157','fiesta','Fiestas en honor a San Roque','Fiestas tradicionales junto al río Genil, cucañas, verbenas al aire libre y comidas populares. Se celebra en Agosto. Muy concurrida por los habitantes de Granada capital que buscan el frescor de la ribera del río.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18158','fiesta','Feria de San Pascual Bailón y Fiesta de la Alcaparra','Feria mayor tradicional de la Vega con casetas, y eventos de puesta en valor de sus cultivos agrícolas tradicionales. Se celebra en Mayo. Feria histórica de gran peso logístico e influencia comercial en la Vega Baja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18159','fiesta','Fiesta de la Prehistoria y Fiestas de la Virgen de la Caridad','Curiosa recreación etnográfica donde los vecinos y turistas se visten con pieles y disfraces de trogloditas, celebrando talleres y comidas en torno a su famosa Cueva de las Ventanas. Se celebra en Agosto. Su Fiesta de la Prehistoria es única en Andalucía y atrae a una enorme cantidad de turismo familiar y medios de comunicación.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18161','fiesta','Fiestas de San Antonio de Padua y la Fiesta del Vino Mosto','Fiestas patronales y degustación de vinos artesanos de la zona alta de Guadix. Se celebra en Agosto. Pueblo pequeño pero con una gran tradición vitivinícola familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18162','fiesta','Fiestas de la Virgen del Carmen (La Mamola) y San Juan (Polopos)','Procesión marítima en la playa, castillos de fuegos artificiales acuáticos y verbenas costeras. Se celebra en Julio (Carmen). La festividad del Carmen en La Mamola es un punto de encuentro masivo para el turismo de costa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18164','fiesta','Fiesta de las Cascaborras y de la Inmaculada Concepción (Fiestas de los Inocentes)','Celebración de Interés Turístico. La "Hermandad de las Ánimas" y las "Cascaborras" toman el pueblo con trajes tradicionales, música de guitarras, bailes folclóricos rústicos y pintorescas peticiones de aguinaldos. Se celebra en Diciembre. Declarada de Interés Turístico de Andalucía. Es una de las tradiciones navideñas e invernales más ricas, puras y espectaculares del sur de España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18165','fiesta','Fiestas de la Virgen del Rosario','Feria local metropolitana, competiciones deportivas, ferias de mediodía y espectáculos musicales. Se celebra en Agosto. Excelente ambiente festivo muy conectado con la capital provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18167','fiesta','Fiestas de la Virgen del Milagro y Feria de la Cerámica','Fiestas patronales y promoción de su famosa artesanía de cerámica de reflejos metálicos y arcilla de las cuevas. Se celebra en Agosto. Su condición de "pueblo artesano" dota a sus ferias de un gran atractivo para los compradores de arte popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18168','fiesta','Fiestas de Moros y Cristianos en honor a San Sebastián','Recreación histórica y teatral de combates medievales con trajes de época y salvas de pólvora en la sierra. Se celebra en Septiembre (traslado estival). Su representación de Moros y Cristianos destaca por la tremenda implicación actoral de los vecinos en un entorno natural precioso.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18170','fiesta','Fiestas de la Virgen del Rosario','Fiestas tradicionales de la Contraviesa, degustaciones de vino de la costa y verbenas. Se celebra en Agosto. Vistas espectaculares del mar y ambiente rural muy acogedor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18171','fiesta','Feria de Salar y Jornadas de la Villa Romana de Salar','Feria tradicional de verano y festival de recreación histórica romana en torno a sus importantes yacimientos arqueológicos. Se celebra en Agosto (Feria) y Octubre (Jornadas Romanas). Sus jornadas romanas están ganando mucha importancia turística y cultural por la calidad de sus mosaicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18173','fiesta','Fiestas de San Juan y Romería de la Virgen del Rosario','*. Hogueras monumentales en la playa por San Juan y una multitudinaria romería de carrozas engalanadas que termina en la playa. *. Se celebra en Junio (San Juan) y Octubre (Romería). *. La Romería del Rosario está declarada de Interés Turístico de Andalucía; su estampa de carrozas flamencas junto a la orilla del mar es bellísima.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18174','fiesta','Fiestas en honor a la Virgen del Rosario','Fiestas de carácter local, verbenas populares y comidas de convivencia. Se celebra en Agosto. Fiesta pequeña y de ambiente muy hospitalario en la comarca de Alhama.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18175','fiesta','Fiestas de las Capitulaciones de Santa Fe y Fiestas Patronales de San Agustín','Hito histórico-cultural nacional. Se recrea la firma de las Capitulaciones entre los Reyes Católicos y Cristóbal Colón en 1492 con un impresionante mercado medieval, festivales de música y actos institucionales. Feria de agosto tradicional. Se celebra en Abril (Capitulaciones) y Agosto (San Agustín). Declarada Fiesta de Interés Turístico Nacional. Es una de las conmemoraciones históricas más importantes de España, atrayendo a embajadas internacionales y miles de turistas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18176','fiesta','Feria del Embrujo y Fiestas de San Roque','Festival temático dedicado a las brujas, la magia y leyendas locales. El pueblo se adorna con aquelarres, pasacalles terroríficos y duendes, aprovechando su estética de "Pueblo de las Brujas". Se celebra en Agosto. Fenómeno turístico masivo. Su Feria del Embrujo satura por completo la localidad, convirtiéndose en uno de los eventos estivales más virales y visitados de la Alpujarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18177','fiesta','Fiestas de San Cayetano y Fiesta del Vino Mosto','Fiestas de la costa interior con degustación de sus reconocidos vinos y almendras de la Contraviesa. Se celebra en Agosto. Gran tradición vinícola artesanal en un entorno rural costero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18178','fiesta','Fiestas de la Virgen del Rosario','Fiestas patronales tradicionales del interior olivarero, procesión y verbenas. Se celebra en Agosto. Marcado carácter de reunión comunitaria de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18180','fiesta','Fiestas de la Virgen de las Nieves (Romería al Mulhacén) y Feria del Jamón de Trevélez','Romería nocturna de alta montaña (los vecinos suben a pie hasta la cima del Mulhacén a 3.479 metros para ver amanecer con la virgen) y promoción de su jamón curado al aire de la sierra con Denominación de Origen. Se celebra en Agosto (Romería) y ferias gastronómicas en otoño. La Romería al Mulhacén es de Interés Turístico por su dureza y espectacularidad mística; su jamón es un emblema gastronómico mundial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18181','fiesta','Fiestas de San Marcos y la Virgen del Rosario','Fiestas patronales serranas, tradicionales comidas de migas y verbenas populares. Se celebra en Agosto (traslado lúdico). Fiesta pequeña y entrañable en los límites de la Alpujarra Oriental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18182','fiesta','Expo-Alpujarra (Feria de Turismo, Artesanía y Tradiciones) y Fiestas de la Virgen del Martirio','Gran feria ganadera e histórica reconvertida en muestra monumental de la cultura, gastronomía y artesanía de toda la comarca. Se celebra en Octubre (Virgen) y Diciembre (Expo-Alpujarra). Expo-Alpujarra es el gran escaparate comercial de fin de año de la sierra; un punto de encuentro masivo para comprar productos navideños alpujarreños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18914','fiesta','Fiestas de Nuestra Señora de la Asunción y Semana Cultural Lorquiana','Feria local de la Vega y eventos culturales dedicados a Federico García Lorca (allí se inspiró para escribir ''La casa de Bernarda Alba''). Se celebra en Agosto (Feria) y Junio (Cultura). Gran valor cultural por las visitas teatralizadas a los escenarios lorquianos reales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18902','fiesta','Fiesta de los Cítricos (Melegís) y Fiestas de San Cristóbal','Gastronómica (promoción de sus famosos naranjos y limones con degustaciones de remojo costero) y patronal. Se celebra en Abril (Cítricos) y Agosto (Patronales). Su fiesta de los cítricos atrae a muchos gastrónomos al Valle de Lecrín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18907','fiesta','Fiestas de San Antonio (Exfiliana) y de la Virgen de la Cabeza (Alcudia)','Fiestas que unifican las tradiciones de sus tres núcleos, con verbenas y procesiones entre casas cueva. Se celebra en Junio y Agosto. Gran ambiente de hermandad en la comarca accitana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19028','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Alharilla','Recreación histórica monumental. Los vecinos escenifican batallas con un texto del siglo XIX, trajes espectaculares y una enorme cantidad de disparos de pólvora con trabucos antiguos. Se celebra en Septiembre. Declarada de Interés Turístico de Andalucía. Es la fiesta de Moros y Cristianos con más tradición, estruendo y realismo de toda la Alpujarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18911','fiesta','Fiestas de San Isidro (買alcor) y de la Virgen de los Dolores (買urcháiz)','Ferias de la Vega con grandes verbenas metropolitanas, ferias de mediodía y eventos deportivos. Se celebra en Mayo y Agosto. Mucha afluencia por su cercanía e interconexión con la capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18184','fiesta','Fiesta de la Morisma (Moros y Cristianos) y Fiestas de San Antonio de Padua','Recreación histórica peculiar ("La Morisma") donde se rememoran los alzamientos moriscos, combinada con la feria local. Se celebra en Junio. Su representación histórica en el entorno de su famoso Jardín Nazari cuenta con un encanto plástico espectacular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18187','fiesta','Fiestas de San José','Fiestas patronales tradicionales del norte provincial, verbenas y baños en sus históricas aguas termales de Alicún. Se celebra en Agosto (traslado estival). Ambiente íntimo y familiar en un entorno geológico único.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18188','fiesta','Feria de Verano y Fiesta de la Pisa de la Alcaparra','Feria local con casetas y puesta en valor gastronómica de sus productos agrícolas tradicionales de ribera. Se celebra en Agosto. Fiesta muy entrañable con actividades lúdicas junto al río Genil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18189','fiesta','Fiestas en honor a San Blas','Patronal de invierno con reparto de roscos bendecidos, y fiestas recreativas en el Parque de la Alfaguara en verano. Se celebra en Febrero (San Blas) y Agosto (Verano). Gran vinculación con el turismo de naturaleza de la sierra y la memoria histórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18192','fiesta','Feria de Zafarraya y Fiesta del Emigrante','Gran feria del Llano con verbenas multitudinarias, mercados de ganado históricos y degustaciones gastronómicas del campo. Se celebra en Agosto. Es la feria con mayor afluencia y despliegue comercial de toda su comarca agrícola.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18913','fiesta','Fiestas en honor a San Lorenzo','Fiestas patronales, carreras de cintas a caballo, verbenas nocturnas y paella gigante. Se celebra en Agosto. Ambiente muy festivo y veraniego en las inmediaciones del Embalse de Iznájar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18193','fiesta','Fiestas Patronales de San Juan Nepomuceno','Gran feria metropolitana con casetas tradicionales, conciertos de bandas nacionales, ferias de día en sus plazas y eventos ecuestres a los pies de Sierra Nevada. Se celebra en Mayo. Una de las ferias de primavera más populosas y con mayor infraestructura de todo el Cinturón de Granada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18194','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Cabeza (El Drama de Zújar)','Recreación histórica y romería al Cerro Jabalcón. Los vecinos representan "El Drama de Zújar", un texto teatral medieval de gran valor literario, acompañado de una masiva subida al monte. Se celebra en Abril. Declarada de Interés Turístico de Andalucía. La espectacularidad de la representación y la subida de la virgen al majestuoso cerro Jabalcón atraen a miles de fotógrafos y curiosos). Con esto queda completada al 100% la Provincia de Granada de la A a la Z, cerrando este gran bloque que ya puedes añadir a tu documento Word. Dime si pasamos al siguiente bloque del documento para redactar la siguiente provincia de Andalucía en orden alfabético, que corresponde a Huelva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22003','fiesta','Romería de la Reina de los Ángeles (Peña de Arias Montano) y Fiesta del Poleo','Romería serrana monumental y fiesta etnográfica-gastronómica basada en la recolección de plantas aromáticas y convivencia popular. Se celebra en Septiembre (Romería) y Mayo (Poleo). Declarada de Interés Turístico de Andalucía. Su romería en el enclave mágico de la Peña de Arias Montano es una de las citas místicas y paisajísticas más importantes de la Sierra de Aracena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90456','fiesta','Fiestas Patronales de Nuestra Señora de los Remedios y Romería de Aljaraque','Romería tradicional andaluza a caballo y feria urbana con casetas y grandes verbenas. Se celebra en Junio. Una de las romerías más populosas del entorno metropolitano de Huelva capital, con un espectacular paseo de jinetes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90743','fiesta','Romería de San Benito Abad (compartida con El Cerro de Andévalo) y Feria de la Trashumancia','Romería de fuerte arraigo andevaleño y festividad agroganadera tradicional. Se celebra en Abril (Romería) y Diciembre (Trashumancia). Destaca por la conservación de costumbres pastoriles y bailes tradicionales del Andévalo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','fiesta','Cruces de Mayo de Almonaster y Jornadas de Cultura Islámica','Festividad folclórica de piques tradicionales entre las cruces del Llano y la Fuente, y recreación histórica/cultural internacional en su mezquita del siglo X. Se celebra en Mayo (Cruces) y Octubre (Jornadas Islámicas). Tanto sus Cruces de Mayo como sus Jornadas Islámicas están declaradas de Interés Turístico. Atraen a miles de turistas culturales por transformar la villa medieval en un zoco del califato.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22002','fiesta','Romería de El Rocío, la Saca de las Yeguas y la Feria de San Pedro','Romería mariana masiva (la más grande de España), tradición ganadera ancestral en Doñana y feria mayor. Se celebra en Mayo/Junio (El Rocío) y Junio (Saca de las Yeguas). El Rocío es Fiesta de Interés Turístico Internacional; un fenómeno social y religioso que moviliza a más de un millón de peregrinos. La Saca de las Yeguas es un hito etnográfico único con más de 500 años de historia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21067','fiesta','Fiestas Patronales de Santa Ana y Fiesta del Guisante','Fiestas patronales tradicionales y muestra gastronómica local. Se celebra en Julio. Ambiente íntimo serrano enfocado en la naturaleza, el senderismo y la convivencia comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','fiesta','Feria de Agosto y Feria Regional del Jamón y del Cerdo Ibérico','Feria mayor de casetas y macro-muestra gastronómica dedicada al jamón ibérico de bellota de la DOP Jabugo. Se celebra en Agosto (Feria) y Octubre (Feria del Jamón). La Feria del Jamón de Aracena es el evento gastronómico más multitudinario de la Sierra de Huelva, atrayendo a decenas de miles de amantes del producto gourmet y profesionales del sector alimentario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22005','fiesta','Romería de San Mamés y Festival de Diana (Festival de Teatro del la Ciudad Romana de Turóbriga)','Romería campestre y festival cultural de teatro clásico en un yacimiento arqueológico romano real. Se celebra en Mayo (Romería) y Julio/Agosto (Festival). Su festival de teatro clásico en las ruinas de Turóbriga ofrece un marco plástico y patrimonial único en la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22006','fiesta','Semana Santa de Ayamonte y Fiestas de las Angustias','Semana Santa monumental transfronteriza y fiestas patronales con procesión, conciertos y feria comercial. Se celebra en Marzo/Abril (Semana Santa) y Septiembre (Angustias). Su Semana Santa está declarada Fiesta de Interés Turístico Nacional por la altísima calidad de su imaginería y su vinculación cultural con la vecina Portugal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90744','fiesta','Belén Viviente de Beas y Capeas de San Bartolomé','Representación navideña viviente tradicional y festejos taurinos populares con encierros tradicionales en la calle. Se celebra en Diciembre/Enero (Belén) y Agosto (Capeas). El Belén Viviente de Beas es el más antiguo de Andalucía -desde 1970- y está declarado de Interés Turístico; es un hito de las navidades onubenses que atrae a multitudes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90459','fiesta','Cruces de Mayo de Berrocal','Rito etnográfico de rivalidad folclórica entre la Cruz de Arriba y la Cruz de Abajo, con desfiles de bestias engalanadas y cantes de "coplas de la cruz". Se celebra en Mayo. Fiesta de enorme tipismo andevaleño declarada de Interés Turístico por su pureza antropológica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90460','fiesta','Feria de la Vendimia del Condado y Fiestas de la Virgen de las Mercedes','Gran feria vinícola que celebra la recogida de la uva con pisada tradicional, catas populares, casetas y eventos ecuestres. Se celebra en Septiembre. Declarada de Interés Turístico. Es la gran fiesta del vino de la provincia de Huelva, ensalzando las bodegas y caldos de la comarca del Condado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90461','fiesta','Cruces de Mayo de Bonares','Festividad mariana y folclórica única. Cuenta con 12 cruces, cada una custodiada por una calle y sus "mayordomos", culminando en una procesión y bailes tradicionales en la plaza. Se celebra en Mayo. Declaradas de Interés Turístico de Andalucía por la asombrosa uniformidad estética de los altares de sus doce Cruces.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90462','fiesta','Romería de San Sebastián','Romería tradicional en el paraje de la "Cabeza de la Alcolea" con caballos y cantes típicos. Se celebra en Mayo. Fiesta de ambiente puramente andevaleño y muy acogedora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90463','fiesta','Fiestas en honor a la Virgen de la Calera','Fiestas patronales, suelta de vaquillas, verbenas de verano y comida popular en la sierra. Se celebra en Septiembre. Mucho arraigo familiar en el límite fronterizo con la provincia de Badajoz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90464','fiesta','Romería de Nuestra Señora de la Coronada','Romería de gran solera andevaleño, donde destaca el canto de las "Sevillanas Calañesas" y el tradicional traje de galana. Se celebra en Abril. Una de las romerías de mayor identidad folclórica del centro de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47031','fiesta','Fiestas de la Virgen de la Granada y Día de la Villa','Fiestas patronales veraniegas y conmemoración de la independencia municipal. Se celebra en Agosto. Ambiente festivo y obrero ligado a la historia de la Cuenca Minera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90465','fiesta','Fiestas de Santiago Apóstol y Capeas de Campofrío','Fiestas patronales con tradicionales sueltas de vaquillas en su histórica plaza de toros (una de las más antiguas de España, del siglo XVIII). Se celebra en Julio. Muy concurrida por los aficionados al mundo del toro debido al valor monumental de su plaza rústica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90466','fiesta','Fiestas en honor a la Virgen del Campo','Fiestas patronales de verano que aprovechan su famosa "Laguna" (una piscina natural gigante en el centro del pueblo) para actividades lúdicas. Se celebra en Julio. Su espectacular laguna artificial en la plaza del pueblo le da a la fiesta un atractivo veraniego único y muy refrescante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21021','fiesta','Feria de Octubre y Fiestas de la Virgen del Rosario / Feria de El Rompido','Gran feria comercial, ganadera y lúdica, acompañada de la tradicional procesión marinera de la Virgen del Carmen en el núcleo costero de El Rompido. Se celebra en Octubre (Feria Mayor) y Julio (El Rompido). Su Feria de Octubre es una de las muestras industriales y agrícolas con más solera de la costa occidental onubense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21022','fiesta','Fiestas de los Santos de la Piedra (San Ciriaco y San Paula)','Fiesta patronal serrana pequeña con procesiones, comidas colectivas y verbenas al fresco. Se celebra en Agosto. [1] *. Municipio de baja población; la fiesta ofrece un ambiente rural íntimo en el pueblo más alto de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21023','fiesta','Romería de San Benito Abad','Joya folclórica nacional. Es la romería más antigua de la provincia de Huelva. Destaca por el baile de "La Folía", el traje de "Galana" (repleto de joyas ancestrales) y el reparto de "Lanzaos". Se celebra en Mayo. Declarada de Interés Turístico de Andalucía. Tiene un valor antropológico incalculable; conserva ritos e indumentarias medievales intactos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21030','fiesta','Feria de Chucena en honor a la Virgen de la Estrella y Fiesta del Vino','Feria mayor de casetas, paseos de caballos y ensalzamiento de los caldos locales de sus cooperativas. Se celebra en Agosto. Muy ligada a la producción vitivinícola del Condado, con gran ambiente en sus casetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21025','fiesta','Jornadas Culturales Islámicas de Cortegana y Feria de Agosto','Macro-festival medieval e islámico en su castillo fortificado del siglo XIII, con mercados, música y torneos, junto a su feria tradicional. Se celebra en Agosto (Jornadas Medievales). Declaradas de Interés Turístico de Andalucía. Sus jornadas medievales transforman por completo el recinto del castillo, atrayendo a decenas de miles de visitantes de toda España y Portugal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21026','fiesta','Certamen Nacional de Pintura al Aire Libre y Fiestas de la Virgen de los Remedios','Encuentro cultural y pictórico de gran prestigio que reúne a cientos de artistas en las calles, y fiestas locales de verano. Se celebra en Agosto. Su certamen pictórico de un solo día es un referente cultural andaluz que llena el pueblo de arte y visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21027','fiesta','Fiestas de San Pedro','Fiestas vecinales con comidas colectivas en la calle y bailes. Se celebra en Junio. Es el municipio con menos habitantes de toda Andalucía; sus fiestas son una reunión familiar íntima de gran calidez.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21028','fiesta','Fiestas de San Bartolomé Apóstol (La Danza de los Garrotes)','Patronal serrana que destaca por una danza ritual ancestral donde los hombres danzan golpeando bastones o "garrotes" de madera ante el santo. Se celebra en Agosto. Gran valor folclórico por la conservación de sus danzas de espadas y bastones en el extremo norte de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21029','fiesta','Feria de la Gastronomía "Saborea Cumbres Mayores" y Fiestas del Corpus Christi (Danza de los Danzantes)','Macro-feria gastronómica dedicada a los embutidos ibéricos de bellota y rito folclórico de danzas con castañuelas ante el Corpus. Se celebra en Diciembre (Feria Gastronómica) y Junio (Corpus). Su feria gastronómica de diciembre posee la ración de jamón de bellota más grande del mundo y atrae masas turísticas de invierno buscando despensa ibérica). Dime si deseas que continuemos directamente con el siguiente bloque de la letra D a la M de Huelva (Encinasola, Escacena del Campo, Fuenteheridos, Galaroza, Gibraleón, Granado, Higuera de la Sierra, Hinojales, Hinojos, Huelva Capital, Isla Cristina, Jabugo, Lepe, Linares de la Sierra, Lucena del Puerto, Manzanilla, Marines, Minas de Riotinto, Moguer...). ¿Seguimos con el listado para tu Word?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21031','fiesta','Romería de la Virgen de Flores y Fiestas de San Juan (La Danza del Pandero)','Romería fronteriza hispano-lusa y folclore tradicional con cantes y danzas de origen medieval. Se celebra en Abril (Flores) y Junio (San Juan). Destaca la enorme hermandad transfronteriza con Portugal y la pureza etnográfica de la "Danza del Pandero", ejecutada exclusivamente por mujeres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21032','fiesta','Fiestas en honor a la Virgen de la Luna y Fiestas de las Cruces de Mayo','Romería, procesión patronal y piques tradicionales entre las Cruces del pueblo. Se celebra en Agosto (Patrona) y Mayo (Cruces). Gran ambiente de casetas y fe en el Condado de Huelva, con fuerte participación de jinetes a caballo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21033','fiesta','Fiestas de la Virgen de la Hermosura y Fiesta de la Castaña','Patronal serrana y Gastronómica (celebración del fin de la cosecha de castañas con tostadas colectivas). Se celebra en Agosto (Patrona) y Noviembre (Castaña). Ubicado en el corazón verde de la sierra; la fiesta de la castaña es un hito de turismo rural e invernal muy concurrido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21034','fiesta','Fiesta de Los Jarritos y Fiestas del Carmen','Hito etnográfico acuático. Considerada la fiesta del agua más antigua de Andalucía, los vecinos se concentran en la histórica Fuente de los Doce Caños para mojarse unos a otros usando "jarritos" de barro tradicionales. Se celebra en Agosto (Jarritos). Declarada de Interés Turístico de Andalucía. Posee un valor antropológico único ligado al culto y abundancia del agua en la Sierra de Aracena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21035','fiesta','Feria de San Lucas y Fiestas Patronales de San Roque','Macro-feria comercial y ganadera histórica (celebrada desde el año 1323) que incluye la Muestra de Artesanía y la tradicional Feria del Mosto. Se celebra en Octubre. Es una de las ferias más antiguas e importantes de la península; su longevidad e impacto económico provincial la convierten en un hito indispensable del otoño onubense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21037','fiesta','Fiestas de Santa Catalina y Feria de Artesanía de la Raya','Patronal y feria artesanal/comercial transfronteriza en colaboración con los pueblos vecinos del Algarve portugués. Se celebra en Noviembre. Fuerte carácter de unión europea y exhibición de productos tradicionales hispano-lusos junto al Guadiana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21038','fiesta','Cabalgata de Reyes Magos de Higuera de la Sierra y Fiestas del Cristo del Rosario','Espectacular desfile viviente navideño. Es la segunda cabalgata más antigua de España (desde 1918), donde los vecinos escenifican pasajes bíblicos totalmente inmóviles sobre carrozas. Se celebra en Enero (Cabalgata). Declarada Fiesta de Interés Turístico Nacional de Andalucía y de Interés Nacional. Atrae cada 5 de enero a decenas de miles de personas de todo el país por su asombrosa belleza artística y fervor popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21039','fiesta','Fiestas de la Virgen de Tórtola (Danza de los Lanzantes)','Patronal serrana caracterizada por una danza ritual de espadas ejecutada por hombres con vistosas indumentarias ante la virgen. Se celebra en Mayo. Un tesoro del folclore andaluz por la preservación rigurosa de sus mudanzas medievales de origen celta-rebozado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21040','fiesta','Corpus Christi de Hinojos y Feria de la Virgen del Valle','Espectáculo vegetal y religioso. Todo el recorrido procesional amanece transformado en un bosque natural cerrado; las fachadas se cubren de ramas de chopos y el suelo se tapiza con toneladas de romero y juncia. Se celebra en Junio (Corpus). Declarada de Interés Turístico. Es una de las manifestaciones estéticas y litúrgicas más bellas de España, convirtiendo las calles del pueblo a las puertas de Doñana en una selva aromática efímera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21041','fiesta','Fiestas Colombinas y Fiestas Patronales de San Sebastián / Semana Santa de Huelva','Gran macro-feria de verano que conmemora la salida de las carabelas de Cristóbal Colón hacia América con un colosal recinto de casetas junto a la ría, corridas de toros y conciertos masivos. Semana Santa de gran señorío andaluz. Se celebra en Agosto (Colombinas) y Enero (San Sebastián). Las Fiestas Colombinas están declaradas de Interés Turístico de Andalucía y son el buque insignia festivo de la provincia, atrayendo a cientos de miles de visitantes por sus intensas noches de música, gastronomía (chocos) y ferias de día.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21042','fiesta','Carnaval de Isla Cristina y Fiestas del Carmen','Carnaval histórico y masivo (el más importante y antiguo de Huelva, famoso por sus agrupaciones teatrales y el entierro de la sardina) y feria marinera costera con procesión en el mar. Se celebra en Febrero (Carnaval) y Julio (Carmen). Su Carnaval está declarado de Interés Turístico de Andalucía; es un fenómeno sociocultural gigantesco que paraliza la costa y atrae a miles de aficionados a las coplas satíricas de toda España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21043','fiesta','Fiestas de la Santísima Trinidad y el "Cocido Gigante de Jabugo"','Patronal tradicional de verano y Macro-evento gastronómico donde se cocina en una olla colosal un cocido con toneladas de carnes ibéricas, jamón y garbanzos para miles de comensales. Se celebra en Julio. Cuna mundial del jamón ibérico de bellota; su festival culinario del cocido atrae a ríos de turistas gourmet ávidos de degustar sus prestigiosos productos cárnicos de la DOP.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21044','fiesta','Romería de Nuestra Señora de la Bella y Feria de la Virgen de la Cinta','Romería andaluz masiva de trajes flamencos y caballistas en el paraje de El Terrón, y feria de verano. Se celebra en Mayo (Romería). Es una de las romerías más populosas y con mayor despliegue de infraestructuras y caballos de toda Andalucía, reuniendo a más de 150.000 personas en torno a su patrona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21045','fiesta','Fiestas del San Juan Bautista y la Noche de los Candiles','Fiestas tradicionales serranas de verano y un precioso ritual nocturno donde el alumbrado público se apaga por completo y el pueblo se ilumina exclusivamente con miles de candiles de aceite. Se celebra en Junio (San Juan) y Julio (Candiles). La Noche de los Candiles dota al entramado empedrado del pueblo de una magia visual y un encanto estético muy fotografiado en la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21046','fiesta','Feria en honor a San Vicente Mártir y Fiestas de las Cruces de Mayo','Feria de invierno con tradicionales capeas taurinas por las calles del centro, y festividad folclórica de las Cruces. Se celebra en Enero (San Vicente). Peculiar por celebrar una potente feria taurina popular en pleno mes de enero, congregando a muchos aficionados de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21047','fiesta','Real Feria de Manzanilla y Fiesta del Vino','Feria agrícola e histórica con casetas andaluzas tradicionales y promoción de los caldos del Condado. Se celebra en Junio. Gran ambiente de caballos y trajes de flamenca en una feria de gran solera en el interior provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21048','fiesta','Fiesta del Mosto y de la Tostá y Fiestas de Nuestra Señora de Gracia','Gastronómica e invernal (degustación masiva de vino mosto de la sierra acompañado de pan tostado con aceite y asado de cerdo) y patronal. Se celebra en Noviembre (Fiesta del Mosto). Pone en valor la pequeña pero selecta producción vinícola artesanal de la sierra con una gran hospitalidad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21049','fiesta','Fiestas de San Roque y la Virgen del Rosario / Semana de la Ciencia y los Minerales','Feria mayor de tradición minera e industrial, y eventos lúdico-culturales que aprovechan su paisaje marciano único. Se celebra en Agosto. Fuerte carácter identitario ligado a la Cuenca Minera, atrayendo a mucho turismo cultural y de arqueología industrial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21050','fiesta','Feria de Moguer (Feria de San Francisco) y Romería de Montemayor / Semana Santa de Moguer','*. Gran feria andaluza monumental con un ordenado recinto de casetas de madera permanentes, romería campestre multitudinaria y Semana Santa de altísima relevancia. *. Se celebra en Septiembre (Feria) y Mayo (Romería). *. La Romería de Montemayor y su Feria de Septiembre destacan en el marco de la cuna de Juan Ramón Jiménez; sus desfiles hípicos y la belleza de sus eventos son de gran calado andaluz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21051','fiesta','Fiesta del Melocotón y Fiestas de la Virgen de las Virtudes','Gastronómica-agrícola (puesta en valor de sus reputados melocotones de regadío serrano con concursos culinarios y ponches populares) y patronal. Se celebra en Agosto. Muy concurrida en el valle del Múrtiga por la exquisitez de sus degustaciones frutales gratuitas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21052','fiesta','Fiestas de San Bartolomé y Día de la Villa','Feria mayor con conciertos de rock, exposiciones pictóricas al aire libre (tierra de artistas) y verbenas. Se celebra en Agosto. Feria de gran dinamismo cultural y social que aglutina a toda la comarca minera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21053','fiesta','Festival Internacional de Danza y Teatro del Castillo de Niebla y Feria de Tosantos / Fiestas del Pino','Prestigioso festival de artes escénicas de nivel europeo en su recinto amurallado medieval, y feria franca histórica medieval con mercados tradicionales. Se celebra en Julio/Agosto (Festival) y Noviembre (Feria de Tosantos). Su Festival de Teatro en el Castillo es un referente cultural absoluto del sur de España. Su Feria de Tosantos (desde el siglo XIII) recrea un mercado medieval masivo que transporta al visitante al medievo). Dime si deseas que continuemos directamente con el siguiente bloque de la letra P a la Z de Huelva (Palma del Condado, Palos de la Frontera, Paterna del Campo, Paymogo, Puebla de Guzmán, Puerto Moral, Rociana del Condado, Rosal de la Frontera, San Bartolomé de la Torre, San Juan del Puerto, San Silvestre de Guzmán, Sanlúcar de Guadiana, Santa Bárbara de Casa, Santa Olalla del Cala, Trigueros, Valdelarco, Valverde del Camino, Villablanca, Villalba del Alcor, Villanueva de las Cruces, Villanueva de los Castillejos, Villarrasa, Zalamea la Real, Zufre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21054','fiesta','Real Feria de la Palma y Fiesta de la Vendimia del Condado','Feria mayor de casetas andaluzas de gran solera y festividad enológica monumental que incluye la protocolaria "Noche del Vino" con la pisada de la uva de la comarca. Se celebra en Septiembre. Declarada de Interés Turístico de Andalucía. Es una de las ferias vinícolas más antiguas y elegantes de la comunidad, combinando tradición bodeguera y aristocracia a caballo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','fiesta','Feria Medieval del Descubrimiento y Fiestas de la Virgen de los Milagros','Recreación histórica masiva que conmemora la salida de las Carabelas hacia América con torneos medievales, mercado artesanal de época, y romería tradicional. Se celebra en Marzo (Feria Medieval) y Agosto (Virgen). Declarada de Interés Turístico de Andalucía. Su Feria Medieval es un acontecimiento de primer nivel nacional por su rigor histórico, transformando todo el entorno histórico de los lugares colombinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21056','fiesta','Fiestas de las Cruces de Mayo y Romería de San Isidro Labrador','"Piques" tradicionales y coloridos entre la Cruz de la Victoria y la Cruz de la Calle Sevilla, con desfiles y carretas tradicionales. Se celebra en Mayo. Espectacular despliegue de fuegos artificiales, caballos engalanados y fervor popular en el Condado norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21057','fiesta','Feria Gastronómica del Gurumelo y Fiestas del Rosario','Feria micológica y gastronómica centrada en el "gurumelo" (Amanita ponderosa), la seta más codiciada del Andévalo onubense. Se celebra en Marzo (Feria del Gurumelo). Referente micológico absoluto en Andalucía; atrae a miles de aficionados a la gastronomía del bosque para degustar este hongo gourmet.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21058','fiesta','Romería de la Virgen de la Peña y Feria de Pesca de Interior y Acuicultura','Romería ancestral andevaleña que destaca por el desfile de jinetes, la "Danza de las Espadas" de origen medieval y los trajes bordados en oro. Se celebra en Abril. Declarada de Interés Turístico de Andalucía. Tiene un valor antropológico incalculable por la perfecta conservación de sus indumentarias y la rigurosa coreografía de su danza guerrera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21059','fiesta','Feria del Ganado de Puerto Moral (Feria de Alcalá) y Fiesta de la Alcaldesa','Feria de ganado de carácter histórico que mantiene los tratos de compraventa tradicionales combinados con eventos lúdicos serranos. Se celebra en Abril. Conserva un encanto etnográfico único en un entorno natural rodeado de dehesas a las puertas del embalse de Aracena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21061','fiesta','Fiestas de las Cruces de Mayo y Feria de la Virgen del Socorro','Celebración folclórica masiva en la que participan sus cinco cruces con una espectacular procesión y desfiles de carretas flamencas. Se celebra en Mayo (Cruces) y Septiembre (Feria). Declarada de Interés Turístico de Andalucía por la singular belleza barroca de las capillas de las cruces y el arraigo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21062','fiesta','Romería de San Isidro Labrador y Feria de la Caza y la Naturaleza','Romería fronteriza hispano-lusa en un entorno de dehesas y muestra monográfica dedicada al sector cinegético. Se celebra en Mayo. Punto de encuentro clave para los aficionados a la caza y el turismo activo en la raya con Portugal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21063','fiesta','Fiestas en honor a San Bartolomé (Danza de las Espadas)','Patronal andevaleña caracterizada por la ejecución de una danza de espadas de origen ancestral frente al paso del santo patrón. Se celebra en Agosto. Gran valor folclórico por la transmisión ininterrumpida de sus mudanzas medievales entre generaciones de vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21064','fiesta','Fiestas de San Juan Bautista (Capeas de San Juan)','Tradicionales capeas taurinas populares con encierros de reses bravas por las calles del pueblo y verbenas multitudinarias. Se celebra en Junio. Son de los festejos taurinos populares más famosos de la provincia de Huelva, atrayendo a miles de jóvenes corredores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21066','fiesta','Feria Cinegética y de Productos Naturales del Andévalo y Fiestas de San Silvestre','Muestra comercial dedicada a la caza, la artesanía y la gastronomía del Andévalo, y fiesta local. Se celebra en Septiembre (Feria Cinegética). Gran escaparate promocional de los recursos medioambientales y económicos del Bajo Guadiana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21065','fiesta','Fiestas de la Virgen de la Rábida y Festival de Música Transfronterizo','Fiestas de la raya con procesión fluvial compartida con la vecina villa portuguesa de Alcoutim, y eventos náuticos en el río. Se celebra en Abril. Pintoresca estampa de barcos engalanados cruzando el río Guadiana, uniendo las tradiciones de ambos países.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21068','fiesta','Romería de San Sebastián y Fiestas del Emigrante','Romería tradicional andevaleña con caballistas en el paraje de la ermita y feria de verano. Se celebra en Mayo. Ambiente campero y vecinal de gran hospitalidad en las dehesas del norte de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21069','fiesta','Feria de Agosto y Romería de la Virgen de Santa Eulalia','Feria mayor de casetas andaluzas junto a su histórico castillo y masiva romería al paraje natural del río Cala. Se celebra en Agosto (Feria) y Mayo (Romería). Eje neurálgico de diversión en la Ruta de la Plata, conectando con Extremadura y Sevilla capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21070','fiesta','Fiestas de San Antonio Abad (Las Tiradas de Trigueros)','Hito etnográfico único en España. El santo procesiona durante más de 30 horas ininterrumpidas mientras los vecinos "tiran" desde los balcones de sus casas miles de panes, embutidos, jamones y quesos que la multitud recoge en el suelo. Se celebra en Enero. Declarada de Interés Turístico de Andalucía. Es una de las fiestas invernales más espectaculares, multitudinarias e impactantes de la península por el volumen de alimentos que se arrojan de forma gratuita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21071','fiesta','Fiestas en honor a la Virgen del Rosario','Fiestas patronales serranas de ambiente tradicional, orquestas al aire libre y comidas populares. Se celebra en Agosto. Pueblo pequeño de espectacular conjunto histórico; la fiesta mantiene una atmósfera íntima y muy acogedora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21072','fiesta','Feria de Agosto de Valverde y Feria de la Artesanía y el Calzado','Gran feria andaluza con casetas, potentes espectáculos ecuestres y corridas de toros, combinada con la promoción de su reputado calzado de cuero artesanal (botos camperos). Se celebra en Agosto. Una de las ferias de verano de mayor envergadura del interior provincial, uniendo industria artesana y ambiente lúdico de casetas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21073','fiesta','Festival Internacional de Danzas de Villablanca y Feria de la Virgen de la Blanca (Danza de los Pastores)','Macro-festival folclórico que reúne a compañías de danza de los cinco continentes, y danza ritual local de origen pastoril con siglos de historia frente a la patrona. Se celebra en Agosto. Declarado de Interés Turístico de Andalucía. Su festival internacional es un escaparate cultural de primer nivel que llena la costa de ritmos de todo el planeta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21074','fiesta','Fiestas de Santa Águeda y Fiestas de las Cruces de Mayo','Fiestas patronales de invierno y celebración folclórica de sus tradicionales Cruces de Mayo. Se celebra en Febrero (Santa Águeda) y Mayo (Cruces). Mucha solera en sus procesiones de carretas flamencas por el llano del Condado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21075','fiesta','Fiestas de San Sebastián (Danza de las Espadas)','Fiesta patronal andevaleña que mantiene el rito folclórico de una antigua y espectacular danza de espadas ejecutada por los jóvenes de la localidad. *. Se celebra en Enero. *. Excelente muestra antropológica de las tradiciones guerreras medievales que perviven en el interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21076','fiesta','Feria Agroganadera del Andévalo y Fiestas de la Inmaculada Concepción','Muestra comercial, artesana y ganadera de referencia comarcal centrada en el cerdo ibérico y el queso artesanal, y feria local. Se celebra en Diciembre (Feria Agroganadera). Gran poder de convocatoria en el Andévalo occidental para la compra de despensa navideña tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21077','fiesta','Fiestas de las Cruces de Mayo de Villarrasa y Feria de Nuestra Señora de los Remedios','"Piques" tradicionales entre la Cruz del Campo y la Cruz de la Arriba, con espectaculares entradas de toros y carretas flamencas. Se celebra en Mayo (Cruces) y Agosto (Feria). Una festividad de las cruces muy pasional que moviliza por completo a la comunidad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21078','fiesta','Feria de Septiembre de Zalamea y Semana Santa (Los Penitentes de Zalamea)','Feria de ganado histórica (desde el siglo XIV) con paseos de caballos, y Semana Santa singular con desfiles de flagelantes descalzos. Se celebra en Septiembre (Feria) y Marzo/Abril (Semana Santa). Su feria de septiembre conserva una gran solera ganadera e hípica en la cuenca minera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21079','fiesta','Fiestas de la Virgen del Puerto','Romería, tradicionales carreras de cintas a caballo y verbenas nocturnas en su monumental Paseo de los Alcaldes. Se celebra en Septiembre. Su espectacular casco histórico colgado sobre el pantano ofrece un marco visual bellísimo para sus desfiles de jinetes). Con esto queda completada al 100% la Provincia de Huelva de la A a la Z, cerrando este gran bloque que ya puedes añadir a tu documento Word. Dime si pasamos al siguiente bloque del documento para redactar la siguiente provincia de Andalucía en orden alfabético, que corresponde a Jaén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24001','fiesta','Fiestas de San Francisco de Paula','Patronal, religiosa, con la tradicional procesión del santo por las calles empinadas de Sierra Mágina y lanzamiento de cohetes. Se celebra en Mayo. Fiesta de carácter local y vecinal enfocada en la convivencia y reencuentro familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','fiesta','Feria de San Mateo y Fiestas de la Virgen de las Mercedes / Etnosur','Feria mayor de casetas, y el prestigioso festival de música de raíz "Etnosur" (Encuentros Étnicos de la Sierra Sur) que incluye talleres, artesanía y circo. Se celebra en Septiembre (San Mateo) y Julio (Etnosur). El festival Etnosur está declarado de Interés Turístico de Andalucía, siendo un hito cultural y musical alternativo de relevancia nacional e internacional que atrae a miles de jóvenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','fiesta','Fiestas Calatravas de Alcaudete y Feria Real','Espectacular festival de recreación histórica donde el pueblo retrocede a la Edad Media bajo el asedio del Castillo, con torneos de caballeros y mercados de época. Se celebra en Julio (Fiestas Calatravas) y Septiembre (Feria). Las Fiestas Calatravas son de los mercados medievales y de recreación histórica más consolidados y vistosos del sur de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','fiesta','Fiestas en honor a San Miguel Arcángel','Fiestas patronales tradicionales, bailes populares y comidas colectivas en el norte provincial. Se celebra en Septiembre. Ambiente serrano idílico, muy cercano al paraje natural de la Cascada de la Cimbarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','fiesta','Romería de la Virgen de la Cabeza y Feria de Septiembre','Romería mariana monumental en pleno corazón del Parque Natural de la Sierra de Andújar, congregando a miles de cofradías de toda España. Se celebra en Abril (Romería) y Septiembre (Feria). Declarada Fiesta de Interés Turístico Nacional. Es la segunda romería más antigua y populosa de España tras El Rocío, reuniendo a más de medio millón de peregrinos en el Cerro del Cabezo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','fiesta','Fiestas de San Bonoso y San Maximiano (Fiestas de los Santos)','Patronal histórica y religiosa que incluye la tradicional "Quema de la Falla" local y las procesiones solemnes de los mártires. Se celebra en Agosto. Gran arraigo etnográfico en la comarca de la Campiña debido a sus peculiares ritos medievales de pólvora y fuego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24007','fiesta','Fiestas Patronales de San Roque y la Feria de San Roque','Fiestas mayores tradicionales con verbenas de verano, encierros infantiles y pasacalles. Se celebra en Agosto. Conectada fuertemente con la artesanía de su alfarería tradicional e identidad agraria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24008','fiesta','Fiestas de San Antón','Tradición invernal donde destaca el "Pelotero", un personaje satírico que recorre las calles fustigando con un látigo de tiras de cuero, compartiendo panes bendecidos. Se celebra en Enero. Posee un singular valor folclórico y de leyenda como parte de las Nuevas Poblaciones de Carlos III.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24010','fiesta','Semana Santa de Baeza y Feria en honor a la Virgen del Alcázar','Semana Santa monumental renacentista y feria mayor con casetas andaluzas de gran elegancia y paseos hípicos. Se celebra en Marzo/Abril (Semana Santa) y Agosto (Feria). Su Semana Santa está declarada de Interés Turístico Internacional; un despliegue de tallas barrocas y cofradías que desfilan por un conjunto urbano Patrimonio de la Humanidad incomparable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24011','fiesta','Fiestas Conmemorativas de la Batalla de Bailén','Recreación histórica y militar internacional. Se rememora la célebre batalla de 1808 contra las tropas napoleónicas con soldados de época, salvas de fusilería, desfiles y campamentos militares. Se celebra en Julio. Declarada Fiesta de Interés Turístico de Andalucía por su enorme rigor y espectacularidad, atrayendo a asociaciones de recreación de toda Europa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','fiesta','Fiestas en honor a Jesús del Llano y de la Virgen de la Encina','Fiestas patronales, verbenas de noche y actividades lúdicas bajo la impresionante estampa de su fortaleza califal (el castillo de Burgalimar). Se celebra en Mayo. Su espectacular patrimonio dota a las noches de fiesta de un gran atractivo para el turismo de interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','fiesta','Fiestas de San Marcos (Toros de San Marcos)','Espectáculo taurino popular masivo. Los toros son engalanados con preciosas colchas bordadas a mano y cascabeles ("toros ensogaos") y corren guiados por peñas y miles de jóvenes. Se celebra en Abril. Declarada Fiesta de Interés Turístico Nacional de Andalucía y de Interés Andaluz. Es una de las tradiciones taurinas de calle más famosas y singulares del país, congregando a decenas de miles de aficionados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','fiesta','Fiestas Patronales del Santo Cristo de la Vera Cruz','Feria local con casetas tradicionales, ferias de mediodía y orquestas nocturnas. Se celebra en Julio. Gran ambiente vecinal con fuerte tradición olivarera y hospitalidad hacia la comarca de La Loma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','fiesta','Fiestas de la Virgen de la Paz','Fiestas patronales tradicionales en el marco montañoso de Sierra Mágina. Se celebra en Agosto (traslado vacacional). Conocido por el fenómeno mediático de sus "Caras de Bélmez"; la fiesta es eminentemente familiar y de retorno estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24016','fiesta','Fiestas Patronales de San Gines de Arlés','Tradición serrana de la Sierra de Segura, con los típicos encierros de vaquillas y reses bravas por las calles, acompañados de verbenas. Se celebra en Agosto. Mucha devoción juvenil en torno a los festejos taurinos tradicionales de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23017','fiesta','Fiestas del Santo Cristo de Burgos','Peregrinación y fiesta de gran devoción religiosa barroca, desfiles de carrozas y verbenas. Se celebra en Agosto. Atrae a miles de fieles de las provincias vecinas por la enorme y legendaria historia milagrosa de su lienzo sagrado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','fiesta','Fiestas en honor a el Señor del Mármol','Procesión del santo patrón, comidas populares colectivas en la plaza y verbenas de verano. Se celebra en Agosto. Tradición con siglos de historia ligada a los olivares montañosos de Mágina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','fiesta','Fiestas de Moros y Cristianos en honor a la Virgen de la Cabeza','Recreación histórica y fiesta patronal. Se escenifican encarnizados combates verbales y con trabucos entre ambos bandos en el paraje del castillo. Se celebra en Agosto. Destaca por la belleza de sus textos medievales y la rigurosa vestimenta de sus compañías de soldados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','fiesta','Fiestas de la Virgen de los Remedios','Feria local de casetas, procesiones tradicionales de la patrona y actividades lúdicas junto a su emblemático palacio renacentista. Se celebra en Agosto. Fiesta participativa con una comunidad vecinal muy unida en el corazón olivarero de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23901','fiesta','Fiestas de la Virgen del Rosario (Cárchel) y San Antón (Carchelejo)','Tradición serrana, hogueras de invierno y verbenas estivales compartidas entre ambos núcleos de población. Se celebra en Agosto. Excelente ambiente de hermandad en los valles de Sierra Mágina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24024','fiesta','Feria de la Fundación de las Nuevas Poblaciones y Fiestas de San Juan de la Cruz','Gran conmemoración ilustrada e histórica institucional que celebra los planos fundacionales del siglo XVIII, combinada con su feria de atracciones. Se celebra en Mayo (Fundación) y Noviembre (San Juan). Capital de las Nuevas Poblaciones de Sierra Morena; sus desfiles coloniales evocan su origen urbanístico ilustrado único en el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23025','fiesta','Fiestas de la Virgen de Consolación (Encierros de Castellar)','Encierros taurinos de reses por el casco antiguo, de gran riesgo y valentía, acompañados de migas y peñas festivas. Se celebra en Agosto. Fuerte poder de convocatoria taurina en la comarca del Condado norte de Jaén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','fiesta','Fiesta de la Cereza y Feria de San Roque','Macro-muestra gastronómica y agrícola dedicada a ensalzar su rica cosecha de cerezas con concursos de postres, licores, degustaciones populares y verbenas. Se celebra en Junio (Fiesta de la Cereza). Convertida en una de las citas culinarias y agrícolas veraniegas más famosas y visitadas de toda la geografía jiennense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','fiesta','BluesCazorla (Festival Internacional de Blues) y Feria del Cristo del Consuelo','Hito musical internacional (el festival de Blues más premiado y respetado de España con conciertos en plazas medievales y toros), y feria tradicional. Se celebra en Julio (BluesCazorla) y Septiembre (Feria). BluesCazorla transforma por completo el pueblo, atrayendo a decenas de miles de melómanos de todo el planeta hacia el Parque Natural). Dime si deseas que continuemos directamente con el siguiente bloque de la letra C hasta la J de Jaén (Chiclana de Segura, Chilluévar, Escañuela, Espeluy, Frailes, Fuensanta de Martos, Fuerte del Rey, Génave, Guardia de Jaén, Higuera de Calatrava, Hinojares, Hornos, Huelma, Huesa, Ibros, Iznatoraf, Jabalquinto, Jaén Capital, Jamilena, Jimena, Jódar...). ¿Seguimos con la lista para que vayas copiando en tu Word?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23029','fiesta','Fiestas Patronales de San Nazario y la Virgen de Nazaret / Encierros de Reses Bravas','Patronal serrana con encierros tradicionales de vaquillas por su escarpado casco urbano medieval y verbenas nocturnas. Se celebra en Septiembre. Espectacular marco visual debido a su ubicación en un risco; las fiestas congregan a toda la comarca de El Condado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','fiesta','Fiestas Patronales en honor a la Virgen de la Paz','Fiestas tradicionales con encierros de vaquillas, actividades infantiles y ferias de mediodía en las plazas. Se celebra en Septiembre. Gran ambiente vecinal y juvenil a las puertas del Parque Natural de Cazorla, Segura y Las Villas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23031','fiesta','Fiestas del Santo Cristo de la Vera Cruz y el festival "Vincularte"','Feria local de casetas y muestra cultural/ artística al aire libre. Se celebra en Septiembre. Fiesta eminentemente familiar en la Campiña de Jaén con gran hospitalidad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24035','fiesta','Fiestas Patronales de San Gregorio Nacianceno','Fiestas patronales tradicionales, procesión solemne, competiciones deportivas y bailes populares. Se celebra en Mayo. Municipio pequeño de baja población; la fiesta ofrece una atmósfera rural e íntima junto al río Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23033','fiesta','Jornadas Literarias Internacionales y Fiesta de la Vinculación / Feria de Agosto','Encuentro cultural y literario de gran prestigio inspirado en la figura del escritor Michael Jacobs, combinada con ferias tradicionales de verano. Se celebra en Junio (Jornadas) y Agosto (Feria). Su proyección cultural atrae cada año a escritores, periodistas e intelectuales de toda Europa a la Sierra Sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23034','fiesta','Feria del Olivar y Fiesta de la Virgen de la Fuensanta','Feria agrícola y comercial dedicada a los sectores del olivar y el aceite de oliva, combinada con casetas y verbenas. Se celebra en Agosto. Mucha animación vecinal en torno a las raíces olivareras de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23035','fiesta','Fiestas Patronales de la Virgen del Rosario','Feria de verano con desfiles de carrozas, ferias de mediodía en el centro del pueblo y orquestas por la noche. Se celebra en Agosto. Muy concurrida por su gran cercanía a Jaén capital, atrayendo a numeroso público joven.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23037','fiesta','Fiestas de San Marcos y el festival de Cine Rural de Génave','Tradición serrana de "toros ensogaos" guiados con cuerdas, y certamen cultural especializado en cortometrajes y temática rural. Se celebra en Abril (San Marcos) y Septiembre (Cine). Su pionera producción de aceite de oliva ecológico y su festival cinematográfico le otorgan un gran encanto cultural comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23038','fiesta','Fiestas de San Sebastián y la Pastira / Feria de San Pedro','Fiestas patronales tradicionales, verbenas multitudinarias y actos culturales junto a su monumental castillo medieval. Se celebra en Agosto. El crecimiento demográfico de sus urbanizaciones residenciales ha convertido su feria de verano en una de las más concurridas del entorno metropolitano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23041','fiesta','Fiestas Patronales de San Roque','Fiestas tradicionales de la campiña, carreras de cintas, comidas populares y orquestas de noche. Se celebra en Agosto. Carácter acogedor y ambiente muy familiar en los límites con la provincia de Córdoba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23042','fiesta','Fiestas en honor a San Marcos y la Virgen del Campo','Fiestas patronales tradicionales con procesión por la vega del río Turrilla y verbenas populares. Se celebra en Abril y Agosto. Es el municipio más pequeño de la provincia; sus fiestas conservan una atmósfera rural e íntima de gran calidez.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','fiesta','Fiestas Patronales de San Lorenzo (Encierros de Hornos)','Tradicionales encierros de vacas bravas por las estrechas calles de su casco histórico fortificado y verbenas populares. Se celebra en Agosto. La espectacular estampa de las reses corriendo bajo su castillo medieval y con vistas al embalse de El Tranco atrae a muchísimo turismo de interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','fiesta','ExpoHuelma (Feria de Muestras del Parque Natural de Sierra Mágina) y Feria de Agosto','Macro-feria comercial, ganadera y de maquinaria agrícola de referencia andaluza, combinada con un gran despliegue de casetas. Se celebra en Agosto. ExpoHuelma es uno de los grandes motores agroganaderos y turísticos del sur de Jaén, atrayendo a miles de profesionales y visitantes de toda la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23045','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Fiestas tradicionales con suelta de vaquillas, ferias de mediodía y concursos de trunco. Se celebra en Octubre. Fiesta muy participativa que marca el preludio de la campaña de recolección de aceituna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23046','fiesta','Fiestas del Remedio (Fiestas de la Virgen del Remedio)','Fiestas patronales de gran fervor religioso con procesiones de la patrona, castillos de fuegos artificiales y verbenas de verano. Se celebra en Mayo. Gran ambiente de hermandad en la comarca de La Loma, con una comunidad vecinal muy implicada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23048','fiesta','Fiestas del Santísimo Cristo de la Vera Cruz (Encierros de Iznatoraf)','Fiestas patronales monumentales con tradicionales y peligrosos encierros de reses bravas por su casco antiguo de origen morisco. Se celebra en Septiembre. La fisonomía de su villa medieval, con calles laberínticas repletas de flores, dota a los encierros taurinos de una espectacularidad estética única.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23049','fiesta','Fiestas en honor a Nuestro Padre Jesús Nazareno','Fiestas patronales, desfiles de gigantes y cabezudos, verbenas populares y paella gigante para el pueblo. Se celebra en Julio. Mucho arraigo vecinal con actividades muy enfocadas en la convivencia de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','fiesta','Feria de San Lucas, Fiestas de San Antón (Carrera Urbana Internacional y Lumbres de San Antón) y Semana Santa de Jaén','Hito atlético y etnográfico masivo (las lumbres en los barrios quemando trastos viejos con melenchones tradicionales y la prestigiosa carrera internacional de atletismo de noche con antorchas), la última gran feria andaluza del año (San Lucas) y Semana Santa de gran señorío barroco. Se celebra en Enero (San Antón), Octubre (San Lucas) y Marzo/Abril (Semana Santa). La Fiesta de San Antón está declarada de Interés Turístico Nacional por su impacto internacional. La Feria de San Lucas es célebres por cerrar la temporada de ferias del sur de España con una masiva feria de casetas y corridas de toros de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23051','fiesta','Fiestas de Nuestro Padre Jesús Nazareno','Fiestas patronales de inmenso fervor religioso, procesiones solemnes que congregan a miles de personas, tracas de pólvora y verbenas. Se celebra en Agosto. La devoción al Nazareno de Jamilena trasciende el ámbito local, atrayendo a fieles de toda la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23052','fiesta','Fiestas Patronales de la Virgen de los Remedios','Fiestas tradicionales, procesión de la patrona entre los olivares de Mágina, competiciones deportivas y bailes. Se celebra en Septiembre. Pone en valor su rico entorno natural y su famosa producción de higos secos artesanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','fiesta','Real Feria de Jódar y Fiestas del Santo Cristo de la Misericordia','La feria más antigua de la provincia (concedida por Alfonso X el Sabio en el siglo XIII), con un gran recinto de casetas, conciertos y corridas de toros. Se celebra en Septiembre. Es la feria de septiembre con mayor empaque e infraestructura de la comarca de Sierra Mágina norte, destacando por su solera e historia). Dime si deseas que continuemos directamente con el siguiente bloque de la letra L hasta la P de Jaén (Lahiguera, Linares, Lopera, Lupión, Mancha Real, Marmolejo, Martos, Mengíbar, Navas de San Juan, Noalejo, Orcera, Peal de Becerro, Pegalajar, Porcuna, Pozo Alcón, Puente de Génave, La Puerta de Segura.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23040','fiesta','Feria en honor a la Virgen de la Consolación y San Juan Bautista','Feria tradicional de verano, carreras de cintas en moto y verbenas. Se celebra en Agosto. Fiesta local de ambiente muy familiar en la Campiña de Jaén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','fiesta','Real Feria de San Agustín y Semana Santa de Linares','Macro-feria andaluza (famosa por su gran feria taurina y conciertos) y Semana Santa multitudinaria con solemnes bandas de cornetas y tambores de renombre nacional. Se celebra en Agosto (Feria) y Marzo/Abril (Semana Santa). Declaradas de Interés Turístico Nacional de Andalucía. La feria de San Agustín goza de un empaque señorial único y la Semana Santa atrae a miles de turistas por el sonido de sus célebres agrupaciones musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','fiesta','Fiestas Patronales de San Roque y los Santos Mártires, y Fiesta de la Candelaria','Patronal con encierros infantiles, verbenas junto al castillo medieval, y tradicionales hogueras de invierno. Se celebra en Agosto. Mucha participación local y comarcal en torno a su rico patrimonio histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23057','fiesta','Fiestas en honor a la Virgen del Lorite','Fiestas patronales tradicionales, procesiones devocionales y bailes populares. Se celebra en Agosto. Celebración pequeña orientada al retorno de emigrantes en época estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23058','fiesta','Feria del Rosario y Fiestas de San José (Las Fallas de Mancha Real)','Feria mayor de otoño con casetas, y quema de una falla gigante (única localidad andaluza que mantiene este rito tradicional valenciano). Se celebra en Octubre (Feria) y Marzo (Fallas). Las Fallas de Mancha Real atraen a miles de curiosos de toda la comunidad por la singularidad de quemar el monumento fallero en el sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','fiesta','Fiestas de la Virgen de la Paz, Feria de Agosto y Fiesta del Agua','Feria tradicional andaluza de casetas y eventos que aprovechan su histórica vinculación con su famoso Balneario de aguas medicinales. Se celebra en Agosto. Excelente ambiente lúdico a orillas del Guadalquivir que atrae mucho turismo termal e interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','fiesta','Fiesta de la Aceituna de Martos y Feria de San Bartolomé','Hito gastronómico-agrícola monumental donde se conmemora oficialmente el inicio de la campaña de recogida con el reparto gratuito de miles de "hoyos" marteños (pan, aceite virgen extra, aceitunas y bacalao). Se celebra en Diciembre (Aceituna) y Agosto (Feria). Declarada de Interés Turístico. Al ser la cuna mundial de la producción de aceite de oliva, su Fiesta de la Aceituna es un acontecimiento institucional y turístico de primer orden.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23061','fiesta','Fiestas en honor a Santa María Magdalena y Feria de Mengíbar','Feria mayor de casetas con conciertos, actividades de recreación romana (Iliturgi) y verbenas populares. Se celebra en Julio. Su gran dinamismo demográfico e industrial impulsa una feria muy populosa en la vega jiennense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23063','fiesta','Romería de la Virgen de la Estrella y Fiestas de San Juan Bautista (Encierros de Navas)','Romería multitudinaria andaluza y tradicionales encierros diarios de reses bravas por las calles del pueblo que duran una semana. Se celebra en Mayo (Romería) y Junio (San Juan). La Romería está declarada de Interés Turístico de Andalucía. Sus encierros de San Juan son de los más famosos de la comarca del Condado por la bravura de sus reses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23064','fiesta','Fiestas de la Virgen de la Mónica','Fiestas patronales, desfiles de carrozas, ferias de mediodía y verbenas populares. Se celebra en Agosto. Punto de encuentro lúdico muy animado en el límite geográfico con la provincia de Granada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','fiesta','Fiestas Patronales de Nuestra Señora de la Asunción (Encierros de Orcera) y Fiesta del Chiringuito','Tradición serrana profunda con los peligrosos e históricos encierros de toros ensogados por las empinadas calles montañosas. Se celebra en Agosto. Sus encierros taurinos en plena Sierra de Segura atraen a miles de aficionados por el entorno natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23066','fiesta','Fiestas en honor a Nuestra Señora de la Asunción y Fiestas Íberas de Peal','Feria local de casetas andaluzas y jornadas culturales de recreación histórica basadas en su rico patrimonio arqueológico íbero. Se celebra en Agosto. Gran valor cultural debido a la original puesta en valor de sus yacimientos de las tumbas de Toya y Hornos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','fiesta','Fiestas Patronales de la Virgen de las Nieves y Fiestas de San Gregorio (Fiesta del Líquido)','Fiestas vinculadas al agua y su famosa "Charca" (un inmenso embalse en el centro urbano) con procesiones y verbenas. Se celebra en Agosto (Virgen) y Mayo (San Gregorio). El entorno de la Charca dota a la feria de mediodía de una frescura y un encanto estético único en Sierra Mágina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','fiesta','Romería de la Virgen de Alharilla y Feria Real de San Lorenzo','Romería multitudinaria y señorial, paseo de jinetes a caballo y carrozas engalanadas, y feria histórica de ganado del siglo XIII. Se celebra en Mayo (Romería) y Agosto (Feria). La Romería de Alharilla está declarada de Interés Turístico de Andalucía; es la más populosa e importante de toda la Campiña occidental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23070','fiesta','Feria y Fiestas en honor a Santa Ana y Fiesta de los Hornazos','Feria mayor tradicional y meriendas populares campestres de pan y huevo. Se celebra en Julio. Fuerte afluencia turística estival debido a su cercanía al embalse de La Bolera y Cazorla sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23071','fiesta','Fiestas de San Isidro Labrador y Encierros de Reses Bravas','Fiestas patronales tradicionales con suelta de vaquillas por el casco urbano y verbenas. Se celebra en Mayo. Ambiente muy participativo y dinámico en la puerta de entrada a la Sierra de Segura.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23072','fiesta','Fiestas de San Juan Bautista y Feria de la Sierra de Segura','Tradicionales encierros taurinos diurnos y nocturnos por las calles del municipio y verbenas populares al aire libre. Se celebra en Septiembre. Se erige como uno de los grandes focos festivos y de diversión de la comarca serrana septentrional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','fiesta','Fiestas de la Virgen de Tíscar y Concurso Nacional de Pintura Rafael Zabaleta','Romería serrana monumental al pintoresco Santuario de la Cueva del Agua y certamen cultural de bellas artes. Se celebra en Agosto. La romería al escarpado enclave rocoso del Santuario de Tíscar posee un inmenso valor místico y paisajístico andaluz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','fiesta','Fiesta de los Mozos de Rus','Hito folclórico satírico único. Consiste en un desfile masivo de los vecinos disfrazados con máscaras artesanales e indumentarias grotescas que parodian la actualidad local con total desparpajo. Se celebra en Septiembre. Declarada de Interés Turístico de Andalucía por conservar de forma pura este peculiar "carnaval de septiembre" de origen medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','fiesta','Fiestas del Medievo de Sabiote y Feria de San Ginés','Festival de recreación histórica donde la villa renacentista retrocede en el tiempo con carreras de caballos a la antigua usanza, mercados y asaltos al castillo. Se celebra en Mayo (Fiestas del Medievo) y Agosto (Feria). Sus Fiestas del Medievo son un referente andaluz por el realismo de los torneos de caballeros en su recinto amurallado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23076','fiesta','Fiestas Conmemorativas de la Batalla de Las Navas de Tolosa y Fiestas de la Emperatriz Santa Elena','Actos institucionales y recreación histórica militar que conmemoran la famosa batalla del año 1212 con desfiles y campamentos. Se celebra en Julio. *. Gran relevancia histórica nacional por su ubicación en el paso estratégico de Despeñaperros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23077','fiesta','Fiestas Patronales de San Sebastián','Fiestas de la campiña, carreras de cintas, comidas colectivas y verbenas de verano trasladas. Se celebra en Julio (traslado estival). Fiesta pequeña y hospitalaria con una comunidad vecinal muy acogedora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23904','fiesta','Fiestas de Santiago Apóstol, San Juan y la Fiesta de la Trashumancia de Santiago de la Espada','Tradición ganadera profunda que pone en valor el pastoreo de la oveja segureña con asados tradicionales y encierros de toros. Se celebra en Julio y Agosto. Municipio más extenso de la sierra; sus fiestas ganaderas y la calidad culinaria de su cordero segureño atraen turismo masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','fiesta','Fiestas de la Pascuamayo (La Mayordomía de Santisteban)','Tradición medieval de gran fervor. Consiste en la disputa pacífica por la "toma del estandarte" de la virgen, acompañada de convites populares masivos de garbanzos tostados y vino. Se celebra en Mayo. Declarada de Interés Turístico de Andalucía. Posee un incalculable valor antropológico por sus rituales gremiales de origen feudal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','fiesta','Fiestas Patronales de la Virgen de los Remedios','Fiestas tradicionales, ferias de mediodía, suelta de vaquillas y verbenas de verano. Se celebra en Septiembre. Mucha participación vecinal junto a las fértiles riberas del río Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','fiesta','Fiestas de la Virgen del Rosario (Festejos Taurinos en la Plaza de Toros Cuadrada)','Festejos taurinos tradicionales celebrados en su mítica e histórica plaza de toros de planta cuadrada ubicada a los pies de su castillo medieval. Se celebra en Octubre. La tremenda originalidad plástica de ver torear en una plaza rectangular/cuadrada medieval colgada del tajo atrae a millares de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','fiesta','Fiestas en honor a San Roque (Encierros de Siles)','Encierros de toros bravos guiados con cuerdas por las empinadas calles de la sierra, calderetas populares de carne y peñas festivas. Se celebra en Agosto. Fuerte tradición taurina popular muy concurrida por los jóvenes de la comarca de Segura.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23084','fiesta','Fiestas Patronales de Santa Águeda','Fiestas de invierno con hogueras tradicionales, migas, verbenas de noche y procesión solemne. Se celebra en Febrero. Conservación impecable de las costumbres y gastronomía invernal olivarera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23085','fiesta','Fiestas de la Virgen de la Cabeza','Feria local de casetas andaluzas, competiciones deportivas, comidas populares y orquestas. Se celebra en Agosto. Ambiente muy festivo y de convivencia vecinal en la comarca de La Loma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23086','fiesta','Romería de la Virgen de la Cabeza de Torredelcampo y Feria de Santa Ana','Romería campestre multitudinaria al paraje de cerro Miguelico y gran feria de casetas andaluzas. Se celebra en Mayo (Romería) y Julio (Feria). Su romería en el cerro Miguelico congrega a decenas de miles de personas, destacando por su gran despliegue de caballistas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','fiesta','Feria de San Cosme y San Damián (Fiestas de los Santos) y Semana Santa de Torredonjimeno','Gran feria andaluza de casetas, conciertos y ferias de día, combinada con una Semana Santa de imaginería barroca señorial. Se celebra en Septiembre (Feria). Una de las ferias de septiembre más populosas e importantes del eje metropolitano occidental de Jaén.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','fiesta','Fiestas de Santiago Apóstol, Feria de Septiembre y Festival de la Canción de Autor "Un Mar de Canciones"','Feria mayor de casetas, y prestigioso festival musical especializado en cantautores de relevancia nacional. Se celebra en Julio (Festival) y Septiembre (Feria). Su festival musical le aporta un sello de calidad cultural e intelectual muy reconocido en toda la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','fiesta','Fiestas de Nuestro Padre Jesús Nazareno y Jornadas Gastronómicas de la Cereza de Torres','Fiestas patronales tradicionales y muestra culinaria dedicada a su afamada cosecha de cerezas de Sierra Mágina. Se celebra en Junio (Cereza) y Septiembre (Patronales). Su cita gastronómica de la cereza en junio atrae a numerosos visitantes buscando productos artesanos de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23091','fiesta','Fiestas Patronales de la Virgen del Campo (Encierros de Torres)','Tradición serrana con suelta de vaquillas por el casco urbano, verbenas de noche y paella gigante. Se celebra en Mayo. Fiesta pequeña orientada a la convivencia familiar y hospitalidad serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','fiesta','Feria de San Miguel y Semana Santa de Úbeda','Semana Santa monumental de máxima categoría internacional, y una de las ferias de otoño más grandes y elegantes de Andalucía, con casetas, corridas de toros y su famoso Festival de Música de Úbeda. Se celebra en Marzo/Abril (Semana Santa) y Septiembre/Octubre (Feria). Su Semana Santa y su Feria de San Miguel están declaradas de Interés Turístico Internacional. Los desfiles procesionales entre palacios renacentistas Patrimonio de la Humanidad configuran un espectáculo estético y cultural insuperable en España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23093','fiesta','Fiestas del Santísimo Cristo de Chircales y Feria de Agosto','Romería campestre de gran devoción al paraje del nacimiento de agua de Chircales, y feria tradicional de verano de casetas. Se celebra en Mayo (Romería) y Agosto (Feria). Mucho arraigo familiar y vecinal en el corazón de la Sierra Sur, atrayendo a numerosos emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','fiesta','Fiestas en honor a la Virgen del Castillo (Encierros de Vilches)','Fiestas patronales con tradicionales y populosos encierros de toros ensogados por las empinadas calles de origen morisco. Se celebra en Agosto. Mucha animación taurina popular y excelentes vistas desde su mirador sobre los embalses del norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','fiesta','Fiestas del Corpus Christi de Villacarrillo y Feria de Septiembre','Espectáculo vegetal y artístico religioso donde los vecinos tapizan kilómetros de calles con asombrosas alfombras de serrín coloreado, flores y plantas aromáticas. Se celebra en Junio (Corpus). Declarado de Interés Turístico de Andalucía. Es uno de los Corpus más antiguos y hermosos de la comunidad, convirtiendo todo el suelo urbano en un lienzo efímero de serrín coloreado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23098','fiesta','Corpus Christi de Villardompardo','Religiosa y artística. Todo el municipio amanece cubierto de alfombras multicolores hechas con flores reales, serrín tintado y altares en las fachadas. Se celebra en Junio. Gran implicación artesanal de toda la población local, muy reconocida a nivel comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24095','fiesta','Fiestas del Rosario y San Juan Bautista','Feria local de casetas, tradicionales carreras de cintas, ferias de mediodía y eventos culturales. Se celebra en Junio y Octubre. Mucha participación juvenil potenciada por su gran cercanía e interconexión con Jaén capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23101','fiesta','Fiestas Patronales de San Bartolomé','Fiestas tradicionales serranas, encierros de vaquillas por el casco urbano y verbenas de noche. Se celebra en Agosto. Es el municipio más septentrional de la provincia; sus fiestas conservan una atmósfera rural e íntima en los límites de La Mancha.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23903','fiesta','Fiestas Patronales de la Virgen del Rosario','Fiestas que unifican las tradiciones de sus tres núcleos (Torrequebradilla, Vados de Torralba y Villargordo), con verbenas y actividades agrícolas de la vega. Se celebra en Agosto. *. Gran ambiente de convivencia y hermandad vecinal a orillas del Guadalquivir). Con esto queda completada al 100% la Provincia de Jaén de la A a la Z, cerrando este extenso e importante bloque listo para tu documento Word. Dime si pasamos al siguiente bloque del documento para redactar la siguiente provincia de Andalucía en orden alfabético, que corresponde a Málaga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90745','fiesta','Fiestas Patronales de San Isidro Labrador y Fiesta de las Candelas','Romería andaluza multitudinaria con carrozas de cañas y flores, y noche invernal de hogueras monumentales en todos los barrios. Se celebra en Mayo (San Isidro) y Febrero (Candelas). Su Romería de San Isidro está declarada de Interés Turístico de Andalucía por su enorme participación y vistosidad en la comarca de Antequera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90433','fiesta','Fiesta de la Castanyada y Feria de Agosto','Gastronómica e invernal (reparto masivo de castañas asadas, batatas cocidas y mantecados con anís en la plaza) y feria tradicional de verano. Se celebra en Noviembre (Castanyada) y Agosto (Feria). La Fiesta de la Castaña atrae a miles de visitantes de toda la provincia buscando el tipismo de la Axarquía interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90434','fiesta','Fiesta de la Embajada (Moros y Cristianos) y Fiesta de la Cereza','Recreación histórica y teatral basada en un romance medieval con trajes de época, y muestra promocional de su afamada cosecha de cerezas de montaña. Se celebra en Septiembre (Embajada) y Junio (Cereza). La Fiesta de la Embajada es de Interés Turístico por ser una de las pocas representaciones de Moros y Cristianos de la provincia, destacando por su rigor y encanto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90435','fiesta','Fiesta del Gazpacho de los Tres Golpes y Fiestas del Santo Cristo de la Integridad','Gastronómica veraniega (degustación masiva de su gazpacho tradicional cortado a cuchillo) y fiesta patronal. Se celebra en Agosto. Su singular evento culinario veraniego en pleno Pirineo de la Axarquía congrega a mucho turismo gastronómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90436','fiesta','Algarrobo Rock y Fiesta de la Quema de Algarrobo / Feria de la Tortilla de Algarrobo','Festival musical veraniego, recreación histórica bandolera (con trajes de 1811 contra el ejército napoleónico) y muestra de su famosa repostería artesana. Se celebra en Septiembre (Quema) y Agosto (Rock). La recreación de "La Quema" moviliza a todo el municipio y se ha consolidado como un gran hito turístico en la Costa del Sol Axarquía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90437','fiesta','Fiestas de Nuestra Señora del Rosario (Hachas de Algatocín)','Patronal serrana que mantiene el singular y antiguo rito nocturno de procesionar al son de cánticos iluminando las calles con grandes "hachas" de cera artesanales. Se celebra en Octubre. Gran valor folclórico y atmósfera mística en el corazón del Valle del Genal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90438','fiesta','Fiestas de San Juan Bautista y la Fiesta de la Portada / Festival Flamenco Torre del Cante','Macro-feria urbana de gran infraestructura y prestigioso festival de cante flamenco purista de renombre nacional. Se celebra en Junio. El festival Torre del Cante está declarado de Interés Turístico de Andalucía, siendo una de las grandes citas estivales obligadas para los amantes del género.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90439','fiesta','Semana Santa de Alhaurín el Grande y Feria de Mayo','Religiosa monumental con la tradicional y famosa rivalidad escénica entre los "Verdes" y los "Moraos", y feria tradicional de casetas. Se celebra en Marzo/Abril (Semana Santa) y Mayo (Feria). Su Semana Santa está declarada de Interés Turístico Nacional por la espectacularidad de sus representaciones vivientes de la Pasión en las calles y la riqueza de sus hermandades.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90440','fiesta','Fiesta del Ajoblanco de Almáchar','Hito gastronómico provincial. Es la fiesta culinaria más antigua de Málaga (desde 1968), donde se reparten de forma gratuita miles de litros de ajoblanco acompañados de uvas moscatel. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico de Andalucía. Es un emblema de la cultura gastronómica malagueña, atrayendo a masas turísticas al interior de la Axarquía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90441','fiesta','Feria de Almargen y Fiestas de San Cosme y San Damián','Feria local de casetas, procesión tradicional, competiciones deportivas y verbenas de verano. Se celebra en Septiembre. Ambiente muy familiar enfocado a la convivencia comarcal en los límites con Sevilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90442','fiesta','Fiesta de la Trilla de Almogía y Feria de San Roque','Muestra etnográfica rural que rescata las faenas agrícolas tradicionales con mulos en la era, cantos de trilla y degustaciones, junto a su feria veraniega. Se celebra en Agosto. Su fiesta de la trilla posee un inmenso valor folclórico y rescata el folclore de Verdiales de estilo Almogía, muy señero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32025','fiesta','Semana Santa de Álora (La Despedía) y Festival de Cante Grande / Feria de Agosto','Religiosa singular, certamen de flamenco de gran solera y feria andaluz de día y noche. Se celebra en Marzo/Abril (Semana Santa) y Agosto (Feria). La Semana Santa está declarada de Interés Turístico Nacional de Andalucía por el emotivo acto de "La Despedía", donde los portadores de los dos pasos de rodillas se saludan en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32001','fiesta','Fiesta del Carnaval de la Harina y Feria de Santiago y Santa Ana','Tradición carnavalesca única en la que los vecinos se persiguen por todo el pueblo arrojándose bolsas de harina hasta quedar completamente encalados. Se celebra en Febrero. Declarado de Interés Turístico Provincial por conservar esta divertida y antiquísima costumbre previa a la Cuaresma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90443','fiesta','Fiestas Patronales de San Roque y el Niño del Fray Leopoldo','Fiestas patronales y peregrinación religiosa dedicada al Beato Fray Leopoldo (nacido en el municipio) con verbenas de montaña. Se celebra en Agosto. Mucha afluencia de devotos de toda Andalucía que acuden a visitar la casa natal del fraile capuchino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32002','fiesta','Real Feria de Agosto de Antequera y Semana Santa de Antequera (Correr la Vega)','Una de las ferias más antiguas del país (desde 1748) con casetas señoriales, corridas de toros Goyescas y espectáculos hípicos. Semana Santa singular con el rito de subir los tronos corriendo por las empinadas cuestas del pueblo ("Correr la Vega"). Se celebra en Agosto (Feria) y Marzo/Abril (Semana Santa). Declaradas de Interés Turístico Nacional. La feria posee un empaque aristocrático e histórico andaluz andaluz de primer nivel, y la Semana Santa es un hito de fuerza y devoción único.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90746','fiesta','Fiesta del Folclore y las Tradiciones Populares de la Axarquía','Certamen musical y etnográfico en calles andalusíes, con pandas de verdiales, coros rocieros y catas de vino dulce local. Se celebra en Julio. La estampa de las agrupaciones folclóricas actuando bajo su bellísimo minarete almohade es de un encanto plástico espectacular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32003','fiesta','Real Feria de Agosto y Feria del Perro de Archidona','Feria mayor de gran solera y una de las muestras caninas y de razas cazadoras más importantes y multitudinarias de España, con desfiles y concursos nacionales. Se celebra en Agosto (Feria Real) y Mayo (Feria del Perro). La Feria del Perro está declarada de Interés Turístico Nacional, congregando a decenas de miles de amantes de los animales y profesionales de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32004','fiesta','Fiesta de la Matanza de Ardales y Feria de Septiembre','Macro-evento gastronómico invernal donde se reparten de forma gratuita miles de porciones de caldillo ardaleño, embutidos y chacinas locales. Se celebra en Febrero (Matanza) y Septiembre (Feria). Declarada de Interés Turístico de Andalucía. Es una de las citas culinarias de invierno con más tirón masivo, potenciada por el turismo que visita el Caminito del Rey.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','fiesta','Fiesta de la Mula de Arenas','Curiosa e histórica feria etnográfica y ganadera dedicada a ensalzar y premiar las labores de carga, exhibiciones y carreras de mulas de la comarca. Se celebra en Octubre. Declarada de Interés Turístico Provincial por su originalidad en la salvaguarda de este animal clave para la agricultura de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90444','fiesta','Semana Santa de Arriate y Feria de la Fiesta en el Aire','*. Semana Santa de inmenso fervor (única localidad malagueña con desfiles procesionales organizados de forma independiente por "Jesistas" y "Cristinos"), y un festival cultural con artesanía y música callejera. *. Se celebra en Marzo/Abril (Semana Santa) y Octubre (Fiesta en el Aire). *. Su Semana Santa está declarada de Interés Turístico de Andalucía debido a su singular fisonomía gremial e histórica y la masiva afluencia de la Serranía de Ronda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29021','fiesta','Fiesta del Mosto de Atajate','Gastronómica y enológica. Los vecinos ofrecen de forma gratuita los mostos artesanales elaborados en las bodegas del pueblo blanco acompañados de migas tradicionales. Se celebra en Noviembre. Es el pueblo con menos habitantes de la provincia; su fiesta del mosto atrae a numeroso público por su autenticidad e inmenso valor vitivinícola.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29022','fiesta','Fiestas de Moros y Cristianos en honor a San Isidoro','Recreación histórica y teatral monumental. Los combates se escenifican en un escenario real inigualable: el recinto amurallado de su histórico Castillo medieval (hoy cementerio del pueblo). Se celebra en Agosto. Declarada de Interés Turístico de Andalucía por la espectacular fisonomía de las batallas y el texto de época que interpretan los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29023','fiesta','Feria de Benahavís en honor a la Virgen del Rosario','Feria de gran categoría con potentes conciertos de bandas de pop nacional, atracciones, espectáculos pirotécnicos y una rica feria gastronómica de hostelería local. Se celebra en Agosto. Se erige como un punto de atracción de ocio muy dinámico en el triángulo de la Costa del Sol occidental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29024','fiesta','Fiesta de Moros y Cristianos de Benalauría (El Cautiverio)','Recreación histórica-teatral de calle de origen centenario basada en los alzamientos moriscos del siglo XVI en la serranía, con salvas de pólvora. Se celebra en Agosto. Destaca por el realismo de los desfiles de las huestes y el alto nivel de implicación de la comunidad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29025','fiesta','Feria de San Juan (Arroyo de la Miel) y la Festividad del Corpus Christi / Procesión del Carmen','Macro-feria costera con un ordenado recinto de casetas, conciertos multitudinarios, alfombras de flores para el Corpus y procesión marítima de gran tradición. Se celebra en Junio (San Juan) y Julio (Carmen). Una de las citas lúdicas más multitudinarias del verano de la Costa del Sol, uniendo el ambiente tradicional andaluz con el turismo internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29026','fiesta','Fiesta del Campo de Benamargosa','Gran muestra agrícola y gastronómica dedicada a ensalzar sus pioneros cultivos de frutos tropicales (aguacates, mangos, chirimoyas) con degustaciones de "baticate" (batido de aguacate), tapas y verbenas. Se celebra en Abril. Declarada de Interés Turístico de Andalucía por poner en valor la rica huerta tropical de la Axarquía con un ambiente muy festivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29027','fiesta','Día de la Música de Benamocarra y Feria de la Virgen de la Salud','Macro-evento cultural internacional donde las calles se llenan de conciertos simultáneos de jazz, clásica, folclore y bandas (tierra del compositor Eduardo Ocón), combinado con su feria local. Se celebra en Septiembre (Día de la Música). Declarada de Interés Turístico Andaluz debido a su originalidad y la inmensa cantidad de músicos de todo el país que congrega en un solo día.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29028','fiesta','Feria de la Chacina de Benaoján y Fiestas de Nuestra Señora del Rosario','Feria gastronómica y comercial monográfica dedicada a sus célebres industrias cárnicas tradicionales de embutidos y lomos en manteca de la serranía, con degustaciones populares. Se celebra en Diciembre (Feria de la Chacina). Punto de encuentro invernal clave en la Serranía de Ronda para la compra de despensa artesanal de alta calidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29029','fiesta','Fiestas Patronales de San Sebastián y Feria Gastronómica del Sabor Andaluz','Feria culinaria artesanal dedicada a los quesos, aceites, mieles y embutidos del Valle del Genal y la serranía, junto a su fiesta local de invierno. Se celebra en Enero (San Sebastián) y Febrero (Feria Gastronómica). Excelente muestra agroalimentaria artesanal en un precioso marco rural de montaña blanca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29031','fiesta','Fiesta de la Sopa de los Siete Ramales y Feria de San Agustín','Gastronómica (degustación masiva de su plato ancestral de origen campesino elaborado con pan y hortalizas de la huerta serrana) y feria mayor de verano. Se celebra en Febrero (Sopa) y Agosto (Feria). Declarada de Interés Turístico de Andalucía; su cita gastronómica invernal llena el municipio en pleno Parque Nacional de la Sierra de las Nieves.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29033','fiesta','Día de la Morcilla de Canillas de Aceituno y Feria de la Virgen de la Cabeza','Hito gastronómico de primavera donde se reparten de forma gratuita miles de kilos de su famosa morcilla aliñada al estilo tradicional acompañada de vino del terreno. Se celebra en Abril (Día de la Morcilla). Declarada de Interés Turístico Andaluz. Es una de las ferias de un solo día más multitudinarias del interior de la Axarquía, atrayendo a miles de comensales a las faldas de Sierra Tejeda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29034','fiesta','Fiestas en honor a la Virgen del Rosario y San Antón','Fiestas patronales tradicionales, procesión solemne, competiciones deportivas y verbenas de noche en sus plazas encaladas. Se celebra en Agosto. Ambiente muy festivo y familiar en un precioso entorno de turismo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29035','fiesta','Fiestas Patronales de la Virgen de Caños Santos y Feria de Agosto','Fiestas patronales de gran devoción comarcal con desfiles de carrozas, ferias de mediodía y verbenas populares bajo su castillo medieval. Se celebra en Septiembre (Patrona) y Agosto (Feria). Mucha participación local con un fuerte arraigo de costumbres tradicionales en la transición a la sierra de Cádiz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29036','fiesta','Villa de la Luna Mora de Carratraca y Feria de Agosto','Espectacular festival cultural donde el pueblo se ilumina exclusivamente con la luz de más de 25.000 velas artesanales, recreando un zoco andalusí medieval con música y danza. Se celebra en Septiembre (Luna Mora). Declarada de Interés Turístico de Andalucía. La asombrosa belleza visual del pueblo iluminado por velas y su tradición de balnearios atrae a millares de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29037','fiesta','Fiesta de la Cortesía (Domingo de Resurrección) y Fiesta del Tostón de Castañas','Antiguo rito folclórico de encuentro místico entre las imágenes de la virgen y el niño en el campo, y tostadas colectivas otoñales de castañas del bosque. Se celebra en Marzo/Abril (Cortesía) y Noviembre (Tostón). Gran belleza paisajística durante el otoño en el Valle del Genal ("Bosque de Cobre"), dotando al Tostón de gran encanto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29038','fiesta','Feria de Cártama en honor a la Virgen de los Remedios y Feria del Ganado tradicional','Feria de grandes dimensiones con un populoso recinto de casetas, procesiones multitudinarias y mantenimiento de tratos comerciales agrícolas de origen centenario. Se celebra en Abril. Su procesión de bajada de la Virgen desde la ermita y su feria tradicional congregan a miles de personas de todo el Valle del Guadalhorce y área metropolitana). Dime si pasamos al siguiente bloque para continuar redactando los municipios de la provincia de Málaga de la C a la G (Casabermeja, Casarabonela, Casares, Coín, Colmenar, Comares, Cómpeta, Cortes de la Frontera, Cuevas Bajas, Cuevas de San Marcos, Cuevas del Becerro, Cútar, Estepona, Faraján, Frigiliana, Fuengirola, Fuente de Piedra, Gaucín, Guaro...). ¿Seguimos avanzando para ir dándole forma a tu documento Word?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29039','fiesta','Corpus Christi de Casabermeja y Festival de Cante Grande de Casabermeja / Fiesta de la Cabra Malagueña','Religiosa (con gran arraigo en calles engalanadas), uno de los festivales flamencos más antiguos de Málaga y feria gastronómica sectorial ganadera. Se celebra en Junio (Corpus), Julio (Flamenco) y Septiembre (Cabra). Su Festival de Cante Grande está declarado de Interés Turístico de Andalucía por su pureza, y la feria gastronómica de la Cabra atrae a miles de gastrónomos a la puerta de Antequera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29040','fiesta','Fiesta de los Rondeles y Feria de Santiago','Hito etnográfico nocturno e invernal. Los vecinos procesionan por las calles oscuras portando castañuelas y quemando "rondeles" (capachos de esparto impregnados en aceite) para iluminar a la Virgen de los Rondeles. Se celebra en Diciembre (Rondeles). Declarada Fiesta de Interés Turístico de Andalucía por el misticismo, espectacularidad y el fuego que envuelve sus empinadas calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29041','fiesta','Feria de Casares y Fiestas Patronales de la Virgen del Campo','Feria mayor de verano con casetas andaluzas tradicionales en su escarpada plaza central, procesiones y eventos culturales flamencos. Se celebra en Agosto (Feria) y Septiembre (Patrona). La estampa de su casco histórico fortificado dota a su feria estival de una belleza visual y un ambiente andaluz muy elogiado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29042','fiesta','Fiesta de la Naranja de Coín y Feria de Mayo / Fiestas del Cristo del Perdón','Macro-muestra gastronómica y agrícola (reparto gratuito de miles de kilos de naranjas, ensaladilla de naranja y sopa hervía) y gran feria andaluz de casetas. Se celebra en Mayo (Feria y Naranja) y Agosto (Fiestas de Verano). La Fiesta de la Naranja está declarada de Interés Turístico de Andalucía, ensalzando la capitalidad agrícola del fructífero Valle del Guadalhorce.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29043','fiesta','Fiesta del Mosto y de la Chacina de Colmenar','Gran macro-evento gastronómico y comercial de invierno que reúne a miles de visitantes en torno a degustaciones de embutidos tradicionales y los vinos mostos de la comarca. Se celebra en Diciembre. Declarada de Interés Turístico de Andalucía; es uno de los grandes bastiones de la despensa artesana y culinaria malagueña en plenos Montes de Málaga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29044','fiesta','Fiesta de San Hilario de Poitiers (Fiesta de los Verdiales)','Patronal y folclórica masiva, con procesión, migas populares y un espectacular encuentro de Pandas de Verdiales de estilo Comares (el más rápido y vivo). Se celebra en Enero. Declarada de Interés Turístico Andaluz. Al ser el "Balcón de la Axarquía", el sonido de los violines y platillos en sus riscos congrega a muchísimos folcloristas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32007','fiesta','Noche del Vino de Cómpeta','Hito enológico internacional. Se recrea la pisa tradicional de la uva moscatel en la plaza del pueblo, acompañada de cantes, bailes por sevillanas y el reparto gratuito de miles de litros de vino de Cómpeta a locales y turistas. Se celebra en Agosto. Declarada Fiesta de Interés Turístico de Andalucía; es un referente absoluto del enoturismo en el sur de España por la masiva afluencia de público internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29046','fiesta','Feria de Cortes y Fiestas Patronales de San Roque y San Sebastián','Feria mayor de la serranía profunda con sueltas de vaquillas, peñas festivas, verbenas de noche y actividades lúdicas en sus pedanías (El Colmenar). Se celebra en Agosto. Punto de conexión muy dinámico entre el Parque Natural de los Alcornocales y la Serranía de Ronda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29047','fiesta','Fiesta de la Zanahoria Morá de Cuevas Bajas','Singularísima feria gastronómica dedicada a su cultivo estrella: una zanahoria de color morado introducida por los árabes hace siglos, con degustaciones de migas con zanahoria, licores morados y mercados agrarios. Se celebra en Diciembre. Declarada de Interés Turístico Provincial por salvaguardar esta joya hortofrutícola única en la comarca de Antequera norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29049','fiesta','Fiesta de San Marcos y Feria de Agosto','Rompimiento tradicional del sombrero por San Marcos (meriendas campestres con el hornazo tradicional) y feria de verano con casetas andaluzas. Se celebra en Abril (San Marcos) y Agosto (Feria). Conectada intensamente al entorno natural de la Falla de Camorro y el Embalse de Iznájar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29048','fiesta','Romería de San Isidro y Feria de San Antonio','Peregrinación andaluza campestre con carretas engalanadas tiradas por bueyes y caballos, y feria local de verano. Se celebra en Mayo (Isidro) y Septiembre (San Antonio). Mucha participación juvenil y ambiente muy dinámico en el acceso a la comarca rondeña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29050','fiesta','Fiesta del Monfí de Cútar','Preciosa recreación histórica de la cultura andalusí y morisca, donde el pueblo decora sus fachadas con telas árabes, zocos artesanales, música e iluminación con velas nocturnas. Se celebra en Octubre. Declarada de Interés Turístico Provincial por su original rigor para rememorar la rebeldía de los "monfíes" en la Axarquía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29051','fiesta','Feria de San Isidro Labrador y Feria de Estepona (Feria Mayor)','Romería y desfile agrícola de gran empaque en el centro urbano (con calles cubiertas de juncos) y una gran feria costera con un macro-recinto de casetas y conciertos pop. Se celebra en Mayo (San Isidro) y Julio (Feria Mayor). Su festividad de San Isidro está declarada de Interés Turístico de Andalucía por ser de las ferias de campo más singulares e importantes de todo el litoral malagueño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29052','fiesta','Fiestas Patronales de San Sebastián','Fiestas patronales tradicionales de la serranía blanca, procesión por calles laberínticas, comidas populares y verbenas estivales trasladadas. Se celebra en Agosto (traslado vacacional). Población pequeña pero con un gran corazón hospitalario en el Valle del Genal superior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29053','fiesta','Festival Frigiliana de las 3 Culturas y Feria de San Antonio de Padua','Macro-festival cultural, lúdico e internacional que celebra la convivencia histórica de las culturas cristiana, judía y musulmana con conciertos de músicas del mundo, ruta de la tapa y mercados medievales. Se celebra en Agosto (Festival 3 Culturas) y Junio (Feria). Declarado Fiesta de Interés Turístico Andaluz. Es uno de los festivales más virales, multitudinarios y exitosos de la provincia, transformando su precioso casco histórico de origen árabe en un bullir internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29054','fiesta','Feria del Rosario (Feria de Fuengirola) y Feria Internacional de los Países (FIP)','Una de las ferias andaluzas más elegantes y famosas por su cuidado paseo de caballos y enganches, combinada con el macro-festival multicultural donde decenas de países exponen su gastronomía y folclore en las casetas estables del recinto. Se celebra en Octubre (Rosario) y Abril/Mayo (FIP). La Feria del Rosario es Fiesta de Interés Turístico de Andalucía y referente de tipismo ecuestre. La Feria Internacional de los Países es un evento único en España que congrega a cientos de miles de visitantes internacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29055','fiesta','Carrera de Cintas a Caballo de Fuente de Piedra y Feria de la Virgen de las Virtudes','Hito ecuestre tradicional de origen medieval (donde los jinetes al galope intentan ensartar una pica en pequeñas anillas) y feria local de casetas. Se celebra en Septiembre. Declarada de Interés Turístico Andaluz; sus carreras hípicas tradicionales gozan de gran fama e historia en la llanura antequerana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29056','fiesta','Toro de Cuerda de Gaucín y Feria de Agosto','Tradicional y multitudinario encierro de un toro guiado con una cuerda por los vecinos a través de las empinadas y blancas cuestas del pueblo el Domingo de Resurrección, junto a su feria estival. Se celebra en Marzo/Abril (Toro de Cuerda) y Agosto (Feria). *. Su Toro de Cuerda posee un inmenso valor etnográfico en la serranía costera interior, congregando a miles de jóvenes corredores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29058','fiesta','Festival de la Luna Mora de Guaro y Feria de San Sebastián','Espectacular festival de música andalusí, sefardí y flamenca donde el alumbrado público se apaga y el casco histórico resplandece bajo el fuego de más de 25.000 velas artesanales dispuestas en el suelo dibujando filigranas. Se celebra en Septiembre (Luna Mora). Declarada de Interés Turístico de Andalucía. Es la pionera y más célebre de las "lunas moras" de la provincia, transformando su auditorio al aire libre en un hito de las noches musicales del sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29059','fiesta','Feria del Emigrante y Fiestas de San Juan Bautista','Feria mayor andaluza de verano de casetas y verbenas concebida originalmente para el reencuentro de los trabajadores locales retornados. Se celebra en Agosto (Feria del Emigrante) y Junio (San Juan). Gran ambiente festivo y hospitalario en el nudo logístico central de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29060','fiesta','Fiestas en honor a Santa Rosa de Lima y Fiesta de la Castaña','Fiestas patronales serranas y jornadas gastronómicas campestres dedicadas a su rica producción maderera y frutal de castañas en el nacimiento del río Genal. Se celebra en Agosto (Patronales) y Noviembre (Castaña). Su espectacular marco natural de "Bosque de Cobre" en otoño dota a sus jornadas tradicionales de gran belleza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29061','fiesta','La Pasión en Istán (Semana Santa) y Fiesta de la Tomatada','Representación teatral viviente de origen antiguo de los pasos bíblicos en las calles del pueblo blanco, y muestra gastronómica estival basada en su huerta serrana. Se celebra en Marzo/Abril (Pasión) y Julio (Tomatada). La representación viviente de los vecinos está declarada de Interés Turístico Andaluz por su gran realismo y devoción a los pies de Sierra Blanca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29062','fiesta','Fiesta del Moscatel de Iznate','Muestra gastronómica y enológica de gran tirón en la que los vecinos abren sus patios andaluces para ofrecer tapas tradicionales, uvas pasas y copas de vino moscatel artesano de la Axarquía. Se celebra en Agosto. Declarada de Interés Turístico Provincial por su esmero en promocionar la cultura culinaria y la uva pasa moscatel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29065','fiesta','Fiestas de la Virgen de Moclón','Fiestas tradicionales serranas, verbenas de noche populares y procesión solemne hacia su ermita rural en el Valle del Genal. Se celebra en Agosto. Muy conocida mundialmente por su fisonomía de "pueblo azul"; la fiesta congrega a mucho turismo familiar de interior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29066','fiesta','Fiesta del 4 de Julio (Día de la Independencia de EE.UU.) y Fiestas de San Bernardo','Curiosísima e histórica festividad internacional que conmemora la aportación de su ilustre vecino, el militar Bernardo de Gálvez, a la independencia americana con desfiles de soldados de época, banderas y barbacoas. Se celebra en Julio (4 de Julio). Declarada de Interés Turístico Provincial por su absoluta exclusividad histórica, atrayendo a embajadas internacionales, medios de comunicación y turistas culturales). ¿Prefieres que continuemos con el siguiente bloque de la letra M a la R de Málaga (Málaga Capital, Manilva, Marbella, Mijas, Moclinejo, Mollina, Monda, Montejaque, Nerja, Ojén, Parauta, Periana, Pizarra, Pujerra, Rincón de la Victoria, Riogordo, Ronda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29067','fiesta','Feria de Málaga (Feria de Agosto) y Semana Santa de Málaga','Gran macro-feria del sur de Europa (con su característico doble formato: Feria de Día en el Centro Histórico y Feria de Noche en el Cortijo de Torres) y Semana Santa monumental. Se celebra en Agosto (Feria) y Marzo/Abril (Semana Santa). Declaradas de Interés Turístico Internacional. La Feria de Agosto atrae a millones de visitantes de todo el mundo. La Semana Santa destaca por el colosal tamaño de sus tronos procesionales, como el de la Virgen de la Esperanza o el Cristo de la Buena Muerte portado por la Legión.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29068','fiesta','Fiesta de la Vendimia de Manilva y Fiestas de Santa Ana','Enológica tradicional de la costa con pisada de uva para la obtención del primer mosto, degustaciones y reparto de racimos de uva moscatel. Se celebra en Septiembre (Vendimia). Declarada de Interés Turístico de Andalucía. Es de las pocas fiestas de la vendimia costeras que combinan el tipismo agrícola con el turismo del litoral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29069','fiesta','Feria de San Bernabé y Feria de San Pedro de Alcántara / Starlite Festival','Ferias andaluzas costeras de grandes dimensiones con desfiles de gigantes y cabezudos, casetas y conciertos pop masivos, combinadas con prestigiosos festivales boutique de verano. Se celebra en Junio (San Bernabé) y Octubre (San Pedro). Feria de altísimo impacto turístico y mediático. Combina de forma excelente las tradiciones del casticismo andaluz con el turismo de lujo internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29070','fiesta','Feria de Mijas en honor a la Virgen de la Peña y Día del Turista','Feria mayor tradicional que se celebra a lo largo de las empinadas cuestas de su pueblo blanco, destacando los desfiles de carruajes, bailes por sevillanas y pasacalles. Se celebra en Septiembre. Declarada de Interés Turístico de Andalucía. Su gran solera y el encanto de sus plazas atraen a miles de residentes extranjeros y turistas nacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29071','fiesta','Fiesta de Viñeros de Moclinejo','Hito etnográfico de la Axarquía que recrea las faenas del campo de la recogida de la uva pasa moscatel, el picado de pasas, la pisa tradicional y catas de su vino dulce. Se celebra en Septiembre. Declarada de Interés Turístico de Andalucía por salvaguardar de forma excelente las costumbres de los viticultores locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29072','fiesta','Feria de la Vendimia de Mollina','Gran macro-feria del vino donde se celebran catas dirigidas por enólogos, desfiles de carrozas engalanadas, verbenas y concursos de poesía en torno al vino. Se celebra en Septiembre. Declarada de Interés Turístico Andaluz. Al albergar la mayor producción de vino de la comarca de Antequera con D.O. Málaga, su cita es indispensable para el sector bodeguero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29073','fiesta','Día de la Sopa Mondeña','Macro-encuentro gastronómico donde los vecinos cocinan en enormes lebrillos de barro su famosa sopa de pan, pimientos, ajos y huevos escalfados para repartirla de forma gratuita. Se celebra en Marzo. Declarada de Interés Turístico de Andalucía. Atrae a millares de visitantes ávidos de comida tradicional en plenas faldas de la Sierra de las Nieves.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29074','fiesta','Fiestas en honor a la Virgen de la Concepción (Juegos de los Cántaros)','Tradición y juego folclórico antiguo donde los vecinos vestidos con trajes típicos se lanzan en corro cántaros de barro con pericia para evitar que se rompan. Se celebra en Agosto. Gran valor antropológico por conservar este juego tradicional y festivo único en la Serranía de Ronda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29075','fiesta','Feria de Nerja en honor a la Virgen de las Angustias y San Miguel Arcángel / Fiesta de las Tres Culturas','Gran feria andaluza costera de gran solera con conciertos, castillos de fuegos artificiales piromusicales junto al Balcón de Europa y concursos de misses y místers. Se celebra en Octubre. Es una de las ferias de otoño con más dinamismo y afluencia de la costa oriental, manteniendo un empaque andaluz muy alegre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29076','fiesta','Festival Flamenco Castillo del Cante de Ojén y Feria de San Dionisio','Uno de los festivales flamencos con mayor solera e historia de la provincia, donde actúan los máximos exponentes del cante jondo. Se celebra en Agosto (Festival) y Octubre (Feria). Su Castillo del Cante está declarado de Interés Turístico de Andalucía y goza de un inmenso prestigio cultural entre los aficionados del género.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29077','fiesta','Fiesta del Conejo de Parauta','Gastronómica serrana donde se reparten de forma gratuita miles de raciones de conejo cocinado al estilo tradicional mondeño acompañado de vino del terreno y música folk. Se celebra en Noviembre. Su cita culinaria otoñal en pleno Valle del Genal coincide con la espectacular caída de las hojas del castaño, atrayendo mucho turismo de naturaleza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29079','fiesta','Fiesta del Aceite de Oliva Verdial de Periana y Fiestas de San Isidro','Muestra gastronómica monumental dedicada a ensalzar su exclusivo aceite de oliva virgen extra de la variedad verdial con desayunos molineros masivos. Se celebra en Abril (Fiesta del Aceite) y Mayo (San Isidro). Declarada de Interés Turístico de Andalucía. Es de los hitos culinarios oleícolas más importantes de la Axarquía, congregando a millares de gourmets.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29080','fiesta','Feria de la Virgen de la Fuensanta (La Rifa de la Virgen)','Singular ritual religioso y lúdico en el que los vecinos pujan de forma pública con dinero por el honor de llevar los varales del trono de la patrona durante la procesión. Se celebra en Agosto. Declarada de Interés Turístico Andaluz por el tremendo fervor popular y el tipismo que rodea a su curiosa subasta de varales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29081','fiesta','Fiesta de la Castaña de Pujerra','Gastronómica e invernal dedicada al castañar del Valle del Genal, con tuestes masivos gratuitos de castañas, degustación de licores y dulces hechos a base de este fruto. Se celebra en Noviembre. Gran valor identitario y etnográfico; transforma este pequeño pueblo blanco en la capital andaluz de la castaña durante un fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29082','fiesta','Fiesta del Boquerón Victoriano y Feria de la Cala del Moral','Macro-muestra culinaria marinera en el paseo marítimo con reparto gratuito de miles de kilos de boquerones fritos y en vinagre, concursos de cocina y conciertos. Se celebra en Septiembre. Declarada de Interés Turístico de Andalucía. Rinde tributo al gran emblema gastronómico malagueño, atrayendo a multitudes al final del verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29083','fiesta','El Paso de Riogordo (Semana Santa) y Fiesta del Caracol Borracho','Impresionante representación viviente de la Pasión de Cristo realizada por más de 500 vecinos en un escenario natural de 10.000 metros cuadrados, considerada de las mejores de Europa. Se celebra en Marzo/Abril (Semana Santa). Declarado Fiesta de Interés Turístico Nacional e Internacional. Su Paso es una de las joyas culturales y dramáticas más colosales de España, congregando cada año a miles de espectadores extranjeros por su veracidad histórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','fiesta','Feria de Pedro Romero (Corrida Goyesca de Ronda) y Ronda Romántica','La feria señorial más famosa de la provincia con la célebre Corrida Goyesca (toreros y público ataviados con trajes de la época de Goya) en su bicentenaria plaza de toros, combinada con un macrofestival de recreación histórica de bandoleros del siglo XIX. Se celebra en Septiembre (Feria de Pedro Romero) y Mayo (Ronda Romántica). Declarada de Interés Turístico Nacional. La Corrida Goyesca y la feria ecuestre son hitos de la aristocracia y el arte taurino mundial. Ronda Romántica atrae a decenas de miles de personas vestidas de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29085','fiesta','Festival Árabe Andalusí de Salares','Hermoso festival cultural y medieval donde el pueblo de la Axarquía se engalana con telas árabes, zocos artesanales, cetrería, degustaciones de cuscús y té, iluminando sus fachadas con velas nocturnas. Se celebra en Septiembre. [1] *. Declarada de Interés Turístico de Andalucía por su esmero y rigor histórico en ensalzar sus raíces mudéjares junto al Parque Natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29086','fiesta','Día del Níspero de Sayalonga','Gran feria agrícola y gastronómica dedicada a su cultivo estrella, repartiendo de forma gratuita miles de kilos de nísperos frescos, mermeladas y licores derivados. Se celebra en Mayo. Declarada de Interés Turístico de Andalucía; es la primera gran cita de la fruta andaluza de primavera y goza de gran éxito comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29087','fiesta','Fiestas Patronales de la Virgen de la Esperanza','Fiestas tradicionales serranas con carreras de cintas a caballo, comidas populares de migas y verbenas al aire libre en sus plazas medievales. Se celebra en Agosto. Conserva la atmósfera rural e íntima de los pueblos blancos de la Alta Axarquía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29088','fiesta','Feria del Espárrago de Sierra de Yeguas y Fiestas de San Bartolomé','Muestra agrícola y comercial de carácter hortofrutícola con degustaciones gastronómicas de platos a base de espárrago verde de la zona y mercado artesanal. Se celebra en Abril. Gran poder de convocatoria en el límite norte provincial, atrayendo a muchos profesionales agrícolas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29089','fiesta','Feria del Queso Artesano de Teba y las Fiestas de Douglas Days','Una de las ferias de quesos artesanos más importantes del país (con concursos nacionales de quesos de cabra y oveja) y una recreación histórica escocesa-medieval única basada en la leyenda de Sir James Douglas. Se celebra en Octubre (Feria del Queso) y Agosto (Douglas Days). La Feria del Queso está declarada de Interés Turístico de Andalucía. Los Douglas Days atraen a delegaciones de Escocia y turistas culturales internacionales por su singular historia de cruzados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29090','fiesta','Fiesta del Cohetazo y el Día de los Polvos (Carnaval de Tolox)','Rito de carnaval antiguo donde los vecinos se arrojan polvos talco blanqueando a todo el pueblo, acompañado de tracas de cohetes de gran estruendo en verano por San Roque. Se celebra en Febrero (Polvos) y Agosto (Cohetazo). Declarada de Interés Turístico Provincial por salvaguardar esta divertida y original costumbre carnavalesca de origen indiano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29901','fiesta','Romería de San Miguel y Feria de Torremolinos / Día del Pescaíto Frito','Romería urbana costera masiva con carretas tiradas por bueyes y caballistas flamencos, gran feria andaluza de día y noche, y reparto de toneladas de pescaíto frito en la playa de La Carihuela. Se celebra en Septiembre (Romería) y Junio (Pescaíto). La Romería de San Miguel está declarada de Interés Turístico de Andalucía; es considerada la romería urbana más populosa e importante de España tras El Rocío, reuniendo a más de 200.000 personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29091','fiesta','Fiesta de las Migas de Torrox','Hito gastronómico monumental de invierno. Se cocinan toneladas de migas al estilo arriero en grandes sartenes al aire libre acompañadas de ensalada arriera, repartiéndose gratis junto con miles de litros de vino del terreno. Se celebra en Diciembre. Declarada Fiesta de Interés Turístico de Andalucía. Es la fiesta gastronómica navideña e invernal más multitudinaria de la Costa del Sol, atrayendo a ríos de visitantes de toda España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29092','fiesta','Fiesta de la Chanfaina de Totalán','Gastronómica en la que los vecinos reparten gratis miles de raciones de su plato estrella ancestral a base de patatas, asadura, aceite de oliva y especias, con pasacalles y orquestas. Se celebra en Noviembre. Declarada de Interés Turístico Provincial; ofrece una atmósfera culinaria muy acogedora a las puertas de la comarca axárquica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29093','fiesta','Romería de la Virgen de los Dolores y Feria de Santiago','Peregrinación andaluza campestre con carretas engalanadas tiradas por bueyes que viajan por los riscos de la comarca, acompañadas de verbenas de verano. Se celebra en Mayo. Mucha devoción vecinal en un entorno natural ideal para el vuelo libre y el turismo activo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29095','fiesta','Feria del Olivar y Fiestas en honor a San Roque','Feria agrícola-comercial y lúdica de casetas andaluzas dedicada a la promoción de sus aceites de oliva de alta calidad de la comarca antequerana norte. Se celebra en Agosto. Ambiente muy festivo y de reencuentro veraniego con los emigrantes locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29902','fiesta','Festival de Verdiales de Villanueva de la Concepción y Feria de Agosto','El certamen folclórico de Verdiales más antiguo de la provincia de Málaga, reuniendo a las mejores pandas de los tres estilos tradicionales (Almogía, Comares y Montes). Se celebra en Julio (Festival de Verdiales). Declarado de Interés Turístico de Andalucía; es la meca indiscutible del folclore malagueño de verdiales a los pies del Torcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29098','fiesta','Real Feria del Ganado de Villanueva de Tapia (Feria Grande)','Una de las ferias de ganado más antiguas e importantes del sur de España (concedida en el siglo XIX) que mantiene compraventas reales de reses y mercado de tratos tradicionales. Se celebra en Octubre. Declarada de Interés Turístico de Andalucía por su altísimo valor etnográfico y comercial en el nudo de tres provincias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29096','fiesta','Fiestas en honor a Nuestra Señora del Rosario y Feria del Emigrante','Feria mayor de casetas con su tradicional carrera de cintas a caballo, verbenas de noche y actividades lúdicas tradicionales de campo. Se celebra en Octubre (Rosario) y Agosto (Emigrante). Mucha participación local con un fuerte arraigo vecinal en los valles norteños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29097','fiesta','Feria de Septiembre en honor a la Virgen de los Dolores y Fiesta de la Matanza tradicional','Gran feria andaluza de casetas de día y noche con potentes orquestas y conciertos, y eventos gastronómicos invernales. Se celebra en Septiembre. Es la feria con mayor afluencia e infraestructuras de toda su zona de la comarca agrícola de los somontanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29099','fiesta','Fiesta del Residente y Feria de la Viñuela','Festividad multicultural veraniega concebida para la integración lúdica y gastronómica de su masiva población de residentes británicos y centroeuropeos. Se celebra en Julio. Peculiar por su carácter cosmopolita a las orillas de su famoso embalse de la Axarquía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29100','fiesta','Feria del Vino y de la Castaña de Yunquera','Macro-muestra gastronómica y comercial dedicada a los caldos artesanales locales y a la rica producción maderera y frutal de castañas, con asados y mercados tradicionales. Se celebra en Octubre. Declarada de Interés Turístico de Andalucía; se erige como uno de los grandes focos de atracción turística de otoño en pleno Parque Nacional de la Sierra de las Nieves). [1] Con este extenso e importante listado de la M a la Z queda completada al 100% la Provincia de Málaga, cerrando así otra gran zona de la base de datos de festividades de España. ¿Cómo prefieres continuar construyendo tu archivo Word? ¿Pasamos a la siguiente provincia en orden alfabético de Andalucía, que corresponde a Sevilla, o prefieres que saltemos a alguna otra provincia específica de España? [1].','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90747','fiesta','Feria de San Bartolomé','Feria local de casetas andaluzas, verbenas nocturnas y actividades infantiles. Se celebra en Agosto. Fiesta de carácter local y vecinal enfocada en el reencuentro veraniego de la Sierra Sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40001','fiesta','Alanís Mediaeval (Jornadas Medievales de Alanís) y Feria de Agosto','Espectacular festival de recreación histórica en su castillo del siglo XIV, con mercados, teatros callejeros y torneos, junto a su feria tradicional. Se celebra en Septiembre (Jornadas Medievales) y Agosto (Feria). Sus jornadas medievales atraen a miles de turistas de interior cada año por la espectacular transformación de la villa de la Sierra Norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90450','fiesta','Festividades de Septiembre (Fiestas de la Santa Cruz y de la Virgen de los Dolores)','Religiosa y folclórica con la tradicional rivalidad pasional de "los piques" entre las hermandades de la Vera Cruz y la Soledad, con espectaculares carrozas. Se celebra en Septiembre. Mucha devoción y estruendo de pólvora en el Aljarafe, con gran afluencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40002','fiesta','Feria de Alcalá y Semana Santa / Carnaval de Alcalá','Gran feria andaluza con un imponente recinto de casetas permanentes en San Juan, paseo de caballos, y Semana Santa de gran arraigo. Se celebra en Junio (Feria) y Marzo/Abril (Semana Santa). Una de las ferias industriales y comerciales más potentes y concurridas de la provincia, muy conectada con la capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90451','fiesta','Semana Santa de Alcalá del Río y Feria de Septiembre','Semana Santa monumental de inmenso fervor y tipismo (famosa por el desfile de las "Legiones Romanas" y la bajada de los pasos), junto a su feria local. Se celebra en Marzo/Abril (Semana Santa) y Septiembre (Feria). Su Semana Santa está declarada de Interés Turístico de Andalucía por la riqueza de su imaginería y el singular dramatismo de sus rituales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90452','fiesta','Feria en honor a la Virgen del Consuelo y Fiesta de la Carreta','Feria mayor de casetas andaluzas, y romería tradicional con desfile de caballistas a orillas del Guadalquivir. Se celebra en Agosto (Feria) y Mayo (Romería). Fiesta participativa con una comunidad vecinal muy implicada en las tradiciones de la Vega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90748','fiesta','Feria de La Algaba y sus Tradicionales Capeas (Fiestas Taurinas)','Festejos taurinos populares celebrados en su mítica plaza de toros de carros e infraestructura rústica, combinados con su feria de casetas. Se celebra en Septiembre. Sus tradicionales capeas y encierros de novillos gozan de una inmensa fama e historia en toda Andalucía, atrayendo a miles de aficionados al mundo del toro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90453','fiesta','Fiestas del Cristo del Crucifijo y de la Virgen de Gracia / Fiesta de los Judas','Patronal serrana y tradición popular de Domingo de Resurrección donde se queman y apedrean "judas" (muñecos de trapo satíricos que representan personajes públicos). Se celebra en Agosto (Patronales) y Marzo/Abril (Judas). Gran valor folclórico y ambiente muy acogedor en plenas dehesas de la Sierra Norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90454','fiesta','Feria de Almensilla y Romería de San Antonio','Feria local de casetas urbanas y peregrinación campestre con carrozas de flores en el Aljarafe. Se celebra en Agosto (Feria) y Mayo (Romería). Mucha participación juvenil potenciada por su crecimiento residencial en el cinturón provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90455','fiesta','Fiesta del Verdeo de Arahal y Feria de San Antonio','Macro-muestra gastronómica y agrícola monumental dedicada a ensalzar la aceituna de mesa (manzanilla y gordal) con el acto de la "Aceituna de Oro", desfiles de carrozas y casetas. Se celebra en Septiembre. Declarada Fiesta de Interés Turístico de Andalucía. Al ser el principal productor de aceituna de mesa del mundo, su hito culinario y agrícola es un acontecimiento masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41012','fiesta','Fiestas en honor a Nuestro Padre Jesús del Socorro y las Fiestas de Santiago / Paso de Hermandades de El Rocío','Procesión patronal de gran devoción, y hito etnográfico masivo al ser uno de los puntos clave del "Paso del Vado del Quema" de las carretas hacia el Rocío. Se celebra en Octubre (Socorro) y Mayo/Junio (Paso del Quema). El paso de las carretas flamencas rocieras cruzando el río Guadiamar a su paso por el municipio es una de las estampas folclóricas más famosas y fotografiadas del país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41013','fiesta','Fiestas de las Cruces de Mayo y Feria del Minero','Tradición folclórica de piques populares entre las Cruces de la localidad, y feria de verano de origen minero obrero. Se celebra en Mayo (Cruces) y Agosto (Feria). Mucha animación vecinal en la transición entre la Campiña y los inicios de Sierra Morena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41014','fiesta','Feria de Agosto y Fiestas Patronales de la Virgen del Socorro','Feria de verano con casetas, potentes verbenas nocturnas, carreras de cintas y competiciones deportivas. Se celebra en Agosto. Ambiente muy festivo y de retorno estival con una fuerte vinculación a las tierras del Genil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41015','fiesta','Fiestas de las Nieves (Festa de la Virgen de las Nieves) y el "Toro de Fuego"','Fiestas patronales que destacan por la quema de espectaculares y tradicionales "toros de fuego" (estructuras metálicas con pirotecnia llevadas a hombros) por las calles del centro. Se celebra en Agosto. Declarada de Interés Turístico Provincial por la gran vistosidad, peligro y arraigo de sus artefactos de pólvora.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41016','fiesta','Romería de Cuatrovitas y Feria de Septiembre','Una de las romerías más antiguas y multitudinarias del Aljarafe (donde la patrona viaja en carretas flamencas hacia su ermita, una joya mudéjar del siglo XII), junto a su feria de casetas. Se celebra en Octubre (Romería) y Septiembre (Feria). La Romería de Cuatrovitas está declarada de Interés Turístico de Andalucía, congregando a decenas de miles de caballistas y peregrinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41017','fiesta','Feria de Bormujos y Fiestas de Santo Domingo de Guzmán','Macro-feria urbana metropolitana, con un gran recinto ferial, ferias de mediodía multitudinarias y grandes conciertos nacionales de pop/rock. Se celebra en Agosto. Una de las ferias veraniegas del Aljarafe con mayor infraestructura y un ambiente juvenil muy vibrante). Dime si deseas que continuemos directamente con el siguiente bloque de la letra C hasta la E de Sevilla (Brenes, Burguillos, Las Cabezas de San Juan, Camas, La Campana, Cantillana, Cañada Rosal, Carmona, Carrión de los Céspedes, Casariche, Castilblanco de los Arroyos, Castilleja de Guzmán, Castilleja de la Cuesta, Castilleja del Campo, El Castillo de las Guardas, Cazalla de la Sierra, Constantine, Coria del Río, Coripe, El Coronil, Los Corrales, El Cuervo de Sevilla, Dos Hermanas, Écija.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41018','fiesta','Feria de Brenes y Fiestas de la Virgen del Rosario','Feria tradicional de la Vega del Guadalquivir con casetas, paseos de caballos y verbenas. Se celebra en Octubre. Festa local muy populosa y centrada en la celebración tras el final de las campañas hortofrutícolas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41019','fiesta','Fiestas en honor a la Virgen del Rosario','Fiestas patronales, procesión solemne que atrae a la comarca, ferias de mediodía y orquestas nocturnas. Se celebra en Octubre. Excelente ambiente vecinal en las primeras estribaciones de la Sierra Norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41020','fiesta','Feria de San Juan Bautista y Semana Santa','Feria mayor de casetas flamencas con exhibiciones ecuestres y Semana Santa de gran devoción. Se celebra en Junio (Feria) y Marzo/Abril (Semana Santa). Feria histórica del Bajo Guadalquivir con gran despliegue de caballistas y enganches.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41021','fiesta','Feria de Camas en honor a la Virgen de los Dolores','Macro-feria urbana metropolitana, con un gran recinto ferial, conciertos y potentes verbenas. Se celebra en Septiembre. Mucha participación juvenil debido a su gran cercanía e interconexión con Sevilla capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41022','fiesta','Feria de San Lorenzo y Fiesta del Aceite de Oliva','Feria tradicional de verano y muestra agroalimentaria para ensalzar los aceites de la comarca. Se celebra en Agosto. Ambiente muy acogedor y de marcado carácter agrario en la Campiña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41023','fiesta','Fiestas de la Asunción (La Asunción de Cantillana) y Fiestas de la Divina Pastora','Hito mariano monumental. Destaca la espectacular "Subida de la Virgen" en su trono y el momento en que se le retira el velo ante miles de fieles que lanzan toneladas de flores y vítores. Se celebra en Agosto (Asunción) y Septiembre (Divina Pastora). Declaradas de Interés Turístico de Andalucía. Poseen un fervor pasional y una espectacularidad estética extrema que atrae a miles de visitantes de toda España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41901','fiesta','Fiesta de los Colonos (Festa de San Joaquín y Santa Ana)','Recreación histórica, folclórica y gastronómica que conmemora la fundación del pueblo por Carlos III con colonos centroeuropeos, manteniendo recetas y bailes singulares. Se celebra en Julio. Muy singular en la comarca de Écija por la preservación de su herencia e identidad centroeuropea.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41024','fiesta','Feria de Carmona, Romería de la Virgen de Gracia y Semana Santa de Carmona','Feria señorial de gran solera (desde 1466), romería multitudinaria y Semana Santa de altísima relevancia artística con pasos antiguos que desfilan por su conjunto amurallado. Se celebra en Mayo (Feria), Septiembre (Romería) y Marzo/Abril (Semana Santa). Declaradas de Interés Turístico Nacional de Andalucía. Sus desfiles históricos y el marco monumental de su judería y alcázares dotan a todas sus fiestas de un empaque aristocrático insuperable.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41025','fiesta','Fiestas de la Virgen de Consolación (El Rosarito)','Tradición mariana del Aljarafe caracterizada por el desfile de caballos engalanados, arcos de flores en las calles y tracas de pólvora. Se celebra en Octubre. Mucha devoción vecinal con "piques" tradicionales muy pasionales en torno a la decoración efímera de las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41026','fiesta','Feria de Santiago Apóstol y Fiesta de los Romanos (Fiestas Romanas de Ventippo)','Feria mayor de casetas y festival de recreación histórica romana en las canteras y ruinas de la antigua ciudad. Se celebra en Julio (Feria y Fiestas Romanas). Sus jornadas de teatro y zoco romano en la cantera histórica poseen un encanto plástico espectacular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41027','fiesta','Feria de Castilblanco y Romería de San Benito Celofán','Romería de gran solera serrana con bueyes y caballistas, y feria veraniega de casetas andaluzas. Se celebra en Agosto. La romería de San Benito congrega a miles de peregrinos de toda la Sierra del Norte y la Vega del Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41028','fiesta','Fiestas Patronales de San Benito Abad','Feria local de casetas, verbenas nocturnas y actividades lúdico-culturales. Se celebra en Julio. Fiesta de carácter marcadamente residencial y vecinal en el balcón del Aljarafe.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41029','fiesta','Semana Santa de Castilleja y Feria de la Inmaculada Concepción','Hito mariano y religioso del Aljarafe con la histórica y feroz rivalidad entre la Hermandad de la Calle Real ("los de la Plaza") y la Hermandad de la Inmaculada ("los del Lugar"). Famosa procesión del Domingo de Resurrección con la "Vuelta". Se celebra en Marzo/Abril (Semana Santa) y Diciembre (Feria). Declarada de Interés Turístico de Andalucía. Es una de las manifestaciones de rivalidad cofrade más pasionales, estéticas y multitudinarias del sur del país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41030','fiesta','Fiestas en honor a San Miguel Arcángel y la Virgen del Buen Suceso','Fiestas patronales tradicionales, carreras de cintas a caballo y verbenas populares en la plaza. Se celebra en Agosto. Ambiente típicamente agrícola y familiar en los límites con Huelva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41031','fiesta','Feria de Agosto y Romería de la Inmaculada Concepción','Feria tradicional serrana con concursos ganaderos, peñas festivas y romería en el monte. Se celebra en Agosto. Muy concurrida por los veraneantes de la capital y amantes de las tradiciones del Andévalo oriental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41032','fiesta','Feria de Cazalla y Fiestas de la Virgen del Monte / Fiesta del Aguardiente','Una de las ferias con más empaque de la sierra, que incluye paseos ecuestres monumentales y la puesta en valor gastronómica de sus famosos licores de guindas y aguardientes tradicionales. Se celebra en Agosto. Referente lúdico absoluto de la Sierra Norte; sus casetas abiertas y el ambiente hípico saturan de visitantes la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41033','fiesta','Feria de Constantina y Semana Santa','Gran feria andaluz de casetas de madera en el Paseo de la Alameda, corridas de toros, y Semana Santa de sobrio señorío serrano. Se celebra en Agosto. Feria señorial que ejerce una enorme atracción comercial y lúdica en toda la comarca norteña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41034','fiesta','Feria de Coria del Río y la Fiesta de los Japoneses (Hasekura Tsunenaga)','Gran feria de casetas junto al río Guadalquivir, y singulares actos culturales que conmemoran la llegada de la expedición samurái de 1614 con farolillos flotantes (Toro Nagashi). Se celebra en Septiembre (Feria) y Octubre (Cultura Japonesa). Su ceremonia del Toro Nagashi flotante en el río Guadalquivir es única en España, atrayendo a delegaciones de Japón y numeroso turismo cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41035','fiesta','Fiesta del Judas de Coripe y Feria de Septiembre','Rito folclórico nacional. El Domingo de Resurrección los vecinos tirotean con escopetas de salva y queman a un muñeco de trapo (el Judas) que cada año encarna a un personaje público polémico del panorama internacional. Se celebra en Marzo/Abril (Judas). Declarada Fiesta de Interés Turístico Nacional de Andalucía por la enorme singularidad y repercusión mediática global que rodea al linchamiento lúdico del muñeco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41036','fiesta','Feria de San Roque y Fiestas de las Cruces de Mayo','Feria de verano con casetas andaluzas, verbenas populares junto a su torre medieval y procesión de cruces. Se celebra en Agosto. Arraigo vecinal con gran protagonismo del mundo del caballo y enganches en la campiña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41037','fiesta','Feria de Agosto en honor a la Virgen del Buensuceso','Feria local de casetas, carreras de cintas, comidas colectivas en la plaza y orquestas nocturnas. Se celebra en Agosto. *. Ambiente muy festivo e impregnado de las costumbres agrarias de la Sierra Sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41903','fiesta','Romería de Nuestra Señora del Rosario y Feria de El Cuervo','Romería multitudinaria compartida en el Parque de San José de la Pista, y feria de casetas tradicionales. Se celebra en Mayo (Romería) y Octubre (Feria). La romería congrega a millares de personas de las provincias de Sevilla y Cádiz debido a su enclave fronterizo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41038','fiesta','Romería de Valme y Feria de Dos Hermanas','Hito etnográfico monumental. Es una de las romerías más populosas de España, famosa por sus singulares carretas cubiertas por miles de flores de papel rizado hechas a mano. Gran macro-feria de casetas urbanas. Se celebra en Octubre (Romería) y Mayo (Feria). La Romería de Valme está declarada Fiesta de Interés Turístico Nacional; un espectáculo visual cromático inigualable en el que participan más de 200.000 personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41039','fiesta','Real Feria de Septiembre de Écija y Semana Santa de Écija','Feria señorial histórica concedida por los Reyes Católicos en un gran recinto de casetas permanentes, y Semana Santa de incalculable valor barroco con monumentales pasos. Se celebra en Septiembre (Feria) y Marzo/Abril (Semana Santa). Declaradas de Interés Turístico Nacional de Andalucía. La Semana Santa destaca por el señorío de sus hermandades desfilando ante las famosas once torres barrocas del plano urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41040','fiesta','Feria de Espartinas en honor a la Virgen de Loreto','Feria del Aljarafe con casetas tradicionales, ferias de mediodía multitudinarias, paseos hípicos y conciertos pop. Se celebra en Septiembre. Mucha afluencia de público joven y residencial del entorno metropolitano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41041','fiesta','Feria de la Mantecá (Feria de Septiembre) y Fiestas del Octavio de la Asunción','Feria tradicional de casetas andaluzas que coincide con el inicio del bullir industrial de sus famosas fábricas de mantecados y polvorones. Se celebra en Septiembre. Capital mundial del mantecado; la feria marca el preludio de su gran campaña navideña con un ambiente festivo muy activo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41042','fiesta','Carnaval de Fuentes de Andalucía y Feria de Agosto','Carnaval histórico único caracterizado por la figura de la "Máscara" (disfraz grotesco con colchas y trapos que parodia la actualidad ocultando la voz con un falsete) y la murga tradicional, junto a su feria mayor. Se celebra en Febrero (Carnaval). Declarado de Interés Turístico de Andalucía por conservar con pureza este carnaval de máscaras e ingenio oral durante la dictadura.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41043','fiesta','Fiestas de la Virgen de la Estrella','Feria local de casetas, procesiones tradicionales de la patrona y actividades lúdicas serranas. Se celebra en Agosto. Fiesta pequeña y de ambiente familiar a las puertas de la Ruta de la Plata.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41044','fiesta','Feria de Gelves y Fiesta de la Artesanía y la Náutica','Feria urbana junto al río Guadalquivir, conciertos, actividades náuticas en Puerto Gelves y verbenas de noche. Se celebra en Agosto. El puerto fluvial dota a la feria de mediodía de un atractivo costero interior muy concurrido en el área metropolitana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41045','fiesta','Feria de Gerena en honor a la Virgen de la Encarnación','Feria tradicional con casetas, paseos de caballos, verbenas de noche y actividades lúdicas vinculadas a su tradición de canteras de granito. Se celebra en Mayo. Gran ambiente de hermandad en la transición a la sierra minera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41046','fiesta','Fiesta de la Alborá (Fiesta de Gilena) y Feria de Agosto','Rito musical religioso nocturno donde los vecinos recorren el pueblo entonando cánticos con tambores y caracolas por la Virgen de la Aurora, junto a su feria estival. Se celebra en Octubre (Alborá) y Agosto (Feria). Su ancestral canto de la Alborá posee un altísimo valor etnográfico en la Sierra Sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41047','fiesta','Una Pará en Gines y Feria de San Ginés / Salida de las Carretas hacia El Rocío','Macro-evento etnográfico e hípico nacional (con concursos de bueyes, enganches y ferias comerciales) y la mítica e histórica salida masiva de sus carretas flamencas cruzando el pueblo hacia Doñana. Se celebra en Septiembre (Una Pará en Gines) y Mayo/Junio (Rocío). La Pará en Gines está declarada Fiesta de Interés Turístico de Andalucía, siendo una macro-muestra de las tradiciones camperas del Aljarafe que reúne a más de 50.000 visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41048','fiesta','Feria de Guadalcanal y Romería de la Virgen de Guaditoca','Feria tradicional serrana con peñas festivas, verbenas al aire libre y masiva romería compartida con bueyes y caballos. Se celebra en Agosto (Feria) y Septiembre (Romería). Mucha devoción en los confines norteños de la provincia, atrayendo a familias de Extremadura.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41049','fiesta','Feria de Guillena en honor a la Virgen de la Granada y Cabalgata Viviente de Reyes Magos de Las Pajanosas','Gran feria andaluza con casetas, ferias de mediodía multitudinarias, eventos ecuestres y una famosa cabalgata viviente navideña en su pedanía. Se celebra en Septiembre (Feria). Foco festivo muy dinámico en el acceso norte metropolitano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41050','fiesta','Semana Santa de Herrera y Feria de Agosto','Semana Santa singular caracterizada por las representaciones corporativas de las "Corporaciones Bíblicas" y los rostricos (máscaras de cera), combinada con su feria de casetas. Se celebra en Marzo/Abril (Semana Santa). Declarada de Interés Turístico de Andalucía por el incalculable valor antropológico de sus desfiles bíblicos, compartidos con Puente Genil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41051','fiesta','Fiestas de la Caldereta de Huévar y Feria de la Virgen de la Sangre','Gastronómica (degustación masiva de su tradicional guiso campera de carne de cordero cocinada a la leña) y feria mayor de casetas flamencas. Se celebra en Enero (Caldereta) y Septiembre (Feria). Su fiesta de la Caldereta invernal es un referente culinario muy popular en todo el Aljarafe occidental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41902','fiesta','Feria de la Isla del Arroz (Feria de Isla Mayor) y Fiesta del Cangrejo de Río','Muestra comercial, lúdica y gastronómica dedicada a sus marismas y cultivos de arroz con degustaciones masivas de paellas y cangrejos de río, junto a su feria de casetas. Se celebra en Septiembre. Entorno único de las marismas de Doñana; su feria gastronómica ensalza la mayor producción de arroz de España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41052','fiesta','Feria de Lantejuela en honor a la Virgen del Rosario','Feria local de casetas, carreras de cintas en moto, orquestas nocturnas y actividades infantiles. Se celebra en Octubre. Ambiente muy festivo y familiar centrado en la convivencia de la campiña central.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41053','fiesta','Las Cruces de Mayo de Lebrija, Caracolá Lebrijana y Feria de San Denis','Espectáculo folclórico mariano (las mujeres bailan las tradicionales "Sevillanas Corraleras" alrededor de los altares de las cruces), uno de los festivales flamencos más importantes del país (Caracolá) y feria mayor. Se celebra en Mayo (Cruces) y Julio (Caracolá). Las Cruces de Mayo están declaradas de Interés Turístico de Andalucía por su asombrosa belleza coral y las corraleras. La Caracolá es una meca indiscutible para el flamenco purista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41054','fiesta','Fiestas Patronales de San Marcos','Fiestas patronales tradicionales, meriendas de pan y hornazo en el campo, procesión y verbenas de verano trasladas. Se celebra en Julio (traslado estival). Municipio de baja población; la fiesta ofrece una atmósfera rural e íntima de gran calidez.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41055','fiesta','Feria de Lora del Río y Romería de Nuestra Señora de Setefilla','Feria mayor andaluza de casetas, paseo de caballos y peregrinación multitudinaria de tradición medieval con salvas de pólvora e "idas y venidas" irregulares de la Virgen. Se celebra en Mayo (Feria) y Septiembre (Romería/Cultos festivos). La Romería de Setefilla está declarada de Interés Turístico de Andalucía por ser uno de los fenómenos de devoción y folclore religioso más antiguos, pasionales y multitudinarios de la Vega del Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41056','fiesta','Feria de la Inmaculada Concepción y Fiestas Fundacionales','Feria tradicional de casetas y conmemoración histórica institucional de su origen ilustrado carolina del siglo XVIII. Se celebra en Agosto (Feria) y Marzo (Fundacionales). Destaca la fisonomía de sus fiestas ligada a su identidad urbana como Nuevas Poblaciones de Carlos III.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41057','fiesta','Fiestas en honor a la Virgen del Rosario','Procesiones tradicionales, verbenas de verano y comidas populares camperas. Se celebra en Agosto. Municipio de baja población; la fiesta destaca por su ambiente íntimo de reencuentro en la frontera con Huelva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41058','fiesta','Feria de Mairena del Alcor y Festival de Cante Jondo Antonio Mairena','La feria más antigua de Andalucía (fundada por Alfonso XI en 1441) con un monumental recinto de casetas, y prestigioso festival internacional de flamenco puro. Se celebra en Abril (Feria) y Septiembre (Festival). Declarada Fiesta de Interés Turístico Nacional de Andalucía. Su feria es pionera e histórica, sirviendo de inspiración para la Feria de Abril de Sevilla capital. Su festival de flamenco es de máxima categoría cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41059','fiesta','Feria de Mairena del Aljarafe','Macro-feria urbana moderna con un inmenso recinto ferial, grandes ferias de mediodía de gran afluencia y potentes conciertos de bandas de pop/rock nacional. Se celebra en Junio. Por su volumen demográfico, es una de las ferias del cinturón metropolitano de Sevilla con mayor vitalidad y ocio juvenil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41061','fiesta','Feria de Santiago y Semana Santa Alternativa','Feria popular de carácter obrero-reivindicativo con conciertos de rock, comidas comunales gratuitas en la calle y actividades autogestionadas. Se celebra en Julio. Fiesta de enorme singularidad política y social en España, atrayendo a numerosos curiosos de todo el país por su modelo de organización asamblearia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41062','fiesta','Feria del Carmen y Fiesta de la Cinta','Feria tradicional con casetas, carreras de cintas a caballo, torneos deportivos y orquestas de noche. Se celebra en Julio. Ambiente puramente familiar de la Sierra Sur, centrado en el reencuentro veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41063','fiesta','Feria de la Seda de Los Molares y Feria de Santa Marta','Espectacular festival de recreación histórica y mercado de época que conmemora su célebre feria de paños y sedas del siglo XV en torno a su castillo medieval. Se celebra en Octubre (Feria de la Seda). Su recreación de la Feria de la Seda es de los mercados medievales con más tipismo y crecimiento turístico del Bajo Guadalquivir.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41064','fiesta','Romería de San Isidro Labrador y Feria de Agosto','Romería andaluza multitudinaria con carretas engalanadas con ramas de olivo y flores de papel que suben a la Sierra de San Pablo, y feria de casetas. Se celebra en Mayo (Romería). La Romería de San Isidro de Montellano está declarada de Interés Turístico de Andalucía por la asombrosa belleza de sus paisajes y la hospitalidad de sus peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41065','fiesta','Feria de Morón, Festival de Flamenco "Gazpacho Andaluz" y Fiestas de la Inmaculada (La Quema de las Barbas de San José)','Gran feria andaluza, uno de los festivales flamencos más antiguos del país (tierra del toque de guitarra de Morón) y quema tradicional de hogueras. Se celebra en Septiembre (Feria y Gazpacho). El festival del Gazpacho Andaluz está declarado de Interés Turístico por su incalculable valor en la salvaguarda del flamenco purista y su arraigo cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41066','fiesta','Fiestas Patronales de la Virgen de la Belén','Fiestas tradicionales serranas, migas colectivas en la plaza del pueblo y verbenas populares al fresco de la noche. Se celebra en Agosto. Conservación impecable de las costumbres y el ambiente acogedor del Parque Natural de la Sierra Norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41067','fiesta','Mercado Barroco de Olivares y Feria de las Nieves','Gran hito de recreación histórica internacional. El pueblo retrocede al Siglo de Oro bajo el mecenazgo del Conde-Duque de Olivares con teatros barrocos de calle, zocos de oficios antiguos y trajes cortesanos de época. Se celebra en Mayo (Mercado Barroco). Declarado de Interés Turístico de Andalucía. Transforma por completo su monumental plaza e iglesia colegial, convirtiéndose en un referente nacional de turismo cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41068','fiesta','Real Feria de Mayo de Osuna y Semana Santa de Osuna','Una de las ferias más antiguas y señoriales de la provincia (desde el siglo XVIII) con paseos hípicos y corridas en su histórica plaza de toros. Semana Santa monumental con desfiles entre iglesias y palacios barrocos. Se celebra en Mayo (Feria) y Marzo/Abril (Semana Santa). Declaradas de Interés Turístico Nacional de Andalucía. La feria posee un empaque aristocrático andaluz único y la Semana Santa destaca por el marco arquitectónico inigualable de su villa ducal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41069','fiesta','Feria de Los Palacios en honor a la Virgen de las Nieves, y Feria Agroganadera de la Marisma','Macro-feria andaluza de grandes dimensiones con cientos de casetas y paseos de enganches, combinada con una de las muestras ganaderas de compraventa real más importantes de España. Se celebra en Septiembre (Feria) y Abril (Feria Agroganadera). Su Feria Agroganadera (desde el siglo XIX) es una meca de tratos comerciales ganaderos e hípicos a nivel nacional, atrayendo a decenas de miles de profesionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41070','fiesta','Feria de Palomares y Fiestas de la Virgen de la Estrella','Feria local metropolitana con casetas, ferias de mediodía en sus plazas y competiciones de doma vaquera. Se celebra en Septiembre. Mucha participación vecinal potenciada por su crecimiento residencial en el Aljarafe.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41071','fiesta','Semana Cultural Flamenca de Paradas y Feria de Mayo','Feria tradicional de casetas andaluzas y prestigiosas jornadas culturales consagradas al estudio y recitales de flamenco de máxima categoría. Se celebra en Mayo. Su Semana Flamenca es un bastión intelectual y de cante purista muy reconocido por los grandes críticos musicales del país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41072','fiesta','Fiesta del Carnaval de Pedrera (Entierro de la Sardina) y Feria de Agosto','Carnaval histórico único en la Sierra Sur, famoso por el multitudinario "entierro de la sardina" donde los vecinos se visten de riguroso luto artesanal en una parodia colectiva. Se celebra en Febrero (Carnaval). Declarado de Interés Turístico de Andalucía debido a la singularidad, coplas y enorme implicación vecinal en la calle previa a la Cuaresma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41073','fiesta','Feria de Muestras de Productos Típicos y Artesanales de la Sierra Norte de Sevilla','Macro-feria gastronómica y comercial de invierno. El pueblo entero se transforma en un inmenso mercado donde se exponen y degustan embutidos ibéricos, quesos, mieles, castañas y carnes de caza. Se celebra en Diciembre. Convertida en la feria agroalimentaria de invierno más exitosa y multitudinaria de la provincia; satura por completo las comunicaciones de la sierra con más de 100.000 visitantes en el puente de diciembre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41074','fiesta','Feria de Agosto y Fiestas del Cristo de la Almoraima','*. Feria mayor de casetas, procesiones tradicionales de ribera, carreras de cintas en moto y verbenas populares. *. Se celebra en Agosto. *. Fiesta participativa en el límite geográfico que separa Sevilla de Córdoba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41075','fiesta','Fiesta de las Carreritas (Domingo de Resurrección) y Feria de la Virgen del Rocío','Tradición etnográfica pasional única. Consiste en una veloz e impresionante carrera que los portadores de los tronos de la Virgen y el Niño realizan en la plaza del pueblo para encontrarse tras la Resurrección. Se celebra en Marzo/Abril (Carreritas) y Junio (Feria). Declarada Fiesta de Interés Turístico de Andalucía por el tremendo fervor popular, la velocidad de los tronos y la singular belleza plástica del rito.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41076','fiesta','Romería de la Virgen de la Pura y Limpia Concepción y Feria de Agosto','Peregrinación campestre multitudinaria al paraje natural de la ermita de la Navas con carretas engalanadas tiradas por bueyes y caballistas, junto a su feria lúdica. Se celebra en Mayo (Romería). Una de las romerías de mayor identidad y fervor de la Sierra Sur, atrayendo a muchos pueblos colindantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41077','fiesta','Reunión de Cante Jondo de La Puebla de Cazalla y Feria de Septiembre','Una de las citas mundiales más importantes y puristas del flamenco (fundada por el pintor Francisco Moreno Galván), sin megafonía estridente, celebrada en una plaza monumental, combinada con su feria de casetas. Se celebra en Julio (Reunión Flamenca) y Septiembre (Feria). La Reunión de Cante Jondo está declarada de Interés Turístico; es una meca indiscutible del flamenco intelectual, atrayendo a estudiosos y artistas de todo el planeta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41078','fiesta','Las Las Candelas de La Puebla de los Infantes y Feria de Agosto','Rito etnográfico de invierno de gran calado. Consiste en la quema de decenas de hogueras monumentales por todos los barrios sobre las que se colocan "muñecos" satíricos, acompañadas de cantos tradicionales de "sanjuanes" y asados de chorizo. Se celebra en Febrero (Las Candelas). Declarada de Interés Turístico de Andalucía por conservar con total pureza estas lumbres tradicionales de convivencia comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41079','fiesta','Encierros de San Sebastián de La Puebla del Río y Corpus Christi','Los encierros de toros y novillos de calle más famosos e históricos del sur de España (con un estilo similar a los Sanfermines), acompañados de chupinazos, capeas en su plaza de toros y macro-ferias de mediodía. Se celebra en Enero (San Sebastián). Declarados de Interés Turístico de Andalucía. Reúnen en una sola mañana de invierno a más de 50.000 personas de toda la comunidad para correr o presenciar las reses en los márgenes de las marismas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41080','fiesta','Feria de San Bartolomé y Fiesta del Queso Artesano','Feria mayor de casetas andaluzas junto a su histórico castillo y muestra gastronómica dedicada a los lácteos tradicionales de la sierra. Se celebra en Agosto. Excelente ambiente serrano y ganadero en el nudo de comunicación con Extremadura.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41081','fiesta','Feria de La Rinconada y Feria de San José de la Rinconada','Dos grandes ferias anuales independientes correspondientes a sus dos núcleos de población, con inmensos recintos feriales, conciertos y ferias de día. Se celebra en Junio (La Rinconada) y Septiembre (San José). Por su volumen demográfico e industrial, sus ferias son de las más vibrantes y con mayor presupuesto lúdico de la Vega de Sevilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41082','fiesta','Semana Santa de La Roda de Andalucía y Feria de Agosto','Semana Santa de inmenso fervor y arraigo caracterizada por la tradicional y pacífica rivalidad de "los piques" de las hermandades ferroviarias, y feria de verano. Se celebra en Marzo/Abril (Semana Santa). Declarada de Interés Turístico de Andalucía por la asombrosa riqueza de su imaginería barroca y el empaque cofrade en la Sierra Sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41083','fiesta','Feria de El Ronquillo en honor a Nuestra Señora de Gracia','Feria tradicional de la sierra con casetas de lona, suelta de vaquillas por el casco urbano, verbenas populares y carreras de cintas. Se celebra en Agosto. Muy concurrida por los habitantes de Sevilla capital que buscan el fresco estival de la dehesa de la Ruta de la Plata.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41084','fiesta','Feria de Agosto de El Rubio y Festival de Música Gallape Rock','Feria de verano con casetas andaluzas tradicionales y potentes festivales musicales veraniegos de rock/punk de gran tirón juvenil. Se celebra en Agosto (Feria) y Septiembre (Gallape Rock). Su festival de rock atrae a miles de jóvenes de toda Andalucía, dinamizando la comarca agraria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41085','fiesta','Fiestas Patronales de Nuestra Señora de la Oliva','Procesiones solemnes de gran lujo barroco (tierra de las bandas de música de cornetas y tambores de Oliva y el Carmen de Salteras de fama mundial) y feria de casetas. Se celebra en Febrero. Su condición de cuna de la música de banda cofrade dota a sus festividades de una calidad sonora e importancia cofrade espectacular en el Aljarafe.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41086','fiesta','Fiestas de San Juan Bautista','Feria metropolitana con un recinto de casetas junto al río Guadalquivir, verbenas nocturnas, actividades deportivas y hogueras de San Juan en la ribera. Se celebra en Junio. Mucha participación y animación juvenil debido a su conexión directa por metro con la capital provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41088','fiesta','Fiesta del Terror de San Nicolás del Puerto y Feria de San Diego','Curiosísima y multitudinaria festividad de verano donde el pueblo entero (aprovechando sus parajes naturales de las Cascadas del Huéznar) se decora de forma terrorífica con pasacalles de zombies, aquelarres y monstruos. Se celebra en Julio (Fiesta del Terror). Su Fiesta del Terror es única en Andalucía; atrae a masas de turismo joven y familiar y satura los alojamientos rurales de la Sierra Norte.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41087','fiesta','Feria de Sanlúcar la Mayor y Semana Santa de Sanlúcar','Gran feria andaluza monumental (de las más antiguas y elegantes del Aljarafe, con casetas estables de madera) y desfiles procesionales barrocos de gran señorío. Se celebra en Mayo (Feria). Se erige como el gran epicentro lúdico, comercial y de diversión de la comarca del Aljarafe occidental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41089','fiesta','Vía Crucis del Aljarafe en las Ruinas de Itálica y Feria de San Isidoro / Ruta de la Tapa Romana','Impresionante acto místico y litúrgico nocturno donde las hermandades portadoras de antorchas rezan en el interior del Anfiteatro de la Ciudad Romana de Itálica real, combinado con gastronomía arqueológica. Se celebra en Febrero/Marzo (Vía Crucis) y Octubre (Feria). Declarado de Interés Turístico de Andalucía. Su Vía Crucis nocturno en las ruinas de Itálica ofrece un marco plástico, místico y patrimonial único en el mundo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41090','fiesta','Fiestas Patronales de San Marcos y la Virgen del Rosario / Fiesta de la Tapa de El Saucejo','Fiestas tradicionales con su tradicional reparto de roscos bendecidos, ferias de mediodía y orquestas de noche. Se celebra en Abril (San Marcos) y Agosto (Feria). Mucha implicación vecinal en las dehesas agrícolas de la comarca sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41091','fiesta','Feria de Abril de Sevilla y Semana Santa de Sevilla','Los dos hitos festivos marianos, costumbristas y folclóricos absolutos del sur de España. Semana Santa monumental de máxima categoría mundial y la Feria de Abril con más de 1.000 casetas de lona, enganches, paseos de caballos aristocráticos y corridas de toros en la Maestranza. Se celebra en Marzo/Abril (Semana Santa) y Abril/Mayo (Feria de Abril). Declaradas de Interés Turístico Internacional. Ambas fiestas paralizan por completo la ciudad y atraen a millones de turistas de todos los continentes, configurando los mayores espectáculos etnográficos, estéticos y económicos del país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41092','fiesta','Fiestas de la Función del Señor de la Vera Cruz y Feria de Los Rosales','*. Fiestas de gran devoción religiosa barroca con impresionantes tracas de fuegos artificiales piromusicales, y feria de casetas andaluzas. *. Se celebra en Septiembre. *. Gran ambiente de hermandad en la Vega del Guadalquivir, con una comunidad vecinal muy implicada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41093','fiesta','Feria de Tomares y Feria de la Tapa de Tomares','Feria de grandes dimensiones con un pulcro recinto de casetas andaluzas, ferias de mediodía de gran renombre gastronómico y conciertos pop nacionales. Se celebra en Septiembre. Su alta renta demográfica impulsa una feria con excelentes infraestructuras y un ambiente de casetas muy refinado en el Aljarafe.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41094','fiesta','Fiesta del Mosto y de la Aceituna Fina de Umbrete y Feria de San Bartolomé','Macro-muestra gastronómica y agrícola en la plaza donde las bodegas locales y cooperativas regalan miles de litros de vino mosto fresco del año acompañado de aceitunas finas del Aljarafe y asados de cerdo. Se celebra en Noviembre (Fiesta del Mosto). Declarada de Interés Turístico de Andalucía; es la gran cita culinaria y enológica de otoño que congrega a millares de gastrónomos de toda la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41095','fiesta','Feria de Consolación de Utrera, Semana Santa y el Potaje Gitano de Utrera','Gran feria andaluza monumental con un inmenso recinto ferial, el festival flamenco más antiguo de España ("Potaje Gitano" desde 1957) celebrado en el marco de la feria, y Semana Santa señorial. Se celebra en Septiembre (Feria de Consolación y Potaje). Declarada Fiesta de Interés Turístico de Andalucía. Su Feria de Consolación es de las más grandes del Bajo Guadalquivir tras la capital. El Potaje Gitano es una institución de la música flamenca mundial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41096','fiesta','Romería de Torrijos y Fiestas del Cristo de la Vera Cruz','Hito etnográfico multitudinario. Es la romería de carretas flamencas tiradas por bueyes y caballos más populosa del Aljarafe y la cuarta más grande de Andalucía, viajando a la Hacienda de Torrijos (una joya mudéjar). Se celebra en Octubre (Romería de Torrijos). Declarada de Interés Turístico de Andalucía. Reúne a más de 50.000 personas en una hermosa jornada campera que marca el cierre de las romerías de otoño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41097','fiesta','Fiestas de la Virgen del Rocío y el Paso de Hermandades de Villamanrique (La Fiesta de los Bueyes)','Joya folclórica rociera. Consiste en el espectacular e histórico recibimiento y parada que los bueyes y carretas flamencas de decenas de hermandades realizan subiendo los escalones de la iglesia del pueblo rumbo al Rocío. Se celebra en Mayo/Junio. Declarada de Interés Turístico de Andalucía. Posee un valor antropológico e histórico incalculable, atrayendo a miles de fotógrafos del mundo por la fuerza de las yuntas de bueyes subiendo los escalones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41100','fiesta','Fiestas Patronales de San Juan Bautista y Fiesta del Huerto de San Juan','Curiosa e histórica festividad donde los vecinos construyen un "huerto artificial" en la plaza del pueblo con verduras, hortalizas y animales reales para subastarlos con fines benéficos. Se celebra en Junio. Gran valor folclórico y etnográfico por la conservación de sus costumbres agrícolas serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41101','fiesta','Feria en honor a Nuestra Señora de las Aguas','Feria mayor de casetas, procesiones tradicionales junto a las riberas fluviales, verbenas populares y carreras de cintas. Se celebra en Septiembre. Mucha participación local con un fuerte arraigo cofrade y de convivencia de la vega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41102','fiesta','Fiestas de la Santa Cruz y Fiestas Patronales de la Virgen de los Reyes / Romería de Alcaudete','"Piques" tradicionales y coloridos de sus fiestas de las Cruces de Mayo con espectaculares fuegos artificiales, y multitudinaria romería campestre a la ermita de Alcaudete. Se celebra en Septiembre (Romería) y Mayo (Cruces). La Romería de Alcaudete está de Interés Turístico de Andalucía, congregando a millares de jinetes y carrozas engalanadas de la comarca de Los Alcores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90749','fiesta','Fiestas de San Joaquín y Santa Ana','Destaca su romería tradicional a la ermita de San Joaquín y el dance popular. Patronal y Etnográfica. Se celebra en Julio. Celebración de arraigo local y comarcal, muy vinculada al retorno estival de familiares y emigrantes de la comarca del Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90750','fiesta','Fiestas de San Victorían y la Fiesta de la Epifanía','Incluye representaciones de títeres ligadas a la tradición oral del Pirineo y la Casa de los Títeres. Patronal y Etnográfica. Se celebra en Enero y Agosto. Tradición local reforzada por su singularidad etnográfica en el Sobrarbe y el turismo cultural que atrae su patrimonio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90751','fiesta','Fiestas Patronales de San Pedro e intercesión de las Santas Nunilo y Alodia','Sobresale la Corrida de Peras, una carrera pedestre tradicional del Somontano cuyos premios históricos eran frutas. Patronal y Etnográfica. Se celebra en Agosto y Octubre. Evento de fuerte arraigo municipal con ritos etnográficos locales muy específicos del Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90674','fiesta','Fiestas de San Roque','Son célebres las actuaciones de su grupo de "As Enramas" y la presencia de los gigantes y cabezudos tradicionales bajo los imponentes Mallos de Agüero. Patronal y Etnográfica. Se celebra en Agosto. Atractivo local con gran potencial escénico por su ubicación geográfica, atrayendo a visitantes de la Hoya de Huesca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23001','fiesta','La Morisma de Aínsa y la Expoforga (Feria de la Comarca del Sobrarbe)','La Morisma es una recreación histórica de la batalla entre cristianos y moros del siglo VIII, declarada Fiesta de Interés Turístico de Aragón. Recreación Histórica, Patronal y Feria Comercial. Se celebra en Septiembre (La Morisma tiene carácter bienal) y Septiembre (Fiestas Mayores). Fiesta de Interés Turístico Regional con enorme valor histórico, artístico y un masivo impacto turístico en todo el Pirineo aragonés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90752','fiesta','Fiestas de San Miguel y las Fiestas de San Blas','Mantienen vivos los pasacalles de carrozas, las jotas aragonesas y las cenas populares al aire libre. Patronal y Gastronómica. Se celebra en Febrero y Septiembre. Celebraciones tradicionales de carácter puramente vecinal y comarcal en las vegas del Cinca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90753','fiesta','Fiestas en honor a San Andrés y a la Virgen del Buen Acuerdo','Destaca el tradicional reparto de pan bendito y los torneos de juegos tradicionales monegrinos. Patronal. Se celebra en Agosto y Noviembre. Festejos de arraigo estrictamente local, orientados a la convivencia vecinal y al reencuentro veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90754','fiesta','Fiesta de San Vicente y la célebre "Festa del Tossino" (Fiesta del Cerdo)','Esta última es una jornada gastronómica multitudinaria que recrea la matanza tradicional del cerdo con degustación masiva. Gastronómica y Etnográfica. Se celebra en Enero. Reconocimiento comarcal y provincial muy potente; es una de las fiestas gastronómicas invernales de referencia en la Litera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90755','fiesta','Fiestas del Santo Ángel Custodio','Centradas en misas tradicionales, campeonatos de guiote y verbenas nocturnas en la plaza mayor. Patronal. Se celebra en Mayo. Verbena y festejo de pueblo pequeño, con carácter familiar e interno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90756','fiesta','Fiestas de la Transfiguración del Señor','Pequeñas procesiones, comidas de hermandad y espectáculos infantiles componen su agenda principal. Patronal. Se celebra en Agosto. Festejos familiares de carácter local y de baja afluencia externa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90757','fiesta','Fiestas de la Virgen de la Rosa','Incluye la tradicional subida ciclista al cerro del pueblo y las verbenas populares a la sombra de su castillo. Se celebra en Agosto. Arraigo estrictamente local enfocado en actividades familiares para residentes y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90758','fiesta','Fiestas en honor a San Bartolomé y San José','Se celebran encierros tradicionales, vaquillas y comidas populares que reúnen a los núcleos de Tormos y Losangeles. Patronal y Taurina. Se celebra en Agosto. Festejos comarcales con buena animación local y taurina dentro de la Hoya de Huesca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90759','fiesta','Fiestas de San Miguel Arcángel','Conserva la bendición de campos y términos, además de juegos infantiles y orquestas. Patronal. Se celebra en Septiembre. Celebración clásica de núcleo pequeño orientada a la identidad comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90760','fiesta','Fiestas de San Ramón Nonato y Santa Margarita','Destaca el desfile de carrozas artesanales y las rondas de jotas por las calles empedradas del municipio. Patronal y Etnográfica. Se celebra en Agosto. Fuerte arraigo identitario en la comarca de la Litera, atrayendo a poblaciones vecinas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90761','fiesta','Fiestas del Santo Cristo de la Salud','Cuenta con una gran tradición ganadera reflejada en sus encierros, toros de fuego y las concurridas ferias locales. Patronal y Taurina. Se celebra en Septiembre. Atractivo comarcal destacado gracias a su afición taurina y eventos populares a orillas del Cinca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90762','fiesta','Fiestas en honor a San Ana','Son singulares sus dances tradicionales acompañados de gaita de boto aragonesa, un patrimonio folclórico recuperado de gran valor. Etnográfica y Patronal. Se celebra en Julio. Hito etnográfico singular en Los Monegros por la pureza y antigüedad de las mudanzas de su dance popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90763','fiesta','Fiestas de Santiago Apóstol','Pequeños torneos deportivos, hogueras tradicionales y bailes populares en la plaza del ayuntamiento. Patronal. Se celebra en Julio. Verbena de arraigo local orientada al reencuentro estival del vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90764','fiesta','Fiestas de Santa María Magdalena','Tradicionales cenas de alforja compartidas, juegos infantiles y sesiones de baile para el pueblo. Patronal. Se celebra en Julio. Celebración netamente familiar y vecinal con mínima proyección exterior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90765','fiesta','Fiestas de la Virgen de la Corona','Con un rico patrimonio folclórico, destacan su antiguo Dance de Almudévar, los toros de fuego y las bodegas subterráneas que abren sus puertas para peñas y catas gastronómicas. Patronal, Etnográfica y Gastronómica. Se celebra en Septiembre. Festividad con gran reconocimiento provincial; atrae a centenares de visitantes de Huesca capital por su proximidad y potencia cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90766','fiesta','Fiestas en honor a San Sebastián y la Virgen de la Piedad','Se organizan comidas populares, actividades en el polideportivo y pasacalles con charanga. Patronal. Se celebra en Agosto. Fiestas de arraigo local con excelente ambiente vecinal en el Cinca Medio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90767','fiesta','Fiestas de San Agustín','Procesión tradicional, puesta de pañuelicos a los nacidos en el año y verbenas nocturnas. Patronal. Se celebra en Agosto. Festejos enfocados a la comunidad local y al retorno de emigrantes por vacaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90272','fiesta','Fiestas en honor a San Hipólito y la recreación medieval de sus mercados','Aunque las patronales son locales, el entorno del castillo y la villa medieval genera una gran afluencia turística que complementa los actos culturales tradicionales. Patronal y Recreación Histórica. Se celebra en Agosto. Su espectacular patrimonio atrae un gran número de visitantes provinciales y nacionales durante sus semanas culturales de verano). Hemos completado el primer bloque de la provincia de Huesca (de la A a la Z, desde Abiego hasta Alquézar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22025','fiesta','Fiestas de San Bartolomé','Destacan las tradicionales orquestas, las competiciones de tiro al plato y el desfile de carrozas con una activa participación de peñas locales. Patronal. Se celebra en Agosto. Festejos con notable ambiente juvenil y comarcal dentro de la comarca de la Litera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22027','fiesta','Fiestas en honor a San Miguel Arcángel','Incluye procesiones a la iglesia parroquial, comidas de hermandad y campeonatos de guiote. Patronal. Se celebra en Septiembre. Celebración de arraigo puramente local orientada al reencuentro de vecinos de la Hoya de Huesca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22028','fiesta','Día de la Exaltación del Traje Ansotano','Fiesta declarada de Interés Turístico Nacional donde los vecinos desfilan luciendo joyas y trajes típicos del siglo de oro pirenaico guardados en arcas familiares. Etnográfica y Cultural. Se celebra en Agosto (Último domingo). Fiesta de Interés Turístico Nacional con un valor etnográfico único en España que atrae a fotógrafos, etnógrafos y miles de turistas anualmente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22029','fiesta','Fiestas en honor a la Natividad de la Virgen','Conserva ritos religiosos locales, actividades infantiles en las plazas y sesiones de baile nocturno. Patronal. Se celebra en Septiembre. Pequeña verbena de pueblo con carácter eminentemente familiar y vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22032','fiesta','Fiestas de la Virgen del Rosario','Mantiene vivo el folclore folclórico de los valles occidentales, la jota pirenaica y juegos tradicionales aragoneses. Patronal y Etnográfica. Se celebra en Agosto. Atractivo estival con gran identidad local acentuada por el turismo rural del Pirineo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22035','fiesta','Fiestas de San Martín y la Feria del Coleccionismo','Las fiestas patronales integran actos tradicionales, mientras que su feria invernal atrae a aficionados de comunidades vecinas. Patronal y Feria Cultural. Se celebra en Noviembre (San Martín) y Agosto (Fiestas de verano). Puntuación reforzada por su carácter fronterizo con Cataluña, que dinamiza culturalmente la comarca de la Ribagorza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22036','fiesta','Fiestas del Nacimiento de la Virgen','Sencillos festejos basados en pasacalles, campeonatos de cartas y orquestas populares. Patronal. Se celebra en Septiembre. Festejos íntimos de baja afluencia, dirigidos a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22037','fiesta','Reunión Invernal de Arguis y Fiestas de San Miguel','La invernal de Arguis es la concentración motera más antigua de España, un hito etnográfico moderno del motor. Concentración Cultural y Patronal. Se celebra en Diciembre (Motos) y Septiembre (Patronales). Su concentración de motos tiene rango e impacto nacional y europeo entre aficionados, elevando la puntuación del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22039','fiesta','Fiestas de San Alonso y las Jornadas Micológicas de Ayerbe','Las jornadas de los hongos atraen a miles de aficionados a la micología y la gastronomía de todo Aragón. Gastronómica, Enológica y Patronal. Se celebra en Septiembre (Patronales) y Octubre (Micológicas). Gran relevancia provincial y comarcal gracias a su consolidada feria gastronómica otoñal en el Reino de los Mallos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22040','fiesta','Fiestas de San Pedro y San Sebastián','Famosas por su concurso de lanzamiento de cuesco de oliva y rondallas populares de fuerte carácter local. Patronal y Etnográfica. Se celebra en Enero y Julio. Arraigo vecinal dinamizado por juegos festivos curiosos singulares de la Litera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22041','fiesta','Fiestas de Santa Lucía','Misas con procesión tradicional, pasacalles infantiles y bailes en la pista municipal de verano. Patronal. Se celebra en Agosto (Fiestas de verano) y Diciembre (Patronal). Orientadas fundamentalmente al ocio de los propios residentes y familiares retornados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22042','fiesta','Fiestas en honor a Nuestra Señora del Rosario','Se caracterizan por las cenas populares al aire libre y las tradicionales jotas en honor a la virgen. Patronal. Se celebra en Agosto. Pequeña celebración veraniega de carácter familiar en el Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22043','fiesta','Fiestas de la Asunción de la Virgen','Actividades deportivas locales, timbas de guiote y verbenas nocturnas que dinamizan la población en época estival. Patronal. Se celebra en Agosto. Festejos típicos de pequeña localidad con foco en la convivencia del núcleo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22044','fiesta','Fiestas de San Alodio y San Nunilo, e hitos de recreación histórica de la Sede Real','Recuerda el pasado del pueblo como corte de los Reyes de Aragón. Patronal y Recreación Histórica. Se celebra en Septiembre. Interés comarcal en la Jacetania gracias al esfuerzo local de recuperación de su memoria histórica medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22045','fiesta','Fiestas de la Asunción y San Roque','Bailes populares en la plaza, pasacalles animados por charangas y campeonatos de cartas. Patronal. Se celebra en Agosto. Arraigo local en la frontera oriental de la provincia, muy familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22046','fiesta','Fiestas de San Juan Bautista y de Nuestra Señora de Loreto','Destaca su tradicional procesión de "las "Cestas", donde los jóvenes portan ofrendas florales y frutales vistiendo trajes regionales aragoneses. Patronal y Etnográfica. Se celebra en Agosto y Octubre. Importante arraigo en el Bajo Cinca por la vistosidad de su desfile etnográfico de ofrendas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22047','fiesta','Fiestas de San Miguel','Pequeñas carreras populares, juegos para niños en el parque y cenas vecinales compartidas. Patronal. Se celebra en Septiembre. Festejo estrictamente vecinal dada su cercanía y absorción de ocio por la capital oscense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22048','fiesta','Fiestas en honor a la Natividad de Nuestra Señora y el Festival del Vino de la D.O','Somontano. El festival del vino es una macro-cita gastronómica, enológica y musical masiva. Enológica, Gastronómica y Patronal. Se celebra en Agosto (Festival del Vino) y Septiembre (Fiestas Mayores). Fiesta de gran repercusión regional y nacional; el Festival del Somontano es un referente enoturístico masivo del norte de España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22050','fiesta','Fiestas de San Lorenzo','Tradicionales hogueras nocturnas, chocolatadas comunitarias y bailes de sociedad en el local social. Patronal. Se celebra en Agosto. Celebración pequeña orientada a mantener las costumbres del núcleo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22051','fiesta','Fiestas de San Cecilio','Romería tradicional a la ermita del santo y comidas populares que reúnen a los habitantes de los distintos núcleos del biello Sobrarbe. Patronal y Etnográfica. Se celebra en Febrero y Agosto. Fuerte carácter de reunión e identidad comarcal en una zona de alta dispersión geográfica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22053','fiesta','Fiestas de San Medardo y la "Festa de la Coqueta"','San Medardo destaca por su ancestral y espectacular "Pastorada" (declarada Fiesta de Interés Turístico de Aragón), y la Coqueta es una gran exaltación gastronómica de su embutido tradicional. Etnográfica, Gastronómica y Patronal. Se celebra en Junio (San Medardo) y Agosto (Festa de la Coqueta). Fiesta de Interés Turístico Regional; la Pastorada de Benabarre posee un incalculable valor histórico y dialectal en la Ribagorza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22054','fiesta','Fiestas de San Marcial','Son famosas por el "Ball dels Benasques", un baile ancestral masculino de origen guerrero que se ejecuta frente a la iglesia, acompañado de música tradicional pirenaica. Etnográfica y Patronal. Se celebra en Junio. *. Hito etnográfico de gran singularidad provincial y regional; el baile atrae a expertos folcloristas y gran cantidad de turistas de alta montaña). Hemos completado el segundo bloque de la provincia de Huesca (desde Altorricón hasta Benasque.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22246','fiesta','Fiestas del Santo Cristo y Romería a la Virgen de Siscar','Mantiene viva la tradición de cantar las completas y las tonadas populares de la Ribagorza. Patronal y Etnográfica. Se celebra en Agosto. Festejos de hondo sentimiento religioso y vecinal orientados al reencuentro familiar en el valle del Isábena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22057','fiesta','Carnaval de Bielsa','Es uno de los carnavales más puros, célebres y ancestrales de España, famoso por sus personajes mitológicos como las Trangas, las Madamas y el Oso. Etnográfica y Rito Pagano. Se celebra en Febrero o Marzo (según el calendario de Cuaresma). Fiesta de Interés Turístico de Aragón con un valor antropológico único a nivel nacional, que atrae a miles de visitantes y estudiosos de Europa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22058','fiesta','Fiestas en honor a San Pedro y San Lorenzo','Cuenta con tradicionales pasacalles, rondallas de jotas y degustaciones de vino del Somontano en sus bodegas locales. Patronal. Se celebra en Agosto. Festejos locales muy animados gracias al turismo activo veraniego de la Sierra de Guara.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22059','fiesta','Feria de Otoño de Biescas y Fiestas de Santa Elena','Su Feria de Otoño es un certamen ganadero y agroalimentario multitudinario, famoso por su concurso de Quesos de Otoño. Feria Comercial, Gastronómica y Patronal. Se celebra en Agosto (Santa Elena) y Octubre (Feria de Otoño). Fiesta de Interés Turístico de Aragón; la feria es un motor económico de escala regional que colapsa el Alto Gállego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22060','fiesta','Fiestas de San Marcos y de Santa Ana','Incluyen un concurrido desfile de carrozas artesanales, competiciones deportivas y comidas populares que reúnen al núcleo de Valcarca. Patronal. Se celebra en Abril y Julio. Festejos de carácter comarcal con gran implicación vecinal y del tejido asociativo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22061','fiesta','Fiestas del Santo Cristo de los Milagros y el Festival de Títeres "Imaginaria"','Sus fiestas patronales destacan por la masiva participación de las peñas, los conciertos y los actos folclóricos tradicionales. Patronal y Festival Cultural. Se celebra en Junio (Imaginaria) y Septiembre (Santo Cristo). Gran relevancia provincial y comarcal; Binéfar es uno de los motores económicos y festivos más potentes de la Litera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22062','fiesta','Fiestas de San Juan Bautista','Pequeñas romerías, campeonatos de guiote en el local social y bailes tradicionales pirenaicos a la luz de las hogueras. Patronal. Se celebra en Junio. Celebración de arraigo estrictamente local y familiar en el Valle de Benasque.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22063','fiesta','Fiestas de San Sebastián y de la Virgen de la Asunción','Destaca su recuperada tradición de las hogueras invernales y los cantos tradicionales en la Hoya de Huesca. Patronal. Se celebra en Enero y Agosto. Eventos con encanto vecinal enfocados a la convivencia comunitaria de los núcleos del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22064','fiesta','Fiestas de Santa Ana (en Blecua) y de la Virgen de la Asunción (en Torres de Montes)','Comparten misas cantadas, concursos gastronómicos de tortillas y verbenas populares. Patronal. Se celebra en Julio y Agosto. Pequeñas verbenas de pueblo orientadas a la identidad de ambos núcleos y al regreso veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22066','fiesta','Fiestas de San Pablo y la Fiesta de la Convivencia (Pirenostrum)','Pirenostrum es la mayor feria de luthiers y constructores de instrumentos tradicionales de los Pirineos, llenando los patios del casco antiguo. Feria Cultural, Etnográfica y Patronal. Se celebra en Enero (San Pablo) y Julio (Pirenostrum, de carácter bienal). Pirenostrum es Fiesta de Interés Turístico de Aragón y un hito musical de proyección nacional y europea.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22067','fiesta','Fiestas de San Roque','Caracterizadas por las tradicionales bajadas de antorchas (fallas del Pirineo), rito etnográfico ancestral que forma parte del patrimonio de la humanidad. Etnográfica y Rito Pagano. Se celebra en Agosto. Reconocimiento comarcal y etnográfico de gran singularidad gracias a la magia de los ritos del fuego pirenaicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22068','fiesta','Fiestas de la Virgen de las Candelas y del Rosario','Destaca la conservación de sus bailes tradicionales y la calidez de sus comidas populares en las calles empedradas. Patronal. Se celebra en Febrero y Septiembre. Festejos de arraigo local potenciados por el turismo rural que visita la Jacetania.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22069','fiesta','Fiestas de la Virgen del Rosario y la Feria de Ganado de Broto','Su feria ganadera de otoño mantiene la esencia de los tratos tradicionales del Pirineo y la exposición de vacuno. Feria Tradicional y Patronal. Se celebra en Octubre. Hito comarcal destacado; la feria atrae a ganaderos y visitantes de todo el Sobrarbe y valles vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22072','fiesta','Fiestas de San Antonio de Padua','Sencillas procesiones, juegos para niños, orquestas locales y comidas comunitarias en el Alto Gállego. Patronal. Se celebra en Junio. Festejos netamente familiares y locales orientados a la cohesión comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22074','fiesta','Fiestas de la Virgen de la Esperanza y la famosa Fiesta de la Chaminera','Reúne cantos tradicionales ribagorzanos y juegos de billas (bolos tradicionales femeninos). Patronal y Etnográfica. Se celebra en Agosto. Fuerte identidad local con notable afluencia estival de veraneantes en el Valle de Benasque). Hemos completado el tercer bloque. Dada tu instrucción de seguir hasta la Z, continuaré de manera ininterrumpida con el siguiente bloque lógico de municipios para asegurar la máxima profundidad histórica y etnográfica. ¿Deseas que mantenga este ritmo de bloques de 15 municipios para dar el visto bueno, o prefieres que acelere la cantidad de municipios por mensaje?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22076','fiesta','Fiestas en honor a Santa Eulalia y San Sebastián','Conserva el rito del encendido de la hoguera de San Sebastián en Berdún y el tradicional reparto de tortas bendecidas. Patronal y Etnográfica. Se celebra en Enero y Septiembre. Festejos comarcales con arraigo en la Jacetania, reforzados por el paso de peregrinos del Camino de Santiago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22077','fiesta','Fiestas en honor a San Bartolomé','Destaca la tradicional "Ronda de Peñas" acompañada por charangas y las competiciones de tiro al plato en el entorno del Bajo Cinca. Patronal. Se celebra en Agosto. Festejo típicamente local con gran participación de la juventud y el tejido asociativo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22078','fiesta','Fiestas de la Asunción y la Recreación Histórica de la Inauguración de la Estación Internacional de Canfranc (1928)','Vecinos y visitantes se visten con trajes de los años 20 para revivir el esplendor de la mítica estación ferroviaria. Recreación Histórica y Patronal. Se celebra en Julio (Recreación) y Agosto (Patronales). La recreación de la estación se ha convertido en una Fiesta de Interés Turístico Regional de gran empaque que atrae a turistas de toda España y Francia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22079','fiesta','Fiestas de la Santa Cruz y de San Bartolomé','Sobresale su tradicional romería a la Ermita de Santa Elena, rodeada de lagunas e hitos paisajísticos monegrinos. Patronal. Se celebra en Mayo y Agosto. Verbenas y celebraciones vecinales íntimas con un marcado carácter familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22080','fiesta','Fiestas de la Santa Cruz y del Santo Cristo','Es muy conocido su ancestral "Dance de Capella" con su pastorada lírico-satírica rimada en bajorribagorzano. Etnográfica y Patronal. Se celebra en Septiembre. Hito etnográfico comarcal muy valorado por filólogos e historiadores debido a la pureza y conservación de sus textos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22081','fiesta','Fiestas de San Nicolás y la Feria del Dulce Artesano en el Monasterio de Casbas','La feria gastronómica pone en valor la repostería artesanal y el patrimonio del cenobio cisterciense. Gastronómica, Cultural y Patronal. Se celebra en Mayo (Feria) y Agosto (Fiestas de verano). Dinamismo comarcal reforzado por su feria gastronómica de repostería en el entorno monumental de la Sierra de Guara.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22083','fiesta','Fiestas en honor a Santa Ana y San Sebastián','Destaca su recuperado e histórico "Dance de Castejón", ejecutado al son de la gaita de boto aragonesa con mudanzas de palos y espadas. Etnográfica y Patronal. Se celebra en Julio y Enero. Reconocimiento comarcal destacado gracias al incalculable valor cultural de su folclore tradicional monegrino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22084','fiesta','Fiestas de la Virgen del Pilar y San Sebastián','Cuenta con el tradicional Baile del Pañuelo (Ball del Panyal), verbenas y campeonatos de juegos tradicionales en el Alto Ésera. Patronal y Etnográfica. Se celebra en Octubre y Enero. Afluencia comarcal notable debido al estatus del municipio como epicentro del turismo activo y el vuelo en parapente del Pirineo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22082','fiesta','Fiestas de la Virgen de la Bella','Sobresale la tradicional romería a la ermita homónima y la comida de hermandad vecinal a orillas del río Cinca. Patronal. Se celebra en Septiembre. Festejos de arraigo local y familiar orientados a la convivencia comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22085','fiesta','Fiestas en honor a San Miguel Arcángel','Sencillas procesiones religiosas, juegos infantiles tradicionales y sesiones de baile en el pabellón. Patronal. Se celebra en Septiembre. Celebración pequeña de pueblo, enfocada prioritariamente a los residentes y familiares emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22086','fiesta','Fiestas de San Miguel Arcángel','Reúne tradicionales comidas vecinales de cordero a la pastora, campeonatos de guiote y caminatas populares por el Valle del Aragón. Patronal. Se celebra en Julio (fiestas de verano) y Septiembre. Festejos locales amenizados por la alta presencia de veraneantes del Pirineo central.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22087','fiesta','Fiestas de San Martín','Conserva ritos religiosos de bendición de alimentos, cenas populares compartidas y espectáculos de animación infantil. Patronal. Se celebra en Noviembre y Agosto (fiestas de verano). Orientada estrictamente a la comunidad local y al reencuentro estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22088','fiesta','Fiestas en honor a Nuestra Señora de la Asunción y San Roque','Cuenta con pasacalles, jotas aragonesas y catas populares de vino local de la comarca del Somontano. Patronal y Enológica. Se celebra en Agosto. Festejos tradicionales de arraigo local con ambiente vecinal muy familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22094','fiesta','Fiestas de San Martín y Romería a la Ermita de Santa María de Chalamera','La romería a este templo templario es un hito de devoción religiosa y convivencia en el Bajo Cinca. Patronal y Etnográfica. Se celebra en Noviembre (San Martín) y Abril (Romería de Pascua). Interés comarcal gracias al valor histórico y patrimonial de su romería templaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22095','fiesta','Fiestas de San Martín','Pequeña procesión tradicional, bailes pirenaicos de pañuelo y comidas vecinales de hermandad a las faldas de la Sierra de Chía. Patronal. Se celebra en Noviembre. Festejos íntimos de alta montaña con un carácter netamente familiar y local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22096','fiesta','Fiestas en honor a San Jorge y a la Virgen del Rosario','Destacan las comidas vecinales a base de migas aragonesas y las sesiones de baile en la plaza. Patronal. Se celebra en Abril y Octubre. Pequeña celebración local dinamizada por su extrema cercanía a Huesca capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22090','fiesta','Fiestas de Nuestra Señora del Pilar','Se celebran tradicionales rondas por las casas del pueblo catando el célebre aguardiente artesanal de Colungo. Patronal y Gastronómica. Se celebra en Octubre. Arraigo local en el Somontano potenciado por la promoción de sus destilados artesanales y el arte rupestre del entorno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22099','fiesta','Fiestas de San Roque','Incluyen el concurso de tiro de soga, desfile de carrozas de peñas y comidas populares masivas en la comarca de la Litera. Patronal. Se celebra en Agosto. Festejos comarcales con gran animación juvenil y vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22102','fiesta','Fiestas en honor a San Pedro y la Virgen de la Avellana','Sobresale su romería tradicional y el reparto de frutos secos bendecidos entre los asistentes. Patronal y Etnográfica. Se celebra en Junio y Julio. Fuerte arraigo tradicional y vecinal en las cercanías del río Cinca). He completado los bloques 4 y 5 de la provincia de Huesca (siguiendo en riguroso orden alfabético hasta Estada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22103','fiesta','Fiestas en honor a San Lorenzo y el Certamen de Poesía en Aragonés "Cleto Torrodellas"','Destacan las tradicionales rondas de peñas, los toros de fuego y el fuerte arraigo de la literatura dialectal en los actos culturales. Patronal y Cultural. Se celebra en Agosto. Festejos de gran vitalidad en el Somontano que atraen a poblaciones vecinas por sus conciertos y certámenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22105','fiesta','Fiestas de San Salvador','Conserva pequeñas procesiones tradicionales, campeonatos de cartas en el local social y comidas de hermandad en la frontera con la Ribagorza oriental. Patronal. Se celebra en Agosto. Celebración de arraigo local orientada a la reunión de familias y antiguos residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22106','fiesta','Fiestas de San Andrés','Pequeñas verbenas e hitos tradicionales de la Jacetania que se adaptan a la hospitalidad de un núcleo pirenaico de alta montaña. Patronal. Se celebra en Noviembre y Agosto (fiestas de verano). Celebración íntima y familiar con carácter y afluencia estrictamente local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22107','fiesta','Fiestas de los Tres Reyes y Fiestas de Verano','Conserva el tradicional "Ball d''es Tops" (Baile de los Carneros), un hito folclórico pirenaico muy singular ligado al pastoreo. Etnográfica y Patronal. Se celebra en Septiembre. Hito etnográfico de gran originalidad en el valle de Vió, muy valorado por el turismo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22109','fiesta','Fiestas de la Asunción de la Virgen','Cuenta con pasacalles infantiles, grandes verbenas en la plaza mayor y la tradicional comida de hermandad a orillas del río Ara. Patronal. Se celebra en Agosto. Festejos comarcales muy animados debido a la notable afluencia de turistas y veraneantes en el Pirineo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22110','fiesta','Fiestas de la Asunción y la Feria del Renacimiento','La Feria del Renacimiento transforma la villa con recreaciones históricas, mercados artesanales y desfiles que conmemoran su esplendor palaciego del siglo XVI. Recreación Histórica, Gastronómica y Patronal. Se celebra en Junio (Feria) y Agosto (Asunción). Su Feria del Renacimiento tiene una alta relevancia provincial por el rigor histórico de sus recreaciones y su bello marco monumental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22111','fiesta','Fiestas de San Antón y de la Virgen de la Asunción','Pequeñas procesiones romeras, juegos tradicionales de billas y animadas verbenas nocturnas. Patronal. Se celebra en Enero y Agosto. Festejos de ámbito estrictamente municipal que reúnen a los diversos núcleos del Toscar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22112','fiesta','Fiestas del Pilar (Fiestas de la Estacada) y el Día de la Faldeta','El Día de la Faldeta está declarado Fiesta de Interés Turístico Nacional; homenajea el bellísimo traje tradicional fragatino que las mujeres lucen en un multitudinario desfile histórico. Etnográfica, Cultural y Patronal. Se celebra en Abril (Día de la Faldeta) y Octubre (Fiestas del Pilar). El Día de la Faldeta posee la máxima consideración nacional por su extraordinario rigor etnográfico, atrayendo a miles de visitantes al Bajo Cinca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22114','fiesta','Fiestas de San Joaquín y los célebres Carnavales del Valle de Chistau','Conserva bailes tradicionales pirenaicos como la truca y melodías de gaita de boto en un entorno de gran aislamiento geográfico. Etnográfica y Rito Pagano. Se celebra en Febrero (Carnaval) y Agosto (Patronales). Elevado valor etnográfico gracias a la pureza con la que el valle conserva sus tradiciones folclóricas e idiomáticas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22116','fiesta','Fiestas en honor a Santiago Apóstol','Incluyen grandes desfiles de carrozas elaboradas por las peñas, competiciones deportivas locales y masivas cenas populares en el pabellón municipal. Patronal. Se celebra en Julio. Gran animación y participación comarcal al tratarse de uno de los principales núcleos urbanos de Los Monegros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22117','fiesta','Fiestas de Santo Cristo y San Vicente Ferrer, y la Fiesta de la Longaniza de Graus','Sus fiestas patronales están declaradas de Interés Turístico Nacional por su espectacular patrimonio folclórico (dances, gigantada y la Mojiganga). La Fiesta de la Longaniza ostenta el récord Guinness a la parrillada de embutido más grande del mundo. Etnográfica, Gastronómica y Patronal. Se celebra en Julio (Longaniza) y Septiembre (Fiestas Mayores). De las fiestas más completas de Aragón; su folclore teatralizado y su hito gastronómico mundial atraen masivamente a visitantes nacionales e internacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22119','fiesta','Fiestas en honor a la Virgen del Rosario y San Bartolomé','Cuenta con tradicionales encierros de vaquillas, toros de fuego y concurridas comidas de peñas a orillas del río Sotón. Patronal y Taurina. Se celebra en Septiembre. Festejos comarcales con una arraigada afición taurina popular en los límites de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22122','fiesta','Fiestas de San Lorenzo','Celebraciones veraniegas familiares con campeonatos de cartas, juegos infantiles y verbenas nocturnas en su espectacular mirador colgado sobre el pantano de Búbal. Patronal. Se celebra en Agosto. Pequeño festejo de alta montaña dinamizado por la gran afluencia de turistas en el Valle de Tena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22908','fiesta','Fiestas de San Lorenzo (en Hoz) y de Santiago (en Costean)','Romerías tradicionales a las ermitas de la comarca del Somontano y comidas de alforja compartidas. Patronal. Se celebra en Julio y Agosto. Celebraciones familiares de pequeños núcleos enfocadas en el retorno de veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22124','fiesta','Fiestas de la Invención de la Santa Cruz','Organiza procesiones tradicionales a la ermita de la virgen, campeonatos de guiote y cenas comunitarias. Patronal. Se celebra en Mayo y Septiembre. Verbenas típicas de arraigo local para residentes y familias que retornan el fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22125','fiesta','Fiestas de San Lorenzo','Declaradas Fiestas de Interés Turístico Nacional, la ciudad entera se viste de blanco y verde. Destacan el estallido del cohete en la plaza, el ancestral y emotivo Dance de los Danzantes de Huesca, las ferias taurinas y las multitudinarias peñas de San Lorenzo. Patronal, Etnográfica y Taurina. Se celebra en Agosto (del 9 al 15). Fiesta de Interés Turístico Nacional con un impacto masivo y una marea humana comparable a grandes capitales de España. Máximo empaque provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22126','fiesta','Fiestas de la Virgen de la Sola','Destaca su romería tradicional en el marco de la espectacular Iglesia de San Miguel de Foces, joya del gótico de la Hoya de Huesca. Patronal y Etnográfica. Se celebra en Septiembre. Arraigo vecinal muy potenciado por el inmenso valor histórico-artístico de su entorno romero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22128','fiesta','Fiestas de San Bartolomé','Sencillos festejos basados en parques infantiles, cenas populares de alforja y verbenas que agrupan a sus distintos núcleos rurales. Patronal. Se celebra en Agosto. Celebración pequeña con un foco puramente interno y familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22129','fiesta','Fiestas de San Vicente y las Jornadas de Música Antigua en la Catedral de Roda de Isábena','Las jornadas musicales y litúrgicas aprovechan la acústica y belleza de la catedral más pequeña y antigua de España. Cultural, Etnográfica y Patronal. Se celebra en Enero (San Vicente) y Julio/Agosto (Música Antigua). Puntuación elevada gracias a la inmensa calidad y proyección nacional de su ciclo de música en un entorno patrimonial medieval único.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22130','fiesta','Fiesta del Primer Viernes de Mayo y Fiestas de Santa Orosia','El Primer Viernes de Mayo (Interés Turístico de Aragón) recrea la legendaria batalla medieval del Conde Aznar contra los moros con miles de jacetanos ataviados con trajes históricos y espectaculares salvas de mosquetería. Santa Orosia congrega los dances más antiguos del Pirineo y la sobrecogedora procesión de sus portadores de mantos. Recreación Histórica, Etnográfica y Patronal. Se celebra en Mayo (Primer Viernes de Mayo) y Junio (Santa Orosia). Fiestas de Interés Turístico Regional con una riqueza folclórica, mística y militar pirenaica espectacular que llena por completo la Jacetania.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22131','fiesta','Fiestas de la Virgen de la Asunción','Conserva el folclore del valle del rÍo Osia, campeonatos de billas tradicionales aragonesas y cenas vecinales al aire libre. Patronal y Etnográfica. Se celebra en Agosto. Carácter local arropado por el turismo rural que visita los valles occidentales jacetanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22133','fiesta','Fiestas de San Sebastián y de San Roque','Sobresale su romería a la joya románica de San Vicente de Labuerda, con cantos tradicionales litúrgicos en el Sobrarbe. Patronal. Se celebra en Enero y Agosto. Festejos familiares muy arraigados con alta participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22135','fiesta','Fiestas de Santa María Magdalena','Carreras pedestres, pasacalles animados por charangas y visitas guiadas tradicionales a su pozo-fuente medieval durante la semana cultural. Patronal. Se celebra en Julio. Festejos vecinales tradicionales de carácter comarcal en el Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22136','fiesta','Fiestas de San Pedro y de la Virgen del Rosario','Incluye desfiles de disfraces, carreras pedestres tradicionales y comidas populares que unen a los núcleos de Marcén y San Lorenzo del Flumen. Patronal. Se celebra en Junio y Octubre. Buenas verbenas de arraigo comarcal con gran implicación vecinal en Los Monegros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22137','fiesta','Fiestas en honor a San Mateo','Destaca su histórico y recuperado "Dance de Lanaja" al son de gaiteros aragoneses, con mudanzas de palos y representaciones cómicas tradicionales. Etnográfica y Patronal. Se celebra en Septiembre. Reconocimiento comarcal destacado gracias al valor etnográfico de sus ritos folclóricos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22139','fiesta','Fiestas de los Santos Reyes y de los Santos Inocentes','Sencillas cenas comunitarias de hermandad en los locales municipales y juegos para los niños del pueblo. Patronal. Se celebra en Enero y Agosto (fiestas de verano). Pequeñas verbenas familiares con mínima repercusión exterior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22141','fiesta','Fiestas de San Antón y de la Virgen del Plan','Cuenta con tradicionales hogueras invernales y degustaciones de vino en las prestigiosas bodegas de la zona. Patronal y Enológica. Se celebra en Enero y Agosto. Arraigo local reforzado por el peso de la cultura vinícola de la D.O. Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22142','fiesta','Fiestas de San Martín y la Feria de San Martín','La feria mantiene viva la esencia ganadera medieval ribagorzana combinada con catas de productos artesanos de la tierra. Feria Tradicional y Patronal. Se celebra en Noviembre y Agosto (fiestas de verano). Interés comarcal gracias al mantenimiento histórico de su feria comercial bajomedieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22143','fiesta','Fiestas de San Roque y las recreaciones del Juicio de las Brujas de Laspaúles','Se rememora mediante representaciones teatrales populares los históricos juicios por brujería acaecidos en el municipio en 1593. Recreación Histórica y Patronal. Se celebra en Agosto. Notable valor etnográfico y turístico comarcal debido al misterio y la originalidad de sus teatralizaciones sobre la brujería pirenaica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22144','fiesta','Fiestas de San Mateo y el Descenso de Nabatas por el río Cinca','Los vecinos construyen y tripulan balsas de troncos (nabatas) rememorando el antiguo transporte fluvial de madera pirenaico. Etnográfica y Hito Histórico. Se celebra en Mayo (Nabatas) y Septiembre (Patronales). Fiesta de Interés Turístico de Aragón; el descenso fluvial es un hito de enorme plasticidad e impacto mediático regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22149','fiesta','Fiestas en honor a San Demetrio','Aunque las patronales son locales, las recreaciones medievales, mercados y actividades culturales junto al imponente Castillo de Loarre generan flujos turísticos multitudinarios. Patronal y Recreación Histórica. Se celebra en Octubre. Dinamismo cultural reforzado por el peso y la afluencia nacional que posee su fortaleza románica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22150','fiesta','Fiestas en honor a San Salvador y Romerías a la Ermita de la Virgen del Viñedo','Destacan las comidas campestres compartidas de cooperativas aceiteras de la comarca. Patronal y Etnográfica. Se celebra en Mayo (Romería) y Agosto (Patronales). Fuerte tradición romera comarcal en los valles que circundan la Sierra de Guara.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22151','fiesta','Fiestas de la Virgen de Nuestra Señora de los Corrales','Cuenta con misas cantadas de jotas aragonesas, torneos de cartas y cenas compartidas en la plaza del pueblo. Patronal. Se celebra en Agosto. Celebración netamente familiar y de vecindario, con muy baja afluencia externa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22905','fiesta','Fiestas de San Raimundo y San Salvador','Intercambio de comidas tradicionales entre núcleos vecinales, concursos de disfraces y pasacalles con charangas. Patronal. Se celebra en Mayo y Agosto. Festejos locales enfocados a cohesionar los núcleos habitados de la llanura de la Hoya.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22155','fiesta','Fiestas en honor a San Juan Bautista','Romerías de fuerte raigambre religiosa local, comidas de hermandad y cantos tradicionales en aragonés ribagorzano. Patronal. Se celebra en Junio y Agosto (fiestas estivales). Festejos íntimos de montaña orientados a salvaguardar la unión de los pocos vecinos de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22156','fiesta','Fiestas de San Ramón Nonato y de San Bartolomé','Comidas populares a base de rancho aragonés, actividades infantiles y sesiones musicales de noche. Patronal. Se celebra en Agosto. Festejo marcadamente local influenciado por la proximidad y servicios de la capital provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22157','fiesta','Fiestas de la Virgen de la Asunción y la Bajada de Fallas de Aneto','La bajada de troncos encendidos (Fallas del Pirineo) desde la montaña es un rito del fuego ancestral catalogado como patrimonio inmaterial de la UNESCO. Etnográfica y Rito Pagano. Se celebra en Junio (Fallas) y Agosto (Asunción). Alto valor antropológico internacional gracias a sus ritos ancestrales del fuego pirenaico en los límites con Cataluña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22158','fiesta','Fiestas de San Mateo y el Homenaje a Guillem de Mont-rodón','El homenaje templario a Montrodón (Fiesta de Interés Turístico de Aragón) revive el pasado medieval de la ciudad y la infancia del rey Jaime I el Conquistador con un inmenso mercado, justas y desfiles militares templarios. Recreación Histórica, Feria Comercial y Patronal. Se celebra en Mayo (Mont-rodón) y Septiembre (San Mateo). Su recreación templaria posee un empaque regional aragonés masivo, atrayendo a recreadores y turistas de toda España a su imponente castillo).','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22160','fiesta','Fiestas de la Virgen de los Dolores y Feria de la Sal','Se celebran tradicionales pasacalles y eventos culturales que ensalzan la tradición artesana alfarera y las salinas históricas del Somontano. Patronal y Etnográfica. Se celebra en Septiembre. Interés local y comarcal potenciado por el turismo de bienestar que visita sus estanques salinos terapéuticos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22162','fiesta','Fiestas de Nuestra Señora del Rosario','Sencillos torneos deportivos locales, procesión patronal y verbenas con orquestas en la Hoya de Huesca. Patronal. Se celebra en Octubre. Esquema festivo de pueblo pequeño, centrado en el reencuentro de vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22163','fiesta','Fiestas de San Martín','Cuenta con tradicionales hogueras, misas cantadas, campeonatos de cartas y jotas al pie de la Sierra de Guara. Patronal. Se celebra en Noviembre (San Martín) y Agosto (Verano). Orientada estrictamente al vecindario local y a los residentes de las urbanizaciones de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22164','fiesta','Fiestas del Santo Cristo','Pequeñas procesiones sobre el impresionante desfiladero del río Cinca, comidas vecinales compartidas y timbas de guiote. Patronal. Se celebra en Septiembre. Festejos íntimos orientados casi en su totalidad al reencuentro familiar local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22165','fiesta','Fiestas en honor a San Gregorio y la Santa Cruz','Concursos de carrozas de peñas artesanales, competiciones deportivas locales y tradicionales cantos de jota aragonesa. Patronal. Se celebra en Mayo y Septiembre. Buen arraigo comarcal con gran dinamismo juvenil en la zona del Bajo Cinca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22167','fiesta','Fiestas del Santo Cristo y de San Roque','Desfile humorístico de disfraces, competiciones populares y masivas cenas vecinales en el pabellón multiusos. Patronal. Se celebra en Mayo y Agosto. Festejos vecinales muy animados de carácter comarcal a las orillas del Cinca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22168','fiesta','Fiestas de San Ramón y Romería al Santuario de Bruis','La romería es un hito de fervor tradicional y de reunión comunitaria de todo el valle de La Fueva. Patronal y Etnográfica. Se celebra en Abril (Romería) y Agosto (Patronales). Fuerte arraigo devocional y comarcal a pesar de la reducida población estable del núcleo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22170','fiesta','Fiestas de la Asunción y San Roque, y el Mercado Medieval de Panticosa','Las patronales conservan el folclore pirenaico, mientras que el mercado llena el pueblo de artesanos y pasacalles. Patronal y Recreación Histórica. Se celebra en Julio (Mercado Medieval) y Agosto (Patronales). Notable afluencia de carácter provincial y nacional gracias al fuerte atractivo turístico e invernal del Valle de Tena.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22172','fiesta','Fiestas en honor a la Santa Cruz','Conserva la tradición de cantar las auroras y las procesiones con reliquias locales en pleno desierto monegrino. Patronal y Etnográfica. Se celebra en Mayo. Festejos tradicionales de arraigo local y reencuentro de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22173','fiesta','Fiestas en honor a Nuestra Señora del Mallo','Las celebraciones se realizan bajo los monumentales Mallos de Riglos, aunando pasacalles, jotas y procesiones tradicionales. Patronal. Se celebra en Septiembre. Atractivo comarcal y turístico importante gracias a su inigualable entorno natural y deportivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22174','fiesta','Fiestas de la Asunción y San Roque','Conserva el tradicional reparto de pan bendito, desfiles de carrozas de peñas y competiciones de juegos tradicionales aragoneses. Patronal. Se celebra en Agosto. Festejos comarcales con gran implicación del vecindario en el Somontano meridional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22175','fiesta','Fiestas en honor a la Virgen de la Asunción','Comidas populares compartidas de rancho, orquestas de noche en la plaza y juegos infantiles. Patronal. Se celebra en Agosto. Carácter local y familiar extendido a los diversos núcleos que integran el municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22176','fiesta','Fiestas en honor a San Joaquín','Tradicionales hogueras, rondas folclóricas por las calles de la villa y cenas comunitarias de alforja. Patronal. Se celebra en Agosto. Pequeño festejo de gran calidez vecinal en el área del Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22177','fiesta','Fiestas de San Roque','Pequeñas procesiones a las ermitas locales de la Ribagorza, actividades deportivas infantiles y sesiones musicales de noche. Patronal. Se celebra en Agosto. Festejo de arraigo local orientado al descanso y reencuentro vacacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22178','fiesta','Fiestas de la Asunción de la Virgen','Misas tradicionales cantadas, juegos de mesa e infantiles y verbenas nocturnas junto al río Alcanadre. Patronal. Se celebra en Agosto. Celebración modesta orientada a la identidad comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22181','fiesta','Fiestas de la Corona de la Virgen','Romerías tradicionales a la ermita de la Virgen de la Corona asentada sobre espectaculares formaciones rocosas monegrinas. Patronal y Etnográfica. Se celebra en Mayo. Pequeño festejo devocional con carácter marcadamente vecinal e íntimo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22182','fiesta','Fiestas de la Virgen de la Compasión','Célebre históricamente por su iniciativa etnográfica-social de la caravana de mujeres, mantiene hoy vivas las jotas del Valle de Gistaín y el Ball de la Corro d''es Mayos. Patronal y Etnográfica. Se celebra en Septiembre. Reconocimiento comarcal y mediático histórico, con un folclore pirenaico muy puro y conservado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22184','fiesta','Fiestas en honor a San Sebastián y la Virgen de la Asunción','Cuenta con tradicionales carreras pedestres monegrinas, comidas populares y espectáculos infantiles. Patronal. Se celebra en Enero y Agosto. Festejos locales arraigados con buen ambiente vecinal y familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22186','fiesta','Fiestas de San Gregorio y San Roque','Incluye catas de vino artesanal del Somontano y la tradicional ronda por las calles del pueblo con música popular. Patronal y Enológica. Se celebra en Mayo y Agosto. Arraigo vecinal dinamizado por la cultura del vino de la ribera del Vero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22187','fiesta','Fiestas de San Roque y San Román','Destaca su romería tradicional a la Ermita de San Román de Castro, con espectaculares vistas sobre el embalse de Barasona. Patronal y Etnográfica. Se celebra en Agosto y Noviembre. Interés comarcal reforzado por su patrimonio histórico-arqueológico y la afluencia estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22188','fiesta','Fiestas de la Virgen de la Asunción','Celebraciones vecinales en la frontera con Cataluña, con verbenas y comidas populares a orillas del río Noguera Ribagorzana. Patronal. Se celebra en Agosto. Festejos de arraigo local y de carácter transfronterizo muy familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22902','fiesta','Fiestas de San Antonio de Padua','Orquestas comerciales, actividades de dinamización infantil y comidas vecinales de rancho en la Jacetania. Patronal. Se celebra en Agosto (fiestas de verano). Festejo animado por el cruce de carreteras pirenaico y el flujo estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22189','fiesta','Fiestas de San Justo y Pastor','Romerías de alta montaña y reuniones vecinales tradicionales a las puertas del Parque Nacional de Ordesa y Monte Perdido. Patronal y Etnográfica. Se celebra en Octubre y Agosto (Verano). Festejos muy íntimos y dispersos por los núcleos del municipio, enriquecidos por el turismo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22190','fiesta','Fiestas de la Invención de la Santa Cruz','Destaca la tradicional romería al Real Monasterio de San Victorián, considerado el cenobio más antiguo de España, atrayendo devotos de todo el Sobrarbe. Patronal y Etnográfica. Se celebra en Mayo. Festejos de hondo valor histórico y patrimonial gracias al peso religioso y cultural de San Victorián.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22113','fiesta','Carnaval de La Fueva','Es un carnaval itinerante único en Aragón, donde una caravana de carrozas y gentes disfrazadas recorre los pequeños pueblos del valle comiendo, bailando y festejando en una jornada festiva multitudinaria. Etnográfica y Rito Pagano. Se celebra en Febrero. Fiesta de Interés Turístico de Aragón por su extrema originalidad y su capacidad de atraer a miles de jóvenes de toda la región.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22195','fiesta','Fiestas de Santiago Apóstol','Eventos tradicionales e infantiles fuertemente vinculados a las actividades culturales realizadas en el imponente Castillo de Montearagón. Patronal y Cultural. Se celebra en Julio. Atractivo local condicionado y potenciado por su proximidad a la capital y a su fortaleza medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22197','fiesta','Fiestas de la Virgen de la Asunción','Cuenta con el histórico "Dance de Robres", un hito etnográfico monegrino ejecutado con trajes tradicionales, paloteados y gaita de boto. Etnográfica y Patronal. Se celebra en Agosto. Hito etnográfico singular gracias al incalculable valor y antigüedad de su dance tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','fiesta','Fiestas de Santiago Apóstol y las ferias de muestras locales','Festejos multitudinarios con desfiles de carrozas, ferias comerciales y un potente recinto de peñas. Patronal y Feria Comercial. Se celebra en Julio. Fiesta de Interés Turístico Regional con una enorme afluencia masiva de todo el Alto Gállego y provincias limítrofes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22200','fiesta','Fiestas de San Juan Bautista y las Fallas de Sahún','Es uno de los ritos etnográficos más espectaculares del Pirineo, donde se corren antorchas de fuego (falles) de forma ancestral, declaradas Patrimonio de la Humanidad. Etnográfica y Rito Pagano. Se celebra en Junio. Fiesta con reconocimiento internacional dentro del conjunto de las Fallas del Pirineo, atrayendo a miles de visitantes por la pureza de su rito del fuego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22201','fiesta','Fiestas de la Virgen de la Candelaria','Romería tradicional a la Ermita de la Virgen de la Candelaria y catas populares de vino D.O. Somontano. Patronal y Enológica. Se celebra en Febrero y Agosto. Festejos de arraigo local con un marcado carácter vecinal y familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22202','fiesta','Fiestas en honor a San Ramón','Pasacalles, torneos de guiote, comidas populares y degustaciones vitivinícolas tradicionales. Patronal. Se celebra en Agosto. Pequeña celebración veraniega orientada a la convivencia vecinal en el Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22203','fiesta','Fiestas de San Felipe Neri','Sencillas procesiones, tiro de soga, espectáculos infantiles y bailes populares en el pabellón multiusos. Patronal. Se celebra en Mayo. Festejo estrictamente local con un ambiente íntimo y comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','fiesta','Festival Internacional de las Culturas "Pirineos Sur" y Fiestas de la Virgen de las Nieves','Pirineos Sur es un macroevento musical y cultural de referencia en España, celebrado sobre un escenario flotante en el embalse de Lanuza. Festival Cultural, Etnográfica y Patronal. Se celebra en Julio (Pirineos Sur) y Agosto (Patronales). Pirineos Sur es un festival de impacto internacional y masivo que posiciona al municipio como un referente cultural en toda Europa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22205','fiesta','Fiestas de San Roque','Destacan sus concurridos desfiles de carrozas, las verbenas populares de verano y las tradicionales cenas vecinales al aire libre. Patronal. Se celebra en Agosto. Festejos comarcales con gran animación juvenil y vecinal en la comarca de la Litera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22207','fiesta','Carnaval de San Juan de Plan','Uno de los carnavales pirenaicos más puros y ancestrales de Aragón, famoso por sus personajes tradicionales como los Pegetes y la quema del Muyén. Etnográfica y Rito Pagano. Se celebra en Febrero. Hito etnográfico singular de nivel regional y nacional gracias al gran valor antropológico de sus ritos carnavalescos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22903','fiesta','Fiestas de la Virgen de la Asunción','Une las celebraciones tradicionales de los núcleos de Pomar, Estiche y Santalecina con comidas de hermandad y orquestas. Patronal. Se celebra en Agosto. Festejos de arraigo local enfocados a la unión comunitaria de sus núcleos pedáneos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22206','fiesta','Fiestas en honor a San Bartolomé','Carreras pedestres tradicionales, campeonatos de cartas aragoneses y bailes populares en la plaza mayor. Patronal. Se celebra en Agosto. Sencilla verbena de pueblo orientada a los residentes y familiares retornados en Los Monegros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22208','fiesta','Fiestas de la Virgen de la Peña','Romería tradicional a la ermita homónima y actividades lúdicas fuertemente vinculadas al aeródromo local y al Camino de Santiago. Patronal y Cultural. Se celebra en Septiembre. Festejos de interés local y comarcal en el entorno de la Jacetania.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22209','fiesta','Fiestas de Santa Cruz y San Caprasio','Festejos tradicionales rodeados de un valor patrimonial incalculable, sirviendo de antesala a las peregrinaciones al Monasterio de San Juan de la Peña. Patronal y Etnográfica. Se celebra en Mayo y Octubre. Puntuación reforzada por el flujo de turismo cultural y religioso que visita su extraordinario románico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22906','fiesta','Romería a Nuestra Señora de Dulcis','Una tradicional jornada de convivencia y devoción religiosa mariana que reúne a los vecinos de Huerta de Vero y El Tormillo. Etnográfica y Patronal. Se celebra en Mayo. Festejos íntimos de arraigo municipal y comarcal en el Somontano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22212','fiesta','Fiestas en honor a la Asunción de la Virgen','Sencillos ritos religiosos, comidas populares vecinales a orillas del río Ésera y juegos infantiles. Patronal. Se celebra en Agosto. Celebración pequeña orientada a mantener las costumbres del núcleo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22213','fiesta','Fiestas de San Antolín y el histórico "Dance de Sariñena"','Su dance tradicional es uno de los más antiguos de Aragón, caracterizado por sus mudanzas de espadas y una espectacular pastorada dramática. Etnográfica, Feria y Patronal. Se celebra en Septiembre. Fiesta de Interés Turístico de Aragón; el valor de su patrimonio folclórico y su peso como capital de Los Monegros congrega a miles de personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22214','fiesta','Romería al Santuario de Torreciudad y Fiestas de San Joaquín','El santuario atrae a miles de peregrinos de carácter internacional, complementando las fiestas tradicionales de la villa. Patronal y Romería Religiosa. Se celebra en Agosto. El enorme impacto global de Torreciudad eleva significativamente el perfil y el flujo turístico del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22215','fiesta','Fiestas de la Virgen del Carmen','Tradicionales comidas populares que recuerdan el pasado de la localidad ligado a la ingeniería hidroeléctrica del Pirineo. Patronal. Se celebra en Julio. Festejos vecinales íntimos en las puertas del Valle de Benasque.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22220','fiesta','Romería de la Virgen de la Jarea','Tradicional procesión marianista con reparto de tortas y una gran comida comunitaria en el pabellón local. Patronal y Etnográfica. Se celebra en Mayo. Celebración pequeña enfocada en la tradición religiosa y vecinal de la Hoya.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22221','fiesta','Fiestas de San Ginés','Pasacalles pirenaicos, campeonatos de guiote y verbenas populares al aire libre en el Valle de Benasque. Patronal. Se celebra en Agosto. Festejos locales amenizados por la notable presencia de turismo de montaña estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22222','fiesta','Fiestas en honor a San Lorenzo','Tradicionales torneos deportivos, espectáculos infantiles y animadas verbenas nocturnas en la Hoya de Huesca. Patronal. Se celebra en Agosto. Festejo típicamente local con gran participación familiar e interna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22223','fiesta','Fiestas de San Gregorio y eventos culturales en el Monasterio de Santa María de Alaón','Las celebraciones tradicionales se enriquecen con el marco medieval románico de su cenobio a orillas del Noguera Ribagorzana. Patronal y Cultural. Se celebra en Mayo y Agosto (Verano). Interés comarcal potenciado por el incalculable valor patrimonial de su monasterio medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22225','fiesta','Fiestas de la Virgen del Patrocinio y el Corpus Christi','Sus alfombras florales del Corpus Christi son monumentales obras de arte efímero declaradas Fiesta de Interés Turístico de Aragón. Etnográfica, Artística y Patronal. Se celebra en Junio (Corpus) y Septiembre (Patronales). Fiesta de Interés Turístico de Aragón; el Corpus de Tamarite es un referente artístico y tradicional que atrae a miles de visitantes nacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22229','fiesta','Fiestas en honor a San Anastasio y la Feria del Chocolate','Su consolidada feria agroalimentaria rinde tributo a la repostería artesanal y atrae a numerosos visitantes de la comarca. Gastronómica y Patronal. Se celebra en Mayo (Feria) y Agosto (Fiestas). Dinamismo comarcal reforzado gracias a la notable popularidad de su feria chocolatera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22232','fiesta','Fiestas de San Blas','Tradicionales hogueras de invierno, chocolatadas colectivas y misas solemnes en la comarca de Los Monegros. Patronal. Se celebra en Febrero. Festejos íntimos orientados casi en su totalidad al vecindario local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22233','fiesta','Fiestas de San Vicente','Pequeñas romerías de montaña, comidas compartidas y verbenas familiares en pleno corazón de la Ribagorza. Patronal. Se celebra en Agosto. Festejos netamente familiares de baja afluencia externa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22234','fiesta','Fiestas de San Salvador','Desfiles de carrozas artesanales, comidas multitudinarias a base de productos locales y un animado recinto para las peñas juveniles. Patronal. Se celebra en Agosto. Festejos comarcales con gran vitalidad y movilización social en el Bajo Cinca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22235','fiesta','Fiestas en honor a San Bartolomé','Cuenta con tradicionales rondas joteras, comidas de hermandad en la ribera del río y sesiones de orquesta. Patronal. Se celebra en Agosto. Arraigo estrictamente local enfocado a las reuniones de familiares en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22236','fiesta','Fiestas de San Pedro de Verona','Sencillas procesiones marianas, juegos para niños y cenas compartidas en el local social monegrino. Patronal. Se celebra en Mayo. Celebración pequeña y vecinal con un carácter netamente familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22239','fiesta','Romería a Nuestra Señora del Puy y Fiestas de la Virgen del Carmen','Tradicional jornada de convivencia religiosa en un entorno de espectaculares formaciones de arenisca. Patronal y Etnográfica. Se celebra en Mayo y Julio. Sencillo festejo municipal centrado en la identidad de sus vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22242','fiesta','Fiestas en honor a San Jorge y Nuestra Señora de la Natividad','Procesiones tradicionales, campeonatos de guiote y verbenas nocturnas en Los Monegros. Patronal. Se celebra en Abril y Septiembre. Pequeña verbena de pueblo orientada a mantener las costumbres locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22243','fiesta','Fiestas de San Juan','Celebración comunitaria que reúne a los habitantes de los distintos y dispersos núcleos bajo el majestuoso macizo del Turbón. Patronal. Se celebra en Junio. Festejos muy íntimos de alta montaña orientados a la convivencia comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','fiesta','Fiestas de la Virgen de la Asunción y el folclore cheso','Conserva con gran pureza bailes tradicionales pirenaicos, el uso de la indumentaria histórica local y cantos populares en lengua aragonesa chesa. Etnográfica y Patronal. Se celebra en Agosto. Elevado valor etnográfico y lingüístico a nivel provincial y regional; atrae a un notable turismo cultural al Valle de Hecho.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22244','fiesta','Fiestas de San Vicente','Romerías tradicionales, juegos populares aragoneses y comidas compartidas entre los pequeños núcleos que componen el valle. Patronal. Se celebra en Septiembre. Festejos muy familiares centrados en la identidad comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22245','fiesta','Fiestas de San Lorenzo','Tradicionales encierros y vaquillas, desfiles de peñas con charangas y comidas populares masivas junto al río Cinca. Patronal y Taurina. Se celebra en Agosto. Buen ambiente comarcal en el Bajo Cinca gracias a su arraigada afición taurina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22909','fiesta','Fiestas de la Inmaculada Concepción','Concursos gastronómicos de paellas, actividades deportivas infantiles y sesiones de baile en el pabellón municipal. Patronal. Se celebra en Septiembre (Fiestas de verano) y Diciembre. Arraigo puramente local en una de las localidades de colonización de la comarca de la Litera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22247','fiesta','Fiestas de la Virgen del Estall','Romerías tradicionales que congregan a los vecinos de la zona en las proximidades del imponente Congost de Mont-rebei. Patronal y Etnográfica. Se celebra en Septiembre. Pequeña celebración local dinamizada por el gran flujo turistico de naturaleza del entorno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22249','fiesta','Fiestas de San Pedro','Bailes tradicionales pirenaicos de pañuelo, torneos de naipes y comidas vecinales de hermandad en el Alto Ésera. Patronal. Se celebra en Junio. Festejos de montaña íntimos orientados a los residentes y veraneantes del Valle de Benasque.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22251','fiesta','Fiestas del Santo Salvador','Celebraciones patronales enriquecidas por el flujo cultural del Real Monasterio de Santa María de Sigena, panteón histórico de los Reyes de Aragón. Patronal y Cultural. Se celebra en Agosto. Interés comarcal y provincial apuntalado por el extraordinario valor del patrimonio monástico del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','fiesta','Romería de Santa Orosia','Es una de las manifestaciones etnográficas más espectaculares del Pirineo, donde los romeros suben las ermitas del acantilado acompañados por los Danzantes de Yebra, quienes bailan al son del chicotén (salterio) y la flauta de tres agujeros, mientras se exhiben las reliquias de la santa. Etnográfica, Patronal y Rito Pagano. Se celebra en Junio (25 de junio). Fiesta de Interés Turístico de Aragón con un valor antropológico incalculable; su dance y la procesión atraen a expertos y devotos de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22253','fiesta','Fiestas en honor a la Natividad de la Virgen y la Feria de la Pez','La feria recrea el oficio perdido de los "pezeleros", artesanos que extraían la pez de la resina de los pinos para marcar el ganado y sellar botas. Recreación Histórica, Etnográfica y Patronal. Se celebra en Septiembre (Patronales) y Junio (Feria de la Pez). Hito etnográfico muy original en el Alto Gállego que rescata con rigor una tradición forestal extinta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22254','fiesta','Fiestas en honor a San Antonio Abad y la Virgen del Buen Suceso, además del festival de música e identidad Zaidín Rock (extensión cultural veraniega)','Las patronales destacan por la presentación de Mairalesas y las multitudinarias cenas de peñas a orillas del río Cinca. Patronal y Festival Cultural. Se celebra en Septiembre (Fiestas Mayores). Gran empaque comarcal en el Bajo Cinca, combinando verbenas de honda raíz local con una alta capacidad de convocatoria juvenil). ¡Hemos completado oficialmente la Provincia de Huesca al 100% llegando a la letra Z! Para mantener el orden estrictamente alfabético de la estructura jerárquica del documento de Microsoft Word, la planificación marca dar el salto a la siguiente provincia de la Comunidad Autónoma de Aragón. Si estás listo, dime si prefieres que empecemos con la Provincia de Teruel o si quieres revisar algún bloque previo. ¿Cómo prefieres continuar el ranking?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90283','fiesta','Fiestas de Santa Ana','Destacan las cenas populares compartidas en el pabellón, las verbenas con orquesta y la tradicional procesión religiosa por el núcleo urbano. Patronal. Se celebra en Julio. Festejos de arraigo estrictamente local, enfocados en el reencuentro de familias que retornan en verano a la Comunidad de Teruel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90289','fiesta','Semana Santa de Albalate del Arzobispo y Fiestas de la Virgen de Arcos','Su Semana Santa forma parte de la Ruta del Tambor y el Bombo, declarada Fiesta de Interés Turístico Internacional, destacando el sobrecogedor acto de "Romper la Hora". Etnográfica y Religiosa. Se celebra en Marzo o Abril (Semana Santa) y Septiembre (Patronales). Fiesta de Interés Turístico Internacional con impacto masivo global por la inmensa fuerza cultural y sonora de sus tambores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','fiesta','Fiestas Patronales en honor a Santa María y al Santo Cristo de la Vega','Son célebres sus encierros tradicionales en una plaza portátil de madera montada en su emblemático casco histórico, además de los cantos de los Mayos de Albarracín en primavera. Patronal, Taurina y Etnográfica. Se celebra en Septiembre (Patronales) y Abril/ Mayo (Los Mayos). Fiesta de Interés Turístico de Aragón; el imponente valor estético del municipio multiplica su proyección y la afluencia nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90290','fiesta','Fiestas del Santo Cristo de la Salud','Cuenta con la tradicional procesión de la bajada del santo, comidas populares de cordero a la pastora y toros de fuego nocturnos. Patronal y Taurina. Se celebra en Agosto. Festejos con notable animación veraniega de la comarca de Gúdar-Javalambre, atrayendo a veraneantes de la Comunidad Valenciana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90768','fiesta','Fiestas en honor a San Agustín','Conserva las tradicionales rondas de jotas por sus escarpadas calles, campeonatos de guiote y verbenas en la plaza mayor. Patronal. Se celebra en Agosto. Celebración de arraigo local orientada a la convivencia vecinal y al retorno estival de emigrantes en las Cuencas Mineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43002','fiesta','Semana Santa de Alcañiz y Fiestas de Nuestra Señora de los Pueyos y el Santo Ángel Custodio','Sus procesiones de Semana Santa pertenecen a la Ruta del Tambor y el Bombo (Interés Turístico Internacional), caracterizadas por el color azul de las túnicas de sus tamborileros. Etnográfica, Religiosa y Patronal. Se celebra en Marzo o Abril (Semana Santa) y Septiembre (Patronales). Fiesta de Interés Turístico Internacional con impacto masivo global y un imponente valor artístico, cultural y de ocupación hotelera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44014','fiesta','Semana Santa de Alcorisa y la recreación de "El Drama de la Cruz"','Su Semana Santa pertenece a la Ruta del Tambor y el Bombo (Interés Turístico Internacional), y destaca la sobrecogedora representación en vivo de la Pasión en el monte del Calvario. Recreación Histórica, Etnográfica y Religiosa. Se celebra en Marzo o Abril. Fiesta de Interés Turístico Internacional; el Drama de la Cruz atrae por sí mismo a miles de visitantes de todo el país cada Viernes Santo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44016','fiesta','Subida a la Encomienda y Fiestas de San Antón','La Subida a la Encomienda es una potente recreación histórica medieval que revive el pasado templario del municipio con mercados, desfiles y luchas. Recreación Histórica y Patronal. Se celebra en Abril (Encomienda) y Julio (Fiestas de verano). Reconocimiento comarcal y provincial muy sólido por el rigor y la implicación vecinal en sus recreaciones medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44017','fiesta','Fiestas en honor a San Juan Bautista y la Virgen de la Zarza','Destaca su romería tradicional al santuario de la Virgen, acompañada de cantos populares y comidas camperas. Patronal y Etnográfica. Se celebra en Agosto. Festejos comarcales muy concurridos gracias al tirón del turismo geológico y de naturaleza de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44021','fiesta','Fiesta del Chopo (Mayo) y Fiestas de la Purísima y San Roque','La Fiesta del Chopo consiste en la ancestral plantada del "Mayo", un árbol talado y erigido por los jóvenes en la plaza como rito de fertilidad. Etnográfica y Rito Pagano. Se celebra en Mayo y Julio. Hito etnográfico de gran pureza en el Maestrazgo turolense que conserva ritos de origen bajomedieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44022','fiesta','Fiestas del Santo Cristo del Calvario','Destaca la subida nocturna en procesión al calvario, iluminada por antorchas y acompañada por toques tradicionales de tambor. Patronal y Religiosa. Se celebra en Septiembre. Fuerte arraigo identitario en Andorra-Sierra de Arcos, reuniendo a una gran cantidad de antiguos vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44023','fiesta','Fiestas del Nacimiento de la Virgen','Sencillos festejos basados en comidas de hermandad, juegos de cartas para los mayores y verbenas nocturnas. Patronal. Se celebra en Agosto. Festejos íntimos de baja afluencia, orientados a la pequeña comunidad local en la comarca del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44024','fiesta','Fiestas de San Bartolomé','Cuenta con tradicionales pasacalles, cenas de alforja populares al aire libre y bailes populares en el local social. Patronal. Se celebra en Agosto. Verbena típica de pueblo pequeño con carácter estrictamente familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44025','fiesta','Semana Santa de Andorra y Fiestas de San Macario','Su Semana Santa forma parte de la Ruta del Tambor y el Bombo, catalogada como de Interés Turístico Internacional, destacando el ensordecedor rugido colectivo al "Romper la Hora". Etnográfica, Religiosa y Patronal. Se celebra en Marzo o Abril (Semana Santa) y Septiembre (San Macario). Fiesta de Interés Turístico Internacional con un impacto global y una de las concentraciones de tamborileros más masivas del Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44026','fiesta','Fiestas del Salvador y de la Virgen de los Dolores','Incluyen verbenas populares, ritos religiosos tradicionales y degustaciones de productos locales de la matanza. Patronal. Se celebra en Agosto. Atractivo estival dinamizado por los visitantes que acuden a las zonas naturales y al observatorio astronómico de Javalambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44027','fiesta','Fiestas de la Asunción y San Roque','Destacan sus animadas cenas vecinales en la plaza, campeonatos de guiote y orquestas populares a orillas del río Algars. Patronal. Se celebra en Agosto. Arraigo local con fuerte influencia de visitantes de la vecina Cataluña debido a su carácter fronterizo en el Matarraña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44028','fiesta','Fiestas de San Blas y de la Virgen del Campo','Se caracterizan por el encendido de grandes hogueras invernales y el reparto de pan bendito entre la vecindad. Patronal y Etnográfica. Se celebra en Febrero y Agosto (Fiestas de verano). Costumbres locales mantenidas con orgullo vecinal en la comarca de la Comunidad de Teruel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44029','fiesta','Semana Santa de Ariño y Fiestas de San Salvador','Como miembro de la Ruta del Tambor y el Bombo (Interés Turístico Internacional), la localidad retumba con la fuerza de sus toques de percusión tradicionales. Etnográfica, Religiosa y Patronal. Se celebra en Marzo o Abril. Fiesta de Interés Turístico Internacional; máxima puntuación por su estatus dentro del selecto grupo de los pueblos del tambor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44031','fiesta','Fiestas en honor a San Pedro y las jornadas Iberfesta Azaila','Las jornadas de recreación íbera ponen en valor el yacimiento arqueológico del Cabezo de Alcalá con desfiles, artesanía y talleres de época. Recreación Histórica y Patronal. Se celebra en Septiembre (Iberfesta). Hito cultural y de recreación histórica con un creciente reconocimiento comarcal y provincial de gran singularidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44033','fiesta','Fiestas del Santo Cristo de los Milagros','Sobresalen los tradicionales toros de fuego, el canto de las auroras de madrugada y las comidas de hermandad en el Valle del Jiloca. *. Patronal y Etnográfica. *. Se celebra en Agosto y Septiembre. *. Festejos locales muy animados que congregan a toda la comarca por su gran tradición taurina y musical.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44034','fiesta','Fiestas de San Pedro y de la Virgen del Carmen','Procesiones solemnes con pasacalles, campeonatos de juegos tradicionales aragoneses y bailes nocturnos. Patronal. Se celebra en Agosto. Festejos clásicos de pueblo pequeño enfocados en el ocio vecinal y comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44035','fiesta','Fiestas de la Virgen del Rosario y San Blas','Tradicional encendido de la hoguera de San Blas, misas cantadas con ofrendas florales y verbenas en el pabellón. Patronal. Se celebra en Febrero y Agosto (Fiestas de verano). Celebración orientada fundamentalmente a la identidad local y a las reuniones familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44036','fiesta','Fiestas de San Bartolomé','Pequeños festejos que integran concursos gastronómicos de tortillas, juegos infantiles y veladas musicales comunitarias. Patronal. Se celebra en Agosto. Festejo estrictamente vecinal y familiar con mínima proyección exterior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44037','fiesta','Fiestas de San Bartolomé','Cuenta con carreras pedestres tradicionales, desfile de carrozas artesanales y toros de fuego enmarcados en la espectacular arquitectura de la villa del Matarraña. Patronal y Etnográfica. Se celebra en Agosto. Elevado interés provincial debido a la gran cantidad de turistas que se suman a sus fiestas patronales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44039','fiesta','Fiestas de la Natividad de la Virgen','Romerías tradicionales al entorno de la Laguna de Gallocanta, pasacalles folclóricos con charangas y comidas vecinales. Patronal. Se celebra en Septiembre. Arraigo en la comarca del Jiloca con actividades muy conectadas a la identidad natural del entorno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44038','fiesta','Fiestas de San José y de San Cosme y San Damián','Conserva el canto tradicional de las auroras y las rondas populares por los portales de piedra del casco urbano. Patronal y Etnográfica. Se celebra en Agosto. Festejos de gran sabor tradicional bajoaragónés con un ambiente muy familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44040','fiesta','Fiestas de la Virgen de la Peña y de San Pedro','Destacan las procesiones al santuario excavado en la roca, el reparto de bollos bendecidos y las orquestas nocturnas. Patronal y Etnográfica. Se celebra en Agosto. Fuerte arraigo devocional y vecinal en la comarca del Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44041','fiesta','Fiestas de la Transfiguración del Señor','Pequeñas carreras populares, cenas compartidas en el merendero local y verbenas populares. Patronal. Se celebra en Agosto. Festejos íntimos de montaña muy condicionados por el turismo rural de la Sierra de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44042','fiesta','Fiestas de la Virgen de la Carrasca','Destaca su romería tradicional al paraje de la Carrasca, con reparto de vino en porrón y comidas camperas. Patronal. Se celebra en Agosto. Festejo de carácter eminentemente local y de reencuentro de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44043','fiesta','Fiestas de Santa Ana y la Virgen de la Aliaga','Conserva carreras pedestres tradicionales (carreras de pollos) y torneos del juego tradicional de la colotka. Patronal y Etnográfica. Se celebra en Julio y Octubre. Notable esfuerzo local por la conservación de juegos y tradiciones deportivas aragonesas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44044','fiesta','Fiestas de la Virgen de la Carrasca','Romería de gran antigüedad que congrega a los pueblos vecinos del Maestrazgo turolense y castellonense en torno a su iglesia templaria. Patronal y Etnográfica. Se celebra en Mayo y Agosto. Importante valor fronterizo e histórico debido a la antigua devoción e interrelación cultural de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44045','fiesta','Fiestas de la Asunción y San Roque','Es célebre la "Sopeta de Bronchales", un multitudinario rito festivo donde la gente se lanza agua y baila al son de la charanga, repartiéndose tortas y vino. Etnográfica y Patronal. Se celebra en Agosto. Gran relevancia provincial; la Sopeta atrae a miles de jóvenes de toda la provincia de Teruel y de la Comunidad Valenciana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44046','fiesta','Fiestas de la Asunción de la Virgen','Sencillos pasacalles, campeonatos de naipes en el teleclub y bailes populares para la vecindad. Patronal. Se celebra en Agosto. Celebración pequeña orientada a mantener los vínculos identitarios del vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44047','fiesta','Fiestas de San Pedro Mártir','Destaca la monumental hoguera invernal, además de las tradicionales comidas de hermandad y orquestas populares en verano. Patronal. Se celebra en Agosto. Festejos de arraigo local y familiar en el curso del río Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44048','fiesta','Fiestas de San Miguel y la Virgen de la Escala','Cuenta con misas solemnes, concursos de disfraces artesanales y verbenas nocturnas en la plaza mayor. Patronal. Se celebra en Agosto. Orientadas fundamentalmente al ocio familiar de residentes y veraneantes de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44049','fiesta','Fiestas de la Asunción y San Roque','Desfile de carrozas artísticas, toros de fuego y comidas populares que llenan sus plazas porticadas de gran valor arquitectónico. Patronal y Etnográfica. Se celebra en Agosto. Puntuación reforzada por el enorme atractivo turístico de su casco urbano, convirtiendo las patronales en un imán comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44050','fiesta','Fiestas en honor a San Roque y la Feria del Jamón de Calamocha','El Baile de San Roque (declarado Fiesta de Interés Turístico de Aragón) es un baile procesional masivo donde cientos de parejas bailan al santo guiadas por un "bastonero". Gastronómica, Etnográfica y Patronal. Se celebra en Agosto (San Roque) y Septiembre (Feria del Jamón). Fiesta de Interés Turístico Regional; su danza tradicional y la potencia agroalimentaria del jamón de Teruel generan un enorme impacto regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44051','fiesta','Semana Santa de Calanda y las Fiestas del Pilar','Su Semana Santa forma parte de la Ruta del Tambor y el Bombo (Interés Turístico Internacional); el acto de "Romper la Hora" al mediodía del Viernes Santo inunda la plaza de túnicas moradas en un rito de fama mundial ligado a Luis Buñuel. Etnográfica, Religiosa y Patronal. Se celebra en Marzo o Abril (Semana Santa) y Octubre (El Pilar). Fiesta de Interés Turístico Internacional; hito etnográfico masivo global de máxima relevancia antropológica y mediática.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44052','fiesta','Fiestas de San Pedro y el Santo Cristo','Pequeñas carreras populares por el entorno del río Blanco, timbas de guiote y verbenas íntimas. Patronal. Se celebra en Agosto. Pequeña verbena rural de alta montaña condicionada por el turismo rural de la Sierra de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44053','fiesta','Fiestas Patronales de Santa Vicenta y la Virgen del Loreto, junto a su Feria de Ganado de Cantavieja','Su feria es una de las citas agropecuarias bajomedievales más antiguas del Maestrazgo, reuniendo subastas estatales de ganado. Feria Tradicional, Comercial y Patronal. Se celebra en Agosto (Patronales) y Septiembre (Feria Ganadera). Hito comercial y de arraigo comarcal muy potente; su feria ganadera es el gran referente socioeconómico del Maestrazgo turolense.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44054','fiesta','Fiestas en honor a San Mateo y la Virgen del Buen Suceso','Cuenta con toros de fuego, jotas tradicionales y una gran animación gracias al turismo de la Sierra de Javalambre. Patronal y Taurina. Se celebra en Septiembre y Agosto (fiestas de verano). Notable afluencia de carácter comarcal potenciada por los veraneantes y el turismo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44055','fiesta','Fiestas en honor a San Roque y la Virgen del Campo','Destaca la tradicional romería a la ermita y el reparto del pan bendito con jotas tradicionales de la comunidad de Teruel. Patronal. Se celebra en Agosto. Festejos de arraigo local y familiar orientados a la convivencia y al regreso estival de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44060','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Sencillas procesiones religiosas, juegos tradicionales para niños y bailes nocturnos en el local municipal. Patronal. Se celebra en Agosto. Festejos de marcado carácter íntimo y familiar en una de las zonas con mayor despoblación.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44061','fiesta','Fiestas en honor a San Blas y la Virgen de la Asunción','Destaca el encendido de la gran hoguera de San Blas en invierno y el posterior reparto de pan artesanal. Patronal y Etnográfica. Se celebra en Febrero y Agosto. Festejos con encanto vecinal en el Bajo Aragón que mantienen vivas las tradiciones invernales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44063','fiesta','Fiestas en honor a la Virgen del Olivar','Tradicionales misas cantadas, campeonatos de cartas y comidas compartidas por el vecindario en las Cuencas Mineras. Patronal. Se celebra en Agosto. Pequeña verbena de pueblo orientada a los residentes y familiares retornados en vacaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44064','fiesta','Fiestas de San Nicolás de Bari y la Virgen del Rosario','Conserva el canto tradicional de las albadas y pasacalles populares amenizados por músicos de la zona. Patronal y Etnográfica. Se celebra en Mayo y Agosto. Festejos tradicionales de arraigo local orientados a la identidad de la comunidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44065','fiesta','Fiestas del Santo Cristo de la Agonía','Pequeños torneos deportivos, comidas populares de hermandad y orquestas populares por las noches. Patronal. Se celebra en Agosto. Verbena típica de pueblo pequeño con carácter familiar en el entorno de la Laguna de Gallocanta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44066','fiesta','Fiestas en honor a la Virgen de la Asunción y San Roque','Cuenta con encierros infantiles simulados, comidas vecinales de cordero y sesiones de baile en el pabellón. Patronal. Se celebra en Agosto. Festejos enfocados a la convivencia de los vecinos del núcleo y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44070','fiesta','Fiestas de la Virgen del Pilar y San Lamberto','Se organizan carreras pedestres tradicionales, rondallas de jotas y cenas de hermandad compartidas. Patronal. Se celebra en Agosto. Arraigo estrictamente local en la comarca de Gúdar-Javalambre con ambiente muy familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44067','fiesta','Fiestas en honor a San Valero y la Virgen del Consuelo','Destaca la monumental hoguera invernal en honor a San Valero donde se asan embutidos del Bajo Martín. Patronal y Gastronómica. Se celebra en Enero y Agosto. Buen ambiente festivo local dinamizado por los ritos del fuego invernales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44068','fiesta','Fiestas de San Sebastián y San Antón','Es célebre la Monumental Hoguera de San Sebastián, en la que se planta un gran álamo en el centro de la plaza y se le prende fuego en un rito etnográfico ancestral espectacular, declarado Fiesta de Interés Turístico de Aragón. Etnográfica, Rito Pagano y Patronal. Se celebra en Enero (19-21 de enero). Fiesta de Interés Turístico Regional con un valor patrimonial y antropológico de primer orden que atrae a visitantes de toda la región.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44074','fiesta','Feria de Cedrillas','Es una de las ferias ganaderas, agrícolas y comerciales más importantes del territorio aragonés, con origen en un privilegio real del siglo XIV otorgado por Juan I. Feria Comercial, Ganadera y Tradicional. Se celebra en Octubre (Primer fin de semana). Macro-feria con un fortísimo impacto económico y ganadero a nivel regional, colapsando la comarca con miles de asistentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44075','fiesta','Fiestas de la Virgen de la Salud y San Domingo de Guzmán','Mantiene la tradición del canto del Rosario de la Aurora por las calles del municipio y verbenas nocturnas. Patronal y Etnográfica. Se celebra en Agosto. Festejos clásicos de arraigo local en la comarca de Teruel con buena participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44076','fiesta','Fiestas de San Clemente y la recreación de la Feria de la Patata de Cella','Las patronales cuentan con encierros taurinos de gran renombre y su feria gastronómica rinde culto a su producto agrícola estrella. Patronal, Taurina y Gastronómica. Se celebra en Agosto (Patronales) y Septiembre (Feria). Reconocimiento provincial relevante; sus festejos taurinos y la feria de la patata atraen a abundante público de Teruel capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44077','fiesta','Fiestas de la Virgen de los Remedios','Conserva la tradicional romería a la ermita, comidas populares de cordero a la pastora y sesiones de baile en la plaza del ayuntamiento. Patronal. Se celebra en Agosto. Pequeña celebración veraniega de carácter familiar y muy íntimo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44082','fiesta','Fiestas de la Virgen del Castillo y San Pedro','Organiza marchas senderistas tradicionales, campeonatos de guiote y bailes populares en la plaza del ayuntamiento. Patronal. Se celebra en Agosto. Celebración clásica de núcleo pequeño orientada a la identidad comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12048','fiesta','Fiestas de San Bartolomé y la Virgen de la Aliaga','Incluye la tradicional romería al santuario de la Virgen de la Aliaga compartida con otros pueblos de la comarca. Patronal y Etnográfica. Se celebra en Agosto. Festejos de arraigo local y de unión comarcal en las Cuencas Mineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44085','fiesta','Fiestas de San Abdón y San Senén (los Santos Piedrecicas)','Misas tradicionales para pedir protección contra el granizo, seguidas de comidas vecinales y orquesta. Patronal. Se celebra en Agosto. Orientadas fundamentalmente al reencuentro estival del vecindario del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44086','fiesta','Fiestas de la Asunción y San Roque, junto a la Feria del Vino del Matarraña','Su feria vitivinícola es la gran cita enológica del noreste de Teruel, ensalzando los caldos artesanales de la comarca. *. Enológica, Gastronómica y Patronal. *. Se celebra en Abril (Feria del Vino) y Agosto (Patronales). *. Fuerte impacto comarcal y provincial; la feria atrae a gran cantidad de visitantes de Tarragona, Zaragoza y toda la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44087','fiesta','Fiestas en honor a San Martín y San Gil','Se organizan comidas populares, campeonatos de cartas y actividades culturales en memoria de su vecino ilustre, el escultor Pablo Serrano. Patronal y Cultural. Se celebra en Agosto. Festejos de carácter vecinal con encanto rural y cultural en Andorra-Sierra de Arcos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44088','fiesta','Fiestas de San Roque y San Sebastián','Cuenta con el reparto tradicional de tortas bendecidas, campeonatos de guiote y cenas vecinales compartidas que dinamizan este pequeño núcleo del Maestrazgo. Patronal. Se celebra en Agosto. Orientadas fundamentalmente al reencuentro comunitario local y de familiares retornados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44093','fiesta','Fiestas de San Juan Bautista y la Virgen del Pilar','Pequeñas verbenas populares nocturnas, actividades infantiles y concurso gastronómico de paellas. Patronal. Se celebra en Junio y Octubre. Festejos íntimos de baja afluencia dirigidos a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44094','fiesta','Fiestas en honor a San Juan Evangelista','Cuenta con comidas de hermandad a orillas del río Alfambra, verbenas nocturnas y suelta de vaquillas locales. Patronal y Taurina. Se celebra en Agosto. Festejos de arraigo local con buen ambiente vecinal por su cercanía a la capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44096','fiesta','Fiestas de la Natividad de la Virgen y el Carrasca Rock','Su festival de música alternativa dinamiza y congrega a jóvenes de toda la provincia en defensa del medio rural. Patronal y Festival Cultural. Se celebra en Septiembre (Patronales) y Julio (Carrasca Rock). Puntuación reforzada notablemente por el festival de rock, hito cultural juvenil de las Cuencas Mineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44097','fiesta','Fiestas de San Lorenzo y el Día del Espliego','Durante el Día del Espliego se realiza la recolección, destilación tradicional y quema artesanal de esta planta aromática. Etnográfica, Gastronómica y Patronal. Se celebra en Agosto. Interés comarcal gracias a la originalidad etnográfica y botánica de su fiesta del espliego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44099','fiesta','Fiestas de San Juan Bautista y Santa Bárbara','Muy vinculadas a su pasado e identidad minera, rindiendo homenaje a los trabajadores del carbón con procesiones y barrenas. Patronal y Etnográfica. Se celebra en Junio y Diciembre. Festejos de marcado orgullo local e identidad obrera en el corazón de las Cuencas Mineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44100','fiesta','Fiesta de los Sanantones y la Encamisada de Estercuel','Una espectacular procesión nocturna a caballo rodeando monumentales hogueras, guiada por los portadores de hachas de fuego. Está declarada Fiesta de Interés Turístico de Aragón. Etnográfica, Rito Pagano y Patronal. Se celebra en Enero (Fin de semana más próximo al 17 de enero). Fiesta de Interés Turístico Regional de excepcional riqueza visual, antropológica y gran poder de convocatoria turística.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44101','fiesta','Fiestas en honor a San Roque','Carreras populares de pollos, juegos infantiles, verbenas musicales y reparto de melocotón con vino. Patronal. Se celebra en Agosto. Celebración estival de carácter familiar en el Noroeste de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44102','fiesta','Fiestas de San Miguel','Mantiene las cenas populares de alforja en el porche de la iglesia y campeonatos locales de cartas y bolos. Patronal. Se celebra en Agosto (fiestas de verano) y Septiembre. Festejos tradicionales con baja proyección exterior de carácter puramente vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44103','fiesta','Fiestas en honor a San Pedro y San Roque','Cuenta con tradicionales exhibiciones taurinas de vaquillas, toro embolado y cenas compartidas en la plaza. Patronal y Taurina. Se celebra en Agosto. Festejos comarcales con gran arraigo de la tradición del toro en la comarca de GúdarJavalambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44105','fiesta','Fiestas de la Asunción y San Roque','Destaca el volteo tradicional de campanas y las comidas populares en este conjunto histórico del Matarraña. Patronal. Se celebra en Agosto. Festejos íntimos y familiares potenciados por el marco monumental de la arquitectura local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44106','fiesta','Fiestas de la Virgen del Buen Suceso y San Víctor','Famosas por sus encierros tradicionales por las empinadas calles empedradas y los toros embolados nocturnos. Patronal y Taurina. Se celebra en Agosto. Fuerte afición taurina de arraigo comarcal que atrae a jóvenes de todo el Maestrazgo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44107','fiesta','Fiestas de San Blas y la Virgen de las Nieves','Conserva el encendido de hogueras y las rondallas de jota que recorren las bodegas tradicionales del municipio. Patronal. Se celebra en Febrero y Agosto. Festejos locales con gran sabor tradicional y participación vecinal en el Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44109','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Destaca su encierro a caballo por la sierra y las comidas de hermandad pastoriles en los Montes Universales. Patronal, Taurina y Etnográfica. Se celebra en Agosto. Atractivo estival relevante gracias a la singularidad de sus eventos camperos y ganaderos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44110','fiesta','Fiestas de San Blas','Tradicionales chocolatadas populares, competiciones vecinales de guiote y veladas musicales en el salón cultural. Patronal. Se celebra en Agosto (adaptadas al verano) y Febrero. Festejos típicamente vecinales orientados al reencuentro veraniego familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44111','fiesta','Fiestas de San Bartolomé','Misas tradicionales, bendición de campos, parques infantiles y verbenas en la plaza mayor. Patronal. Se celebra en Agosto. Celebración pequeña orientada a mantener las costumbres del núcleo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44112','fiesta','Fiestas de la Virgen de los Navarros','Sobresale su histórica y multitudinaria procesión donde se baila la jota aragonesa de cara a la imagen de la virgen durante todo el recorrido. Patronal y Etnográfica. Se celebra en Septiembre. Fuerte arraigo identitario en la comarca del Jiloca con gran vistosidad folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44113','fiesta','Fiestas de la Virgen de los Desamparados','Cuenta con vaquillas, toro embolado, bailes populares de disfraces y comidas colectivas en la plaza. Patronal y Taurina. Se celebra en Agosto. Fiestas muy animadas por el turismo de veraneo en el sur de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44114','fiesta','Fiestas en honor a San Salvador','Destaca la carrera tradicional de gallos y los pasacalles populares cantando música en catalán de Aragón. Patronal y Etnográfica. Se celebra en Agosto. Encanto comarcal con gran arraigo e identidad propia de la zona del Matarraña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44115','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Además de los actos religiosos, pasacalles y verbenas, el municipio destaca por sus jornadas de divulgación paleontológica, aprovechando su estatus como uno de los yacimientos de dinosaurios más importantes de Europa. Patronal y Cultural. Se celebra en Agosto. Festejos de arraigo local y familiar potenciados significativamente por el turismo científico y cultural que visita los yacimientos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44116','fiesta','Fiestas de Nuestra Señora del Pilar y San Blas','Cuenta con el tradicional encendido de la gran hoguera de San Blas en invierno y animadas comidas de hermandad en el pabellón municipal durante el verano. Patronal y Etnográfica. Se celebra en Febrero y Octubre. Celebraciones tradicionales de carácter puramente local en la comarca de AndorraSierra de Arcos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44117','fiesta','Fiestas en honor a San Bernardo y la Virgen del Carmen','Sobresalen sus tradicionales carreras pedestres, las rondas joteras por las calles moriscas y la recreación histórica de la expulsión de los moriscos (que conmemora su pasado mudéjar). Patronal y Recreación Histórica. Se celebra en Agosto. Hito comarcal destacado gracias al valor histórico y la cuidada ambientación de sus recreaciones en la Sierra de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44119','fiesta','Fiestas de San Pedro y San Pablo','Conocido por la tradicional subasta de los platos típicos cocinados por los vecinos, las carreras de gallos y las verbenas populares a los pies de la Muela de San Juan. Patronal y Etnográfica. Se celebra en Julio. Fiestas muy animadas por el retorno estival de familias a uno de los pueblos más altos de España.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44120','fiesta','Fiestas de Santiago Apóstol y la Feria de la Trashumancia','La feria pone en valor el secular oficio pastoril de los Montes Universales con exhibiciones de esquilado, talleres artesanos y degustación de calderetas de cordero. Etnográfica y Gastronómica. Se celebra en Julio (Patronales) y Septiembre (Feria). Importante hito etnográfico comarcal y provincial que preserva con orgullo la memoria de la ganadería trashumante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44121','fiesta','Fiestas de San Bartolomé y la Virgen del Buen Suceso','Destacan las tradicionales procesiones a la ermita, los toros embolados nocturnos y las orquestas que llenan de ambiente la plaza mayor. Patronal y Taurina. Se celebra en Agosto. Festejos de fuerte arraigo vecinal muy animados por el turismo de montaña de la Sierra de Gúdar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44122','fiesta','Semana Santa de Híjar','Destaca el rito ancestral de "Romper la Hora" a la medianoche del Jueves Santo, donde miles de tambores y bombos atruenan al unísono con túnicas negras. Es una celebración declarada de Interés Turístico Internacional como parte de la Ruta del Tambor y Bombo. Etnográfica y Religiosa. Se celebra en Marzo o Abril (según el calendario litúrgico). Fiesta de Interés Turístico Internacional con un impacto masivo y global, un hito cultural imprescindible del Bajo Martín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44123','fiesta','Fiestas en honor a San Miguel y la Virgen del Pilar','Incluye juegos infantiles, comidas populares, campeonatos de guiote y veladas musicales en el local social del municipio. Patronal. Se celebra en Agosto. Festejos familiares de baja afluencia externa, orientados a la convivencia y reunión de los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44127','fiesta','Fiestas de la Virgen de los Dolores y San Cristóbal','Conserva ritos tradicionales de bendición de vehículos, comidas populares compartidas y espectáculos infantiles en la plaza de la iglesia. Patronal. Se celebra en Julio. Pequeñas verbenas de arraigo puramente local orientadas al reencuentro de emigrantes veraniegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44128','fiesta','Fiestas de San Antón y las Fiestas de la Asunción','En invierno destaca la tradicional hoguera monumental nocturna y el reparto de pan bendito entre la comunidad. Patronal y Etnográfica. Se celebra en Enero y Agosto. Festejos típicos de pequeña localidad enfocados en preservar las costumbres tradicionales del núcleo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44129','fiesta','Fiestas en honor a San Francisco de Asís y la Virgen del Rosario','Cuenta con animadas cenas populares en la plaza, pasacalles acompañados por charangas y verbenas nocturnas. Patronal. Se celebra en Agosto. Celebración netamente familiar y vecinal con mínima proyección exterior en el Bajo Martín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44130','fiesta','Fiestas de San Pedro y de la Virgen de la Asunción','Celebración que destaca por sus campeonatos de juegos tradicionales aragoneses, verbenas musicales y comidas populares al aire libre. Patronal. Se celebra en Agosto. Verbena y festejo de pueblo pequeño, enfocado al ocio interno y familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44131','fiesta','Fiestas de San Roque','Sencillas procesiones religiosas, campeonatos de cartas, actividades para niños en las plazas y sesiones de baile nocturnas en el pabellón. Patronal. Se celebra en Agosto. Festejos íntimos de baja afluencia dirigidos esencialmente a los residentes y familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44080','fiesta','Fiestas en honor a San Valero y la Virgen de Loreto','Se caracterizan por las concurridas orquestas populares, desfiles de disfraces y el mantenimiento del dialecto tradicional local en los pregones. Patronal. Se celebra en Enero y Septiembre. Festejos locales de notable ambiente comarcal dentro del Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44108','fiesta','Fiestas de la Virgen de Gracia y San Bartolomé','El espectacular casco histórico del municipio sirve de escenario para conciertos, pasacalles de gigantes y cabezudos y animadas cenas de peñas locales. Patronal y Cultural. Se celebra en Agosto. Gran atractivo estival en la comarca del Matarraña potenciado por la monumentalidad patrimonial de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44126','fiesta','Fiestas de la Virgen del Cid','Destaca la multitudinaria romería al santuario de la Virgen, donde se realizan danzas tradicionales folclóricas con vistosos trajes y exhibiciones taurinas en el recinto amurallado medieval. Etnográfica, Patronal y Taurina. Se celebra en Mayo y Septiembre. Gran reconocimiento comarcal y provincial gracias al incalculable valor etnográfico de sus dances y su entorno monumental en el Maestrazgo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44146','fiesta','Fiestas en honor a San Bartolomé y la Virgen de la Gracia','Cuenta con encierros taurinos tradicionales, suelta de vaquillas, comidas comunitarias de hermandad y orquestas nocturnas. Patronal y Taurina. Se celebra en Agosto. Festejos comarcales con excelente ambiente juvenil y afición taurina en el Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44187','fiesta','Fiestas de San Cosme y San Damián','Sobresale el tradicional reparto de pan bendito, las rondas joteras por las calles de la villa y las concurridas cenas de hermandad. *. Patronal. *. Se celebra en Septiembre. *. Festejos tradicionales de arraigo local con un ambiente vecinal muy cercano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44191','fiesta','Semana Santa de La Puebla de Híjar','Integrante de la Ruta del Tambor y Bombo y declarada Fiesta de Interés Turístico Internacional, sobresale por el impresionante estruendo de sus tambores en la "Rompida de la Hora" y el cese absoluto del sonido tras las procesiones. Etnográfica y Religiosa. Se celebra en Marzo o Abril (según el calendario litúrgico). Fiesta de Interés Turístico Internacional con impacto y proyección global, con gran afluencia de visitantes nacionales y extranjeros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44192','fiesta','Fiestas del Santo Cristo de la Columna y la Feria de la Trufa de Teruel (FITRUE)','La feria es el epicentro nacional de la trufa negra, con concursos de búsqueda con perros, catas y conferencias gastronómicas internacionales. Gastronómica, Comercial y Patronal. Se celebra en Septiembre (Patronales) y Diciembre (Feria de la Trufa). Su feria gastronómica posee rango e impacto nacional y europeo entre profesionales del sector trufícola, elevando notablemente la puntuación del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44268','fiesta','Fiestas de San Juan Bautista','Sencillas comidas compartidas entre los pocos habitantes estables, torneos de guiote y veladas musicales íntimas. Patronal. Se celebra en Agosto (adaptadas para el retorno). Festejos de arraigo estrictamente local, orientados a la reunión familiar veraniega en un pueblo muy pequeño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44132','fiesta','Fiestas de San Joaquín y Santa Ana','Actividades deportivas locales, timbas de guiote y tradicionales verbenas musicales nocturnas en la comarca del Jiloca. Patronal. Se celebra en Agosto. Festejo netamente vecinal orientado a la convivencia estival y al regreso de familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44133','fiesta','Fiestas en honor a San Bartolomé','Pequeñas procesiones, juegos tradicionales para niños en el parque del pueblo y verbenas compartidas en el pabellón. Patronal. Se celebra en Agosto. Celebración pequeña orientada a mantener los lazos de identidad comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44135','fiesta','Fiestas de la Virgen del Pilar y San Juan Bautista','Famosas localmente por sus divertidas comidas vecinales a orillas del río Turia y orquestas de verano. Patronal. Se celebra en Junio y Septiembre. Festejos de arraigo local enfocados en actividades familiares para residentes y veraneantes de la comarca de Teruel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44136','fiesta','Fiestas de San Juan Bautista y Santiago Apóstol','Incluye la bendición de campos, chocolatadas comunitarias y bailes populares en el local multiusos. Patronal. Se celebra en Julio. Festejos familiares tradicionales de baja afluencia externa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44137','fiesta','Fiestas de la Virgen del Loreto y Santiago','Destaca por sus tradicionales encierros de reses bravas por sus empinadas calles medievales, el toro embolado y las rondas joteras. Patronal y Taurina. Se celebra en Julio y Septiembre. Notorio arraigo comarcal con gran afluencia de público juvenil aficionado al toro de calle en Gúdar-Javalambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44141','fiesta','Fiestas de San Pedro y de la Virgen de la Asunción','Celebradas con comidas de hermandad, catas populares de vinos locales de la comarca del Matarraña y verbenas. Patronal y Enológica. Se celebra en Agosto. Arraigo local vecinal dinamizado por el turismo rural fronterizo con Cataluña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44138','fiesta','Fiestas de San Roque y San Juan Bautista','Conserva ritos religiosos locales, tradicionales volteos de campanas artesanales, pasacalles y campeonatos deportivos comarcales. Patronal. Se celebra en Agosto. Muy buena animación local gracias a la activa asociación cultural del municipio que atrae a las poblaciones vecinas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44142','fiesta','Fiestas en honor a San Juan Bautista','Sencillas comidas compartidas, torneos de cartas y pequeñas verbenas nocturnas en la plaza mayor. Patronal. Se celebra en Agosto. Orientadas estrictamente al disfrute de los propios residentes y familiares veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44143','fiesta','Fiestas de la Virgen del Rosario y del Santo Cristo','Cuenta con tradicionales espectáculos taurinos de calle, encierros, toro embolado y comidas comunitarias que atraen a visitantes de la Comunidad Valenciana por su cercanía. Patronal y Taurina. Se celebra en Agosto y Octubre. Atractivo comarcal y turístico destacado debido a su afición taurina y su ubicación estratégica fronteriza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44144','fiesta','Fiestas de la Virgen de la Salud','Destacan las tradicionales rondas musicales con guitarras por el pueblo, competiciones deportivas locales y grandes cenas vecinales en el pabellón. Patronal. Se celebra en Agosto. Festejos de arraigo local con excelente ambiente vecinal en las Cuencas Mineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44145','fiesta','Fiestas en honor a San Juan Bautista y las Fiestas de Agosto, complementadas con el regreso al pasado de las Jornadas de Recreación Histórica de "El Regreso del Comendador"','La villa revive el ambiente barroco del siglo XVIII bajo el dominio de la Orden de San Juan. Recreación Histórica, Patronal y Taurina. Se celebra en Agosto (Patronales) y Septiembre (Recreación). Festividad con gran reconocimiento provincial; la cuidada fidelidad histórica de sus jornadas barrocas atrae a centenares de visitantes del Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44147','fiesta','Fiestas de San Sebastián y la Virgen de la Asunción','Caracterizadas por las espectaculares hogueras de San Sebastián en invierno y las rondas joteras veraniegas cantadas en su variante local del catalán del Matarraña. Patronal y Etnográfica. Se celebra en Enero y Agosto. Fuerte identidad local e idiomática en la comarca con notable afluencia estival de veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44148','fiesta','Fiestas de San Lorenzo','Pequeños torneos de guiote, pasacalles animados por charangas locales y cenas vecinales comunitarias en el pabellón. Patronal. Se celebra en Agosto. Festejos orientados prioritariamente al reencuentro veraniego de la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44149','fiesta','Fiestas en honor a San Roque y la festividad de Santa Margarita','Destacan por el tradicional canto de las "Completas", las rondas populares por el bellísimo entramado urbano amurallado y sus festejos taurinos de calle. Patronal, Etnográfica y Taurina. Se celebra en Agosto. Gran atractivo comarcal; la belleza medieval de la localidad sirve de marco excepcional potenciando la experiencia turística de las fiestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44150','fiesta','Fiestas de Nuestra Señora de las Nieves','Celebración pequeña basada en procesiones tradicionales a la ermita, campeonatos de guiote y verbenas familiares al aire libre. Patronal. Se celebra en Agosto. Celebración de arraigo local enfocada en el turismo familiar de retorno estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44151','fiesta','Fiestas en honor a San Juan Bautista y la Virgen de la Fuente','Sobresalen los tradicionales toros de fuego, orquestas musicales y pasacalles populares que aprovechan el entorno natural de sus célebres grutas de cristal. Patronal. Se celebra en Agosto. Muy buena animación comarcal en la comarca del Maestrazgo dinamizada por el flujo de turistas veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44152','fiesta','Fiestas del Santo Sepulcro y de la Virgen del Pilar','Sobresale su tradicional romería a la Ermita de la Virgen de la Belmonte y las hogueras populares de San Blas. Patronal y Etnográfica. Se celebra en Febrero y Agosto. Festejos de arraigo local potenciados por el retorno estival de las familias a la comarca del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44153','fiesta','Fiestas en honor a Santiago Apóstol y la tradicional Feria del Azafrán','La feria rinde homenaje al cultivo del "oro rojo", incluyendo demostraciones de "esbrizne" (separar los estigmas de la flor) y gastronomía típica. Gastronómica, Etnográfica y Patronal. Se celebra en Julio (Santiago) y Octubre (Azafrán). Gran reconocimiento provincial y comarcal; la cultura del azafrán es un hito de identidad agrícola único en Teruel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44154','fiesta','Fiestas en honor a la Asunción de la Virgen y San Roque','Conserva las tradicionales "corregudes" (carreras pedestres y de mulos) y el Baile del Rodat en la comarca del Matarraña. Patronal y Etnográfica. Se celebra en Agosto. Notable ambiente vecinal y comarcal potenciado por el turismo rural que visita el Matarraña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44155','fiesta','Fiestas del Santo Cristo de la Salud','Cuenta con vistosos desfiles de carrozas, pasacalles organizados por las peñas y comidas populares en las faldas de su imponente iglesia gótico-mudéjar. Patronal. Se celebra en Septiembre. Festejos de gran empaque comarcal que actúan como dinamizador social de las Cuencas Mineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44156','fiesta','Fiestas de la Virgen de la Peña','Sencillas procesiones religiosas, campeonatos de guiote y verbenas nocturnas que congregan a familiares retornados de la Comunidad Valenciana. Patronal. Se celebra en Agosto. Celebración pequeña y de carácter eminentemente familiar y vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44157','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Bailes populares en la plaza, pasacalles animados por charangas y cenas vecinales compartidas a la sombra de los pinares. Patronal. Se celebra en Agosto. Orientadas prioritariamente a la comunidad local y al reencuentro de veraneantes de la Sierra de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44158','fiesta','Fiestas Patronales de San Miguel y el Festival Puerta al Mediterráneo','El festival llena su espectacular castillo gótico de artes escénicas de primer nivel nacional. Sus fiestas de septiembre incluyen los tradicionales toros embolados. Cultural, Patronal y Taurina. Se celebra en Agosto (Festival) y Septiembre (San Miguel). Fiesta e hito de Interés Turístico Regional; el festival cultural y su tradición taurina atraen masivamente a visitantes aragoneses y valencianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44159','fiesta','Fiestas en honor a San Roque','Destacan sus encierros tradicionales de vaquillas por el núcleo urbano y las verbenas populares en la Sierra de Albarracín. Patronal y Taurina. Se celebra en Agosto. Arraigo local típico de alta montaña, muy participativo y familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44160','fiesta','Fiestas de la Virgen de la Estrella y la Feria Ganadera de Mosqueruela','Su feria de origen medieval (siglo XIV) es uno de los hitos ganaderos y comerciales más puros de la sierra de GúdarMaestrazgo. Feria Tradicional, Patronal y Taurina. Se celebra en Mayo (Romería), Agosto (Fiestas) y Septiembre (Feria). Gran reconocimiento provincial por la antigüedad e importancia económica de su feria de ganado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44161','fiesta','Fiestas de la Virgen de la Aliaga y San Roque','Destacan sus encierros, el toro de fuego y las procesiones tradicionales arropadas por la espectacular torre mudéjar del municipio. Patronal y Taurina. Se celebra en Agosto. Fuerte identidad local y comarcal con gran animación de peñas en el Bajo Martín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44163','fiesta','Fiestas de San Miguel Arcángel','Incluye comidas populares de cordero a la pastora, verbenas musicales y juegos tradicionales infantiles aragoneses. Patronal. Se celebra en Agosto (fiestas de verano) y Septiembre. Pequeña celebración veraniega adaptada al ocio de residentes y familiares retornados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44164','fiesta','Fiestas de San Juan y de la Virgen de las Nieves','Sencillos festejos basados en pasacalles, campeonatos de naipes y cenas compartidas en la calle. Patronal. Se celebra en Agosto. Festejos íntimos de baja afluencia externa debido al reducido tamaño del núcleo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44165','fiesta','Fiestas en honor a la Virgen del Carmen','Destaca por sus concurridos festejos taurinos con toros embolados y las orquestas que llenan el recinto festivo. Patronal y Taurina. Se celebra en Agosto. Atractivo comarcal con buena afluencia procedente del límite con Castellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44167','fiesta','Fiestas de la Virgen de la Asunción','Actividades tradicionales en el frontón, misas tradicionales en su iglesia parroquial y verbenas orientadas a los veraneantes. Patronal. Se celebra en Agosto. Celebración puramente local y familiar ligada al retorno de emigrantes en el Parque Cultural del Martín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44168','fiesta','Fiestas de la Virgen de la Mercedes','Reúne tradicionales comidas vecinales, desfiles de disfraces y orquestas populares de gran dinamismo local. Patronal. Se celebra en Septiembre. Arraigo estrictamente local enfocado en el reencuentro de fin de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44169','fiesta','Fiestas en honor a Santa Engracia y la Virgen de las Masas','Destaca su romería tradicional al santuario y las actividades lúdicas vinculadas a la memoria del pasado minero de la localidad. Patronal y Etnográfica. Se celebra en Agosto. Festejos comarcales con buena animación local dentro del Valle del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44171','fiesta','Fiestas de la Virgen de los Desamparados y de San Roque','Caracterizadas por la masiva presencia de familias que acuden al Valle del Mijares, combinando orquestas y baños en el río. Patronal. Se celebra en Agosto. Festejos locales muy dinamizados por el turismo rural y de naturaleza de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44172','fiesta','Fiestas de la Virgen del Cantal y de San Bartolomé','Sobresale su devoción a la virgen aparecida en una roca, procesiones tradicionales y charangas por sus bodegas locales. Patronal. Se celebra en Agosto. Fuerte identidad local y comarcal en Andorra-Sierra de Arcos, potenciada por proyectos de apadrinamiento de olivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44174','fiesta','Fiestas de la Virgen del Tremedal','Declarada Fiesta de Interés Turístico de Aragón, destaca por su ancestral Romería de los Pañuelos al santuario, las rondas tradicionales y sus peculiares festejos taurinos en la plaza de toros de madera. Etnográfica, Patronal y Taurina. Se celebra en Septiembre. Fiesta de Interés Turístico Regional con una gran devoción y espectacularidad etnográfica en la Sierra de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44175','fiesta','Fiestas de la Santa Cruz','Tradicionales comidas comunitarias de hermandad, juegos para niños y bailes nocturnos en el local social del pueblo. Patronal. Se celebra en Agosto (adaptadas para el verano) y Septiembre. Celebración netamente familiar con mínima proyección exterior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44176','fiesta','Fiestas de San Justo y San Pastor','Mantienen vivos los pasacalles de disfraces, las jotas aragonesas y las cenas populares al aire libre. Patronal. Se celebra en Agosto. Celebraciones tradicionales de carácter comarcal en las Cuencas Mineras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44177','fiesta','Fiestas de la Virgen de la Palma y el Festival de Artes Escénicas "Gaire"','El festival Gaire transforma por completo este pequeño pueblo atrayendo a miles de personas con espectáculos de circo, teatro y danza callejera. Cultural, Festival Artístico y Patronal. Se celebra en Septiembre (Festival Gaire). Excelente puntuación debido al brutal impacto del Festival Gaire, hito cultural de referencia provincial y autonómica contra la despoblación.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44178','fiesta','Fiestas de San Malachías','Cuenta con hogueras de invierno tradicionales, pasacalles vecinales y cenas comunitarias compartidas en el Bajo Aragón. Patronal. Se celebra en Noviembre y Agosto (fiestas estivales). Orientadas prioritariamente a los residentes y la cohesión comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44179','fiesta','Fiestas en honor a la Virgen de la Fuente y San Miguel','Destaca el desfile tradicional al Santuario de la Virgen de la Fuente, muestra soberbia de arquitectura mudéjar, acompañado de comidas populares de cordero. Patronal y Etnográfica. Se celebra en Septiembre. Importante arraigo en la comarca del Matarraña por la belleza de su entorno monumental y devoción.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44180','fiesta','Fiestas en honor a San Pedro y San Roque','Aunque las patronales son locales, las recreaciones históricas medievales organizadas en su espectacular castillo de rodeno rojo atraen masivo turismo provincial. Patronal y Recreación Histórica. Se celebra en Agosto. Su patrimonio monumental e histórico eleva el dinamismo de los festejos estivales en la comarca del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44181','fiesta','Fiestas de San Bartolomé','Sencillas procesiones religiosas, juegos tradicionales para niños y bailes populares nocturnas. Patronal. Se celebra en Agosto. Verbena clásica de núcleo pequeño orientada a la identidad comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44182','fiesta','Fiestas del Santo Cristo de la Peña','Destacan las tradicionales rondallas de jotas aragonesas, las comidas compartidas y los campeonatos de cartas. Patronal. Se celebra en Agosto. Festejos locales enfocados a la comunidad y al retorno de emigrantes por vacaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44183','fiesta','Fiestas de la Virgen de la Peña','Romería tradicional por los bellos senderos del nacimiento del río Pitarque y cenas populares vecinales. Patronal y Etnográfica. Se celebra en Octubre y Agosto (fiestas de verano). Festejos íntimos de montaña con encanto vecinal potenciado por los visitantes de la naturaleza del Maestrazgo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44184','fiesta','Fiestas en honor a la Santa Cruz','Pequeñas parrilladas populares, campeonatos de guiote y verbenas musicales de noche. Patronal. Se celebra en Agosto. Celebración netamente familiar y vecinal con baja proyección exterior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44185','fiesta','Fiestas de San Juan y el Festival de Música de Raíz "PoboBao"','El festival es una relevante muestra estival de música folk, etno y actividades culturales en la Comunidad de Teruel. Festival Cultural y Patronal. Se celebra en Junio (PoboBao) y Junio (San Juan). Dinamismo comarcal reforzado por su original apuesta por la música tradicional y folclórica en la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44189','fiesta','Fiestas de San Roque','Cuenta con procesiones tradicionales a la ermita, campeonatos deportivos locales y verbenas populares nocturnas. Patronal. Se celebra en Agosto. Festejos típicos de pequeña localidad con foco en la convivencia estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44190','fiesta','Fiestas en honor a San Miguel Arcángel','Conserva la misa tradicional con reparto de pan bendito, charangas por el pueblo y bailes públicos. Patronal. Se celebra en Agosto. Arraigo local enfocado en actividades familiares para residentes y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44193','fiesta','Fiestas de la Virgen del Pilar y San Antonio Abad','San Antonio destaca por su ancestral Sanantonada, una espectacular hoguera y representación etnográfica de las tentaciones del santo entre calles medievales. Etnográfica, Rito Pagano y Patronal. Se celebra en Enero (San Antonio) y Agosto (fiestas estivales). Hito etnográfico comarcal y provincial muy valorado gracias a la espectacularidad de su fiesta de invierno en un entorno monumental.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44194','fiesta','Fiestas de San Rafael','Ofrece tradicionales pasacalles, comidas populares en su plaza porticada medieval y catas de aceite de oliva del Bajo Aragón. Patronal y Gastronómica. Se celebra en Noviembre y Agosto (fiestas de verano). Festejos de arraigo local con excelente ambiente vecinal en el Matarraña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44195','fiesta','Fiestas de San Domingo de Silos','Celebraciones basadas en misas solemnes, concursos de disfraces infantiles y sesiones de baile en el pabellón. Patronal. Se celebra en Agosto. Festejo de baja afluencia, dirigido a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44196','fiesta','Fiestas de San Lorenzo y la Virgen de los Dolores','Sencillas procesiones, torneos de juegos tradicionales aragoneses y comidas comunitarias vecinales. Patronal. Se celebra en Agosto. Celebración de arraigo local dinamizada por las visitas turísticas a sus yacimientos paleontológicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44197','fiesta','Fiestas de la Virgen de los Dores','Tradicionales hogueras nocturnas, pasacalles infantiles y bailes en el local municipal. Patronal. Se celebra en Agosto. Celebración pequeña orientada a mantener las costumbres del núcleo local de la Sierra de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44201','fiesta','Fiestas del Toro de San Roque y el Mercado Medieval de Rubielos','Su mercado medieval es uno de los pioneros y más afamados de la provincia, transformando el conjunto histórico. Las patronales incluyen toros de fuego y embolados. Recreación Histórica, Patronal y Taurina. Se celebra en Agosto (Mercado Medieval) y Septiembre (San Roque). Gran relevancia provincial y autonómica; su mercado medieval y tradición taurina ostentan un gran impacto turístico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44206','fiesta','Fiestas en honor a San Agustín y la Virgen de Pradas','Cuenta con tradicionales romerías al castillo e iglesia de Pradas, pasacalles con charanga y toros embolados. Patronal y Taurina. Se celebra en Agosto. Festejos de arraigo local con ambiente festivo comarcal atraído desde el límite con Castellón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44207','fiesta','Fiestas de San Martín de Tours','Conserva tradicionales misas con cantos folclóricos propios, comidas vecinales populares y degustaciones de los reputados vinos artesanales del valle del Jiloca. Patronal y Gastronómica. Se celebra en Noviembre y Agosto (fiestas estivales). Ocio tradicional y familiar enfocado en mantener las costumbres del núcleo municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44208','fiesta','Fiestas de San Bartolomé','Sencillas procesiones religiosas, juegos infantiles tradicionales y sesiones de baile nocturno en el pabellón. Patronal. Se celebra en Agosto. Celebración pequeña de pueblo, enfocada prioritariamente a los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90769','fiesta','Fiestas de la Virgen del Molino','Destacan sus encierros tradicionales de vaquillas por las calles, las orquestas de gran nivel y la concurrida romería popular a la ermita del Molino. Patronal y Taurina. Se celebra en Agosto. Importante arraigo comarcal en el Jiloca con gran capacidad de atracción juvenil y peñista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44173','fiesta','Fiestas en honor a El Salvador','Pequeños torneos de guiote, concursos gastronómicos de paellas y sesiones de baile en la plaza del ayuntamiento. Patronal. Se celebra en Agosto. Verbena de arraigo local orientada al reencuentro estival del vecindario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44198','fiesta','Fiestas de San Bartolomé','Famosas por sus encierros taurinos tradicionales por las calles del pueblo y las meriendas de hermandad en los pinares. Patronal y Taurina. Se celebra en Agosto. Festejos de notable afición taurina en la comarca de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44199','fiesta','Fiestas en honor a la Virgen del Rosario','Festejos basados en orquestas populares, campeonatos de cartas y actividades para niños. Patronal. Se celebra en Agosto. Pequeña celebración veraniega de carácter netamente familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44203','fiesta','Fiestas de San Miguel','Sencillas procesiones, espectáculos infantiles y comidas vecinales compartidas para mitigar la despoblación. Patronal. Se celebra en Septiembre (con actos en agosto). Festejos íntimos dirigidos casi exclusivamente a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44204','fiesta','Fiestas de la Virgen de la Asunción','Festejos familiares tradicionales de alta montaña con comidas populares a base de productos de la sierra. Patronal. Se celebra en Agosto. *. Festejos orientados al ocio de los propios residentes y familiares de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44205','fiesta','Semana Santa de Samper de Calanda','Pertenece formalmente a la Ruta del Tambor y el Bombo, destacando el sobrecogedor sonido de los tambores, el cese del toque tras las procesiones tradicionales y el acto del "Abajamiento" del Cristo. Etnográfica y Religiosa. Se celebra en Marzo o Abril. Fiesta declarada de Interés Turístico Internacional debido al impacto global y riqueza ritual de la Ruta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44210','fiesta','FITRUE (Feria Internacional de la Trufa) y Fiestas de la Asunción y de la Virgen de la Media Villa','Fitrue es el macro-evento de referencia nacional e internacional de la trufa negra (Tuber melanosporum), congregando a profesionales y amantes de la gastronomía de todo el mundo. Gastronómica, Feria Comercial y Patronal. Se celebra en Agosto (Patronales) y Diciembre (FITRUE). Fitrue posee un altísimo impacto económico y hostelero de rango nacional e internacional, consolidando al municipio como la capital de la trufa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44211','fiesta','Fiestas de San Blas','Tradicionales hogueras, juegos infantiles y comidas vecinales compartidas que cobran fuerza gracias al complejo del balneario de la localidad. Patronal. Se celebra en Agosto (adaptadas para el verano) y Febrero. Arraigo local y familiar dinamizado puntualmente por los visitantes de la zona balnearia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44212','fiesta','Fiestas en honor a San Valero y San Elena','Pequeñas procesiones tradicionales, reparto de pan bendito y orquestas de noche en el Bajo Aragón. Patronal. Se celebra en Agosto (verano) y Enero. Festejos familiares íntimos con un marcado carácter vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44213','fiesta','Fiestas de la Virgen del Castillo','Romería a la ermita, comidas de hermandad vecinal en la plaza y campeonatos de guiote. Patronal. Se celebra en Agosto. Celebración pequeña de pueblo enfocada a residentes y veraneantes del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50253','fiesta','Fiestas de San Pascual Bailón','Sencillos festejos basados en pasacalles, campeonatos de naipes y comidas populares en la Comunidad de Calatayud. Patronal. Se celebra en Mayo. Festejos íntimos de baja afluencia externa, dirigidos a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44216','fiesta','Fiestas del Ángel (La Vaquilla del Ángel) y Las Bodas de Isabel de Segura','La Vaquilla es una macro-fiesta masiva con encierros de toros ensogados por el casco histórico, y Las Bodas de Isabel es una espectacular recreación histórica medieval de la leyenda de los Amantes de Teruel que transforma por completo la ciudad. Recreación Histórica, Etnográfica, Patronal y Taurina. Se celebra en Julio (La Vaquilla) y Febrero (Las Bodas de Isabel de Segura). Ambas festividades ostentan la declaración de Fiesta de Interés Turístico Nacional, rozando el rango internacional por su afluencia masiva de decenas de miles de turistas de toda España y del extranjero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44217','fiesta','Fiestas de la Virgen del Rosario','Pequeñas romerías locales entre ambos núcleos, comidas de cordero de la sierra y bailes en el local social. Patronal. Se celebra en Agosto. Festejos típicos de pequeña localidad con foco en la convivencia familiar estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44218','fiesta','Fiestas de San Cristóbal y la Virgen de los Desamparados','Tradicionales pasacalles, juegos para niños a orillas del río Ebrón y verbenas de orquesta en la plaza del ayuntamiento. Patronal. Se celebra en Agosto. Orientadas prioritariamente a la comunidad local de los pinares de Rodeno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44219','fiesta','Fiestas de la Virgen de los Olmos','Sobresale su romería tradicional y las comidas populares que congregan a numerosos visitantes atraídos por el entorno natural de la Laguna de Gallocanta. Patronal. Se celebra en Agosto. Fuerte identidad local y comarcal con dinamismo estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44220','fiesta','Fiestas en honor a San Roque','Cenas populares de alforja, campeonatos de guiote y música en directo en su pista municipal de verano. Patronal. Se celebra en Agosto. Celebración pequeña de pueblo, de carácter eminentemente interno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44221','fiesta','Fiestas de San Antón y San Miguel','Sobresale el encendido de la gran hoguera monumental de San Antón y los desfiles de carrozas artesanales durante el verano. Patronal y Etnográfica. Se celebra en Enero y Septiembre. Festejos comarcales bien consolidados con gran arraigo en la comarca del Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44222','fiesta','Fiestas de San Agustín','Procesiones tradicionales arropadas por los núcleos de Godos y Torrecilla, con comidas vecinales y espectáculos infantiles. Patronal. Se celebra en Agosto. Festejos de arraigo local enfocados a la comunidad y al retorno estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44223','fiesta','Fiestas de San Bernardo','Pequeñas cenas vecinales en las calles de piedra, música nocturna y actividades lúdicas tradicionales del Matarraña. Patronal. Se celebra en Agosto. Festejos íntimos de alta montaña con un carácter netamente familiar y local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44224','fiesta','Fiestas en honor a San Bernardo y la Virgen de la Asunción','Reúnen a toda la cuenca minera con sus tradicionales verbenas, campeonatos de guiote y cenas vecinales al aire libre. Patronal. Se celebra en Agosto. Festejos de arraigo local orientados a la convivencia y al retorno estival de las familias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44225','fiesta','Fiestas de San Juan Bautista y San Roque','Destacan sus animadas charangas, las procesiones tradicionales por el casco urbano y las comidas populares a orillas del río Matarraña. Patronal. Se celebra en Agosto. Atractivo vecinal y familiar con buena animación estival gracias al turismo rural de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44227','fiesta','Fiestas de la Virgen del Pilar y San Fabián','Mantienen ritos religiosos tradicionales, orquestas nocturnas en el pabellón municipal y parques infantiles para los más jóvenes. Patronal. Se celebra en Agosto (fiestas de verano) y Enero. Celebración clásica de núcleo pequeño orientada a la identidad comunitaria local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44226','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Cuenta con encierros tradicionales, vaquillas, comidas comunitarias de hermandad y verbenas nocturnas. Patronal y Taurina. Se celebra en Agosto. Fiestas locales muy animadas con buena tradición taurina en la comarca de Teruel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44228','fiesta','Fiestas en honor a San Pedro y San Pablo','Celebran tradicionales pasacalles, jotas aragonesas y cenas vecinales que reactivan el núcleo urbano. Patronal. Se celebra en Junio y Agosto (semana cultural). Orientadas fundamentalmente al ocio de los propios residentes y familiares retornados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44229','fiesta','Fiestas en honor a San Miguel Arcángel','Destacan las comidas vecinales a base de cordero de la sierra y las actividades lúdicas integradas en la naturaleza del entorno. Patronal. Se celebra en Agosto. Festejos de arraigo local potenciados por el turismo estival que visita la Sierra de Albarracín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44231','fiesta','Fiestas de San Cosme y San Damián','Conserva ritos religiosos locales, campeonatos deportivos en el frontón y animadas sesiones de baile en el local social. Patronal. Se celebra en Septiembre. Festejos de arraigo estrictamente local enfocados en actividades familiares para residentes y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44232','fiesta','Fiestas de San Roque y el tradicional Dance de Torrijo','El dance popular acompañado de gaita es un patrimonio folclórico recuperado de gran interés en el valle del Jiloca. Etnográfica y Patronal. Se celebra en Agosto. Interés comarcal destacado gracias al valor de sus danzas tradicionales y su gran ambiente festivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44234','fiesta','Fiestas de la Virgen del Rosario','Sencillos festejos basados en pasacalles, reparto de tortas tradicionales y orquestas populares para todo el vecindario. Patronal. Se celebra en Octubre. Festejos íntimos de baja afluencia, dirigidos a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44235','fiesta','Fiestas en honor a San Roque','Se caracterizan por las cenas populares al aire libre y las tradicionales jotas, atrayendo a visitantes de los pueblos anexos de la sierra. Patronal. Se celebra en Agosto. Pequeña celebración veraniega con un ambiente vecinal muy familiar y acogedor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44239','fiesta','Fiestas de Nuestra Señora de Loreto','Actividades infantiles locales, timbas de guiote y verbenas nocturnas que dinamizan la población en la época estival. Patronal. Se celebra en Agosto. Festejos típicos de pequeña localidad con foco en la convivencia del núcleo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44240','fiesta','Fiestas de la Virgen del Rosario y San Roque','Destacan sus encierros tradicionales, orquestas en la plaza mayor y actividades lúdicas alrededor de su conocido embalse. Patronal y Taurina. Se celebra en Agosto. Notable afluencia de carácter comarcal en Gúdar-Javalambre gracias al turismo de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44241','fiesta','Fiestas en honor a la Virgen de la Natividad y San Miguel','Cuenta con un concurrido desfile de carrozas de peñas, encierros de vaquillas y la tradicional presentación de reinas. Patronal y Taurina. Se celebra en Septiembre. Festejos comarcales con gran implicación vecinal y excelente animación en el Bajo Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44243','fiesta','Fiestas de San Roque','Pequeñas procesiones, comidas de hermandad en el pabellón multiusos y espectáculos de animación infantil. Patronal. Se celebra en Agosto. Festejos enfocados a la comunidad local y al retorno de emigrantes por vacaciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44244','fiesta','Fiestas en honor a la Virgen del Pilar y San Roque','Al ser el municipio más alto de España, sus verbenas estivales gozan de una gran afluencia de turistas de montaña. Patronal. Se celebra en Agosto. Arraigo local reforzado por el gran impacto del turismo geográfico y de nieve de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44245','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Sobresalen las tradicionales rondas musicales por las calles empedradas, las jotas y las comidas comunitarias. Patronal. Se celebra en Agosto. Fuerte lazo identitario en la comarca del Matarraña con buena participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44246','fiesta','Fiestas Patronales de Santiago y Santa Ana','Ofrecen desfiles de carrozas, masivos encierros taurinos y toros de fuego nocturnos bajo el imponente marco monumental de su castillo medieval. Patronal, Taurina y Recreación Histórica. Se celebra en Julio y Agosto. Gran relevancia de nivel provincial y regional; el patrimonio de la villa atrae a millares de visitantes durante su semana grande.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44247','fiesta','Fiestas de San Miguel Arcángel y la Virgen de la Piedad','Conservan las misas cantadas tradicionales, pasacalles con charanga y animadas cenas de hermandad entre peñas. Patronal. Se celebra en Agosto. Festejos de arraigo local con excelente ambiente vecinal en el Matarraña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44250','fiesta','Fiestas en honor a la Santísima Trinidad','Procesión tradicional, puesta de pañuelos y verbenas nocturnas íntimas en el local del ayuntamiento. Patronal. Se celebra en Junio y Agosto (fiestas culturales). Celebración netamente familiar y vecinal con mínima proyección exterior.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44251','fiesta','Fiestas de la Virgen del Campo y San Roque','Destacan sus encierros, competiciones de juegos tradicionales aragoneses y las concurridas verbenas de su plaza. Patronal y Taurina. Se celebra en Agosto. Atractivo comarcal destacado gracias a su afición taurina a lo largo de la cuenca del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44252','fiesta','Fiestas de San Gervasio y San Protasio','Pequeñas carreras populares, juegos para niños en la plaza y cenas vecinales compartidas. Patronal. Se celebra en Junio y Agosto. [1] *. Festejo estrictamente vecinal y de baja afluencia externa orientado al reencuentro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44256','fiesta','Fiestas de San Cristóbal y San Benón','Tradicionales hogueras nocturnas, chocolatadas comunitarias y bailes de sociedad en las noches de verano. Patronal. Se celebra en Julio y Agosto. Celebración pequeña orientada a mantener las costumbres identitarias del núcleo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44257','fiesta','Fiestas en honor a la Virgen del Rosario y los Santos Mártires','Romería tradicional a las ermitas de la Sierra de Albarracín y comidas comunitarias de cordero. Patronal y Etnográfica. Se celebra en Julio. Fuerte carácter de reunión e identidad vecinal en una zona de alta dispersión serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44258','fiesta','Fiestas de la Virgen del Carmen','Pasacalles tradicionales, campeonatos de cartas aragonesas y bailes populares en la pista municipal de verano. Patronal. Se celebra en Julio. Festejos típicos de pequeña localidad con foco en la convivencia del núcleo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44260','fiesta','Fiestas de San Bartolomé y la célebre Romería de San Marcos (La Balma)','Es un hito etnográfico histórico del Maestrazgo que congrega a los pueblos vecinos en una marcha secular de hondo misticismo. Etnográfica y Patronal. Se celebra en Abril (Romería) y Agosto (Patronales). Hito etnográfico comarcal muy valorado debido a la antigüedad y fuerza visual de su romería montañesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44261','fiesta','Fiestas de la Virgen del Pilar y San Roque','Cuenta con encierros tradicionales de reses bravas, suelta de vaquillas en la plaza y multitudinarias comidas de peñas locales. Patronal y Taurina. Se celebra en Agosto. Festejos comarcales con gran animación taurina y juvenil en el eje del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44263','fiesta','Fiestas en honor a Santa Engracia','Procesiones religiosas tradicionales, parques infantiles y verbenas populares nocturnas muy concurridas por su cercanía a la capital. Patronal. Se celebra en Agosto. Puntuación dinamizada por su proximidad a Teruel capital, lo que eleva el flujo de visitantes los fines de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44264','fiesta','Fiestas del Santo Cristo del Consuelo y de la Virgen de la Fuensanta','Destaca su histórica romería al santuario de la Fuensanta y los festejos taurinos populares con toros de fuego. Patronal, Etnográfica y Taurina. Se celebra en Septiembre. Fuerte arraigo identitario comarcal con gran devoción religiosa y afición taurina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44265','fiesta','Fiestas de San Juan Bautista y la Virgen del Pilar','Carreras pedestres tradicionales, pasacalles musicales con charangas locales y cenas vecinales compartidas. Patronal. Se celebra en Junio y Octubre. Arraigo e identidad local en los límites de la comarca del Bajo Martín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44266','fiesta','Fiestas en honor a San Pedro y San Abdón','Conserva misas solemnes tradicionales, comidas de hermandad vecinal y campeonatos de juegos de mesa aragoneses. Patronal. Se celebra en Julio. Festejos familiares enfocados primordialmente a los residentes y familiares emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44267','fiesta','Fiestas de San Roque y San Antón','Incluye el encendido de hogueras tradicionales en invierno y verbenas populares nocturnas al aire libre durante la etapa veraniega. Patronal y Etnográfica. Se celebra en Enero y Agosto. Eventos con encanto vecinal enfocados a la convivencia comunitaria de sus núcleos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90129','fiesta','Fiestas Patronales en honor a la Virgen de la Asunción y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Celebración de arraigo estrictamente local, vertebrada en torno a verbenas tradicionales, procesiones religiosas y actividades culturales dirigidas al retorno estival de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90770','fiesta','Fiestas del Santo Cristo del Consuelo y de la Virgen del Rosario','Patronal. Se celebra en Mayo y Septiembre. Festejos tradicionales de carácter vecinal con misas, pasacalles y cenas populares de fuerte arraigo familiar en el municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90771','fiesta','Fiestas en honor a San Pedro y Nuestra Señora de la Corona','Patronal. Se celebra en Junio y Agosto. Festividad local de corte tradicional en la comarca de Campo de Borja, caracterizada por sus hogueras, comidas populares y campeonatos de juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90131','fiesta','Fiestas de San Pedro de Arbués y la Virgen del Rosario','Patronal. Se celebra en Mayo y Septiembre. Celebración típicamente municipal que congrega a los vecinos en torno a actos religiosos, orquestas nocturnas y eventos lúdicos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49001','fiesta','Fiestas del Santo Cristo de la Capilla y Fiesta de la Vendimia de la D.O','Campo de Borja. Patronal y Enológica. Se celebra en Septiembre. Reconocimiento comarcal relevante por albergar de forma cíclica la Fiesta de la Vendimia, atrayendo a visitantes de la provincia para el primer pisado de la uva y degustaciones culinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90132','fiesta','Fiestas de San Clemente y la Virgen de las Nieves','Patronal. Se celebra en Agosto. Verbena tradicional de pueblo pequeño orientada a la reunión de familias y descendientes de la localidad durante el periodo vacacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','fiesta','Fiestas de San Antonio de Padua y Fiestas en honor a la Virgen del Castillo','Patronal, Etnográfica y Taurina. Se celebra en Junio y Septiembre. Festividad de gran potencia comarcal y provincial, con encierros taurinos de gran tradición, el dance de Alagón y una alta afluencia de visitantes de toda la ribera del Ebro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90133','fiesta','Fiestas en honor a San Pedro y San Roque','Patronal. Se celebra en Agosto. Festejos típicamente vecinales de arraigo local, potenciados en época estival para la acogida de familias y emigrantes retornados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90134','fiesta','Fiestas Patronales de los Santos Cosme y Damián','Patronal. Se celebra en Septiembre. Celebración tradicional de pequeña escala con procesiones, hogueras populares y verbenas musicales de ámbito puramente local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90135','fiesta','Fiestas de Nuestra Señora del Rosario y San Jorge','Patronal. Se celebra en Abril y Septiembre. Pequeñas fiestas de marcado carácter familiar en el valle del Huecha, centradas en la convivencia de la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90136','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Celebración ligada a la Ribera Baja del Ebro, vertebrada en torno a comidas populares, concursos lúdicos y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90137','fiesta','Fiestas de San Gregorio y San Roque','Patronal y Hito Literario. Se celebra en Mayo y Agosto. Atractivo local singular por su vinculación histórica con la Ínsula Barataria de El Quijote, complementado con actos patronales tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90138','fiesta','Fiestas en honor a San Sebastián','Patronal y Etnográfica. Se celebra en Enero y Agosto. Destaca el tradicional "Dance de Alcalá de Moncayo" en el contexto de las faldas del Moncayo, manteniendo vivo un folklore comarcal muy específico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90139','fiesta','Fiestas de San Pascual Bailón y la Virgen de la Leche','Patronal. Se celebra en Mayo y Agosto. Romerías tradicionales y verbenas populares orientadas a la cohesión comunitaria y al retorno de antiguos residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90140','fiesta','Fiestas en honor a la Natividad de la Virgen María','Patronal. Se celebra en Septiembre. Festejos pequeños de carácter estrictamente rural con procesiones, campeonatos de juegos de mesa y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90141','fiesta','Fiestas de la Virgen de la Peña y San Miguel','Patronal y Etnográfica. Se celebra en Septiembre. Reconocimiento comarcal y provincial relevante debido a las romerías a la ermita fortificada, sus espectáculos taurinos tradicionales y su fuerte vida asociativa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90142','fiesta','Fiestas de San Roque','Patronal y Artístico-Cultural. Se celebra en Agosto. A las fiestas tradicionales de San Roque se suma el impacto de su festival de arte urbano, atrayendo visitantes provinciales para ver los murales que decoran el pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90143','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Celebración íntima y familiar característica de las localidades con menor población de la ribera del Ebro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90144','fiesta','Fiestas en honor a San Roque y la Virgen del Castillo','Patronal y Termal-Turística. Se celebra en Agosto. Atrae notable afluencia provincial debido a su estatus de villa termal, complementando los actos religiosos con encierros taurinos y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90145','fiesta','Fiestas de San Gervasio y San Protasio','Patronal. Se celebra en Junio y Agosto. Pequeños festejos tradicionales de arraigo estrictamente local diseñados para la convivencia de la población residente y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90146','fiesta','Fiestas en honor a San Roque y Santa Apolonia','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Destaca la arraigada romería a la Ermita de Santa Elena en la Sierra de Alcubierre y sus dance tradicionales con hondo arraigo en Los Monegros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90147','fiesta','Fiestas de San Roque','Patronal y Arqueológico-Cultural. Se celebra en Agosto. Celebración popular potenciada por el reclamo turístico de su impresionante presa romana, dinamizando la comarca del Campo de Belchite.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90148','fiesta','Fiestas de San Nicolás de Tolentino','Patronal y Enológica. Se celebra en Septiembre. Festejos marcados por la fortísima tradición vitivinícola de la zona, con apertura de bodegas tradicionales y degustaciones populares de vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90149','fiesta','Fiestas de San Sebastián y Santa Pantaria, y las Jornadas de Cine de La Almunia (FESCILA)','Patronal, Etnográfica y Cultural. Se celebra en Septiembre (Patronales) y Mayo (Cine). Fiesta de Interés Turístico Regional por sus Jornadas de Cine de gran empaque y unas fiestas patronales masivas con dances, vaquillas y carrozas de gran envergadura provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90150','fiesta','Fiestas de San Gervasio y San Protasio','Patronal. Se celebra en Junio y Agosto. Festejos tradicionales de arraigo local al pie de la Sierra de Algairén, con cenas en las calles y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90151','fiesta','Fiestas en honor a San Sebastián y las Reliquias','Patronal y Etnográfica. Se celebra en Enero y Agosto. Destaca por el peso histórico de su Palacio de la Orden de Malta y el tradicional Dance de Ambel, referente folclórico de la comarca del Campo de Borja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90152','fiesta','Fiestas de la Virgen de la Aguadora','Patronal y Turística. Se celebra en Julio y Agosto. Fiestas impulsadas por el gran atractivo turístico del municipio como uno de los pueblos más bonitos de España, combinando naturaleza y tradición local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90772','fiesta','Fiestas en honor a la Virgen de Mediavilla','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Festividad montañesa marcada por procesiones tradicionales, su entorno natural en el Parque Natural del Moncayo y encierros populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90154','fiesta','Fiestas en honor a San Cosme y San Damián','Patronal. Se celebra en Septiembre. Festejos comarcales con arraigados encierros de vaquillas, pasacalles musicales y verbenas que atraen a vecinos de las localidades del valle del Jalón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90155','fiesta','Fiestas de San Juan Bautista y la Virgen de los Milagros','Patronal. Se celebra en Junio y Agosto. Festejos rurales de pequeña escala organizados para mantener las tradiciones religiosas y lúdicas compartidas por los residentes y familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90773','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Septiembre. Destacan sus tradicionales festejos taurinos y la suelta de reses, un hito de gran raigambre popular que dinamiza el extremo occidental de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90156','fiesta','Fiestas de San Martín','Patronal y Cultural. Se celebra en Agosto y Noviembre. Pequeña festividad en el Camino de Santiago aragonés que en verano cobra gran relevancia lúdica y juvenil, atrayendo a población de la Jacetania.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90157','fiesta','Fiestas en honor a San Román','Patronal. Se celebra en Agosto. Celebración vecinal típica de las Altas Cinco Villas orientada a preservar cantos tradicionales y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90158','fiesta','Fiestas en honor a San Blas y la Virgen de la Peana','Patronal y Etnográfica. Se celebra en Febrero y Septiembre. Hito etnográfico provincial de primer orden gracias a la máscara de "El Santero" durante San Blas, festividad que incluye el lanzamiento de manzanas y una devoción centenaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90774','fiesta','Fiestas en honor a la Virgen de la Piedad','Patronal. Se celebra en Septiembre. Festejos tradicionales que reúnen elementos religiosos, hogueras y verbenas que dinamizan de forma notable la comarca del Campo de Belchite.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90159','fiesta','Fiestas de San Blas y la Virgen del Rosario','Patronal. Se celebra en Febrero y Agosto. Festejos locales pequeños basados en misas, procesiones tradicionales y comidas comunitarias para el reencuentro de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90160','fiesta','Fiestas de los Santos Julián y Basilisa','Patronal y Cultural. Se celebra en Agosto. Reunión anual de carácter íntimo en torno a su relevante patrimonio románico, sirviendo de reencuentro estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90161','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto. Pequeña verbena de arraigo local al sur de la provincia con enfoque puramente vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50043','fiesta','Fiestas de la Virgen del Rosario y San Antón','Patronal. Se celebra en Mayo y Enero. Celebración de la ribera del Jalón estructurada en torno a comidas en la calle, vaquillas y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50044','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos familiares veraniegos orientados al ocio infantil, juvenil y al regreso de antiguos vecinos a la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','fiesta','Fiestas en honor a la Virgen del Pueyo','Patronal e Histórica. Se celebra en Septiembre. Gran relevancia comarcal potenciada por su trágico trasfondo histórico. Las fiestas patronales incluyen romerías masivas a la ermita de la patrona y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50046','fiesta','Fiestas de San Roque y San Miguel','Patronal. Se celebra en Agosto y Septiembre. Celebración que pone en valor la figura del escritor Baltasar Gracián mediante actos culturales entrelazados con el programa lúdico tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50047','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto. Festejos de pueblo pequeño en el valle del Manubles centrados en bailes públicos y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50048','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Natural. Se celebra en Agosto. Pequeños festejos que aprovechan la cercanía de la Laguna de Gallocanta para atraer visitantes de proximidad geográfica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50901','fiesta','Fiestas de la Virgen de la Asunción','Patronal e Histórica. Se celebra en Agosto. Atractivo turístico por su imponente judería y castillo medieval, lo que eleva el impacto comarcal de sus procesiones y torneos lúdicos estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50050','fiesta','Fiestas de la Virgen del Castillo y Fiestas de los Santos Gervasio y Protasio (Saca de la Virgen cada 25 años)','Patronal y Etnográfica. Se celebra en Agosto / Junio (Cíclica). Cuenta de forma ordinaria con festejos locales, pero alcanza nivel de hito etnográfico de alta singularidad provincial por la "Saca de la Virgen", romería periódica de gran fervor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50051','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Agosto y Septiembre. Festejos notorios en las Cinco Villas con encierros tradicionales, vaquillas y un arraigado programa folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50052','fiesta','Fiestas de San Juan Bautista y la Inmaculada Concepción','Patronal. Se celebra en Junio y Diciembre. Celebración vecinal íntima y de carácter marcadamente familiar en el Campo de Borja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50053','fiesta','Fiestas de San Agustín y la Virgen del Rosario','Patronal y Taurina. Se celebra en Mayo y Agosto. Destaca en la Ribera Alta del Ebro por sus concurridos festejos taurinos populares, vaquillas en la calle y almuerzos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50054','fiesta','Fiestas de la Virgen de los Santos','Patronal. Se celebra en Agosto. Pequeñas verbenas y misas rurales para acoger a las familias de antiguos residentes durante el verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50055','fiesta','Fiestas de San Bartolomé, la Virgen de la Peana y la recreación histórica de la "Entrada de los Reyes Magos"','Patronal, Histórica y Enológica. Se celebra en Agosto y Septiembre. Fiestas de gran empaque comarcal y provincial con el dance de Borja, desfiles de carrozas, ferias comerciales y el hito enoturístico de la capital de la D.O.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50056','fiesta','Fiestas de San Agustín y Nuestra Señora de los Dolores','Patronal y Arqueológica. Se celebra en Mayo y Agosto. Festejos locales impulsados por la notoriedad de los Bronces de Botorrita de la ciudad celtíbera de Contrebia Belaisca, atrayendo turismo cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50057','fiesta','Fiestas en honor a San Blas y Santa Ana','Patronal y Comercial. Se celebra en Febrero y Julio. Potente feria industrial del calzado unida a las fiestas patronales, lo que otorga una marcada relevancia socioeconómica y visitantes en la comarca del Aranda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50058','fiesta','Fiestas de la Virgen de la Esperanza','Patronal. Se celebra en Septiembre. *. Pequeña festividad del valle del Jalón estructurada sobre verbenas, campeonatos de guiñote y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50059','fiesta','Fiestas en honor a San Agustín','Patronal y Etnográfica. Se celebra en Agosto. Festejos monegrinos de relieve con el baile del "Dance de Bujaraloz", pasacalles de peñas y gran arraigo en la llanura aragonesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50064','fiesta','Fiestas de San Ildefonso y Nuestra Señora del Rosario','Patronal. Se celebra en Enero y Agosto. Festejos riberanos con vaquillas, juegos infantiles tradicionales y verbenas orientadas a la población local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50065','fiesta','Fiestas de la Inmaculada Concepción','Patronal. Se celebra en Agosto (adaptadas) y Diciembre. Pequeña celebración popular diseñada exclusivamente para el encuentro de vecinos y familiares emigrados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50066','fiesta','Fiestas del Santo Cristo de Cadrete','Patronal y Gastronómica. Se celebra en Septiembre. Relevancia provincial en el entorno metropolitano de Zaragoza por sus multitudinarias verbenas, festejos taurinos y la promoción de productos hortofrutícolas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','fiesta','Fiestas de San Roque y Fiestas de la Virgen de la Peña','Patronal, Etnográfica y Tradición Musical. Se celebra en Agosto y Septiembre. Fiestas de Interés Turístico Nacional. San Roque congrega a decenas de miles de personas con sus multitudinarias peñas, la mítica petición de las vaquillas y el cantar de "La Dolores".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50068','fiesta','Fiestas del Santísimo Cristo de los Milagros','Patronal y Etnográfica. Se celebra en Septiembre. Fervor religioso masivo en Valdejalón, caracterizado por el dance tradicional, suelta de vaquillas y grandes conciertos públicos de rango provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50069','fiesta','Fiestas de la Virgen del Rosario y la Calcenada','Patronal y Deportivo-De la Tierra. Se celebra en Agosto. Famoso en el plano provincial por la "Calcenada", una multitudinaria marcha senderista y deportiva por la cara oculta del Moncayo que complementa las fiestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50070','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos íntimos apoyados en el idílico paisaje fluvial de las hoces del río Mesa, enfocados al veraneo familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50071','fiesta','Fiestas de San Pedro y San Roque','Patronal. Se celebra en Agosto. Celebración rural modesta basada en romerías tradicionales, orquestas locales y competiciones lúdicas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','fiesta','Fiestas del Santo Cristo de la Santa Cruz','Patronal. Se celebra en Mayo y Agosto. Festejos vinculados al embalse de Tranquera, centrados en el folclore local y comidas hermandadas de vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50073','fiesta','Fiestas del Santo Cristo de Santiago y Fiesta de la Vendimia de Cariñena','Patronal, Enológica y Etnográfica. Se celebra en Septiembre. Fiesta de Interés Turístico de Aragón. El broche enológico es el encendido de la Fuente de la Mora, emanando miles de litros de vino gratis en un festejo multitudinario nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50074','fiesta','Fiestas de San Roque y Conmemoración del Compromiso de Caspe','Patronal y Recreación Histórica. Se celebra en Agosto (Patronales) y Junio (Compromiso). La Recreación del Compromiso de Caspe es Fiesta de Interés Turístico Regional; engalana toda la villa medieval con desfiles, tabernas y rigor histórico de impacto masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50075','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto. Pequeñas verbenas estivales que convocan a las familias y segundas residencias para evitar la despoblación de la tradición local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50076','fiesta','Fiestas de San Pascual Bailón','Patronal. Se celebra en Mayo y Agosto. Celebraciones locales discretas con procesión tradicional a la ermita, juegos tradicionales y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50077','fiesta','Fiestas de la Virgen del Rosario y San Sebastián','Patronal y Gastronómica. Se celebra en Mayo y Agosto. Famoso en la comarca por el consumo tradicional de escabeches de conejo y perdiz durante sus fiestas, atrayendo gastrónomos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50078','fiesta','Fiestas del Santo Cristo de la Capilla','Patronal e Histórica. Se celebra en Mayo y Agosto. Festejos tradicionales marcados por el notable patrimonio histórico-medieval de las Cinco Villas, incluyendo procesiones solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50079','fiesta','Fiestas de la Virgen del Monte','Patronal y Cultural. Se celebra en Septiembre. Festejos dinamizados por el orgullo local de poseer la iglesia mudéjar de Santa Tecla, declarada Patrimonio de la Humanidad por la UNESCO.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50080','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Encuentros lúdicos familiares de muy pequeña escala orientados a la pervivencia cultural de la comunidad rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50093','fiesta','Fiestas de San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Septiembre. La célebre "Carrera de Chodes" o de las "Poyatas" se celebra en su icónica e histórica plaza de toros circular, atrayendo a numeroso público provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50082','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto. Romerías locales vinculadas al nacimiento del río Piedra, atrayendo turismo de naturaleza y veraneantes de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50083','fiesta','Fiestas de San Blas','Patronal. Se celebra en Febrero y Agosto. Pequeña fiesta de la Ribera Baja con reparto de pan bendito, hogueras invernales y orquestas en época veraniega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50084','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Actividades lúdicas tradicionales de arraigo estrictamente local para el reencuentro de la población emigrada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50085','fiesta','Fiestas en honor a San Bernardo','Patronal y Etnográfica. Se celebra en Agosto. Cuenta con el tradicional Dance de Codo, reliquia folclórica de los Monegros zaragozanos que realza las procesiones patronales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50086','fiesta','Fiestas del Santo Cristo del Mar y de la Virgen de la Natividad','Patronal. Se celebra en Agosto. Festejos típicamente vecinales y familiares en la cabecera del río Grío, muy volcados en el retorno de los emigrantes en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50087','fiesta','Fiestas de San Bartolomé y San Jerónimo','Patronal. Se celebra en Agosto. Celebración de arraigo estrictamente local con verbenas y comidas comunitarias en un núcleo de muy baja densidad demográfica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50088','fiesta','Fiestas en honor al Santo Cristo de la Agonía','Patronal y Enológica. Se celebra en Agosto. Festejos tradicionales marcados por la cultura vinícola de la D.O. Cariñena, incluyendo pasacalles, vaquillas y jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50089','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Lúdica-Urbana. Se celebra en Agosto. Municipio de gran crecimiento demográfico periurbano que organiza unas fiestas masivas con conciertos potentes y gran afluencia del área metropolitana de Zaragoza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50090','fiesta','Fiestas en honor a la Virgen de la Guía y San Jerónimo','Patronal. Se celebra en Agosto. Celebraciones locales en el pueblo más alto de la provincia, caracterizadas por su ambiente familiar y hogueras tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50091','fiesta','Fiestas en honor a San Pedro en Cátedra y la Virgen del Rosario','Patronal. Se celebra en Agosto. Pequeños festejos tradicionales junto a la Laguna de Gallocanta, enfocados en la reunión vecinal y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50092','fiesta','Fiestas en honor a San Roque y la Virgen de la Consolación','Patronal y Etnográfica. Se celebra en Agosto. Festejos de fuerte arraigo en la comarca del Bajo Aragón-Caspe, destacando las procesiones a su ermita románica y sus tradicionales carreras pedrestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','fiesta','Fiestas del Corpus Christi y Festival de Música Antigua de Daroca','Patronal, Etnográfica y Cultural. Se celebra en Junio (Corpus) y Agosto (Festival). Fiesta de Interés Turístico Regional. La procesión del Corpus Christi con los Sagrados Corporales posee un valor histórico y religioso monumental, sumado a un festival musical de prestigio internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50095','fiesta','Fiestas de la Virgen de la Oliva y Feria de Ejea','Patronal, Taurina y Comercial. Se celebra en Septiembre (Fiestas) y Marzo/Abril (Feria). Grandes fiestas de empaque provincial en la capital de las Cinco Villas, con un ciclo taurino muy potente, encierros masivos, grandes conciertos y una feria comercial multisectorial de referencia regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50096','fiesta','Fiestas en honor a Santa Ana','Patronal. Se celebra en Julio. Pequeña festividad veraniega con comidas populares en el estrecho valle del río Henar, dirigida a la comunidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50098','fiesta','Fiestas de la Virgen del Mar y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Destaca la devoción a la Virgen del Mar con cantos tradicionales de auroros de origen bajomedieval y procesiones con hondo arraigo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50099','fiesta','Fiestas en honor a San Frontonio y Carnavales de Épila','Patronal y Etnográfica. Se celebra en Mayo (San Frontonio) y Febrero (Carnavales). Los Carnavales de Épila son unos de los más singulares de Aragón, destacando las "mascarutas" y el mantenimiento de tradiciones singulares. Sus fiestas patronales arrastran a toda la comarca de Valdejalón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50100','fiesta','Fiestas en honor a San Gregorio','Patronal. Se celebra en Mayo. Romería tradicional a la ermita de la Corona, combinada con orquestas y actividades infantiles para el vecindario de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50101','fiesta','Fiestas de Santa Águeda','Patronal y Etnográfica. Se celebra en Febrero. Festejos de gran singularidad comarcal por la Procesión de las Panbenditeras, donde las jóvenes portan canastas con pan bendito ataviadas con el traje regional aragonés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50102','fiesta','Fiestas en honor a San Isidro y San Roque','Patronal. Se celebra en Mayo y Agosto. Tradiciones ligadas a la comarca del Bajo Aragón-Caspe, dinamizadas por pasacalles, toros de fuego y cenas en las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50104','fiesta','Fiestas de la Virgen de la Sabina','Patronal y Etnográfica. Se celebra en Mayo. Romería tradicional al santuario de la Virgen de la Sabina en pleno desierto de Los Monegros, con bailes tradicionales y jornadas de convivencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50105','fiesta','Recreación Histórica de la Batalla del Ebro y Fiestas de Santa Ana','Recreación Histórica y Patronal. Se celebra en Julio. Su recreación de la Batalla del Ebro es uno de los eventos de reconstrucción históricomilitar más importantes de España, atrayendo a miles de visitantes y recreadores de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50107','fiesta','Fiestas en honor a San Isidro Labrador y la Virgen del Carmen','Patronal y Taurina. Se celebra en Mayo y Octubre. Fiestas muy populares marcadas por la presencia de festejos taurinos tradicionales, encierros y la alta participación vecinal ligada al dinamismo industrial del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50108','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Celebración pequeña de marcado carácter familiar para la reunión estival de descendientes del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50109','fiesta','Fiestas de la Virgen del Asalto y San Miguel','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Se conmemora el milagro del "Asalto" con procesiones religiosas de origen medieval y actividades tradicionales en las Cinco Villas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50111','fiesta','Fiestas en honor a la Virgen del Pilar y San Guillermo','Patronal. Se celebra en Mayo y Octubre. Festejos familiares en el valle del Huecha, con verbenas y comidas populares de arraigo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50113','fiesta','Fiestas de Nuestra Señora del Castillo y San Juan Bautista','Patronal y Enológica. Se celebra en Mayo y Septiembre. Muy marcadas por el peso de sus cooperativas vitivinícolas de la D.O. Campo de Borja, combinando vaquillas con el reparto de vino y ritos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50114','fiesta','Fiestas en honor a San Bartolomé y Fiesta Goyesca','Patronal y Recreación Cultural. Se celebra en Agosto y Septiembre (Goyesca). La Fiesta Goyesca recrea la época del pintor universal Francisco de Goya en su villa natal, con vestimentas de época y mercados, sumando proyección provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50115','fiesta','Fiestas de San Miguel Arcángel y la Virgen del Rosario','Patronal y Gastronómica. Se celebra en Septiembre/Octubre. *. Festejos potentes que integran la promoción de la célebre Cebolla Fuentes de Ebro con Denominación de Origen, además de contar con encierros taurinos y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50117','fiesta','Fiestas en honor a la Virgen del Buen Acuerdo y San Lourenzo','Patronal y Ornitológica. Se celebra en Agosto y Noviembre (Festival de las Grullas). Aunque las patronales son locales, el Festival de las Grullas atrae a ecoturistas de todo el país por el paso migratorio sobre su famosa laguna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50118','fiesta','Fiestas de San Pedro y la Cátedra de San Pedro','Patronal y Etnográfica. Se celebra en Junio y Febrero. Destacan por el riquísimo e histórico Dance de Gallur con sus tradicionales mudanzas, declaradas de gran valor antropológico en la Ribera Alta del Ebro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50119','fiesta','Fiestas de la Virgen del Buen Suceso y San Pedro de Verona','Patronal y Taurina. Se celebra en Abril y Agosto. Festejos con encierros de reses bravas por sus calles, procesiones solemnes y alta participación de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50120','fiesta','Fiestas de San Jorge y de la Virgen de la Esperanza','Patronal. Se celebra en Mayo y Agosto. Pequeñas verbenas veraniegas en las cercanías del alto Jalón, destinadas a la reunión de vecinos dispersos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50121','fiesta','Fiestas en honor a Santiago Apóstol y la Virgen de la Asunción','Patronal. Se celebra en Julio y Agosto. Celebraciones en el Valle del Aranda con misas tradicionales, campeonatos deportivos populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50122','fiesta','Fiestas de la Virgen de las Mercedes y San Samper','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Famoso en la comarca de Tarazona por la romería al pozo de San Miguel y las leyendas tradicionales vinculadas a su sima natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50123','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Festejos vecinales marcados por las comidas populares y los espectáculos musicales en el pabellón municipal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50124','fiesta','Fiestas de la Virgen de Herrera','Patronal y Etnográfica. Se celebra en Septiembre. Gran romería al Santuario de la Virgen de Herrera, situado en un monte elevado, reuniendo a cofrades e invitados de múltiples pueblos limítrofes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50125','fiesta','Fiestas en honor a San Roque y la Virgen de San Daniel','Patronal y Etnográfica. Se celebra en Agosto. Destacan los pasacalles populares, los tradicionales encierros y la visita turística vecinal a su gruta de las Maravillas durante los festejos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50126','fiesta','Fiestas de San Babil y de San Juan Bautista','Patronal, Taurina y Comercial. Se celebra en Enero y Junio. Capital del Valle del Aranda que concentra grandes espectáculos taurinos, ferias vinculadas a la industria del calzado y hogueras masivas por San Babil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50129','fiesta','Fiestas en honor a la Virgen de Jaraba y San Vicente','Patronal y Termal. Se celebra en Agosto y Septiembre. Festejos que aprovechan la importante afluencia estival de sus balnearios, organizando procesiones a la ermita en el cañón del río Mesa y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50130','fiesta','Fiestas de la Virgen del Rosario y del Santo Cristo de la Piedad','Patronal. Se celebra en Agosto y Septiembre. Tradición local en el somontano del Moncayo con rondallas de jota, competiciones populares y toros de fuego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50131','fiesta','Fiestas de la Natividad de la Virgen','Patronal. Se celebra en Septiembre. Festejos íntimos centrados en comidas populares, espectáculos de variedades y actividades para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50132','fiesta','Fiestas de la Virgen del Rosario y San Jorge','Patronal. Se celebra en Septiembre y Abril. Festejos tradicionales de la Ribera Alta de marcado ambiente vecinal con orquestas y suelta de vaquillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50135','fiesta','Fiestas en honor a Santo Tomás','Patronal y Arqueológica. Se celebra en Diciembre y Agosto. Pequeña festividad dinamizada en verano por las visitas al yacimiento romano de Los Bañales en las Cinco Villas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50136','fiesta','Fiestas de Santo Domingo de Guzmán','Patronal y Enológica. Se celebra en Agosto. Fiestas arraigadas en el Campo de Belchite con encierros de vaquillas, peñas muy activas y degustaciones del vino de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50138','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Verbena tradicional de pueblo pequeño concebida para la reunión anual de familias veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50137','fiesta','Fiestas de la Virgen de Monegros y la Venida de la Virgen','Patronal y Etnográfica. Se celebra en Septiembre y Marzo. Hito religioso y de folklore en Los Monegros, destacando la multitudinaria romería al Santuario de la Virgen de Magallón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50139','fiesta','Fiestas en honor a San Atanasio y la Virgen de los Dolores','Patronal. Se celebra en Mayo y Agosto. Festejos locales marcados por las tradiciones de la cuenca del río Aguasvivas, con reparto de pan bendito y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50140','fiesta','Fiestas de San Sebastián y la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Enero y Agosto. Destaca el pesaje y reparto tradicional de uvas y panes benditos en las faldas del Moncayo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50141','fiesta','Fiesta de los Pesos y Fiestas de San Miguel','Etnográfica y Patronal. Se celebra en Julio y Septiembre. La "Fiesta de los Pesos" es un rito medieval único catalogado como Fiesta de Interés Turístico de Aragón, donde se pesa a los niños nacidos en el año y se ofrece su peso en trigo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50142','fiesta','Fiestas de San Ramón Nonato','Patronal y Etnográfica. Se celebra en Agosto. Festejos que reviven antiguas leyendas pirenaicas y el folklore tradicional del valle de la Onsella.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50143','fiesta','Fiestas en honor a San Vicente y San Gonzalo','Patronal y Etnográfica. Se celebra en Septiembre. Famoso por el "Paloteao de Longares", un baile folclórico ancestral ejecutado en procesión que cuenta con la declaración de Fiesta de Interés Turístico de Aragón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50144','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Pequeñas celebraciones de alta montaña en las Cinco Villas, centradas en la hermandad de sus escasos habitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50146','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio. Festejos tradicionales de ribera con procesiones populares y espectáculos musicales para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50147','fiesta','Fiestas de San Pedro y la Virgen del Rosario','Patronal y Taurina. Se celebra en Junio y Octubre. Festejos marcados por una gran afición taurina con suelta de reses en la calle y competiciones de jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50148','fiesta','Fiestas de San Esteban y la Virgen del Campo','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Se celebran con solemnes romerías a la ermita y un gran ambiente de peñas medievales en el prepirineo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50151','fiesta','Fiestas del Santo Cristo de los Milagros','Patronal y Etnográfica. Se celebra en Septiembre. Destaca la bajada del Santo Cristo en procesión de antorchas y los tradicionales encierros de vaquillas de gran seguimiento comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50152','fiesta','Fiestas en honor a San Lorenzo y San Esteban','Patronal y Gastronómica. Se celebra en Agosto. Festejos masivos en la comarca del Bajo Aragón-Caspe, populares por la elaboración de "sardinadas" y platos de melocotón local con vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50153','fiesta','Fiestas de San Lorenzo y de Nuestra Señora de la Huerta','Patronal, Enológica y Musical. Se celebra en Agosto y Septiembre. Gran tradición en torno a la cultura musical de su banda y la cultura del vino de la D.O. Campo de Borja, abriendo sus bodegas excavadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50154','fiesta','Fiestas de la Virgen del Rosario y San Roque','Patronal. Se celebra en Agosto. Celebración puramente vecinal centrada en orquestas de verbena y meriendas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50155','fiesta','Fiestas del Santo Cristo de la Humildad','Patronal y Molinera. Se celebra en Agosto. Festejos dinamizados por las actividades culturales en torno a su restaurado e icónico molino de viento de tipo manchego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50156','fiesta','Fiestas de la Virgen del Castillo','Patronal. Se celebra en Septiembre. Pequeña festividad en el valle del Huecha orientada a los juegos tradicionales y el folclore jotero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50160','fiesta','Fiestas del Santo Cristo de la Columna y Nuestra Señora de la Merced','Patronal, Etnográfica y Taurina. Se celebra en Julio y Septiembre. Festejos de gran entidad con un prestigioso Dance tradicional, encierros de reses bravas muy concurridos y un arraigo histórico notable en el límite fronterizo con Navarra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50157','fiesta','Fiestas de San Vicente y San Roque','Patronal. Se celebra en Enero y Agosto. Festejos tradicionales de la comarca de Tarazona, destacando las comidas populares en las bodegas del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50159','fiesta','Fiestas de las Santas Justa y Rufina','Patronal y Etnográfica. Se celebra en Julio y Septiembre. Destaca la devoción mudejar de sus templos y las procesiones tradicionales que congregan a toda la vega del Jiloca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50902','fiesta','Fiestas de Santa Catalina','Patronal. Se celebra en Mayo y Noviembre. Pequeña e íntima festividad vecinal en las orillas del río Gállego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50164','fiesta','Fiestas de San Gregorio y Santa Ana','Patronal. Se celebra en Mayo y Julio. Fiestas típicamente de comarca árida con reparto de raciones populares, charangas y bailes nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50165','fiesta','Fiestas de Santa Agatoclia (La Santa) y Fiesta de San Blas y Santa Águeda','Patronal, Etnográfica y Deportiva. Se celebra en Septiembre (La Santa) y Febrero (San Blas). Sus fiestas de San Blas y Santa Águeda son Fiesta de Interés Turístico de Aragón por sus espectaculares disfraces artesanales. Sus patronales destacan por competiciones náuticas en el "Mar de Aragón".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50166','fiesta','Fiestas del Santo Cristo de los Milagros','Patronal y Cultural. Se celebra en Agosto. Celebraciones coronadas por el imponente Castillo de Mesones, donde se realizan actividades culturales y recreativas de ambiente medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50167','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Septiembre. Festejos tradicionales marcados por el turismo recreativo de su embalse y peñas festivas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50169','fiesta','Fiestas de San Blas y la Virgen de la Regla','Patronal y Enológica. Se celebra en Febrero y Septiembre. Celebraciones tradicionales en la Comunidad de Calatayud apoyadas en su rica producción de vino cooperativista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19183','fiesta','Fiestas de la Virgen de la Fuente','Patronal y Alfarera. Se celebra en Septiembre. Festejos de gran calado provincial; destacan la romería a la ermita decorada por Goya y las demostraciones de su afamada alfarería tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50173','fiesta','Fiestas en honor a la Virgen del Castillo y San Roque','Patronal. Se celebra en Agosto. Festividades de arraigo puramente vecinal y rural, impulsadas por la Asociación Cultural local para el fomento de verbenas y el retorno estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50174','fiesta','Fiestas de San Juan y la Virgen del Cid','Patronal. Se celebra en Agosto. Celebración tradicional con una arraigada romería a la ermita de la Virgen, orquestas nocturnas y cenas de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50175','fiesta','Fiestas de Santa Ana y San Roque','Patronal y Etnográfica. Se celebra en Julio y Agosto. Festejos de notable arraigo comarcal que incluyen encierros taurinos, carrozas y actividades en las peñas locales con gran concurrencia del valle del Jalón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50176','fiesta','Fiestas en honor a San Martín','Patronal. Se celebra en Noviembre y Agosto (fiestas de verano). Festejos locales que cobran gran vida en su edición estival gracias a la reunión de descendientes del pueblo en la comarca de Calatayud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50177','fiesta','Fiestas de San Félix y la Virgen del Rosario','Patronal. Se celebra en Agosto y Septiembre. Cuenta con gran animación en la comarca de la Comunidad de Calatayud, destacando sus procesiones y sus concurridos festejos taurinos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50178','fiesta','Fiestas de la Virgen de la Vega y San Eulogio','Patronal. Se celebra en Agosto and Septiembre. Celebración tradicional en el escarpado entramado urbano del municipio, estructurada con pasacalles, jotas y charangas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50179','fiesta','Fiestas de San Clemente y la Virgen de la Altura','Patronal y Etnográfica. Se celebra en Agosto. Destaca su tradicional romería a la ermita de la Virgen de la Altura y la intensa agenda cultural que dinamiza la comarca del Campo de Belchite.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50180','fiesta','Fiestas de los Santos Mártires (San Cornelio y San Cipriano)','Patronal. Se celebra en Septiembre. Pequeña festividad vecinal cercana a la capital aragonesa, centrada en comidas populares, espectáculos infantiles y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50181','fiesta','Fiestas en honor a la Virgen de la Fuente','Patronal, Etnográfica y Artesanal. Se celebra en Septiembre. Festejos de fuerte impacto comarcal gracias al atractivo cultural de su ermita decorada por Goya y su histórica tradición cerámica, atrayendo a numeroso público provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50184','fiesta','Fiestas de San Mamés y la Virgen del Rosario','Patronal. Se celebra en Agosto. Celebración de escala familiar en el valle del Jiloca, muy vinculada a los talleres culturales estivales y al turismo paleontológico local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50185','fiesta','Fiestas de la Virgen de la Candelaria y San Bartolomé','Patronal y de Turismo Activo. Se celebra en Febrero y Agosto. La afluencia a sus fiestas estivales se ve potenciada por su condición de centro neurálgico de deportes de aventura junto a los Mallos de Riglos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50186','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeños festejos tradicionales en la comarca de las Cinco Villas, enfocados en la conservación de tradiciones locales y reuniones familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50187','fiesta','Fiestas de San Vicente Ferrer','Patronal. Se celebra en Abril y Agosto. Verbenas y celebraciones de carácter netamente local e íntimo, diseñadas para el reencuentro de la vecindad en el valle del Isuela.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50188','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos rurales tradicionales de pequeña escala, orientados plenamente al retorno de los emigrantes de la localidad durante el verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50189','fiesta','Fiestas de San Bartolomé y la Virgen de Dos Aguas','Patronal y Etnográfica. Se celebra en Agosto. Celebración singular en el Bajo Aragón-Caspe, destacando la romería a la ermita de la Virgen de Dos Aguas —en la confluencia de los ríos Matarraña y Algars— y desfiles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50190','fiesta','Fiestas de San Marcial','Patronal y Taurina. Se celebra en Junio/Julio. Festejos muy activos en la comarca de Tarazona y el Moncayo, reconocidos por sus intensos espectáculos taurinos, encierros y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50191','fiesta','Fiestas en honor a San Nicasio y la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto. Festejos muy animados en la ribera del Ebro, con tradicionales encierros y suelta de vaquillas que congregan a jóvenes de localidades vecinas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','fiesta','Fiestas de la Virgen de los Alantares y San Sebastián','Patronal y Turística. Se celebra en Agosto. Festejos con notable afluencia provincial debido al gran flujo de visitantes que genera la proximidad inmediata del Monasterio de Piedra y el embalse de Tranquera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50193','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Julio (fiestas de verano). Su cercanía a Zaragoza capital le otorga una alta asistencia en sus verbenas estivales, concursos gastronómicos y actos lúdicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50194','fiesta','Fiestas de la Santa Cruz y la Virgen del Milagro','Patronal. Se celebra en Mayo y Agosto. Tradición local centrada en misas mayores, procesiones a las ermitas y pequeñas orquestas para los vecinos de la comunidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50195','fiesta','Fiestas en honor a San Nicolás de Bari y la Virgen del Rosario','Patronal. Se celebra en Agosto. Celebración típicamente veraniega en el Campo de Daroca, dinamizada por asociaciones juveniles para mantener vivas las orquestas y juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50196','fiesta','Fiestas del Santo Cristo de la Columna','Patronal. Se celebra en Agosto. Pequeña festividad vecinal que destaca por sus tradicionales hogueras y cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50197','fiesta','Fiestas de San Juan Bautista y la Virgen de la rasmia; Festival "Orés Mágico"','Patronal y Cultural. Se celebra en Agosto (Patronales) y Junio (Magia). Logra un reconocimiento comarcal muy destacado e innovador gracias a su festival de magia urbana, que multiplica la población del pueblo con magos internacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50198','fiesta','Fiestas en honor a la Virgen del Pilar y San Cristóbal','Patronal. Se celebra en Agosto. Festejos tradicionales de baja intensidad en la cara oculta del Moncayo, dedicados a la convivencia familiar y comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50199','fiesta','Fiestas de Santa Engracia y San Martín','Patronal. Se celebra en Abril y Noviembre. Festejos de arraigo local en la Ribera Baja del Ebro, con alta participación vecinal en vaquillas y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50200','fiesta','Fiestas de la Virgen del Águila y San José','Patronal y Enológica. Se celebra en Septiembre. Festejos muy concurridos en el Campo de Cariñena, vinculados fuertemente a la tradición del vino, la subida a la ermita de la Virgen del Águila y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50201','fiesta','Fiestas de San Íñigo y San Roque','Patronal y Termal. Se celebra en Junio y Agosto. Su vinculación histórica con su conocido balneario aporta un flujo constante de visitantes a sus tradicionales fiestas patronales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50202','fiesta','Fiestas de San Pedro y San Roque','Patronal. Se celebra en Agosto. Festejos del valle del Jalón enfocados en mantener vivas las tradiciones agrarias, jotas y orquestas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50203','fiesta','Fiestas de San Pedro de Verona y San Roque','Patronal y Medioambiental. Se celebra en Abril y Agosto. Atrae numeroso público de Zaragoza debido a su cercanía y su vinculación con el espacio natural de la Reserva de los Galachos de La Alfranca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50204','fiesta','Fiestas de San Roque y la Virgen del Pilar','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festejos de gran calado provincial; destacan sus encierros, sus tradicionales "recreaciones barrocas" vinculadas al Palacio de los Duques de Villahermosa e intensos actos en peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50205','fiesta','Fiestas de San Roque y San Bartolomé','Patronal. Se celebra en Agosto. Pequeña festividad en las Cinco Villas orientada a campeonatos lúdicos, comidas vecinales en la plaza Mayor y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50206','fiesta','Fiestas de Santa Beatriz y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Cuenta con un arraigo comarcal sólido en Los Monegros zaragozanos gracias a sus tradicionales dances, encierros y la romería a la ermita de San José.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50207','fiesta','Fiestas de San Ramón Nonato','Patronal. Se celebra en Agosto. Festejos locales pequeños e íntimos con comidas populares para celebrar la época post-cosecha y recibir a los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50208','fiesta','Fiestas de San Roque y San Gregorio','Patronal y Taurina. Se celebra en Mayo y Agosto. Macro-fiestas de gran empaque provincial conocidas por sus espectaculares encierros al lado del río Ebro, concursos taurinos de renombre regional y masivos conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50209','fiesta','Fiestas de San Pedro Mártir de Verona y la Virgen de la Merced','Patronal. Se celebra en Abril y Septiembre. Fuerte crecimiento de asistencia provincial debido a su expansión demográfica y cercanía a la capital, con verbenas de gran formato y festejos taurinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50211','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio. Festejos vecinales de pequeña escala que giran en torno a la hoguera de San Antonio, jotas y cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50212','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Celebración estrictamente vecinal, de carácter familiar y muy íntimo en una de las localidades con menor población de la ribera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50213','fiesta','Fiestas en honor a la Virgen del Pilar y San Agustín','Patronal y Cultural. Se celebra en Agosto. Fiestas complementadas por la labor de su museo etnográfico local, orientadas a revitalizar la historia y costumbres de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50214','fiesta','Fiestas de San Jorge y la Virgen de los Dolores','Patronal. Se celebra en Abril y Agosto. Celebración familiar de marcado carácter rural en el límite provincial con Soria, enfocada a la cohesión vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50215','fiesta','Fiestas en honor a San Pedro y San Roque','Patronal. Se celebra en Agosto. Pequeña verbena de arraigo local para acoger a las familias emigrantes que retornan en la época estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50216','fiesta','Fiestas de Santiago Apóstol y Santa Ana','Patronal. Se celebra en Julio. Festividad local en el Campo de Borja, vertebrada por el volteo de campanas, pasacalles con charangas y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50217','fiesta','Fiestas de San Sebastián y la Virgen del Rosario','Patronal y Taurina. Se celebra en Enero y Septiembre. Destacan por sus tradicionales espectáculos de vaquillas en calles y plazas anexas al cauce del Ebro, con gran arraigo en la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50219','fiesta','Fiestas del Rosario y San Roque','Patronal. Se celebra en Agosto. Festejos masivos debido a su gran población industrial y cercanía a Zaragoza, ofreciendo conciertos de primera línea, comparsas de gigantes y cabezudos y fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50218','fiesta','Fiestas de San Pelayo','Patronal. Se celebra en Junio y Agosto. Celebración de arraigo local conocida históricamente por ser la tierra natal de los antepasados de Juan Antonio Artigas, dinamizada con actos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50220','fiesta','Fiestas de San Nicolás','Patronal. Se celebra en Diciembre y Agosto (fiestas de verano). Pequeñas verbenas junto al río Gállego, organizadas por y para los vecinos con carácter entrañable y vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50221','fiesta','Fiestas en honor a la Virgen de Constantín','Patronal y de Naturaleza. Se celebra en Septiembre. Conocido por ser "el pueblo con menos habitantes de España con semáforo", sus fiestas atraen a senderistas y amantes del Moncayo por su espectacular enclave.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50222','fiesta','Fiestas de Santa Ana','Patronal, Taurina y Cultural. Se celebra en Julio. Gran empaque comarcal y provincial en la Ribera Baja del Ebro; destacan sus tradicionales encierros y el reclamo cultural de su célebre Museo de las Momias de Quinto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50223','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal y Etnográfica. Se celebra en Septiembre. Festejos vinculados culturalmente a sus históricas minas de sal, celebrados con dances tradicionales, vaquillas y gran animación en sus peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50224','fiesta','Fiestas de la Virgen de los Ángeles y San Cristóbal','Patronal. Se celebra en Agosto. Fiestas típicamente de reencuentro rural en la comarca de Daroca, dinamizadas con campeonatos de guiote y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50225','fiesta','Fiestas de María Magdalena y la Virgen de la Media Villa','Patronal y Taurina. Se celebra en Julio y Septiembre. Gran relevancia provincial por la afición taurina de la localidad, celebrando importantes concursos de recortes, encierros y una gran vida peñista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50227','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos a la sombra de su torre mudéjar, enfocados a unir a la comunidad y a los familiares emigrados mediante cenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50228','fiesta','Fiestas de Santiago Apóstol y San Ignacio de Loyola','Patronal. Se celebra en Julio. Celebración local junto a los restos de su castillo medieval, organizada con encierros tradicionales y espectáculos lúdicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50241','fiesta','Fiestas del Santo Cristo de la Agonía y San Roque','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Festejos en el valle del Jalón con arraigo histórico, procesión del Santo Cristo, dance tradicional de jotas y suelta de vaquillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50230','fiesta','Fiestas de la Virgen del Castillo','Patronal y Recreación Histórica. Se celebra en Agosto. Potente festejo en las Cinco Villas que aprovecha el marco monumental de su imponente castillo medieval para organizar desfiles, encierros de reses bravas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50231','fiesta','Fiestas de San Martín y la Virgen del Rosario','Patronal. Se celebra en Octubre y Mayo. Celebraciones locales centradas en procesiones religiosas tradicionales, pasacalles musicales y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50232','fiesta','Fiestas en honor a la Virgen de la Peña','Patronal y Pirinaica. Se celebra en Septiembre. Festejos marcados por su proximidad a Navarra y el Pirineo, destacando sus tradiciones montañesas y comidas de hermandad en un bello casco urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50233','fiesta','Fiestas del Santo Cristo de la Salud','Patronal. Se celebra en Agosto. Celebración de ámbito estrictamente local para el reencuentro de la población con familiares retornados en la temporada estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50234','fiesta','Fiestas de San Martín y la Virgen del Pilar','Patronal y Micológica. Se celebra en Noviembre (Micológicas) y Agosto (Verano). Muy conocida en el ámbito provincial por sus consolidadas jornadas micológicas en otoño, atrayendo a centenares de micólogos y gastrónomos al Moncayo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50235','fiesta','Fiestas de San Mateo Apóstol','Patronal y Taurina. Se celebra en Septiembre. Festejos masivos con gran relevancia comarcal, caracterizados por sus encierros taurinos, verbenas de gran envergadura y una alta participación juvenil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50236','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Fiestas tradicionales de la Sierra de Algairen orientadas a actividades vecinales e infantiles en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50237','fiesta','Fiestas de la Santa Cruz y San Juan Baja','Patronal. Se celebra en Mayo y Agosto. Festejos pequeños en las faldas del Moncayo, basados en procesiones a la ermita, jotas aragonesas y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50238','fiesta','Fiestas en honor a Santa Eulalia','Patronal. Se celebra en Agosto. Atractivas fiestas estivales potenciadas por el turismo de aguas bravas del río Gállego, atrayendo a jóvenes de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50239','fiesta','Fiestas de San Justo y San Pastor','Patronal. Se celebra en Agosto. Celebración rural vecinal en el entorno de la Laguna de Gallocanta, enfocada a la preservación de tradiciones locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50240','fiesta','Fiestas en honor a San Roque y la Virgen de Montler','Patronal y Etnográfica. Se celebra en Agosto. Festividad de relevancia comarcal en la Ribera Baja del Ebro, destacando la tradicional procesión de "pan bendito", el dance sastaguino y sus concurridas verbenas junto al río.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50242','fiesta','Fiestas de San Pedro Arbués y la Virgen del Rosario','Patronal. Se celebra en Agosto. Celebración típicamente vecinal de la Sierra de Vicor, volcada en cenas compartidas en la plaza, pasacalles y el retorno vacacional de las familias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50243','fiesta','Fiestas de San Bartolomé y la Virgen del Carmen','Patronal. Se celebra en Agosto. Festejos tradicionales de arraigo local que dinamizan la comarca del Aranda con competiciones deportivas, orquestas y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50244','fiesta','Fiestas del Santo Cristo de las Tres Cruces','Patronal y Etnográfica. Se celebra en Agosto. Celebración de las Cinco Villas caracterizada por su fervor religioso en las procesiones, campeonatos de jotas y espectáculos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50245','fiesta','Fiestas de San Fermín y Santa Ana','Patronal. Se celebra en Julio. Pequeña festividad pirenaica en la Jacetania zaragozana, orientada a la convivencia de los vecinos y visitantes de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16198','fiesta','Fiestas de San Roque y San Justo y Pastor','Patronal. Se celebra en Agosto. Festejos pequeños de carácter rural con misas solemnes, comidas populares en el pabellón y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50247','fiesta','Fiestas en honor a San Antonio de Padua y San Santiago','Patronal y Taurina. Se celebra en Junio y Julio. Gran animación en la comarca de Zaragoza debido a la proximidad a la capital, con encierros de reses bravas y una potente agenda lúdica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','fiesta','Fiestas Patronales en honor a San Esteban y la Virgen de Valentuñana, y las Fiestas del Nacimiento de Fernando el Católico','Patronal y Recreación Histórica. Se celebra en Agosto (Patronales) y Marzo (Recreación). Fiesta de Interés Turístico Regional por sus recreaciones históricas medievales que transforman el casco histórico fortificado, atrayendo turismo de todo el país.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50249','fiesta','Fiestas de la Virgen del Rosario y San Sebastián','Patronal y Etnográfica. Se celebra en Septiembre. Hito comarcal en el Campo de Borja por el arraigo de su dance tradicional, sus tradicionales "auroras" cantadas de madrugada y las bodegas subterráneas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50250','fiesta','Fiestas de San Miguel Arcángel','Patronal y Turística. Se celebra en Septiembre. Festividad local en pleno Parque Natural del Moncayo, complementada con rutas senderistas y verbenas populares concurridas en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','fiesta','Fiestas en honor a San Atilano y la Salida del Cipotegato','Patronal, Etnográfica y Tradición Histórica. Se celebra en Agosto. Fiesta de Interés Turístico Nacional con un impacto masivo. El personaje del Cipotegato recibe una lluvia masiva de tomates al dar inicio a las fiestas de la ciudad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50252','fiesta','Fiestas en honor a la Virgen de Sancho Abarca','Patronal y Etnográfica. Se celebra en Abril y Septiembre. Fiesta de Interés Turístico Regional destacada por su espectacular "Dance de Tauste", el Rosario de Cristal nocturno y la torre humana o "repostre" de gran valor folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50254','fiesta','Fiestas de San Juan Bautista y la Virgen del Pilar','Patronal. Se celebra en Junio y Octubre. Celebración vecinal con fuerte arraigo en el valle del Isuela, manteniendo las tradiciones de volteo de campanas y hogueras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50255','fiesta','Fiestas de San Pedro de Verona y la Virgen de los de Tobed','Patronal y Etnográfica. Se celebra en Agosto. Su patrimonio Mudéjar Patrimonio de la Humanidad sirve de escenario para unas fiestas patronales llenas de jota aragonesa y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50256','fiesta','Fiestas de San Blas y la Virgen de la Belda','Patronal. Se celebra en Agosto. Festejos rurales íntimos enfocados en la reunión estival de los descendientes del pueblo, con cenas comunitarias y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50257','fiesta','Fiestas en honor a San Félix','Patronal. Se celebra en Agosto. Pequeña celebración tradicional basada en actividades infantiles, campeonatos de juegos de mesa y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50260','fiesta','Fiestas de San Millán de la Cogolla','Patronal e Histórica. Se celebra en Noviembre y Mayo. Su vinculación con el nacimiento de San Millán marca los actos litúrgicos, sumados a las fiestas de primavera orientadas al público familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50261','fiesta','Fiestas de San Antón y San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto. Destaca en la comarca de Tarazona por la celebración de la "Caravana de Culturas", una feria que rememora su pasado mudéjar, judío y cristiano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50262','fiesta','Fiestas de la Virgen del Castellar y San Andrés','Patronal, Etnográfica y Taurina. Se celebra en Mayo y Noviembre. Relevancia comarcal por sus tradicionales romerías a la ermita de El Castellar cruzando el río Ebro, y sus populares encierros de vaquillas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50263','fiesta','Fiestas de los Santos San Félix y San Regulo','Patronal. Se celebra en Septiembre. Tradición local en el valle del Manubles, con su tradicional hoguera de los santos, pasacalles con charangas y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50264','fiesta','Fiestas en honor a San Bartolomé','Patronal y Enológica. Se celebra en Agosto. Festejos vinculados al entorno vinícola de Cariñena, caracterizados por catas populares, verbenas de verano y actividades en el embalse de Las Torcas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50265','fiesta','Fiestas en honor a San Roque y la Feria de la Brujería y Plantas Medicinales','Patronal y Etnográfica / Ritos Paganos. Se celebra en Julio (Brujería) y Agosto (Patronales). Gran repercusión provincial y autonómica. Su Feria de la Brujería aprovecha la condición de Trasmoz como el único pueblo maldito y excomulgado de España, atrayendo a miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50266','fiesta','Fiestas de la Asunción y San Roque','Patronal. Se celebra en Agosto. Celebración tradicional del somontano del Moncayo con rondallas de jotas, concursos gastronómicos de ranchos y verbenas de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','fiesta','Fiestas de la Virgen de San Cristóbal y el Certamen de Cine de Viajes','Patronal y Cultural. Se celebra en Julio y Septiembre. La espectacularidad de su conjunto medieval eleva el empaque de sus celebraciones, atrayendo turismo comarcal a sus conciertos y actos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50268','fiesta','Fiestas de San Eutropio','Patronal y Jacobea. Se celebra en Mayo y Agosto. Festejos de arraigo local influenciados por el trazado del Camino de Santiago Aragonés, reuniendo a caminantes y vecinos en eventos lúdicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50269','fiesta','Fiestas de San Sebastián y la Virgen del Rosario','Patronal y Taurina. Se celebra en Enero y Octubre. Festejos comarcales en el eje del Jalón con encierros de vaquillas por las calles, comidas de hermandad y actos religiosos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50270','fiesta','Fiestas de la Santa Cruz y San Salvador','Patronal y Cultural. Se celebra en Mayo y Agosto. Conocido por sus festivales culturales de microteatro e historia, que complementan los eventos de verbenas tradicionales del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19296','fiesta','Fiestas en honor a San Pedro','Patronal. Se celebra en Junio. Festejos estrictamente locales y de escala familiar, vertebrados en torno a la misa patronal y una pequeña orquesta comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50272','fiesta','Fiestas de San Lamberto y Santa Ana','Patronal, Taurina y Macro-ferias. Se celebra en Junio y Julio. Gran volumen de asistencia provincial por su condición de municipio dormitorio masivo. Cuenta con ferias comerciales, masivos conciertos de rock, grandes peñas e importantes ferias taurinas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50274','fiesta','Fiestas en honor a San Blas y San Roque','Patronal. Se celebra en Agosto. Pequeñas fiestas de verano orientadas a dinamizar el pueblo con orquestas, competiciones infantiles y cenas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50273','fiesta','Fiestas de San Juan Bautista y la Virgen de la Cinta','Patronal. Se celebra en Agosto. Celebración vecinal íntima y de carácter rural, estructurada para acoger el regreso de los emigrantes de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50275','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre. Pequeña festividad vecinal con fuerte tradición piadosa, misas tradicionales aragonesas con jotas y meriendas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50276','fiesta','Fiestas de San Gregorio y San Roque','Patronal. Se celebra en Mayo y Agosto. Festejos tradicionales de las Cinco Villas que combinan juegos infantiles populares, comidas comunales y música nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50277','fiesta','Fiestas de San Juan y la Virgen del Rosario','Patronal y Gastronómica. Se celebra en Agosto. Festejos que ganan atractivo local gracias a la promoción de sus frutas locales tradicionales en las comidas y concursos del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50278','fiesta','Fiestas de San Nicolás de Bari y San Roque','Patronal e Histórico-Arqueológica. Se celebra en Agosto. Festividad local impulsada por la cercanía de las ruinas de la colonia romana de Celsa, lo que atrae un turismo cultural complementario a las verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50279','fiesta','Fiestas de San Juan Bautista y la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos pequeños de carácter estrictamente rural con procesiones, comidas de hermandad en la plaza del pueblo y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50280','fiesta','Fiestas de San Bernardo y la Feria del Monasterio de Veruela','Patronal, Enológica y Gastronómica. Se celebra en Agosto (Patronales) y Ferias estacionales. Impacto comarcal relevante. Su vinculación directa al Monasterio de Veruela y el Museo del Vino de la D.O. Campo de Borja dinamiza las fiestas con ferias gastronómicas y catas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50281','fiesta','Fiestas en honor a San Miguel Arcángel','Patronal. Se celebra en Septiembre. Celebración íntima y familiar en el Valle del Queiles orientada principalmente a los residentes tradicionales de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50283','fiesta','Fiestas de Santiago Apóstol y Santa María Magdalena','Patronal. Se celebra en Julio. Festejos puramente locales centrados en procesiones religiosas tradicionales aragonesas, torneos de guiñote y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50284','fiesta','Fiestas de San Marcos y San Ignacio de Loyola','Patronal e Histórico-Industrial. Se celebra en Agosto. Gran valor etnográfico local por su historia artesanal de molinos de pólvora y alfarería tradicional, lo que marca los pasacalles y rutas durante las fiestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50285','fiesta','Fiestas en honor a San Pedro e Isabel de Portugal','Patronal y Taurina. Se celebra en Mayo y Agosto. Gran animación local en la comarca de Zaragoza con encierros por las calles, concursos de carrozas vecinales y bailes de gala.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50286','fiesta','Fiestas de San Cristóbal y la Virgen del Rosario','Patronal. Se celebra en Agosto. Festejos pequeños estructurados en torno al reencuentro veraniego de familias vinculadas al cultivo tradicional de la vid.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50287','fiesta','Fiestas en honor a San Gervasio y San Protasio','Patronal. Se celebra en Junio y Agosto. Celebración de la Comunidad de Calatayud con misas solemnes, comidas populares de rancho aragonés y competiciones deportivas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50903','fiesta','Fiestas de la Virgen del Pueyo y San Gregorio','Patronal, Etnográfica y Taurina. Se celebra en Mayo y Septiembre. Gran afluencia de la comarca zaragozana por su tradicional romería a la ermita, sus populosas e importantes jornadas taurinas de calle y la participación masiva de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50288','fiesta','Fiestas en honor a las Santas Reliquias','Patronal, Taurina y Cultural. Se celebra en Agosto. Potente festividad gracias a su crecimiento industrial y universitario, ofreciendo macroconciertos, masivos encierros de vaquillas y un alto arraigo provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50289','fiesta','Fiestas en honor a San Gil Abad','Patronal. Se celebra en Septiembre. Pequeña verbena local de ambiente tranquilo y familiar, muy enfocada en las tradiciones de la comarca del Campo de Daroca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50290','fiesta','Fiestas en honor a San Blas y la Virgen del Pilar','Patronal y Paleontológica. Se celebra en Febrero y Agosto. Festejos tradicionales locales potenciados en los últimos años por actividades lúdicas e infantiles vinculadas a sus yacimientos de dinosaurios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50291','fiesta','Fiestas de la Virgen del Carmen y San Pedro de Alcántara','Patronal e Histórica. Se celebra en Agosto y Octubre. Recordado históricamente por la batalla carlista de la localidad; las fiestas mantienen viva la jota aragonesa y las comidas populares en las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50292','fiesta','Fiestas de San Miguel Arcángel y la Virgen del Rosario','Patronal. Se celebra en Mayo y Octubre. Celebración vecinal con hogueras tradicionales, torneos de naipes, procesiones religiosas aragonesas y música de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50293','fiesta','Fiestas en honor a la Virgen de la Sierra','Patronal y Etnográfica. Se celebra en Septiembre. Relevancia local alta por su tradicional romería al Santuario de la Virgen de la Sierra y el peso de su tradición vitivinícola en las celebraciones.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90162','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Pequeña festividad rural serrana basada en la convivencia comunitaria, juegos tradicionales e infantiles y bailes nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50296','fiesta','Fiestas en honor a San Roque y Santa Bárbara','Patronal y Taurina. Se celebra en Agosto y Diciembre. *. Animada celebración en la Ribera Baja del Ebro centrada en sus tradicionales encierros y capeas taurinas de vaquillas por el casco urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','fiesta','Fiestas del Pilar','Patronal, Etnográfica, Musical y Macrofestividad. Se celebra en Octubre. Fiesta de Interés Turístico Internacional. Destaca por la Ofrenda de Flores masiva a la Virgen, el Rosario de Cristal, y una masiva programación de conciertos y actos tradicionales que congregan a millones de visitantes mundiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50298','fiesta','Fiestas en honor a San Licer y la Romería de la Virgen del Salz','Patronal, Etnográfica y Taurina. Se celebra en Mayo (Romería) y Agosto (San Licer). Fiesta de gran empaque comarcal y provincial. Su tradicional romería a pie de gran distancia y sus potentes fiestas de agosto cuentan con festejos taurinos multitudinarios, grandes peñas y conciertos masivos). ¡Hemos completado con éxito el 100% de la provincia de Zaragoza, finalizando así toda la Comunidad Autónoma de Aragón! Dime cómo prefieres continuar el proyecto: • ¿Pasamos a la siguiente Comunidad Autónoma en orden alfabético (Iniciar Principado de Asturias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90682','fiesta','Fiestas de Nuestra Señora de Avellaneda','Patronal y Etnográfica. Se celebra en Septiembre. Festejos tradicionales del occidente asturiano caracterizados por la descarga de voladores, folclore vaqueiro y comidas vecinales de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90637','fiesta','Fiesta de los Humanitarios de San Martín de Moreda','Etnográfica y Gastronómica. Se celebra en Noviembre. Fiesta de Interés Turístico Nacional. Destaca por su masivo desfile de carrozas, el uso generalizado del traje tradicional asturiano y la degustación gastronómica del panchón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05001','fiesta','Fiesta de San Roque en Sames','Patronal. Se celebra en Agosto. Celebración de arraigo estrictamente local en el entorno de los Picos de Europa, centrada en verbenas rurales y subasta del ramu.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05002','fiesta','Fiesta del Bollo y Festival Intercéltico de Avilés','Etnográfica, Gastronómica y Cultural. Se celebra en Abril (El Bollo) y Julio (Intercéltico). Fiestas de Interés Turístico Nacional. La Fiesta del Bollo destaca por su comida en la calle multitudinaria por el casco histórico, y el festival atrae masivamente a grupos de todas las naciones celtas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05003','fiesta','Feria de San Antonio y Fiestas del Rosario','Feria Comercial / Ganadera y Patronal. Se celebra en Junio y Octubre. Gran arraigo comarcal debido al peso de sus ferias ganaderas tradicionales y las muestras de artesanía local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90638','fiesta','Fiesta de la Maina y Fiesta de San Juan','Etnográfica y Patronal. Se celebra en Junio y Julio. Destaca por la defensa del folclore local y la fuerte tradición de las hogueras de San Juan en la comarca de la sidra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90639','fiesta','Fiestas de San Diego y Feria de la Miel','Patronal y Gastronómica. Se celebra en Agosto y Noviembre (Miel). Reconocimiento provincial por su Feria de la Miel, hito agroalimentario del occidente asturiano, sumado a sus procesiones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','fiesta','Certamen del Queso de Cabrales','Gastronómica y Etnográfica. Se celebra en Agosto. Fiesta de Interés Turístico Regional. Macro-evento gastronómico masivo que congrega a miles de personas para la subasta del famoso queso y exhibiciones de deportes tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05004','fiesta','Festival del Arroz con Leche','Gastronómica. Se celebra en Mayo. Fiesta de Interés Turístico Regional. Evento multitudinario donde se reparten miles de raciones de este postre típico, acompañado de un gran mercado artesanal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90640','fiesta','Festival de la Fresa de Candamo','Gastronómica y Feria Agrícola. Se celebra en Junio. Potente fiesta comarcal que premia los mejores cultivos de fresa de la huerta del Nalón, atrayendo a numeroso público provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','fiesta','Fiestas del Carmen y la Magdalena (La Descarga)','Patronal y Etnográfica / Pirotécnica. Se celebra en Julio. Fiesta de Interés Turístico Nacional. Su hito central es "La Descarga", una impresionante y masiva suelta de miles de voladores en apenas unos minutos que estremece todo el valle.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90010','fiesta','Fiestas de Nuestra Señora de la Consolación','Patronal. Se celebra en Septiembre. Pequeños festejos tradicionales de ambiente costero y veraniego, orientados a la reunión familiar vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90011','fiesta','Fiestas del Santísimo Cristo de Candás y Festival de la Sardina','Patronal y Gastronómica. Se celebra en Agosto y Septiembre. Fiesta de Interés Turístico Regional por su Festival de la Sardina en Candás, atrayendo masivamente a visitantes para degustar el pescado a la plancha.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90641','fiesta','Certamen del Queso Casín','Gastronómica y Etnográfica. Se celebra en Agosto. Celebración de relevancia comarcal y provincial dedicada a la puesta en valor de uno de los quesos más antiguos de España en pleno Parque Natural de Redes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90012','fiesta','Fiestas de San Isidro Labrador en Piedrasblancas y Festival de Surf de Salinas','Patronal y Deportivo-Cultural. Se celebra en Mayo y Julio (Surf). El festival de surf e integración cultural en la playa de Salinas atrae a un público masivo e internacional, elevando el impacto lúdico del concejo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90013','fiesta','Fiesta del Corpus Christi de Castropol','Etnográfica y Religiosa. Se celebra en Junio. Fiesta de Interés Turístico Regional. Destaca por la confección de espectaculares alfombras florales de gran valor artístico que cubren las calles históricas de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90014','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Septiembre. Festejos locales al amparo de su riqueza castreña, con romerías tradicionales asturianas, música de gaita y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90015','fiesta','Fiestas de Loreto y Feria del Antroxu (Carnaval)','Patronal y Etnográfica. Se celebra en Febrero y Agosto. Festejos de fuerte arraigo estival en la costa asturiana, atrayendo a turistas provinciales gracias a sus desfiles y procesiones marítimas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90642','fiesta','Fiestas de las Hogueras de San Juan en Trasona','Etnográfica y Ritos Paganos. Se celebra en Junio. Fiesta comarcal muy potente celebrada en el entorno del pantano de Trasona, congregando a miles de jóvenes de la zona central asturiana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05008','fiesta','Fiestas de San Pedro y L''Amuravela','Patronal y Etnográfica / Tradición Oral. Se celebra en Junio. Fiesta de Interés Turístico Regional. Destaca de forma absoluta por el sermón de L''Amuravela, recitado en verso en el dialecto pixueto local desde un barco en el puerto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33022','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración de alta montaña en el occidente asturiano, de ambiente vecinal y centrada en bailes tradicionales y comidas comunales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33023','fiesta','Fiestas de Nuestra Señora de la Caridad','Patronal. Se celebra en Septiembre. Romería tradicional costera en el occidente asturiano con una importante concurrencia de concejos limítrofes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33024','fiesta','Semana Grande (Fiestas de Begoña) y Fiesta de la Sidra Natural','Patronal, Enológica y Macro-festividad. Se celebra en Agosto. Fiestas de Interés Turístico Nacional por su Fiesta de la Sidra. Reúne a decenas de miles de personas batiendo récords mundiales de escanciado simultáneo en la playa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33025','fiesta','Fiestas del Santísimo Cristo del Socorro en Luanco','Patronal y Etnográfica. Se celebra en Febrero y Agosto. Destaca su arraigada procesión marítima y las actividades lúdico-deportivas veraniegas ligadas a la villa marinera de Luanco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33026','fiesta','Fiestas de Santa Ana y el Mercado de Flor','Patronal y Ferias Comerciales Históricas. Se celebra en Abril (Flor) y Julio (Santa Ana). *. Hito comercial de gran tradición en Asturias por sus mercados tradicionales de hortalizas, pan de escanda y quesos, con gran poder de convocatoria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33027','fiesta','Fiestas de San Salvador','Patronal y Jacobea. Se celebra en Agosto. Festejos en el Camino Primitivo que aúnan el folclore del occidente con la acogida a peregrinos y verbenas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','fiesta','Fiesta del Solsticio de Verano y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejos rurales marcados por el aislamiento geográfico que preserva de forma pura el folclore local y la arquitectura tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33029','fiesta','Fiestas de Nuestra Señora de Pastur','Patronal. Se celebra en Septiembre. Pequeña romería montañesa asturiana con una misa tradicional y una posterior merienda campestre familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33030','fiesta','Certamen del Queso de La Peral','Gastronómica. Se celebra en Agosto. Festejos locales dinamizados por la feria gastronómica en honor al queso azul de la Peral, emblema del concejo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33031','fiesta','Fiestas de Santiago Apóstol en Sama y San Pedro en La Felguera','Patronal y Tradición Industrial. Se celebra en Junio y Julio. Grandes festejos urbanos en las cuencas mineras con desfiles de carrozas, desfile de gigantes y cabezudos y masivos conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33033','fiesta','Fiesta de Nuestra Señora de la Soterraña y Fiesta de los Corderos (Prau Llagüezos)','Patronal y Gastronómica / Romería. Se celebra en Abril (Soterraña) y Julio (Corderos). La Fiesta del Cordero en el Prau Llagüezos es de Interés Turístico Nacional, celebrando la hermandad entre concejos asturianos comiendo cordero a la estaca en la montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33035','fiesta','Exconxuraos de Llanera','Recreación Histórica y Etnográfica. Se celebra en Julio. Fiesta de Interés Turístico Regional. Conmemora un alzamiento medieval con cenas feudales, torneos de caballeros y un gran mercado medieval muy concurrido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33036','fiesta','Fiestas de San Roque, la Virgen de la Guía y Santa María Magdalena','Patronal, Etnográfica y Rivalidad Tradicional. Se celebra en Julio y Agosto. Fiesta de Interés Turístico Nacional. Caracterizada por la sana y espectacular rivalidad histórica entre los tres bandos del pueblo, con desfiles de trajes llaniscos únicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33037','fiesta','Fiestas de San Juan Bautista y la de los Mártires de Valdecuna','Patronal, Ritos Paganos y Romería Etnográfica. Se celebra en Junio (San Juan) y Septiembre (Mártires). La romería de los Mártires de Valdecuna es Fiesta de Interés Turístico Regional, famosa por sus "taramundis", la tonada asturiana y el consumo masivo de sidra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33038','fiesta','Certamen del Queso de Afuega''l Pitu','Gastronómica. Se celebra en Enero. Relevancia provincial por la promoción y cata de una de las variedades de queso más características y consumidas del Principado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33039','fiesta','Fiestas de San Antonio','Patronal. Se celebra en Junio. Verbena veraniega de carácter familiar con verbenas al aire libre en la plaza del ayuntamiento.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33040','fiesta','Festival de la Sidra de Nava','Enológica y Etnográfica. Se celebra en Julio. Fiesta de Interés Turístico Nacional. La gran capital de la sidra organiza el prestigioso concurso de escanciadores y ofrece miles de litros gratis a los asistentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33041','fiesta','Fiestas de Nuestra Señora de la Barca y San Roque','Patronal y Descenso Acuático. Se celebra en Agosto. Gran calado provincial por la coincidencia de las fiestas patronales marítimas con el famoso Descenso a Nado de la Ría del Navia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33042','fiesta','Fiestas del Ecce Homo y Fiesta del Picadillo y del Sabadiego','Patronal y Gastronómica. Se celebra en Abril (Sabadiego) y Septiembre (Ecce Homo). Reconocimiento gastronómico provincial muy alto por sus industrias cárnicas tradicionales, entronizadas en la famosa Orden del Sabadiego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33043','fiesta','Certamen del Queso Gamonéu en Benia de Onís','Gastronómica y Ganadera. Se celebra en Octubre. Hito agroalimentario provincial centrado en la venta y puesta en valor de la variedad de queso Gamonéu de los Picos de Europa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33044','fiesta','Fiestas de San Mateo y el Día de América en Asturias','Patronal, Etnográfica y Desfile Internacional. Se celebra en Septiembre. El Día de América en Asturias es Fiesta de Interés Turístico Nacional. Un multitudinario desfile rinde homenaje a la emigración asturiana a América con carrozas y grupos folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33045','fiesta','Fiesta del Descenso Internacional del Sella en Arriondas','Deportiva, Etnográfica y Macro-folclórica. Se celebra en Agosto. Fiesta de Interés Turístico Internacional, compartida con Ribadesella. Conocida popularmente como "Les Piragües", atrae a cientos de kilómetros de visitantes de todo el mundo en una acampada masiva y desfile de asturianía previo a la salida.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33046','fiesta','Certamen del Queso de Peñamellera','Gastronómica. Se celebra en Julio. Festejos locales orientados al mantenimiento de la producción quesera artesanal en el entorno del río Cares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33047','fiesta','Fiestas de San Roque en Panes y Fiesta de la Travesía Histórica del Cares','Patronal y Turística. Se celebra en Agosto. Celebración fronteriza con Cantabria que aúna las verbenas populares con el turismo activo fluvial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33048','fiesta','Fiesta de San Roque','Patronal. Se celebra en Agosto. Pequeña celebración rural del occidente asturiano caracterizada por su carácter vecinal íntimo e histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33049','fiesta','Festival de la Avellana en Infiesto','Gastronómica y Feria Tradicional. Se celebra en Octubre. Fiesta de Interés Turístico Regional. Concentra una masiva afluencia para comprar avellanas cosechadas en el concejo, junto a concursos y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33050','fiesta','Fiesta del Aguinaldo','Etnográfica y Rito Tradicional Invierno. Se celebra en Enero. Gran valor folclórico local por la figura de "El Guirria", un personaje ancestral enmascarado que persigue a las mujeres del pueblo a caballo pidiendo el aguinaldo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33051','fiesta','Fiestas del Santísimo Cristo de la Misericordia y Descenso Folklórico del Nalón (Sección Pravia)','Patronal y Piragüismo Tradicional. Se celebra en Septiembre. Relevancia comarcal alta debido a los actos lúdicos del valle bajo del Nalón, las charangas históricas y sus tradicionales verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33052','fiesta','Fiestas de la Virgen de los Remedios y Feria Gastronómica de los Nabos','Patronal y Gastronómica. Se celebra en Septiembre y Septiembre/Octubre. Festejos en la Senda del Oso potenciados por menús tradicionales gastronómicos de pote de nabos arcaico asturiano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33053','fiesta','Fiesta del Alba y Fiestas de San José en Bárzana','Gastronómica, Etnográfica y Patronal. Se celebra en Julio (Alba) y Marzo (San José). Destaca la Fiesta del Alba en la ermita de Salcedo, declarada de interés comarcal, famosa por sus carreras de caballos montanos, folclore tradicional y cata del cordero a la estaca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33054','fiesta','Certamen de la Castaña Valduna y Fiestas de Santa Eulalia','Gastronómica y Patronal. Se celebra en Noviembre (Castaña) y Diciembre. Hito gastronómico comarcal que protege y promociona la "castaña valduna", una variedad autóctona de gran calidad, atrayendo a centenares de productores y visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33055','fiesta','Feria Indianos de Colombres y Fiestas de la Virgen de la Sacristía','Recreación Histórica, Cultural y Patronal. Se celebra en Julio (Indianos) y Septiembre (Patronal). Su Feria Indiano-Americana tiene un gran empaque regional, transformando la villa con indumentarias de época, mercados de ultramar y música caribeña para honrar el legado de la emigración.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33056','fiesta','Fiesta de las Piraguas (Descenso Internacional del Sella) y Fiestas de Guía','Deportiva, Etnográfica y Masiva. Se celebra en Agosto. Fiesta de Interés Turístico Internacional. El Descenso del Sella es uno de los eventos deportivos y folclóricos más multitudinarios del planeta, vertebrado por el "tren fluvial" y una masiva acampada global [1].','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33057','fiesta','Fiestas de San Juan en Soto de Rey y Fiesta de Santiago en Bueño','Patronal y Etnográfica. Se celebra en Junio y Julio. Festejos de arraigo local y de fuerte componente etnográfico, especialmente potenciados por el marco de hórreos tradicionales del pueblo de Bueño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33058','fiesta','Fiestas de Nuestra Señora de los Remedios y Fiesta de la Nieve en el Angliru','Patronal y Deportiva-Turística. Se celebra en Septiembre. Festejos populares que reciben gran afluencia local y deportiva por la mítica vinculación del municipio al coloso ciclista del Angliru y sus paisajes mineros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33061','fiesta','Fiesta de los Quintos y Fiestas de San Martín','Etnográfica y Patronal. Se celebra en Agosto y Noviembre. Celebración tradicional del occidente asturiano orientada al reencuentro de familias y a mantener vivas las ferias de artesanía en hierro de los Oscos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33060','fiesta','Fiesta de les Cebolles Rellenes (El Entrego) y Fiesta de los Nabos (Sotrondio)','Gastronómica. Se celebra en Noviembre. Fiestas Gastronómicas de Interés Turístico Regional. Ambas citas culinarias paralizan la cuenca del Nalón atrayendo a comensales de toda Asturias para degustar estos platos identitarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33063','fiesta','Fiestas de San Juan y Feria de la Artesanía','Patronal y Feria Comercial. Se celebra en Junio y Agosto. Celebraciones tradicionales en la frontera con Galicia, centradas en la orilla del río Eo, con comidas populares y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33062','fiesta','Fiestas de la Jira de Ferreira y Fiesta de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Romería tradicional de hondo arraigo rural astur-galaico que congrega a los vecinos en torno a un área recreativa natural con música tradicional de gaita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33064','fiesta','Fiestas de San Romano y del Suro','Patronal y Etnográfica. Se celebra en Agosto. Verbena tradicional de concejo pequeño, vertebrada por la Senda del Oso y orientada a la convivencia familiar y el turismo rural estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33065','fiesta','Fiestas de Santiago y Fiesta de la Sidra de Sariego','Patronal y Enológica (Sidra). Se celebra en Julio. Festejos integrados en la Comarca de la Sidra, caracterizados por el reparto de la tradicional espicha asturiana, el escanciado libre y tonada folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33066','fiesta','Fiesta de los Huevos Pintos (Pola de Siero) y las Fiestas del Carmín','Etnográfica, Tradicional y Romería Masiva. Se celebra en Abril (Huevos Pintos) y Julio (Carmín). Los Huevos Pintos son Fiesta de Interés Turístico Nacional por su arte de decoración artesanal. El Carmín es la romería más multitudinaria y descontrolada de Asturias, congregando a decenas de miles de jóvenes con camisas de cuadros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33067','fiesta','Feria ganadera de la Trashumancia y Fiestas de San Ginés en Rioseco','Feria de Ganado y Etnográfica. Se celebra en Agosto y Octubre. Ubicado en el Parque Natural de Redes; sus fiestas ensalzan el pastoreo de montaña, las exposiciones de vaca asturiana de los valles y los mercados artesanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33068','fiesta','Fiesta del Rosario en Pola de Somiedo y Certamen Ganadero de la Raza Asturiana de los Valles','Etnográfica y Feria Ganadera de Montaña. Se celebra en Septiembre. Relevancia provincial por ser el escaparate principal de la ganadería vacuna de montaña, complementado con cantos de vaqueiros y verbenas rurales de gran tipismo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33069','fiesta','San Pedro en San Juan de la Arena y Festival de la Angula','Patronal, Marinera y Gastronómica. Se celebra en Junio (San Pedro) y Marzo (Angula). Su Festival de la Angula goza de alto prestigio provincial. Las fiestas de San Pedro destacan por la emocionante procesión marinera y la danza prima a la orilla de la ría del Nalón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33070','fiesta','Fiestas de Nuestra Señora del Carmen y el Campeonato de Surf de Tapia (Memorial Peter Gulley)','Patronal, Marinera y Deportiva-Internacional. Se celebra en Julio (Carmen) y Semana Santa (Surf). Gran relevancia regional. Reúne la sobria tradición marinera del Carmen con una de las citas de surf más antiguas e internacionales del norte de España, masificando la villa costera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33071','fiesta','Fiesta de San Martín y Feria de la Artesanía y la Cuchillería','Patronal y Hito Etnográfico-Artesanal. Se celebra en Mayo y Noviembre. El arraigo de sus ferias artesanales de navajas y forja tradicional dota a sus fiestas de un imán turístico regional en el núcleo pionero del turismo rural español.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33072','fiesta','Fiestas de Santiago en San Martín y Ferias de Otoño (Muestra ganadera y gastronómica)','Patronal, Ganadera y Gastronómica. Se celebra en Julio y Noviembre. Destacan sus jornadas gastronómicas dedicadas al pote tevergano y las ferias ganaderas tradicionales que congregan a los pastores de los puertos de Marabio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33073','fiesta','Fiestas de San Roque y la Feria de Muestras de Tineo','Patronal, Romería y Macro-feria Comercial. Se celebra en Mayo (Feria) y Agosto (San Roque). Fiesta de Interés Turístico Regional por la romería de San Roque en el campo del mismo nombre. Su macro-feria de muestras industrial y ganadera es una de las más potentes de toda Asturias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33034','fiesta','Fiestas de San Timoteo (Luarca) y Fiesta del Rosario','Romería Tradicional, Patronal y Masiva. Se celebra en Agosto. Fiesta de Interés Turístico Nacional. La romería de San Timoteo en Luarca es multitudinaria; los romeros visten chambras de cuadros, portan bastones y desfilan al son de charangas y gaitas hasta el prado del santo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33074','fiesta','Fiestas de Nuestra Señora de la Asunción y la Feria de Muestras de Vegadeo','Patronal y Macro-feria Comercial. Se celebra en Junio (Feria) y Agosto (Patronales). *. La Feria de Muestras de Vegadeo es la segunda más antigua de Asturias y posee un descomunal impacto socioeconómico atrayendo expositores del norte de España y Portugal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33075','fiesta','Fiesta de Santa Ana y el Viacrucis Viviente','Patronal y Etnográfica / Religiosa. Se celebra en Julio (Santa Ana) y Semana Santa (Viacrucis). Su Viacrucis Viviente destaca a nivel comarcal por la implicación vecinal y la belleza del entorno del Monasterio de Santa María.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33076','fiesta','Fiestas del Portal y el Festival de la Manzana','Patronal, Enológica (Sidra) y Agrícola. Se celebra en Septiembre (Portal) y Octubre (Manzana - bienal). Fiesta de Interés Turístico Regional. Capital de la manzana asturiana, sus fiestas combinan el fervor de la Danza del Portal con la bendición del primer mosto de manzana y concursos de escanciadores). ¡Hemos completado con éxito el 100% del Principado de Asturias, finalizando todos los concejos de la A a la Z! Dime cómo deseas continuar el proyecto: • ¿Iniciamos la siguiente Comunidad Autónoma en orden alfabético (Iniciar Canarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90626','fiesta','Fiestas de Nuestra Señora de las Nieves y la Fiesta de la Rama','Patronal, Etnográfica y Rito Tradicional. Se celebra en Agosto. Fiesta de Interés Turístico Nacional. La Bajada de la Rama es un rito aborigen masivo donde miles de personas bailan al ritmo de la banda portando ramas aromáticas hasta el mar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90627','fiesta','Carnaval de Agüimes y Fiestas de San Sebastián','Etnográfica, Masiva y Patronal. Se celebra en Febrero (Carnaval) y Septiembre (San Sebastián). Famoso por albergar uno de los carnavales históricos y con mayor tradición de murga y crítica de Gran Canaria, con un fuerte arraigo e impacto regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25001','fiesta','Fiestas de Nuestra Señora de la Antigua y Feria de Artesanía de Antigua','Patronal y Feria Insular. Se celebra en Mayo (Feria) y Septiembre (Patronal). Su feria de artesanía es un referente en Fuerteventura, concentrando a creadores de todo el archipiélago y dinamizando el centro de la isla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90628','fiesta','Fiestas de San Ginés Obispo','Patronal, Marinera y Musical. Se celebra en Agosto. Fiestas capitalinas de Lanzarote con gran empaque insular, caracterizadas por regatas de jolateros, conciertos masivos en la playa de El Reducto y parrandas canarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25002','fiesta','Fiestas de la Virgen de la Cuevita','Patronal y Etnográfica. Se celebra en Agosto. Festividad singular en las cumbres de Gran Canaria, con procesiones nocturnas de fervor popular hacia una ermita excavada en la roca viva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25003','fiesta','Fiestas Patronales de San Juan Bautista','Patronal, Etnográfica y Alfombras de Flores. Se celebra en Junio. Destaca la confección de espectaculares alfombras de serrín y flores en sus calles señoriales, atrayendo a miles de visitantes de toda la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25004','fiesta','Fiestas en honor a la Virgen de la Peña','Patronal y Romería Insular. Se celebra en Septiembre. Fiesta de la patrona de Fuerteventura. Es el evento religioso y folclórico más importante de la isla, con peregrinos que cruzan los senderos desde todos los municipios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90643','fiesta','Fiestas Patronales de San Roque','Patronal, Agrícola y Etnográfica. Se celebra en Agosto. Relevancia comarcal alta por su Traída del Palo y la Romería-Ofrenda, donde los vecinos portan los mejores frutos de la tierra montañesa en carretas decoradas hacia la iglesia de San Roque.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25005','fiesta','Fiestas Mayores de Santiago Apóstol (Año Santo Jacobeo de Gáldar)','Patronal, Histórica, Religiosa y Jacobea. Se celebra en Julio. Fiesta de Interés Turístico Regional de gran empaque arqueológico e histórico. Gáldar goza de privilegios papales singulares al ser la sede del Jacobeo de Canarias, atrayendo a peregrinos de todo el archipiélago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90629','fiesta','Fiestas Patronales de San Juan Bautista','Patronal y Danza del Fuego. Se celebra en Junio. Hito tradicional de Lanzarote caracterizado por la Noche de San Juan, las danzas rituales en torno a la hoguera gigante y la quema de "Facundo" bajo el palmeral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35011','fiesta','Fiestas de Nuestra Señora de la Candelaria y Festival Internacional de Folklore','Patronal y Encuentro Cultural Global. Se celebra en Febrero (Patronal) y Julio (Folklore). Gran renombre provincial y autonómico por su festival folclórico que congrega a grupos de los cinco continentes, complementando su histórica herencia de calados artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35012','fiesta','Fiestas de San Antonio de Padua y Fiestas del Carmen en Arguineguín','Patronal, Marinera y Turística. Se celebra en Junio (San Antonio) y Julio (Carmen). La procesión marítima de la Virgen del Carmen entre los puertos de Arguineguín y Mogán atrae a millares de visitantes provinciales y turistas alojados en el sur de la isla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35013','fiesta','Fiestas de San Antonio de Padua','Patronal, Etnográfica y Romería de los Quesos. Se celebra en Junio. Destaca por su arraigada Romería-Ofrenda dedicada a ensalzar los productos queseros de las medianías de Gran Canaria, con una enorme implicación folclórica de los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35014','fiesta','Fiestas de Nuestra Señora de la Candelaria','Patronal y Mercado Artesanal Histórico. Se celebra en Febrero. Gran calado en Fuerteventura, concentrando las procesiones tradicionales y la música canaria en torno a la histórica Casa de los Coroneles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35015','fiesta','Fiestas de Nuestra Señora de Regla','Patronal e Histórico-Religiosa. Se celebra en Junio. Festejos en torno al histórico pórtico de azteca de su templo parroquial, atrayendo a visitantes del centro y sur de Fuerteventura con música de parrandas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35016','fiesta','Carnaval de Las Palmas de Gran Canaria y Fiestas de San Juan (Fundación de la ciudad)','Carnaval Masivo, Histórica y Urbana. Se celebra en Febrero / Marzo (Carnaval) y Junio (San Juan). Fiesta de Interés Turístico Internacional el Carnaval, mundialmente célebre por su Gala Drag Queen, comparsas masivas y desfiles urbanos multitudinarios de enorme impacto global.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35017','fiesta','Fiestas Patronales de Nuestra Señora del Rosario','Patronal, Urbana y Regatas. Se celebra en Septiembre y Octubre. Como capital insular, centraliza eventos modernos como conciertos de pop nacional, regatas de achipencos —artilugios flotantes divertidos— y ferias comerciales urbanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35018','fiesta','Fiestas Patronales de San Bartolomé','Patronal y Folclórica. Se celebra en Agosto. Celebración agraria en el centro geográfico insular con pasacalles teatrales, festivales folclóricos de malagueñas e importantes torneos de lucha canaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35019','fiesta','Fiestas de Santiago Apóstol en Tunte y Maspalomas Pride','Patronal (Tunte) / Macro-evento Internacional (Maspalomas). Se celebra en Julio (Santiago) y Mayo (Pride). Reconocimiento global masivo por el Pride de Maspalomas que atrae cientos de miles de turistas de todo el planeta, combinando el tipismo histórico de Santiago en el interior serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35021','fiesta','Fiestas de San Antonio de Padua y Florabrígida','Patronal y Exposición Agrícola-Floricultura. Se celebra en Junio. Florabrígida es una arraigada muestra de flores, plantas y artesanía con gran afluencia de la zona metropolitana de la isla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35022','fiesta','Fiestas de Santa Lucía y Romería de Los Labradores','Patronal y Etnográfica. Se celebra en Diciembre. Fiesta de Interés Turístico Regional. Destaca el hermanamiento con delegaciones de Suecia en honor a Lucía y la Romería de los Labradores, donde se reparte el "mejunje", bebida autóctona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35023','fiesta','Fiestas de la Virgen de Guía y la Fiesta de Las Marías','Patronal y Voto Etnográfico de Promesa. Se celebra en Agosto (Patronal) y Septiembre (Las Marías). La Fiesta de Las Marías conmemora una histórica promesa de los campesinos locales, portando ramas desde las cumbres al compás de caracolas marinas o guácaras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35024','fiesta','Fiestas de Nuestra Señora de las Nieves y los Diabletes de Teguise','Patronal y Etnográfica / Ritos Ancestrales. Se celebra en Agosto (Patronal) y Carnaval/ Corpus (Diabletes). *. Hito folclórico insular. Sus "Diabletes", disfrazados con máscaras de buey y pieles de cabra, asustan a los niños por la antigua capital de Lanzarote recreando ritos aborígenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35025','fiesta','Fiestas del Almendro en Flor','Agrícola, Gastronómica y Etnográfica. Se celebra en Febrero. Fiesta de Interés Turístico Regional. Celebra la floración de los almendros en la cumbre con ferias de artesanía, parrandas y degustaciones de dulces tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35026','fiesta','Fiestas de San Juan Bautista y Fiestas del Santísimo Cristo de Telde','Patronal y Fervor Popular. Se celebra en Junio y Septiembre. Festejos urbanos masivos de la segunda ciudad más poblada de la isla, con ferias de ganado de gran peso y espectáculos pirotécnicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35027','fiesta','Fiestas de Nuestra Señora del Pino','Patronal, Romería Masiva e Insular. Se celebra en Septiembre. Fiesta de la Patrona de Gran Canaria. Es la romería-ofrenda institucional por excelencia, adonde acuden peregrinos de todos los municipios a pie durante la madrugada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35028','fiesta','Fiestas en honor a Nuestra Señora de la Candelaria y San Blas','Patronal y Romería local. Se celebra en Febrero. Festejos de invierno que marcan la tradición campesina previa a la expansión turística de Puerto del Carmen, con asaderos populares de pescado y música de parrandas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35029','fiesta','Fiestas de la Virgen de los Dolores (Patrona de Lanzarote)','Patronal, Insular y Romería Masiva. Se celebra en Septiembre. Fiesta de Interés Turístico Regional. Es la romería principal y multitudinaria de Lanzarote; peregrinos de todos los rincones de la isla caminan con indumentaria canaria tradicional hasta Mancha Blanca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35030','fiesta','Fiestas Juradas de San Miguel Arcángel (Batalla de Tamasite)','Recreación Histórica y Patronal. Se celebra en Octubre. Fiesta de Interés Turístico Regional. Recrea la histórica victoria armada de los campesinos majoreros armados con palos contra los corsarios ingleses desembarcados en 1740.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35031','fiesta','Fiestas del Almendro en Flor y la Suelta del Perro de San Miguel','Etnográfica (Almendro) / Rito Pagano (San Miguel). Se celebra en Enero (Almendro) y Septiembre (San Miguel). La noche de San Miguel se recrea la "Suelta del Perro", donde el demonio encadenado se escapa provocando un espectacular desfile de aquelarres y fuego de gran tirón provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35032','fiesta','Fiestas de la Encarnación y la Fiesta de la Manzana','Agrícola y Patronal. Se celebra en Octubre. Celebración centrada en la cosecha de la manzana reineta del municipio, con ferias de repostería, sidra local y una romería tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35033','fiesta','Fiestas Patronales del Apóstol San Mateo y Feria del Agricultor','Patronal, Agrícola y Etnográfica. Se celebra en Septiembre. Gran relevancia provincial y de cumbres, destacando su tradicional bajada del vino, competiciones de arrastre de ganado vacuno y concurridos mercados de hortalizas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','fiesta','Fiestas de Nuestra Señora de los Remedios','Patronal. Se celebra en Septiembre. Festejos tradicionales al sur de la isla, al pie del Parque Nacional de Timanfaya, uniendo la devoción de carretas tradicionales y verbenas populares al aire libre). ¡Hemos completado con éxito el 100% de la Comunidad Autónoma de Canarias, finalizando todos sus municipios de la A a la Z! Dime cómo prefieres proceder con el macro-proyecto: • ¿Iniciamos la siguiente Comunidad Autónoma en orden alfabético (Iniciar Cantabria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38001','fiesta','Representación de la Pasión de Adeje y Fiestas de la Virgen de la Encarnación','Teatro Religioso / Etnográfica y Patronal. Se celebra en Semana Santa (Pasión) y Octubre (Patronal). La Pasión de Adeje es un monumental teatro callejero retransmitido por televisión con repercusión en todo el archipiélago, congregando a miles de actores locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90630','fiesta','Fiestas de San Marcos Evangelista y las Hogueras de San Marcos','Etnográfica y Rito Tradicional. Se celebra en Abril. Famoso rito donde los jóvenes saltan sobre monumentales hogueras de troncos de sabina en las estrechas calles empedradas de este pueblo gomero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90775','fiesta','Fiestas de la Virgen del Paso','Patronal y Romería de Montaña. Se celebra en Septiembre. Tradicional bajada a pie de la virgen desde su ermita en los acantilados de la meseta sureña de La Gomera acompañada por chácaras y tambores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90644','fiesta','Fiestas de San Agustín y Romería de San Agustín','Patronal y Tradición Musical. Se celebra en Agosto. Conocido como el "pueblo de la música", sus romerías tradicionales destacan por la excelsa calidad de sus bandas y agrupaciones folclóricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90645','fiesta','Fiestas de Nuestra Señora de la Abona','Patronal. Se celebra en Septiembre. Celebración tradicional del sur de Tenerife con bajadas de la virgen a la costa, torneos de arrastre de ganado y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90776','fiesta','Fiestas del Santísimo Cristo de la Salud y Carnaval de Los Cristianos','Carnaval Turístico y Patronal. Se celebra en Marzo (Carnaval) y Octubre (Patronal). El Carnaval de Los Cristianos es el epicentro de la fiesta veraniega e internacional en el sur de Tenerife, atrayendo una altísima afluencia masiva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90631','fiesta','Fiestas de la Virgen del Rosario y la Batalla de Lepanto','Recreación Histórica y Patronal. Se celebra en Agosto (Trienal). Recreación naval de carácter histórico y popular de la Batalla de Lepanto, escenificada con barcos de madera y castillo de lona en pleno casco de La Palma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90632','fiesta','Fiesta de las Cruces y Fiestas de San Pedro Apóstol','Etnográfica y Patronal. Se celebra en Mayo (Cruces) y Junio. Destaca el enramado y joyado artesanal de decenas de cruces en los antiguos caminos de la localidad, compitiendo en belleza y espectacularidad floral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90777','fiesta','Fiestas de Santiago Apóstol y Fiesta de las Madres','Patronal y Romería. Se celebra en Julio. Festejos tradicionales de La Palma que combinan recitales de habaneras, festivales de folclore y orquestas populares de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38003','fiesta','Fiestas de Nuestra Señora de los Remedios y Fiestas de San Antonio Abad en Teno Alto','Patronal y Etnográfica Serrana. Se celebra en Octubre y Septiembre (Teno). El aislamiento histórico de Teno Alto dota a sus fiestas de un valor etnográfico único, conservando el ancestral baile de las tajarastes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90778','fiesta','Fiestas de la Virgen de la Candelaria (Patrona de Canarias)','Patronal, Peregrinación y Recreación Aborigen. Se celebra en Agosto y Febrero. Fiesta de Interés Turístico Nacional. Reúne a cientos de miles de peregrinos de todo el archipiélago y destaca la emocionante Guanche de la Virgen.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90633','fiesta','Fiestas Patronales en honor a la Virgen del Rosario','Patronal. Se celebra en Agosto. Celebración de carácter puramente municipal y tradicional, vertebrada por la reunión de familias del sur de la isla, verbenas populares y las danzas de cintas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16085','fiesta','Fiestas de Nuestra Señora de los Reyes (en años de Bajada) y Fiesta de San Lorenzo Tarajal','Patronal y Etnográfica. Se celebra en Septiembre. Hito insular relevante; se convierte en punto neurálgico de la isla de El Hierro durante las celebraciones tradicionales de pastores, tocadores de pito y tambor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90634','fiesta','Fiesta de la Vendimia','Gastronómica, Enológica y Tradicional. Se celebra en Agosto. Festejo de gran relevancia insular que homenajea la cultura agraria de los viñedos cultivados sobre ceniza volcánica, destacando la tradicional Danza de los Caballitos de Fuego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38005','fiesta','Fiestas de San Roque (Romería de San Roque)','Patronal, Marinera y Etnográfica. Se celebra en Agosto. Fiesta de Interés Turístico Nacional. Su romería marítimo-terrestre posee una belleza singular, donde las carretas recorren el casco histórico de piedra y las barcas engalanadas escoltan al santo por el litoral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38016','fiesta','Fiestas de la Virgen de la Luz y de San Antonio del Monte','Patronal y Feria de Ganado Tradicional. Se celebra en Junio. San Antonio del Monte acoge la mayor feria ganadera de La Palma, un hito para el sector primario insular con concursos de arrastre y folclore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38017','fiesta','Fiestas Patronales en honor a San Antonio de Padua','Patronal y Etnográfica. Se celebra en Junio. Una de las romerías más antiguas y populosas del sur de Tenerife, que congrega a numerosas agrupaciones folclóricas de toda la isla y carrozas artesanales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38019','fiesta','Fiestas lustrales de la Virgen de la Luz y Pascua Florida','Patronal y Arte Floral-Religioso. Se celebra en Septiembre (Patronal) y Semana Santa (Pascua). La Pascua Florida llena el casco urbano de esculturas e intervenciones florales de gran formato únicas en el archipiélago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38020','fiesta','Fiestas de San Pedro Apóstol y la Bajada de la Virgen del Socorro','Patronal, Etnográfica y Recreación Histórica. Se celebra en Junio (San Pedro) y Septiembre (El Socorro). Fiesta de Interés Turístico Regional. La Bajada de la Virgen del Socorro recrea la aparición mariana a los guanches en las playas de Chimisay, congregando a decenas de miles de personas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38021','fiesta','Fiestas de la Virgen de la Encarnación y San Juan','Patronal y Etnográfica. Se celebra en Junio y Septiembre. Festejos en el frondoso norte de La Gomera, caracterizados por los bailes de tambor tradicionales, exhibiciones de silbo gomero y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38006','fiesta','Fiestas de San Andrés Apóstol (Las Tablas de San Andrés)','Etnográfica, Enológica y Rito Popular. Se celebra en Noviembre. Fiesta de Interés Turístico Regional de hondo impacto popular. Consiste en el vertiginoso arrastre de los jóvenes sobre tablas de madera por las empinadas calles del pueblo, coincidiendo con el descorche del vino nuevo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38024','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Carnaval de Los Llanos (Fiesta de la Polvacera). Se celebra en Julio (Patronales) y Febrero (Carnaval). Relevancia comarcal altísima. El Carnaval destaca por el rito tradicional de "La Polvacera", donde la ciudad se cubre completamente de polvos de talco en un ambiente festivo masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38025','fiesta','Fiestas Patronales de San Antonio Abad y el Salvador','Patronal y Concurso de Vinos. Se celebra en Enero y Agosto. Homenaje al cultivo de la viña en el norte tinerfeño, aunando la bendición de animales domésticos en invierno con comidas y parrandas populares en época estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','fiesta','Fiestas de la Infraoctava del Corpus Christi y Fiestas Patronales de San Isidro Labrador y Santa María de la Cabeza','Religiosa, Alfombras de Flores y Tierras, Romería Masiva. Se celebra en Junio. Fiesta de Interés Turístico Internacional. Destaca por sus monumentales e inigualables alfombras de flores y arenas volcánicas del Teide en la plaza del Ayuntamiento, seguidas de una de las romerías más aristocráticas y populosas del archipiélago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38027','fiesta','Fiestas Trienales de la Bajada de la Virgen del Pino y Fiesta del Sagrado Corazón de Jesús','Patronal, Etnográfica y Alfombras de Flores. Se celebra en Agosto / Septiembre (Bajada trienal) y Junio (Sagrado Corazón). Fiesta de Interés Turístico Regional por la Bajada de la Virgen del Pino, un evento de enorme fervor en La Palma que destaca por su romería tradicional y las monumentales alfombras de tapices naturales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38901','fiesta','Fiestas en honor a San Antonio Abad y Fiestas de la Virgen de los Reyes (participación en la Bajada cuatrienal)','Patronal, Etnográfica y Tradición de Bailarines. Se celebra en Enero y Septiembre. Relevancia comarcal y de fuerte identidad insular; sus bailarines tocan el tambor, las chácaras y la flauta en una de las procesiones de pastores más puras de Canarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38011','fiesta','Fiestas de Julio (Grandes Fiestas de la Virgen del Carmen y San Telmo) y el Carnaval Internacional del Puerto de la Cruz','Marinera, Masiva y Carnaval. Se celebra en Febrero/Marzo (Carnaval) y Julio (Embarcación del Carmen). Fiesta de Interés Turístico Nacional. La masiva e icónica embarcación de la Virgen del Carmen en el muelle pesquero congrega a más de cien mil fieles en un baño de fervor colectivo sin igual.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38032','fiesta','Fiestas de Nuestra Señora de La Esperanza','Patronal y Romería Tradicional. Se celebra en Agosto. Festividad local de alto arraigo tinerfeño, caracterizada por su populosa Romería de La Esperanza, que congrega carretas, agrupaciones folclóricas y un ambiente ganadero tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38018','fiesta','Fiestas Patronales de la Virgen de la Esperanza','Patronal y Bajada de las Hayas. Se celebra en Enero y Agosto. Atractivo etnográfico notable gracias al rito de la "Bajada de las Hayas", donde los vecinos recolectan ramas de haya en el monte y las transportan en romería para adornar el pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38051','fiesta','Fiestas de la Virgen de la Victoria','Patronal, Histórica y Gastronómica. Se celebra en Agosto y Septiembre. Conmemoración histórica de las batallas coloniales, integrada con una rica oferta de guachinches tradicionales y catas de vinos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38010','fiesta','Fiestas de Mayo (Cruces y Fuegos de Los Realejos) y Romería de San Isidro Labrador','Religiosa, Espectáculo Pirotécnico, Romería Regional. Se celebra en Mayo. Fiesta de Interés Turístico Nacional. La exhibición pirotécnica de la noche del 3 de mayo es una de las mayores y más espectaculares competiciones de fuegos artificiales de Europa, enfrentando históricamente a las calles del Medio y del Sol.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38042','fiesta','Fiestas en honor a Nuestra Señora de la Luz','Patronal y Festival de Cuentos. Se celebra en Septiembre (Patronal) y Diciembre (Festival Literario). A las verbenas tradicionales de septiembre se une su célebre Festival Internacional de Cuentos "Saltos de Página", que dota al municipio de gran empaque cultural regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38029','fiesta','Fiesta del Almendro en Flor','Gastronómica, Agrícola y Etnográfica. Se celebra en Febrero. De relieve provincial y autonómico muy fuerte, celebra el florecimiento de los almendros palmeros repartiendo vino del país y dulces tradicionales de almendra entre oleadas de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38030','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Junio. Pequeña celebración tradicional palmera con hogueras de San Juan, festivales de folklore tradicional y competiciones deportivas autóctonas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38033','fiesta','Fiestas de Nuestra Señora de Montserrat','Patronal y Encuentro Indiano local. Se celebra en Septiembre. Importancia en el noreste palmero por sus grandes verbenas populares, carreras de sortijas a caballo y procesiones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38023','fiesta','Fiestas del Santísimo Cristo de La Laguna y Romería de San Benito Abad','Patronal, Religiosa, Romería Regional y Fuegos Artificiales. Se celebra en Julio (San Benito) y Septiembre (Cristo). Fiesta de Interés Turístico Nacional la Romería de San Benito por ser el máximo exponente del folclore de las islas. Las fiestas del Cristo destacan por sus espectaculares "Fuegos del Risco" en una ciudad Patrimonio de la Humanidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38034','fiesta','Fiestas en honor a San Juan Bautista','Patronal y Rito del Humo. Se celebra en Junio. Mantiene la curiosa tradición etnográfica de encender hogueras con pinillo verde creando una gran humareda ritual para dar la bienvenida a la fiesta del santo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38035','fiesta','Fiestas de San Miguel Arcángel','Patronal y Feria de Artesanía. Se celebra en Septiembre. Festejos del sur de Tenerife que aúnan la Romería tradicional, exposiciones de alfarería canaria y orquestas populares nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38036','fiesta','Fiestas Lustrales de la Bajada de la Virgen de Guadalupe y Fiestas Colombinas','Patronal (Lustral), Etnográfica e Histórica. Se celebra en Octubre (Lustrales cada 5 años) y Septiembre (Colombinas). Fiesta de Interés Turístico Regional por las Fiestas Lustrales. La procesión marítima de la patrona insular desde la Ermita de Puntallana hasta la capital convoca un fervor extraordinario con bailes de tambor ancestrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38037','fiesta','Fiestas Lustrales de la Bajada de la Virgen de las Nieves (Danza de los Enanos)','Patronal (Lustral), Etnográfica y Rito Tradicional. Se celebra en Julio / Agosto (Cada 5 años). Fiesta de Interés Turístico Nacional de inmenso calado mundial. La Danza de los Enanos, que se transforman mágicamente ante el público al compás de una polka polifónica, atrae cobertura y visitantes globales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38012','fiesta','Carnaval de Santa Cruz de Tenerife y Fiestas de Mayo','Carnaval Masivo Global y Etnográfica (Fiestas de Mayo). Se celebra en Febrero / Marzo (Carnaval) y Mayo (Patronales). Fiesta de Interés Turístico Internacional y declarada como "Patrimonio de la Humanidad" latente. Considerado uno de los carnavales más importantes del planeta por su espectacular Gala de la Reina, murgas, comparsas y masivo ambiente callejero seguro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16135','fiesta','Fiestas de San Antonio de Padua','Patronal y Etnográfica. Se celebra en Junio. Celebración rural y norteña caracterizada por su vistosa romería mariana, ferias de repostería local como los tradicionales bizcochos de Moya y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38013','fiesta','Fiestas de Santiago Apóstol y Nuestra Señora de la Candelaria','Patronal. Se celebra en Julio. Romerías tradicionales que transcurren junto a los campos lávicos históricos del volcán Chinyero, uniendo devoción y un imponente paisaje natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38041','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Festejos del norte de la isla centrados en hermosos tapices florales urbanos, catas colectivas de vino y festivales de música coral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38043','fiesta','Fiestas del Santísimo Cristo de Tacoronte','Patronal y Enológica. Se celebra en Septiembre. Relevancia insular muy alta. Atrae a millares de peregrinos de toda Tenerife para venerar su histórica imagen sagrada, coincidiendo con ferias de la vendimia de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38045','fiesta','Fiestas en honor a San Miguel Arcángel','Patronal y Rito Singular. Se celebra en Septiembre. Destaca la divertida Danza de los Caballitos de Fuego de herencia local y el desfile festivo por el enclave costero y platanero del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38046','fiesta','Romería de San Marcos Evangelista','Patronal, Agrícola y Etnográfica. Se celebra en Abril. Fiesta de Interés Turístico Regional. Inaugura oficialmente el calendario de romerías tradicionales de la isla, famosa por sus carretas decoradas artesanalmente con barcos hechos de granos de cereales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38047','fiesta','Fiestas de la Natividad de la Virgen (Danza del Diablo de Tijarafe)','Patronal, Etnográfica y Ritos de Fuego. Se celebra en Septiembre. Fiesta de Interés Turístico Regional. En plena madrugada festiva aparece un diablo gigante de metal cargado de pirotecnia que baila entre la multitud escupiendo fuego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38049','fiesta','Fiestas de Nuestra Señora de los Reyes y San Antonio','Patronal y Romería Costera. Se celebra en Enero y Julio. Festejos que combinan los tradicionales e identitarios toques de chácaras y tambores con una afluencia notable de turismo alternativo internacional en el palmeral del sur.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38050','fiesta','Fiestas de San Juan Bautista y Fiestas Lustrales de la Virgen del Carmen','Patronal y Romería Insular. Se celebra en Junio (San Juan) y Julio (Carmen cada cinco años). Las fiestas lustrales del Carmen congregan de forma masiva a la población retornada de Venezuela y la península en grandes bajadas folclóricas por el norte isleño.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38048','fiesta','Fiestas de la Bajada de la Virgen de los Reyes','Patronal, Insular y Etnográfica Macromanifestación. Se celebra en Julio y Agosto (Cada cuatro años). Fiesta de Interés Turístico Nacional. Todo El Hierro acompaña a su patrona a pie por el "Camino de la Virgen" durante 28 kilómetros, mudando los bailarines de cada pueblo sus trajes al cruzar las rayas comunales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38052','fiesta','Fiestas en honor a San Agustín y el Santo Hermano Pedro','Patronal e Histórico-Religiosa. Se celebra en Agosto. Festejos en el municipio más alto de Canarias que homenajean al primer santo del archipiélago, congregando peregrinos pastoriles que recorren los senderos tradicionales desde la costa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90027','fiesta','Fiesta de los Limones en Novales y Fiestas de San Roque','Gastronómica, Agrícola y Patronal. Se celebra en Julio (Limones) y Agosto (San Roque). Gran relevancia comarcal por la Fiesta de los Limones de Novales, donde el pueblo se decora por completo y se ensalza la producción de su microclima con mercadillos y repostería artesanal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90243','fiesta','Fiestas Patronales de la Virgen de la Bien Aparecida y los Encierros de Ampuero','Taurina, Patronal y Etnográfica. Se celebra en Septiembre. Fiesta de Interés Turístico Regional. Sus encierros taurinos son conocidos popularmente como "los sanfermines del norte" debido a su antigüedad y a la inmensa cantidad de mozos y aficionados que congregan.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90244','fiesta','Fiesta de la Virgen de las Nieves y Certamen de la Jota Montañesa','Etnográfica y Patronal. Se celebra en Agosto. Festejo de hondo tipismo en el centro de Cantabria, destacando el encuentro folclórico que preserva las tonadas tradicionales y los bailes con albarcas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90245','fiesta','Fiestas de Nuestra Señora del Moral','Patronal y Romería Tradicional. Se celebra en Septiembre. Romería montañesa tradicional de gran arraigo en el Valle de Iguña, donde se sube a la ermita en la braña con carros engalanados, piteros y folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90635','fiesta','Fiestas de San Esteban y San Roque','Patronal y Tradición Marinera. Se celebra en Agosto. Celebración vecinal típica de la zona de las marismas, caracterizada por juegos infantiles, marmitadas populares y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90028','fiesta','Fiestas de San Pantaleón en Castillo y Feria del Pimiento de Isla','Gastronómica y Patronal. Se celebra en Julio (San Pantaleón) y Septiembre (Pimiento). Relevancia provincial alta por la Feria del Pimiento de Isla, que atrae a miles de visitantes para adquirir su famoso producto hortícola y degustar los menús gastronómicos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90636','fiesta','Feria del Primer de Año y Fiestas de San Pelayo','Feria de Ganado y Patronal. Se celebra en Junio (San Pelayo) y Noviembre (Feria). Conocido históricamente como "la capital del mundo" por los indianos; su feria ganadera de ganado caprino y ovino es una de las más auténticas del Alto Asón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90030','fiesta','Fiestas de San José','Patronal y Urbana. Se celebra en Marzo. Festejos urbanos masivos en el área metropolitana de Santander, con una destacada feria del libro, competiciones de remo tradicionales en la ría y desfiles de carrozas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90246','fiesta','Fiestas de Nuestra Señora de la Consolación y San Roque','Patronal y Etnográfica. Se celebra en Agosto. Verbena típica del interior cántabro ligada al paso de la calzada romana, orientada a la convivencia estival y pasacalles folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90029','fiesta','Fiestas de San Roque en Ajo y Fiesta de San Juan','Patronal y Romería Costera. Se celebra en Junio y Agosto. Festejos estivales muy animados debido a la afluencia turística de las playas de Ajo, centrados en parrilladas y música comercial de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39012','fiesta','Día de Cantabria (Día de la Montaña)','Etnográfica, Folclórica e Identitaria. Se celebra en Agosto. Fiesta de Interés Turístico Nacional. Es la gran exaltación de las tradiciones cántabras, con desfiles de carros típicos, demostraciones de deporte rural, mercados de queso y pasacalles de miles de albarcas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39013','fiesta','Fiestas de la Virgen del Carmen en Frama','Patronal y Romería de Montaña. Se celebra en Julio. Pequeña festividad lebaniega rodeada de viñedos y frutales, basada en misas tradicionales con cantos corales y comidas compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39014','fiesta','Fiestas de la Virgen de la Velilla y la Campana de oro en Carmona','Etnográfica y Feria Ganadera. Se celebra en Septiembre. Hito etnográfico en el corazón de la Cantabria profunda, con pasás de ganado tudanco adornado con campanos ruidosos bajando de los puertos de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','fiesta','Fiesta de la Salud en los Puertos de Aliva','Romería de Montaña y Etnográfica. Se celebra en Julio. Fiesta de Interés Turístico Regional. Celebrada en plenos Picos de Europa a más de 1.400 metros de altura; los romeros suben a pie, a caballo o en todoterrenos para rendir culto en la pradera alpina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39016','fiesta','Fiestas de la Virgen del Carmen en Revilla de Camargo','Patronal, Romería y Fervor Religioso. Se celebra en Julio. Romería nocturna multitudinaria a nivel regional; miles de peregrinos de toda Cantabria caminan de madrugada portando velas hasta la ermita para la misa de luz.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39027','fiesta','Fiestas de San Pedro en Nestares','Patronal. Se celebra en Junio. Celebración vecinal pacífica en el entorno de Reinosa, con torneos de bolos cántabros, comidas populares y orquestas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39017','fiesta','Fiestas de la Virgen de las Nieves','Patronal y Romería Campurriana. Se celebra en Agosto. Romería tradicional cántabra junto al Embalse del Ebro, caracterizada por meriendas campestres, pandereteras y trajes típicos campurrianos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39018','fiesta','Fiestas de San Roque','Patronal e Histórica. Se celebra en Agosto. Festejos que aprovechan el impresionante marco del Camino Real y los torreones medievales de Cartes, con mercados artesanos y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39019','fiesta','Fiestas de la Virgen de la Santa Cruz en Socobio','Patronal y Tradicional. Se celebra en Septiembre. Festividad en torno al entorno monumental de su colegiata románica, con procesión, pasacalles de piteros y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39020','fiesta','Coso Blanco y la Pasión Viviente de Castro-Urdiales','Desfile Artístico (Coso Blanco) y Recreación Histórica-Religiosa (Pasión). Se celebra en Semana Santa (Pasión) y Primer viernes de Julio (Coso Blanco). Ambas citas ostentan el rango de Fiesta de Interés Turístico Nacional. La Pasión Viviente es una sobrecogedora representación por el casco viejo marinero, y el Coso Blanco llena la noche de carrozas de papel celofán calado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30019','fiesta','Fiestas de Nuestra Señora del Carmen en Villayuso','Patronal y Tradición Rural. Se celebra en Julio. Pequeña celebración rural montañesa centrada en la música folk local, el juego de bolos y comidas compartidas entre los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39022','fiesta','Fiesta del Orujo (celebrada conjuntamente en la comarca) y San Sebastián en Tama','Enológica/Gastronómica y Patronal. Se celebra en Noviembre (Orujo). Participación directa en la producción y festejos del orujo lebaniego en la falda de Picos de Europa, con catas tradicionales en las alquitaras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39024','fiesta','Fiestas del Santo Cristo del Amparo y la Danza del Kiko','Patronal, Etnográfica y Marinera. Se celebra en Julio. Fiesta de Interés Turístico Regional. Conserva la espectacular procesión marítima con las embarcaciones del puerto, el baile tradicional del Kiko y una gran quema de fuegos artificiales frente al palacio modernista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39025','fiesta','Guerras Cántabras y Fiestas de San Juan','Recreación Histórica (Guerras Cántabras) y Patronal. Se celebra en Junio (San Juan) y Último fin de semana de Agosto (Guerras). [1] *. Las Guerras Cántabras son Fiesta de Interés Turístico Nacional; miles de personas recrean con absoluto rigor arqueológico los campamentos, batallas y desfiles de las legiones romanas contra las tribus cántabras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39026','fiesta','Fiestas de San Vicente de Toranzo y Mercado Tradicional Alceda','Patronal y Feria de Oficios. Se celebra en Julio y Agosto. Festejos en el Valle de Toranzo que reviven antiguos oficios tradicionales artesanos de la madera en sus parques termales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39028','fiesta','Fiestas de la Virgen del Rosario y San Vicente','Patronal. Se celebra en Octubre. Celebración vecinal con fuerte tradición rural en Trasmiera, con campeonatos de bolos y bailes modernos de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39029','fiesta','Fiesta de la Virgen de la Cama','Patronal y Fervor Religioso Tradicional. Se celebra en Agosto. Famoso en la comarca oriental por su emotiva procesión nocturna donde se porta la imagen yacente de la Virgen, atrayendo a numerosos devotos de los pueblos colindantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39030','fiesta','Fiestas de San Vicente y las Nieves en el Alto de las Nieves','Patronal y Romería de Montaña. Se celebra en Agosto. Romería montañera tradicional en la frontera con el País Vasco, caracterizada por la subida masiva a pie hasta la cumbre rocosa de las Nieves.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39031','fiesta','Fiestas de San Roque en Beranga','Patronal. Se celebra en Agosto. Fiestas tradicionales de marcado arraigo rural e íntimo en el interior de Trasmiera, enfocadas al reencuentro veraniego familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39032','fiesta','Romería de Labradores a la Virgen de Labra','Romería Etnográfica y Ganadera. Se celebra en Agosto. Celebración típica campurriana que rinde tributo a las labores del campo, con cantos folclóricos de ronda e indumentaria tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39033','fiesta','Fiestas de San Antonio en Bielva','Patronal y Folclórica. Se celebra en Junio. Celebración pequeña en el Valle del Nansa centrada en romerías tradicionales con música de gaita y pito montañés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39034','fiesta','Fiestas de San Bartolomé y Feria Ganadera de Quintanilla','Feria de Ganado y Patronal. Se celebra en Agosto. Feria ganadera serrana de ganado vacuno y caballar de gran pureza, manteniendo intacto el espíritu de trato comercial tradicional a la antigua usanza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39035','fiesta','Batalla de Flores de Laredo','Desfile Monumental, Artístico y Tradicional. Se celebra en Último viernes de Agosto. Fiesta de Interés Turístico Internacional. Impresionante y masivo desfile de carrozas de colosales dimensiones recubiertas por completo de millones de flores naturales (claveles y dalias) clavadas a mano pacientemente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39036','fiesta','Fiestas de la Virgen de la Regata y San Fermín','Patronal y Romería Tradicional. Se celebra en Julio. Celebración familiar en su idílico valle verde, con concursos de paellas, juegos infantiles tradicionales de Cantabria y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39037','fiesta','Fiestas de San Pedro y el Hombre Pez','Patronal y Hito Mitológico-Cultural. Se celebra en Junio y Julio. Aprovecha la famosa leyenda mitológica del Hombre Pez de Liérganes para dinamizar turísticamente la villa monumental con representaciones callejeras y verbenas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39038','fiesta','Fiestas del Santísimo Cristo de la Agonía','Patronal y Fervor Religioso Histórico. Se celebra en Septiembre. Famoso santuario regional que atrae a peregrinos devotos de toda España para sus solemnes procesiones y bajadas del venerado Cristo milagrero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39039','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Romería del Valle de Pas. Se celebra en Septiembre. Típica romería pasiega con puestos de dulces artesanales como sobaos y quesadas, salto pasiego tradicional y música folclórica local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39040','fiesta','Fiestas de Nuestra Señora de las Nieves en Gajano y Regatas de Traineras en Pedreña','Deportiva, Marinera y Patronal. Se celebra en Agosto. Su vinculación histórica con las regatas tradicionales de traineras y el remo dota de un gran dinamismo costero y deportivo a sus fiestas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39041','fiesta','Fiesta de los Casados en Villanueva de la Peña','Tradicional y Lúdica. Se celebra en Agosto. Curiosa festividad vecinal que rinde homenaje y organiza juegos tradicionales exclusivos para matrimonios, con verbenas y parrilladas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39045','fiesta','Fiestas de San Juan Bautista','Patronal y Rito de Hogueras. Se celebra en Junio. Pequeña celebración rural pasiega basada en las hogueras de solsticio en el accidentado karst calcáreo del río Miera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39044','fiesta','Fiestas de la Virgen del Monte en Mogro','Patronal y Romería de Costa. Se celebra en Agosto. Animadas verbenas estivales al borde de la ría de Pas, atrayendo al público veraneante de los campings y playas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39046','fiesta','La Vijanera en Silió (Nota: Silió pertenece a Molledo) y Fiestas de la Virgen del Camino','Carnaval Ancestral y Masivo. Se celebra en Primer domingo de Enero. La Vijanera es Fiesta de Interés Turístico Nacional. Es el primer carnaval del año en Europa; rito pagano precristiano espectacular donde los "zarramacos" se visten de pieles con pesados campanos para ahuyentar los malos espíritus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39047','fiesta','Fiestas de San Emeterio y San Celedonio','Patronal, Veraniega y Urbana masiva. Se celebra en Agosto y Septiembre. Festejos que aprovechan la enorme explosión demográfica estival de Noja, ofreciendo macro-conciertos gratuitos, ferias de atracciones infantiles y fuegos en la playa de Trengandín.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39048','fiesta','Fiestas de San Pedro en Sobarzo','Patronal. Se celebra en Junio. Celebración vecinal tranquila en la comarca de las de Pisueña, complementada por la proximidad turística del Parque de Cabárceno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39049','fiesta','Fiestas de San Pedro en Linares y Romería de la Virgen de la Salud','Patronal y Tradición de Montaña. Se celebra en Junio. Pequeñas romerías serranas situadas junto al espectacular Desfiladero de La Hermida, con fuerte componente familiar y folk tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39050','fiesta','Fiesta del Laurel y Fiestas de San Roque','Etnográfica y Gastronómica. Se celebra en Agosto. Festejos en el interior lebaniego dedicados a ensalzar los productos boscosos de la comarca, con degustaciones locales e hilanderas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16157','fiesta','Feria del Queso Artesano de Pesquera','Gastronómica y de la Tierra. Se celebra en Agosto. Destacado hito comarcal que convierte a este diminuto municipio en el epicentro quesero del norte de España durante un fin de semana, con catas y talleres tradicionales de cuajada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39052','fiesta','Fiestas de la Virgen de Valencia en Vioño','Patronal y Romería Tradicional Masiva. Se celebra en Septiembre. Fiesta de Interés Turístico Regional. Tradicionalísima e importante concentración multitudinaria en el santuario forestal, con reparto masivo de paella popular, piteros y saltos de danza prima.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39053','fiesta','Certamen Ganadero de Polaciones y Fiesta del Purriego','Etnográfica, Folclórica y Feria de Ganado. Se celebra en Septiembre. Fuerte identidad purriega preservada en la Cantabria más alta, destacando la música tradicional de rabel de cuerdas de tripa y tonadas montañesas arcaicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39054','fiesta','Fiestas de San Pedro e hito literario de José María de Pereda','Patronal y Cultural. Se celebra en Junio. Festejos locales marcados por el orgullo cultural de la cuna del escritor Pereda, con certámenes literarios y verbenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','fiesta','Fiesta del Orujo de Potes y Fiestas de la Santísima Cruz','Enológica, Gastronómica y Tradicional. Se celebra en Septiembre (Cruz) y Noviembre (Orujo). La Fiesta del Orujo está declarada Fiesta de Interés Turístico Nacional; multitudinaria cata de aguardientes destilados públicamente en alquitaras de cobre por las calles medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39056','fiesta','Fiestas de San Miguel y Jornadas de las Cuevas Prehistóricas','Patronal y Cultural-Arqueológica. Se celebra en Septiembre. Festividades arropadas por el estatus termal del municipio y sus famosas cuevas de arte paleolítico Patrimonio de la Humanidad, atrayendo turismo comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39057','fiesta','Verbena de la Rosa de Ramales','Etnográfica y Tradición de Baile Histórico. Se celebra en Julio. Fiesta de Interés Turístico Regional. Tradición romántica originada en las Guerras Carlistas, donde las parejas bailan vals portando rosas naturales que se intercambian ceremoniosamente.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39058','fiesta','Fiestas de los Santos Mártires y San Andrés','Patronal y Etnográfica. Se celebra en Septiembre. Festejos locales singulares por poseer una plaza de toros cuadrada tradicional de mampostería donde se celebran capeas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39059','fiesta','Fiestas de San Mateo (Día de Campoo)','Romería Etnográfica, Tradicional e Identitaria. Se celebra en Septiembre. Fiesta de Interés Turístico Nacional. El Día de Campoo es un soberbio homenaje al folclor campurriano, colapsando la ciudad de carretas de bueyes, justas de rabel y rondas de mozos que cantan tonadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39060','fiesta','Fiestas de San Miguel Arcángel en Puente San Miguel y Día de las Instituciones de Cantabria','Institucional, Histórica y Patronal. Se celebra en Julio (Instituciones) y Septiembre. Gran relevancia provincial; acoge el acto oficial de reafirmación histórica identitaria cántabra con izado de bandera y folclor institucionalizado masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39061','fiesta','Fiestas de la Virgen de Latas y Festival de Surf de Somo','Romería Marinera y Deportiva. Se celebra en Agosto. [1] *. Aúna la ancestral e histórica romerías tradicional de Latas con el ambiente joven y deportivo de la primera reserva de surf de España en Somo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39062','fiesta','Fiestas de San Mamés','Patronal. Se celebra en Agosto. Celebración vecinal pacífica en el interior de Trasmiera basada en comidas de hermandad, partidos lúdicos de fútbol y verbenas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39063','fiesta','Feria Ganadera de San Miguel en Puentenansa','Feria de Ganado de la Tierra. Se celebra en Septiembre. Feria vacuna muy prestigiosa en los valles occidentales para la compraventa de ganado tudanco, conservando costumbres comerciales tradicionales ancestrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39064','fiesta','Fiestas de San Juan Bautista en La Cavada','Patronal e Histórico-Industrial. Se celebra en Junio. Festejos marcados por el orgullo histórico de su antigua Real Fábrica de Artillería, con desfiles de época y pasacalles populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39065','fiesta','Fiestas de la Virgen de la Luz','Patronal y Tradición del Pantano. Se celebra en Septiembre. Pequeña festividad ligada al paisaje del Embalse del Ebro, vertebrada por procesiones religiosas tradicionales y meriendas campestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39066','fiesta','Feria de San Simón (Feria de la Fuentona de Ruente)','Ganadera, Gastronómica y Mitológica. Se celebra en Octubre. Relevancia comarcal alta por su exposición de ganado tudanco y el magnetismo folclórico de la surgencia kárstica de La Fuentona, hogar legendario de las anjanas cántabras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39067','fiesta','Fiestas de la Virgen de los Milagros en Riva','Patronal y Fervor Religioso Tradicional. Se celebra en Septiembre. Romería tradicional en el Valle de Ruesga que atrae a peregrinos de toda la cuenca del Asón para encender velas y compartir almuerzos campestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39068','fiesta','Fiesta de los Picayos de Ruiloba (Fiesta de la Virgen de los Remedios)','Etnográfica y Ritos de Danza Histórica. Se celebra en Julio. Fiesta de Interés Turístico Regional. Famosa por la espectacular y arcaica ejecución de la Danza de los Picayos, donde los danzantes castañean al son de versos religiosos tradicionales montañeses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39069','fiesta','Fiestas de San Felix y el Magosto de la Castaña','Patronal y Tradicional. Se celebra en Mayo y Noviembre (Magosto). Festejos tradicionales locales integrados en el fértil valle de Buelna, con asados comunitarios de castañas y campeonatos de bolos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39070','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Pequeña festividad rural serrana basada en procesiones tradicionales, torneos de cartas de guiñote y orquestas comunales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39071','fiesta','Fiesta de Santiago Apóstol y Fiesta de los Santos Mártires','Patronal y Etnográfica. Se celebra en Julio y Agosto. Celebración clave en las Villas Pasiegas que salvaguarda el tipismo de la cultura del pastoreo de montaña, con concursos de salto pasiego, soka-tira y cante de tonadas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39072','fiesta','Fiestas de San Roque','Patronal y Etnográfica. Se celebra en Agosto. Festejos marcados por el aislamiento histórico de su geografía pasiega, atrayendo turismo comarcal para presenciar exhibiciones de muda ganadera, folclore y juegos tradicionales de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39080','fiesta','Fiesta de La Folía y Fiestas de El Carmen','Patronal, Marinera y Etnográfica. Se celebra en Abril o Mayo (La Folía, segundo domingo tras Pascua) y Julio. Fiesta de Interés Turístico Nacional. La Folía destaca por su imponente procesión marítima de barcos pesqueros engalanados que escoltan a la Virgen de la Barquera acompañados por los cantos de las "picayas".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39073','fiesta','Fiestas de San Roque y el Festival de Cine de Acción de España','Patronal, Urbana y Cultural. Se celebra en Agosto. Gran animación en el área metropolitana de Santander, combinando eventos modernos y culturales de gran asistencia con las tradicionales verbenas, fuegos artificiales y peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39074','fiesta','Fiestas de San Lázaro en Sarón y Fiestas del Pilar','Patronal y Macro-feria Comercial. Se celebra en Julio y Octubre. Relevancia comarcal alta en el Valle de Cayón por sus concentraciones de peñas, desfiles de carrozas humorísticas y ferias comerciales y gastronómicas de gran afluencia provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39075','fiesta','Fiestas de Santiago (Semana Grande de Santander) y la Romería de la Virgen del Mar','Patronal, Taurina, Musical y Macro-festividad. Se celebra en Mayo (Virgen del Mar) y Julio (Santiago). Fiesta de Interés Turístico Regional. La Semana Grande de la capital moviliza a toda la comunidad autónoma con su feria taurina de Santiago, conciertos masivos en la Campa de la Magdalena y casetas gastronómicas urbanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39076','fiesta','Auto Sacramental y Cabalgata de Reyes de Santillana del Mar, y las Fiestas de Santa Juliana','Religioso-Teatral e Histórica. Se celebra en Enero (Reyes) y Junio (Santa Juliana). Fiesta de Interés Turístico Nacional. Su monumental Cabalgata y Auto Sacramental transforma todo el conjunto histórico medieval involucrando a cientos de vecinos y figurantes en un despliegue artístico único.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39077','fiesta','Fiestas de San Jorge','Patronal. Se celebra en Abril. Celebración rural y familiar de pequeña escala en el valle de Campoo, centrada en misas tradicionales, juegos infantiles de plaza y una pequeña orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39078','fiesta','Fiestas de Nuestra Señora del Soto','Patronal y Romería Tradicional. Se celebra en Septiembre. Atractivo comarcal relevante en el Valle del Pas, destacando la romería tradicional al santuario barroco de la virgen, el concurso de jotas cántabras y las comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39079','fiesta','Carnaval de Santoña (Carnaval del Norte) y Fiestas de la Virgen del Puerto','Carnaval Marino, Marinera y Gastronómica. Se celebra en Febrero (Carnaval) y Septiembre (Virgen del Puerto). Fiesta de Interés Turístico Nacional por su Carnaval del Norte, famoso por el desfile de comparsas de temática marina y el Juicio en el Fondo del Mar con el entierro del Besugo en la bahía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39081','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Pequeña festividad vecinal de los valles pasiegos asentada sobre verbenas nocturnas tradicionales, torneos de bolos cántabros y meriendas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39082','fiesta','Fiestas de la Virgen de Valvanuz','Patronal, Etnográfica y Romería Masiva. Se celebra en Agosto. Fiesta de Interés Turístico Regional. Es una de las romerías más identitarias y concurridas de los Valles Pasiegos; miles de personas acuden al prado del santuario para disfrutar del folclore y los saltos de bastón pasiegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39083','fiesta','Fiesta de Nuestra Señora de la Bien Aparecida (en Veguilla) y Ferias de la Ganadería de Soba','Patronal y Feria Ganadera. Se celebra en Septiembre. Homenaje al sector ganadero lácteo de las zonas altas del valle, organizando exposiciones de ganado selecto frisón, mercados artesanos y verbenas rurales de fuerte arraigo local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39084','fiesta','Fiestas de la Virgen de la Milagrosa','Patronal. Se celebra en Septiembre. Festejos de ámbito comarcal en el valle de Trasmiera que combinan tradicionales campeonatos de bolo palma, comidas populares de patatas con carne y romerías musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39085','fiesta','Fiestas de Nuestra Señora del Carmen','Patronal y Marinera. Se celebra en Julio. Festejo veraniego con alta proyección provincial, caracterizado por una emocionante y concurrida procesión marítima por la ría de San Martín, acompañada de conciertos al aire libre y peñas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39086','fiesta','Fiesta de la Virgen de la Luz (en Correpoco) y Fiesta de San Miguel en Barcena Mayor','Patronal, Gastronómica y Etnográfica. Se celebra en Septiembre. El entorno histórico medieval de Bárcena Mayor confiere un empaque provincial a sus celebraciones otoñales, donde se ensalzan los cocidos montañeses, la artesanía de madera y el folclore de la comarca de Saja-Nansa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39087','fiesta','Fiestas de la Virgen Grande (La Patrona)','Patronal, Macro-feria, Tradicional y Musical. Se celebra en Agosto. Fiesta de Interés Turístico Regional. Paraliza la segunda ciudad de Cantabria durante diez días con la fastuosa Gala de la Flora — desfile de carrozas de papel maché—, mercadillos artesanos y macro-conciertos gratuitos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39088','fiesta','Fiestas de San Pedro','Patronal y Gastronómica. Se celebra en Junio. Su ubicación aislada en los Picos de Europa otorga un encanto único a la festividad, famosa por el tradicional baile de "la rosca", jotas lebaniegas y la degustación de su renombrado queso Picón Bejes-Tresviso.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39089','fiesta','Fiesta de Nuestra Señora de las Nieves','Patronal y Etnográfica / Ganadera. Se celebra en Agosto. Festejos que ensalzan la raza bovina tudanca, autóctona de Cantabria, rodeados de la arquitectura tradicional montañesa que inspira las novelas de Pereda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39090','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos vecinales de pequeña escala con un marcado tono familiar, dinamizados con juegos para niños, parrilladas populares y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39095','fiesta','Fiestas del Carmen en Pesúes y la Fiesta de los Santos Mártires en Unquera','Patronal, Gastronómica y Costera. Se celebra en Julio y Agosto. Animación comarcal notable en la desembocadura del Deva, famosa por el descenso lúdico del río y por integrar los dulces típicos locales, como las corbatas de Unquera, en sus ferias tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39093','fiesta','Fiestas de Nuestra Señora de Montesclaros','Patronal e Histórico-Religiosa. Se celebra en Septiembre. Sede del Monasterio de Montesclaros, santuario de gran devoción en el sur de Cantabria, atrayendo a peregrinos de Campoo y el norte de Palencia para procesiones populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39092','fiesta','Fiestas de Santa Eulalia en Mataporquera','Patronal y Gastronómica. Se celebra en Julio. *. Destacan a nivel comarcal sus tradicionales ollas ferroviarias de patatas con carne en homenaje al pasado minero y ferroviario del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39094','fiesta','Fiestas de la Virgen de la Velilla y Feria de la Patata de Valderredible','Patronal y Agrícola / Gastronómica. Se celebra en Septiembre (Virgen) y Octubre (Feria). Hito agroalimentario comarcal enfocado en ensalzar la patata local mediante grandes muestras comerciales, concursos de cocina tradicional y romerías folclóricas junto al río Ebro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39096','fiesta','Fiestas de San Cristóbal y Fiesta del Ecce Homo','Patronal y Tradicional Montañesa. Se celebra en Julio y Agosto. Festejos típicamente de montaña en el entorno lebaniego, marcados por las orquestas de verano, parrandas y degustaciones de orujo tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39097','fiesta','Fiestas de Nuestra Señora de la Vega','Patronal, Gastronómica y Hito Etnográfico. Se celebra en Septiembre. Relevancia provincial alta al configurarse como el epicentro cultural de la comunidad pasiega, con mercados del sobado y la quesada artesanal, deportes rurales vernáculos y cantos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39098','fiesta','Fiestas de la Virgen de la Leche','Patronal. Se celebra en Agosto. Festejos tradicionales del valle del Pisueña con el Palacio de Soñanes como marco patrimonial, centrados en música folclórica montañesa, deportes tradicionales y verbenas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39099','fiesta','Fiestas de San Juan y Fiesta de los Santos Mártires en Obregón','Patronal y Tradicional. Se celebra en Junio y Agosto. Gran animación local debido a su cercanía al Parque de la Naturaleza de Cabárceno, ofreciendo tradicionales romerías de pueblo, peñas festivas y parrilladas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39100','fiesta','Fiestas de San Juan Bautista y Santa Eulalia','Patronal. Se celebra en Junio. Celebración vecinal íntima asentada en los ritos de las hogueras de San Juan, pasacalles tradicionales aragoneses y meriendas de hermandad en los barrios rurales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39102','fiesta','Fiestas de Nuestra Señora de la Merced en Boto','Patronal. Se celebra en Septiembre. Festejos comarcales de Trasmiera orientados a la reunión de familias ganaderas, con campeonatos de cartas, comidas populares de asados y verbenas de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90074','fiesta','Fiestas de San Roque y la Virgen de la Asunción','Patronal y popular. Se celebra en Agosto. Celebración tradicional de arraigo local y de fuerte retorno estival, centrada en verbenas y actos religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51015','fiesta','Fiestas de El Salvador y Mercado Medieval de La Adrada','Patronal, Histórica y Recreación. Se celebra en Febrero (San Blas), Agosto (El Salvador) y Mayo (Mercado Medieval). El Mercado Medieval tiene rango y proyección regional atrayendo a miles de visitantes a su castillo, complementado por sus consolidadas fiestas de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90075','fiesta','Fiestas de San Felipe y Santiago','Patronal. Se celebra en Mayo. Festividad comunitaria de carácter estrictamente local, enfocada en la convivencia vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90076','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Pequeña celebración veraniega dinamizada por la población flotante y los antiguos residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90077','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Mayo y Septiembre. Festejos rurales tradicionales de pequeña escala y carácter vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90078','fiesta','Fiestas de la Virgen de la Redonda','Patronal y Romería. Se celebra en Septiembre. Romería tradicional en el Valle de Amblés de arraigo comarcal limitado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51008','fiesta','Fiestas de la Virgen de los Remedios y del Santísimo Cristo de la Exaltación','Patronal y Etnográfica. Se celebra en Septiembre y Octubre. Destaca por sus tradiciones en la Sierra de Gredos, procesiones solemnes y gran afluencia de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','fiesta','Fiestas Patronales de la Virgen del Pilar de Arenas y de San Pedro de Alcántara','Patronal, Religiosa y Tradicional. Se celebra en Septiembre y Octubre. Gran empaque comarcal y provincial, con romerías al Santuario de San Pedro de Alcántara y alta concurrencia turística de comunidades vecinas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90079','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Verbena y actos religiosos de escala estrictamente local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','fiesta','Ferias y Fiestas de San Victorino','Patronal, Taurina y Feria Comercial. Se celebra en Julio. Fiestas de gran peso e importancia histórica en la comarca de La Moraña, combinando encierros tradicionales, ferias y eventos culturales de relevancia regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90080','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña festividad local articulada en torno a ritos religiosos y reuniones vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','fiesta','Fiestas de Santa Teresa de Jesús y Jornadas Medievales de Ávila (El Mercado de las Tres Culturas)','Patronal, Histórica y Cultural. Se celebra en Octubre (Santa Teresa) y Septiembre (Jornadas Medievales). Las Jornadas Medievales ostentan el título de Interés Turístico Nacional con un impacto masivo; las fiestas teresianas vertebran la identidad cultural de la capital provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','fiesta','Fiestas del Santísimo Cristo del Caño y de San Pedro del Barco','Patronal, Gastronómica y Romería. Se celebra en Agosto (San Pedro) y Septiembre (Cristo del Caño). Gran relevancia regional en las estribaciones de Gredos, potenciada por su conocida gastronomía de judías con marca de calidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90082','fiesta','Fiestas del Santísimo Cristo de Gracia','Patronal y Taurina. Se celebra en Septiembre. Reconocimiento comarcal notable debido a sus festejos taurinos tradicionales y gran afluencia estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90083','fiesta','Fiestas de la Asunción de la Virgen','Patronal. Se celebra en Agosto. Festejos locales enfocados en la dinamización de los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90084','fiesta','Fiestas de Santa Teresa y del Santo Cristo de la Agonía','Patronal. Se celebra en Agosto. Tradición local unida al entorno rural limítrofe con Salamanca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05025','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Celebración típicamente familiar y vecinal durante el periodo estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05026','fiesta','Fiestas de la Virgen de la Peña','Patronal. Se celebra en Agosto. Festejos rurales centrados en el reencuentro de familias nativas en el valle del Zapardiel, con santa misa solemne, juegos infantiles y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05027','fiesta','Fiestas de la Virgen de la Salceda','Patronal y Tradicional. Se celebra en Agosto. Festejos locales con actividades culturales infantiles y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05029','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto (fiesta del emigrante). Pequeña celebración adaptada al calendario estival para reunir a la comunidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05030','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Pequeño núcleo rural con festejos estrictamente familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05033','fiesta','Fiestas de San Juan y San Roque','Patronal. Se celebra en Junio y Agosto. Celebraciones tradicionales de baja intensidad fuera del ámbito vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05034','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Verbena e infraestructura festiva mínima de arraigo familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05035','fiesta','Fiestas del Santísimo Cristo en la Agonía','Patronal. Se celebra en Agosto. Fiestas tradicionales de carácter local potenciadas en la época estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05036','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Encuentros vecinales tradicionales sin proyección fuera de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05037','fiesta','Fiestas de los Santos Mártires (San Justo y San Pastor)','Patronal y Etnográfica. Se celebra en Agosto. Destaca en el entorno serrano por la conservación de bailes y trajes tradicionales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05038','fiesta','Fiestas de San Roque y de la Virgen de los Milagros','Patronal e Histórica. Se celebra en Agosto. El gran valor patrimonial de esta villa histórica dota de una singularidad y estética especial a sus ritos e hitos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05039','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos locales de carácter reducido.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05040','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Actos litúrgicos y pequeña verbena veraniega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05041','fiesta','Fiestas de la Virgen de la Abadesa','Patronal, Tradicional y Taurina. Se celebra en Septiembre. Reconocimiento comarcal alto en el Valle del Alberche por sus encierros, festejos taurinos y la tradicional ronda nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05042','fiesta','Fiestas de San Juan','Patronal. Se celebra en Junio. Arraigo estrictamente vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05043','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos familiares y comunitarios de pequeña escala.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05044','fiesta','Fiestas de San Roque','Patronal y Taurina. Se celebra en Agosto. Atrae a antiguos residentes con encierros tradicionales y festejos populares en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05045','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos locales marcados por las reuniones familiares veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05046','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Pequeña celebración rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','fiesta','Fiestas de la Virgen de la Chilla y Fiestas de la Vela','Romería, Patronal y Etnográfica. Se celebra en Septiembre. La Romería de la Virgen de la Chilla es Fiesta de Interés Turístico Regional, destacando por su enorme afluencia, los tradicionales rodeos ganaderos históricos y el cante folclórico del sur de Gredos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05048','fiesta','Fiestas de San Ibán o San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo. Pequeña festividad con misas y meriendas comunitarias tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05049','fiesta','Fiestas de la Santa Cruz y de San Antonio','Patronal y Tradicional. Se celebra en Mayo y Agosto. Hito etnográfico local vinculado a su pasado cantero, con actividades culturales de buena asistencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05052','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración pequeña orientada a los vecinos y veraneantes de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05053','fiesta','Fiestas del Santísimo Cristo de la Humildad','Patronal. Se celebra en Agosto. Celebración estrictamente local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05054','fiesta','Fiestas de San Bartolomé y San Sebastián','Patronal y Etnográfica. Se celebra en Agosto (San Bartolomé) y Enero (San Sebastián, con los tradicionales Zaragüelles). La fiesta invernal de San Sebastián posee un alto valor etnográfico debido a sus disfraces tradicionales y ritos populares en el Valle del Tiétar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05055','fiesta','Fiestas de San Sebastián y de la Virgen de la Muela','Patronal y Gastronómica. Se celebra en Agosto y Octubre (Fiesta de la Castaña). Sus castañares propician una interesante muestra micológica y gastronómica otoñal de creciente afluencia turística.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05056','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeños festejos veraniegos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','fiesta','Carnaval de Cebreros y Fiestas de la Virgen de Valsordo','Etnográfica, Carnaval y Patronal. Se celebra en Febrero/Marzo (Carnaval) y Agosto (Virgen de Valsordo). El Carnaval de Cebreros está declarado Fiesta de Interés Turístico Regional, caracterizado por su desfile monumental de carrozas y comparsas que congrega a miles de personas de toda la provincia y Madrid.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05058','fiesta','Fiestas de San Roque y Fiesta del Mayo','Patronal y Tradición Pagana. Se celebra en Agosto (San Roque) y Mayo (Puesta del Mayo). Conserva el rito tradicional de "poner el Mayo" por los jóvenes de la localidad, con un marcado valor identitario serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05067','fiesta','Fiestas de San Miguel','Patronal e Histórica. Se celebra en Octubre y Agosto. Dinamizado por su cercanía al Castro de la Mesa de Miranda, aunque las fiestas son de escala vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05059','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos tradicionales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05060','fiesta','Fiestas de la Virgen de la Natividad','Patronal. Se celebra en Septiembre. Procesiones y verbenas de carácter estrictamente local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05061','fiesta','Fiestas de San Juan Evangelista','Patronal. Se celebra en Diciembre y Agosto. Asistencia impulsada por los veraneantes debido a la proximidad con la capital abulense.','inventario_fiestas_pdf');
