INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05064','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre. Celebración puramente interna y rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05065','fiesta','Fiestas de la Virgen de la Aurora y de San Juan','Patronal. Se celebra en Junio y Octubre. Fiestas comarcales de la Moraña con procesiones religiosas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05066','fiesta','Fiestas de la Virgen de las Angustias','Patronal y Tradicional. Se celebra en Julio. Destaca por la belleza plástica de sus procesiones nocturnas por el casco histórico medieval y sus tradicionales e históricos vítores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05903','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Fiesta local nacida de la unión de los núcleos de Diego Álvaro y Carpio de Mediados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05070','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeña festividad familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05072','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre. Festejos tradicionales íntimos de población local.','inventario_fiestas_pdf');
