INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05075','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio. Pequeña verbena y actos religiosos de ámbito local.','inventario_fiestas_pdf');
