INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05089','fiesta','Fiestas de San Pedro de Alcántara','Patronal / Etnográfica. Se celebra en Octubre y Agosto. Reconocimiento comarcal en el Bajo Tiétar con procesiones en trajes típicos, rondas tradicionales y encierros.','inventario_fiestas_pdf');
