INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05106','fiesta','Fiestas de San Pedro Bautista','Patronal. Se celebra en Agosto. El municipio menos poblado de la provincia celebra verbenas sencillas de carácter meramente familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05104','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Celebración tradicional de alta montaña ligada históricamente a los ciclos ganaderos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05105','fiesta','Fiestas de Nuestra Señora del Espino y Festival Músicos en la Naturaleza','Patronal / Macro-evento Musical. Se celebra en Julio y Septiembre. El festival "Músicos en la Naturaleza" tiene un impacto masivo nacional; las fiestas patronales mantienen los ritos serranos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05107','fiesta','Fiestas de la Virgen de la Consolación','Patronal. Se celebra en Septiembre. Pequeña celebración rural con meriendas comunitarias y torneos de juegos de cartas autóctonos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05108','fiesta','Fiestas de Nuestra Señora de la Concepción','Patronal. Se celebra en Agosto. Verbena local veraniega que actúa como dinamizador social de la comarca del barco de Ávila.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05109','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos populares con pasacalles, campeonatos deportivos y bailes tradicionales en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05110','fiesta','Fiesta del Cristo de la Luz y La Romería del Ciruelo','Patronal / Etnográfica. Se celebra en Mayo y Septiembre. La Romería del Ciruelo posee una singularidad etnográfica notable con caballos cruzando el río Tiétar, atrayendo a numeroso público comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05113','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración popular serrana junto al río Tormes orientada a los residentes y veraneantes de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','fiesta','Fiestas de San Nicolás de Bari y del Santísimo Cristo de las Injurias','Patronal / Recreación Histórica. Se celebra en Agosto, Septiembre y Diciembre. Hito histórico monumental; sus jornadas eclesiásticas, jornadas isabelinas e importantes campeonatos de galgos tienen peso regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05115','fiesta','Fiestas de la Virgen de la Antigua','Patronal / Taurina. Se celebra en Septiembre. Atrae visitantes de urbanizaciones cercanas gracias a sus encierros tradicionales y festejos taurinos populares.','inventario_fiestas_pdf');
