INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05118','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Octubre. Pequeña función religiosa y actividades populares adaptadas para el vecindario mayoritario del pueblo.','inventario_fiestas_pdf');
