INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05124','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Fiesta serrana en el límite provincial con Salamanca, destacando su procesión y folclore charro-abulense.','inventario_fiestas_pdf');
