INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05126','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Celebración local pequeña caracterizada por las competiciones de juegos tradicionales de calva y petanca.','inventario_fiestas_pdf');
