INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05131','fiesta','Fiestas de las Santas Justa y Rufina','Patronal. Se celebra en Julio. Celebración de arraigo familiar con actos dedicados a los niños y comidas colectivas campestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05132','fiesta','Fiestas de San Pedro de Alcántara y Nuestra Señora de la Puebla','Patronal / Recreación Histórica. Se celebra en Julio y Octubre. Festejos de gran empaque medieval bajo la silueta del Castillo de los Duques de Alburquerque con ferias de artesanía comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05133','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña celebración rural que conmemora el solsticio de verano con sencillos actos populares.','inventario_fiestas_pdf');
