INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05139','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Actos tradicionales centrados en campeonatos de juegos populares y verbenas musicales de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05140','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeña verbena de pueblo en La Moraña con fines puramente de convivencia estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05141','fiesta','Fiestas de la Virgen de la Aliseda','Patronal. Se celebra en Septiembre. Festejos locales al pie de la sierra que constan de actos religiosos, folclore serrano y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05142','fiesta','Fiestas de Santa Cristina','Patronal. Se celebra en Julio. Celebración vecinal que mantiene viva la tradición de las hogueras populares y las comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05143','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Festejos de arraigo local al amparo del Valle de Amblés con verbenas y pasacalles.','inventario_fiestas_pdf');
