INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05145','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Pequeño festejo rural con tradiciones religiosas e infantiles en un entorno marcadamente ganadero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05149','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Actividades culturales de verano junto a su emblemático castillo-palacio mudéjar, atrayendo turismo comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05147','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos tradicionales marcados por la riqueza del arte mudéjar de la localidad como trasfondo cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05148','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración clásica del verano abulense orientada exclusivamente al encuentro familiar de fin de semana.','inventario_fiestas_pdf');
