INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05155','fiesta','Fiestas de San Bartolomé y el Cristo del Barrio','Patronal y Cultural. Se celebra en Mayo y Agosto. Festejos locales marcados por exposiciones culturales temporales y verbenas de carácter vecinal.','inventario_fiestas_pdf');
