INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05169','fiesta','Fiestas del Santo Cristo de las Injurias','Patronal. Se celebra en Septiembre. Tradición local articulada en torno al culto del Cristo con pujas por los banzos y verbenas populares.','inventario_fiestas_pdf');
