INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05182','fiesta','Fiestas de San Roque y el Santísimo Cristo de la Vera Cruz','Patronal, Taurina y Etnográfica. Se celebra en Agosto y Septiembre. Famosas en el Valle del Tiétar por su espectacular plaza de toros portátil de piedra, sus tradicionales "Rondas" cantadas por las empinadas calles y su desbocada animación.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05183','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Celebración de carácter estrictamente familiar e íntimo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05184','fiesta','Fiestas de la Virgen de la Mostaza','Patronal y Romería. Se celebra en Agosto. Romería tradicional en un paraje de pinares fronterizo con Madrid, lo que eleva exponencialmente su afluencia de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05185','fiesta','Fiestas de San Judas Tadeo y San Antón','Patronal. Se celebra en Enero y Octubre. Singular devoción local a San Judas Tadeo que convoca a fieles de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05186','fiesta','Fiestas de la Virgen de la Vega y Feria Goyesca','Recreación Histórica y Patronal. Se celebra en Septiembre. Hito regional destacado por su "Feria Goyesca", donde la villa se engalana y los habitantes visten trajes de época rememorando los tiempos del Ducado de Alba retratados por Goya.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05187','fiesta','Fiestas de San Roque','Patronal y Taurina. Se celebra en Agosto. Importante atractivo estival en el Valle del Tiétar que incluye vistosos pasacalles con gigantes y cabezudos, encierros y animadas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05188','fiesta','Fiestas del Salvador','Patronal. Se celebra en Agosto. Festejos sencillos con caldereta comunitaria para despedir el verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05189','fiesta','Fiestas de San Sebastián y la Virgen de Gracia','Patronal y Etnográfica. Se celebra en Enero y Agosto. Conocida por el encendido de las tradicionales "Luminarias" o hogueras de San Sebastián en invierno y sus animados pasacalles estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05190','fiesta','Fiestas del Santo Cristo de las Angustias','Patronal. Se celebra en Agosto. Pequeña verbena nocturna de fuerte raigambre familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05191','fiesta','Fiestas de San Juan Bautista y la Virgen del Carmen','Patronal. Se celebra en Junio y Julio. Celebración vecinal con misas castellanas tradicionales y juegos de frontón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05192','fiesta','Fiestas de Santiago Apóstol y la Virgen del Fresno','Patronal y Gastronómica. Se celebra en Julio y Septiembre. Festividad marcada por la recolección frutal de la zona y meriendas colectivas en los prados altos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05193','fiesta','Fiestas de San Juan Evangelista y la Virgen de la Antigua','Patronal y Taurina. Se celebra en Agosto. Festejos tradicionales de la Moraña que albergan encierros camperos y novilladas de interés comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05194','fiesta','Fiestas de San Antón y Nuestra Señora de la Asunción','Patronal. Se celebra en Enero y Agosto. Verbenas típicas de la llanura abulense enfocadas al reencuentro comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05195','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal. Se celebra en Agosto. Celebración de la sierra de la Paramera que destaca por sus campeonatos de calva y tute.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05196','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejo humilde con la tradicional hoguera de San Juan como eje etnográfico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05197','fiesta','Fiestas de San Martín Obispo','Patronal. Se celebra en Noviembre. Mantiene viva la tradición de la matanza domiciliaria simulada y cenas populares invernales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05198','fiesta','Fiestas de Santa Bárbara y San Juan','Patronal. Se celebra en Junio y Diciembre. Celebración invernal y estival reducida al ámbito estrictamente vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05199','fiesta','Fiestas de San Bartolomé Apóstol','Patronal. Se celebra en Agosto. Festejos serranos típicos integrados por pasacalles con dulzaina y tamboril.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05200','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeña celebración en el Valle del Corneja orientada al descanso y ocio veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05201','fiesta','Las Luminarias de San Antón','Etnográfica y Rito del Fuego. Se celebra en Enero. Fiesta de Interés Turístico Nacional. Espectacular tradición secular nocturna donde jinetes y caballos cruzan inmensas hogueras dispuestas por las calles del pueblo para purificar a los animales con el humo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05206','fiesta','Fiestas de San Esteban Protomártir','Patronal. Se celebra en Agosto (por traslado). Festejo muy íntimo con procesión litúrgica y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05208','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Reunión anual de vecinos con refresco popular tras los actos religiosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05207','fiesta','Fiestas del Vitor a San Pedro Bautista','Etnográfica y Religiosa. Se celebra en Febrero y Julio. Declarada de Interés Turístico Regional. Destaca el "Vítor", una procesión nocturna a caballo donde los jinetes portan antorchas escoltando un estandarte en honor al mártir local franciscano, creando una estampa medieval única.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05209','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Tradición local basada en misas tradicionales y campeonatos deportivos intergeneracionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05901','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque (agrupa varios anejos)','Patronal. Se celebra en Agosto. Punto de reunión clave para los pueblos de la vertiente norte de Gredos centrales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05210','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo. Festejos locales pequeños orientados a la reunión de vecinos y descendientes del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05211','fiesta','Fiestas de San Juan Bautista y la Virgen de la Resina','Patronal y Etnográfica. Se celebra en Junio y Septiembre. Destaca el fuerte arraigo de la romería y las verbenas estivales que atraen a numerosos visitantes de la comarca del Alberche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05213','fiesta','Fiestas de la Virgen de la Fuentes y San Juan','Patronal y Romería Etnográfica. Se celebra en Septiembre y Junio. Celebración de arraigo local y comarcal ligada a la ermita de la Virgen de las Fuentes con folclore tradicional de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05214','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Celebraciones típicas del verano abulense enfocadas en el retorno de emigrantes y actividades lúdicas infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05215','fiesta','Fiestas de la Virgen de la Piedad','Patronal y Etnográfica. Se celebra en Septiembre. Celebración tradicional de la sierra con subasta de bieldos y procesiones que conservan la identidad local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05216','fiesta','Fiestas de San Martín y de Verano','Patronal y Verbena Estival. Se celebra en Noviembre y Agosto. Festejos marcados por el incremento poblacional en verano con parrilladas comunitarias y campeonatos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05217','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Pequeña verbena local y actos litúrgicos solemnes con procesión tradicional por el núcleo urbano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05218','fiesta','Fiestas del Santo Cristo de la Misericordia','Patronal. Se celebra en Septiembre. Festejos religiosos con tradicionales pujas por los banzos del santo y actividades culturales populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05219','fiesta','Fiestas de San Pascual Baylón','Patronal. Se celebra en Mayo. Festividad local en la comarca de La Moraña con misa solemne y juegos infantiles tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05220','fiesta','Fiestas de la Virgen de la Estación y San Pedro','Patronal y Feria de Muestras. Se celebra en Septiembre y Junio. Fiestas dinámicas debido a su buena conexión logística, con notables encierros camperos y ferias comerciales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05222','fiesta','Fiestas del Santo Cristo de la Exaltación','Patronal y Etnográfica. Se celebra en Septiembre. Destacan sus tradicionales bailes folclóricos y las peñas locales que llenan de animación el pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05221','fiesta','Fiestas de la Exaltación de la Santa Cruz','Patronal y Taurina. Se celebra en Septiembre. Grandes fiestas en el Barranco de las Cinco Villas que incluyen encierros tradicionales y una plaza de toros emblemática.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05226','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Enfocadas principalmente a las actividades familiares durante las vacaciones de verano de la población emigrada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05224','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Verbenas populares y campeonatos de cartas tradicionales en un ambiente íntimo y festivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05225','fiesta','Feria del Paño y Fiestas del Santo Cristo del Sepulcro','Feria Comercial/Histórica y Patronal. Se celebra en Septiembre. Hito comarcal relevante que conmemora el histórico comercio y confección textil de los arrieros riojanos y berrocalenses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05227','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Taurina. Se celebra en Agosto. Gran afluencia de veraneantes de la Comunidad de Madrid; cuenta con espectáculos pirotécnicos de nivel y encierros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05228','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Pequeña festividad rural con procesión, campeonatos de calva y veladas musicales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05904','fiesta','Fiestas de Santiago Apóstol (en Lastra del Cano)','Patronal y Romería. Se celebra en Julio. Celebración serrana que aglutina a las distintas pedanías del término municipal en torno al folclore tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05229','fiesta','Fiestas de Santo Domingo de Silos','Patronal. Se celebra en Diciembre y Agosto (fiesta de verano). Estructura típica de pequeña localidad de la llanura norteña con procesión patronal corta y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05230','fiesta','Fiestas de Santo Tomé y la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Tradición local basada en las misas solemnes, subastas de roscas y la hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05233','fiesta','Fiestas del Santo Cristo de la Serrezuela','Patronal y Tradición Folclórica. Se celebra en Septiembre. Reconocida por la conservación de la jota serrana y trajes típicos locales de gran valor etnográfico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05234','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Festejos netamente veraniegos con actividades infantiles y cenas compartidas al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05235','fiesta','Fiestas de San Benito y del Emigrante','Patronal y Encuentro Estival. Se celebra en Julio y Agosto. Típica fiesta de la comarca de la Moraña enfocada en recuperar tradiciones lúdicas para los jóvenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05236','fiesta','Fiestas de la Virgen de la Nueva','Patronal y Romería. Se celebra en Septiembre. Romería que congrega a los habitantes de los numerosos valles y pedanías que conforman este escarpado municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05237','fiesta','Fiestas de Santa Apolonia','Patronal. Se celebra en Febrero y Agosto. Celebración invernal religiosa complementada con actividades culturales en el periodo estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05238','fiesta','Festival "Luna Celta" y Fiestas de San Roque','Recreación Histórica y Patronal. Se celebra en Agosto. Destaca a nivel provincial por la macro-recreación histórica celta en el Castro de Ulaca, atrayendo turismo arqueológico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05239','fiesta','Fiestas de la Virgen de la Purificación','Patronal. Se celebra en Febrero y Agosto. Marcada por la leyenda local del Castillo de Aunqueospese y eventos culturales veraniegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05240','fiesta','Fiestas de la Virgen de los Remedios y Feria de Agosto','Patronal, Taurina y Macro-feria. Se celebra en Septiembre y Agosto. De los festejos más masivos del sur abulense debido a su población estacional, con encierros de prestigio y grandes conciertos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05241','fiesta','Fiestas de San Antonio de Padua *','Patronal, Taurina y Gastronómica *. Se celebra en Junio *. Fiesta de Interés Regional con arraigados festejos taurinos, pasacalles de gigantes y una masiva afluencia turística.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05242','fiesta','Fiestas de San Marcos','Patronal y Tradición Popular. Se celebra en Abril. Reconocido por sus tradicionales hogueras y procesión donde se baila al santo patrón en la comarca de la Moraña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05243','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Eventos sencillos basados en comidas vecinales y orquestas por la noche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05244','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas de montaña revitalizadas por el turismo rural veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05245','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Dada su cercanía a la capital abulense, atrae público periférico para sus eventos musicales nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05247','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Actos litúrgicos y juegos tradicionales que vertebran la unión comunitaria de las distintas pedanías.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90085','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Festejos tradicionales locales con procesión religiosa y actividades para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05249','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Celebraciones que concentran el ocio en el mes veraniego para dar cabida a los residentes ausentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05251','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Taurina. Se celebra en Agosto. Festejos tradicionales que conservan pequeñas capeas o eventos taurinos de carácter popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05252','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Reunión anual de carácter familiar con sencillos actos religiosos y aperitivo comunal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05253','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festividad local basada en campeonatos de juegos autóctonos y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05254','fiesta','Fiestas del Santo Cristo de la Agonía','Patronal. Se celebra en Septiembre. Famosa a nivel comarcal por sus tradicionales pasacalles y competiciones deportivas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05256','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Actividades lúdicas infantiles y misas solemnes organizadas por la cofradía local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05257','fiesta','Fiestas del Santo Cristo de la Luz','Patronal y Etnográfica. Se celebra en Septiembre. Conserva un rico patrimonio histórico-cultural reflejado en su plaza de toros tradicional y danzas típicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05905','fiesta','Fiestas de la Virgen de las Eras','Patronal y Taurina. Se celebra en Septiembre. Destacan sus tradicionales novilladas y encierros, que congregan a numerosos aficionados del Valle del Alberche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05258','fiesta','Fiestas de Santa María Mayor','Patronal. Se celebra en Agosto. Festejo veraniego clásico adaptado al entorno rural con orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05259','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Comidas populares compartidas por todos los vecinos en las naves municipales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05260','fiesta','Fiestas de la Virgen de la Asunción y San Pedro Bautista','Patronal y Tradición Histórica. Se celebra en Agosto y Febrero. Vinculada históricamente a San Pedro Bautista, mártir en Japón, cuyo festejo evoca raíces locales profundas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05261','fiesta','Fiestas de Santa Marina','Patronal. Se celebra en Julio. Célebre mediáticamente por celebrar las campanadas de Nochevieja al mediodía para los mayores, sumado a sus fiestas patronales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05262','fiesta','Fiestas de San Bartolomé y del Santo Cristo de la Borranchina','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Ricas en folclore dentro del Valle del Tiétar, con tradicionales pasacalles, "vítores" al santo y capeas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05263','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Destaca la presencia de sus famosos verracos de piedra preromanos que sirven de marco estético a las verbenas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05264','fiesta','Fiestas de San Antonio','Patronal. Se celebra en Junio. Festejos tradicionales modestos con campeonatos de cartas, calva y juegos de niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05265','fiesta','Fiestas de San Antonio Padua','Patronal. Se celebra en Junio y Agosto. Actividades lúdicas tradicionales organizadas por las asociaciones culturales locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05266','fiesta','Fiestas del Santo Cristo de la Expiración','Patronal. Se celebra en Agosto. Fiesta marcada por la diáspora familiar veraniega con encanto rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05267','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Actos tradicionales serranos en las cercanías de la Sierra de Gredos, con gran ambiente familiar). Con este último municipio queda completada al 100% la provincia de Ávila, de la A a la Z, respetando la estructura jerárquica y los criterios de puntuación fijados. Si deseas continuar con el proyecto, indícamelo para procesar la siguiente provincia de Castilla y León en orden alfabético: Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90103','fiesta','Fiestas de Santa María la Mayor','Patronal. Se celebra en Septiembre. Festejos de arraigo estrictamente local concentrados en actos litúrgicos en su célebre iglesia románica y pequeñas verbenas familiares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90104','fiesta','Fiestas del Santo Cristo de los Remedios','Patronal y Romería. Se celebra en Septiembre. Celebración de la comarca de la Ribera del Duero con gran implicación en las tradicionales subastas y procesiones a la ermita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90105','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto (fiesta de verano). Encuentros estivales que reúnen a los descendientes del valle de Caderechas con comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90106','fiesta','Fiestas de San Guillermo y la Natividad','Patronal. Se celebra en Septiembre. Pequeñas verbenas que marcan el final de las cosechas en el entorno de la comarca de La Bureba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90107','fiesta','Fiestas de la Natividad de Nuestra Señora','Patronal. Se celebra en Septiembre. Festejos locales dinámicos gracias a su cercanía con Burgos capital, con competiciones deportivas y juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90108','fiesta','Fiestas de San Urbán','Patronal. Se celebra en Mayo y Agosto. Celebraciones familiares basadas en juegos de cartas tradicionales, calva y verbenas musicales de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90109','fiesta','Romería de la Virgen de la Serna','Romería Etnográfica. Se celebra en Julio. Punto de encuentro identitario para las múltiples pedanías del páramo septentrional burgalés con danzas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90110','fiesta','Fiestas de San Roque','Patronal y Ganadera. Se celebra en Agosto. Conserva vestigios de ferias ganaderas en el límite con Cantabria junto con pasacalles y campeonatos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09907','fiesta','Fiestas del Rosario y de San Martín','Patronal. Se celebra en Octubre y Agosto. Municipio de gran crecimiento periférico que organiza eventos musicales consolidados y actividades para la juventud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90111','fiesta','Fiestas de San Mamés','Patronal. Se celebra en Agosto. Pequeñas fiestas del entorno de Miranda de Ebro orientadas a la reunión vecinal y cenas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90779','fiesta','Fiestas de San Diego (en Dobro)','Patronal y Romería. Se celebra en Noviembre y Agosto. Reúne el folclore folclórico de las diversas localidades del cañón del Ebro con muestras de jotas castellanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90112','fiesta','Fiestas de San Juan y Santiago','Patronal. Se celebra en Julio. Festejos junto a las peñas del desfiladero de Pancorbo con verbenas y pasacalles animados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90113','fiesta','Fiestas en Honor a San Vito','Patronal y Enológica. Se celebra en Junio y Septiembre. Arraigo vinícola en plena Ribera del Duero con gran protagonismo de sus históricas bodegas subterráneas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','fiesta','Fiestas de la Virgen de las Viñas','Patronal, Enológica y Taurina. Se celebra en Septiembre. Fiesta de Interés Turístico Nacional. Impacto masivo con la bajada de las peñas, desfile de gigantes y cabezudos, ferias taurinas de relieve e inmenso patrimonio gastronómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90114','fiesta','Fiestas de San Blas y Santa Brígida','Patronal y Etnográfica. Se celebra en Febrero y Agosto. Tradicionales hogueras de San Blas e importantes juegos de bolos tradicionales en el periodo veraniego.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90115','fiesta','Fiestas de la Virgen de la Pinilla','Patronal y Etnográfica. Se celebra en Agosto. Destaca la bajada tradicional de la Virgen de la ermita serrana y los bailes de "la rueda" tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09021','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Sencillos festejos veraniegos orientados al descanso y esparcimiento de familias retornadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09022','fiesta','Fiestas de San Pedro y San Pablo','Patronal. Se celebra en Junio. Procesiones sobrias seguidas de bailes públicos amenizados por charangas de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31029','fiesta','Fiestas de San Vicente Mártir y San Roque','Patronal y Recreación Histórica. Se celebra en Agosto. Muy concurrida por su dinamismo; ocasionalmente incluye pasajes de conmemoración histórica en torno al paso de Juana la Loca). Para garantizar la estabilidad y la calidad del documento de Microsoft Word sin que el sistema sufra cortes imprevistos debido al límite de caracteres: ¿deseas que continuemos de forma inmediata con el siguiente bloque (empezando por Arenillas de Riopisuerga y Arlanzón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09024','fiesta','Fiestas de San Esteban Protomártir','Patronal. Se celebra en Agosto. Festejos típicamente veraniegos con competiciones de cartas, juegos infantiles y cenas de hermandad al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09025','fiesta','Fiestas de San Lorenzo y la Virgen de Vilga','Patronal y Náutica. Se celebra en Agosto. Festejos muy singulares a orillas del Embalse del Ebro que combinan verbenas con actividades acuáticas y gran afluencia de visitantes cántabros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09026','fiesta','Fiestas de San Miguel Arcángel','Patronal y Tradición Serrana. Se celebra en Septiembre y Agosto. Celebración con fuerte identidad ligada a la Sierra de la Demanda, destacando sus danzas folclóricas y juegos autóctonos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09027','fiesta','Fiestas de la Natividad de Nuestra Señora','Patronal. Se celebra en Septiembre. Pequeñas fiestas de arraigo local basadas en la liturgia tradicional y verbenas de plaza orientadas al reencuentro vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09029','fiesta','Representación Histórica de la Batalla de Atapuerca y Fiestas de San Martín','Recreación Histórica y Patronal. Se celebra en Agosto (Batalla) y Noviembre. Fiesta de Interés Turístico Regional. La recreación histórica de la batalla de 1054 atrae a miles de personas y cuenta con un enorme valor etnográfico e impacto turístico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09030','fiesta','Romería de la Virgen de Carrales','Patronal y Romería. Se celebra en Septiembre. Romería tradicional que congrega a los tres barrios históricos del municipio en torno a su ermita románica con bailes típicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09032','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Festejos tradicionales del Campo de Muñó que reviven en el periodo estival para acoger a las familias de emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09033','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Celebraciones en el Valle del Esgueva con campeonatos de bolos castellanos, misas cantadas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09034','fiesta','Fiestas de San Millán y San Pedro','Patronal y Etnográfica. Se celebra en Noviembre y Agosto. Destaca por el gran empaque de sus dos parroquias monumentales, cuyas cofradías organizan procesiones y desfiles de peñas muy animados en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09035','fiesta','Fiesta Romana en Honor a Baco y Fiestas de San Roque','Recreación Histórica y Patronal. Se celebra en Agosto. Hito cultural de gran empaque comarcal basado en los yacimientos romanos de la villa; los vecinos se visten con togues y recrean bacanales y desfiles romanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09036','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Sencilla festividad de carácter rural con bendición de vehículos, juegos infantiles y meriendas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09037','fiesta','Fiestas de la Virgen de Costana','Patronal y Tradición Minera/Serrana. Se celebra en Septiembre. Celebración en plena Sierra de la Demanda que destaca por la conservación de cánticos tradicionales y su pasado ferrón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09038','fiesta','Fiestas de la Virgen del Rosario y San Pedro Apóstol','Patronal y Etnográfica. Se celebra en Septiembre y Junio. Festejos de gran arraigo en la comarca de Pinares con pingada del mayo tradicional y danzas folclóricas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09039','fiesta','Fiestas de San Salvador','Patronal. Se celebra en Agosto. Fiestas serranas volcadas en el deporte rural, campeonatos de pelota mano y verbenas musicales de gran asistencia estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09041','fiesta','Fiestas de San Pedro de Verona','Patronal. Se celebra en Abril y Agosto. Celebraciones locales pequeñas con procesión tradicional y orquestas populares de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09043','fiesta','Fiestas de San Facundo y San Primitivo','Patronal. Se celebra en Noviembre y Agosto. Festejos en la comarca de la Bureba que dinamizan los meses de verano con disfraces y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09044','fiesta','Fiestas de Santiago Apóstol','Patronal y Jacobea. Se celebra en Julio. Ligada históricamente al Camino de Santiago, cuenta con una acogida especial a peregrinos durante sus jornadas festivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09045','fiesta','Fiestas de San Cosme y San Damián','Patronal y del Páramo. Se celebra en Septiembre. Punto de reunión para los pueblos de la comarca del Tozo, con tradicionales subastas y competiciones de bolos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','fiesta','Fiestas de San Vitores y de la Virgen de Belén','Patronal, Etnográfica y Feria Comercial. Se celebra en Septiembre y Junio. Reconocimiento comarcal potente por su tradicional "Danza de Belorado", bailada con zancos y castañuelas, e históricas ferias de muestras alfombradas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09050','fiesta','Fiestas de San Cornelio y San Cipriano','Patronal. Se celebra en Septiembre. Festejos fronterizos con el País Vasco que atraen turismo rural gracias a su entorno natural en el Monumento del Monte Santiago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09051','fiesta','Fiestas de la Virgen de los Dolores','Patronal y Agrícola. Se celebra en Septiembre. Festejos de fuerte carácter agrícola en la Ribera del Duero con tradicionales peñas y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09052','fiesta','Fiestas de la Asunción de Nuestra Señora','Patronal. Se celebra en Agosto. Celebración familiar típica de los pueblos de la Bureba con orquesta en la plaza y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09061','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Pequeñas verbenas que complementan las actividades de ocio estival del Valle de Esgueva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09062','fiesta','Fiestas del Santo Cristo de los Milagros','Patronal y Etnográfica. Se celebra en Septiembre. Conserva tradiciones típicas de la sierra de pinares como el cántico de los mayos y procesiones solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09004','fiesta','Fiestas de San Domingo de Guzmán y San Sebastián','Patronal e Histórico-Religiosa. Se celebra en Agosto y Enero. Hito etnográfico potente por ser cuna del fundador de los Dominicos; destacan la procesión del "Privilegio" y las masivas verbenas en su monumental conjunto histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09065','fiesta','Fiestas del Santísimo Cristo de la Salud','Patronal y Enológica. Se celebra en Septiembre. Celebraciones muy ligadas al vino de la Ribera del Duero, compartiendo hermandad en las bodegas tradicionales del subsuelo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09066','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto. Pequeña verbena local de verano y campeonatos de cartas organizados por la asociación cultural del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09067','fiesta','Fiestas de la Virgen del Carrascal y San Roque','Patronal, Etnográfica y Gastronómica. Se celebra en Agosto. Gran relevancia en la comarca de pinares por la tradicional "Caldereta" popular, bailes tradicionales de jotas y la pingada del mayo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09068','fiesta','Fiestas de Santiago Apóstol y Feria de la Manzana Reineta','Patronal y Gastronómica. Se celebra en Julio y Octubre. Muy conocida a nivel provincial por su feria dedicada a la manzana reineta del Valle de Caderechas, con catas y mercados tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09070','fiesta','Fiestas de San Juan Bautista','Patronal y Cinematográfica. Se celebra en Junio y Agosto. Revitalizada por los aficionados al cine debido a su cercanía con el cementerio de Sad Hill; incluye eventos culturales singulares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09071','fiesta','Fiestas de Santa Eulalia','Patronal. Se celebra en Diciembre y Agosto. Celebraciones modestas de carácter vecinal estructuradas en torno a juegos populares y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09072','fiesta','Fiestas de San Román Mártir','Patronal. Se celebra en Noviembre y Agosto. Aprovecha su cercanía a la capital para organizar grandes verbenas en el mes de agosto orientadas al público joven.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09073','fiesta','Fiestas de Santa Águeda y San Martín','Patronal y Gastronómica. Se celebra en Febrero y Noviembre. Destaca la celebración de las Águedas con fuerte arraigo de jotas y reparto de dulces tradicionales en el área metropolitana de Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09074','fiesta','Fiestas de la Natividad de Nuestra Señora','Patronal. Se celebra en Septiembre. Gran ambiente juvenil en sus verbenas debido al constante crecimiento demográfico y proximidad a la capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09075','fiesta','Fiestas de Santa Eulalia','Patronal y Jacobea. Se celebra en Diciembre y Agosto. Hito en el Camino de Santiago donde se organizan parrilladas comunitarias y actividades lúdicas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09076','fiesta','Fiestas de San Saturnino','Patronal. Se celebra en Noviembre y Agosto. Festejos tradicionales locales basados en comidas vecinales y juegos de bolos autóctonos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09077','fiesta','Fiestas de la Natividad de Nuestra Señora','Patronal. Se celebra en Septiembre. Sencillas verbenas que marcan el final de las campañas de recogida del cereal en la comarca burebana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09078','fiesta','Fiestas de la Natividad de la Virgen','Patronal. Se celebra en Septiembre. Festejos íntimos de montaña con misas solemnes y campeonatos de cartas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09079','fiesta','Fiestas de San Pedro del Alcantara','Patronal. Se celebra en Octubre y Agosto. Celebraciones enfocadas en el retorno estival con pequeñas actuaciones musicales en el centro del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09083','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Paso jacobeo con procesión tradicional e invitación popular a vino y queso de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09082','fiesta','Fiestas de la Virgen del Campo','Patronal y Romería. Se celebra en Septiembre. Festejos tradicionales en el límite con La Rioja con procesión folclórica y cantos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','fiesta','Feria del Ajo y Fiestas de la Virgen de la Manzana','Feria Agrícola/Gastronómica y Patronal. Se celebra en Julio y Septiembre. Hito comarcal muy potente; la Feria del Ajo atrae a miles de visitantes y compradores a este monumental enclave histórico del Camino de Santiago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09084','fiesta','Representación de "Los Siete Infantes de Lara" y Fiestas de San Esteban','Recreación Histórica y Patronal. Se celebra en Agosto (Teatro) y Diciembre. Gran valor etnográfico por el teatro popular al aire libre donde los vecinos recrean este cantar de gesta medieval con gran realismo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09085','fiesta','Fiestas de la Virgen de la Vega','Patronal y Enológica. Se celebra en Septiembre. Festejos vinculados a la cultura del vino de la Ribera del Duero, con peñas dinámicas y tradicionales meriendas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09086','fiesta','Fiestas de San Juan y del Emigrante','Patronal. Se celebra en Junio y Agosto. Muy concurrida por urbanizaciones cercanas y militares del acuartelamiento de Castrillo, ofreciendo verbenas masivas en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09063','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Se organizan en torno a su imponente torreón medieval con verbenas y juegos tradicionales castellanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09093','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Festejos familiares con hinchables para niños, campeonatos de mus y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09094','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Bendición tradicional de maquinaria agrícola y vehículos seguida de una comida comunal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09095','fiesta','Fiestas de San Pedro en Cátedra','Patronal. Se celebra en Febrero y Agosto. Actividades lúdicas veraniegas para atraer a las familias que veranean en la comarca del Arlanzón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09098','fiesta','Fiestas de San Vitores y de la Virgen de la Antigua','Patronal y Etnográfica. Se celebra en Agosto y Septiembre. Hito etnográfico potente por sus antiquísimas danzas folclóricas con trajes tradicionales de gran valor y la bajada del santo de su ermita de las dehesas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09100','fiesta','Fiestas de Santa Eulalia','Patronal. Se celebra en Diciembre y Agosto. Enfocadas al ocio de los meses estivales con música tradicional y concursos de cocina local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09101','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Misa solemne con procesión por las calles de la villa y bailes amenizados por charangas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09102','fiesta','Fiestas de la Virgen de Encinillas','Patronal y Romería. Se celebra en Septiembre. Romería tradicional de gran encanto en el entorno de las Merindades y junto al río Ebro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09103','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Tradicionales meriendas en las bodegas del pueblo acompañadas de charangas y competiciones de juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09104','fiesta','Fiestas de Santa María Magdalena','Patronal. Se celebra en Julio. Pequeñas verbenas y juegos tradicionales de cartas organizados por la comisión de fiestas local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09105','fiesta','Fiestas de la Virgen del Carmen','Patronal. Se celebra en Julio. Celebración vecinal con cantos tradicionales del rosario de la aurora y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09108','fiesta','Fiestas de San Pedro y San Antón *','Patronal *. Se celebra en Junio y Enero *. Dinamismo creciente gracias a su ubicación en la autovía A-1, destacando por sus orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09109','fiesta','Fiestas de San Juan Bautista y Romería de San Formerio','Patronal y Romería Etnográfica. Se celebra en Junio y Septiembre. Hito potente en el enclave de Treviño; la romería a la ermita de San Formerio congrega a decenas de pueblos con procesiones tradicionales de gran fervor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09110','fiesta','Fiestas de la Virgen de la Calle','Patronal. Se celebra en Agosto. Ubicado en el entorno de Santo Domingo de Silos; se llena de visitantes estivales que disfrutan de verbenas rurales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09112','fiesta','Fiesta del Avión (Homenaje a Diego Marín Aguilera) y Fiestas del Cristo','Recreación Histórica/Hito Etnográfico y Patronal. Se celebra en Agosto y Septiembre. Singular homenaje al pionero de la aviación Diego Marín Aguilera frente a su castillo romano-medieval, atrayendo gran interés cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','fiesta','Fiesta de la Cereza y Fiestas de San Cosme y San Damián','Gastronómica, Histórica y Patronal. Se celebra en Julio y Septiembre. Fiesta de Interés Regional. El Mercado Medieval y Fiesta de la Cereza inunda la villa de puestos artesanales, trajes de época y atrae turismo masivo nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09114','fiesta','Fiestas de Santa Marina','Patronal. Se celebra en Julio. Festejos ligados a la tradición de los canteros de piedra del municipio con competiciones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09115','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto. Actividades lúdicas estivales integradas en la llanura de la Bureba con gran participación vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09119','fiesta','Fiestas de San Clemente','Patronal. Se celebra en Noviembre y Agosto. Festejos que se trasladan a las fechas de verano para asegurar la afluencia de jóvenes de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','fiesta','Fiestas de San Pedro y San Pablo (Sampedros) y Romería de El Curpillos','Patronal, Etnográfica, Taurina y Romería Masiva. Se celebra en Junio. Fiesta de Interés Turístico Internacional. Destaca la solemnidad de El Curpillos en Las Huelgas con su desfile de gigantones y la tradicional "gira" gastronómica en El Parral, sumado a las ferias taurinas, fuegos artificiales y desfiles multitudinarios de peñas folclóricas). Para continuar con el proyecto en el orden estricto solicitado y asegurar que el sistema no sature sus límites de respuesta: ¿deseas pasar de inmediato al Bloque 3 (empezando por los municipios con la letra D como Danvila / Denmedio / Diócesis / Duero correspondientes)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42076','fiesta','Fiestas del Santísimo Cristo del Consuelo','Patronal y Taurina. Se celebra en Septiembre. Notable arraigo en el este de la provincia, célebre por sus tradicionales festejos taurinos en su singular plaza mayor porticada, desfile de peñas y jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09120','fiesta','Fiestas de San Cosme y San Damián','Patronal. Se celebra en Septiembre. Festejos pequeños junto a los Montes Obarenes con cenas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09122','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto. Verbenas veraniegas que congregan a los residentes ausentes en la comarca de Arlanza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','fiesta','Fiestas de la Virgen de Begoña y del "Montero"','Patronal, Militar/Histórica y Gastronómica. Se celebra en Agosto y Septiembre. Hito etnográfico de gran relevancia nacional por el homenaje al Cuerpo de Monteros de Cámara del Rey, desfiles militares solemnes, mercadillos de pasiegos y un festival de folclore cántabro-burgalés masivo). Avanzamos a muy buen ritmo. Para continuar de inmediato con el Bloque 4 (empezando por los municipios con la letra F y G como Frandovínez, Fresnillo de las Dueñas y Fuentecén), por favor confírmame con un "ok" o "sigue".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09127','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Festejos típicos de la comarca del Arlanza centrados en verbenas de plaza, campeonatos de mus y calva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09128','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Dinamismo juvenil elevado por su cercanía al área metropolitana de Burgos, con conciertos y parrilladas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09129','fiesta','Fiestas de San Antonio y San Vicente','Patronal y Romería Serrana. Se celebra en Junio y Septiembre. Destaca por su romería de montaña a la ermita de San Vicente y los cánticos folclóricos tradicionales de la Sierra de la Demanda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09133','fiesta','Fiestas de San Román Mártir','Patronal. Se celebra en Noviembre y Agosto. Pequeña festividad veraniega con juegos infantiles y cenas comunitarias organizadas por los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09132','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre y Agosto. Festejos rurales tradicionales basados en la procesión del santo y actividades deportivas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09131','fiesta','Fiestas de la Virgen de la Natividad','Patronal y Enológica. Se celebra en Septiembre. Gran afluencia por su proximidad a Aranda de Duero; destacan los desfiles de peñas y la apertura de bodegas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','fiesta','Fiesta del Capitán y Fiestas del Santo Cristo de los Remedios','Recreación Histórica, Medieval y Patronal. Se celebra en Junio (El Capitán) y Septiembre. Fiesta de Interés Turístico Regional. La Fiesta del Capitán conmemora la rebelión de la ciudad contra el poder señorial con una espectacular danza de banderas frente a su castillo medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09135','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Celebraciones modestas de la comarca de La Bureba basadas en bailes populares de orquesta y juegos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09136','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Gastronómica. Se celebra en Agosto. Muy concurrida dentro de la Ribera del Duero; cuenta con encierros tradicionales y meriendas en los lagares antiguos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09137','fiesta','Fiestas de la Virgen de la Nava y San Antonio','Patronal y Etnográfica. Se celebra en Junio. Hito etnográfico notable por sus antiquísimas Danzas de Fuentelcésped, donde los danzantes visten faldones tradicionales y ejecutan paloteos solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09138','fiesta','Fiestas de la Virgen de la Guía','Patronal. Se celebra en Septiembre. Festejos ribereños tradicionales que reúnen a las familias del pueblo en torno a las bodegas subterráneas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09139','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeña festividad con arraigados juegos de bolos castellanos y concursos de disfraces infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09140','fiesta','Fiestas de San Lorenzo y de la Virgen del Rosario','Patronal y Taurina. Se celebra en Agosto y Octubre. Cuenta con encierros tradicionales y una activa participación de sus peñas festivas en las zonas mineras y vinícolas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09141','fiesta','Fiestas de la Virgen de la Santísima Trinidad','Patronal y Macro-verbena. Se celebra en Junio y Septiembre. Su gran cercanía a Aranda de Duero genera una masiva asistencia a sus orquestas nocturnas y eventos taurinos de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09143','fiesta','Fiestas de San Quirico y Santa Julita','Patronal. Se celebra en Junio y Agosto. Festejos estrictamente familiares orientados a la convivencia vecinal en los valles de La Bureba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09148','fiesta','Fiestas de Nuestra Señora de los Reyes','Patronal. Se celebra en Agosto. Actos religiosos solemnes en su monumental iglesia gótica acompañados de verbenas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09149','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre y Agosto. Pequeñas verbenas que aprovechan el regreso estival de los emigrantes de la localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09151','fiesta','Fiestas de la Virgen de la Vega','Patronal, Enológica e Histórica. Se celebra en Septiembre. Hito en la Ribera del Duero; destaca por la bajada de la Virgen de la ermita, las meriendas en bodegas medievales y el gran empaque de su conjunto histórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09152','fiesta','Fiestas del Santo Cristo de la Exaltación','Patronal y Vinícola. Se celebra en Septiembre. Fiestas muy tradicionales desarrolladas en el entorno de sus dos cerros de bodegas subterráneas, con charangas y procesiones solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09154','fiesta','Fiestas del Santo Cristo del Amparo y Carnaval de Hacinas','Patronal y Etnográfica/Ritos de Fuego. Se celebra en Septiembre y Febrero (Carnaval). Hito etnográfico singular gracias a su ancestral Carnaval, famoso por personajes mitológicos como la Tarasca y el Comendador, rodeados de árboles fósiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09155','fiesta','Fiestas de Santiago Apóstol','Patronal e Histórica. Se celebra en Julio. Festejos enmarcados en la impresionante fortaleza medieval fortificada, con comidas populares y música regional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09159','fiesta','Fiestas de la Inmaculada Concepción','Patronal y Jacobea. Se celebra en Diciembre y Agosto. Punto neurálgico del Camino de Santiago; organiza cenas vecinales que integran de forma activa a los peregrinos internacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09160','fiesta','Fiestas de la Virgen de la Cueva','Patronal y Romería. Se celebra en Agosto. Famosa por su romería a la ermita excavada en la roca, con tradicionales meriendas campestres junto al río.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09162','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Celebraciones ligadas a la historia de las canteras romanas de donde salió la piedra de la Catedral de Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09164','fiesta','Fiestas del Santo Cristo de la Piedad','Patronal. Se celebra en Agosto. Festejos ribereños tradicionales que incluyen competiciones de bolos tradicionales castellanos y desfile de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09163','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Etnográfica y de Naturaleza. Se celebra en Agosto. Gran empaque al inicio del Cañón del Río Lobos; destaca por la pingada del mayo tradicional y las grandes calderetas populares de carne.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09166','fiesta','Fiestas del Santo Cristo de Castillo','Patronal. Se celebra en Septiembre. Reúne a los tres barrios históricos del municipio en torno a la ermita común con juegos de calva y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09167','fiesta','Fiesta del Gallo y Fiestas de San Román','Etnográfica, Jacobea y Patronal. Se celebra en Julio (El Gallo) y Noviembre. Muy conocida en el entorno jacobeo por la pintoresca "Fiesta del Gallo", que incluye carreras tradicionales, juegos populares y reparto gastronómico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09176','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio *. Festejos periféricos de Burgos capital con verbenas pequeñas y comidas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09177','fiesta','Fiestas de Santa Cruz y Feria de la Alubia de Ibeas','Patronal y Gastronómica. Se celebra en Mayo y Noviembre (Feria). Hito gastronómico comarcal de gran relevancia; la feria atrae a miles de personas para degustar y comprar la alubia roja del plato tradicional "olla podrida".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09178','fiesta','Fiestas de San Pedro Mártir','Patronal. Se celebra en Abril y Agosto. Pequeñas verbenas estivales en el límite con La Rioja con juegos tradicionales de cartas y parchís.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09179','fiesta','Fiestas de la Santa Cruz','Patronal. Se celebra en Mayo y Agosto. Actividades familiares organizadas por los vecinos para amenizar las noches del verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09180','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos tradicionales de la comarca del Odra-Pisuerga con pasacalles y campeonatos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09181','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Pequeña orquesta en la plaza del pueblo y competiciones lúdicas para el público infantil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09182','fiesta','Fiestas de Santiago Apóstol','Patronal y Jacobea. Se celebra en Julio. Festejos junto al río Pisuerga y el histórico Puente Fitero, uniendo lazos con la provincia de Palencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09183','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Celebración serrana enmarcada en su magnífica iglesia románica porticada, con bailes tradicionales castellanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09184','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Municipio de baja densidad que revive en agosto con una parrillada de hermandad comunal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09189','fiesta','Fiestas de San Millán (en Castrobarto)','Patronal y Romería. Se celebra en Noviembre y Septiembre. Concentra el folclore de los múltiples núcleos de población de la Merindad con competiciones tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09190','fiesta','Romería de la Virgen de Encinillas','Romería Etnográfica. Se celebra en Septiembre. Tradición compartida en el norte burgalés con gran presencia de visitantes del Valle de Losa y del País Vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09191','fiesta','Fiestas de la Virgen de Lara (en Lara de los Infantes)','Patronal e Histórica. Se celebra en Agosto. Celebraciones con fuerte carga evocadora de la historia de los Siete Infantes de Lara y el origen de Castilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09192','fiesta','Fiestas de San Zadornil','Patronal y de Naturaleza. Se celebra en Agosto. Pequeños festejos integrados en el Parque Natural de Montes Obarenes-San Zadornil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','fiesta','Fiestas del Nacimiento de Nuestra Señora y Fiesta Barroca de Lerma','Patronal, Taurina y Recreación Histórica Barroca. Se celebra en Septiembre y Agosto (Festa Barroca). Fiesta de Interés Regional. Destaca por sus grandes encierros tradicionales y, de forma singular, por la recreación histórica barroca del Siglo de Oro en torno al Duque de Lerma.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09195','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Sencillos festejos veraniegos con bailes de plaza y actividades lúdicas infantiles). El documento para Word avanza de forma sólida y exhaustiva. Para continuar de inmediato con el Bloque 5 (empezando por la letra M con municipios clave de gran empaque como Madrigal de la Altas Torres / Mahamud / Melgar de Fernamental / Medina de Pomar o Miranda de Ebro), por favor confírmame escribiendo "ok" o "sigue".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09196','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Pequeñas verbenas que aprovechan el paso de la autovía A-1 para atraer público comarcal a sus conciertos nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09197','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos rurales íntimos con hoguera tradicional, campeonatos de mus y aperitivos comunitarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09198','fiesta','Fiestas de la Virgen del Basardilla','Patronal y Romería. Se celebra en Septiembre y Agosto. Tradicional procesión folclórica en su monumental entorno gótico-renacentista, con meriendas populares en las bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09200','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos de la comarca de la Sierra con juegos tradicionales castellanos de bolos y calva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09199','fiesta','Fiestas de la Virgen de Castrejón','Patronal y Enológica. Se celebra en Mayo y Agosto. Fuerte arraigo vinícola en la Ribera del Duero, destacando por las reuniones de peñas en los lagares tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09202','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Sencilla reunión vecinal con misa solemne, juegos infantiles y música en la plaza principal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09206','fiesta','Fiestas de San Cornelio y San Cipriano','Patronal. Se celebra en Septiembre. Festejos agrarios de carácter local coincidiendo con el fin de la recogida del cereal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09208','fiesta','Corrida del Gallo y Fiestas de la Virgen del Camino','Etnográfica/Carnaval Singular y Patronal. Se celebra en Febrero (Carnaval) y Agosto. Hito etnográfico potente a nivel provincial por su ancestral Carnaval, donde destacan los disfraces de "zarramacos", las coplas tradicionales y la pintoresca persecución del gallo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09009','fiesta','Fiestas del Rosario y Ruta de Carlos V','Patronal, Taurina y Recreación Histórica. Se celebra en Octubre y Octubre (Ruta). Fiesta de Interés Turístico Regional. Destaca por sus masivos encierros tradicionales taurinos y por la espectacular recreación histórica del último viaje del Emperador Carlos V a su paso por la villa medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09211','fiesta','Fiestas de la Virgen del Velasco y San Roque','Patronal, Fluvial y Taurina. Se celebra en Agosto. Gran relevancia comarcal en el límite con Palencia; cuenta con barcas tradicionales en el Canal de Castilla, encierros camperos y verbenas muy concurridas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09213','fiesta','Fiestas de San Miguel (en Nofuentes)','Patronal y Romería. Se celebra en Septiembre. Aglutina el folclore de las numerosas pedanías de la merindad en torno a actividades lúdicas e infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09214','fiesta','Fiestas de San Juan y Feria Ganadera de Villasante','Patronal y Feria Tradicional. Se celebra en Junio y Octubre. Conserva una importante feria ganadera y de muestras del norte burgalés, complementada con romerías campestres.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09906','fiesta','Romería de la Virgen de Montes Claros','Romería Etnográfica. Se celebra en Mayo. Hito de hermandad comarcal que congrega a más de una quincena de pueblos en torno a su ermita con tradicionales danzas folclóricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09215','fiesta','Romería de San Bernabé (Ojo Guareña)','Romería Etnográfica y de Naturaleza. Se celebra en Junio. Hito potentísimo de enorme valor religioso y natural; miles de romeros asisten a la misa solemne y a la comida popular en el impresionante marco de la cueva-ermita del Complejo Kárstico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09216','fiesta','Fiestas de la Virgen de la Guía (en Pedrosa)','Patronal y Romería ferroviaria. Se celebra en Agosto. Dinamismo vacacional con verbenas concurridas que atraen visitantes del cercano País Vasco y de la cornisa cantábrica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09217','fiesta','Fiestas de San Roque (en Quecedo)','Patronal y Etnográfica. Se celebra en Agosto. Festejos integrados en el cañón del río Ebro con muestras folclóricas de jotas castellanas y deportes tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09218','fiesta','Fiestas de la Virgen de la Ribera','Patronal y Musical. Se celebra en Septiembre. Destaca en la llanura ribereña por el gran nivel de sus actividades culturales veraniegas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09010','fiesta','Fiestas de San Juan del Monte y Fiestas de la Virgen de Altamira','Patronal, Romería Urbana y Gastronómica. Se celebra en Mayo/Junio (San Juan) y Septiembre. Fiesta de Interés Turístico Nacional. La Romería de San Juan del Monte es la mayor romería del norte de España; un estallido masivo de color con blusas, charangas, bombos y gastronomía tradicional mirandesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09220','fiesta','Fiestas de San Eulalia','Patronal. Se celebra en Diciembre y Agosto. Festejos familiares enfocados en el retorno estival con cenas comunitarias al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09221','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Gran participación juvenil por su cercanía a Burgos; cuenta con competiciones deportivas y pasacalles animados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09223','fiesta','Fiestas de San Pedro Apóstol','Patronal y Serrana. Se celebra en Junio y Agosto. Festejos serranos rodeados de robledales, volcados en recuperar música de dulzaina tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09224','fiesta','Romería de Nuestra Señora del Valle','Romería y Patronal. Se celebra en Mayo y Agosto. Celebración ligada a su histórica ermita románica y a los restos arqueológicos de la zona con procesiones solemnes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09225','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Reunión anual de vecinos con campeonatos locales de calva, cartas y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09226','fiesta','Fiestas de Santiago Apóstol y San Juan','Patronal y Romería Trashumante. Se celebra en Julio. Festejos de montaña con gran arraigo de la cultura pastoril e histórica de la Mesta y la trashumancia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09227','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Verbenas populares en la zona norte con pasacalles y parrilladas organizadas por las asociaciones locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09228','fiesta','Fiestas de la Virgen del Egido y "El Cotarro"','Patronal y Enológica/Etnográfica. Se celebra en Septiembre. Hito enoturístico internacionalmente galardonado por la conservación de su colina de bodegas subterráneas, abriendo los lagares tradicionales durante los festejos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09229','fiesta','Fiestas de San Antón y la Virgen de la Vega','Patronal y Enológica. Se celebra en Enero y Agosto. Festejos veraniegos ribereños centrados en espectáculos taurinos de plaza y hermandad en las bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09230','fiesta','Fiestas de la Asunción de Nuestra Señora','Patronal. Se celebra en Agosto. Pequeña orquesta de pueblo y juegos infantiles tradicionales en el entorno de la Bureba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09231','fiesta','Fiestas de la Natividad de Nuestra Señora','Patronal. Se celebra en Septiembre y Agosto. Festejos familiares basados en juegos autóctonos de cartas y campeonatos de mus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09232','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Etnográfica y de Naturaleza. Se celebra en Agosto. Tradición alpina serrana donde destaca la pingada del mayo tradicional y las actividades en torno a las Lagunas Glaciares de Neila.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09235','fiesta','Fiestas de la Virgen de la Basardilla','Patronal y Vinícola. Se celebra en Septiembre. Ambiente muy festivo coordinado por las peñas ribereñas con desfiles y catas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09236','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Actividades lúdicas para niños y comidas populares compartidas por todos los vecinos en las calles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','fiesta','El Cronicón de Oña y Fiestas de San Vitores','Recreación Histórica y Patronal. Se celebra en Agosto (El Cronicón). Fiesta de Interés Turístico Regional. Espectacular representación teatral histórica en el interior del Monasterio de San Salvador donde se escenifica el origen del Condado de Castilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09239','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Sencillos actos religiosos combinados con veladas musicales organizadas por la juventud del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09241','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto. Debido a su cercanía al aeropuerto y a Burgos capital, sus verbenas veraniegas reciben una gran afluencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09242','fiesta','Fiestas del Santo Cristo de la Ruina','Patronal y Romería. Se celebra en Septiembre. Tradicional romería a la ermita románica con merienda campestre compartida por los vecinos de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09243','fiesta','Fiestas de la Virgen del Omnium Sanctorum','Patronal. Se celebra en Agosto. Actividades familiares clásicas de verano con concursos de disfraces y pasacalles populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09012','fiesta','Fiestas del Santo Cristo de Barrio','Patronal, Taurina y de Naturaleza. Se celebra en Agosto. Festejos espectaculares debido al enclave natural de su desfiladero, con suelta de vaquillas tradicional y grandes desfiles de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09246','fiesta','Fiestas de la Virgen del Arroyal y San Roque','Patronal, Etnográfica y Gastronómica. Se celebra en Agosto. Gran tradición pinares con la pingada de tres mayos gigantes, jotas bailadas a la antigua usanza y calderetas populares de carne de toro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09247','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Pequeña festividad a orillas del río Pisuerga adaptada a la temporada vacacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09248','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeñas verbenas rurales de montaña que congregan a los amantes del turismo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09249','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Actividades lúdicas tradicionales de cartas, campeonatos de mus y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09250','fiesta','Fiestas del Santo Cristo de la Salud','Patronal e Histórica. Se celebra en Septiembre. Festejos vinculados históricamente a la figura del rey visigodo Wamba; incluyen procesiones solemnes y pasacalles de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09253','fiesta','Fiestas de Santa Isabel','Patronal. Se celebra en Julio y Agosto. Festejos en el límite meridional con Segovia, con juegos autóctonos castellanos y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09255','fiesta','Fiestas de San Juan (en Valderrama)','Patronal. Se celebra en Junio. Pequeños festejos integrados en el entorno natural del Parque Natural de Montes Obarenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09256','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Enológica. Se celebra en Agosto. Hito vitícola fundamental de la Ribera del Duero; cuenta con degustaciones de sus reconocidos tintos y grandes comidas en bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09259','fiesta','Fiestas de la Santa Cruz','Patronal. Se celebra en Mayo y Agosto. Festejos del entorno del río Urbel que dinamizan el periodo estival con orquestas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09257','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Actividades lúdicas tradicionales de cartas y juegos populares de bolos en la meseta burgalesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09258','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Misa solemne, jotas populares en la plaza mayor y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','fiesta','Fiestas de Santiago Apóstol y de Nuestra Señora de los Remedios','Patronal, Enológica e Histórica. Se celebra en Julio y Septiembre. Hito comarcal de gran belleza; las fiestas se enmarcan en su impresionante plaza ducal y castillo, destacando las danzas folclóricas y las bodegas subterráneas medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09262','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Meriendas colectivas en los cerros de bodegas y verbenas populares animadas por charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09265','fiesta','Romería de la Virgen de Manciles','Romería Etnográfica. Se celebra en Mayo. Tradicional procesión con subastas de banzos y bailes populares en los prados de la ermita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09266','fiesta','Fiestas de la Virgen de la Asunción','Patronal, Serrana y de Naturaleza. Se celebra en Agosto. Festejos de montaña en plena Sierra de la Demanda, con gran protagonismo del deporte rural y el senderismo festivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09267','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña orquesta local y juegos de naipes organizados por las peñas del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09268','fiesta','Fiestas de San Cristóbal y la Pingada del Mayo','Patronal y Etnográfica. Se celebra en Julio. Destaca por la tradicional traída y alzada del mayo con bueyes y el gran empaque de su folklore serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09269','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Actividades lúdicas infantiles orientadas al descanso de familias retornadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34132','fiesta','Fiesta de la Virgen del Socorro y San Juan Bautista','Patronal y Jacobea. Se celebra en Junio y Septiembre. Tradición jacobea marcada por el paso de peregrinos, procesión religiosa con acompañamiento folclórico, campeonatos de cartas y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','fiesta','Fiesta del Escarrete y Fiestas de San Cosme y San Damián *','Etnográfica/Única, Musical y Patronal *. Se celebra en Febrero (Escarrete) y Septiembre *. Hito etnográfico excepcional; la Fiesta del Escarrete es una danza tradicional única donde las parejas bailan alrededor de animales marinos y aves. Además, destaca por su inmensa tradición de bandas de música en la villa salinera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09273','fiesta','Fiestas de San Eufemia','Patronal. Se celebra en Septiembre y Agosto. Festejos tradicionales burgaleses basados en bailes populares en la plaza y juegos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09274','fiesta','Fiestas de San Roque y la Virgen de la Asunción','Patronal, Industrial/Textil y Taurina. Se celebra en Agosto. Hito relevante en la Sierra de la Demanda; célebre por sus grandes desfiles de carrozas artesanales, sus encierros taurinos y su histórica identidad ligada a la industria textil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09275','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre y Agosto. Festejos de verano que organizan macro-meriendas populares y orquestas de música para la juventud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09276','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Etnográfica. Se celebra en Septiembre. Ubicado en el enclave de Treviño, cuenta con una inmensa afluencia y actividades mixtas que combinan el folclore castellano y vasco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09277','fiesta','Fiestas de San Jorge y del Emigrante','Patronal. Se celebra en Abril y Agosto. Festejos tradicionales a orillas del río Arlanza con campeonatos de bolos tradicionales y piragüismo). El avance del ranking es impecable. Para proceder de inmediato con el Bloque 6 (que abarca desde la letra Q hasta la T inclusive, empezando por municipios clave como Quintanaortuño, Quintanar de la Sierra, Roa de Duero, Santo Domingo de Silos o Salas de los Infantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09287','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Festejos dinamizados en el periodo estival por su cercanía a la capital, destacando por sus actividades infantiles y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09288','fiesta','Fiestas de San Esteban','Patronal e Histórica. Se celebra en Agosto. Festejos rurales vinculados históricamente a la boda real de Carlos II con María Luisa de Orleáns, celebrada en esta localidad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09289','fiesta','Fiestas de la Virgen de los Lirios y San Cristóbal','Patronal, Etnográfica y Gastronómica. Se celebra en Julio. Gran empaque en la comarca de Pinares; destaca por la ancestral "pingada del mayo" en la plaza, los torneos de pelota mano y calderetas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09294','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Celebración típica del entorno del Arlanza basada en cenas comunitarias y campeonatos de bolos castellanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09901','fiesta','Fiestas de la Santísima Trinidad y San Roque','Patronal y Cultural. Se celebra en Junio y Agosto. Gran dinamismo turístico gracias al espacio cultural "Territorio Artlanza", que atrae numeroso público a sus eventos veraniegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09295','fiesta','Fiestas de San Vicente','Patronal. Se celebra en Agosto. Festejos vecinales en las proximidades del desfiladero de La Yecla, volcados en recuperar tradiciones locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09297','fiesta','Fiestas de San Facundo y San Primitivo','Patronal. Se celebra en Noviembre y Agosto. Festejos estivales muy concurridos por jóvenes de la comarca debido a sus orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09298','fiesta','Fiestas de San Pedro y San Pablo','Patronal. Se celebra en Junio y Agosto. Sencillas verbenas y actos religiosos solemnes en la comarca de La Bureba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09301','fiesta','Fiestas de Santa Eulalia','Patronal y Ruta del Cid. Se celebra en Diciembre y Agosto. Dinamismo periférico por su cercanía a Burgos, sumado a actividades culturales vinculadas al Camino del Cid.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09302','fiesta','Fiestas de San Juan Bautista','Patronal y Etnográfica. Se celebra en Junio. Festejos serranos que mantienen la traída tradicional del mayo y cantos populares de dulzaina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09303','fiesta','Fiestas de San Pedro','Patronal. Se celebra en Junio y Agosto. Pequeñas verbenas que congregan a las familias vinculadas al turismo rural de la Sierra de la Demanda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09304','fiesta','Fiestas de la Virgen del Monasterio','Patronal y Jacobea. Se celebra en Septiembre. Festejos tradicionales marcados por la hospitalidad con los peregrinos del Camino de Santiago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09306','fiesta','Fiestas de San Julián y Santa Basilisa','Patronal. Se celebra en Enero y Agosto. Actos en torno a su joya de iglesia románica combinados con meriendas vecinales veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09307','fiesta','Fiestas de la Virgen de la Calle','Patronal, Jacobea y Etnográfica. Se celebra en Septiembre. Destaca por sus procesiones con danzantes tradicionales al son de la gaita y tamboril en la entrada del Camino en Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09309','fiesta','Fiestas de San Adrián Mártir','Patronal, Etnográfica y de Naturaleza. Se celebra en Agosto. Festejos en plena comarca de Pinares con la tradicional pingada del mayo y actividades lúdicas rodeadas de huellas de dinosaurio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09310','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Pequeña verbena de plaza y juegos tradicionales organizados por los vecinos de La Bureba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09311','fiesta','Fiestas de San Benito','Patronal. Se celebra en Julio. Sencillas celebraciones a orillas del río Arlanza centradas en juegos infantiles y comidas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09314','fiesta','Fiesta de San Vicente','Patronal. Se celebra en Enero. Pequeños festejos invernales de carácter estrictamente familiar con actos religiosos, juegos de cartas tradicionales y comida de hermandad para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09315','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Gran ambiente de peñas y parrilladas populares por su cercanía al área metropolitana de Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09317','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Municipio de muy baja densidad poblacional que se reúne en torno a una merienda comunal estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09318','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Serrana. Se celebra en Agosto. Festejos típicos de alta montaña con competiciones de pelota mano y jotas tradicionales castellanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09016','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Taurina y Enológica. Se celebra en Agosto. Fiesta de Interés Turístico Regional. Sede de la D.O. Ribera del Duero; celebra espectaculares encierros tradicionales por sus calles y capeas populares de gran raigambre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09323','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre y Agosto. Pequeña orquesta local y juegos de cartas tradicionales en el entorno de la Bureba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09325','fiesta','Fiestas de San Pedro y San Pablo','Patronal. Se celebra en Junio. Procesiones solemnes seguidas de tradicionales meriendas en las bodegas del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09327','fiesta','Fiestas de San Ignacio de Loyola','Patronal. Se celebra en Julio. Festejos familiares basados en competiciones de mus, disfraces infantiles y bailes de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09328','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Celebraciones modestas de carácter vecinal estructuradas en torno a meriendas compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09329','fiesta','Fiestas de San Juan Bautista','Patronal y Frutícola. Se celebra en Junio. Festejos vinculados a la recolecta de la fruta en el Valle de las Caderechas, con catas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09017','fiesta','Fiestas de la Virgen de la Maza y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Cabecera comarcal de la Sierra de la Demanda; organiza grandes encierros, ferias taurinas, campeonatos de pelota y festivales de folclore folclórico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09332','fiesta','Fiestas de la Santa Cruz','Patronal. Se celebra en Mayo y Agosto. Aprovecha su proximidad a la capital para congregar numeroso público en sus verbenas musicales de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09334','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Sencilla festividad de carácter rural con bailes de orquesta tradicionales en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09335','fiesta','Fiestas de San Adrián Mártir','Patronal *. Se celebra en Agosto *. Festejos centrados en la convivencia de los vecinos con juegos infantiles y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09337','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos de la Ribera del Duero con gran protagonismo de las reuniones en las bodegas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09338','fiesta','Fiestas de San Mamés','Patronal. Se celebra en Agosto. Actividades lúdicas de verano que reciben gran asistencia de público joven periférico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09339','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Vinícola. Se celebra en Agosto. Festejos ribereños tradicionales que incluyen meriendas colectivas en los lagares y peñas muy activas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09340','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto. Celebración serrana en torno a su emblemática iglesia románica, orientada al reencuentro vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09360','fiesta','Fiestas de San Vicente','Patronal. Se celebra en Enero y Agosto. Pequeña festividad rural basada en la liturgia tradicional y juegos infantiles veraniegos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09343','fiesta','Fiestas de Santa Cecilia','Patronal. Se celebra en Noviembre y Agosto. Verbenas populares y concursos de cocina organizados por la asociación cultural del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09345','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Gastronómica. Se celebra en Agosto. Muy conocida en la comarca por albergar el Museo de los Aromas; sus fiestas incluyen catas y eventos singulares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09346','fiesta','Fiestas de la Virgen de Urbión','Patronal y Romería Serrana. Se celebra en Septiembre. Tradicional romería de montaña que congrega a los amantes de la naturaleza y el folclore de la Sierra de la Demanda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09347','fiesta','Fiestas de San Pedro y San Pablo y Mercado Medieval','Patronal y Recreación Histórica. Se celebra en Junio y Agosto (Mercado). Hito en el entorno de Miranda; su Mercado Medieval inunda la villa fortificada de puestos artesanales y trajes de época de gran realismo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09348','fiesta','Fiestas de Santa Inés','Patronal. Se celebra en Enero y Agosto. Sencillos festejos veraniegos orientados al descanso y esparcimiento de las familias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09350','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Destaca por la solemnidad de sus procesiones en un entorno monumental dominado por su famosa torre renacentista.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09351','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Celebraciones familiares basadas en comidas compartidas y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09352','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos rurales con tradicionales competiciones de bolos tradicionales castellanos y música popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09354','fiesta','Fiestas de Santa Eulalia','Patronal. Se celebra en Diciembre y Agosto. Pequeña orquesta de pueblo y juegos infantiles en el centro del municipio.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09355','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Celebraciones en el Valle del Esgueva con verbenas nocturnas y meriendas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09356','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos en las cercanías de Santo Domingo de Silos con procesión tradicional e invitación popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','fiesta','Fiesta de Los Jefes y Fiestas de Santo Domingo de Silos','Etnográfica/Única, Tradición Histórica y Patronal. Se celebra en Enero (Los Jefes) y Diciembre. Hito etnográfico notable. La "Fiesta de Los Jefes" recrea la defensa de la villa contra los moros mediante una simulación de hogueras y espectaculares carreras a caballo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09361','fiesta','Fiesta del Petróleo y Fiestas de Nuestra Señora de los Remedios','Conmemorativa/Industrial y Patronal. Se celebra en Junio (Petróleo) y Septiembre. Celebración singular que congrega interés por la historia del único campo petrolífero terrestre de España, con eventos culturales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09362','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Mucha animación en sus orquestas nocturnas gracias a su ubicación en el nudo de comunicaciones cercano a la capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09366','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos del entorno del Arlanza con campeonatos locales de calva, cartas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09368','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Festejos locales pequeños orientados a la reunión de vecinos y descendientes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09369','fiesta','Fiestas de Santa Águeda y de la Virgen de los Prados','Patronal, Etnográfica y Vinícola. Se celebra en Febrero y Septiembre. Gran empaque ribereño; destaca el arraigo de las Águedas y la apertura de sus espectaculares bodegas subterráneas del siglo XVIII.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09372','fiesta','Fiestas de la Virgen del Viso','Patronal. Se celebra en Mayo y Agosto. Verbenas populares estivales que aprovechan su dinamismo y proximidad a Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09373','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Punto de reunión para los pueblos de la comarca de la lora, con juegos tradicionales de bolos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09374','fiesta','Fiestas de San Vicente Mártir','Patronal. Se celebra en Enero y Agosto. Celebraciones familiares típicas del páramo burgalés con orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09375','fiesta','Fiestas de la Virgen de la Asunción','Patronal e Histórica. Se celebra en Agosto. Celebración enmarcada en el territorio histórico de la célebre Batalla de Tamarón del año 1037.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09377','fiesta','Fiestas de la Virgen de las Aguas','Patronal y Jacobea. Se celebra en Agosto. Gran afluencia debido a su ubicación en el Camino de Santiago, ofreciendo importantes verbenas y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09378','fiesta','Fiestas de San Miguel','Patronal. Se celebra en Septiembre. Pequeños festejos de arraigo local basados en meriendas populares y juegos de naipes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09380','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre y Agosto. Sencillas verbenas que complementan las actividades de ocio estival en el Valle de Esgueva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09381','fiesta','Fiestas de la Virgen del Carmen *','Patronal *. Se celebra en Julio *. Pequeñas fiestas serranas rodeadas de un entorno natural de robledales y pinares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09382','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Reunión vecinal anual con misa solemne, aperitivo comunal y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09384','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal e Histórica. Se celebra en Agosto. Festejos en torno a su famoso puente romano sobre el Arlanza, con gran ambiente de peñas y charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09386','fiesta','Fiestas de San Joaquín','Patronal. Se celebra en Agosto. Celebraciones enfocadas en el retorno estival con pequeñas actuaciones musicales de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09387','fiesta','Fiestas de San Juan y del Santo Cristo de la Agonía','Patronal y Navideña/Única. Se celebra en Septiembre y Diciembre (Belén). Muy reconocido a nivel provincial por su espectacular Belén Viviente en el castillo y cuevas, sumado a sus fiestas patronales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09388','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto. Sencilla reunión vecinal con una cena compartida al aire libre para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09389','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Festejos tradicionales del Valle del Arlanza con competiciones de calva y veladas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09390','fiesta','Fiestas de San Martín Obispo y la Virgen del Carmen','Patronal y Etnográfica. Se celebra en Noviembre y Julio. Festejos de gran arraigo en la comarca con tradicionales procesiones y desfiles de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09391','fiesta','Fiestas de San Sebastián y la Virgen de la Asunción','Patronal. Se celebra en Enero y Agosto. Festejos basados en las meriendas populares y el folclore folclórico de jotas en la llanura del Esgueva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09392','fiesta','Fiestas de la Virgen de la Peña','Patronal y Romería Jacobea. Se celebra en Septiembre. Romería tradicional con gran fervor hacia su ermita excavada en la roca, integrando a peregrinos del Camino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09019','fiesta','Fiestas de San Bartolomé','Patronal, Taurina y Gastronómica. Se celebra en Agosto. Gran relevancia en las Merindades; destaca por sus animados encierros tradicionales, masivos desfiles de peñas y parrilladas populares junto al río Nela.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09395','fiesta','Fiestas de San Juan Bautista','Patronal y de Naturaleza. Se celebra en Junio. Festejos de gran encanto ecológico aprovechando su entorno de cascadas y pozas en el Valle del Rudrón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09396','fiesta','Fiestas de la Virgen de la Fuente','Patronal y Cultural. Se celebra en Septiembre y Agosto. Muy conocida por sus rutas de murales artísticos, que sirven de escenario a las verbenas veraniegas). El avance del ranking sigue un patrón perfecto. Para proceder de inmediato con el Último Bloque de Burgos (Letras U, V, W, X, Y, Z, completando la provincia al 100% con municipios como Úrbel del Castillo, Vadocondes, Valdeande, Valle de Mena, Villadiego o Villarcayo), por favor indícamelo escribiendo "ok" o "sigue".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09398','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración de carácter local orientada a la reunión de vecinos en torno a su patrimonio fortificado y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09400','fiesta','Fiestas de San Cosme y San Damián','Patronal, Enológica y Taurina. Se celebra en Septiembre. Festejos de gran tradición en la Ribera del Duero, celebrados en su villa amurallada con tradicionales capeas y meriendas en bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09403','fiesta','Fiestas de la Virgen del Juncal','Patronal. Se celebra en Septiembre y Agosto. Destacan sus tradicionales campeonatos de bolos castellanos y las veladas musicales que animan las noches del verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09405','fiesta','Fiestas de la Virgen del Rosario','Patronal y Vinícola. Se celebra en Septiembre. Festejos ribereños marcados por la apertura de los lagares antiguos y las peñas locales que dinamizan el pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09406','fiesta','Fiestas del Santo Cristo de la Columna','Patronal. Se celebra en Agosto. Dinamismo vecinal en auge debido a su crecimiento demográfico en la autovía A-1, con grandes verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09408','fiesta','Fiestas de la Natividad de Nuestra Señora','Patronal. Se celebra en Septiembre. Sencillas celebraciones que marcan el fin de los trabajos agrícolas en la llanura de La Bureba.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09908','fiesta','Fiestas de San Roque y Romería de la Virgen de Criales','Patronal y Romería Etnográfica. Se celebra en Agosto. Aglutina el folclore norteño de sus múltiples pedanías, atrayendo a numerosos visitantes del País Vasco a sus verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09409','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeños festejos de montaña en un entorno natural privilegiado junto al río Ebro, volcados en el turismo rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09410','fiesta','Fiestas de San Antonio (en Villasana) y Feria de la Cornicabra','Patronal, Gastronómica y de Tradición Cantábrica. Se celebra en Junio y Noviembre (Feria). Hito comarcal relevante en el extremo norte; su feria gastronómica y sus masivas fiestas estivales tienen un fuerte impacto y conexión con Vizcaya.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09411','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Actividades lúdicas tradicionales y comidas populares organizadas para el disfrute de las familias retornadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09902','fiesta','Romería de la Virgen de Cuadros','Romería Etnográfica. Se celebra en Septiembre. Romería tradicional de gran concurrencia comarcal que une a la decena de pueblos del valle con danzas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09905','fiesta','Fiestas de la Virgen de la Gracia (en Sedano)','Patronal y de Naturaleza. Se celebra en Agosto. Festejos de gran encanto cultural y literario, revitalizados en verano por el turismo que recorre el Parque Natural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09412','fiesta','Fiestas de San Bartolomé (en Quintana Martín Galíndez)','Patronal y Deportiva/Acuática. Se celebra en Agosto. Gran animación estival aprovechando el río Ebro y el embalse, con competiciones lúdicas y grandes orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09413','fiesta','Fiestas de la Virgen de la Blanca (en Soncillo)','Patronal y Ganadera. Se celebra en Septiembre. Conserva ferias ganaderas tradicionales de montaña que atraen a tratantes e interesados de Cantabria y Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09414','fiesta','Fiestas de la Virgen de la Vega (en Quintanilla)','Patronal y Serrana. Se celebra en Septiembre. Festejos de fuerte arraigo serrano con jotas tradicionales interpretadas al son de dulzainas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09415','fiesta','Fiestas de Santa Elena','Patronal. Se celebra en Agosto. Celebración clásica del páramo burgalés basada en campeonatos locales de cartas, mus y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09416','fiesta','Fiestas de San Mamés','Patronal. Se celebra en Agosto. Pequeña festividad vecinal que apuesta por la ecología y la unión comunitaria de sus valles despoblados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09417','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos familiares pequeños con orquestas locales de fin de semana en la comarca del Odra-Pisuerga.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09418','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Misa procesional, aperitivo vecinal y competiciones tradicionales de calva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09419','fiesta','Fiestas de San Pedro y San Pablo','Patronal. Se celebra en Junio. Festejos tradicionales en el entorno de La Bureba con comidas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09407','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Municipio de muy baja densidad que organiza una jornada festiva con parrillada comunal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09423','fiesta','Fiestas de San Salvador','Patronal. Se celebra en Agosto. Celebración vecinal íntima con juegos infantiles y música en la plaza principal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09427','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Gran empaque comarcal; destaca por sus animados desfiles de carrozas, capees de toros tradicionales y la conservación de dichos populares de su historia local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09428','fiesta','Fiestas de San Mamés','Patronal y Vinícola. Se celebra en Agosto. Festejos integrados en la Ribera del Duero con meriendas compartidas en las bodegas y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09431','fiesta','Fiestas de Santiago Apóstol y San Roque','Patronal y Jacobea. Se celebra en Julio y Agosto. Punto de parada clave en el Camino de Santiago; organiza eventos lúdicos que integran a vecinos y peregrinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09433','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Sencillas verbenas veraniegas pensadas para los descendientes del pueblo en la falda de la Sierra de la Demanda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09434','fiesta','Fiestas de San Vicente Mártir','Patronal. Se celebra en Enero y Agosto. Dinamismo masivo debido a su cercanía directa con Burgos capital; ofrece verbenas multitudinarias y grandes eventos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09437','fiesta','Fiestas de la Virgen del Madrazo','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Procesiones solemnes en su imponente conjunto gótico-renacentista, complementadas con juegos tradicionales y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09438','fiesta','Fiestas de San Pedro Apóstol','Patronal y Enológica *. Se celebra en Junio *. Gran afluencia por su proximidad a Aranda de Duero; destacan sus comidas populares en bodegas subterráneas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09439','fiesta','Fiestas de la Asunción de Nuestra Señora','Patronal. Se celebra en Agosto. Crecimiento residencial periférico que aporta un ambiente muy juvenil a sus verbenas y desfiles de disfraces.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09440','fiesta','Fiestas del Santo Cristo de la Salud','Patronal. Se celebra en Agosto. Festejos rurales con comidas colectivas en las naves del municipio y torneos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09441','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebraciones modestas de carácter vecinal estructuradas en torno a juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09442','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Vinícola. Se celebra en Agosto. Tradición vinícola de la zona del Arlanza, con verbenas concurridas y meriendas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09444','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Misa solemne, jotas populares en la plaza y campeonatos locales de calva.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09446','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Sencillo festejo rural con parrillada comunal y orquesta de música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09447','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Actividades lúdicas infantiles orientadas al descanso de familias en la comarca serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09448','fiesta','Fiestas de San Pedro Apóstol y Festival de Folk','Patronal y Mural/Musical. Se celebra en Junio y Agosto. Muy conocida a nivel provincial por su ruta de murales dedicados a escritores e ilustradores y sus festivales de música folk.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09449','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos que aprovechan su ubicación vial para atraer público de los alrededores a sus orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09450','fiesta','Fiestas de la Santa Cruz','Patronal. Se celebra en Mayo y Agosto. Pequeña verbena de plaza y competiciones tradicionales de bolos en la falda de la sierra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09451','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Conserva ricas tradiciones de cánticos populares y desfiles de peñas en el entorno de la comarca ribereña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09454','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Festejos locales pequeños basados en la liturgia tradicional y comidas vecinales compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09455','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Veladas musicales organizadas por la comisión de fiestas para amenizar el verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09456','fiesta','Fiestas de la Natividad de Nuestra Señora','Patronal. Se celebra en Septiembre. Festejos de arraigo local tradicionales basados en pasacalles y campeonatos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09903','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Feria de Muestras y Taurina. Se celebra en Agosto. Hito primordial en Las Merindades; organiza potentes ferias de muestras agrarias, grandes encierros taurinos y verbenas multitudinarias junto al río Nela.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09458','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Gran participación de jóvenes debido al auge demográfico y su cercanía al área metropolitana de Burgos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09460','fiesta','Fiestas de la Virgen de Barruelo','Patronal y Romería. Se celebra en Septiembre. Destaca la procesión a su ermita y las meriendas tradicionales campestres compartidas en la comarca del Odra.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09463','fiesta','Fiestas de la Virgen de la Asunción','Patronal y de Naturaleza. Se celebra en Agosto. Muy concurrida por su cercanía al embalse de Úrbel y el pantano; cuenta con orquestas potentes y deportes rurales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09464','fiesta','Fiestas de San Mamés','Patronal. Se celebra en Agosto. Festejos familiares en el Valle del Esgueva con concursos de disfraces infantiles y campeonatos de mus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09466','fiesta','Fiestas de San Quirico y Santa Julita','Patronal. Se celebra en Junio y Agosto. Pequeñas verbenas que congregan a las familias en torno a actividades lúdicas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09467','fiesta','Fiestas de San Adrian','Patronal. Se celebra en Septiembre. Sencilla reunión vecinal anual con misa solemne y aperitivo comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09471','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Gran animación juvenil en sus verbenas de plaza debido a su inmediata proximidad a Burgos capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09472','fiesta','Fiestas de San Andrés','Patronal. Se celebra en Noviembre y Agosto. Sencillos festejos estivales organizados por los vecinos para el disfrute de la juventud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09473','fiesta','Fiestas de Santa Eugenia','Patronal. Se celebra en Agosto. Actos litúrgicos en su monumental iglesia acompañados de juegos tradicionales castellanos y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09476','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio. Festejos familiares pequeños enfocados en mantener viva la hermandad rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09424','fiesta','Fiestas de Santo Domingo de la Calzada','Patronal y Jacobea. Se celebra en Mayo. Cuna de Santo Domingo de la Calzada; conserva un gran valor histórico-religioso en pleno trazado jacobeo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09425','fiesta','Fiestas de San Bartolomé y de la Virgen del Torrejón','Patronal, Etnográfica y Serrana. Se celebra en Agosto. Gran relieve en la comarca de pinares; destaca por la pingada del mayo tradicional con bueyes y la caldereta de carne popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09478','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto. Pequeñas verbenas serranas en un entorno presidido por su magnífica iglesia románica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09480','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos tradicionales del Campo de Muñó basados en comidas vecinales compartidas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09482','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos a orillas del Pisuerga orientados a dinamizar las noches del periodo vacacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09483','fiesta','Fiestas de San Andrés y de la Virgen de la Asunción','Patronal y Enológica *. Se celebra en Noviembre y Agosto *. Hito ribereño tradicional con gran arraigo de sus peñas dentro de sus bodegas subterráneas de origen medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09485','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Sencilla reunión anual de vecinos con campeonatos de mus y música popular de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26001','fiesta','Fiestas de San Nicolás y la Reina de la Cistierna','Patronal y Tradición de Montaña. Se celebra en Septiembre y Julio. Festejos del alto Esla que conservan vivas las tonadas tradicionales leonesas y los juegos de bolos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90196','fiesta','Fiestas del Santo Cristo de la Vega','Patronal. Se celebra en Septiembre. Celebración de la vega del Esla con procesión tradicional, torneos de cartas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90197','fiesta','Fiestas del Sacramento y el Antruejo Tradicional','Etnográfica/Carnaval Singular y Patronal. Se celebra en Febrero (Antruejo) y Junio. Hito etnográfico potente por su ancestral Carnaval con los "Jurrucos" y "Castrejos", personajes mitológicos que escenifican batallas rituales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90664','fiesta','Fiestas de la Virgen de la Blanca y Semana Santa de Almanza','Patronal y Tradición Religiosa. Se celebra en Agosto y Marzo/Abril. Festejos en su villa murada medieval; destaca su recuperada procesión del Santo Entierro y las populosas verbenas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25001','fiesta','Fiestas de la Navidad de Nuestra Señora','Patronal. Se celebra en Septiembre. Festejos en el Páramo leonés centrados en comidas de hermandad y campeonatos de pelota a mano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90198','fiesta','Fiestas de San Juan Bautista y Feria del Vino de Ardon','Patronal y Enológica. Se celebra en Junio y Agosto. Relevancia vitivinícola gracias a las bodegas excavadas en arcilla donde se degusta el vino de la Denominación Tierra de León.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90199','fiesta','Fiestas de la Virgen de la Asunción y Feria del Vino del Bierzo','Patronal y Enológica. Se celebra en Agosto. Festejos con marcado acento berciano; las bodegas señoriales del palacio abren sus puertas al folclore comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26002','fiesta','Fiesta de Astures y Romanos y Fiestas de Santa Marta','Recreación Histórica, Gastronómica y Patronal. Se celebra en Julio (Astures) y Agosto (Santa Marta). Fiesta de Interés Turístico Nacional. Espectacular macro-recreación histórica donde la ciudad regresa al año 25 a.C. con campamentos, circo romano y desfiles de tribus astures de enorme impacto masivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90200','fiesta','El Magosto Celta y Fiestas de Santa Marina','Etnográfica/Gastronómica y Cultural. Se celebra en Noviembre (Magosto) y Julio. Hito cultural potente en los Ancares; su Magosto nocturno reúne a miles de personas en torno a las castañas asadas y conciertos de folk dentro de sus pallozas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26009','fiesta','Carnaval de La Bañeza y Fiestas de Nuestra Señora de la Asunción','Etnográfica/Carnaval de Interés y Gran Premio de Velocidad. Se celebra en Febrero (Carnaval) y Agosto. Fiesta de Interés Turístico Nacional. Su carnaval destaca por no estar sujeto a concursos, primando la espontaneidad y los disfraces artesanos, sumado a su mítica carrera de motos urbana veraniega.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90201','fiesta','Fiestas de Santa Marina','Patronal y Romería de Montaña. Se celebra en Julio. Sencillos festejos en el Bierzo profundo orientados al reencuentro de la población que emigró a zonas urbanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90780','fiesta','Fiesta de Pastores y Vaqueros y Fiestas del Cristo','Etnográfica/Trashumante y Patronal. Se celebra en Septiembre. Hito tradicional relevante que rinde homenaje a la antigua cultura ganadera trashumante y a los rebaños de merinas, reuniendo pendones leoneses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26004','fiesta','Fiestas del Santo Ecce Homo y Festival de Exaltación del Botillo','Gastronómica de Élite, Patronal y Religiosa. Se celebra en Septiembre (Patronal) y Febrero (Botillo). Fiesta de Interés Turístico Regional. Su gala gastronómica en honor al botillo berciano congrega a personalidades nacionales y miles de comensales en una cita cultural de primer orden.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90202','fiesta','Fiestas del Bendito Cristo y Feria del Dulce','Feria Comercial/Gastronómica y Patronal. Se celebra en Septiembre y Septiembre (Feria). Hito de gran dinamismo comarcal en la ribera del Órbigo; su feria reúne a maestros reposteros de todo el noroeste español con catas y muestras multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90203','fiesta','Romería de la Virgen del Valle','Romería Tradicional. Se celebra en Septiembre. Festejos en la Cabrera Alta que reúnen el fervor religioso de varios valles con bailes tradicionales al son de la gaita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90781','fiesta','Fiestas de San Juan Bautista y la Virgen de Perales','Patronal y Jacobea. Se celebra en Junio y Septiembre. Localidad con un marcado carácter jacobeo que organiza cenas comunitarias integrando activamente a los peregrinos internacionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90782','fiesta','Fiestas de San Vicente','Patronal. Se celebra en Enero y Agosto. Festejos del Páramo que trasladan sus eventos principales al verano con verbenas de plaza y campeonatos de bolos leoneses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26005','fiesta','Fiestas de San Roque y Feria del Pilar','Patronal, Ganadera y Tradición Etnográfica. Se celebra en Agosto y Octubre (Feria). Cabecera de la montaña oriental; destaca por la mítica jota leonesa de Boñar, su tradicional mercado del Pilar de origen bajomedieval y los corros de Lucha Leonesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90205','fiesta','Fiestas de San Vicente y de la Virgen de la Vega','Patronal y Entorno Natural. Se celebra en Enero y Agosto. Pequeñas verbenas que aprovechan su ubicación junto a Las Médulas para recibir visitas comarcales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90206','fiesta','Fiestas de la Magdalena','Patronal y Tradición Maragata. Se celebra en Julio. Festejos en tierras maragatas con procesiones solemnes al ritmo de la chifla y el tamboril tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90783','fiesta','Fiestas del Salvador y Romería de la Virgen de la Puerta','Patronal y Romería de Alta Montaña. Se celebra en Agosto. Espectacular marco paisajístico en el Parque Regional de Picos de Europa con muestras de folclore ganadero montañés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90784','fiesta','Fiestas de San Pedro y San Blas','Patronal. Se celebra en Junio y Febrero. Festejos basados en actividades deportivas locales, grandes comidas vecinales y orquestas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90207','fiesta','Fiestas de Santa Ana','Patronal. Se celebra en Julio. Gran ambiente festivo berciano impulsado por sus peñas y torneos de fútbol sala tradicionales de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90208','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Mayo y Septiembre. Sencillas veladas musicales organizadas por los vecinos con juegos tradicionales de cartas e infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26006','fiesta','Certamen Ganadero de Babia y Fiestas del Cristo','Feria Sectorial/Etnográfica y Patronal. Se celebra en Agosto y Septiembre. Hito ganadero de gran prestigio en la comarca de Babia; reúne los mejores ejemplares de ganado equino hispano-bretón y exhibiciones folclóricas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26007','fiesta','Fiestas de la Pascua y Feria Enoturística del Bierzo','Patronal, Enológica y Feria Medieval. Se celebra en Abril (Pascua) y Mayo. Hito comercial berciano de enorme tradición; su mercado medieval y las verbenas multitudinarias en torno a la cultura del vino Mencía atraen a miles de gallegos y leoneses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90665','fiesta','Fiestas de la Virgen de la Soledad y Feria del Caballo de Pura Raza','Patronal, Ecuestre y Enológica. Se celebra en Septiembre y Mayo (Feria). Gran empanque comercial y festivo; sus fiestas de la Soledad son famosas en todo el Bierzo por sus masivas verbenas de orquestas punteras gallegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90210','fiesta','Fiestas de San Quintín','Patronal y Tradición de Ancares. Se celebra en Octubre y Agosto (fiestas estivales). Celebraciones que defienden la arquitectura de pallozas y la música gallego-leonesa serrana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90785','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Pequeños festejos orientados a la reunión familiar veraniega en la comarca de Cea.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90786','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Actividades familiares clásicas con juegos de cartas tradicionales e hinchables en la ribera del Órbigo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90787','fiesta','Fiestas del Rosario','Patronal. Se celebra en Octubre y Julio (fiestas estivales). Dinamismo vecinal elevado por su cercanía al área metropolitana de León capital, organizando verbenas masivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90788','fiesta','Fiestas de la Virgen de la Vega','Patronal y Romería Tradicional. Se celebra en Mayo. Destaca la masiva procesión folclórica hacia su ermita, donde se conserva el milagro histórico de las luces de la llanura.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90789','fiesta','Fiestas de San Bartolomé','Patronal y Fluvial. Se celebra en Agosto. Festejos vinculados a su playa fluvial en el río Órbigo, atrayendo gran turismo juvenil con competiciones y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26008','fiesta','Fiestas de San Guillermo y Feria Ferroviaria','Patronal, Conmemorativa e Industrial. Se celebra en Mayo (San Guillermo) y Agosto. Hito comarcal de la montaña leonesa; rinde honores a su histórica vinculación con el Ferrocarril de La Robla con desfiles de pendones leoneses y corros de aluche.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90217','fiesta','Romería de la Virgen de la Peña','Romería Tradicional y Enológica. Se celebra en Mayo. Romería berciana de gran devoción popular que se celebra en su santuario con vistas al embalse de Bárcena, seguida de meriendas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90790','fiesta','Fiestas de San Pedro y San Pablo','Patronal. Se celebra en Junio. Festejos en la comarca de Los Oteros basados en el folclore castellano-leonés y catas de sus tradicionales vinos de aguja.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90218','fiesta','Fiestas de San Stephen (San Esteban) y Fiesta del Cerezo en Flor','Patronal, Frutícola y de Naturaleza. Se celebra en Agosto y Marzo/Abril. Atrae gran turismo por las rutas de cerezos en flor bercianos, complementado con sus tradicionales procesiones junto a sus iglesias románicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90791','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Tradición Serrana. Se celebra en Agosto. Festejos montañeses junto al río Esla que celebran exhibiciones de Lucha Leonesa y muestras de folclore tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90219','fiesta','Fiestas de San Cipriano','Patronal. Se celebra en Septiembre. Festejos en la ribera del Bernesga con pasacalles populares, macro-meriendas vecinales y música nocturna de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90792','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña orquesta local y juegos populares organizados para las familias que veranean en la comarca de Rueda.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90793','fiesta','Fiestas del Santo Cristo','Patronal. Se celebra en Septiembre. Sencilla reunión vecinal anual con misa procesional y aperitivos comunales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90794','fiesta','Fiestas de San Cristóbal','Patronal y Tradición Minera. Se celebra en Julio. Gran animación festiva e infraestructura gracias a su pasado industrial en el Bierzo, con notables conciertos y desfiles de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90795','fiesta','Fiestas de San Juan y de la Virgen de la Guiana','Patronal y Paisajística/Ecológica. Se celebra en Junio y Septiembre. Festejos celebrados en el entorno directo del Monumento Natural de Las Médulas y el Lago de Carucedo, recibiendo turismo rural nacional). El volcado para Microsoft Word se está organizando con precisión estructural. Para continuar de forma inmediata con el Bloque 2 (empezando por los municipios con la letra D y E como Destriana, El Burgo Ranero o Encinedo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90220','fiesta','Fiestas del Salvador y San Roque','Patronal y Tradición de la Valduerna. Se celebra en Agosto. Festejos rurales tradicionales que reúnen a las familias con competiciones de bolos leoneses y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90796','fiesta','Fiestas del Santo Cristo y de San Pedro (en Calzadilla)','Patronal y Jacobea. Se celebra en Septiembre y Junio. Punto de paso clave en el Camino de Santiago Francés; destaca la hospitalidad jacobea en sus actos y las cenas populares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90221','fiesta','Fiestas de San Mamés y Romería de la Virgen del Valle','Patronal y Romería Etnográfica. Se celebra en Agosto y Septiembre. Festejos en la Cabrera Baja que conservan cantos ancestrales, folclore de pandereta y la gaita de fole típica de la zona de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90222','fiesta','Fiestas de San Bartolomé','Patronal y Tradición Minera. Se celebra en Agosto. Celebración en la antigua cuenca minera de Sabero, marcada por el reencuentro veraniego y torneos deportivos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90797','fiesta','Fiestas de San Clemente','Patronal. Se celebra en Noviembre y Agosto (fiestas de verano). Localidad de muy baja densidad de población en Tierra de Campos que revive en verano con meriendas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90223','fiesta','Fiestas del Corpus Christi y de Santa Bárbara','Patronal y Tradición Minera/Etnográfica. Se celebra en Junio (Corpus) y Diciembre (Santa Bárbara). Hito etnográfico potente por su arraigada identidad minera en el Bierzo; la fiesta de Santa Bárbara destaca por sus emotivas procesiones nocturnas con antorchas y barrenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90224','fiesta','Fiestas de Jesús Nazareno y el Belén Artesano','Patronal y Navideña/Hito Etnográfico. Se celebra en Septiembre y Diciembre/Enero. Su famoso Belén Artesano animado atrae a miles de visitantes en Navidad, complementando sus tradicionales fiestas patronales del Bierzo Alto.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90225','fiesta','Feria de la Pimiento de Fresno y Fiestas de San Roque','Gastronómica de primer nivel y Patronal. Se celebra en Septiembre (Feria) y Agosto. Hito agroalimentario provincial de enorme éxito; su feria exalta el pimiento morrón gigante con miles de visitantes y mercados gastronómicos tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90798','fiesta','Fiestas de San Blas y la Virgen del Carmen','Patronal. Se celebra en Febrero y Julio. Pequeñas verbenas estivales en la zona sur leonesa basadas en la convivencia vecinal y juegos infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90226','fiesta','Fiestas de San Juan Bautista','Patronal y Tradición Ribereña. Se celebra en Junio y Agosto. Dinamismo creciente gracias a su ubicación en la ribera del Torío, con un fuerte arraigo juvenil y orquestas multitudinarias en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90666','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Sencillas celebraciones basadas en las peñas del pueblo, juegos tradicionales y comidas populares compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90227','fiesta','Feria del Vino Prieto Picudo y Fiestas de San Juan','Enológica, Cultural y Patronal. Se celebra en Agosto (Feria) y Junio. Gran empaque vitivinícola en la zona sur; el festival internacional de payasos "Mila_Gros" y la feria del vino atraen a numeroso público provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90228','fiesta','Fiestas de la Virgen del Carmen y Romería de San Froilán','Patronal y Romería Tradicional. Se celebra en Julio y Octubre. Celebración ligada a su imponente monasterio cisterciense románico, destacando por sus exhibiciones folclóricas de pendones leoneses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90799','fiesta','Fiestas de San Roque','Patronal e Histórica. Se celebra en Agosto. Festejos enmarcados en su magnífico palacio renacentista y castillo medieval, con cenas populares e iluminación histórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90800','fiesta','Fiestas del Santo Cristo','Patronal. Se celebra en Septiembre. Actos litúrgicos y reuniones tradicionales de familiares retornados en la comarca de Los Oteros). El avance del ranking es impecable. Para proceder de inmediato con el Bloque 3 (que abarcará las letras H, I, J y L, incluyendo municipios clave como Hospital de Órbigo y León capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90229','fiesta','Justas Medievales del Passo Honroso','Recreación Histórica de Élite. Se celebra en Junio. Fiesta de Interés Turístico Nacional. Espectacular macro-recreación histórica que conmemora la hazaña del caballero don Suero de Quiñones en 1434. Todo el pueblo se transforma en una villa medieval con torneos de caballeros, cetrería y mercados tradicionales que atraen a decenas de miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90230','fiesta','Fiestas de Santa Marina','Patronal y Tradición Minera. Se celebra en Julio. Festejos en el Bierzo Alto marcados por el reencuentro veraniego, competiciones deportivas en su playa fluvial y folclore comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90231','fiesta','Fiestas de San Benito','Patronal. Se celebra en Julio. Sencillas celebraciones tradicionales de la zona sur leonesa basadas en juegos tradicionales de cartas, verbenas de plaza y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90232','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (fiestas estivales). Festejos rurales centrados en el regreso estival de emigrantes, con tradicionales campeonatos de bolos leoneses y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90233','fiesta','Procesión del Corpus Christi de Laguna de Negrillos','Etnográfica y Tradición Religiosa de Élite. Se celebra en Junio. Fiesta de Interés Turístico Regional. Destaca de forma excepcional por la presencia del personaje de San Sebastián, un militar que camina con paso firme y desafiante abriendo paso a la procesión litúrgica, junto a danzantes tradicionales de gran valor etnológico.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90234','fiesta','Fiestas del Santo Cristo','Patronal. Se celebra en Septiembre. Festejos del Páramo leonés basados en misas cantadas, campeonatos de pelota a mano y cenas compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26010','fiesta','Fiestas de San Juan y San Pedro y Romería de San Froilán','Patronal, Romería Tradicional y Semana Santa de León. Se celebra en Junio (San Juan), Octubre (San Froilán) y Marzo/Abril (Semana Santa). Fiesta de Interés Turístico Internacional para su Semana Santa, célebre por la procesión de Los Pasos y el acto del Encuentro. Además, destaca su romería de San Froilán con la mayor concentración de pendones leoneses, el desfile de carros engalanados y la procesión tradicional de Las Cantaderas en la catedral.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90235','fiesta','El Antruejo de Llamas de la Ribera y Fiestas del Rosario','Etnográfica/Carnaval Singular y Patronal. Se celebra en Febrero (Antruejo) y Octubre. Hito etnográfico notable gracias a su ancestral Carnaval tradicional, donde destacan los "Guirrios" con espectaculares abanicos de colores en la cabeza y máscaras zoomorfas, declarados bien de interés cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45086','fiesta','Romería de la Virgen de los Remedios (en Luyego)','Romería Etnográfica Maragata. Se celebra en Octubre. Hito de gran devoción en la comarca de la Maragatería; miles de romeros asisten con la vestimenta tradicional maragata para bailar al son de la chifla y el tamboril.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90801','fiesta','Fiestas de la Virgen de los Remedios y Feria de Luyego','Romería Tradicional y Feria Maragata. Se celebra en Octubre. Centro neurálgico del fervor maragato; rinde homenaje al traje regional y acoge grandes mercadillos artesanales de avellanas y productos de la tierra). El volcado de León avanza con paso firme y descripciones etnográficas de alto valor. Para continuar de inmediato con el Bloque 4 (que abarcará las letras M, N, O y P, incluyendo municipios clave como Mansilla de las Mulas, Ponferrada o Murias de Paredes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90236','fiesta','Fiestas de la Virgen de la Cepeda','Patronal y Romería Comarcal. Se celebra en Agosto. Festejos que reúnen a los pueblos de la comarca de La Cepeda con verbenas y juegos tradicionales de bolos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26011','fiesta','Feria de San Martín y Fiestas de la Virgen de Gracia','Feria Multisectorial Tradicional y Patronal. Se celebra en Noviembre (Feria) y Septiembre. Su histórica feria ganadera de San Martín tiene origen medieval y es un potente referente provincial, sumado al paso del Camino de Santiago.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90237','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Mayo y Agosto. Festejos en la ribera del Esla que promueven verbenas de verano, torneos de cartas y parrilladas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16122','fiesta','Fiestas de la Virgen de Ríos','Patronal y Tradición de Alta Montaña. Se celebra en Agosto. Espectacular marco festivo bajo el Mampodre, destacando por sus exhibiciones de Lucha Leonesa y folclore pastoril.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24099','fiesta','Fiestas de San Pelayo','Patronal. Se celebra en Junio. Festejos en la meseta de Los Oteros con procesiones tradicionales y meriendas populares regadas con vino de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24098','fiesta','Fiestas de San Juan y de la Cuenca Minera','Patronal y Tradición Minera. Se celebra en Junio y Agosto. Celebración en la cuenca del Torío que revive con el regreso estival de familias, ofreciendo verbenas y campeonatos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90802','fiesta','Fiestas del Santo Cristo de la Veracruz','Patronal. Se celebra en Septiembre. Actos religiosos solemnes y juegos populares infantiles en una pequeña localidad con gran arraigo agrario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24100','fiesta','Fiestas de las Angustias y San Roque (Fiesta del Agua)','Patronal, Jacobea y Tradición Singular. Se celebra en Agosto. Hito jacobeo en el Bierzo; su célebre "Fiesta del Agua" inunda las calles abriendo las compuertas del río Meruelo, atrayendo a miles de jóvenes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24101','fiesta','Fiestas de la Virgen de la Seita y Muestra de Oficios Tradicionales','Patronal y Etnográfica/Feria Artesanal. Se celebra en Septiembre y Agosto. Ubicado en Omaña, destaca su muestra etnográfica que recupera la artesanía, el hilado tradicional y el folclore de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24102','fiesta','Fiestas de las San Bartolo','Patronal y Etnográfica. Se celebra en Agosto. Festejos bercianos tradicionales que organizan rutas culturales y verbenas muy animadas gracias a su activa comisión juvenil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24103','fiesta','Fiestas de San Vito','Patronal. Se celebra en Junio y Agosto. Pequeñas celebraciones en el límite suroeste del Bierzo, orientadas a la convivencia familiar y música de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24104','fiesta','Fiestas del Sagrado Corazón','Patronal. Se celebra en Junio y Agosto. Sencillas veladas musicales y juegos infantiles tradicionales organizados junto a la ribera del río Omaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24105','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Julio (fiestas estivales). Elevado dinamismo en sus verbenas y orquestas nocturnas debido a su pertenencia al área metropolitana de León capital.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24107','fiesta','Feria del Vino Prieto Picudo y Fiestas del Cristo','Enológica y Patronal. Se celebra en Agosto (Feria) y Septiembre. Cuna histórica del vino Prieto Picudo; su feria del vino es un hito tradicional que abre las cuevas subterráneas a catas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24108','fiesta','Fiestas de Santa María','Patronal. Se celebra en Agosto. Festejos de la Valduerna marcados por competiciones de bolos tradicionales leoneses y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24109','fiesta','Fiestas de la Virgen de Fátima y San Roque','Patronal y Etnográfica/Tradición Patsueza. Se celebra en Mayo y Agosto. Festejos en el alto Sil que defienden el folclore local y los cánticos en habla asturleonesa o "patsuezu".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24110','fiesta','Fiestas de las Nieves y Magosto y Feria de las Castañas','Patronal y Gastronómica/Etnográfica Notable. Se celebra en Agosto (Nieves) y Noviembre (Magosto). Su "Magosto y Feria de las Castañas" es de los más potentes del Bierzo, recreando antiguos oficios y asando miles de castañas en tambores tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24112','fiesta','Romería de la Virgen de Trascastro (Danza de Fornela)','Romería y Tradición Etnográfica de Élite. Se celebra en Agosto. Hito etnográfico excepcional en el Valle de Fornela; los danzantes visten faldas e interpretan espectaculares bailes de paloteo al son de la gaita.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24113','fiesta','Fiestas de las Vírgenes del Corpus y del Rosario','Patronal. Se celebra en Junio y Octubre (Verano estival). Festejos del Páramo leonés basados en animadas peñas locales, desfiles y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24114','fiesta','Fiestas del Santo Cristo y Feria del Cueto','Patronal, Ganadera y Tradición Etnográfica. Se celebra en Septiembre. Cabecera de la montaña central; sus fiestas aglutinan desfiles de pendones leoneses, corros de aluche y un gran mercado ganadero tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24115','fiesta','Fiestas de la Encina y la Noche Templaria','Patronal, Recreación Histórica de Élite y Fluvial. Se celebra en Septiembre (Encina) y Julio (Noche Templaria). Fiesta de Interés Turístico Regional. La Noche Templaria es una espectacular recreación que transforma la ciudad y su castillo en un feudo medieval con miles de personas vestidas de época.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24116','fiesta','Fiestas de la Virgen de la Corona','Patronal y de Alta Montaña. Se celebra en Septiembre. Celebración en pleno corazón de los Picos de Europa; destaca la ancestral procesión folclórica que congrega el fervor de los valles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24117','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos agrarios de carácter vecinal basados en misas tradicionales, orquestas de plaza y juegos para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24118','fiesta','Fiestas de la Virgen de la Guía','Patronal. Se celebra en Septiembre y Agosto. Pequeñas verbenas que dinamizan la montaña oriental leonesa sirviendo de punto de reunión familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24119','fiesta','Fiestas de la Virgen de los Remedios','Patronal. Se celebra en Octubre y Agosto (fiestas estivales). Sencillas celebraciones bercianas enmarcadas en el entorno del Castillo de Cornatel, con música y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24120','fiesta','Fiesta de la Trashumancia y Fiestas del Santo Cristo','Etnográfica/Trashumante Notable y Patronal. Se celebra en Agosto. Hito tradicional de primer orden; celebra el pasado pastoril de la montaña oriental con demostraciones de mastines leoneses, esquilado y folclore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24121','fiesta','Feria del Ganado de Lillo y Fiestas de las Nieves','Ganadera Tradicional, de Naturaleza y Patronal. Se celebra en Septiembre (Feria) y Agosto *. Su histórica feria ganadera de montaña atrae a cientos de tratantes del norte español, complementada con corros de Lucha Leonesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24122','fiesta','Fiestas de San Antonio y Festival de la Ensalada de Bacalao','Patronal y Gastronómica Comarcal. Se celebra en Junio y Agosto. Ubicado en Cabrera, cuenta con un fuerte lazo cultural gallego y un festival gastronómico tradicional muy concurrido). El volcado maestro continúa estructurándose a la perfección. Para proceder de inmediato con el Siguiente Bloque (Letras Q, R y S, empezando por Quintana del Castillo, Riaño, Sahagún, San Andrés del Rabanedo y Santa María del Páramo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24123','fiesta','Fiestas de San Pedro y de la Virgen de la Portería','Patronal y Tradición de la Cepeda. Se celebra en Junio y Agosto. Festejos rurales centrados en el retorno estival con tradicionales juegos de bolos tradicionales leoneses y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24124','fiesta','Fiestas de San Pedro y San Pablo','Patronal. Se celebra en Junio. Festejos en la vega del Jamuz estructurados en torno a procesiones solemnes, campeonatos de cartas tradicionales y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24125','fiesta','Fiestas de la Virgen del Fresno','Patronal y Romería Tradicional. Se celebra en Septiembre y Agosto. Romería tradicional en las comarcas del sur que congrega a los pueblos vecinos en torno a su ermita arbolada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24127','fiesta','Fiestas del Bendito Cristo','Patronal. Se celebra en Septiembre. Sencillas celebraciones tradicionales basadas en juegos populares infantiles, comidas populares y orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24129','fiesta','Fiestas de San Juan Bautista','Patronal y Romería de Montaña. Se celebra en Junio y Agosto. Festejos de montaña en el alto Porma, con actividades familiares enfocadas en el turismo rural y la convivencia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24130','fiesta','Fiesta de la Alborada y Fiestas de Nuestra Señora de la Quinta Angustia','Patronal, Paisajística y Etnográfica/Ritos de Fuego. Se celebra en Agosto y Enero (Alborada). Hito tradicional de gran atractivo turístico; destaca su mítica jota leonesa de Riaño, desfiles de pendones leoneses reflejados en el embalse y el ancestral "Antruido" con ritos de fuego de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24131','fiesta','Fiestas del Corpus Christi','Patronal. Se celebra en Junio. Celebración en la llanura del Tuerto con procesiones florales solemnes, torneos deportivos y veladas musicales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24132','fiesta','Fiestas de San Juan y Feria Tradicional de Omaña','Patronal y Feria Etnográfica. Se celebra en Junio y Octubre (Feria). Conserva una importante feria de muestras tradicionales de la comarca de Omaña, con desfiles de ganado, artesanía y folclore local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24133','fiesta','Fiestas de San Blas y de Verano','Patronal. Se celebra en Febrero y Agosto. Pequeños festejos que trasladan el ocio principal al mes estival con comidas populares e hinchables infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24134','fiesta','Fiestas de la Virgen de Celada','Patronal, Tradición Minera e Industrial. Se celebra en Septiembre. Cabecera de la cuenca industrial del Bernesga; sus fiestas destacan por la masiva romería al santuario de Celada, corros de Lucha Leonesa y desfiles populares de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24136','fiesta','Fiestas del Santo Cristo de las Eras','Patronal. Se celebra en Septiembre. Festejos en el Páramo leonés con competiciones tradicionales de pelota a mano, concursos de disfraces y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24137','fiesta','Fiestas de Nuestra Señora de la Asunción y Santa Bárbara','Patronal, Conmemorativa e Industrial/Minera. Se celebra en Agosto y Diciembre. Su gran pasado minero se evoca en torno al Museo de la Siderurgia y la Minería de Castilla y León, con procesiones de antorchas y eventos folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24139','fiesta','Fiestas de San Juan Facundo y Feria de San Simón','Patronal, Taurina y Feria Histórica/ Gastronómica. Se celebra en Junio (San Juan) y Octubre (Feria). Fiesta de Interés Turístico Regional. Destaca por sus históricos y tradicionales encierros de toros al estilo de la villa, sumado al mercado de origen bajomedieval de San Simón, de gran renombre gastronómico por el puerro de Sahagún.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24141','fiesta','Fiestas de la Virgen de la Guía','Patronal. Se celebra en Agosto. Sencillas verbenas de plaza y juegos tradicionales organizados por los vecinos de la comarca del sur leonesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24142','fiesta','Fiestas de San Juan Bautista y Corpus Christi','Patronal y Macro-verbena. Se celebra en Junio. Municipio con gran volumen demográfico colindante con la capital; organiza orquestas nocturnas masivas y conciertos que atraen a miles de jóvenes de toda la periferia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24144','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Bendición tradicional de vehículos y tractores agrícolas acompañada de verbenas populares de plaza y cenas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24145','fiesta','Certamen de Ganado Hispano-Bretón de Babia y Fiestas del Rosario','Feria Sectorial de Élite y Patronal. Se celebra en Agosto y Septiembre. Hito ganadero de gran relevancia nacional en el corazón de Babia; reúne las mejores yeguas y caballos de la raza con muestras de folclore y arrastre de troncos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24146','fiesta','Fiestas de San Jorge y Romería de la Virgen de Nogales','Patronal y Romería Tradicional. Se celebra en Abril y Agosto. Festejos en torno a las ruinas de su histórico monasterio, con procesión folclórica y cantos tradicionales leoneses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24148','fiesta','Fiestas de los Santos Justo y Pastor','Patronal y Jacobea. Se celebra en Agosto. Dada su cercanía a Astorga y su ubicación en el Camino de Santiago, cuenta con una gran concurrencia vecinal y pasacalles animados.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24149','fiesta','Fiestas de San Millán','Patronal. Se celebra en Noviembre y Agosto (fiestas estivales). Actividades lúdicas infantiles orientadas al descanso de familias en la vega del Esla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24151','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos en la ribera del Curueño con campeonatos locales de calva, cartas tradicionales y verbenas de pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24152','fiesta','Fiesta del Patio Maragato y Fiestas de la Virgen del Carmen','Etnográfica/Maragata de Élite y Patronal. Se celebra en Agosto. Hito cultural maragato; rinde homenaje a la arquitectura y folclore tradicionales arrieros, con bailes al son del tamboril y la chifla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24153','fiesta','Fiestas de Santa Cristina','Patronal. Se celebra en Julio. Misa solemne con procesión por las calles de la villa y bailes populares amenizados por charangas de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24154','fiesta','Fiestas de San Jorge y Feria de la Alfarería de Jiménez','Patronal y Feria Artesanal Tradicional. Se celebra en Abril y Mayo (Feria). Su feria de alfarería en Jiménez de Jamuz es un gran hito etnográfico provincial, atrayendo a maestros artesanos del barro y miles de compradores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24155','fiesta','Fiestas de las Candelas y Santiago Apóstol','Patronal. Se celebra en Febrero y Julio. Sencillas verbenas campestres con parrilladas comunitarias de fin de semana en la comarca del Órbigo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24158','fiesta','Fiestas de Santa María','Patronal. Se celebra en Septiembre y Agosto. Festejos rurales centrados en el reencuentro de vecinos con juegos infantiles y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24156','fiesta','Fiestas de San Antonio *','Patronal *. Se celebra en Junio y Agosto *. Actividades familiares organizadas por las asociaciones culturales del pueblo en la llanura de Cea.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24157','fiesta','Fiestas de la Virgen de la Guía y Feria Multisectorial del Páramo','Patronal, Macro-feria Comercial y Taurina. Se celebra en Septiembre. Gran relevancia comarcal; su macro-feria de muestras agrícolas e industriales de origen tradicional reúne a decenas de miles de visitantes en el Páramo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24159','fiesta','Feria del Ajo de Santa Marina y Fiestas del Santo Cristo','Feria Agrícola/Gastronómica de Élite y Patronal. Se celebra en Julio. Hito tradicional de gran prestigio provincial; las vistosas ristras de ajos inundan la villa en un mercado histórico multitudinario con música y catas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24160','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos en la meseta leonesa con tradicionales meriendas campestres, verbenas populares y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24161','fiesta','Fiestas de Santiago Apóstol','Patronal y Tradición Maragata. Se celebra en Julio. Festejos maragatos desarrollados entre sus monumentales casonas de piedra, con procesión al son de la flauta pastoril y el tambor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24162','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Aprovecha su cercanía al área urbana de la capital para organizar grandes verbenas en las noches de verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24163','fiesta','Fiestas de San Juliano','Patronal y Encuentros Culturales. Se celebra en Enero y Julio (fiestas estivales). Municipio residencial periférico con un notable dinamismo juvenil, grandes orquestas de plaza y eventos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24164','fiesta','Fiestas de San Roque','Patronal y de Alta Montaña. Se celebra en Agosto. Festejos tradicionales de la montaña leonesa occidental con exhibiciones lúdicas de Lucha Leonesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24165','fiesta','Fiestas de San Salvador','Patronal. Se celebra en Agosto. Sencillos festejos en el Bierzo occidental junto al río Selmo, con verbenas y meriendas familiares al aire libre.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24166','fiesta','Fiestas de la Virgen del Carmen','Patronal. Se celebra en Julio. Misa procesional solemne, campeonatos locales de cartas tradicionales de mus y bailes en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24167','fiesta','Fiestas de San Joaquín','Patronal. Se celebra en Agosto. Festejos rurales tradicionales en la comarca de Omaña orientados al reencuentro de familiares ausentes). El progreso del listado leonés es impecable y está listo para su cierre. Para proceder de inmediato con el Último Bloque de León (Letras T, U, V, W, X, Y, Z, completando la provincia al 100% con municipios clave como Toral de los Vados, Valencia de Don Juan, Vega de Espinareda, Villablino y Villafranca del Bierzo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24168','fiesta','Fiestas del Santo Cristo de la Vega','Patronal. Se celebra en Septiembre. Festejos en la vega del Esla enmarcados en su histórico palacio de tapial, con juegos populares y verbenas de plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24206','fiesta','Toral en Tren y Fiestas de San Cristóbal','Recreación Histórica/Ferroviaria y Patronal. Se celebra en Junio (Toral en Tren) y Julio. Hito etnográfico notable; todo el pueblo se viste de época para revivir la época dorada del ferrocarril con un viaje en tren de vapor antiguo y mercados tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24169','fiesta','Fiestas de San Juan Bautista','Patronal y Tradición Minera. Se celebra en Junio. Grandes fiestas de la cuenca minera del Sil con hogueras tradicionales, desfiles de peñas y verbenas de gran asistencia comarcal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24170','fiesta','Fiestas de San Roque y Santa Bárbara','Patronal y Tradición Minera. Se celebra en Agosto y Diciembre. Festejos marcados por la identidad minera del Bierzo Alto, con procesiones tradicionales y actividades culturales veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24171','fiesta','Fiestas de San Nicolás','Patronal y Jacobea. Se celebra en Diciembre y Agosto (fiestas estivales). Sencillas celebraciones en el Camino de Santiago Francés a su paso por el valle del Valcarce, integrando a los peregrinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24172','fiesta','Romería de la Virgen del Valle y Fiestas de San Salvador','Romería Etnográfica Alta y Patronal. Se celebra en Septiembre y Agosto. Cabecera de la Cabrera Alta; su romería congrega el folclore folclórico tradicional de pandereta y flauta pastoril de toda la comarca de montaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24173','fiesta','Fiestas del Corpus Christi','Patronal. Se celebra en Junio. Festejos tradicionales de la ribera del Órbigo con competiciones de cartas tradicionales, bolos tradicionales leoneses y orquestas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24174','fiesta','Fiestas de San Cipriano','Patronal. Se celebra en Septiembre. Actos religiosos con pujas por los banzos y juegos infantiles tradicionales en el Páramo leonés.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24185','fiesta','Feria de la Artesanía Textil y Fiestas de la Virgen de la Carballeda','Feria Artesanal Tradicional y Romería Maragata. Se celebra en Septiembre (Feria) y Septiembre (Romería). Hito etnográfico maragato de primer orden; su feria exalta las mantas de lana tradicionales de la arriería con demostraciones folclóricas de chifla y tamboril.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24175','fiesta','Romería de San Froilán (en La Virgen del Camino) y Fiestas de la Sobarriba','Romería y Tradición Comarcal. Se celebra en Octubre y Agosto. Ubicado en la comarca de La Sobarriba; destaca por la masiva aportación de pendones leoneses y carros engalanados a las fiestas patronales tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24176','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Sencillas verbenas estivales basadas en la convivencia comunitaria, comidas vecinales e hinchables infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24177','fiesta','Fiestas de la Virgen de la Collada','Patronal y Romería de Montaña. Se celebra en Septiembre. Festejos en el alto Curueño con tradicionales corros de Lucha Leonesa y muestras de folclore ganadero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24178','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto. Municipio de baja densidad poblacional que se reúne en torno a una merienda comunal estival y orquesta local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24179','fiesta','Fiestas de San Froilán','Patronal y Montañesa. Se celebra en Octubre y Agosto (fiestas de verano). Festejos tradicionales junto al río Curueño con campeonatos locales de calva, cartas tradicionales y música tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24180','fiesta','Fiestas de la Virgen de la Velilla','Patronal y Romería Tradicional. Se celebra en Agosto. Romería tradicional en la meseta leonesa que congrega el fervor de varios pueblos en torno a su ermita arbolada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24181','fiesta','Fiestas del Santo Cristo de la Vera Cruz y Feria de San Antón','Patronal, Histórica y Gastronómica. Se celebra en Septiembre (Cristo) y Enero (Feria). Antigua cuna de las ferias ganaderas del sur de León; destaca por sus monumentales procesiones, encierros camperos tradicionales y su renombrado bacalao al estilo de Valderas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24182','fiesta','Romería del Castro y Fiestas del Cristo','Romería Etnográfica y Patronal. Se celebra en Mayo y Agosto. Festejos en la comarca de la Sequeda que mantienen vivas las procesiones tradicionales con pendones leoneses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24183','fiesta','Romería de la Virgen de la Velilla','Romería y Tradición Serrana. Se celebra en Agosto. Hito religioso notable en la montaña oriental; destaca la espectacular procesión folclórica hacia el santuario mariano con bailes de jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24184','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeñas verbenas que congregan a las familias en torno a actividades lúdicas tradicionales en la comarca de Omaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24188','fiesta','Fiestas de Nuestra Señora del Castillo y San Roque y Mercado Medieval','Patronal, Feria Comercial/Gastronómica y Recreación Histórica. Se celebra en Septiembre (Patronal) y Julio (Mercado). Fiesta de Interés Turístico Regional. Su mercado medieval en el impresionante castillo gótico-antiguo y sus populosas fiestas estivales atraen a decenas de miles de personas de todo el norte español.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24189','fiesta','Romería de San Froilán (en La Virgen del Camino)','Romería Etnográfica de Élite y Patronal. Se celebra en Octubre. Fiesta de Interés Turístico Regional. Epicentro de la mayor romería de la provincia; el santuario de la Virgen del Camino recibe a miles de romeros, carros engalanados, desfiles de pendones leoneses y venta tradicional de avellanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24190','fiesta','Fiestas de San Mamés','Patronal. Se celebra en Agosto. Sencilla reunión vecinal con misa solemne, juegos populares infantiles y baile en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24193','fiesta','Muestra de Gallos de Pluma y Fiestas de San Roque','Feria Sectorial/Etnográfica Única y Patronal. Se celebra en Marzo (Muestra) y Agosto. Hito etnográfico singular; su feria exalta la cría tradicional de los gallos de León de pluma para pesca, única en el mundo, atrayendo turismo internacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24196','fiesta','Fiestas del Carmen y San Roque','Patronal y Fluvial. Se celebra en Julio. Grandes fiestas del Bierzo en torno a su enorme playa fluvial junto al monasterio de San Andrés, con orquestas de primer nivel y eventos deportivos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24197','fiesta','Fiestas de Santa María','Patronal. Se celebra en Agosto *. Mucha animación vecinal y verbenas gracias a su cercanía al nudo viario del área metropolitana de León.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24198','fiesta','Fiestas de la Virgen de la Magdalena','Patronal y Jacobea. Se celebra en Julio. Festejos marcados por el Camino de Santiago Francés antes de la subida a O Cebreiro, con comidas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24194','fiesta','Feria de la Cecina de Chivo y Fiestas de Santa Gutiérrez','Gastronómica de Élite y Patronal. Se celebra en Noviembre (Feria) y Agosto. Fiesta de Interés Turístico Regional. Su feria de la cecina de chivo de Vegacervera congrega a miles de personas para degustar este embutido tradicional de montaña único.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24199','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos tradicionales de la montaña central con campeonatos de bolos tradicionales leoneses y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24201','fiesta','Fiestas de Santiago Apóstol y Virgen del Rosario','Patronal y Romería Tradicional. Se celebra en Julio y Octubre. Festejos en la ribera del Porma que destacan por la reunión vecinal y desfiles de pendones leoneses locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24202','fiesta','Fiestas de San Roque (Festejos de Laciana) y El Ferandón','Patronal, Ganadera y Etnográfica/Tradición Patsueza. Se celebra en Agosto. Cabecera de la comarca de Laciana; rinde honores a la cultura pastoril e histórica minera, con corros de Lucha Leonesa y música tradicional en habla patsueza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24203','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Sencillas veladas musicales organizadas por los vecinos con juegos tradicionales de cartas de mus.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24205','fiesta','Fiestas de Santiago Apóstol (Batalla de Villadangos)','Patronal, Jacobea y Recreación Histórica. Se celebra en Julio. Festejos del Camino de Santiago que incorporan mercados tradicionales medievales evocando la histórica batalla del año 1111.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24207','fiesta','Fiestas del Señor y Feria de la Patata','Patronal y Agrícola/Gastronómica Comarcal. Se celebra en Junio y Octubre (Feria). Festejos tradicionales de la vega del Esla que defienden los productos de la huerta leonesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24209','fiesta','Fiestas del Santo Cristo de la Esperanza y Fiesta de la Poesía','Patronal, Jacobea de Élite y Literaria/Cultural. Se celebra en Septiembre (Cristo) y Junio (Poesía). Fiesta de Interés Turístico Regional. Sede histórica del Camino de Santiago; destaca el desfile tradicional de "Los Gigantes", las danzas folclóricas de paloteo y su prestigioso certamen poético nacional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24210','fiesta','Fiestas de San Juan Bautista (en Brañuelas)','Patronal y Tradición Ferroviaria. Se celebra en Junio. Festejos en el puerto de Manzanal que evocan su pasado ferroviario con comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24211','fiesta','Fiestas de San Blas','Patronal. Se celebra en Febrero y Agosto (fiestas estivales). Actividades lúdicas tradicionales infantiles orientadas al descanso de familias veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24901','fiesta','Fiestas de San Juan y de la Montaña Central','Patronal y de Alta Montaña. Se celebra en Junio y Agosto. Festejos de montaña en el paso de Pajares, con tradicionales corros de Lucha Leonesa y jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24212','fiesta','Fiestas del Salvador y Feria del Vino de la Tierra','Patronal y Enológica Comarcal. Se celebra en Septiembre y Agosto (Feria). Festejos de la zona sur con gran protagonismo de las peñas en las bodegas excavadas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24213','fiesta','Fiestas de San Blas','Patronal. Se celebra en Febrero y Agosto. Sencillos festejos veraniegos con bailes de plaza y parrilladas organizadas por los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24214','fiesta','Fiestas de la Virgen del Carmen','Patronal y Tradición de la Cepeda. Se celebra en Julio. Festejos rurales tradicionales del valle de Magaz con campeonatos de bolos tradicionales leoneses.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24215','fiesta','Fiestas del Santo Cristo Mártir','Patronal. Se celebra en Septiembre. Misa solemne cantada, campeonatos locales de cartas tradicionales de mus y veladas musicales en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24216','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos de la Valduerna basados en el folclore castellano-leonés de dulzaina y comidas compartidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24217','fiesta','Fiestas de San Esteban','Patronal. Se celebra en Agosto. Sencilla reunión de carácter vecinal estructurada en torno a juegos populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24218','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Veladas musicales de fin de semana y actividades para niños organizadas por la asociación cultural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24222','fiesta','Fiestas de San Juan y del Emigrante','Patronal y Macro-verbena. Se celebra en Junio y Agosto. Gran volumen demográfico adosado a la capital; sus orquestas de plaza nocturnas atraen masivamente a la juventud de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24223','fiesta','Fiestas de San Juan y la Feria del Hacha (en Veguellina)','Patronal, Industrial y Feria de Muestras. Se celebra en Junio y Julio. Hito relevante en el Órbigo presidido por Veguellina; sus ferias de muestras agrarias tradicionales y conciertos son muy populosos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24224','fiesta','Fiestas de San Antonio','Patronal y Jacobea. Se celebra en Junio. Ubicado en el trazado del Camino de Santiago, cuenta con pasacalles y parrilladas comunitarias de fin de semana.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24225','fiesta','Fiestas del Santo Cristo y de Lancia','Patronal e Histórico-Arqueológica. Se celebra en Septiembre. Festejos vinculados culturalmente a las ruinas de la ciudad astur-romana de Lancia, con eventos folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24226','fiesta','Fiestas de San Facundo','Patronal. Se celebra en Noviembre y Agosto (fiestas estivales). Sencillas verbenas campestres orientadas a la convivencia de familias de la comarca de Cea.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24227','fiesta','Fiestas de la Virgen del Rosario','Patronal y Tradición de la Sobarriba. Se celebra en Octubre y Agosto. Festejos tradicionales marcados por las exhibiciones de Lucha Leonesa y desfiles de pendones leoneses locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24228','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Misa solemne con procesión por la llanura del Órbigo y bailes de plaza con orquestas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24229','fiesta','Fiestas de San Santiago Apóstol','Patronal. Se celebra en Julio. Pequeña festividad vecinal basada en meriendas populares y juegos autóctonos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24230','fiesta','Fiestas del Santo Cristo de la Aldea','Patronal. Se celebra en Septiembre. Festejos en el Páramo leonés con tradicionales competiciones de pelota a mano y veladas musicales nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34025','fiesta','Fiesta de San Sebastián y Virgen de las Victorias','Patronal y Etnográfica. Se celebra en Enero y Septiembre. Celebración de arraigo estrictamente local con procesión tradicional, refresco vecinal y verbena en el teleclub durante el retorno estival.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90803','fiesta','Fiesta de San Juan Bautista y Santa Ana','Patronal. Se celebra en Junio y Julio. Festejos típicamente locales con hoguera de San Juan, campeonato de bolos populares, misa cantada y orquestas dirigidas a la población flotante del verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35001','fiesta','Fiestas de San Juan Bautista y la Virgen de Llano','Patronal, Histórica y Gastronómica. Se celebra en Junio y Septiembre. Festividad de Interés Turístico Regional con gran empaque norteño, desfile de carrozas, concentración de peñas, y ferias gastronómicas ligadas a su potente industria galletera.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90238','fiesta','Fiesta de la Virgen del Carmen y Descenso Internacional del Pisuerga','Deportiva, Etnográfica y Patronal. Se celebra en Agosto. Hito regional masivo que fusiona la competición piragüística internacional con el desfile de las rústicas "canoas de plástico" y folklore castellano a orillas del Canal de Castilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90239','fiesta','Fiestas de Nuestra Señora del Cortijo','Patronal. Se celebra en Septiembre. Celebración tradicional en la comarca del Cerrato centrada en la misa solemne en la ermita, meriendas de bodegas y bailes públicos de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90804','fiesta','Fiesta de San Vicente','Patronal. Se celebra en Enero. Pequeña festividad invernal de carácter vecinal limitada a los actos litúrgicos, aperitivo comunitario y dinamización cultural de baja escala.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90240','fiesta','Fiestas de San Miguel Arcángel y Nuestra Señora de Alconada','Patronal y Mercado Histórico. Se celebra en Septiembre. Hito comarcal de relevancia con encierros urbanos tradicionales, feria barroca en su conjunto histórico porticado y afluencia masiva desde la capital provincial.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90241','fiesta','Fiesta de San Pedro y Nuestra Señora de las Fuentes','Patronal y Etnográfica. Se celebra en Junio y Septiembre. Arraigo local con la tradicional romería a la ermita románica de Nuestra Señora de las Fuentes, acompañamiento de dulzaineros y meriendas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90805','fiesta','Fiesta de la Virgen de Garón','Romería y Patronal. Se celebra en Septiembre. Romería típica de retorno veraniego que reúne a los descendientes del pueblo en el santuario forestal de Garón con jotas castellanas y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34015','fiesta','Fiestas de San Facundo y San Primitivo','Patronal. Se celebra en Noviembre. Festejos invernales adaptados a la baja demografía, enfocados en los actos religiosos tradicionales y una cena comunitaria para los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34017','fiesta','Fiestas de la Santa Cruz','Patronal y Taurina. Se celebra en Septiembre. Celebración con gran arraigo comarcal famosa por sus tradicionales encierros camperos y urbanos, desfile de peñas locales por su entramado medieval y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34018','fiesta','Fiesta de la Virgen de la Cueva','Romería y Patronal. Se celebra en Mayo. Destaca por su procesión hasta el mirador de Tierra de Campos, degustación de productos de la zona y meriendas en los tradicionales lagares y bodegas excavadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34019','fiesta','Fiestas de San Eutropio','Patronal. Se celebra en Abril. Celebración primaveral de carácter vecinal con misa cantada, campeonatos de cartas, juegos infantiles en la plaza y baile nocturno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34020','fiesta','Fiesta de las Siete Doncellas','Etnográfica y Romería. Se celebra en Mayo. Singular romería basada en la leyenda local, con procesión, canto de letanías tradicionales y un fuerte componente de reunión comunitaria de la comarca de Saldaña.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34022','fiesta','Fiestas de Nuestra Señora de Revilla','Patronal, Enológica y Taurina. Se celebra en Septiembre. Capital del Cerrato que destaca por sus procesiones con danzantes folclóricos, encierros taurinos y la masiva apertura de su histórico barrio de bodegas subterráneas del cerro del Castillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34024','fiesta','Fiesta de San Esteban','Patronal. Se celebra en Agosto. Festejos mínimos de verano organizados para la población estival con juegos tradicionales para niños, campeonato de tusa y verbena modesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34025','fiesta','Fiesta de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración veraniega con misa solemne, procesión por el casco urbano a orillas del río Valdavia y orquesta nocturna en la plaza principal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34027','fiesta','Festividad de Santa Bárbara y Santo Tomás','Etnográfica, Minera y Patronal. Se celebra en Diciembre y Julio. Gran arraigo identitario ligado al pasado minero del carbón, destacando la procesión nocturna con lámparas de mina, ofrenda floral a los caídos y manifestaciones folclóricas de la Montaña Palentina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34028','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Verbena y juegos populares organizados en el valle del Boedo coincidiendo con las vacaciones de los emigrantes locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34029','fiesta','Fiestas de San Isidro Labrador y San Pedro','Patronal y Cultural. Se celebra en Mayo y Junio. Relevancia comarcal por la bendición de campos, desfiles folclóricos, conciertos en el entorno monumental de San Pedro Cultural y actos ecuestres tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34031','fiesta','Fiesta de San Antonio','Patronal. Se celebra en Junio. Pequeña celebración bajo la silueta de su emblemática torre del homenaje, centrada en la misa, procesión del santo y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34032','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Celebración en este enclave palentino rodeado de territorio cántabro, con hoguera tradicional, dianas floreadas y parrillada para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34033','fiesta','Fiesta de San Pedro Advíncula','Patronal. Se celebra en Agosto. Festejos veraniegos enfocados en el reencuentro de familias nativas con competiciones de cartas, juegos infantiles y baile de sociedad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34035','fiesta','Fiestas de la Virgen del Amparo','Patronal. Se celebra en Mayo. Procesión religiosa con cantos tradicionales marianos, seguida por comidas de hermandad y campeonatos de bolos masculinos y femeninos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34034','fiesta','Fiestas de San Pedro Apóstol','Patronal y Jacobea. Se celebra en Junio. Festividad dinamizada por su ubicación estratégica en el Camino de Santiago, con danzas folclóricas junto al famoso rollo jurisdiccional gótico y acogida especial a peregrinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34036','fiesta','Acto de Exaltación del Fuero de Brañosera y Fiesta de San Roque','Histórica y Patronal. Se celebra en Octubre y Agosto. Hito político-histórico de gran relevancia que conmemora el nacimiento del primer ayuntamiento de España en el año 824, atrayendo a autoridades regionales y recreando estampas medievales montañesas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34037','fiesta','Fiestas de la Virgen de los Remedios y San Justo y Pastor *','Patronal *. Se celebra en Agosto y Septiembre *. Festejos tradicionales del valle de la Valdavia con campeonatos de pelota mano, desfile de disfraces infantiles y verbenas nocturnas multitudinarias en verano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34038','fiesta','Fiesta de San Quirico','Patronal. Se celebra en Junio. Celebración agraria tradicional local con misa de acción de gracias, pasacalles con dulzaina y tamboril, y actividades recreativas en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34039','fiesta','Fiesta de San Andrés','Patronal. Se celebra en Noviembre. Festejos de invierno reducidos al ámbito vecinal con oficios religiosos, campeonatos de mus y una merienda popular a base de productos de la matanza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34041','fiesta','Fiestas de la Virgen de las Candelas y San Esteban','Patronal. Se celebra en Febrero y Agosto. Festejos estivales con procesión, campeonatos de cartas en el bar local, atracciones infantiles y una verbena nocturna orientada al turismo familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34042','fiesta','Fiestas de Santiago Apóstol y la Virgen de la Asunción','Patronal y Jacobea. Se celebra en Julio y Agosto. Celebración con arraigo en la ruta jacobea que destaca por la procesión de Santiago, danzas típicas castellanas acompañadas por dulzaineros y degustación de pastas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34045','fiesta','Fiesta de San Agustín','Patronal. Se celebra en Agosto. Celebración estival de carácter local centrada en la misa solemne, juegos populares infantiles y una cena de hermandad en los entornos del Canal de Castilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34046','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos vecinales mínimos adaptados a la baja demografía, con encendido de la hoguera, aperitivo comunitario en el ayuntamiento y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34048','fiesta','Fiesta de la Virgen de la O','Patronal. Se celebra en Septiembre. Pequeña festividad local de Tierra de Campos con misa, procesión de la patrona, campeonatos de tusa y un baile con orquesta en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34049','fiesta','Fiesta de Santa Águeda','Patronal y Etnográfica. Se celebra en Febrero. Tradicional celebración en la Montaña Palentina donde las mujeres toman el bastón de mando, vistiendo trajes regionales y repartiendo las típicas rosquillas de la santa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34050','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio. Celebración rural con procesión del santo, reparto de panecillos bendecidos, juegos para niños y meriendas vecinales en el entorno de los lagares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34051','fiesta','Fiesta de la Virgen de la Paz','Patronal. Se celebra en Enero y Agosto. Destaca la celebración de retorno estival con verbenas, campeonatos de bolos y chosco, aprovechando la fisonomía de su villa de origen medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34052','fiesta','Fiestas de la Virgen del Camino y San Quirico','Patronal. Se celebra en Junio y Septiembre. Festejos locales que reúnen a la cuenca del Valdavia, con meriendas populares junto al río, jotas castellanas y verbenas con orquesta en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34053','fiesta','Fiesta de la Virgen de la Reina de los Ángeles','Patronal. Se celebra en Septiembre. Tradicional romería y procesión, acompañada de repique de campanas manual, encierro infantil y el tradicional refresco a base de escabeche y vino de la zona.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34055','fiesta','Fiestas de San Miguel Arcángel y San Roque','Patronal e Histórica. Se celebra en Mayo y Agosto. Arraigo local e histórico ligado a la figura de Juan de San Martín, con desfiles folclóricos, verbenas nocturnas populosas y suelta de vaquillas en el coso portátil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34057','fiesta','Fiestas de San Martín y la Virgen de Palacios','Patronal y Enológica. Se celebra en Noviembre y Septiembre. Destacan los festejos de septiembre por las meriendas populares y apertura de sus singulares bodegas subterráneas escalonadas en la ladera del cerro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34058','fiesta','Fiestas de la Virgen de la Paz y San Jacinto','Patronal. Se celebra en Agosto. Festejos veraniegos muy animados por peñas locales, con encierro de carretones, caldereta popular en el pinar y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34059','fiesta','Fiesta de la Virgen del Castillo','Patronal y Etnográfica. Se celebra en Septiembre. Destaca a nivel provincial por la espectacular Danza de los Danzantes y el Chiborra, personaje satírico tradicional que recita versos populares vestido con llamativos colores.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34060','fiesta','Fiestas de San Román','Patronal. Se celebra en Octubre. Festejos de otoño con misa, subasta de banzos de la procesión, campeonatos de mus en las tabernas y orquesta musical para los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34061','fiesta','Fiesta de Santa Lucía','Patronal. Se celebra en Agosto. Festejos estivales para el reencuentro de la población emigrada con juegos tradicionales, chocolatada popular y música en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34062','fiesta','Fiesta de la Virgen de los Pastores','Romería y Patronal. Se celebra en Agosto. Romería típica del valle del Valdavia con procesión, bendición de vehículos, competiciones de tusa y verbenas populares veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34063','fiesta','Fiesta de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos junto al río Pisuerga orientados al veraneante familiar, con procesión, parrillada popular y música disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34066','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Tradicionales meriendas en las bodegas del pueblo, acompañadas de pasacalles, campeonatos de bolos femeninos y orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34067','fiesta','Fiesta de San Pelayo','Patronal. Se celebra en Junio. Pequeñas fiestas de la Montaña Palentina rodeadas de robledales, con actos litúrgicos, barbacoa vecinal y campeonatos de juegos de mesa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34068','fiesta','Fiesta de San Martín','Patronal. Se celebra en Noviembre. Celebración invernal de carácter estrictamente familiar centrada en los oficios religiosos y un almuerzo comunitario a base de embutidos locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34069','fiesta','Fiestas de San Isidro y Fiestas de Botijero','Patronal, Taurina y Etnográfica. Se celebra en Mayo y Agosto. Importante relevancia comarcal en la villa episcopal; destaca por sus encierros tradicionales por el casco histórico, desfile masivo de peñas y meriendas en su enorme entramado de bodegas subterráneas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34070','fiesta','Fiesta de San Millán','Patronal. Se celebra en Noviembre. Fiestas tradicionales agrarias con misa cantada, procesión por las calles de trazado medieval, campeonatos de cartas y orquesta invernal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34071','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos típicamente veraniegos con gran participación de la juventud en el parque local, pasacalles de dulzaina, disfraces y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34072','fiesta','Fiestas de la Virgen del Milagro','Patronal y Etnográfica. Se celebra en Mayo. Celebración de Tierra de Campos que destaca por la rogativa tradicional a la virgen, el canto de salves, tiro al plato y meriendas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34073','fiesta','Fiesta de San Juan Bautista','Patronal. Se celebra en Junio *. Pequeños festejos rurales en la comarca de Guardo con encendido de la gran pira de San Juan, juegos infantiles y baile popular en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34074','fiesta','Fiesta de San Telmo y Fiesta de Santiago Apóstol','Patronal, Religiosa y Jacobea. Se celebra en Abril y Julio. Destaca la procesión de "El Ole", hito etnográfico único donde los vecinos avanzan bailando y cantando con bastones mientras se vitorea al santo en un ambiente de gran fervor y arraigo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34076','fiesta','Fiestas de San Agustín','Patronal y Taurina. Se celebra en Agosto. Gran afluencia comarcal motivada por sus tradicionales encierros de reses bravas por las calles, actividades culturales ligadas al entorno de la Laguna de la Nava y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34077','fiesta','Fiestas de Nuestra Señora de la Antigua','Patronal e Histórica. Se celebra en Septiembre. Celebración singular que aprovecha el marco monumental de su rehabilitado castillo medieval para albergar conciertos, mercados de artesanía y desfiles folclóricos de peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34079','fiesta','Fiestas de la Virgen de los Ángeles y San Isidro','Patronal, Gastronómica y Deportiva. Se celebra en Agosto y Mayo. Festejos de gran concurrencia debido a su cercanía a la capital, destacando sus encierros taurinos, la feria del pan artesano grijotano y actividades náuticas en el Canal de Castilla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34080','fiesta','Fiestas de San Antonio de Padua y Certamen de la Exaltación del Fuero de Guardo','Patronal, Etnográfica y Minera. Se celebra en Junio. Fiesta de Interés Turístico Regional que congrega a miles de personas en la Montaña Palentina, caracterizada por la vistosa procesión con alfombras florales, el desfile de carrozas tradicionales y el folclore minero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34081','fiesta','Fiestas del Santo Cristo de la Aceña','Patronal y Romería. Se celebra en Septiembre. Tradicional traslado del Cristo a la iglesia parroquial, seguido de campeonatos de bolos y tusa, comidas populares y orquesta nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34083','fiesta','Festival Nacional de la Exaltación del Cangrejo de Río','Gastronómica, Etnográfica y Recreación Histórica. Se celebra en Agosto. Fiesta de Interés Turístico Regional de enorme impacto; incluye un gran desfile de carrozas con motivos fluviales, la comida oficial del cangrejo y la quema de la "Falla del Cangrejo" ante miles de visitantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34088','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal y Deportiva. Se celebra en Agosto. Festejos con notable afluencia por su proximidad al río Carrión, ofreciendo piragüismo popular, verbenas multitudinarias en la plaza y una gran caldereta vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34089','fiesta','Fiestas de la Virgen de la Piedad','Patronal y Jacobea. Se celebra en Septiembre. Celebración en la entrada palentina del Camino de Santiago, famosa por su procesión, la tradicional merienda en los lagares y bailes tradicionales con agrupaciones de dulzaineros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34091','fiesta','Fiesta de San Pedro','Patronal. Se celebra en Junio. Festejos tradicionales locales en el valle del Valdavia con campeonatos de cartas, hinchables infantiles y baile nocturno de carácter familiar.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34092','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal y Deportiva. Se celebra en Agosto. Gran animación estival con competiciones deportivas en el polideportivo municipal, desfile de disfraces organizados por peñas locales y verbenas con orquestas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34094','fiesta','Fiesta de Santiago Apóstol','Patronal y Jacobea. Se celebra en Julio. Festividad marcada por el paso de peregrinos jacobeos, incluyendo misa cantada, aperitivo comunitario y bailes con disco-móvil en el centro del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34903','fiesta','Fiesta de la Virgen de Renedo','Romería y Patronal. Se celebra en Septiembre. Romería comarcal que reúne a los pueblos de la zona de Ucieza en la ermita de la Virgen, con danzas tradicionales y meriendas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90242','fiesta','Fiesta de San Cristóbal','Patronal. Se celebra en Julio. Celebración en Tierra de Campos enfocada en la bendición tradicional de vehículos y un almuerzo de hermandad para los vecinos y veraneantes.','inventario_fiestas_pdf');
