INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37025','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto (Verano). Celebración en pleno Campo Charro que destaca por sus encierros tradicionales, capeas de vaquillas, exhibición de folclore con gaita y tamboril, y meriendas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37026','fiesta','Fiestas del Santo Cristo de la Laguna','Patronal y Romería. Se celebra en Mayo y Septiembre. Romería tradicional hasta la ermita situada junto a la laguna, con la subasta de banzos, bendición de campos, jotas salmantinas y posterior caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37027','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festejos estivales a orillas del río Tormes potenciados por talleres medioambientales, descensos lúdicos en piragua, comidas comunitarias y orquestas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37028','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos veraniegos condicionados por el entorno de su monumental presa hidráulica, enfocados en el turismo familiar con juegos tradicionales y verbenas de pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37029','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Celebración rural orientada al retorno estival con misa cantada, campeonato de calva y bolos charros, seguidos de una parrillada de hermandad para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37030','fiesta','Fiestas de la Santa Cruz','Patronal. Se celebra en Mayo y Agosto. Festejos en la comarca de Ledesma con procesión tradicional, pasacalles de dulzaineros, competiciones de cartas en el teleclub y bailes nocturnos con discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37031','fiesta','Fiestas del Santo Cristo de Hornillos','Patronal y Romería. Se celebra en Octubre y Mayo. Gran arraigo comarcal en Las Villas por la multitudinaria romería al santuario del Cristo, con procesiones multitudinarias, subastas, bailes regionales charros y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37032','fiesta','Fiestas de San Fabián y San Sebastián','Patronal e Histórica. Se celebra en Enero y Julio. Destaca su vinculación con la Batalla de los Arapiles de 1812, organizando jornadas de recreación histórica napoleónica, desfiles con uniformes de época y rutas culturales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37033','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre. Festejos tradicionales de La Armuña centrados en la misa solemne, encierro infantil de carretones, campeonatos de mus y baile público con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37034','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Pequeños festejos rurales adaptados a la baja demografía local, limitados a los actos litúrgicos marianos, juegos de cartas tradicionales y un refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37035','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos estivales muy animados por la población flotante, caracterizados por campeonatos deportivos en el colegio local, comidas populares y bailes nocturnos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37037','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Mayo. Pequeña celebración en la comarca de Ciudad Rodrigo centrada en la procesión del santo, aperitivo comunitario en las escuelas y música grabada para los residentes). [1] ¿Puedo continuar con el siguiente bloque de la provincia de Salamanca?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37038','fiesta','Fiestas de San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Gran relevancia en la comarca de Las Villas; destaca por sus concurridos encierros urbanos de reses bravas, capeas en su plaza fija, desfile masivo de peñas y la tradicional paellada comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37042','fiesta','Fiestas de Santa María Magdalena','Patronal. Se celebra en Julio. Festejos de escala estrictamente local adaptados a la baja demografía, con misa cantada, campeonato de tusa y merienda vecinal para los residentes estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37044','fiesta','Fiestas del Cristo de las Mercedes y Feria de San Felipe','Patronal, Taurina y Ganadera. Se celebra en Septiembre y Mayo. Hito comarcal en Arribes del Duero; sus fiestas del Cristo destacan por los encierros a caballo, capeas urbanas tradicionales y la ancestral Feria Agroganadera de San Felipe.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37045','fiesta','Fiestas de San Sebastián y de la Virgen de la Asunción','Patronal y Romería. Se celebra en Enero y Agosto. Celebración tradicional en la Sierra de Francia con la subasta de banzos de la virgen, bailes de jotas tradicionales y meriendas populares de peñas en los pinares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37046','fiesta','Fiestas de la Virgen del Castañar y Procesión del Corpus Christi (Los Hombres de Musgo)','Patronal, Histórica y Taurina. Se celebra en Septiembre y Junio. Su procesión del Corpus Christi es Fiesta de Interés Turístico Nacional por los singulares "Hombres de Musgo" que recrean la reconquista de la ciudad; las fiestas de septiembre incluyen festejos taurinos en la plaza más antigua de España, "La Ancianita".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37047','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo. Celebración de carácter vecinal a orillas del río Alhandiga, con misa solemne, campeonato de calva y bolos charros, seguidos de una cena popular en el centro social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37049','fiesta','Fiestas de Santa María Magdalena','Patronal y Etnográfica. Se celebra en Julio. Festejos en el Parque Natural de Arribes del Duero, caracterizados por pasacalles tradicionales con gaita y tamboril, tiro al plato y verbenas dirigidas a la población flotante.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37050','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Taurina. Se celebra en Septiembre. Festejos en el Campo Charro con encierro de carretones infantiles, capea tradicional de vaquillas en el coso del pueblo, chocolatada comunitaria y bailes de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37051','fiesta','Fiestas de la Visitación de la Virgen y San Roque','Patronal. Se celebra en Julio y Agosto. Festejos veraniegos que dinamizan la comarca de Guijuelo con competiciones deportivas para jóvenes, comidas vecinales de hermandad y música disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37052','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto (Verano). Celebración estival de retorno con encierros tradicionales urbanos, capeas populares de reses bravas en plaza portátil, charangas y verbenas con orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37054','fiesta','Fiestas de la Santa Cruz','Patronal y Taurina. Se celebra en Mayo y Agosto (Verano). Festejos en la comarca de Ciudad Rodrigo célebres por sus encierros a caballo tradicionales por el campo, capeas de vaquillas, bailes folclóricos charros y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37055','fiesta','Fiestas de San Juan Bautista','Patronal y Taurina. Se celebra en Junio. Festejos en la comarca de Vitigudino que destacan por sus tradicionales encierros urbanos, capeas de vaquillas, desfile de peñas locales y bailes con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37056','fiesta','Fiestas del Santo Cristo de la Salud','Patronal y Fronteriza. Se celebra en Agosto. Pequeña festividad en la raya con Portugal condicionada por el retorno estival; incluye misa, procesión del Cristo, campeonatos de cartas y verbenas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37058','fiesta','Fiestas de San Jaime (Santiago Apóstol)','Patronal. Se celebra en Julio. Festejos de carácter vecinal en la comarca de Vitigudino centrados en los actos religiosos, juegos infantiles tradicionales, caldereta popular y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37059','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Romería. Se celebra en Septiembre. Tradicional romería en el Campo Charro con procesión religiosa, subasta de banzos, bailes de jotas al son del tamboril y meriendas de hermandad en los encinares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37060','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos veraniegos que aprovechan la cercanía a la capital para albergar competiciones deportivas, parrillada popular comunitaria y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37061','fiesta','Fiestas de la Virgen del Rosario y San Juan Bautista','Patronal y Etnográfica. Se celebra en Agosto y Junio. Notable afluencia en la Sierra de Francia potenciada por su cercanía a la Peña de Francia, ofreciendo vistosos ofertorios tradicionales con trajes charros y peñas animadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37062','fiesta','Fiestas de Nuestra Señora del Castillo','Patronal. Se celebra en Agosto. Festejos de La Armuña enfocados en el reencuentro familiar estival, con misa solemne, campeonato de calva y bolos castellanos, y baile público con discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37065','fiesta','Fiestas de San Pedro Apóstol y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Junio y Octubre. Festejos en las Arribes del Duero que destacan por sus pasacalles tradicionales con gaita y tamboril, carreras de cintas a caballo, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37067','fiesta','Fiestas del Señor (Corpus Christi) y San Vicente','Patronal y Cultural. Se celebra en Junio y Enero. Relevancia comarcal por su condición de gran municipio dormitorio de la capital, atrayendo a miles de jóvenes a sus macroverbenas, desfiles de peñas y actividades a orillas del Tormes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37069','fiesta','Fiestas de la Virgen de la Peña y San Juan','Patronal y Taurina. Se celebra en Octubre y Junio. Gran animación estival por su cercanía a Salamanca, caracterizada por encierros de reses bravas por las calles, concurso de paellas, juegos infantiles y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37070','fiesta','Fiestas de la Virgen de la Peña y San Pedro','Patronal. Se celebra en Mayo y Junio. Festejos muy concurridos que aprovechan el entorno histórico de los Arapiles, ofreciendo desfiles de peñas locales, verbenas multitudinarias y caldereta popular). [1] ¿Puedo continuar con el siguiente bloque de la provincia de Salamanca?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37072','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal y Taurina. Se celebra en Junio y Octubre. Festejos de arraigo en el Campo Charro con tradicionales capeas de vaquillas, pasacalles al son del tamboril, campeonatos de calva y comidas populares entre peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37071','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Jacobea. Se celebra en Agosto. Festejos marcados por el paso de la Vía de la Plata con misa solemne, procesión por su trama rústica empedrada, juegos tradicionales para veraneantes y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37073','fiesta','Fiestas de Santa Elena','Patronal y Etnográfica. Se celebra en Agosto. Gran animación en la comarca de La Armuña, destacando por las tradicionales carreras de cintas a caballo, desfiles humorísticos de disfraces, grandes verbenas y paellada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37074','fiesta','Fiestas de San Antonio de Padua','Patronal y Taurina. Se celebra en Junio. Celebración en la comarca de Ciudad Rodrigo célebre por sus encierros tradicionales urbanos, suelta de vaquillas en el coso rústico, charangas y cenas populares de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37077','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos de retorno familiar estival centrados en los actos religiosos, competiciones de bolos castellanos, juegos infantiles en la plaza y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37001','fiesta','Fiestas de Santa Ana y Día de la Boda Típica Candelariense','Etnográfica, Patronal y Gastronómica. Se celebra en Julio y Agosto. Fiesta de Interés Turístico Regional por la espectacular recreación de la Boda Típica, donde los vecinos visten los monumentales e históricos trajes de choricero y candelariense por sus calles con regaderas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37079','fiesta','Fiestas de San Vicente y la Virgen del Rosario','Patronal. Se celebra en Enero y Octubre. Pequeña celebración rural en el Campo de Salamanca adaptada a la baja demografía, con oficios litúrgicos tradicionales, campeonatos de mus y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37080','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Festejos veraniegos en la comarca de Béjar rodeados de castañares, caracterizados por marchas de senderismo, parrillada popular comunitaria y bailes públicos de orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37081','fiesta','Fiestas de la Virgen de la Misericordia y San Jaime','Patronal y Taurina. Se celebra en Agosto y Julio. Relevancia comarcal por sus tradicionales, históricos y peligrosos encierros urbanos de reses bravas por su recinto porticado, multitudinarias capeas, peñas musicales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37082','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Festejos de gran arraigo en la comarca de Guijuelo y Las Villas, famosos por sus tradicionales encierros camperos a caballo, novilladas, concurso de carrozas y verbenas multitudinarias.','inventario_fiestas_pdf');
