INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37085','fiesta','Fiestas de San Roque y Nuestra Señora de la Asunción','Patronal y Cultural. Se celebra en Agosto. Hito en el área metropolitana por su gran explosión demográfica; atrae masivamente a la juventud de la capital con sus potentes conciertos, desfiles de peñas y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37086','fiesta','Fiestas de San Isidro Labrador','Patronal y Taurina. Se celebra en Mayo. Festejos tradicionales del Campo de Argañán con encierros de carretones, suelta de vaquillas para los mozos de la comarca, procesión con bendición de campos y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37087','fiesta','Fiestas de San Roque','Patronal y Deportiva. Se celebra en Agosto. Festejos condicionados por el crecimiento de sus urbanizaciones cercanas a la capital, con torneos de golf populares, paellada comunitaria y animadas disco-móviles nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37088','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Celebración en pleno Campo Charro rural centrada en la misa cantada, la hoguera de San Juan, campeonatos de tusa en la taberna y una cena vecinal para los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37089','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto (Verano). Festejos estivales organizados para la población flotante con campeonatos de cartas en las antiguas escuelas, juegos tradicionales infantiles y parrillada de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37090','fiesta','Fiestas de la Virgen del Triunfo','Patronal y Etnográfica. Se celebra en Agosto. Vistosos festejos en la Sierra de Francia con la celebración del ofertorio tradicional, donde los vecinos lucen ricos trajes serranos bordados, danzas de jotas y pasacalles.','inventario_fiestas_pdf');
