INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37185','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal. Se celebra en Junio y Octubre. Festejos tradicionales de La Armuña con procesiones religiosas, competiciones de calva, campeonatos de cartas en el teleclub y bailes populares con disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37096','fiesta','Fiestas de San Juan Bautista','Patronal y Taurina. Se celebra en Junio. Celebración en la comarca de Ciudad Rodrigo con encierros a caballo camperos tradicionales, suelta de vaquillas, meriendas populares en el campo y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37097','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña festividad vecinal en el Campo Charro reducida debido a la baja demografía a actos religiosos tradicionales, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37002','fiesta','Fiestas de San Bartolomé (Fiesta de la mocedad)','Patronal y Etnográfica. Se celebra en Agosto. Festejos tradicionales en la Sierra de Francia de gran vistosidad; destaca el Ofertorio a la Virgen con trajes regionales tradicionales y la ancestral "alborada" cantada por las calles medievales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37099','fiesta','Fiestas de San Marcos y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Abril y Octubre. Festejos serranos que destacan por el tradicional canto del ramo, subasta de banzos de la virgen, bailes populares folclóricos al son del tamboril y meriendas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37100','fiesta','Fiestas de San Marcos','Patronal. Se celebra en Abril y Agosto (Verano) *. Festejos en las Arribes del Duero adaptados para los veraneantes, con competiciones de cartas populares, juegos infantiles en la plaza y música disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37101','fiesta','Fiestas de Nuestra Señora de los Ángeles','Patronal y Taurina. Se celebra en Agosto. Festejos de la comarca de Vitigudino bajo la estampa de los restos de su castillo medieval, célebres por sus tradicionales encierros, capeas urbanas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37103','fiesta','Fiestas del Santo Cristo de la Columna','Patronal, Etnográfica y Taurina. Se celebra en Septiembre. Hito comarcal en el Alto Tormes que destaca por sus tradicionales encierros y capeas urbanas, la vistosa procesión con alboradas folclóricas y la apertura masiva de las peñas locales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37104','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña celebración en la comarca de la Sierra de Francia adaptada al turismo familiar veraniego, con misa tradicional, juegos infantiles y música grabada en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37106','fiesta','Fiestas de San Sebastián y la Virgen del Rosario','Patronal y Taurina. Se celebra en Enero y Agosto. Festejos estivales tradicionales en la comarca de la Tierra de Vitigudino, famosos por sus encierros de reses bravas por el casco urbano, capeas, jotas charras y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37003','fiesta','Carnaval del Toro','Etnográfica, Taurina y Cultural. Se celebra en Febrero o Marzo (Carnavales). Fiesta de Interés Turístico Nacional de masivo impacto internacional. Es el carnaval taurino más antiguo de España, caracterizado por sus espectaculares encierros a caballo por el campo, capeas en su plaza de madera rectangular y masivas charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37108','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto (Verano). Festejos de retorno en la Tierra de Alba con misa solemne, campeonatos de bolos charros y calva, seguidos de una cena popular para residentes y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37109','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Festejos rurales tradicionales en la comarca de Béjar con procesión mariana, canto del ramo al son de la gaita y el tamboril, y meriendas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37110','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Celebración estivales de arraigo local en la comarca de Peñaranda con juegos tradicionales, parrillada popular comunitaria en las piscinas y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37112','fiesta','Fiestas de San Martín de Tours','Patronal y Etnográfica. Se celebra en Noviembre y Agosto. Festejos de verano que adelantan la fiesta patronal para los emigrantes, destacando el tradicional ofertorio, jotas serranas y comidas colectivas en los pinares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37113','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto. Festejos en el Campo de Vitigudino célebres por sus tradicionales encierros y capeas urbanas, espectáculos folclóricos con flauta y tamboril y cenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37115','fiesta','Fiestas del Santo Cristo de la Buena Muerte','Patronal y Taurina. Se celebra en Septiembre. Festejos en el Campo Charro con suelta de vaquillas en plaza portátil, encierro infantil de carretones, procesión solemne y baile con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37116','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeña celebración en la comarca de Ledesma centrada en los oficios religiosos tradicionales de la Asunción, campeonato de mus y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37117','fiesta','Fiestas de San Marcos y Santo Domingo de Guzmán','Patronal y Cultural. Se celebra en Abril y Agosto. Gran animación en este municipio del área metropolitana; destaca por su desfile de peñas, potentes macroverbenas en la plaza, paellada masiva y actividades infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37118','fiesta','Fiestas del envío de San Juan y la Virgen del Rosario','Patronal. Se celebra en Junio y Octubre. Celebración rural a orillas del río Tormes orientada al turismo familiar con misa solemne, competiciones de cartas populares y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37119','fiesta','Fiestas de San Bernardo','Patronal y Taurina. Se celebra en Agosto. Festejos en el Campo de Agadones con encierros tradicionales urbanos, capeas de reses bravas en plaza portátil, charangas musicales y comidas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37120','fiesta','Fiestas de San Silvestre','Patronal. Se celebra en Diciembre y Agosto (Verano). Festejos veraniegos para retornados en la comarca de Ledesma con misa cantada, campeonatos de bolos charros y una gran cena popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37121','fiesta','Fiestas de la Virgen del Rosario y San Juan Bautista','Patronal y Taurina. Se celebra en Octubre y Junio. Festejos tradicionales en Las Villas con capeas populares de vaquillas, desfile humorístico de disfraces organizados por las peñas y orquestas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37122','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos de retorno estival con oficios religiosos tradicionales, competiciones infantiles, campeonatos de calva y música disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37123','fiesta','Fiestas de la Virgen de las Mercedes','Patronal y Taurina. Se celebra en Septiembre. Celebración en la comarca de Vitigudino con encierros de vaquillas por las calles, pasacalles al son de la gaita charra, tiro al plato y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37124','fiesta','Fiestas de San Juan Bautista y la Virgen del Maderal','Patronal y Etnográfica. Se celebra en Junio y Septiembre. Festejos en la comarca de Guijuelo tradicionales por sus bailes de jotas, la procesión de la Virgen del Maderal con subasta de banzos y meriendas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37125','fiesta','Fiestas de la Santa Cruz y la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Mayo y Octubre. Vistosos festejos serranos que destacan por el tradicional Ofertorio a la Virgen con trajes regionales bordados, pasacalles con tamboril y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37126','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña festividad vecinal en la Tierra de Ledesma reducida por la baja demografía a actos religiosos, campeonatos de mus en las antiguas escuelas y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37128','fiesta','Fiestas de Santiago Apóstol','Patronal y Taurina. Se celebra en Julio. Festejos en la comarca de La Armuña célebres por sus tradicionales encierros urbanos de reses bravas, suelta de vaquillas, concurso de disfraces y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37129','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Mayo (Verano). Festejos en la comarca de Ledesma dinamizados por su cercanía a la capital, con paellada popular comunitaria, torneos de fútbol sala, hinchables y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37130','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Celebración tradicional en La Armuña centrada en la misa solemne, campeonatos de calva y bolos charros, seguidos de meriendas de hermandad en los lagares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37131','fiesta','Fiestas de San Vicente y San Antonio','Patronal y Cultural. Se celebra en Enero y Junio. Festejos en Entresierras vinculados a la figura del poeta Gabriel y Galán, que combinan recitales de verso tradicional, procesiones litúrgicas, parrilladas y música local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37132','fiesta','Fiesta del Almendro en Flor y Fiestas de San Bartolomé','Etnográfica, Paisajística y Patronal. Se celebra en Marzo y Agosto. Gran relevancia en la frontera portuguesa; la Fiesta del Almendro atrae a miles de visitantes para contemplar el paisaje arribense y celebrar el tradicional encuentro institucional transfronterizo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37133','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio y Agosto. Pequeña celebración en la comarca de Béjar orientada al turismo familiar de vacaciones, con misa solemne, campeonato de mus y juegos tradicionales para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37134','fiesta','Fiestas del Santo Cristo de la Guía','Patronal. Se celebra en Agosto. Festejos estivales de reencuentro vecinal a orillas del río Alhándiga, caracterizados por campeonatos de cartas, una gran parrillada vecinal y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37135','fiesta','Fiestas del Corpus Christi','Patronal, Taurina y Ganadera. Se celebra en Junio. Hito taurino de gran relevancia comarcal en el Campo Charro; célebre por sus tradicionales e intensos encierros a caballo, capeas urbanas en la plaza fija y desfile masivo de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37136','fiesta','Fiestas del San Bartolomé (Los Encierros de Fuenteguinaldo)','Patronal y Taurina. Se celebra en Agosto. Celebración de enorme raigambre considerada de las más importantes del sur provincial; destaca por sus arriesgados y multitudinarios encierros a caballo por el campo y capeas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37137','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto (Verano). Festejos de verano adaptados para los emigrantes en el Campo de Yeltes, con suelta de vaquillas en coso portátil, encierro infantil de carretones y verbena en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37138','fiesta','Fiestas del Santo Cristo del Socorro','Patronal y Jacobea. Se celebra en Agosto. Festividad dinamizada por su fuerte vinculación con la Vía de la Plata, acogiendo a numerosos peregrinos en una gran caldereta popular, conciertos folk y pasacalles de tamboril.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37139','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos veraniegos en la comarca de Guijuelo con procesión solemne, campeonatos de bolos y calva, comidas comunitarias de peñas y bailes nocturnos con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37140','fiesta','Fiestas de la Virgen de la Asunción','Patronal, Taurina y Fronteriza. Se celebra en Agosto. Festejos de gran animación en la frontera con Portugal, caracterizados por sus tradicionales encierros urbanos, capeas de reses bravas y una gran afluencia de público de ambos países.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37141','fiesta','Fiestas de El Salvador','Patronal. Se celebra en Agosto. Celebración en la comarca de Alba con oficios religiosos tradicionales, competiciones de cartas populares en las antiguas escuelas y música disco-móvil para la juventud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37142','fiesta','Fiestas de Santo Tomás de Villanueva','Patronal. Se celebra en Septiembre y Agosto. Festejos muy concurridos por la presencia de segundas residencias metropolitanas, ofreciendo concursos gastronómicos, paellada comunitaria y grandes verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37144','fiesta','Fiestas de la Virgen del Rosario y San Juan','Patronal. Se celebra en Octubre y Junio. Festejos tradicionales a orillas del Tormes con procesiones religiosas, competiciones de pesca popular, juegos infantiles tradicionales y cenas populares vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37145','fiesta','Fiestas del Santo Cristo de la Exaltación','Patronal y Taurina. Se celebra en Abril y Agosto. Destacan sus festejos taurinos veraniegos de la raya con tradicionales encierros a caballo por el campo, capeas, pasacalles de charangas y grandes bailes públicos con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37146','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos de retorno familiar en el límite con la provincia de Ávila, con misa cantada, campeonatos de calva y bolos charros, seguidos de una comida comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37147','fiesta','Fiestas del Santo Cristo de la Amargura','Patronal y Etnográfica. Se celebra en Septiembre. Celebración serrana caracterizada por el vistoso ofertorio tradicional de la mocedad vestido con el traje típico, danzas folclóricas de jotas al son del tamboril y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37149','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña festividad vecinal en el Campo Charro reducida por la despoblación a los actos religiosos tradicionales, campeonato de mus y refresco para los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37150','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos de verano mínimos adaptados a la demografía estival, centrados en una misa comunitaria, juegos tradicionales de cartas y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37151','fiesta','Fiestas de San Bartolomé','Patronal y Taurina. Se celebra en Agosto. Festejos tradicionales del Campo de Ledesma con suelta de vaquillas en plaza portátil, encierro infantil de carretones, chocolatada popular y orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37152','fiesta','Fiestas de la Virgen de la Esperanza','Patronal y Taurina. Se celebra en Agosto. Gran animación estival en La Armuña, famosa por sus encierros urbanos tradicionales, concursos de disfraces organizados por las peñas y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37154','fiesta','Fiestas de San Cristóbal y las Madrinas','Patronal y Etnográfica. Se celebra en Julio y Septiembre. Destaca la Fiesta de las Madrinas por su gran valor etnográfico, con la procesión de las roscas bendecidas, desfile con trajes charros y bailes populares tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37155','fiesta','Fiestas de Santiago Apóstol','Patronal y Deportiva. Se celebra en Julio. Festejos junto al embalse de Santa Teresa que combinan actos litúrgicos con piragüismo popular, parrillada comunitaria y música disco-móvil para veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37156','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal, Taurina y Gastronómica. Se celebra en Agosto. Hito industrial y chacinero de gran repercusión regional; sus fiestas destacan por albergar ferias taurinas con figuras de primer nivel, multitudinarios desfiles de peñas y degustaciones masivas de jamón de Guijuelo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37157','fiesta','Fiestas de San Juan Bautista y el Emigrante','Patronal. Se celebra en Junio y Agosto. Festejos rurales centrados en el reencuentro estival, con misa cantada, campeonatos de tusa y bolos charros, seguidos de una merienda comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37158','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Etnográfica. Se celebra en Septiembre. Destaca por el tradicional Ofertorio bajo el centenario olmo de la plaza, con bailes de jotas serranas al son del tamboril y subasta de roscas bendecidas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37159','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Pequeña celebración en la comarca de Guijuelo adaptada a la población estival con competiciones de cartas, juegos infantiles y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37004','fiesta','Fiestas de San Juan Bautista y Feria del Queso de Hinojosa','Patronal, Taurina y Gastronómica. Se celebra en Junio y Mayo. Gran hito de las Arribes del Duero; sus fiestas patronales incluyen la tradicional bajada a caballo al río Duero, espectaculares encierros y la masiva Feria del Queso artesano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37161','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Festejos de arraigo serrano en la comarca de Béjar con misa cantada, procesión por las intrincadas calles, pasacalles tradicionales y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37162','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Romería. Se celebra en Agosto. Romería tradicional a la ermita de la Virgen de Valdejimena, con jotas salmantinas, campeonato de calva y meriendas de hermandad en los encinares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37163','fiesta','Fiestas de San Antonio de Padua','Patronal y Deportiva. Se celebra en Junio. Festejos en el municipio más alto de la provincia, dinamizados por su entorno de montaña cercano a La Covatilla, con parrillada vecinal y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37164','fiesta','Fiestas de San Bartolomé','Patronal y Deportiva. Se celebra en Agosto. Notable animación estival a orillas del río Tormes, caracterizada por sus descensos lúdicos en piragua, campeonatos de fútbol sala y populosas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37165','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Celebración vecinal mínima en la comarca de Vitigudino, adaptada a la baja demografía con una misa tradicional, aperitivo vecinal y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37166','fiesta','Fiestas del Santo Cristo de la Exaltación','Patronal y Taurina. Se celebra en Septiembre. Festejos de la comarca de Ciudad Rodrigo con suelta de vaquillas en plaza portátil, pasacalles al son de la gaita charra, cenas populares de peñas y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37167','fiesta','Fiestas de San Miguel Arcángel','Patronal y Cultural. Se celebra en Septiembre y Julio. Festejos dinamizados por sus proyectos de poesía rural y patrimonio geológico, combinando actos litúrgicos con recitales, paellada comunitaria y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37168','fiesta','Fiestas del Santo Cristo de los Afligidos','Patronal y Etnográfica. Se celebra en Septiembre. Festejos con gran sabor serrano en el límite extremeño, célebres por su vistosa procesión, bailes folclóricos tradicionales con gaita y tamboril, y verbenas muy concurridas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37169','fiesta','Fiestas de San Blas y Nuestra Señora de los Remedios','Patronal. Se celebra en Febrero y Agosto. Destacan los festejos de retorno veraniego en la comarca de Alba con campeonatos de bolos charros, juegos infantiles y orquesta nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37006','fiesta','Fiestas del Corpus Christi (Los Espantos de Ledesma)','Patronal, Taurina e Histórica. Se celebra en Junio. Fiesta de Interés Turístico Regional de gran arraigo; destaca por "Los Espantos", donde los jinetes intentan guiar a los toros hacia la villa medieval mientras los mozos los contienen.','inventario_fiestas_pdf');
