INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37244','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre y Agosto. Festejos de verano en el límite cacereño de la Vía de la Plata, caracterizados por marchas de senderismo por los castañares, parrillada popular y orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37245','fiesta','Fiestas de la Virgen del Rosario y Fiesta del Pandero Cuadrado','Etnográfica y Patronal. Se celebra en Octubre y Agosto. Hito etnográfico único en España; destaca su Festival del Pandero Cuadrado, donde las mujeres tocan este ancestral instrumento de percusión con porra mientras bailan el "ajechao".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37247','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración rural orientada al retorno estival en la Tierra de Alba con misa solemne, campeonatos de bolos castellanos y calva, seguidos de una parrillada de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37246','fiesta','Fiestas y Ferias de la Virgen de Loreto','Patronal, Taurina y Feria Comercial. Se celebra en Agosto. Festividad de gran empaque y tradición en el este provincial; destaca por sus importantes ferias y mercados, corridas de toros de primer nivel, multitudinarias peñas y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37248','fiesta','Fiestas de San Blas y la Feria Agroganadera de Peralejos','Ganadera, Patronal y Taurina. Se celebra en Febrero y Agosto. Hito comarcal en la Tierra de Vitigudino; destaca por su veterana e importante Feria Agroganadera que reúne abundante ganado charro, exposiciones, y capeas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37249','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña festividad vecinal en la comarca de Vitigudino reducida por la despoblación a los actos religiosos tradicionales, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37250','fiesta','Fiestas de la Virgen del Castillo','Patronal, Taurina y Enológica. Se celebra en Septiembre. Festejos de gran arraigo en las Arribes del Duero; destacan sus tradicionales encierros urbanos y capeas de vaquillas, la romería a la ermita sobre el cañón del Duero y degustaciones de vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37251','fiesta','Fiestas de Santo Domingo de Guzmán','Patronal. Se celebra en Agosto. Festejos veraniegos en la comarca de Béjar con procesión solemne, tradicionales campeonatos de cartas, parrillada popular vecinal y baile nocturno con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37252','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeñas fiestas estivales en la Sierra de Francia rodeadas de olivares, con misa litúrgica tradicional, competiciones infantiles y música grabada en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37253','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos veraniegos para emigrantes en la Tierra de Ledesma, con competiciones de calva y bolos charros, cena popular vecinal y baile con discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37254','fiesta','Fiestas de San Blas y la Virgen del Rosario','Patronal. Se celebra en Febrero y Octubre. Festejos tradicionales de La Armuña con procesión mariana, campeonato de calva, refresco vecinal en las escuelas y baile público con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37255','fiesta','Fiestas de San Blas y el Emigrante','Patronal. Se celebra en Febrero y Agosto. Festejos de retorno veraniego en la comarca de Guijuelo con campeonatos de cartas populares, juegos infantiles en la plaza, parrillada vecinal y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37256','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto. Festejos estivales tradicionales en el límite norte de La Armuña, con suelta de vaquillas en plaza portátil, desfile de disfraces organizados por las peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37257','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos de verano mínimos adaptados a la demografía estival en la comarca de Vitigudino, centrados en una misa comunitaria, juegos de cartas y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37258','fiesta','Fiestas de San Pedro Celestrino','Patronal y Taurina. Se celebra en Mayo y Agosto. Festejos tradicionales del Campo de Argañán con encierros de vaquillas por las calles, pasacalles al son de la gaita charra, cenas de peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37259','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en la comarca de Béjar, centrada en los actos litúrgicos tradicionales, campeonato de mus en las antiguas escuelas y una parrillada comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37260','fiesta','Fiestas de San Juan Bautista','Patronal y Taurina. Se celebra en Junio y Agosto. Festejos de retorno veraniego en el Campo de Yeltes con suelta de vaquillas en plaza portátil, encierro infantil de carretones y baile con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37262','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos veraniegos en la comarca de Vitigudino centrados en la misa cantada, tradicionales campeonatos de cartas, cena vecinal de hermandad y baile nocturno.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37263','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Festejos de gran animación en el límite con Extremadura, caracterizados por sus pasacalles tradicionales, torneos deportivos populares, grandes verbenas y caldereta comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37265','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto. Festejos estivales en el este provincial con capeas populares de vaquillas en plaza portátil, pasacalles de dulzaina, comidas comunitarias de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37266','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeña festividad vecinal en la comarca de Vitigudino, reducida debido a la baja demografía a actos religiosos tradicionales, campeonato de naipes y merienda popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37267','fiesta','Fiestas de San Roque','Patronal y Taurina. Se celebra en Agosto. Festejos en el Campo de Yeltes muy animados por peñas locales, célebres por sus tradicionales encierros urbanos de reses bravas, capeas, caldereta popular y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37268','fiesta','Fiestas de Santiago Apóstol','Patronal y Etnográfica *. Se celebra en Julio *. Festejos serranos al pie de la Peña de Francia que destacan por el tradicional ofertorio, jotas salmantinas al son del tamboril, comidas colectivas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37269','fiesta','Fiestas de San Juan Bautista (La Fiesta del Rebollo)','Patronal, Taurina y Etnográfica. Se celebra en Junio y Agosto. Gran arraigo comarcal en el Campo de Agadones; destaca por sus singulares encierros a caballo tradicionales, el baile del "Són" con vistosos trajes típicos y capeas urbanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37270','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal y Taurina. Se celebra en Junio y Octubre. Festejos tradicionales en el Campo Charro con tradicionales capeas de vaquillas, pasacalles de charangas, campeonatos de calva y comidas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37271','fiesta','Fiestas de San Lorenzo','Patronal y Taurina. Se celebra en Agosto. Gran animación en la comarca de Ledesma, destacando por sus encierros urbanos tradicionales, desfiles humorísticos de disfraces organizados por las peñas y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37272','fiesta','Fiestas de San Benito y del Emigrante','Patronal y Taurina. Se celebra en Mayo y Agosto. Festejos en el Campo de Ciudad Rodrigo dinamizados por el retorno estival, caracterizados por capeas tradicionales en plaza portátil, encierro infantil de carretones y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37303','fiesta','Fiestas de San Cayetano','Patronal y Taurina. Se celebra en Agosto. Celebración en la comarca de Los Agadones con gran animación juvenil, destacando sus encierros urbanos tradicionales de reses bravas, pasacalles con charanga y populosas cenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37011','fiesta','Ferias y Fiestas en honor a la Virgen de la Vega y Semana Santa de Salamanca','Patronal, Cultural, Taurina y Religiosa. Se celebra en Septiembre y Marzo/Abril. Hito masivo de impacto nacional e internacional. Su Semana Santa está declarada de Interés Turístico Internacional; las ferias de septiembre llenan la monumental Plaza Mayor de conciertos gratuitos, desfiles de folklore charro, ferias taurinas en La Glorieta y casetas gastronómicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37275','fiesta','Fiestas de San Quintín','Patronal y Paisajística. Se celebra en Octubre y Agosto (Verano). Festejos estivales en Arribes del Duero adaptados para los veraneantes, combinando los actos religiosos con rutas al castro vetón, competiciones de cartas y baile público con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37276','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos en la comarca de Peñaranda centrados en el reencuentro familiar estival, con misa cantada, torneos tradicionales de calva, campeonato de mus y música disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37277','fiesta','Fiestas del Santísimo Cristo de las Aguas','Patronal e Histórica. Se celebra en Septiembre. Celebración tradicional junto al embalse de Santa Teresa que aprovecha su histórico recinto amurallado medieval para albergar comidas de hermandad, jotas salmantinas y pasacalles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37278','fiesta','Fiestas de San Cristóbal y la Virgen del Rosario','Patronal y Cultural. Se celebra en Julio y Octubre. Municipio metropolitano de rápido crecimiento; destaca por su gran concentración de peñas juveniles, macroverbenas con orquestas potentes en la plaza, paellada masiva e hinchables infantiles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37284','fiesta','Fiestas del Santo Cristo de la Sala (Fiesta del Quema del Estupendo)','Patronal, Etnográfica y Enológica. Se celebra en Septiembre. Hito serrano de gran valor etnográfico; destaca el ancestral ritual de la quema de "El Estupendo", la coronación de la reina con trajes tradicionales de bodas serranos, bailes de paleo y cata de vinos autóctonos de la D.O. Sierra de Salamanca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37285','fiesta','Fiestas de El Noveno','Histórica, Taurina y Etnográfica. Se celebra en Mayo. Fiesta de Interés Turístico Regional de gran singularidad; conmemora la exención del pago de un tributo feudal en 1852, destacando sus espectaculares encierros urbanos y capeas celebradas en una histórica plaza construida íntegramente con carros de madera junto a la muralla.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37012','fiesta','Fiestas de la Virgen de la Consolación','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Festejos de gran belleza en este conjunto histórico serrano; destaca su solemne Ofertorio tradicional donde los vecinos visten ricos indumentarias bordadas, seguido de capeas populares en su singular plaza de toros fortificada dentro del castillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37287','fiesta','Fiestas de San Miguel Arcángel','Patronal y Etnográfica. Se celebra en Septiembre. Celebración en la Sierra de Francia famosa por su tradicional ofertorio mariano, pasacalles folclóricos al son de la gaita y el tamboril, degustación de dulces locales con miel y verbenas nocturnas populosas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37036','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio y Agosto. Pequeños festejos serranos adaptados a la demografía estival, caracterizados por la misa tradicional, campeonatos de cartas en el teleclub y una parrillada de hermandad en los pinares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37288','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos en la comarca de Las Villas dinamizados por el río Tormes, ofreciendo piragüismo popular, comidas vecinales de hermandad, juegos tradicionales y verbenas con orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37289','fiesta','Fiestas de San Juan Bautista y la Virgen de la Augusta','Patronal y Taurina. Se celebra en Junio y Agosto. Festejos tradicionales en pleno Campo Charro célebres por sus encierros urbanos de vaquillas, concurso humorístico de disfraces entre peñas locales, campeonatos de calva y bailes con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37291','fiesta','Fiestas de San Pedro y la Virgen del Rosario','Patronal y Jacobea. Se celebra en Junio y Octubre. Festividad marcada por su ubicación en el Camino de Santiago de la Vía de la Plata, caracterizada por la procesión tradicional flanqueada por pendones, torneos de bolos charros y cenas populares vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37290','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Festejos en la comarca de Ledesma orientados al reencuentro de familias nativas con misa cantada, encierro infantil de carretones, campeonato de mus y orquesta en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37292','fiesta','Fiestas de San Pelayo','Patronal. Se celebra en Junio. Pequeña celebración rural en la Tierra de Ledesma reducida por la baja demografía a actos religiosos, competiciones de cartas populares en las antiguas escuelas y un refresco vecinal). [1] ¿Puedo continuar con el siguiente bloque de la provincia de Salamanca?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37279','fiesta','Fiestas del Corpus Christi','Patronal, Taurina y Etnográfica. Se celebra en Junio. Celebración de gran arraigo en la comarca de Ciudad Rodrigo; destaca por sus tradicionales encierros a caballo por el campo, capeas urbanas, animadas charangas de peñas y parrilladas comunitarias de carne de lidia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37283','fiesta','Fiestas de los Santos Justo y Pastor','Patronal. Se celebra en Agosto. Festejos estivales de carácter estrictamente local adaptados a la población flotante, con misa solemne, campeonato de calva y música discomóvil para la juventud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37293','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos de verano mínimos condicionados por la baja demografía, enfocados en un aperitivo vecinal en las antiguas escuelas y juegos de cartas tradicionales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37294','fiesta','Fiestas de Santa Marta','Patronal, Cultural y Taurina. Se celebra en Julio. El mayor hito del área metropolitana por volumen de asistencia; destaca por sus multitudinarios encierros taurinos urbanos, desfiles masivos de peñas, conciertos musicales de primer nivel y su Festival de Teatro de Calle.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37296','fiesta','Fiestas de Santiago Apóstol y San Jorge','Patronal y Taurina. Se celebra en Julio y Abril. Festejos en la comarca de Peñaranda con suelta de vaquillas en plaza portátil, pasacalles al son de la dulzaina, competiciones de calva y grandes verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37297','fiesta','Fiestas de Santiago Apóstol y de la Virgen de Valparaíso','Patronal y Romería. Se celebra en Julio y Octubre. Festejos de gran animación comarcal con la tradicional subasta de banzos de la virgen, pasacalles folclóricos al son del tamboril, grandes verbenas veraniegas y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37298','fiesta','Fiestas de San Agustín','Patronal, Etnográfica y Enológica. Se celebra en Agosto. Festejos serranos que destacan por el vistoso Ofertorio tradicional con trajes regionales bordados, las ancestrales danzas de paleo y degustaciones de los preciados vinos locales de la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37299','fiesta','Fiestas de San Miguel Arcángel','Patronal y Taurina. Se celebra en Septiembre y Agosto (Verano). Festejos estivales en el límite con la provincia de Zamora, caracterizados por encierros de vaquillas por las calles, cenas comunitarias de peñas y baile público con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37301','fiesta','Fiestas del Rosario','Patronal y Recreativa. Se celebra en Agosto. Festejos estivales muy animados junto al embalse de Almendra, potenciados por actividades de ocio acuático popular, parrillada comunitaria y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37313','fiesta','Fiestas de San Ramón Nonato','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Gran arraigo en la Sierra de Francia; destaca por la procesión del santo con el tradicional Ofertorio y trajes serranos, la ancestral "Alborada", capeas urbanas en la plaza mayor y degustaciones de vino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37314','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña celebración en pleno Campo Charro rural centrada en los oficios religiosos tradicionales, campeonatos de cartas y una merienda popular para los pocos residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37330','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Octubre y Agosto. Celebración de retorno veraniego en la comarca de Alba con capeas populares de vaquillas en plaza portátil, desfile de disfraces entre las peñas y orquesta nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37331','fiesta','Fiestas de Nuestra Señora de la Inmaculada Concepción','Patronal. Se celebra en Septiembre y Agosto (Verano). Festejos estivales orientados a los emigrantes con misa cantada, campeonatos tradicionales de calva, campeonato de mus y música disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37332','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos veraniegos sencillos organizados para el turismo familiar con procesión, competiciones de cartas populares en las antiguas escuelas y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37333','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio y Agosto. Festejos veraniegos en la comarca de Guijuelo con procesión solemne, tradicionales campeonatos de cartas, parrillada popular vecinal y baile con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37334','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre. Pequeñas fiestas serranas tradicionales al pie del río Sangusín, con misa tradicional, competiciones infantiles en la plaza y música grabada en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37335','fiesta','Fiestas de San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Gran animación en la comarca del Buen Amor, famosa por sus encierros urbanos tradicionales de reses bravas, suelta de vaquillas, actividades vinculadas a su histórico alcornocaleño y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37336','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Pequeña festividad vecinal en la Tierra de Alba reducida debido a la baja demografía a actos religiosos tradicionales, campeonato de mus y refresco para los vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37337','fiesta','Fiestas de Nuestra Señora del Rosario (Fiestas de las Madrinas)','Patronal, Taurina y Etnográfica. Se celebra en Octubre y Agosto. Festejos estivales en la comarca de Vitigudino, célebres por su tradicional desfile de Madrinas con trajes charros y roscas bendecidas, seguidos de encierros y capeas urbanas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37338','fiesta','Fiestas de San Vicente','Patronal. Se celebra en Enero y Agosto (Verano). Festejos de retorno veraniego en La Armuña con misa solemne, campeonatos de calva y bolos salmantinos, seguidos de una cena popular comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37339','fiesta','Fiestas de San Valerio (Las Fiestas del Toro de Valero)','Patronal, Taurina y Etnográfica. Se celebra en Enero. Hito taurino de gran singularidad invernal en la Sierra de Francia; abre oficialmente la temporada taurina provincial con su tradicional festival taurino en la plaza del pueblo cerrada con maderas, pasacalles al son del tamboril y degustación de chocolate.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37340','fiesta','Fiestas de San Ildefonso y las Madrinas','Patronal y Etnográfica. Se celebra en Enero y Septiembre. Festejos en la comarca de Vitigudino tradicionales por su procesión de las Madrinas con trajes charros y subasta de roscas bendecidas, caldereta popular y bailes folclóricos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37341','fiesta','Fiestas de Santiago Apóstol','Patronal *. Se celebra en Julio y Agosto *. Pequeña celebración veraniega en la comarca de Béjar con misa cantada, campeonato de tusa y merienda vecinal para los residentes y emigrantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37342','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos junto al río Tormes dinamizados por su cercanía a la capital, con paellada popular comunitaria, torneos de fútbol sala, hinchables infantiles y animadas disco-móviles.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37344','fiesta','Fiestas de San Juan Bautista','Patronal y Taurina. Se celebra en Junio. Festejos tradicionales en pleno Campo Charro, célebres por su suelta de vaquillas para los mozos en plaza portátil, pasacalles al son de la gaita charra, cenas populares de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37345','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos de retorno estival en la comarca de Ledesma con procesión, competiciones tradicionales de calva, refresco vecinal en las escuelas y baile público.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37346','fiesta','Fiestas del Santo Cristo de los Navas y San Bartolomé','Patronal y Taurina. Se celebra en Agosto. Festejos en pleno Campo Charro rodeados de fincas de ganado bravo, famosos por sus tradicionales encierros camperos a caballo, novilladas, concurso de carrozas y verbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37347','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Taurina. Se celebra en Agosto. Gran animación estival en la comarca de La Armuña, famosa por sus encierros urbanos tradicionales de reses bravas, pasacalles multitudinarios de peñas locales y verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37348','fiesta','Fiestas de San Fernando','Patronal. Se celebra en Mayo y Agosto (Verano). Celebración en la comarca de Peñaranda orientada al reencuentro de familias nativas con campeonatos de calva, bolos salmantinos, parrillada popular y discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37349','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Pequeña festividad vecinal en la comarca de Vitigudino reducida por la despoblación a actos religiosos tradicionales, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37351','fiesta','Fiestas de San Agustín','Patronal y Taurina. Se celebra en Agosto. Festejos en la comarca de la Tierra de Peñaranda, célebres por sus tradicionales encierros y capeas urbanas, espectáculos folclóricos con flauta y tamboril, y grandes verbenas). ¿Puedo continuar con el siguiente bloque de la provincia de Salamanca para terminar los municipios restantes de la V a la Z?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37352','fiesta','Fiestas de la Virgen del Rosario y San Juan','Patronal. Se celebra en Octubre y Junio. Festejos muy animados a orillas del río Tormes gracias a su cercanía a la capital, destacando por sus competiciones de pesca, paellada comunitaria y animadas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37353','fiesta','Fiestas de San Juan Bautista','Patronal y Taurina. Se celebra en Junio. Celebración en pleno Campo Charro que cuenta con tradicionales capeas de vaquillas, encierros infantiles de carretones, jotas salmantinas al son del tamboril y cenas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37354','fiesta','Fiestas de la Virgen de los Remedios y Feria de la Piedra','Patronal, Cultural y Feria de Muestras. Se celebra en Mayo. Hito comarcal del área metropolitana; sus fiestas patronales atraen a miles de jóvenes con potentes conciertos y macroverbenas, complementadas con la feria que pone en valor la famosa piedra dorada de sus canteras.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37355','fiesta','Fiestas de la Virgen de la Asunción','Patronal, Etnográfica y Taurina. Se celebra en Agosto. Sabor serrano en su casco urbano fortificado; destaca por su vistoso Ofertorio tradicional con ricos trajes típicos de la Sierra de Francia, bailes folclóricos y capeas en la plaza del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37356','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto (Verano). Festejos de retorno veraniego en el Campo de Argañán con misa solemne, competiciones de juegos tradicionales de cartas, chocolatada vecinal y disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37357','fiesta','Fiestas de San Agustín','Patronal y Taurina. Se celebra en Agosto. Gran animación en la raya con Portugal, célebre por sus arriesgados encierros tradicionales urbanos de reses bravas, capeas en su plaza fija, charangas y masiva afluencia transfronteriza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37358','fiesta','Fiestas del Santo Cristo de la Custodia','Patronal y Taurina. Se celebra en Pentecostés (Mayo/Junio) y Agosto. Festejos en la comarca de Peñaranda caracterizados por la suelta de vaquillas en plaza portátil, encierros infantiles, comidas populares de peñas y orquestas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37360','fiesta','Fiestas de San Juan Bautista y la Virgen del Rosario','Patronal y Taurina. Se celebra en Junio y Octubre. Festejos tradicionales de la comarca de Vitigudino famosos por sus encierros urbanos de vaquillas, pasacalles al son de la gaita charra, tiro al plato y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37361','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en la comarca de Vitigudino, adaptada en verano para los emigrantes con campeonatos de mus, parrillada popular comunitaria y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37362','fiesta','Fiestas del Santísimo Sacramento','Patronal y Cultural. Se celebra en Junio. Hito en el cinturón metropolitano de Salamanca; destaca por su enorme presupuesto para conciertos de primer nivel, populosos desfiles y locales de peñas, macroverbenas y paellada multitudinaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37363','fiesta','Fiestas de San Antonio de Padua','Patronal y Taurina. Se celebra en Junio y Agosto. Festejos en el Campo de Yeltes que combinan los actos religiosos con encierros tradicionales de vaquillas por el casco urbano, charangas y bailes públicos con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37364','fiesta','Fiestas de San Roque (San Roque el de los Toros)','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Hito de enorme raigambre en Arribes del Duero; célebre por sus peligrosos encierros urbanos por calles en pendiente escarpada, capeas nocturnas, el canto tradicional de "La Tarara" y peñas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37365','fiesta','Fiestas de San Vicente y la Virgen del Rosario','Patronal. Se celebra en Enero y Octubre. Celebración tradicional del Campo de Ledesma centrada en la misa solemne, campeonatos de calva y bolos charros, seguidos de meriendas de hermandad en los locales municipales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37366','fiesta','Fiestas de San Cipriano','Patronal. Se celebra en Septiembre y Agosto. Festejos de escala estrictamente local adaptados a la baja demografía, con oficios litúrgicos tradicionales, campeonato de mus y refresco para los residentes estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37367','fiesta','Fiestas de San Bartolomé','Patronal y Taurina. Se celebra en Agosto. Festejos en la comarca de Vitigudino con suelta de vaquillas en plaza portátil, encierro infantil de carretones, pasacalles con tamboril y baile con orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37368','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeña festividad vecinal reducida debido a la despoblación rural a actos religiosos tradicionales, campeonato de naipes en las escuelas y un aperitivo comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37369','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio y Agosto (Verano). Festejos de retorno veraniego en la Tierra de Ledesma con misa cantada, campeonatos de bolos charros, cena popular vecinal y baile amenizado por charangas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37370','fiesta','Fiestas de la Virgen de los Reyes','Patronal y Taurina. Se celebra en Septiembre. Festejos de gran animación en la comarca de Ledesma, famosos por sus encierros urbanos tradicionales de reses bravas, concurso de disfraces entre peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37371','fiesta','Fiestas de San Ceferino','Patronal y Taurina. Se celebra en Agosto. Gran animación en la Sierra de Gata salmantina potenciada por sus piscinas naturales, destacando sus encierros tradicionales urbanos, capeas, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37372','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Festejos tradicionales de La Armuña con oficios religiosos de acción de gracias, campeonatos de calva, refresco vecinal en las escuelas y baile público con discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37373','fiesta','Fiestas de Nuestra Señora de los Caballeros','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Hito comarcal considerado la "Capital de la Charrería"; destaca por sus tradicionales encierros y capeas urbanas, y la exhibición del Baile del Cordón y del Són con los trajes charros más ricos de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37374','fiesta','Fiestas de la Virgen de la Vega','Patronal y Taurina. Se celebra en Septiembre. Gran relevancia en la comarca de Las Villas, famosa por sus espectaculares y tradicionales encierros urbanos de toros, concurso de recortes, multitudinarias peñas musicales y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37375','fiesta','Fiestas de la Virgen del Carmen y San Sebastián','Patronal, Etnográfica y Taurina. Se celebra en Julio. Festejos de gran tradición artesanal en Las Villas, caracterizados por encierros de vaquillas, exhibiciones de artesanía de mimbre local, desfile humorístico de peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37350','fiesta','Fiestas del Toro en honor a San Sebastián *','Patronal, Taurina y Paisajística *. Se celebra en Agosto *. Gran arraigo en las Arribes del Duero; destaca por sus encierros tradicionales por el casco urbano, capeas en su plaza mayor porticada, pasacalles al son del tamboril y paseos fluviales en barco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37013','fiesta','Fiestas de la Virgen del Socorro (Los Corpus de Vitigudino)','Patronal, Taurina y Feria Comercial. Se celebra en Junio (Corpus) y Agosto. Gran hito y capital comarcal del noroeste provincial; sus célebres fiestas del Corpus destacan por los tradicionales e intensos encierros urbanos nocturnos, desfile masivo de carrozas artesanales, peñas y ferias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37377','fiesta','Fiestas de la Virgen del Castillo','Patronal, Romería y Arqueológica. Se celebra en Abril y Agosto. Romería tradicional que rodea la ermita situada dentro de su monumental Castro Vetón fortificado, combinando procesiones litúrgicas, jotas charras, caldereta popular y capeas veraniegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37378','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Pequeña festividad vecinal en la comarca de Ciudad Rodrigo, reducida debido a la baja demografía a actos religiosos tradicionales, campeonatos de cartas y una merienda popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37379','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio. Festejos veraniegos en la Tierra de Ledesma centrados en la misa cantada, tradicionales campeonatos de calva y bolos salmantinos, parrillada popular y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37380','fiesta','Fiestas de San Juan Bautista','Patronal y Deportiva. Se celebra en Junio. Festejos marcados por su complejo de golf metropolitano, combinando la misa tradicional del santo con torneos populares abiertos, paellada vecinal y música grabada en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37381','fiesta','Fiestas de San Lorenzo','Patronal y Taurina. Se celebra en Agosto. Celebración estival en la comarca de Vitigudino, caracterizada por la suelta de vaquillas en coso portátil, encierro infantil de carretones, cenas de peñas y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','fiesta','Fiesta de San Roque','Patronal. Se celebra en Agosto. Festejos menores adaptados a la baja demografía invernal, centrados en el reencuentro de familias nativas con una comida popular de hermandad). Con este bloque completamos oficialmente todos los municipios de la provincia de Salamanca. ¿Podemos continuar con la siguiente provincia de Castilla y León (Provincia de Segovia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90116','fiesta','Fiestas del Santísimo Cristo del Amor y San Lorenzo','Patronal y Etnográfica. Se celebra en Mayo y Agosto. Festejos de gran arraigo tradicional en la Campiña Segoviana, célebres por sus vistosas danzas de paloteo frente a la imagen del Cristo, comidas populares y animadas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90117','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos estivales sencillos y familiares a orillas del río Pirón, centrados en los oficios litúrgicos tradicionales, campeonatos de cartas en el teleclub y música disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90118','fiesta','Fiestas de San Martín de Tours','Patronal. Se celebra en Noviembre y Agosto (Verano). Festejos adelantados al verano para la población estival, caracterizados por juegos infantiles en la plaza de la iglesia, campeonatos de chinchón y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90119','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración serrana orientada al retorno vacacional, con procesión tradicional por los distintos barrios del municipio, caldereta popular y bailes públicos con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90120','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos vecinales mínimos adaptados a la baja demografía invernal, que incluyen santa misa cantada, campeonato de bolos castellanos femeninos y merienda comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90121','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal y Enológica. Se celebra en Agosto. Celebración en la comarca del Voltoya potenciada por su vinculación al sector vitivinícola de la D.O. Rueda, combinando actos litúrgicos con apertura de bodegas y jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90122','fiesta','Fiestas de Santa María Magdalena','Patronal. Se celebra en Julio y Septiembre. Festejos tradicionales de carácter rural centrados en la procesión de la patrona, campeonatos de mus, juegos infantiles en el frontón y baile nocturno con orquesta.','inventario_fiestas_pdf');
