INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90125','fiesta','Fiestas de la Virgen de los Prados','Patronal y Romería. Se celebra en Septiembre. Tradicional romería a la ermita de la Virgen con subasta de banzos, jotas castellanas interpretadas por dulzaineros, meriendas colectivas y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90126','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Pequeña festividad veraniega centrada en la misa solemne del apóstol, juegos populares infantiles en la plaza mayor, cena vecinal de hermandad y baile con discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90128','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Dinamizada turísticamente por ser escenario cinematográfico rural; combina su procesión tradicional con actividades culturales para retornados y verbenas estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42031','fiesta','Fiestas de la Virgen de la Losa y Fiesta de los Quintos','Patronal, Romería y Etnográfica. Se celebra en Septiembre y Febrero. Notable arraigo en la vertiente segoviana del Guadarrama, destacando su multitudinaria romería a la ermita de la Losa, desfile de trajes tradicionales y subasta de banzos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40021','fiesta','Fiestas de San Mamés','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local para el turismo familiar vacacional, con procesión religiosa, campeonato de mus y orquesta de baile en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40022','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Celebración veraniega tradicional con pasacalles al son de la dulzaina, torneos de fútbol sala, comidas vecinales de hermandad y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40024','fiesta','Fiestas de San Miguel y Certamen Medieval "Ayllón Medieval"','Histórica, Recreación y Patronal. Se celebra en Septiembre y Julio. Fiesta de Interés Turístico Regional por su espectacular recreación medieval, transformando toda la villa histórica con mercados artesanales, desfiles de época y torneos caballerescos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40025','fiesta','Fiestas de la Virgen de la Soledad','Patronal. Se celebra en Septiembre y Agosto (Verano). Festejos estivales muy animados orientados al retorno de emigrantes con santa misa, campeonatos de cartas en el centro social, jotas tradicionales y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40026','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Celebración tradicional al pie de la Sierra de Guadarrama con pasacalles de dulzaina y tamboril, torneos de frontón, caldereta popular y verbena nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40028','fiesta','Fiestas de Santa Ana','Patronal. Se celebra en Julio. Festejos de escala estrictamente local adaptados a la demografía veraniega con santa misa, tradicionales campeonatos de calva, chocolatada popular y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40029','fiesta','Fiestas de Santo Tomás Apóstol','Patronal. Se celebra en Julio. Pequeña festividad vecinal dinamizada por la población flotante estival, que incluye oficios litúrgicos religiosos, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40030','fiesta','Fiestas de la Virgen del Castillo (Fiesta de la Subida)','Patronal, Romería y Etnográfica. Se celebra en Mayo (Cada diez años de forma masiva) y Septiembre. Gran relevancia comarcal; destaca su ancestral y multitudinaria romería al cerro de la Virgen del Castillo con espectaculaces danzas de jotas cuesta arriba y enramadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40031','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio. Festejos con notable concurrencia debido a su cercanía a la capital provincial, caracterizados por comidas populares de hermandad, hinchables infantiles y orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40032','fiesta','Fiestas de la Virgen del Rosario','Patronal y Taurina. Se celebra en Septiembre. Festejos de notable animación junto a la autovía A-1 con tradicionales encierros urbanos y capeas de vaquillas, concentración de peñas, jotas charras y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40033','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio y Agosto. Festejos de verano que adelantan los actos para los veraneantes, centrados en el reencuentro vecinal con campeonatos de bolos castellanos, caldereta popular y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40034','fiesta','Fiesta de las Reliquias de San Valentín (Las Mojadas de Caballar)','Etnográfica y Religiosa. Se celebra en Octubre (Y convocatorias extraordinarias por sequía). Hito etnográfico de gran singularidad; consiste en la procesión y sumersión de los cráneos de los santos hermanos en la fuente santa para pedir lluvia en épocas de sequía.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40035','fiesta','Fiestas de San Lorenzo y Feria de Artesanía El Sotillo','Patronal y Cultural. Se celebra en Agosto. Festejos dinamizados por sus activos talleres de artesanía tradicional, combinando las procesiones religiosas con mercados de creadores locales, música folk y comidas comunitarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40036','fiesta','Fiestas del Santo Cristo del Humilladero','Patronal y Taurina. Se celebra en Septiembre. Gran animación en la comarca de Cantalejo, famosa por sus tradicionales encierros y capeas urbanas de vaquillas en la plaza fija, peñas locales y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40037','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos de retorno familiar estival en Tierra de Fuentidueña con santa misa solemne, campeonatos de cartas populares en las antiguas escuelas y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40039','fiesta','Fiestas de la Virgen del Amor Hermoso','Patronal. Se celebra en Junio y Agosto (Verano). Festejos estivales muy animados en el nordeste de la provincia, con pasacalles de dulzaina, torneos deportivos populares, paellada comunitaria y grandes bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40040','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Taurina y Etnográfica. Se celebra en Agosto. Hito comarcal de gran afluencia célebre por sus tradicionales e intensos encierros urbanos y camperos, corridas de toros, desfile masivo de peñas y folclore ligado a la gacería.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40041','fiesta','Fiestas de la Inmaculada Concepción y Feria del Chorizo de Cantimpalos','Patronal, Gastronómica y Taurina. Se celebra en Agosto y Abril. Hito gastronómico provincial; destaca su feria que promociona el chorizo con I.G.P. mediante degustaciones masivas, combinada en agosto con encierros taurinos urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40043','fiesta','Fiestas de la Virgen del Bustar','Patronal, Taurina y Romería. Se celebra en Septiembre y Mayo. Hito taurino y romero de primer orden provincial; destaca por sus multitudinarios encierros camperos y urbanos de reses bravas, corridas de toros y romería tradicional.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40044','fiesta','Fiestas de la Virgen del Frutos','Patronal y Romería. Se celebra en Octubre y Agosto. Festejos muy vinculados al Parque Natural de las Hoces del Río Duratón, destacando su romería tradicional de los santos, jotas castellanas y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40045','fiesta','Fiestas de la Virgen de la Estrella','Patronal. Se celebra en Septiembre. Festejos serranos tradicionales con procesión de la patrona, subasta de banzos al son de la dulzaina, competiciones populares de cartas y orquesta en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40046','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración rural orientada al retorno estival junto al río Serrano con santa misa cantada, campeonato de chinchón y merienda popular vecinal en el frontón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40047','fiesta','Fiestas de la Inmaculada Concepción','Patronal. Se celebra en Septiembre (Adelantadas). Pequeña celebración veraniega adaptada para los descendientes del pueblo con santa misa, campeonato de bolos tradicionales femeninos y refresco en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40048','fiesta','Fiestas de la Virgen de la Esperanza','Patronal. Se celebra en Septiembre. Festejos vecinales mínimos en el oriente de la provincia condicionados por la baja demografía, limitados a oficios religiosos, juegos de naipes y cena comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40049','fiesta','Fiestas de la Virgen de los Remedios','Patronal. Se celebra en Septiembre. Pequeños festejos rurales en el valle del río San Juan con oficios religiosos tradicionales de acción de gracias, juegos infantiles y música grabada en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40053','fiesta','Fiestas de la Virgen de la Peña','Patronal. Se celebra en Septiembre y Agosto. Festejos de retorno familiar estival al pie de Somosierra, caracterizados por campeonatos tradicionales de calva, parrillada popular y baile con orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40054','fiesta','Fiestas de San Juan Bautista','Patronal y Deportiva. Se celebra en Junio y Agosto. Festejos dinamizados por su entorno de montaña cercano a la Pinilla, combinando la hoguera tradicional de San Juan con marchas de senderismo y cenas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40065','fiesta','Fiestas de la Virgen de los Remedios','Patronal y Etnográfica. Se celebra en Septiembre. Festejos en plena comarca de la Tierra de Pinares, célebres por sus tradicionales danzas de paloteo castellano frente a la patrona, grandes verbenas y paellada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40055','fiesta','Fiestas de San Mamés *','Patronal *. Se celebra en Agosto *. Festejos mínimos adaptados a la baja demografía del noreste segoviano, centrados en una santa misa comunitaria, juegos tradicionales de cartas y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40056','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Festejos veraniegos volcados en las peñas de jóvenes retornados, con meriendas populares tradicionales en los lagares y orquesta nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Taurina e Histórica. Se celebra en Agosto. Hito turístico provincial; destaca por sus espectaculares encierros taurinos nocturnos por las calles de trazado medieval, capeas junto al imponente castillo gótico-mudéjar y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40058','fiesta','Fiestas de Santo Domingo de Guzmán','Patronal. Se celebra en Agosto. Festejos tradicionales de la Campiña Segoviana con santa misa cantada, campeonatos de bolos castellanos y calva, seguidos de cenas populares colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40059','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos estivales para emigrantes que aprovechan el entorno monumental de las ruinas del Monasterio de Santa María de la Sierra, con caldereta y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40060','fiesta','Fiestas de Nuestra Señora de la Antigua','Patronal e Histórica. Se celebra en Septiembre. Agrupa los festejos de sus localidades aprovechando el marco del castillo de Castilnovo, albergando parrilladas populares y música tradicional con dulzaineros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40061','fiesta','Fiestas de la Virgen de la Leche','Patronal. Se celebra en Agosto. Pequeña festividad veraniega de carácter familiar con santa misa tradicional, competiciones infantiles en la plaza y cena popular de hermandad para vecinos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40902','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración tradicional agraria con santa misa de acción de gracias, pasacalles con tamboril y dulzaina, y actividades recreativas organizadas por los jóvenes del pueblo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','fiesta','Fiestas en honor a Nuestra Señora del Rosario (Los Encierros de Cuéllar)','Patronal y Taurina. Se celebra en Agosto. Fiesta de Interés Turístico Internacional. Son considerados los encierros más antiguos de España, documentados desde 1215; destaca el traslado masivo de los toros por el campo a caballo hasta la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40068','fiesta','Fiestas de San Juan Bautista y de Nuestra Señora del Rosario','Patronal y Arqueológica. Se celebra en Junio y Octubre. Festejos de arraigo local dinamizados en verano por las visitas a su estación de arte rupestre, con santa misa, campeonatos de tusa y bailes en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40069','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Celebración estival de carácter familiar en el límite con la provincia de Ávila, con santa misa, juegos tradicionales para niños y música discomóvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40070','fiesta','Fiestas del Santo Cristo de la Esperanza','Patronal. Se celebra en Septiembre y Agosto (Verano). Festejos adelantados para los emigrantes retornados, con pasacalles de dulzaina, torneos populares de mus y chinchón, y una gran caldereta vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40071','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Pequeña festividad veraniega adaptada a la baja demografía del norte provincial, centrada en un almuerzo comunitario y campeonatos de cartas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40072','fiesta','Fiestas de San Vicente y de la Virgen del Rosario','Patronal y Cultural. Se celebra en Enero y Octubre. Festejos en crecimiento debido a su cercanía residencial a la capital, con una gran paellada popular, hinchables para niños y verbenas populosas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40073','fiesta','Fiestas de la Virgen de la Cruz','Patronal y Etnográfica. Se celebra en Septiembre. Notable relevancia comarcal gracias a las ancestrales danzas de paloteo e indumentarias tradicionales frente a la patrona, seguidas de grandes verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40074','fiesta','Fiestas de San Benito Arcángel','Patronal. Se celebra en Septiembre y Agosto. Festejos tradicionales de la campiña centrados en la procesión del santo con subasta de banzos, competiciones de calva y bailes con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40075','fiesta','Fiestas de San Martín y de la Virgen de la Chasca','Patronal. Se celebra en Noviembre y Agosto. Festejos estivales sencillos que agrupan a sus distintas pedanías en una jornada de hermandad con juegos tradicionales y cena vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40076','fiesta','Fiesta de la Virgen de la Fuencisla y Fiesta de los Gabarreros','Patronal, Etnográfica y Cultural. Se celebra en Septiembre y Marzo. La Fiesta de los Gabarreros está declarada de Interés Turístico Regional; rememora el ancestral oficio forestal con exhibiciones de corta de troncos, arrastre y folklore serrano.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40077','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto (Verano). Festejos metropolitanos con masiva afluencia juvenil, caracterizados por grandes orquestas nocturnas, torneos deportivos y una gran comida comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40078','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Agosto. Celebración de la comarca cuellarana orientada al retorno familiar con santa misa solemne, pasacalles al son de la dulzaina y competiciones de naipes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40080','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Sencillos festejos veraniegos junto a la autovía del norte, centrados en los actos religiosos tradicionales, juegos para niños y una chocolatada popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40079','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Romería. Se celebra en Septiembre. Festejos de gran arraigo histórico que incluyen romería tradicional a la ermita del Cristo, canto de jotas, parrillada popular y música orquestal en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40082','fiesta','Fiestas del Santo Cristo del Calvario','Patronal. Se celebra en Mayo y Agosto (Verano). Celebración rural centrada en las peñas de jóvenes retornados, con meriendas tradicionales en bodegas excavadas y baile público por las noches.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40083','fiesta','Fiestas de San Bernardo','Patronal. Se celebra en Agosto. Festejos veraniegos que dinamizan el oriente de la provincia, con pasacalles, campeonatos de bolos castellanos femeninos y orquesta en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40084','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Festejos típicos de la Tierra de Pinares con bendición tradicional de vehículos, juegos tradicionales de cartas, cena popular vecinal y discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40086','fiesta','Fiestas de la Virgen de la Asunción y Feria Ángel de la Guarda','Patronal, Taurina y Feria de Muestras. Se celebra en Agosto y Marzo. Gran relevancia comarcal debido a su potente e histórica feria de maquinaria y su desfile de carrozas veraniego, complementado con tradicionales encierros urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40088','fiesta','Fiestas de San Roque y Nuestra Señora de la Asunción','Patronal y Etnográfica. Se celebra en Agosto. Notable animación en Tierra de Pinares potenciada por sus lagunas, con tradicionales danzas de jotas al son del tamboril, grandes verbenas y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40089','fiesta','Fiestas de Santo Domingo de Guzmán','Patronal. Se celebra en Agosto. Festejos veraniegos muy populosos entre los emigrantes de la comarca, caracterizados por meriendas en lagares tradicionales, campeonatos de cartas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40091','fiesta','Fiestas de San Vicente Mártir','Patronal y Romería. Se celebra en Enero y Agosto (Verano). Destaca la romería estival a la ermita románica de San Vicente, acompañada por dulzaineros locales, comidas populares y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','fiesta','Fiestas de la Virgen de la Alborada','Patronal e Histórica. Se celebra en Septiembre. Pone en valor su monumental villa murada medieval, albergando procesiones solemnes, cánticos tradicionales de alborada, jotas castellanas y verbenas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40093','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeñas fiestas serranas tradicionales centradas en los oficios religiosos de la Asunción, competiciones infantiles y música grabada en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40094','fiesta','Fiestas de la Virgen del Pópulo','Patronal. Se celebra en Septiembre. Festejos tradicionales de la campiña segoviana con santa misa solemne, subasta de banzos de la patrona, campeonatos de cartas y bailes con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40095','fiesta','Fiestas de San Antonio de Padua','Patronal y Etnográfica. Se celebra en Junio y Agosto. Festejos muy animados en el Carracillo con tradicionales danzas de paloteo castellano, parrillada popular comunitaria y animadas verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40097','fiesta','Fiestas de San Vitores','Patronal y Deportiva. Se celebra en Agosto. Festejos condicionados por su potente infraestructura de turismo activo y ocio, con torneos de Paintball populares, paellada comunitaria y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40099','fiesta','Fiestas de la Virgen de Luján *','Patronal *. Se celebra en Julio y Agosto *. Pequeños festejos veraniegos en el límite con Burgos, centrados en el reencuentro de familias nativas con campeonato de cartas y juegos para niños.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40100','fiesta','Fiestas de San Pedro de Cátedra','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Festejos estivales en Tierra de Pinares célebres por su suelta de vaquillas en plaza portátil, encierro infantil de carretones, chocolatada popular y orquesta.','inventario_fiestas_pdf');
