INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40103','fiesta','Fiestas de Nuestra Señora de las Vegas','Patronal y Romería. Se celebra en Septiembre. Tradicional romería a orillas del río Eresma con procesión religiosa, subasta de banzos al son de la dulzaina, meriendas vecinales y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40110','fiesta','Fiestas de El Salvador','Patronal y Etnográfica. Se celebra en Agosto. Festejos en la Tierra de Pinares famosos por sus bailes de jotas tradicionales al son del tamboril, grandes verbenas en la plaza mayor y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40111','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en el poniente provincial adaptada a la baja demografía, con santa misa, campeonato de mus y refresco para los residentes estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40112','fiesta','Fiestas de San Juan Bautista y el Santo Cristo de la Agonía','Patronal y Cultural. Se celebra en Junio y Agosto. Hito en el área metropolitana debido a su gran explosión demográfica; atrae masivamente a la juventud con sus potentes macroverbenas, desfiles de peñas y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','fiesta','Fiestas de Nuestra Señora de Castroboda y Siglo XII Medieval','Histórica, Recreación y Patronal. Se celebra en Septiembre y Agosto. Gran joya medieval fortificada sobre el embalse de Linares; su recreación del Siglo XII atrae a miles de turistas con mercados de época, desfiles de caballeros y arqueros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40903','fiesta','Fiestas de San Juan Evangelista','Patronal. Se celebra en Agosto (Adelantadas). Festejos veraniegos para emigrantes en la campiña con santa misa solemne, tradicionales competiciones de calva y bolos castellanos, y cena popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40118','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración de carácter familiar orientada al turismo estival con procesión de la patrona, campeonatos de cartas populares en las antiguas escuelas y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40119','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos en la campiña baja con pasacalles de dulzaineros locales, campeonatos de calva y bolos charros, seguidos de una parrillada de hermandad vecinal.','inventario_fiestas_pdf');
