INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40124','fiesta','Fiestas de San Esteban Protomártir','Patronal. Se celebra en Agosto (Adelantadas). Festejos veraniegos en el límite con Valladolid con procesión solemne, tradicionales campeonatos de cartas, comidas comunitarias de peñas y bailes nocturnos.','inventario_fiestas_pdf');
