INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40134','fiesta','Fiestas de San Roque y Nuestra Señora de the Asunción','Patronal y Taurina. Se celebra en Agosto. Gran animación en la comarca del Pirón, famosa por sus encierros urbanos tradicionales de reses bravas por las calles, concurso de peñas locales y verbenas de primer nivel.','inventario_fiestas_pdf');
