INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40141','fiesta','Fiestas de San Roque y la Virgen de la Asunción','Patronal y Taurina. Se celebra en Agosto. Gran animación en la comarca del Carracillo, famosa por sus tradicionales y peligrosos encierros de toros urbanos por las calles, masivo desfile de peñas locales y verbenas de primer nivel.','inventario_fiestas_pdf');
