INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40166','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Festejos veraniegos en el límite con la provincia de Valladolid con procesión solemne, tradicionales campeonatos de calva, cenas de peñas y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40168','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto [1] *. Pequeña festividad veraniega de carácter familiar en el nordeste de la provincia, centrada en la santa misa tradicional, campeonato de mus y cena popular de hermandad.','inventario_fiestas_pdf');
