INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40172','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeñas fiestas de montaña rodeadas de hayedos en el límite con Guadalajara, con oficios religiosos tradicionales de la Asunción, parrillada popular y música en la plaza.','inventario_fiestas_pdf');
