INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40176','fiesta','Fiestas de San Baudilio y de la Virgen del Carmen','Patronal. Se celebra en Mayo y Julio. Festejos en la Tierra de Pinares junto al río Carrarión con procesión mudéjar, campeonatos de bolos castellanos, cenas vecinales de hermandad y bailes populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40177','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Festejos tradicionales de la comarca cuellarana con bendición de vehículos, campeonatos de cartas populares en el teleclub, parrillada vecinal y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40178','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio y Agosto. Celebración en el oeste de la provincia orientada al retorno de familias nativas con santa misa solemne, campeonato de calva y cena de hermandad en el frontón.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40906','fiesta','Fiestas de San Cristóbal y Nuestra Señora del Rosario','Patronal y Cultural. Se celebra en Julio y Octubre. Municipio de gran crecimiento segregado de la capital; destaca por su masiva concentración de peñas, potentes macroverbenas musicales en la plaza, paellada masiva e hinchables infantiles). ¿Puedo continuar con el siguiente bloque de la provincia de Segovia?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40182','fiesta','Fiestas de San Martín y la Virgen del Rosario','Patronal. Se celebra en Noviembre y Agosto (Verano). Festejos estivales de gran animación en la Tierra de Pinares, organizados para la población flotante con torneos deportivos, cenas de peñas y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40183','fiesta','Fiestas de San Miguel Arcángel','Patronal y Deportiva. Se celebra en Septiembre y Agosto. Festejos dinamizados por su entorno fluvial a orillas del río Duratón, que combinan las tradicionales procesiones con piragüismo lúdico, caldereta popular y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40184','fiesta','Fiestas de San Juan Bautista y Nuestra Señora de la Natividad','Patronal y Etnográfica. Se celebra en Junio y Septiembre. Relevancia comarcal por su hito etnográfico ligado a las tradicionales danzas de paloteo castellano, pasacalles al son de dulzaineros y su potente Centro de Interpretación del Folklore.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40180','fiesta','Fiestas de San Bartolomé','Patronal y Etnográfica. Se celebra en Agosto. Festejos tradicionales de la Campiña Segoviana vinculados históricamente a la tradición de los arrieros, con santa misa solemne, campeonatos de cartas, comidas vecinales y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40185','fiesta','Fiestas de la Virgen de la Soterraña','Patronal, Etnográfica y Taurina. Se celebra en Septiembre. Gran empaque comarcal que destaca por la procesión de los cirios y las ofrendas tradicionales, la suelta de vaquillas en su histórica plaza de toros y verbenas multitudinarias en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40186','fiesta','Fiestas de Santa Marta','Patronal. Se celebra en Julio y Agosto. Pequeña festividad vecinal al pie de la autovía del norte, centrada en los oficios religiosos en su templo románico, campeonato de naipes en el teleclub y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40191','fiesta','Fiestas de la Virgen de la Natividad','Patronal. Se celebra en Septiembre y Agosto. Festejos en el núcleo de Villarejo al pie del puerto de Somosierra, caracterizados por campeonatos de calva, comidas populares comunitarias y verbenas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40192','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Pequeños festejos rurales adaptados a la baja demografía invernal, centrados en actos religiosos tradicionales, campeonatos de cartas en el teleclub y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40193','fiesta','Fiestas de San Miguel Arcángel','Patronal y Romería. Se celebra en Septiembre y Mayo. Festejos condicionados por su ubicación en el Parque Natural de las Hoces del Duratón, destacando la romería tradicional a las ruinas del Convento de la Hoz, caldereta y jotas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40194','fiesta','Ferias y Fiestas de San Juan y San Pedro, y Semana Santa de Segovia','Patronal, Cultural, Taurina y Religiosa. Se celebra en Junio y Marzo/Abril. Hito masivo de impacto nacional; su Semana Santa destaca por las espectaculares procesiones con el Acueducto romano de fondo. En San Juan y San Pedro se celebran grandes conciertos, corridas de toros, ferias de folklore y fuegos artificiales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','fiesta','Fiesta de los Fueros de Sepúlveda y Fiestas de los Toros en honor a la Virgen de la Peña','Histórica, Recreación, Patronal y Taurina. Se celebra en Julio y Agosto. Festividad de gran relevancia; la Fiesta de los Fueros rememora su esplendor medieval vistiendo la villa con antorchas y mercados. Sus encierros taurinos de agosto son de los más antiguos y famosos de la provincia.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40198','fiesta','Fiestas de la Virgen de la Natividad','Patronal. Se celebra en Septiembre. Sencillos festejos rurales en la comarca de Sepúlveda centrados en los actos litúrgicos tradicionales, juegos infantiles en la plaza de la iglesia y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40199','fiesta','Fiestas de Nuestra Señora de la Sierra','Patronal, Romería e Histórica. Se celebra en Agosto. Notable afluencia turística potenciada por su monumental iglesia románica, combinando las tradicionales misas y subastas de banzos con comidas comunitarias serranas y conciertos folk). ¿Puedo continuar con el siguiente bloque de la provincia de Segovia para avanzar hacia el final de su índice alfabético?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40200','fiesta','Fiestas de San Juan Bautista y de Nuestra Señora del Rosario','Patronal. Se celebra en Junio y Octubre. Festejos estivales para retornados en la comarca del Pirón, con santa misa cantada, campeonatos de cartas en el teleclub y baile público con disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40201','fiesta','Fiestas de San Pedro en Cátedra','Patronal. Se celebra en Febrero y Agosto (Verano). Festejos de escala estrictamente local adaptados para los veraneantes, con oficios religiosos tradicionales, competiciones infantiles en el frontón y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40206','fiesta','Fiestas de Santa Ana','Patronal. Se celebra en Julio. Celebración serrana muy concurrida por el turismo rural, con pasacalles de dulzaina y tamboril, tradicionales campeonatos de calva, parrillada popular y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40205','fiesta','Fiestas de Santiago Apóstol y la Virgen del Pilar','Patronal y Romería. Se celebra en Julio y Octubre. Notable arraigo comarcal que incluye la tradicional romería a la ermita de Santiago en el cañón del río Viejo, subasta de banzos al son de jotas castellanas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40207','fiesta','Fiestas del Santo Cristo del Amparo','Patronal y Cultural. Se celebra en Septiembre. Municipio metropolitano al pie de la sierra con gran afluencia de jóvenes, caracterizado por una concentración de peñas, variadas actividades infantiles y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40211','fiesta','Fiestas de Santa Eulalia','Patronal. Se celebra en Agosto (Adelantadas). Pequeña festividad vecinal bajo la silueta de su torreón fortificado, centrada en los oficios religiosos de la patrona, campeonato de mus y merienda popular de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40212','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Festejos estivales mínimos condicionados por la baja demografía en el entorno de las Hoces del Riaza, reducidos a actos litúrgicos, naipes y un almuerzo comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40213','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto. Festejos rurales tradicionales en la comarca de Pedraza con santa misa cantada, campeonato de bolos tradicionales castellanos y música grabada para los residentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40218','fiesta','Fiestas de la Inmaculada Concepción','Patronal y Etnográfica. Se celebra en Septiembre (Adelantadas). Festejos vinculados a su pasado minero de extracción de yeso, combinando los actos religiosos con meriendas tradicionales en los lagares subterráneos y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40219','fiesta','Fiestas de Santo Tomás Apóstol y la Virgen del Rosario','Patronal, Taurina y Gastronómica. Se celebra en Julio y Septiembre. Gran animación en la comarca de Cuéllar; destaca por sus encierros urbanos tradicionales de toros, torneos de pelota mano y degustaciones de su afamado ajo de Vallelado.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40220','fiesta','Fiestas de San Cristóbal','Patronal. Se celebra en Julio. Sencillos festejos veraniegos con la tradicional bendición de vehículos en la comarca de Pedraza, juegos infantiles, campeonato de mus y discomóvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40221','fiesta','Fiestas de la Virgen de la Velilla','Patronal y Romería. Se celebra en Septiembre. Romería tradicional a la ermita de la Virgen con procesión religiosa, subasta de banzos al son de la dulzaina, caldereta popular vecinal y baile en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40214','fiesta','Fiestas de San Antonio de Padua y Feria del Garbanzo de Valseca','Patronal y Gastronómica. Se celebra en Junio y Agosto. Hito gastronómico provincial; destaca su feria que promociona el garbanzo local mediante una masiva cocedura y degustación popular, combinada en verano con grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40216','fiesta','Fiestas de Nuestra Señora de la Aparecida','Patronal y Etnográfica. Se celebra en Septiembre. Gran relevancia en la comarca de la campiña, célebre por sus tradicionales danzas de paloteo frente a la patrona, desfile de peñas, comidas vecinales y orquestas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40222','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos veraniegos volcados en las peñas de jóvenes en la comarca del Duratón, caracterizados por pasacalles con charangas, campeonato de calva y grandes bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40223','fiesta','Fiestas de la Virgen del Rosario','Patronal y Etnográfica. Se celebra en Septiembre y Agosto. Festejos tradicionales vinculados a su pasado artesanal de los hornos de cal, con procesión de la patrona con subasta, caldereta popular y verbenas muy animadas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40224','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos vecinales mínimos adaptados a la baja demografía invernal, reducidos a una santa misa comunitaria, campeonato de naipes en el teleclub y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40225','fiesta','Fiestas en honor a San Sebastián y de la Virgen del Carrascal','Patronal y Taurina. Se celebra en Enero y Agosto. Hito comarcal de gran afluencia; destaca por sus tradicionales encierros urbanos de reses bravas por su casco histórico, capeas en su plaza de toros fija y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40228','fiesta','Fiestas de San Sebastián','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Festejos en plena Tierra de Pinares célebres por su suelta de vaquillas en plaza portátil, encierro infantil de carretones, chocolatada popular y orquesta en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40229','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Pequeña celebración de carácter familiar orientada al turismo estival con procesión, campeonatos de cartas populares en las escuelas y cena popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40230','fiesta','Fiestas de San Antonio de Padua','Patronal y Taurina. Se celebra en Junio y Agosto. Festejos de retorno veraniego en el límite con Valladolid, caracterizados por capeas de vaquillas en coso portátil, cenas comunitarias de peñas y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40231','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración en la llanura del río Eresma con santa misa cantada, campeonato de calva y bolos castellanos, seguidos de una cena popular comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40233','fiesta','Fiestas de la Virgen de la Redonda','Patronal y Etnográfica. Se celebra en Agosto. Gran animación estival; destaca por las tradicionales danzas de jotas al son de la dulzaina frente a la patrona, concurso de carrozas, parrillada popular y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40234','fiesta','Fiestas de la Exaltación de la Santa Cruz','Patronal. Se celebra en Septiembre *. Festejos de carácter tradicional agrario en la Tierra de Pinares con santa misa de acción de gracias, pasacalles con tamboril, campeonato de mus y orquesta nocturna). Con este bloque completamos oficialmente todos los municipios de la provincia de Segovia. ¿Podemos continuar con la siguiente provincia de Castilla y León (Provincia de Soria)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90806','fiesta','Fiesta de la Barrosa y Fiestas de la Virgen del Camino','Etnográfica, Patronal y Gastronómica. Se celebra en Febrero (Carnaval) y Agosto. Destaca la Fiesta de la Barrosa por su inmenso valor etnográfico soriano, donde los quintos portan un armazón que imita a un toro mientras realizan danzas ancestrales y ritos agrarios.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41011','fiesta','Fiestas de la Virgen de los Milagros y Fiestas de San Miguel (Los Toros del Cajón)','Patronal, Religiosa y Taurina. Se celebra en Junio y Septiembre. Fiesta de Interés Turístico Regional con gran empaque moncaíno, famosa por la masiva romería de los diecisiete pueblos de la comarca, sus tradicionales encierros y los famosos toros del cajón.','inventario_fiestas_pdf');
