INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90274','fiesta','Fiestas del Santo Cristo del Campillo','Patronal y Romería. Se celebra en Septiembre y Agosto (Verano). Festejos de retorno veraniego que incluyen una tradicional romería a la ermita del Cristo, campeonatos de bolos femeninos, caldereta popular y verbena nocturna.','inventario_fiestas_pdf');
