INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90276','fiesta','Fiestas de Santa María Magdalena','Patronal. Se celebra en Agosto (Adelantadas). Festejos de escala estrictamente local debido a la despoblación del cordón serrano, limitados a oficios religiosos de acción de gracias y un aperitivo vecinal.','inventario_fiestas_pdf');
