INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90278','fiesta','Fiestas de la Virgen de la Blanca','Patronal. Se celebra en Agosto. Celebración de retorno familiar estival junto a su histórico torreón fortificado, con santa misa solemne, campeonatos tradicionales de calva y música disco.','inventario_fiestas_pdf');
