INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90280','fiesta','Fiestas de la Virgen de la Asunción y Fiesta de la Trashumancia','Etnográfica y Patronal. Se celebra en Agosto. Notable arraigo en las Tierras Altas sorianas, potenciado por jornadas culturales que rememoran el pasado ganadero merino, exhibiciones de esquileo y caldereta serrana.','inventario_fiestas_pdf');
