INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42019','fiesta','Fiesta del Traslado de la Virgen de los Santos (Fiesta de las Arcas)','Etnográfica, Patronal y Romería. Se celebra en Julio y Noviembre. Hito etnográfico tradicional de gran singularidad; consiste en el ritual centenario donde los pueblos de Almarza y San Andrés se reúnen para trasladar la imagen compartida de la Virgen.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42020','fiesta','Fiestas de la Bajada de Jesús Nazareno','Patronal, Religiosa y Taurina. Se celebra en Septiembre. Festividad de Interés Turístico Regional de enorme impacto masivo; destaca el sobrecogedor momento nocturno de la procesión bajo una espectacular salva de fuegos artificiales, encierros y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42021','fiesta','Fiestas de la Virgen de la Blanca','Patronal. Se celebra en Agosto. Festejos veraniegos volcados en el reencuentro de familias nativas en el Campo de Gómara, con pasacalles, campeonatos de bolos castellanos y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42022','fiesta','Fiestas de la Virgen de Llana','Patronal e Histórica. Se celebra en Agosto. Festejos que aprovechan el marco monumental de su imponente castillo medieval fortificado, albergando comidas populares de hermandad, jotas tradicionales sorianas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42023','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Septiembre y Agosto. Pequeñas fiestas de verano adaptadas a la baja demografía de la comarca de Medinaceli, centradas en una santa misa, campeonato de tusa y aperitivo comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42024','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración de carácter tradicional agraria con santa misa de acción de gracias, pasacalles al son de los dulzaineros, cena vecinal de hermandad y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42025','fiesta','Fiestas del Santo Cristo de la Buena Muerte','Patronal, Taurina y Ferroviaria. Se celebra en Septiembre. Gran relevancia comarcal en el valle del Jalón; destaca por sus concurridos encierros urbanos de vaquillas, concurso de carrozas, masiva concentración de peñas y verbenas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42026','fiesta','Fiestas de San Cipriano y Festival de Música Rural "Boina Fest"','Cultural, Patronal y Vanguardia Rural. Se celebra en Agosto. Hito contra la despoblación; su singular festival de música enfocado en visibilizar artistas de zonas despobladas atrae a cientos de visitantes que acampan y dinamizan el entorno rural.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42027','fiesta','Fiesta del Santo Cristo de los Remedios','Patronal y Romería. Se celebra en Agosto. Festejos serranos condicionados por su cercanía al monumental Acebal de Garagüeta, combinando las tradicionales misas con comidas comunitarias campestres y bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42028','fiesta','Fiestas de la Virgen del Almuerzo','Patronal. Se celebra en Agosto (Adelantadas). Pequeña festividad veraniega de carácter familiar con santa misa tradicional, competiciones infantiles en la plaza de las escuelas y refresco vecinal.','inventario_fiestas_pdf');
