INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42030','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos de retorno familiar estival a orillas del río Duero, caracterizados por santa misa cantada, campeonato de calva y merienda popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42032','fiesta','Fiestas del Santo Cristo de los Remedios','Patronal y Etnográfica. Se celebra en Agosto. Festejos en plena comarca de pinares, caracterizados por pasacalles tradicionales con dulzaina y tamboril, torneos de frontón, caldereta popular y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42033','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos vecinales mínimos en Tierra de Berlanga condicionados por la despoblación, que incluyen santa misa cantada, campeonato de chinchón y merienda comunitaria.','inventario_fiestas_pdf');
