INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42055','fiesta','Fiestas de San Ildefonso y la Virgen de la O (Las Danzas de Casarejos)','Etnográfica y Patronal. Se celebra en Enero y Agosto (Verano). Gran valor folclórico en la comarca de Pinares; destaca por sus espectaculares y ancestrales danzas de paloteo interpretadas dentro del templo al son de la dulzaina.','inventario_fiestas_pdf');
