INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42106','fiesta','Fiestas de la Virgen del de la Blanca','Patronal. Se celebra en Agosto [1] *. Pequeñas fiestas estivales de carácter estrictamente vecinal, con santa misa, campeonato de naipes y refresco para los residentes estivales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42107','fiesta','Fiestas de la Virgen de Barruso','Patronal e Histórica. Se celebra en Agosto. Festejos bajo el imponente castillo medieval de Magaña de las Tierras Altas, con procesión de la patrona, jotas castellanas y caldereta popular de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42108','fiesta','Fiestas de la Virgen del del Rosario','Patronal. Se celebra en Septiembre y Agosto. Festejos vecinales mínimos condicionados por la baja demografía cerealista, reducidos a una santa misa comunitaria, naipes y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42110','fiesta','Fiestas de la Virgen del del Rosario y San Blas','Patronal. Se celebra en Agosto (Adelantadas). Celebración de retorno familiar en la comarca del Moncayo con santa misa cantada, campeonatos de cartas populares en la taberna y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42111','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y forestal. Se celebra en Agosto. Festejos muy vinculados a la industria de la resina de sus pinares, caracterizados por pasacalles tradicionales con dulzaina, caldereta popular y grandes bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42113','fiesta','Fiesta del Toro de Júbilo y Fiestas del Culto al de la Inmaculada','Etnográfica, Taurina e Histórica. Se celebra en Noviembre y Agosto. El Toro de Júbilo está declarado Fiesta de Interés Turístico Regional; es un rito nocturno ancestral único donde se cubre a un toro con astas de barro y fuego en su monumental plaza mayor gótica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42115','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Festejos veraniegos para emigrantes centrados en los oficios religiosos en su entorno de parameras, campeonato de mus y cena vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42116','fiesta','Fiestas de San Martín','Patronal y Enológica. Se celebra en Agosto (Adelantadas). Festejos potenciados por sus lagares de la D.O. Ribera del Duero, combinando la procesión tradicional con catas populares de vino y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42117','fiesta','Fiestas del Santo Cristo de la Buena Guía y la Pingada del Mayo','Etnográfica y Patronal. Se celebra en Mayo y Julio. Notable valor estético e identitario en Pinares; los mozos levantan el colosal pino pringado entre casonas de piedra tradicionales carretiles, con grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42118','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos vecinales mínimos adaptados a la baja demografía de la comarca de Almazán, limitados a oficios religiosos tradicionales, campeonato de naipes y aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42119','fiesta','Fiestas de la Virgen de la Bienvenida','Patronal e Histórica. Se celebra en Agosto. Pone en valor su recinto medieval amurallado bajo su palacio gótico, albergando procesiones solemnes, desfile humorístico de peñas, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42120','fiesta','Fiestas de Nuestra Señora de Tiermes y Romería Arqueológica','Arqueológica, Romería y Patronal. Se celebra en Mayo y Agosto. Gran valor histórico; su romería se celebra en la histórica ermita románica anexa a la colosal ciudad celtíbero-romana de Tiermes excavated en roca, atrayendo a toda la comarca.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42121','fiesta','Fiestas de la Virgen de la Blanca','Patronal y Etnográfica. Se celebra en Agosto. Único pueblo soriano de la comarca camerana, caracterizado por sus pasacalles tradicionales con gaita y tamboril, torneos de frontón vasco, caldereta serrana y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42123','fiesta','Fiestas de San Juan Bautista y de Nuestra Señora de la Asunción','Patronal e Histórica. Se celebra en Junio y Agosto. Festejos que aprovechan el bellísimo e histórico marco renacentista de su plaza mayor porticada, albergando parrilladas populares, conciertos folk y música orquestal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42124','fiesta','Fiestas de la Virgen del Valle','Patronal y Paisajística. Se celebra en Septiembre y Agosto. Festejos dinamizados por el turismo de naturaleza de la Fuentona y el Sabinar de Calatañazor, que combinan las procesiones tradicionales con paelladas colectivas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42125','fiesta','Fiestas de San Roque','Patronal y Astronómica. Se celebra en Agosto. Festejos de pinares potenciados por su certificación como Destino Turístico Starlight, ofreciendo observaciones astronómicas populares nocturnas, caldereta y bailes). ¿Puedo continuar con el siguiente bloque de la provincia de Soria?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42127','fiesta','Fiestas de la Virgen de la Antigua','Patronal y Paisajística. Se celebra en Agosto. Festejos estivales sencillos condicionados por el entorno del Cañón del Río Lobos, con santa misa tradicional, campeonato de cartas en el teleclub y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42128','fiesta','Fiestas de la Virgen de la Alharilla','Patronal. Se celebra en Agosto. Pequeña celebración rural en la comarca de Almarza adaptada a la baja demografía, con oficios litúrgicos tradicionales, juegos infantiles de plaza y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42129','fiesta','Fiestas del Niño Jesús y de la Virgen del Rosario (La Pingada del Mayo)','Etnográfica, Patronal y Micológica. Se celebra en Enero y Agosto. Notable relevancia en la comarca de pinares; destaca por la ancestral pingada del mayo por parte de los mozos, conciertos folclóricos, caldereta popular serrana y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42130','fiesta','Fiestas de San Adrián','Patronal. Se celebra en Agosto (Adelantadas). Festejos vecinales mínimos en la comarca de Almazán condicionados por la despoblación, que incluyen santa misa cantada, campeonato de chinchón y merienda comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42131','fiesta','Fiestas de San Clemente','Patronal. Se celebra en Agosto (Adelantadas). Festejos adelantados al verano para los emigrantes retornados, con procesión tradicional por las calles del casco urbano, campeonatos de mus y refresco en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42132','fiesta','Fiestas de la Virgen del Remedio y Jornadas de Gustavo Adolfo Bécquer','Patronal, Cultural e Histórica. Se celebra en Agosto. Gran animación al pie del Moncayo, dinamizada por las rutas culturales en honor a Bécquer que combinan las procesiones con lecturas poéticas, teatro de época y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41007','fiesta','Fiestas de el Santo Cristo de la Cruz a Cuestas','Patronal, Taurina y Gastronómica. Se celebra en Septiembre. Gran hito y motor industrial del Moncayo soriano; destaca por sus tradicionales encierros y capeas de reses bravas por las calles, el desfile masivo de peñas, verbenas multitudinarias y comidas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42135','fiesta','Fiesta del Acebo de Oncala y Fiestas de San Millán','Etnográfica, Paisajística y Feria de Muestras. Se celebra en Diciembre y Agosto. Hito tradicional de gran relevancia invernal en las Tierras Altas, célebre por su mercado de artesanía del acebo, representación en vivo de oficios trashumantes y degustación de migas serranas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42139','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Pequeña festividad vecinal reducida debido a la despoblación en el Campo de Gómara, centrada en una santa misa comunitaria, naipes en el teleclub y aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42140','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos estivales de escala estrictamente local debido a la baja demografía, limitados a oficios religiosos tradicionales, campeonato de mus y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42142','fiesta','Fiestas de San Juan Bautista y de Nuestra Señora del Rosario','Patronal. Se celebra en Junio y Octubre. Celebración de carácter tradicional agraria con santa misa, campeonato de bolos tradicionales castellanos, cena popular de hermandad y música disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42144','fiesta','Fiestas de San Juan Bautista y de Nuestra Señora de la Asunción','Patronal y Etnográfica. Se celebra en Junio y Agosto. Notable relevancia comarcal famosa por su artesanía tradicional de alfarería negra, combinando las procesiones litúrgicas con ferias de barro, comidas populares y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42145','fiesta','Fiestas de San Lorenzo','Patronal y Paisajística. Se celebra en Agosto. Festejos de retorno familiar estival junto al paraje resinero de los pinares, caracterizados por santa misa solemne, campeonatos tradicionales de calva y caldereta vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42148','fiesta','Fiestas de la Virgen de la Blanca','Patronal. Se celebra en Agosto. Festejos veraniegos mínimos adaptados a la baja demografía de la comarca de las Vicarías, limitados a oficios religiosos tradicionales, chinchón y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42151','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal. Se celebra en Septiembre y Agosto. Celebración de carácter familiar orientada al turismo estival en el valle de la cuenca alta del Duero, con procesión, campeonato de mus y parrillada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42152','fiesta','Fiestas de San Bernardino de Siena','Patronal. Se celebra en Mayo y Agosto (Verano). Festejos de retorno veraniego en la Tierra de Berlanga con santa misa cantada, campeonatos de cartas populares en las escuelas y meriendas en bodegas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42153','fiesta','Fiestas de la Virgen de las Angustias','Patronal e Histórica. Se celebra en Agosto. Festejos que aprovechan el espectacular marco rústico de su conjunto histórico amurallado sobre el risco, con caldereta popular comunitaria y bailes al son de la dulzaina.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42154','fiesta','Fiestas de San Lorenzo','Patronal y Arqueológica. Se celebra en Agosto. Festejos dinamizados por el entorno arqueológico de los campamentos romanos de Numancia, combinando las tradicionales misas con comidas comunitarias campestres y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42155','fiesta','Fiestas de San Pedro Apóstol','Patronal e Histórica. Se celebra en Junio y Agosto. Festejos que ponen en valor su fisonomía rústica medieval amurallada, albergando procesiones solemnes, campeonatos tradicionales de calva, comidas populares y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42156','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos vecinales mínimos condicionados por la baja demografía cerealista del Campo de Gómara, reducidos a una santa misa comunitaria, naipes y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42158','fiesta','Fiestas de la Virgen del Barrio','Patronal y Cultural. Se celebra en Agosto. Festejos veraniegos para emigrantes que aprovechan el entorno de su villa romana y su centenario sabinar, con procesión solemne, tradicionales campeonatos de cartas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42159','fiesta','Fiestas de San Sebastián','Patronal. Se celebra en Enero y Agosto (Verano). Pequeña festividad vecinal en el valle del Tera adaptada a la demografía estival, centrada en una santa misa comunitaria, juegos tradicionales de cartas y cena popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42160','fiesta','Fiestas de Nuestra Señora del Castillo y de la Virgen de la Vega','Patronal y Etnográfica. Se celebra en Agosto. Notable animación en el valle soriano al pie de la Sierra de Carcaña, con tradicionales danzas de jotas al son del tamboril, grandes verbenas, caldereta popular y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42161','fiesta','Fiestas de la Virgen de la Nieves y del Santo Cristo','Patronal y Etnográfica. Se celebra en Agosto *. Notable relevancia estética en la comarca de pinares; destaca por su procesión junto al río Duero flanqueada por casonas de piedra tradicionales, caldereta serrana y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','fiesta','Fiestas de la Virgen del Rivero y del Santo Cristo de la Buena Dicha','Patronal, Taurina y Enológica. Se celebra en Septiembre. Fiesta de Interés Turístico Regional de gran empaque en la Ribera del Duero soriana; destaca por sus monumentales encierros por las calles medievales, novilladas, peñas y apertura de sus cientos de bodegas tradicionales subterráneas excavadas en el cerro.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42163','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Pequeña festividad veraniega de carácter familiar en el límite con La Rioja, centrada en la santa misa tradicional, campeonato de mus y cena popular de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42164','fiesta','Fiestas de San Leonardo y las Danzas del de Paloteo','Etnográfica, Patronal y Taurina. Se celebra en Enero/Febrero y Julio. Hito folclórico de primer orden provincial; destaca por sus ancestrales, vistosas y complejas danzas de paloteo e indumentaria tradicional ejecutadas dentro del templo de origen celtíbero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42165','fiesta','Fiestas de San Juan Bautista y el de Paso del Fuego','Etnográfica, Patronal y Romería. Se celebra en Junio. Fiesta de Interés Turístico Nacional de enorme impacto global; su ancestral rito nocturno del Paso del Fuego consiste en cruzar descalzo un manto de brasas de roble ardiendo, portando a las rústicas Móndidas vestidos de blanco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42166','fiesta','Fiestas de la Virgen del de la Asunción','Patronal y Paleontológica. Se celebra en Agosto. Pequeñas fiestas de montaña en las Tierras Altas rodeadas de yacimientos de icnitas de dinosaurio, con oficios religiosos tradicionales de la Asunción, parrillada popular y música.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42168','fiesta','Fiestas del Santo Cristo de la Miranda','Patronal y Romería. Se celebra en Mayo y Agosto. Tradicional romería al límite del Parque Natural del Cañón del Río Lobos, acompañada por pasacalles de dulzaineros, caldereta popular comunitaria y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42171','fiesta','Fiestas de la Virgen de la Vega','Patronal y Taurina. Se celebra en Septiembre y Agosto. Gran animación en la cuenca del Nágima bajo los restos de su castillo de tapial mudéjar, célebre por su suelta de vaquillas en plaza portátil, concurso de peñas locales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42172','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Octubre y Agosto. Festejos de verano mínimos adaptados a la baja demografía en la comarca de Almazán, centrados en una misa comunitaria, juegos tradicionales de cartas y cena vecinal de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42173','fiesta','Fiestas de San Juan o de la Madre de Dios','Etnográfica, Patronal, Taurina y Gastronómica. Se celebra en Junio (Fines de junio). Declaradas Fiesta de Interés Turístico Nacional. Un hito masivo e identitario único estructurado en las históricas doce Cuadrillas; destaca el festejo de los toros en el monte Valonsadero, el desfile de las "Sacas", la tajada de carne y el Lunes de Bailas a orillas del Duero.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42174','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos tradicionales en el bellísimo entorno de la comarca de El Valle, con procesión mariana, campeonatos de pelota mano en el frontón, caldereta de carne local y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42175','fiesta','Fiestas de San Caprasio','Patronal y Romería. Se celebra en Agosto. Destaca la romería tradicional a las ruinas de la ermita de San Caprasio en plenas Tierras Altas, acompañada por dulzaineros locales, comidas populares de hermandad y disco-móvil). ¿Puedo continuar con el siguiente bloque de la provincia de Soria para terminar los municipios restantes de la T a la Z?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42176','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Festejos estivales en el Campo de Gómara adaptados al retorno familiar con santa misa solemne, campeonatos de tusa y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42177','fiesta','Fiesta de San Roque y las Danzas de la Alfarería','Etnográfica y Patronal. Se celebra en Agosto. Festejos tradicionales vinculados a su histórico gremio de alfareros, con exhibiciones de barro cocido, pasacalles al son de la dulzaina y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42178','fiesta','Fiestas de San Miguel Arcángel y de la Virgen de la Blanca','Patronal. Se celebra en Agosto. Celebración de pinares orientada al reencuentro de familias emigradas, caracterizada por campeonatos tradicionales de calva, bolos femeninos y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42181','fiesta','Fiestas de la Virgen del Rosario y San Esteban','Patronal y Etnográfica. Se celebra en Agosto. Notable animación en la comarca de Almazán gracias a su pasado resinero, ofreciendo jotas castellanas al son del tamboril, grandes verbenas en la plaza mayor y caldereta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42182','fiesta','Fiestas de San Esteban Protomártir','Patronal. Se celebra en Agosto (Adelantadas). Festejos vecinales mínimos condicionados por la baja demografía agraria, limitados a oficios religiosos tradicionales, campeonato de naipes y merienda de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42183','fiesta','Fiestas de la Virgen de los Remedios','Patronal. Se celebra en Septiembre y Agosto. Agrupa las celebraciones tradicionales de sus múltiples pedanías del Campo de Gómara en una jornada estival con juegos tradicionales infantiles y cena popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42184','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Sencillos festejos veraniegos en las cercanías de las Vicarías, con santa misa cantada, torneos tradicionales de cartas populares y música discomóvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42185','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Pequeña festividad vecinal reducida debido a la despoblación de las Tierras del Burgo, centrada en un almuerzo comunitario para residentes y veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42188','fiesta','Fiestas de la Virgen de los Manantiales y de San Roque','Patronal y Romería. Se celebra en Agosto. Festejos al pie de la Sierra del Moncayo con procesión tradicional a la ermita, subasta de banzos al son de la dulzaina, caldereta serrana y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42189','fiesta','Fiestas de la Virgen de la Salud','Patronal, Romería y Paisajística. Se celebra en Agosto. Notable relevancia turística por ser la puerta de entrada al Parque Natural del Cañón del Río Lobos; destaca su solemne romería tradicional, caldereta popular y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42190','fiesta','Fiestas de la Virgen de la Natividad y la Pingada del Mayo','Etnográfica y Patronal. Se celebra en Septiembre y Mayo. Festejos tradicionales de la comarca de pinares que conservan el rito ancestral de levantar el pino mayo por los jóvenes del pueblo, con música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42191','fiesta','Fiestas de la Virgen de las Espigas y San Lucas','Patronal y Etnográfica. Se celebra en Agosto y Octubre. Gran animación en la comarca de El Valle; célebre por su puesta en valor de las tradiciones serranas, pasacalles de dulzaineros, grandes orquestas y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42192','fiesta','Fiestas de San Lorenzo','Patronal. Se celebra en Agosto. Pequeña festividad vecinal vinculada a la memoria literaria de Avelino de Miguel, reducida por la baja demografía a actos religiosos, naipes y refresco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42193','fiesta','Fiestas de la Virgen de la Clamores','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local debido a la despoblación en el límite con Aragón, limitados a oficios litúrgicos tradicionales y una merienda popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42194','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Sencillos festejos veraniegos en las Tierras del Burgo orientados al turismo familiar, con santa misa, campeonatos de mus y chinchón, y parrillada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42195','fiesta','Fiestas de la Virgen del Rosario','Patronal. Se celebra en Agosto (Adelantadas). Festejos de retorno familiar estival adaptados a la baja demografía del sur provincial, centrados en los oficios religiosos de acción de gracias y un refresco vecinal.','inventario_fiestas_pdf');
