INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42198','fiesta','Fiestas de la Virgen del Collado','Patronal e Histórica. Se celebra en Agosto. Festejos serranos que aprovechan la estampa medieval de su monumental iglesia románica fortificada, albergando jotas tradicionales sorianas y cenas de hermandad.','inventario_fiestas_pdf');
