INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42209','fiesta','Fiestas de la Virgen de la Villavieja y Jornadas Paleontológicas','Patronal y Paleontológica. Se celebra en Agosto. Gran animación en las Tierras Altas, dinamizada por su Centro de Interpretación de las Icnitas de dinosaurio, combinando las procesiones con actividades de divulgación.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42211','fiesta','Fiestas de la Virgen de la Natividad','Patronal. Se celebra en Septiembre y Agosto. Festejos veraniegos en la comarca de Almarza con santa misa solemne, campeonatos de bolos castellanos, calva, cena popular vecinal y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42212','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Celebración en el sur provincial con procesión tradicional en su templo románico con galería porticada, campeonatos de cartas populares y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42213','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos vecinales mínimos adaptados a la baja demografía del Campo de Gómara, reducidos a una santa misa comunitaria, naipes y un aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42215','fiesta','Fiestas de la Virgen del Pino y San Roque (Fiesta de la Pinochada)','Etnográfica, Patronal y Taurina. Se celebra en Agosto. Fiesta de Interés Turístico Regional de gran impacto; destaca por "La Pinochada", un ritual etnográfico único donde las mujeres casadas y solteras se enfrentan portando ramas de pino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42216','fiesta','Fiestas de San Martín','Patronal. Se celebra en Noviembre y Agosto (Verano). Festejos veraniegos mínimos adaptados a la baja demografía de las Tierras Altas, centrados en el reencuentro de familias nativas con merienda popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42217','fiesta','Fiestas de San Sebastián','Patronal y Paisajística. Se celebra en Enero y Agosto (Verano). Festejos estivales muy animados junto al espectacular nacimiento del río Queiles bajo su castillo, con caldereta popular y bailes con dulzaineros.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42218','fiesta','Fiestas de el Santo Cristo de la Villa','Patronal e Histórica. Se celebra en Agosto. Notable afluencia en este conjunto histórico fortificado de las Tierras Altas, que combina las procesiones tradicionales con mercados de artesanía, caldereta popular y orquestas). Con este bloque completamos oficialmente todos los municipios de la provincia de Soria. ¿Podemos continuar con la siguiente provincia de Castilla y León (Provincia de Valladolid)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90808','fiesta','Fiestas de San Juan Ante Portam Latinam y la Virgen del Rosario','Patronal. Se celebra en Mayo y Octubre. Festejos típicamente locales en los Torozos occidentales, basados en la misa solemne, campeonatos de cartas en el teleclub y bailes populares para la población flotante estival.','inventario_fiestas_pdf');
