INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47036','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos en el límite con la provincia de Zamora con pasacalles de dulzaineros locales, campeonato de calva, parrillada popular comunitaria y bailes de sociedad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47037','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal y Taurina. Se celebra en Agosto. Festejos de gran animación estival en el valle del Trabancos, célebres por sus encierros de vaquillas por las calles, charangas, cenas de peñas y orquestas potentes.','inventario_fiestas_pdf');
