INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47040','fiesta','Fiestas de los Santos Justo y Pastor','Patronal. Se celebra en Agosto. Pequeña festividad vecinal reducida debido a la despoblación de Tierra de Campos, centrada en una santa misa tradicional y refresco comunitario en el teleclub.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47041','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio y Agosto (Verano). Festejos veraniegos para emigrantes centrados en los oficios religiosos en los Montes Torozos, campeonato de mus y cena vecinal de hermandad.','inventario_fiestas_pdf');
