INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47050','fiesta','Fiestas de Santa Marina y Fiesta de la Vendimia de Cigales','Patronal, Enológica y Taurina. Se celebra en Julio y Septiembre. Hito vitivinícola de la provincia; destaca su histórica Fiesta de la Vendimia con pisado tradicional de la uva y degustaciones de clarete, combinada en verano con encierros taurinos urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47051','fiesta','Fiestas de San Ginés','Patronal. Se celebra en Agosto. Festejos en los Montes Torozos orientados al veraneante familiar, con procesión rústica, campeonato de calva, parrillada popular y música en la plaza.','inventario_fiestas_pdf');
