INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47056','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeña festividad vecinal en el valle del Cuco reducida debido a la despoblación, centrada en oficios religiosos tradicionales, campeonato de naipes y aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47057','fiesta','Fiestas de San Antonio de Padua','Patronal y Enológica. Se celebra en Junio y Agosto. Festejos en la D.O. Cigales orientados al turismo estival con procesión mariana, tradicionales meriendas en sus bodegas subterráneas excavadas y disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47058','fiesta','Fiestas de San Bernardino de Siena y de los Acontecimientos Históricos','Patronal e Histórica. Se celebra en Mayo y Agosto. Festejos en Tierra de Campos que ponen en valor su arquitectura de barro y tapial, albergando procesiones solemnes, campeonatos de calva y música folclórica.','inventario_fiestas_pdf');
