INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47101','fiesta','Fiestas de la Virgen de la Concepción (Celebración de "Los Pegotes")','Patronal, Etnográfica y Taurina. Se celebra en Septiembre y Noviembre/ Diciembre. Hito etnográfico regional por la bajada y subida nocturna de la Virgen de los Pegotes, transportada en coche de caballos e iluminada con hogueras y antorchas por miles de fieles.','inventario_fiestas_pdf');
