INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47104','fiesta','Fiestas de San Miguel y San Jerónimo (Encierros Tradicionales de Olmedo)','Patronal, Taurina e Histórica. Se celebra en Septiembre. Es Fiesta de Interés Turístico Regional; sus encierros tradicionales a caballo por el campo y las calles de la villa mudéjar atraen a miles de aficionados y peñas musicales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47105','fiesta','Fiestas de la Virgen del de la Blanca','Patronal. Se celebra en Agosto. Festejos del valle del Esgueva orientados al retorno vacacional, con procesión tradicional con subasta de banzos, campeonatos de cartas en el teleclub y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47106','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeños festejos familiares en el valle del Botijas centrados en oficios religiosos, meriendas comunitarias de hermandad y música grabada en el centro social.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47109','fiesta','Fiestas de San Maurice','Patronal y Taurina. Se celebra en Septiembre y Agosto (Verano). Festejos de gran arraigo en Tierra de Campos, célebres por sus tradicionales encierros de vaquillas por el casco urbano, campeonato de pelota mano y grandes bailes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47111','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal y Taurina. Se celebra en Agosto. Gran animación comarcal famosa por sus peligrosos encierros tradicionales urbanos por el entramado histórico, concursos de recortes y verbenas de primer nivel.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47112','fiesta','Fiestas de San Agustín y Piñón de España','Patronal, Gastronómica y Taurina. Se celebra en Agosto. Relevancia comarcal por sus tradicionales encierros y la feria gastronómica del piñón; desfile masivo de peñas locales y macroverbenas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47113','fiesta','Fiestas del Santo Cristo de la Guía','Patronal. Se celebra en Agosto. Festejos veraniegos para emigrantes retornados, con santa misa cantada, campeonatos de cartas populares en las antiguas escuelas y una gran caldereta vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47114','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque (Fiestas de San Roque en Peñafiel)','Patronal, Taurina y Enológica. Se celebra en Agosto. Fiesta de Interés Turístico Regional; célebre por el "chúndara" y sus encierros y capeas en la histórica Plaza del Coso de trazado medieval, donde los toros comparten espacio con la multitud.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47115','fiesta','Fiestas de la Virgen de la Expectación','Patronal. Se celebra en Agosto (Adelantadas). Festejos en el borde de los Montes Torozos orientados al veraneante familiar, con procesión mariana, campeonato de calva, cena popular y baile con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47116','fiesta','Fiestas de San Juan Bautista','Patronal, Enológica y Taurina. Se celebra en Junio. Gran animación en la cuna de la Ribera del Duero; destaca por sus encierros urbanos de reses bravas, la masiva apertura de bodegas tradicionales subterráneas y catas populares.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47117','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Celebración en el valle del Esgueva orientada al turismo de retorno familiar, con procesión, competiciones infantiles en la plaza y una gran cena vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47118','fiesta','Fiestas del Santo Cristo de la Buena Dicha','Patronal. Se celebra en Agosto. Festejos de retorno familiar en el valle del Cuco con santa misa solemne, campeonatos de cartas populares en el teleclub y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47119','fiesta','Fiestas de San Juan Ante Portam Latinam','Patronal. Se celebra en Mayo y Agosto (Verano). Pequeña festividad vecinal adaptada a la demografía estival, centrada en oficios religiosos marianos, campeonato de mus y refresco para los residentes.','inventario_fiestas_pdf');
