INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47122','fiesta','Fiestas de Santa María la Mayor y San Quintín','Patronal, Taurina y Gastronómica. Se celebra en Septiembre. Relevancia comarcal bajo la silueta de su castillo fortificado; destaca por sus encierros urbanos de toros, desfile humorístico de peñas y promoción de sus famosos mantecados de Portillo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47123','fiesta','Fiestas de San Juan Bautista','Patronal y Taurina. Se celebra en Junio y Agosto. Festejos en la comarca medinense célebres por su suelta de vaquillas en plaza portátil, pasacalles al son de la dulzaina, caldereta popular y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47124','fiesta','Fiestas de los Santos Justo y Pastor','Patronal, Taurina y Enológica. Se celebra en Agosto. Gran animación en la D.O. Rueda, famosa por sus encierros urbanos tradicionales de reses bravas por las calles, concurso de peñas locales y verbenas al pie de su patrimonio mudéjar.','inventario_fiestas_pdf');
