INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47127','fiesta','Fiestas de Nuestra Señora del Rosario','Patronal y Enológica. Se celebra en Agosto (Adelantadas). Festejos en plena Ribera del Duero con meriendas populares en bodegas subterráneas, campeonato de pelota mano, desfile de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47129','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal, Taurina y Enológica. Se celebra en Agosto. Gran animación comarcal con tradicionales encierros y capeas urbanas de vaquillas, peñas musicales, verbenas multitudinarias y apertura de bodegas tradicionales.','inventario_fiestas_pdf');
