INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47143','fiesta','Fiestas de San Pedro Apóstol','Patronal. Se celebra en Junio y Agosto. Pequeñas fiestas veraniegas en el valle del Cuco, con oficios religiosos tradicionales, parrillada popular en las antiguas escuelas y música disco.','inventario_fiestas_pdf');
