INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47145','fiesta','Fiestas de la Virgen de Fombuena','Patronal y Etnográfica. Se celebra en Agosto. Notable animación en la Tierra de Pinares, caracterizada por sus tradicionales danzas de jotas al son de la dulzaina, caldereta popular y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47147','fiesta','Fiestas de San Pablo Apóstol','Patronal. Se celebra en Enero y Agosto (Verano). Pequeña festividad vecinal adaptada a la demografía estival, centrada en los actos religiosos tradicionales, campeonato de mus y refresco para los residentes.','inventario_fiestas_pdf');
