INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47149','fiesta','Fiestas de San Pelayo y Festival Nacional de Cultura Libre','Cultural y Patronal. Se celebra en Junio y Agosto. Hito cultural de resistencia rural en los Montes Torozos; su singular festival enfocado en la música independiente y artes en el campo atrae a numeroso público joven.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47150','fiesta','Fiestas de la Virgen de la Vega','Patronal, Taurina y Enológica. Se celebra en Septiembre. Festejos de la D.O. Toro con tradicionales encierros urbanos de toros por las calles, concurso de recortes, degustaciones de vino en lagares antiguos y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47151','fiesta','Fiestas de San Salvador','Patronal. Se celebra en Agosto. Sencillos festejos veraniegos en el valle del Hornija centrados en los actos litúrgicos tradicionales, campeonatos de cartas en el teleclub y merienda popular vecinal.','inventario_fiestas_pdf');
