INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47154','fiesta','Fiestas de San Juan Evangelista','Patronal y Gastronómica. Se celebra en Agosto (Adelantadas). Festejos en el valle del Valcorba célebres por sus parrilladas tradicionales de pinchos de lechazo al sarmiento, comidas de hermandad de peñas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47155','fiesta','Fiestas de San Juan Bautista y la Virgen de la Asunción','Patronal y Cultural. Se celebra en Junio y Agosto. Municipio del cinturón metropolitano de gran explosión demográfica; atrae masivamente a la juventud con sus potentes macroverbenas, desfiles de peñas y paellada masiva.','inventario_fiestas_pdf');
