INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47158','fiesta','Fiestas de la Virgen de la Asunción y Fiesta del Verdejo','Patronal, Enológica y Taurina. Se celebra en Agosto y Abril. Hito vitivinícola y considerada la "Cuna del Verdejo"; destaca por su feria del vino que atrae a miles de visitantes, complementada en agosto con encierros tradicionales urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47159','fiesta','Fiestas de la Virgen de la Moya y del Novillo','Patronal, Enológica y Taurina. Se celebra en Agosto y Septiembre. Relevancia comarcal por sus arraigados encierros urbanos nocturnos, la Fiesta de la Vendimia con degustaciones de queso local y vino, y animadas concentraciones de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47160','fiesta','Fiestas de San Pelayo','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Festejos veraniegos en el valle del Trabancos célebres por su suelta de vaquillas en plaza portátil, pasacalles al son de la dulzaina, caldereta popular y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47161','fiesta','Fiestas de Nuestra Señora de la Guía y Recreación de las Siete Doncellas','Histórica, Recreación, Patronal y Cultural. Se celebra en Septiembre y Agosto. Gran hito histórico-cultural junto al Archivo General de Simancas; destaca su espectacular recreación del "Tributo de las Siete Doncellas", con desfiles de época medieval y macroverbenas metropolitanas). ¿Puedo continuar con el último bloque de la provincia de Valladolid para cerrar los municipios restantes de la T a la Z?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47165','fiesta','Fiestas de la Virgen de la Peña y de la Guía','Patronal, Taurina e Histórica. Se celebra en Septiembre. Declaradas de Interés Turístico Regional, destacan por los espectaculares y multitudinarios encierros mixtos por el campo y las calles rústicas, el desfile de faroles de las peñas y su Mercado Medieval.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47169','fiesta','Fiestas de San Martín','Patronal. Se celebra en Agosto (Adelantadas). Pequeños festejos veraniegos en la cuenca del Esgueva adaptados al retorno familiar, centrados en los actos religiosos tradicionales, campeonato de cartas y meriendas vecinales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47170','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local en la comarca del Botijas, con santa misa cantada, campeonato de chinchón, juegos infantiles y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47166','fiesta','Fiestas de la Virgen del Carmen','Patronal y Taurina. Se celebra en Agosto (Adelantadas). Festejos estivales muy animados a orillas del Duero con capeas populares de vaquillas, desfile de disfraces organizados por las peñas y orquestas nocturnas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47167','fiesta','Fiestas de San Marcos y Santa Ana','Patronal y Taurina. Se celebra en Agosto. Festejos en Tierra de Campos célebres por sus encierros urbanos tradicionales de reses bravas, suelta de vaquillas, caldereta popular y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47168','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Festejos vecinales mínimos en los Montes Torozos condicionados por la baja demografía, con oficios religiosos tradicionales, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47171','fiesta','Fiestas de la Virgen de la Asunción y Recreación de los Comuneros','Histórica, Recreación, Patronal y Taurina. Se celebra en Agosto y Abril. Hito histórico comarcal bajo su colosal e intacto castillo; destaca por su recreación histórica del levantamiento comunero de 1521, combinada en verano con encierros tradicionales urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47172','fiesta','Fiestas de los Santos Justo y Pastor','Patronal. Se celebra en Agosto. Celebración tradicional de retorno estival con santa misa cantada, campeonatos de bolos castellanos femeninos, parrillada popular comunitaria y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47173','fiesta','Fiestas de San Martín y de la Virgen de la Atalaya','Patronal, Gastronómica y Taurina. Se celebra en Noviembre y Agosto. Gran relevancia provincial y gastronómica; célebre por sus parrilladas masivas de pinchos de lechazo al sarmiento, encierros taurinos urbanos de reses bravas y peñas multitudinarias.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47174','fiesta','Fiestas de la Virgen del Castillo','Patronal, Cultural e Histórica. Se celebra en Septiembre y Agosto. Notable afluencia comarcal dinamizada por el marco medieval de su "Castillo Encantado", albergando conciertos folk, pasacalles de dulzaina, caldereta popular y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47177','fiesta','Fiestas de el Salvador y Festival de Teatro de las Dos Orillas (Fexturo)','Cultural y Patronal. Se celebra en Agosto. Hito y referente de las artes escénicas en Tierra de Campos; su prestigioso festival de teatro alternativo y de títeres rural dinamiza de forma masiva la comarca agraria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47178','fiesta','Fiestas de la Virgen de la Anunciada','Romería, Cultural e Histórica. Se celebra en Marzo/Abril y Septiembre. Hito nacional por su condición de primera "Villa del Libro" de España; su romería tradicional se celebra en la espectacular e histórica ermita románica lombarda extramuros, atrayendo a numerosos intelectuales y turistas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47179','fiesta','Fiestas de la Virgen del Rosario','Patronal, Enológica y Romería. Se celebra en Octubre y Agosto (Verano). Festejos en plena "milla de oro" de la Ribera del Duero, dinamizados por el entorno monumental del Monasterio de Santa María de Valbuena, combinando catas de vino, jotas y comidas de peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47180','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Pequeña festividad familiar en el valle del Cuco con santa misa tradicional, meriendas de hermandad en los lagares subterráneos excavados y música en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47181','fiesta','Fiestas de San Vicente Mártir','Patronal. Se celebra en Enero y Agosto (Verano). Festejos de verano para los retornados en Tierra de Campos, con pasacalles de dulzaina, tradicionales campeonatos de cartas populares y cena popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47182','fiesta','Fiestas de la Virgen del Milagro y del Milagro de Carlos V','Patronal, Recreación Histórica y Taurina. Se celebra en Mayo y Octubre. Notable concurrencia en la comarca del Adaja; destaca por su recreación histórica del paso del emperador Carlos V, complementada con encierros taurinos tradicionales urbanos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47186','fiesta','Feria y Fiestas de Nuestra Señora de San Lorenzo y Semana Santa de Valladolid','Patronal, Cultural, Taurina y Religiosa. Se celebra en Septiembre y Marzo/Abril. Su Semana Santa es de Interés Turístico Internacional, considerada un museo nacional de escultura policromada en las calles. Las ferias de septiembre congregan a cientos de miles de personas con macroconciertos gratuitos en la Plaza Mayor, ferias taurinas y la masiva Feria de Casetas Gastronómicas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47184','fiesta','Fiestas de San Pedro y de la Nochevieja de Verano','Patronal, Recreativa y Enológica. Se celebra en Julio y Primer fin de semana de Agosto. Hito comarcal famoso en España por su original "Nochevieja de Verano", donde miles de personas toman las uvas disfrazadas en pleno agosto, regado con vinos de la D.O. Cigales.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47185','fiesta','Fiestas del Santo Cristo de las Eras','Patronal. Se celebra en Agosto. Festejos tradicionales de Tierra de Campos al pie de los Torozos, con oficios religiosos, campeonato de mus, juegos infantiles y baile con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47187','fiesta','Fiestas de San Salvador','Patronal. Se celebra en Agosto. Festejos veraniegos en el extremo septentrional del río Valderaduey, centrados en el reencuentro de familias nativas con competiciones de bolos castellanos y parrillada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47188','fiesta','Fiestas de la Virgen de Cantores','Patronal. Se celebra en Agosto. Sencillos festejos veraniegos junto a la autovía A-6, caracterizados por santa misa solemne, tradicionales campeonatos de cartas populares y cena popular comunitaria.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47189','fiesta','Fiestas de San Juan Bautista *','Patronal *. Se celebra en Junio y Agosto *. Pequeña festividad vecinal en la Tierra de Medina orientada al turismo familiar, con procesión, campeonato de cartas en el teleclub y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47190','fiesta','Fiestas de el Salvador','Patronal. Se celebra en Agosto. Festejos vecinales mínimos adaptados a la baja demografía de los Torozos occidentales, reducidos a una santa misa comunitaria, naipes y aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47191','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Celebración de carácter tradicional rural con procesión de la patrona por su casco de piedra, campeonato de calva y música disco-móvil nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47192','fiesta','Fiestas de San Bernardo','Patronal y Enológica. Se celebra en Agosto. Festejos en la D.O. Rueda orientados a los veraneantes, caracterizados por meriendas populares tradicionales en los lagares subterráneos y orquesta en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47193','fiesta','Fiestas de San Roque','Patronal, Taurina y Recreativa. Se celebra en Agosto. Gran animación en la comarca del Cega por su fuerte crecimiento residencial; destaca por sus multitudinarios encierros urbanos de toros, desfiles de peñas y populosas verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47195','fiesta','Fiestas de la Virgen de la Asunción','Patronal. Se celebra en Agosto. Festejos en el valle del Duero dinamizados por las peñas de jóvenes, con meriendas populares, campeonatos de fútbol sala y verbenas nocturnas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47213','fiesta','Fiestas de San Miguel Arcángel','Patronal y Taurina. Se celebra en Septiembre y Agosto (Verano). Festejos de retorno estival con suelta de vaquillas en calles valladas, pasacalles al son de la dulzaina, caldereta popular y baile público.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47197','fiesta','Fiestas de la Santa Cruz (La Celebración del "Voto de Villa")','Patronal y Taurina. Se celebra en Mayo. Notable relevancia en Tierra de Campos, famosa por sus encierros urbanos tradicionales de reses bravas por las calles, concurso de recortes y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47198','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos veraniegos mínimos adaptados a la baja demografía de Tierra de Campos, centrados en los oficios religiosos, campeonato de mus y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47199','fiesta','Fiestas de San Francisco de Asís','Patronal. Se celebra en Septiembre y Agosto. Sencillos festejos estivales a orillas del río Sequillo orientados al reencuentro de familias nativas, con santa misa, campeonatos de cartas y merienda vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47200','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en el valle del Esgueva adaptada al turismo familiar de retorno, con santa misa cantada, campeonato de calva y cena de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47203','fiesta','Fiestas de la Virgen de Grijasalbas','Patronal y Romería. Se celebra en Mayo y Agosto. Romería tradicional en Tierra de Campos con procesión, subasta de banzos al son de la dulzaina, jotas castellanas y comidas colectivas de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47204','fiesta','Fiestas de la Virgen de la Copacabana','Patronal y Taurina. Se celebra en Agosto. Festejos muy animados en el límite con Zamora, célebres por sus encierros de vaquillas por las calles, charangas, comidas de peñas y orquestas en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47205','fiesta','Fiestas de San Isidro y de Cabo de Año (Los Encierros de Villafrechós)','Patronal, Taurina y Gastronómica. Se celebra en Mayo y Septiembre. Gran tradición taurina en Tierra de Campos con encierros urbanos de toros por las calles de tapial, degustación de almendras garrapiñadas locales y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47206','fiesta','Fiestas de la Virgen de la Santísima Trinidad','Patronal e Histórica. Se celebra en Agosto. Festejos bajo el imponente e intacto castillo medieval de Villafuerte, combinando los actos religiosos con visitas culturales, comidas populares y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47207','fiesta','Fiestas de la Virgen del Rosario','Patronal e Histórica. Se celebra en Septiembre y Agosto. Notable afluencia en Tierra de Campos que pone en valor las ruinas de su castillo histórico y colegiata, albergando conciertos folk, caldereta popular y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47208','fiesta','Fiestas de San Nicolás de Bari','Patronal. Se celebra en Agosto (Adelantadas). Pequeña festividad vecinal reducida debido a la despoblación de Tierra de Campos, centrada en una santa misa de acción de gracias y refresco comunitario.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47209','fiesta','Fiestas de Santiago Apóstol','Patronal. Se celebra en Julio y Agosto. Festejos de escala estrictamente local adaptados a la demografía veraniega, con santa misa, campeonato de naipes en el teleclub y merienda popular vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47214','fiesta','Fiestas de la Virgen de las Fuentes y Feria del Queso de Villalón','Patronal, Gastronómica y Taurina. Se celebra en Septiembre y Junio. Hito y capital tradicional de Tierra de Campos; destaca por su veterana e importante Feria del Queso "Pata de Mulo", encierros taurinos urbanos por su recinto porticado y peñas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47217','fiesta','Fiestas de la Virgen del Milagro (La Celebración de los Quintos)','Patronal, Taurina y Cultural. Se celebra en Septiembre y Mayo. Gran animación metropolitana condicionada por el fuerte crecimiento demográfico; destaca por sus concurridos encierros de reses bravas por las calles y grandes orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47223','fiesta','Fiestas de San Andrés Apóstol','Patronal. Se celebra en Agosto (Adelantadas). Festejos en los llanos de los Montes Torozos orientados al veraneante familiar, con procesión rústica, campeonato de calva, cena popular vecinal y baile con orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47225','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos veraniegos en el valle del Hornija centrados en la misa cantada, campeonato de calva, meriendas populares en lagares antiguos y música disco nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47226','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos de retorno estival en el valle del Jaramiel con procesión tradicional rústica, campeonato de mus, comidas populares vecinales de hermandad y orquesta.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47227','fiesta','Fiestas de San Miguel Arcángel','Patronal. Se celebra en Septiembre y Agosto. Festejos vecinales mínimos adaptados a la baja demografía en el límite provincial, reducidos a una santa misa comunitaria, naipes en el teleclub y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47229','fiesta','Fiestas del Santo Cristo de la Merced','Patronal y Taurina. Se celebra en Septiembre. Gran animación en Tierra de Campos, famosa por su suelta de vaquillas en calles valladas mudéjares, concurso de recortes, caldereta popular y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47194','fiesta','Fiestas de Nuestra Señora de las Nieves','Patronal. Se celebra en Agosto. Pequeñas fiestas veraniegas en Tierra de Pinares en el límite con Segovia, con oficios religiosos tradicionales, campeonato de mus y merienda popular en las escuelas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47230','fiesta','Fiestas de Santa María la Real y Santiago Apóstol','Patronal e Histórica. Se celebra en Agosto y Julio. Notable relevancia histórica de los Torozos; dinamizada por las visitas a su monumental iglesia mozárabe y osario del siglo X, combinando actos tradicionales con cenas de peñas y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47231','fiesta','Fiestas del de la Octava del del Corpus y Fiesta del de la Salchicha de Zaratán','Patronal, Gastronómica y Cultural. Se celebra en Junio y Noviembre. Hito en el cinturón metropolitano por su gran expansión demográfica; atrae masivamente a la juventud con sus potentes macroverbenas, desfiles de peñas y su famosa feria del embutido local). [1] Con este bloque completamos oficialmente todos los municipios de la provincia de Valladolid. ¿Podemos continuar con la última provincia de Castilla y León (Provincia de Zamora)?.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48001','fiesta','Fiestas de la Virgen de la Asunción y San Roque','Patronal, Taurina y Fronteriza. Se celebra en Agosto. Hito y capital comarcal de Aliste; destaca por sus tradicionales e intensos encierros de vaquillas por el recinto amurallado, desfile de peñas y un fuerte folklore de gaitas y panderos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90499','fiesta','Fiestas de la Virgen del Rosario','Patronal y Enológica. Se celebra en Octubre y Agosto (Verano). Festejos estivales en el valle del Eria enfocados en el reencuentro familiar, con meriendas tradicionales de peñas en los lagares subterráneos y bailes con disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90500','fiesta','Fiestas de la Virgen de la Consolación y San Roque','Patronal. Se celebra en Agosto. Sencillos festejos veraniegos condicionados por el entorno granítico de Sayago, con santa misa solemne, campeonato de cartas en las antiguas escuelas y verbena local.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90501','fiesta','Fiestas de Santo Tomás Apóstol','Patronal y Etnográfica. Se celebra en Julio. Pequeña celebración en la comarca de la Tierra del Pan célebre por su fuerte tradición folclórica ligada al canto y la danza tradicional del "Bolero de Algodre".','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90502','fiesta','Fiestas de San Pelayo','Patronal y Etnográfica. Se celebra en Junio y Agosto. Festejos dinamizados por su ubicación junto al Duero, combinando la procesión tradicional de banzos con competiciones de calva, cenas populares comunitarias y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90503','fiesta','Fiestas de San Roque','Patronal y Taurina. Se celebra en Agosto. Notable relevancia en la comarca de Sayago; destaca por su suelta de reses bravas en plaza portátil, pasacalles al son de los dulzaineros, grandes orquestas y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90504','fiesta','Fiestas de Nuestra Señora de la Asunción y San Roque','Patronal. Se celebra en Agosto. Festejos de retorno familiar en la Tierra del Pan con santa misa cantada, torneos tradicionales de calva, campeonato de mus y orquesta en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42026','fiesta','Fiestas de la Virgen del Rosario','Patronal y Cultural. Se celebra en Octubre y Agosto. Festejos muy concurridos por su cercanía metropolitana a la capital, que combinan las procesiones tradicionales con torneos deportivos, hinchables infantiles y macroverbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90505','fiesta','Fiestas del Santo Cristo de la Vega','Patronal. Se celebra en Agosto. Celebración de carácter familiar orientada al turismo de retorno estival a orillas del río Órbigo, con procesión, campeonato de chinchón y parrillada vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90506','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Festejos vecinales mínimos adaptados a la baja demografía invernnal de Sayago, reducidos a una santa misa comunitaria, naipes en el teleclub y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90675','fiesta','Fiestas de la Virgen de la Asunción','Patronal y Taurina. Se celebra en Agosto. Festejos de la comarca de la Tierra del Vino célebres por su suelta de vaquillas en calles valladas, campeonatos de cartas, comidas populares de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49014','fiesta','Fiestas de San Antón','Patronal. Se celebra en Agosto (Adelantadas). Pequeña festividad vecinal en la Tierra del Pan adaptada para los veraneantes, centrada en un almuerzo comunitario en el frontón y música grabada.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49015','fiesta','Fiestas del Santo Cristo de la Vera Cruz','Patronal y Arqueológica. Se celebra en Agosto. Festejos dinamizados en verano por las visitas a su famoso castro celtíbero de "Las Labradas", combinando los actos religiosos con rutas culturales y verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49017','fiesta','Fiestas de Nuestra Señora de la Asunción y Romería de la Virgen de los Remedios','Patronal y Romería. Se celebra en Agosto y Septiembre. Notable relevancia comarcal en Sanabria gracias a su multitudinaria romería al santuario de los Remedios, con subasta de banzos al son de gaitas y caldereta popular.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49018','fiesta','Fiestas de San Mamés y de la Virgen de la Vidriales','Patronal. Se celebra en Agosto. Festejos veraniegos en el valle de Vidriales para emigrantes retornados, con pasacalles de dulzaina, campeonato de mus y cenas de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49019','fiesta','Fiestas de San Marina','Patronal. Se celebra en Julio y Agosto. Sencillos festejos veraniegos en la vega del Esla orientados al turismo familiar, con santa misa, tradicionales campeonatos de calva y música disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49020','fiesta','Fiestas de el Santo Cristo de la Piedad','Patronal y Taurina. Se celebra en Septiembre y Agosto. Festejos tradicionales en el límite con Valladolid que cuentan con suelta de vaquillas en calles valladas, concurso de peñas locales y verbenas en la plaza mayor.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49021','fiesta','Fiestas de la Veguilla y Fiestas del Toro Enmaromado','Patronal, Taurina e Histórica. Se celebra en Mayo y Junio. El Toro Enmaromado está declarado de Interés Turístico Nacional de masivo impacto; consiste en una carrera tradicional histórica donde los mozos corren guiando a un toro asido por una larga maroma por las calles de la villa.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49022','fiesta','Fiestas de San Tomás','Patronal. Se celebra en Agosto (Adelantadas). Pequeña celebración rural en la Tierra del Pan centrada en los oficios religiosos de la Asunción, campeonato de mus en las antiguas escuelas y un refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49023','fiesta','Fiestas de la Virgen de Gracia','Patronal, Romería y Taurina. Se celebra en Agosto. Hito y centro neurálgico comarcal de Sayago; destaca por su multitudinaria romería, capeas de vaquillas en su plaza fija, animadas charangas de peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49024','fiesta','Fiestas de la Virgen de las Nieves','Patronal y Taurina. Se celebra en Agosto. Gran animación en la comarca de Toro, famosa por sus tradicionales encierros y capeas de reses bravas por las calles, concentraciones de peñas y orquestas potentes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49025','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos tradicionales de la campiña del Esla con santa misa cantada, campeonato de calva, merienda de hermandad vecinal a la orilla del río y música disco.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49026','fiesta','Fiestas de San Bartolomé','Patronal. Se celebra en Agosto. Pequeña festividad vecinal en el valle del Esla reducida debido a la despoblación, centrada en oficios religiosos tradicionales, campeonato de naipes y aperitivo vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49027','fiesta','Fiestas de Santa Marina','Patronal. Se celebra en Julio y Agosto. Festejos estivales de escala estrictamente local en el valle de Vidriales, con santa misa, chinchón y merienda popular en las escuelas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49028','fiesta','Fiestas de San Esteban *','Patronal *. Se celebra en Agosto (Adelantadas) *. Festejos vecinales mínimos condicionados por la baja demografía, que incluyen santa misa cantada, campeonato de cartas y merienda de hermandad.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49031','fiesta','Fiestas de San Isidro Labrador y San Roque','Patronal. Se celebra en Mayo y Agosto. Festejos típicamente locales en el bajo Sayago centrados en los actos religiosos, meriendas en los cortinos y bailes con disco-móvil para los veraneantes.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49032','fiesta','Fiestas de la Virgen de la Divina Pastora','Patronal. Se celebra en Septiembre y Agosto (Verano). Festejos de retorno estival en el valle del Tera, caracterizados por competiciones en la playa fluvial, parrillada popular y música orquestal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49033','fiesta','Fiestas de la Virgen de la Asunción y la Trinidad','Patronal, Taurina y Arqueológica. Se celebra en Agosto y Junio. Hito comarcal dinamizado por su villa romana de "El Beneficio", célebre por sus capeas de vaquillas en calles valladas, masivo desfile de peñas y grandes verbenas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49034','fiesta','Fiestas de la Santa Cruz y San Roque','Patronal y Taurina. Se celebra en Mayo y Agosto. Festejos en la comarca de La Guareña famosos por sus tradicionales encierros de vaquillas por el casco urbano, concursos de recortes y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49035','fiesta','Fiestas de la Virgen de la Consolación','Patronal. Se celebra en Agosto. Celebración en la Tierra de Campos zamorana con santa misa de acción de gracias, campeonatos de cartas populares en el teleclub y orquesta nocturna.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49036','fiesta','Fiestas de la Virgen de Árboles','Patronal, Etnográfica y Taurina. Se celebra en Septiembre. Notable relevancia por su espectacular encierro campero a caballo y la exhibición de sus ancestrales trajes e indumentarias bordadas del folclore carbajalino.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49037','fiesta','Fiestas de San Miguel Arcángel','Patronal y Recreativa. Se celebra en Agosto (Adelantadas). Festejos de verano junto al embalse de Almendra, con competiciones náuticas populares, caldereta comunitaria y música nocturna en la plaza.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49038','fiesta','Fiestas de San Juan Bautista','Patronal. Se celebra en Junio y Agosto. Pequeña festividad vecinal en la Tierra del Vino, centrada en oficios religiosos tradicionales, campeonato de mus y refresco comunitario en las antiguas escuelas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49039','fiesta','Fiestas de San Juan Bautista y la Virgen del Viso','Patronal. Se celebra en Junio y Septiembre. Festejos tradicionales de la comarca vitivinícola con santa misa solemne, campeonatos de bolos castellanos, meriendas vecinales y disco-móvil.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49040','fiesta','Fiestas de San Roque','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local orientados al turismo de retorno familiar, con procesión rústica, campeonatos de naipes y refresco vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49041','fiesta','Fiestas de San Roque','Patronal y Taurina. Se celebra en Agosto. Festejos junto al río Esla que cuentan con suelta de vaquillas en plaza portátil, pasacalles al son de la dulzaina, comidas comunitarias de peñas y orquestas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49042','fiesta','Fiestas de la Virgen de la Tabla y San Roque','Patronal. Se celebra en Agosto. Festejos veraniegos en la Tierra del Pan con pasacalles de dulzaineros locales, campeonato de calva, parrillada popular comunitaria y bailes públicos.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49043','fiesta','Fiestas de la Virgen del Río y la Purísima','Patronal e Histórica. Se celebra en Agosto y Diciembre. Festejos en Tierra de Campos que ponen en valor su fisonomía de villa medieval rústica, albergando procesiones solemnes, campeonatos de calva y música folclórica.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49044','fiesta','Fiestas de San Martín','Patronal. Se celebra en Agosto (Adelantadas). Pequeños festejos estivales adaptados a la baja demografía invernal, centrados en una santa misa comunitaria, naipes en el teleclub y un aperitivo.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49046','fiesta','Fiestas de San Antonio de Padua','Patronal. Se celebra en Junio y Agosto. Celebración tradicional rural en Tierra de Campos con santa misa cantada, torneos tradicionales de cartas populares y cena de hermandad vecinal.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49047','fiesta','Fiestas de el Salvador','Patronal. Se celebra en Agosto. Festejos de escala estrictamente local en la Tierra del Pan con santa misa de acción de gracias, chinchón y merienda popular en las escuelas.','inventario_fiestas_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49048','fiesta','Fiestas de Nuestra Señora de la Asunción','Patronal. Se celebra en Agosto. Festejos veraniegos en Sanabria orientados al veraneante familiar, con procesión rústica, campeonato de mus y música disco nocturna en la plaza.','inventario_fiestas_pdf');
